window.XZ=window.XZ||{};(window.XZ.bank=window.XZ.bank||{})["生理学"]=[["1988-N12",2,"第3节 生理性止血","纤维蛋白与纤维蛋白原的降解",1988,12,"A","","使纤维蛋白分解成纤维蛋白降解产物的因素是",[["A","第Ⅵ因子"],["B","活化素"],["C","凝血酶"],["D","纤维蛋白单体"],["E","纤溶酶"]],"E","纤溶酶属于丝氨酸蛋白酶，它最敏感的底物是纤维蛋白和纤维蛋白原，在纤溶酶的作用下，纤维蛋白和纤维蛋白原可被分解为许多可溶性小肽，称为纤维蛋白降解产物（E对）。FⅥ是血清中活化的FVa，其功能是作为辅因子加速FⅩa对凝血酶原的激活（A错），FⅥ已不再视为一个独立的凝血因子。活化素全称为纤溶酶原活化素，又称纤溶酶原激活物，主要功能是激活无活性的纤溶酶原成为有活性的纤溶酶，发挥纤溶作用（B错）。凝血酶的主要功能是分解纤维蛋白原为纤维蛋白单体，并激活FⅩⅢ，使纤维蛋白单体相互聚合，形成不溶于水的交联纤维蛋白多聚体（C错）。纤维蛋白单体即纤维蛋白，是纤溶酶的底物（D错）。","","N"],["1988-N14",10,"第1节 内分泌与激素","多肽或蛋白质类激素",1988,14,"A","","下列激素中，哪一种是肽类激素",[["A","醛固酮"],["B","睾酮"],["C","促肾上腺皮质激素"],["D","雌二醇"],["E","皮质醇"]],"C","激素分子结构形式多样，其化学本质直接决定激素对靶细胞的作用机制。激素一般按化学性质可分为胺类、肽与蛋白质类和脂类。胺类激素的典型代表为儿茶酚胺类激素（去甲肾上腺素、肾上腺素和多巴胺等）、甲状腺激素、褪黑素等；肽类和蛋白质类激素的典型代表包括下丘脑调节肽、腺垂体激素（C对）、甲状旁腺素、胰岛素、胃肠激素等；脂类激素的典型代表为类固醇激素，如孕酮、醛固酮（A错）、皮质醇（E错）、睾酮（B错）、雌二醇（D错）和胆钙化醇。","","N"],["1988-N21",9,"第2节 神经系统的感觉分析功能","躯体痛觉的信息处理",1988,21,"A","","传导躯体痛觉的第二级神经元在",[["A","周围神经末梢"],["B","脊髓丘脑束"],["C","丘脑外侧核"],["D","脊髓后角"],["E","后根神经节"]],"D","躯体感觉包括浅感觉和深感觉两大类，浅感觉又包括触-压觉、温度觉和痛觉；深感觉即为本体感觉，主要包括位置觉和运动觉。传导痛觉、温度觉和粗略触-压觉的纤维先交叉后上行（进入脊髓后在后角换元，第二级神经元发出纤维经白质前连合交叉至对侧，在脊髓前外侧部上行，形成前外侧索传入系统），而本体感觉和精细触-压觉的纤维则先上行后交叉（进入脊髓后沿后索上行，在延髓下部的薄束核和楔束核更换神经元，换元后的第二级神经元发出纤维交叉至对侧组成内侧丘系，后者抵达丘脑的特异感觉接替核后外侧腹核，此处存在第三级神经元）。因此传导躯体痛觉温度觉和粗略触-压觉的第二级神经元在脊髓后角（D对），传导本体感觉和精细触-压觉的第二级神经元在延髓下部的薄束核和楔束核。","","N"],["1988-N26",2,"第4节 血型和输血原则","血量",1988,26,"A","","有效循环血量是指",[["A","维持正常代谢所需血量"],["B","包括存于肝、脾和淋巴窦及停滞于循环中血量"],["C","全身血容量"],["D","单位时间内通过心血管系统进行循环的血量"],["E","以上都不是"]],"D","有效循环血量是指单位时间内通过心血管系统进行循环的血量（D对），但不包括贮存于肝、脾和淋巴血窦或停滞于毛细血管中的血量（B错）。","","N"],["1988-N43",2,"第4节 血型和输血原则","ABO血型系统",1988,43,"A","","决定A、B及H抗原的基因是控制细胞合成某种特异的",[["A","抗原的肽链"],["B","蛋白质水解酶"],["C","磷脂酶"],["D","转糖基酶"],["E","蛋白质合成酶"]],"D","ABO血型系统各种抗原的特异性取决于红细胞膜上的糖蛋白或糖脂上所含的糖链的组成与连接顺序，而糖链的组成与连接顺序受某种特异的糖基转移酶（转糖基酶）（D对）控制。","","N"],["1988-N44",2,"第3节 生理性止血","纤维蛋白的生成",1988,44,"A","","血液凝固，血块收缩后析出的液体是",[["A","细胞外液"],["B","细胞内液"],["C","血清"],["D","血浆"],["E","组织液"]],"C","血液凝固，血块收缩后析出的液体是血清（C对）。血清与血浆（D）的区别是血清缺乏纤维蛋白原和FⅡ、FⅤ、FⅤⅢ、FⅩⅢ等凝血因子，但也增添了少量凝血过程中由血小板释放的物质。","","N"],["1988-N45",3,"第3节 血管生理","动脉血压的测量与正常值",1988,45,"A","","肱动脉的",[["A","脉搏波传播速度和血流速度相同"],["B","脉压随年龄的增大而减小"],["C","远心端被结扎后，其近心端的血压可升高约20％"],["D","血压在当手臂高举过头部时降低"],["E","血压在临床上代表人体动脉血压的高低"]],"E","由于在大动脉中血压降落很小，为了方便起见，临床上通常将在上臂测得的肱动脉压代表动脉血压（E对）。远心端被结扎后，其近心端的血压并不会有明显变化（C错）。测量血压时，上臂的中点应与心脏保持同一水平位，以保证测量的准确性，手臂高举过头部时，肱动脉位置上升，受静水压影响，血压将下降（D对）。本题DE均正确，但给出的参考答案仅为E。","","N"],["1988-N46",4,"第1节 肺通气","肺泡通气量",1988,46,"A","","正常人做深呼吸运动使每分通气量增加两倍时",[["A","肺泡气氧分压增加两倍"],["B","动脉血氧饱和度增加两倍"],["C","动脉血氧饱和度增加10％"],["D","肺泡通气量必定增加两倍"],["E","以上都不正确"]],"E","每分通气量指每分钟吸入或呼出的气体总量，等于潮气量与呼吸频率的乘积。正常成年人平静呼吸时，潮气量为500ml，呼吸频率为12～18次/分，以呼吸频率为16次/分计算，每分肺通气量为8L。作深呼吸运动，如果潮气量增加到2000ml，呼吸频率为8次/分时，每分肺通气量为16L，每分通气量即增加到原来的两倍。肺泡通气量为每分钟吸入肺泡的新鲜空气量，等于潮气量和无效腔气量之差与呼吸频率的乘积，正常成年人的无效腔气量约为150ml，平静呼吸时肺泡通气量为（500ml-150ml）×16=5600ml，即5.6L；深呼吸运动时肺泡通气量为（2000ml-150ml）×8=14800ml，即14.8L。作深呼吸运动使每分通气量增加两倍时，肺泡通气量增加不止两倍（D错）。肺泡通气量增加时，每分钟吸入肺泡的新鲜空气量增加，肺泡气氧分压和动脉血氧饱和度均增加，但肺泡通气量增加与肺泡气氧分压增加和动脉血氧饱和度增加无固定比例关系（ABCD错）。","","N"],["1988-N47",5,"第1节 消化生理概述","APUD细胞和胃肠激素",1988,47,"A","","胃泌素激素包括",[["A","促胰液素"],["B","抑胃肽"],["C","胆囊收缩素（缩胆囊素）"],["D","血管活性肠肽"],["E","胰高血糖素"]],"C","本题给出的参考答案是胆囊收缩素（无参考解析），可能与胆囊收缩素与胃泌素可作用于相同的受体，产生相同（有时也相反，参见十版生理学P168）的生物学效应有关。不过笔者查阅了所有的参考书及文献资料均未找到“胃泌素激素”这一概念。","","N"],["1988-N48",6,"第1节 能量代谢","间接测热法",1988,48,"A","","临床用简便方法测定能量代谢，必须测定的数据是",[["A","食物的热价"],["B","食物的氧热价"],["C","非蛋白呼吸商"],["D","一定时间内的耗氧量"],["E","一定时间内的二氧化碳生产量"]],"D","能量代谢率的经典测算方法：1.测定机体在一定时间内的尿氮排出量，根据尿氮排出量计算出体内消耗蛋白质的量（尿氮量除以0.16），然后根据蛋白质的生物热价（18kJ/g）计算出蛋白质部分的产热量；2.测定机体在一定时间内的耗氧量和CO₂产生量，减去蛋白质氧化时的耗氧量和CO₂产生量（根据第一步消耗蛋白质的量计算出来的），得出非蛋白物质氧化时的耗氧量和CO₂产生量，然后计算出非蛋白呼吸商（NPRQ），然后根据P223表7-2得出相对应的非蛋白氧热价，从而计算出非蛋白部分的产热量；3.将氧化蛋白质的产热量与氧化非蛋白质的产热量相加，即可算出机体在一定时间内的总产热量，即能量代谢率。能量代谢率的简化测算方法：经典测算方法的步骤比较繁琐，在临床工作中，采用相对简便的测定方法，一种方法是将蛋白质的产热量和耗氧量忽略不计（体内能量主要来自糖和脂肪的氧化），将测得的一定时间内的耗氧量和CO₂产生量所求得的呼吸商视为非蛋白呼吸商，经査表找到相对应的氧热价，耗氧量与此氧热价相乘，便可计算出一定时间内的产热量。另外一种方法更简单，只需测定一定时间内的耗氧量（D对），根据国人的统计资料，受试者食用混合膳食时的非蛋白呼吸商定为0.82，与此相对应的氧热价为20. 20kJ/L，用测定的一定时间内的耗氧量乘以20. 20kJ/L，即可得到这时间内的产热量。用简化方法所获得数值与经典测算方法所得数值非常接近。","","N"],["1988-N49",9,"第3节 神经系统对躯体运动的调控","牵张反射的感受器",1988,49,"A","","肌梭的传入冲动增多",[["A","对同一肌肉的运动神经元起抑制作用"],["B","对其他肌肉的运动神经元起抑制作用"],["C","对脊髓的闰绍细胞起抑制作用"],["D","对其他关节肌肉的运动神经元起兴奋作用"],["E","对同一肌肉的运动神经元起兴奋作用"]],"E","肌梭是感受肌肉长度的感受器，当肌肉受外力牵拉而使肌梭感受装置被拉长时，传入神经传入冲动增加，肌梭的传入冲动增加可引起支配同一肌肉的α运动神经元兴奋（E对ABD错），它一方面使梭外肌收缩，形成一次牵张反射；另一方面α运动神经元通过轴突侧支激活抑制性中间神经元闰绍细胞（C错），闰绍细胞再通过其短轴突释放抑制性递质（甘氨酸）抑制该运动神经元和同类的其他运动神经元，此为回返性抑制。","","N"],["1988-N50",8,"第3节 视觉","眼的折光系统",1988,50,"A","","眼的折光系统中，折光力量大的界面是",[["A","房水-水晶体前面界面"],["B","角膜后表面-房水界面"],["C","水晶体后表面-玻璃体界面"],["D","玻璃体-视网膜界面"],["E","空气-角膜前表面界面"]],"E","根据光学原理，当光线从一种媒质进入另一种媒质时将发生折射，折射的程度取决于界面后对界面前两种不同媒质的折射率之比和界面的曲率大小。人眼的折光系统是一个复杂的光学系统。人眼光线在到达视网膜之前，须先后通过角膜、房水、晶状体和玻璃体4种折射率不同的折光体（媒质），以及各折光体（主要是角膜和晶状体）的前、后表面多个屈光度不等的折射界面。由于角膜的折射率明显高于空气的折射率，而眼内4种折光体之间的折射率以及各折射界面之间的曲率均相差不大，故入眼光线的折射主要发生在角膜前表面（E对）。","","N"],["1988-N51",10,"第6节 胰岛内分泌","激素的调节作用",1988,51,"A","","关于胰岛素的相互作用，哪项是错误的",[["A","胰岛素抑制胰高血糖素的分泌"],["B","胰高血糖素抑制胰岛素的分泌"],["C","胰高血糖素促进生长抑素的分泌"],["D","生长抑素抑制胰岛素的分泌"],["E","胰高血糖素促进胰岛素的分泌"]],"B","胰岛素、胰高血糖素、生长抑素（下丘脑、胃肠也可分泌）三者均为由胰岛分泌的内分泌激素（十版生理学P373），三者的相互作用关系错综复杂：胰岛素抑制胰高血糖素的分泌（A对），胰高血糖素促进胰岛素和生长抑素的分泌（CE对）（B错，为本题正确答案），生长抑素抑制胰岛素和胰高血糖素的分泌（D对）。","","N"],["1988-N52",11,"第2节 女性生殖功能及其调节","月经周期各期的内分泌调控",1988,52,"A","","以下关于月经周期的描述，错误的是",[["A","在FSH作用下，卵巢的卵泡期开始"],["B","排卵前血中雌激素逐渐增多，并形成第一次高峰"],["C","月经前半期，由于雌激素负反馈作用，出现LH分泌高峰"],["D","在LH高峰作用下，卵泡排卵，卵巢进入黄体期"],["E","黄体发育，雌激素、孕激素大量分泌，子宫内膜进入分泌期"]],"C","在卵泡早期（月经周期第1～5天），在卵泡刺激素（FSH）和黄体生成素（LH）的作用下，未发育成熟的卵泡进入卵巢周期的卵泡期（A对）。在卵泡晚期（月经周期第6～14天），卵泡逐渐发育成熟，雌激素分泌不断增多，至排卵前一天左右，血中雌激素浓度到达最高值，形成月经周期中雌激素的第一次高峰（B对），雌激素高峰通过正反馈机制，促进下丘脑促性腺激素释放激素（GnRH）分泌增强，后者进而刺激LH分泌增多，形成LH高峰（C错，为本题正确答案）。在LH高峰作用下，卵泡排卵，排卵后卵巢进入黄体期（D对）。黄体期，黄体细胞在LH的作用下分泌大量雌激素和孕激素（P410），在雌激素和孕激素的刺激下，子宫内膜细胞体积增大，糖原含量增加，腺管增长而变弯曲，分泌含糖原的黏液，使子宫内膜进入子宫周期的分泌期（P410）（E对）。","","N"],["1988-N76",3,"第2节 心脏的电生理学及生理特性","心脏的起搏点",1988,76,"B","","窦房结",[["A","只有传导性而无自律性，传导速度很慢"],["B","只有自律性而无传导性"],["C","既有自律性也有传导性，自律性较低，传导速度较慢"],["D","既有自律性也有传导性，传导速度较快"],["E","既有自律性也有传导性，自律性较高"]],"E","心肌细胞有四种基本生理特性，即兴奋性、自律性、传导性和收缩性。其中工作细胞（心室肌和心房肌）具有兴奋性、传导性和收缩性，自律细胞（窦房结细胞、房室结细胞、浦肯野细胞）具有兴奋性、自律性和传导性。在所有心肌细胞里，窦房结细胞自律性最高，房室交界结区传导速率最慢：窦房结细胞动作电位4期自动去极化速率最快，单位时间内发生兴奋的次数最多，因而自律性最高（E对）；房室交界结区细胞直径最小，局部电流沿细胞纵轴流动的纵向电阻最大，电紧张电位的扩布距离最近，因而兴奋的传导速度最慢。","","N"],["1988-N77",3,"第2节 心脏的电生理学及生理特性","心脏的起搏点",1988,77,"B","","房室交界结区",[["A","只有传导性而无自律性，传导速度很慢"],["B","只有自律性而无传导性"],["C","既有自律性也有传导性，自律性较低，传导速度较慢"],["D","既有自律性也有传导性，传导速度较快"],["E","既有自律性也有传导性，自律性较高"]],"C","心肌细胞有四种基本生理特性，即兴奋性、自律性、传导性和收缩性。其中工作细胞（心室肌和心房肌）具有兴奋性、传导性和收缩性，自律细胞（窦房结细胞、房室结细胞、浦肯野细胞）具有兴奋性、自律性和传导性。在所有心肌细胞里，窦房结细胞自律性最高，房室交界结区传导速率最慢：窦房结细胞动作电位4期自动去极化速率最快，单位时间内发生兴奋的次数最多，因而自律性最高；房室交界结区细胞直径最小，局部电流沿细胞纵轴流动的纵向电阻最大，电紧张电位的扩布距离最近，因而兴奋的传导速度最慢（C对）。","","N"],["1988-N78",6,"第2节 体温及其调节","温度感受器",1988,78,"B","","中枢性温度感受神经元数量较多的部位是",[["A","视前区-下丘脑前部"],["B","下丘脑后部"],["C","大脑皮层运动区"],["D","中脑"],["E","脑干网状结构"]],"A","中枢温度感受器是存在于中枢神经系统内对温度变化敏感的神经元，包括热敏神经元和冷敏神经元。下丘脑、脑干网状结构和脊髓等中枢神经系统中都含有温度敏感神经元，其中在视前区-下丘脑前部（PO/AH）热敏神经元居多（A对）；而在脑干网状结构和下丘脑的弓状核，则冷敏神经元较多（E对）。本题问的是中枢性温度感受神经元数量较多的部位，故AE均正确，但给出的答案仅为A。","","N"],["1988-N79",6,"第2节 体温及其调节","出汗",1988,79,"B","","精神性发汗中枢可能位于",[["A","视前区-下丘脑前部"],["B","下丘脑后部"],["C","大脑皮层运动区"],["D","中脑"],["E","脑干网状结构"]],"C","精神紧张或情绪激动时，也会引起发汗，称为精神性发汗。其中枢位于大脑皮层运动区（C对），通过支配汗腺的交感肾上腺素能纤维引起发汗，发汗部位主要在掌心、足底及前额等处。精神性发汗与体温调节的关系不大，而是机体应激反应的表现之一。","","N"],["1988-N82",5,"第7节 吸收","脂肪的吸收",1988,82,"B","","脂蛋白缺乏",[["A","酸的酯化增强"],["B","血浆中与清蛋白结合的游离脂肪酸增多"],["C","禁食12小时后，血浆中有多量的乳糜微粒"],["D","血浆高密度脂蛋白（HDL）减少"],["E","禁食12小时后，血浆胆固醇处于极高水平"]],"B","略","","N"],["1988-N89",3,"第5节 器官循环","冠脉循环的生理特点",1988,89,"C","","可伴有休克",[["A","出血坏死型胰腺炎"],["B","隐性心肌梗死"],["C","两者都是"],["D","两者都不是"]],"C","由于冠脉的分支大部分深埋于心肌组织中，故心肌收缩对冠脉血流量（CBF）有很大影响，尤其是对左心室冠脉血流量的影响，在等容收缩期，心肌强烈收缩，压迫冠脉血管，使冠脉血流急剧减少，左冠状动脉血流甚至发生倒流（B对）。","","N"],["1988-N94",5,"第1节 消化生理概述","电生理特性",1988,94,"C","","胃肠平滑肌的自律性运动",[["A","起源于肌肉本身"],["B","整体中受自主神经系统和体液因素的调节"],["C","两者均是"],["D","两者均不是"]],"C","胃肠平滑肌的自律性运动源自于胃肠平滑肌的基本电节律（慢波），基本电节律起源于肌肉本身，故胃肠平滑肌的自律性运动也起源于肌肉本身（A对）。胃肠平滑肌的自律性运动受自主神经（交感神经和副交感神经，属于周围神经系统的一部分）和胃肠激素等体液因素的的调节（B对）。本题AB均对，正确答案为C。","","N"],["1988-N95",5,"第1节 消化生理概述","电生理特性",1988,95,"C","","胃肠平滑肌的基本电节律",[["A","起源于肌肉本身"],["B","整体中受自主神经系统和体液因素的调节"],["C","两者均是"],["D","两者均不是"]],"C","胃肠平滑肌的基本电节律（慢波）起源于肌肉本身的Cajal间质细胞，而不起源于外来神经的支配（区别于骨骼肌）（A对）。慢波的幅度和频率产生不依赖于自主神经（交感神经和副交感神经，属于周围神经系统的一部分）和体液的支配，但是受到自主神经系统和体液因素的调节（B对）。本题AB均对，正确答案为C。","","N"],["1988-N96",9,"第4节 神经系统对内脏活动、本能行为和情绪的调节","自主神经系统的结构特征",1988,96,"C","","肾上腺髓质受",[["A","交感神经支配"],["B","副交感神经支配"],["C","两者均有"],["D","两者均无"]],"A","交感神经分布广泛，几乎支配所有内脏器官，而副交感神经分布较局限，有些器官没有副交感神经支配，如皮肤和肌肉的血管、一般的汗腺、竖毛肌、肾上腺髓质（A对）和肾脏只有交感神经支配。","","N"],["1988-N97",9,"第4节 神经系统对内脏活动、本能行为和情绪的调节","自主神经系统的结构特征",1988,97,"C","","一般汗腺受",[["A","交感神经支配"],["B","副交感神经支配"],["C","两者均有"],["D","两者均无"]],"A","自主神经包括交感神经和副交感神经，交感神经分布广泛，几乎支配所有内脏器官，而副交感神经分布较局限，有些器官没有副交感神经支配，如皮肤和肌肉的血管、一般的汗腺（A对）、竖毛肌、肾上腺髓质和肾脏只有交感神经支配。值得注意的是支配汗腺的交感神经节后纤维释放的是乙酰胆碱而不是去甲肾上腺素。","","N"],["1988-N110",2,"第3节 生理性止血","内源性凝血途径",1988,110,"X","","因子Ⅹ的激活除Ca²⁺外还需下列哪些凝血因子",[["A","因子Ⅴa"],["B","因子Ⅷ"],["C","因子Ⅲ"],["D","因子Ⅶ"]],"BCD","内源性凝血途径和外源性凝血途径均可激活FⅩ为FⅩa，最终FⅩa与FVa结合形成凝血酶原酶复合物，进而激活凝血酶原（FⅡ）。在内源性凝血途径，FⅨa在Ca²⁺的作用下与FⅧa在活化的血小板提供的膜磷脂表面结合成复合物（因子X酶复合物），可进一步激活FⅩ，生成FⅩa，在此过程中，FⅧa作为辅因子，可使FⅨa对FⅩ的激活速度提高20万倍（B对）。在外源性凝血途径，当血管破损时，暴露出FⅢ，FⅢ与FⅦa结合形成FⅦa-FⅢ复合物，该复合物在磷脂和Ca²⁺存在的情况下迅速激活FⅩ，生成FⅩa，在此过程中FⅢ作为辅因子，可使FⅦa催化FⅩ激活的效力增加1000倍（CD对）。","","N"],["1988-N117",7,"第1节 肾的功能解剖和肾血流量","肾间质",1988,117,"X","","肾脏产生的内分泌素包括",[["A","肾素"],["B","促红细胞生成因子"],["C","前列腺素"],["D","降钙素"]],"ABC","肾素是由肾脏近球细胞分泌的一种酸性蛋白酶（A对），经肾静脉进入血液循环，启动RAS的链式反应，调节动脉血压。肾脏是产生促红细胞生成素（促红细胞生成因子）的主要部位（B对），由肾皮质肾小管周围的间质细胞（如成纤维细胞、内皮细胞）产生，当贫血、缺氧或肾血流减少等因素致肾氧供不足时，其合成和分泌增多，是调节骨髓红细胞生成的主要因子。肾脏还能生成前列腺素（C对），参与局部或全身血管活动的调节。降钙素由甲状腺C细胞（或称滤泡旁细胞）分泌，不是肾脏产生的（D错），肾脏中参与调节钙的吸收和血钙水平的是1α-羟化酶。","","N"],["1988-N137",2,"第4节 血型和输血原则","ABO血型系统",1988,137,"X","","ABO血型系统的抗体是",[["A","天然抗体"],["B","多是IgM"],["C","不透过胎盘"],["D","温抗体"]],"ABC","ABO血型系统存在天然抗体（A对），天然抗体多属IgM（B对），分子量大，不能通过胎盘，因此，血型与胎儿血型不合的孕妇，体内的天然ABO血型抗体一般不能通过胎盘到达胎儿体内，不会使胎儿的红细胞发生凝集破坏（C对）。","","N"],["1988-N138",3,"第4节 心血管活动的调节","颈动脉窦和主动脉弓压力感受性反射",1988,138,"X","","急性失血时，交感神经的调节作用可引起",[["A","阻力血管收缩"],["B","容量血管收缩"],["C","心率加快"],["D","心输出量增加"]],"ABCD","急性出血时，颈动脉窦内压力降低，通过压力感受性反射，使交感神经紧张性增强，作用于心肌细胞的β₁受体，导致心率加快（C对），心脏收缩力加强，心输出量增多（D对），作用于血管平滑肌细胞的α受体，则导致血管收缩（包括阻力血管、容量血管在内的所有血管）（AB对）。","","N"],["1988-N139",4,"第1节 肺通气","弹性阻力和顺应性",1988,139,"X","","肺顺应性",[["A","在平静呼吸范围内大于在深吸气量范围内"],["B","30岁时大于10岁时"],["C","大于肺和胸廓的总顺应性"],["D","在肺充满生理盐水时大于肺充满空气时"]],"ACD","这道题重点解释一下D选项，很多真题参考书的答案并没有给D选项。不选D给出的解释是充满生理盐水时，可以降低肺泡表面张力的肺泡表面活性物质减少，肺泡表面张力增大，肺的顺应性减小。然而，需要注意的是当充满生理盐水时，根本不存在液气界面，也就没有表面张力（肺的表面张力源于肺泡内表面的液-气界面），而肺泡表面活性物质只是降低表面张力。所以，充满生理盐水时，肺泡表面张力几乎为0，肺的弹性阻力减小（由占2/3的肺表面张力和占1/3的肺弹性成分回缩力组成），故顺应性增大（D对）。而如果只是充少量生理盐水再注空气，由于液气界面的存在，表面张力这时是存在的，但充水使表面活性物质的减少，而使表面张力增大，顺应性减少，故临床肺水肿的患者顺应性是减小的。","","N"],["1988-N140",5,"第4节 小肠内消化","神经调节",1988,140,"X","","调节胰液分泌的神经体液因素有",[["A","迷走神经兴奋"],["B","胃泌素"],["C","促胰液素"],["D","支配胰腺的内脏大神经"]],"ABCD","调节胰液分泌的神经体液因素包括：①神经因素包括迷走神经和内脏大神经（属交感神经）（AD对），其中迷走神经起主要作用；②体液因素包括促胰液素（C对）、缩胆囊素、胃泌素（B对）、血管活性肠肽等，其中促胰液素和缩胆囊素起主要作用。","","N"],["1988-N141",7,"第4节 尿液的浓缩和稀释","肾髓质间液渗透浓度梯度的形成",1988,141,"X","","营养不良患者肾的浓缩功能减弱，这是由于",[["A","肾小球滤过率增加"],["B","抗利尿激素分泌减少"],["C","血浆胶体渗透压下降"],["D","尿素生成减少"]],"ACD","营养不良意味着蛋白质摄入不足，导致血浆胶体渗透压下降（C对），进而肾小球有效滤过压增加，肾小球滤过率增加（A对），该题AC选项存在争议，但原正确答案包含AC。抗利尿激素的分泌量主要取决于血浆晶体渗透压（而不是胶体渗透压）的改变，故营养不良对抗利尿激素分泌的影响不大（B错）。内髓组织高渗是由NaCl和尿素共同形成的，营养不良患者，蛋白质代谢减少，尿素生成量减少，尿素在小管外组织间液中积聚减少，影响内髓质高渗（髓质高渗是小管液中水重吸收的动力）的形成，从而降低尿浓缩功能（D对）。","","N"],["1988-N142",9,"第1节 神经系统功能活动的基本原理","突触后抑制",1988,142,"X","","突触后抑制",[["A","是通过抑制性中间神经元实现的"],["B","突触后膜呈超极化"],["C","回返性抑制和交互性抑制均属突触后抑制"],["D","由一个兴奋性神经元直接引起下一个神经元的抑制"]],"ABC","中枢抑制分为突触后抑制和突触前抑制两种，突触后抑制是由抑制性中间神经元释放抑制性递质，使突触后神经元发生超极化（B对），产生IPSP。突触后抑制的产生必须有抑制性中间神经元的参与（A对），而不能由一个兴奋性神经元直接引起下一个神经元的抑制（D错）。交互性抑制又称传入侧支性抑制，它和回返性抑制为突触后抑制的两种基本形式（C对）。","","N"],["1988-N148",7,"第3节 肾小管和集合管的物质转运功能","K⁺的重吸收和分泌",1988,148,"X","","下列哪些情况时血浆K⁺浓度会升高",[["A","酸中毒"],["B","醛固酮分泌过多"],["C","缺氧"],["D","注射葡萄糖和胰岛素"]],"AC","当发生酸中毒时，肾小管上皮细胞Na⁺-H⁺交换加强，而Na⁺-K⁺交换则受抑制（因为H⁺和K⁺二者存在竞争性抑制关系），可造成血K⁺浓度升高（A对）。机体缺氧导致葡萄糖以糖酵解方式供能，使体内酸性代谢产物增多，发生代谢性酸中毒，引起血K⁺浓度升高（C对）。醛固酮的作用是保钠排钾，故醛固酮分泌过多，血钾浓度会降低（B错）。注射葡萄糖和胰岛素均可引起血中胰岛素浓度升高，胰岛素可促进K⁺进入细胞，降低血浆K⁺浓度（D错）。","","N"],["1988-N150",10,"第4节 甲状旁腺、维生素D与甲状腺C细胞内分泌","1,25-二羟维生素D₃生成的调节",1988,150,"X","","抑制25（OH）D₃-1α-羟化酶系的因素是",[["A","CT"],["B","低血磷"],["C","1，25-（OH）₂-D₃"],["D","PTH（甲状旁腺素）"]],"AC","合成1，25-（OH）₂D₃所需的1α羟化酶的活性受很多因素影响。其中抑制因素包括1，25-（OH）₂D₃本身（负反馈抑制）和1，25-（OH）₂D₃的拮抗激素CT（降钙素）（AC对）；激活因素包括1，25-（OH）₂D₃的合成前体维生素D、PTH（甲状旁腺素）、低血钙、低血磷等（BD错）。","","N"],["1989-N22",2,"第3节 生理性止血","内源性凝血途径",1989,22,"A","","在凝血过程中能起自我催化作用的是",[["A","接触因子（凝血因子Ⅻ）"],["B","钙离子"],["C","凝血酶"],["D","组织凝血活酶"],["E","凝血酶原"]],"A","接触因子即FⅫ（十版生理学P68 表3-2 凝血因子的某些特性），在内源性凝血途径中，当血液与带负电荷的异物表面接触时，首先是FⅫ接触并结合到异物表面，故得名接触因子。FⅫ与异物表面结合之后被激活为活性形式FⅫa，FⅫa再激活前激肽释放酶成为激肽释放酶，激肽释放酶又可以激活FⅫ成为FⅫa，构成FⅫ的正反馈激活过程，即FⅫ→前激肽释放酶→FⅫ，故FⅫ（接触因子）通过前激肽释放酶间接完成了自我催化的作用（A对）。钙离子即FⅣ，可以作为辅因子辅助依赖维生素K的凝血因子（FⅡ、FⅦ、FⅨ、FⅩ）发挥作用，依赖维生素K的凝血因子的分子中均含有γ-羧基谷氨酸，和钙离子结合后可发生变构，暴露出与磷脂结合的部位而参与凝血。钙离子来源于食物，不需要被激活，更不存在自我催化的过程（B错）。凝血酶原即FⅡ，可在凝血酶原复合物（FⅩa-FⅤa-Ca²⁺-磷脂复合物）的催化下激活成为凝血酶，凝血酶可使纤维蛋白原（FⅠ）从N端脱下四段小肽，转变为纤维蛋白单体。凝血酶和凝血酶原均不存在自我催化作用（CE错）。组织凝血活酶又称组织因子，即FⅢ，为FⅦa的辅因子，是外源性凝血途径的启动物，不存在自我催化作用（D错）。","","N"],["1989-N26",10,"第1节 内分泌与激素","脂类激素",1989,26,"A","","下列激素属于类固醇激素的是",[["A","生长激素释放因子（GHRF）"],["B","生长激素（GH）"],["C","促卵泡激素（FSH）"],["D","雌激素"],["E","催乳素"]],"D","激素分子结构形式多样，其化学本质直接决定激素对靶细胞的作用机制。激素一般按化学性质可分为胺类、肽与蛋白质类和脂类。胺类激素的典型代表为儿茶酚胺类激素（去甲肾上腺素、肾上腺素和多巴胺等）、甲状腺激素、褪黑素等；肽类和蛋白质类激素的典型代表包括下丘脑调节肽（A错）、腺垂体激素（BCE错）、甲状旁腺素、胰岛素、胃肠激素等；脂类激素的典型代表为类固醇激素，如孕酮、醛固酮、皮质醇、睾酮、雌二醇（D对）和胆钙化醇。","","N"],["1989-N40",2,"第3节 生理性止血","生理性止血的基本过程",1989,40,"A","","血凝块回缩是由于",[["A","血凝块中纤维蛋白收缩"],["B","红细胞发生叠连而压缩"],["C","白细胞发生变形运动"],["D","血小板的收缩蛋白收缩"],["E","以上都不是"]],"D","血小板的收缩能力与其收缩蛋白有关，在血小板内存在类似肌肉的收缩蛋白系统（D对），包括肌动蛋白（血小板微丝）、肌球蛋白等等，血凝块中的血小板收缩，血凝块回缩，挤出其中的血清，使血凝块更加坚实，牢固封住血管的破口。","","N"],["1989-N41",3,"第4节 心血管活动的调节","RAS的构成",1989,41,"A","","产生肾素的细胞是",[["A","肾上腺髓质的嗜铬细胞"],["B","入球和出球小动脉的近球细胞"],["C","远曲小管的致密斑细胞"],["D","近球小体的间质细胞"],["E","近球小管的小皮细胞"]],"B","肾脏近球细胞又称颗粒细胞或球旁细胞，是入球小动脉和出球小动脉管壁中一些特殊分化的平滑肌细胞，细胞内含颗粒，能合成、储存和释放肾素。","","N"],["1989-N42",3,"第5节 器官循环","冠脉循环的生理特点",1989,42,"A","","在人体处于安静状态时，下列哪个器官的动脉血和静脉血含氧量差值最大",[["A","脑"],["B","心脏"],["C","肾脏"],["D","皮肤"],["E","骨骼肌"]],"B","器官的摄氧率越高，耗氧量越大时，动脉血和静脉血含氧量差值就越大。在所有器官中，心脏的摄氧率最高，耗氧量最大（B对）。","","N"],["1989-N43",4,"第1节 肺通气","弹性阻力和顺应性",1989,43,"A","","肺泡表面活性物质",[["A","位于肺泡上皮与液体分子层之间"],["B","由肺泡Ⅰ型细胞所分泌"],["C","主要成分是二硬脂酰卵磷脂"],["D","可使肺顺应性变大"],["E","增加肺泡表面张力"]],"D","肺泡细胞包括Ⅰ型细胞和Ⅱ型细胞两类，其中Ⅰ型细胞是普通的肺泡上皮细胞，覆盖了肺泡95%的表面积，是进行气体交换的部位。Ⅱ型细胞具有分泌功能，能够分泌肺表面活性物质（B错），肺泡表面活性物质的主要成分是二棕榈酰卵磷脂，也叫二软脂酰卵磷脂（C错），二棕榈酰卵磷脂以单层分子垂直排列于肺泡液-气界面，而不是位于肺泡上皮与液体分子层之间（A错）。肺表面活性物质的主要作用是降低肺泡表面张力（E错），增加肺顺应性（D对）。","","N"],["1989-N44",4,"第3节 气体在血液中的运输","Hb与O₂结合的特征",1989,44,"A","","当血液的血红蛋白含量正常时，如果血红蛋白氧饱和度为60％，则每100ml血的含氧量约为",[["A","10.5ml"],["B","12ml"],["C","13.4ml"],["D","20ml"],["E","40ml"]],"B","血液的血红蛋白含量正常约为15g/100ml，1g血红蛋白实际能结合的O₂量约为1.34ml，在100ml血液中，Hb所能结合的最大的O₂量为15g×1.34ml/g=20.1ml，即Hb氧容量为20.1ml。血氧饱和度为Hb氧含量（100ml血液中Hb实际所结合的O₂量）与Hb氧容量的百分比，即血氧饱和度=Hb氧含量/Hb氧容量，当血氧饱和度为60%，Hb氧容量为20.1ml时，Hb氧含量约为12ml（B对）。","","N"],["1989-N45",5,"第3节 胃内消化","抑制胃液分泌的主要因素",1989,45,"A","","通过肠-胃反射",[["A","促进胃的排空，抑制胃酸分泌"],["B","抑制胃的排空，促进胃酸分泌"],["C","促进胃的排空，促进胃酸分泌"],["D","抑制胃的排空，抑制胃酸分泌"],["E","以上都不是"]],"D","十二指肠和空肠黏膜具有多种感受器，可以感受酸、渗透压、机械扩张以及脂肪、氨基酸、肽类等物质的刺激反射性抑制胃的运动，延缓胃排空，抑制胃酸分泌（D对）等。此反射称为肠胃反射。","","N"],["1989-N46",6,"第1节 能量代谢","基础代谢",1989,46,"A","","以下有关“基础代谢率”的叙述，哪一项是错误的",[["A","男子的基础代谢率平均比女子的高"],["B","幼儿的基础代谢率比成人的高"],["C","老年人的基础代谢率低"],["D","体重相同的人，其基础代谢率较接近"],["E","基础代谢率同体表面积之间具有比例关系"]],"D","基础代谢率是指在基础状态下单位时间内的能量代谢。基础代谢率的高低与体重不成比例关系（D错，为本题正确答案），而与体表面积成正比（E对），基础代谢率常以单位时间内单位面积的产热量为单位来表示。除体表面积外，基础代谢率还因受试者性别、年龄的不同而有差异，当其他情况相同时，男性的基础代谢率平均值较同龄组女性高（A对）；儿童的基础代谢率比成人高（B对），年龄越大，代谢率越低（C对）。","","N"],["1989-N47",9,"第4节 神经系统对内脏活动、本能行为和情绪的调节","交感神经系统的功能",1989,47,"A","","交感神经兴奋时出现",[["A","瞳孔缩小"],["B","骨骼肌血管舒张"],["C","消化道括约肌舒张"],["D","逼尿肌收缩"],["E","支气管平滑肌收缩"]],"B","大多数交感节后纤维释放的递质是去甲肾上腺素（除支配汗腺和骨骼肌血管的交感节后纤维释放乙酰胆碱外），交感神经系统的活动与各器官上去甲肾上腺素受体的分布有关。交感神经兴奋时，作用于虹膜辐射状肌（瞳孔开大肌）的α₁受体使虹膜辐射状肌收缩，瞳孔扩大（A错）。作用于骨骼肌血管的β₂受体（去甲肾上腺素介导）或M受体（乙酰胆碱介导）使骨骼肌血管舒张（B对）；作用于消化道括约肌的α₁受体使消化道括约肌收缩（C错）。作用于膀胱逼尿肌的β₂受体使逼尿肌舒张（D错）。作用于支气管平滑肌的β₂受体使支气管平滑肌舒张（E错）。交感神经兴奋的状态可以用机体在剧烈运动时的生理状态来协助记忆：机体在剧烈运动时交感神经兴奋（十版生理学P322），心率加快、心肌收缩力增强，心输出量增加，目的是为全身的肌肉提供更多的血液和氧气；呼吸运动加强，支气管平滑肌舒张，肺泡通气量，目的是为了血液提供更多的氧气；皮肤、肾、胃肠等全身各处的血管平滑肌均收缩，但骨骼肌血管舒张，目的是为了让血液重新分配，为肌肉提供更多的血液；由于全身血液分配至骨骼肌，导致胃肠道供血不足，不利于胃肠道进行消化和吸收，故消化道平滑肌舒张，括约肌收缩，消化腺分泌减少；剧烈运动时，一般不会有特别强烈的尿意，也尿不出来等等。","","N"],["1989-N48",10,"第1节 内分泌与激素","内分泌系统",1989,48,"A","","调节机体各种机能的两大信息传递系统是",[["A","第一信号系统与第二信号系统"],["B","第一信使与第二信使"],["C","cAMP与cGMP"],["D","中枢神经系统与外周神经系统"],["E","神经系统与内分泌系统"]],"E","内分泌系统通过分泌各种激素全面调控与个体生存密切相关的基础功能活动，如维护组织和细胞的新陈代谢，调节机体的生长、发育、生殖及衰老过程等。它与神经系统和免疫系统的调节能相辅相成，分别从不同的方面调节和维持机体的内环境稳态（E对）。","","N"],["1989-N49",11,"第2节 女性生殖功能及其调节","卵巢的生卵作用",1989,49,"A","","血中哪一激素出现高峰可作为排卵标志",[["A","催乳素"],["B","卵泡刺激素"],["C","黄体生成素"],["D","催乳素释放因子"],["E","催乳素释放抑制因子"]],"C","LH峰是引发排卵的关键因素，可作为排卵标志（C对）：在LH峰出现之前，初级卵母细胞由于周围的颗粒细胞分泌一种卵母细胞成熟抑制因子（OMI），使卵母细胞的成熟分裂停止于初级卵母细胞阶段。当LH峰出现时，高浓度的LH可抵消OMI的抑制作用，使初级卵母细胞恢复分裂，形成次级卵母细胞和第一极体。随即次级卵母细胞开始第二次成熟分裂，最后，次级卵泡逐渐发育为成熟卵泡并突出于卵巢表面，形成透明的卵泡小斑（排卵孔）。LH峰的出现还能促进卵泡细胞分泌孕激素和前列腺素，孕激素可激活纤溶酶、胶原酶、蛋白水解酶及透明质酸酶等，使卵泡壁溶解破裂，前列腺素可使卵泡壁肌上皮细胞收缩，这些作用都有助于卵细胞从排卵孔排出。","","N"],["1989-N58",7,"第5节 尿生成的调节","概述",1989,58,"A","","抗利尿激素",[["A","是蛋白质类激素"],["B","由垂体后叶合成"],["C","作用于近曲小管"],["D","在血容量增加时分泌减少"],["E","在体液渗透压下降时分泌增加"]],"D","抗利尿激素又称血管升压素，是由下丘脑视上核和室旁核神经元合成，经下丘脑-垂体束运输到神经垂体（垂体后叶）储存的多肽类激素，而非蛋白质类激素（十版生物化学与分子生物学P12 50个氨基酸残基以上为蛋白质，50个氨基酸残基以下为多肽）（AB错）。抗利尿激素有V₁和V₂两种受体，V₁受体分布于血管平滑肌，V₂受体分布于肾集合管主细胞基底侧（十版生理学P231），故抗利尿激素主要作用于肾集合管，而不是近曲小管（C错）。抗利尿激素的释放受多重因素的调节和影响，其中最重要的是体液渗透压和血容量：体液渗透压下降时，下丘脑渗透压感受器刺激减少，抗利尿激素分泌也减少（E错）；血容量增加时，静脉回心血量增加，可刺激心肺感受器，使经迷走神经传入下丘脑的冲动增加，抑制抗利尿激素的释放（D对）。","","N"],["1989-N89",3,"第5节 器官循环","冠脉循环的生理特点",1989,89,"B","","左心室等容收缩期",[["A","左冠脉血流不变"],["B","左冠脉血流急剧减少"],["C","左冠脉血流缓慢增加"],["D","左冠脉血流急剧增加"],["E","左冠脉血流达最大值"]],"B","由于冠脉的分支大部分深埋于心肌组织中，故心肌收缩对冠脉血流量（CBF）有很大影响，尤其是对左心室冠脉血流量的影响，在等容收缩期，心肌强烈收缩，压迫冠脉血管，使冠脉血流急剧减少，左冠状动脉血流甚至发生倒流（B对）。","","N"],["1989-N90",3,"第5节 器官循环","冠脉循环的生理特点",1989,90,"B","","左心室舒张期的早期",[["A","左冠脉血流不变"],["B","左冠脉血流急剧减少"],["C","左冠脉血流缓慢增加"],["D","左冠脉血流急剧增加"],["E","左冠脉血流达最大值"]],"D","在心室舒张期，虽然冠脉血压降低，但由于心室收缩时对冠状动脉的压迫作用被解除，对血流的阻力减小，因为冠脉血流量急剧增加，并且在舒张早期达到高峰，然后逐渐回降，故D和E选项均为本题正确答案，本题给出的参考答案仅为D。","","N"],["1989-N91",4,"第1节 肺通气","肺容量",1989,91,"B","","测定肺通气功能的较好指标是",[["A","潮气量"],["B","肺活量"],["C","时间肺活量"],["D","肺扩散容量"],["E","通气/血流比值"]],"C","肺活量是反映了肺一次通气的最大能力，在一定程度上可作为肺通气功能的指标。但由于测定肺活量时不限制呼气的时间，所以不能充分反映肺组织的弹性状态和气道的通畅程度，即肺通气功能的好坏。例如，某些病人肺组织弹性降低或呼吸道狭窄，通气功能已经受到损害，但是如果延长呼气时间，所测得的肺活量是正常的。因此，提出了时间肺活量的概念，时间肺活量是指一次最大吸气后，第1秒内尽力尽快呼气所能呼出的最大气体量。肺组织弹性降低或呼吸道狭窄的病人肺活量可正常，但时间肺活量是下降的，时间肺活量不仅反映了肺活量的大小，而且反映了肺组织的弹性状态和气道的通畅程度，因此是评论肺通气功能的较好指标（C对）。","","N"],["1989-N92",4,"第2节 肺换气和组织换气","通气_血流比值",1989,92,"B","","测定肺换气效率的较好指标是",[["A","潮气量"],["B","肺活量"],["C","时间肺活量"],["D","肺扩散容量"],["E","通气/血流比值"]],"E","通气/血流比值是指每分钟肺泡通气量（VA）和每分钟肺血流量（Q）之间的比值（VA/Q）。正常成年人安静时，VA约为4.2L/min，Q约为5L/min，因此，VA/Q约为0.84。如果VA/Q比值增大，就意味着通气过剩，血流相对不足，部分肺泡气体未能与血液气体充分交换，致使肺泡无效腔增大。反之，VA/Q比值下降，则意味着通气不足，血流相对过多，部分血液流经通气不良的肺泡，混合静脉血中的气体不能得到充分更新，犹如发生了功能性动-静脉短路。因此，VA/Q比值可作为衡量肺换气功能的指标（E对）。","","N"],["1989-N93",10,"","",1989,93,"B","","哪种血钙水平，PTH分泌最旺盛",[["A","≤4mg%"],["B","5～7mg%"],["C","7～9mg％"],["D","9～11mg％"],["E","≥12mg％"]],"A","血钙水平是调节甲状旁腺分泌PTH（甲状旁腺素）的最主要因素，血钙水平越低，PTH分泌越多（A对），按照八版生理学的说法，血钙降低至7mg%（7mg/dl）时PTH即可产生最大分泌量，则本题AB均正确。注：7mg%和7mg/dl均代表100ml血液中含7毫克钙离子。","","N"],["1989-N94",10,"第4节 甲状旁腺、维生素D与甲状腺C细胞内分泌","降钙素的分泌调节",1989,94,"B","","哪种血钙水平，CT分泌最旺盛",[["A","≤4mg%"],["B","5～7mg%"],["C","7～9mg％"],["D","9～11mg％"],["E","≥12mg％"]],"E","血钙水平是调节甲状腺C细胞分泌CT（降钙素）的最主要因素，血钙水平越高，CT分泌最旺盛（E对）。","","N"],["1989-N105",5,"第3节 胃内消化","消化期的胃液分泌",1989,105,"C","","食物经咀嚼由咽而进入胃所引起的胃液分泌",[["A","头期的胃液分泌"],["B","胃期的胃液分泌"],["C","两者兼有"],["D","两者均无"]],"C","咀嚼及吞咽过程中通过口腔和咽部感受器反射性引起的胃液分泌，为头期胃液分泌；食物进入胃以后，可刺激胃壁上的机械感受器和化学感受器，促进胃液大量分泌，为胃期胃液分泌。故食物经咀嚼由咽而进入胃所引起的胃液分泌既包括了头期胃液分泌（A对），又包括了胃期胃液分泌（B对）。本题AB均对，正确答案为C。","","N"],["1989-N106",5,"第3节 胃内消化","消化期的胃液分泌",1989,106,"C","","食物经胃瘘管注入胃所引起的胃液分泌",[["A","头期的胃液分泌"],["B","胃期的胃液分泌"],["C","两者兼有"],["D","两者均无"]],"B","空腹时，胃液的分泌量很少，进食后，胃液的分泌开始增多，称为消化期的胃液分泌。根据消化道感受食物刺激的部位，可将消化期的胃液分泌分为头期、胃期和肠期三个时期。食物经胃瘘管注入胃，可直接刺激胃壁上的机械感受器和化学感受器，促进胃液大量分泌，属于胃期胃液分泌（B对）。","","N"],["1989-N132",10,"第4节 甲状旁腺、维生素D与甲状腺C细胞内分泌","甲状旁腺激素的生理作用",1989,132,"X","","关于甲状旁腺激素是",[["A","由甲状旁腺主细胞分泌"],["B","为多肽类激素"],["C","促进破骨细胞的活动"],["D","升高血钙"]],"ABCD","PTH主要由甲状旁腺主细胞合成和分泌（A对），是由84个氨基酸残基构成的多肽激素（B对），其作用效应是升高血钙和降低血磷（D对）。PTH作用的靶器官主要是肾脏和骨，对骨的效应包括促进成骨细胞活动和促进破骨细胞活动两方面（C对），两种作用相互平衡，维持机体骨的正常结构及其更新。说一下B选项，一般而言50个氨基酸残基以下才称多肽，50个氨基酸残基以上称蛋白质（十版生物化学与分子生物学P12），如由29个氨基酸残基组成的胰高血糖素称作为多肽（十版生理学P377），而含有51个氨基酸残基的胰岛素一般称为蛋白质（十版生理学P373），故严格来说由84个氨基酸残基组成的甲状旁腺素为蛋白质类激素，而不为多肽类激素，但本题给出的参考答案为B正确。","","N"],["1989-N143",8,"第3节 视觉","晶状体变凸",1989,143,"X","","眼的调节能力大小的指标是",[["A","远点"],["B","近点"],["C","焦距"],["D","焦度"]],"B","当眼注视6m以外的物体（远物）时，从物体发出的所有进入眼内的光线上可被认为是平行光线，对正常眼来说，不需要作任何调节即可在视网膜形成清晰的像。而在注视近物时，物体上各点发出的光从四面八方进入人眼后呈不同程度的辐射状，需要经过一定的调节才能在视网膜上形成准确清晰的物像，物体离眼越近，就越需要调节，因此可以用近点来表示人眼的调节能力的大小（B对），它是指眼作充分调节时所能看清楚的眼前最近物体的所在之处。","","N"],["1989-N144",5,"第4节 小肠内消化","神经调节",1989,144,"X","","调节胰液分泌的神经体液因素有",[["A","迷走神经兴奋"],["B","胃泌素"],["C","促胰液素"],["D","支配胰腺的内脏大神经"]],"ABCD","调节胰液分泌的神经体液因素包括：①神经因素包括迷走神经和内脏大神经（属交感神经）（AD对），其中迷走神经起主要作用；②体液因素包括促胰液素（C对）、缩胆囊素、胃泌素（B对）、血管活性肠肽等，其中促胰液素和缩胆囊素起主要作用。","","N"],["1989-N145",4,"第2节 肺换气和组织换气","呼吸气体和人体不同部位气体的分压",1989,145,"X","","正常人平静呼吸时",[["A","呼出气氧分压大于肺泡气氧分压"],["B","肺泡气二氧化碳分压约两倍于大气二氧化碳分压"],["C","肺动脉血二氧化碳分压高于肺泡气二氧化碳分压"],["D","肺泡水气压小于肺泡二氧化碳分压的一半"]],"AC","气体分子在体内的一定是由分压高处向分压低处转移。CO₂分压由高到低依次为：细胞内液＞组织液＞组织毛细血管血液＞静脉血液＞肺动脉内的混合静脉血＞肺泡气＞呼出气＞大气（C对）。O₂分压由低到高依次为：细胞内液＜组织液＜组织毛细血管血液＜肺动脉内的混合静脉血＜肺泡气＜呼出气＜大气（A对）。肺泡气二氧化碳分压约为40.3mmHg，大气二氧化碳分压仅为0.3mmHg，因此，肺泡气二氧化碳分压是大气二氧化碳分压的100倍以上（B错）。肺泡水气压约为47.1mmHg，肺泡二氧化碳分压约为40.3mmHg，即肺泡水气压比肺泡二氧化碳分压更大（D错）。","","N"],["1989-N146",1,"第1节 细胞膜的物质转运功能","钠-钾泵",1989,146,"X","","细胞内液与细胞外液相比，细胞内液含有",[["A","较多的Na⁺"],["B","较多的Cl⁻"],["C","较多的Ca²⁺"],["D","较多的K⁺"]],"D","Na⁺、K⁺、Ca²⁺、Cl⁻四种离子中，细胞内液相比细胞外液含量较多的离子只有K⁺（D对），其余三种离子均为细胞外含量高于细胞内。","","N"],["1989-N147",2,"第3节 生理性止血","生理性抗凝物质",1989,147,"X","","下列情况中可延缓或防止凝血的是",[["A","血液中加入枸橼酸钠"],["B","血液置于硅胶管中"],["C","血液中加入肝素"],["D","血液中加入双香豆素"]],"ABC","柠檬酸钠又称枸橼酸钠，可Ca²⁺结合，生成难解离的可溶性络合物枸橼酸钙，Ca²⁺是凝血过程的重要辅助因子，血液中Ca²⁺减少，血液凝固受阻（A对）。临床上测定凝血时间的方法有三种：玻璃管法（正常值4～12min）、塑料管法（正常值10～19min）、硅管法（正常值15～32min），硅胶管表面带正电荷，不易使凝血因子接触活化，凝血时间比较长（B对）。肝素是一种酸性黏多糖，可以使抗凝血酶的抗凝作用增强2000倍以上，常用于临床病人手术后抗凝治疗，以预防血栓形成（C对）。双香豆素为维生素K 类似物，通过竞争性拮抗维生素K的作用，抑制FⅡ、FⅦ、FⅨ、FⅩ等维生素K依赖的凝血因子的合成，因此在体内具有抗凝作用，但在体外无抗凝作用，因为体外血液不存在凝血因子的合成过程，双香豆素对血液中已有的凝血因子FⅡ、FⅦ、FⅨ、FⅩ并无抑制作用，故血液中加入双香豆素并不能达到延缓或防止凝血的目的（D错），临床上常用的体内的抗凝剂华法林为双香豆素衍生物，与双香豆素同属于香豆素类抗凝剂。","","N"],["1989-N148",1,"第1节 细胞膜的物质转运功能","原发性主动转运",1989,148,"X","","心肌细胞外Na⁺浓度增高时",[["A","Na⁺-Ca²⁺交换增强"],["B","Na⁺-K⁺交换减弱"],["C","细胞内Ca²⁺浓度降低"],["D","细胞内K⁺浓度升高"]],"AC","钠泵的重要功能之一就是维持细胞内外的Na⁺、K⁺浓度梯度，这是细胞发生电活动的基础。当细胞内的Na⁺浓度升高时，细胞内外的Na⁺浓度差减小，钠泵被激活，将细胞内多余的Na⁺排出细胞外，维持细胞内外正常的Na⁺浓度差，而当细胞外Na⁺浓度升高时，细胞内外的Na⁺浓度差增大，钠泵则被抑制，抑制Na⁺排出细胞外，同时也抑制了K⁺进入细胞内，细胞内K⁺浓度降低（D错）。Na⁺-Ca²⁺交换和Na⁺-K⁺交换属于继发性主动转运，其驱动力来自Na⁺的跨膜浓度梯度，Na⁺顺浓度梯度内流的同时，带动Ca²⁺和K⁺外流，当细胞外Na⁺浓度升高时，Na⁺顺浓度梯度内流增加，Na⁺-Ca²⁺交换和Na⁺-K⁺交换均增强（A对B错）。Na⁺-Ca²⁺交换增强，Ca²⁺外流增多，细胞内Ca²⁺浓度降低（C对）。","","N"],["1989-N152",2,"第2节 血细胞生理","红细胞生成所需物质",1989,152,"X","","影响红细胞成熟的因素有",[["A","叶酸"],["B","维生素B₂"],["C","维生素B₁₂"],["D","泛酸"]],"AC","叶酸以四氢叶酸的形式起作用，四氢叶酸作为一碳单位的载体，在体内参与嘌呤核苷酸和胸腺嘧啶核苷酸的合成，故叶酸缺乏时，核苷酸特别是胸腺嘧啶核苷酸合成（十版生物化学与分子生物学P101）减少，红细胞中DNA合成受阻，细胞分裂增殖速度下降，细胞体积增大，核内染色质疏松，影响红细胞成熟，导致巨幼细胞性贫血（A对）。体内叶酸多以N⁵-甲基四氢叶酸形式存在，发挥作用时，N⁵-甲基四氢叶酸与同型半胱氨酸反应生成四氢叶酸与甲硫氨酸（十版生物化学与分子生物学P189），此反应需N⁵-甲基四氢叶酸转甲基酶催化，而维生素B₁₂是该酶的辅酶成分，故当维生素B₁₂缺乏时，转甲基反应受阻，影响四氢叶酸的周转利用，间接影响胸腺嘧啶脱氧核苷酸的生成，同样影响红细胞成熟，导致巨幼细胞性贫血（C对）。维生素B₂（十版生物化学与分子生物学P97）又称核黄素，是FAD和FMN的组成部分，参与氧化呼吸链的递氢过程，维生素B₂是红细胞生成的原料之一（十版生理学P59），但与红细胞的成熟无关（B错）。泛酸（十版生物化学与分子生物学P99）又称遍多酸，因广泛存在于动、植物组织中而得名，是辅酶A的组成部分，参与酰基转移的过程，同样与红细胞生成无关（D错）。","","N"],["1990-N25",2,"第3节 生理性止血","凝血因子",1990,25,"A","","下述哪种因子不存在于血浆中",[["A","Ⅴ因子"],["B","Ⅲ因子"],["C","Ⅹ因子"],["D","Ⅻ因子"],["E","Ⅶ因子"]],"B","FⅢ因子又称组织因子，正常情况下，FⅢ因子位于血管壁外膜细胞，而在血管中膜或内膜层却很稀少，在正常情况下FⅢ因子不与循环血液接触，不存在于血浆中（B对）。因为FⅢ因子来自血液之外，由FⅢ因子（组织因子）暴露于血液而启动的凝血过程，称为外源性凝血途径。","","N"],["1990-N30",10,"第1节 内分泌与激素","脂类激素",1990,30,"A","","下列激素哪一个不是类固醇激素",[["A","醛固酮"],["B","睾酮"],["C","促肾上腺皮质激素"],["D","雌二醇"],["E","皮质醇"]],"C","激素分子结构形式多样，其化学本质直接决定激素对靶细胞的作用机制。激素一般按化学性质可分为胺类、肽与蛋白质类和脂类。胺类激素的典型代表为儿茶酚胺类激素（去甲肾上腺素、肾上腺素和多巴胺等）、甲状腺激素、褪黑素等；肽类和蛋白质类激素的典型代表包括下丘脑调节肽、腺垂体激素（C对）、甲状旁腺素、胰岛素、胃肠激素等；脂类激素的典型代表为类固醇激素，如孕酮、醛固酮（A错）、皮质醇（E错）、睾酮（B错）、雌二醇（D错）和胆钙化醇。","","N"],["1990-N41",3,"第3节 血管生理","影响动脉血压的因素",1990,41,"A","","能使脉压增大的情况是",[["A","射血期延长"],["B","外周阻力增大"],["C","心率加快"],["D","体循环平均压降低"],["E","大动脉的可扩张性减小"]],"E","射血期延长，可能由于心脏收缩能力减弱或者外周阻力增大，前者每搏量下降导致收缩压下降更明显，脉压下降；后者舒张压升高得比收缩压更明显，脉压下降（A错）。体循环平均充盈压下降时，静脉回心血量减少，心脏每搏输出量减少，每搏出量减少时，收缩压的降低比舒张压的降低更显著，脉压减小（D错）。","","N"],["1990-N42",7,"第4节 尿液的浓缩和稀释","肾髓质间液渗透浓度梯度的形成",1990,42,"A","","进入集合管的尿液是",[["A","低渗的"],["B","等渗的"],["C","高渗的"],["D","低渗或等渗的，但不会是高渗的"],["E","等渗或高渗的，但不会是低渗的"]],"D","按照八版教材的观点（八版生理学P257），远曲小管与集合管一样可受抗利尿激素的调节而重吸收水，在这种情况下，经过远曲小管渗透作用重吸收水之后，小管液最多可以上升至等渗（等渗之后达到平衡，不可能为高渗），故认为小管液的渗透浓度在离开远曲小管进入集合管之前为低渗或等渗，但不会是高渗的（D对）。根据九、十版生理学，髓袢升支细段、髓袢升支粗段和远曲小管，均为通透NaCl而不通透水的低渗重吸收，小管液渗透浓度依次逐渐下降，至远曲小管时，小管液的渗透浓度降至最低。集合管上存在水通道蛋白（AQP），开始变得对水具有通透性，可以在抗利尿激素的调控下对水进行重吸收，这种重吸收是基于肾小管内外的渗透浓度梯度（基于小管液的渗透浓度低于管周组织液），又由于远曲小管位于皮髓质交界，该处组织液渗透浓度≤血浆渗透浓度，故小管液的渗透浓度在离开远曲小管进入集合管之前只能为低渗（小管液的渗透浓度＜组织液渗透浓度≤血浆渗透浓度）（A对）。综上，根据九、十版生理学，正确答案应为A，当年给出的参考答案为D。","","N"],["1990-N43",11,"第1节 男性生殖功能及其调节","睾酮的生理作用",1990,43,"A","","雄激素的作用，哪项是错误的",[["A","刺激雄性附性器官发育，并使之维持在成熟状态"],["B","刺激男性副性征出现"],["C","促进肌肉与骨骼生长，使男子身高在青春期冲刺式生长"],["D","分泌过盛，可使男子身高超出常人"],["E","维持正常的性欲"]],"D","雄激素的作用比较广泛，主要包括以下几个方面：①促进胚胎性器官的分化；②刺激附属性器官的发育并使之维持在成熟状态（A对）；促进男性第二性征的出现（B对）；③促进生精细胞的分化和精子的生成（维持生精效应）；④维持男性的正常性欲（E对）；⑤促进蛋白质的合成并抑制其分解，加速肌肉与骨骼的生长（C对）。分泌过盛，可使男子身高超出常人的是生长激素（D错，为本题正确答案）。","","N"],["1990-N44",6,"第1节 能量代谢","间接测热法",1990,44,"A","","临床用简便方法测定能量代谢，必须测定的数据是",[["A","食物的热价"],["B","食物的氧热价"],["C","非蛋白呼吸商"],["D","一定时间内的耗氧量"],["E","一定时间内的二氧化碳生产量"]],"D","能量代谢率的经典测算方法：1.测定机体在一定时间内的尿氮排出量，根据尿氮排出量计算出体内消耗蛋白质的量（尿氮量除以0.16），然后根据蛋白质的生物热价（18KJ/g）计算出蛋白质部分的产热量；2.测定机体在一定时间内的耗氧量和CO₂产生量，减去蛋白质氧化时的耗氧量和CO₂产生量（根据第一步消耗蛋白质的量计算出来的），得出非蛋白物质氧化时的耗氧量和CO₂产生量，然后计算出非蛋白呼吸商（NPRQ），然后根据十版生理学P199表7-2得出相对应的非蛋白氧热价，从而计算出非蛋白部分的产热量；3.将氧化蛋白质的产热量与氧化非蛋白质的产热量相加，即可算出机体在一定时间内的总产热量，即能量代谢率。能量代谢率的简化测算方法：经典测算方法的步骤比较繁琐，在临床工作中，采用相对简便的测定方法，一种方法是将蛋白质的产热量和耗氧量忽略不计（体内能量主要来自糖和脂肪的氧化），将测得的一定时间内的耗氧量和CO₂产生量所求得的呼吸商视为非蛋白呼吸商，经査表找到相对应的氧热价，耗氧量与此氧热价相乘，便可计算出一定时间内的产热量。另外一种方法更简单，只需测定一定时间内的耗氧量（D对），根据国人的统计资料，受试者食用混合膳食时的非蛋白呼吸商定为0.82，与此相对应的氧热价为20. 20kJ/L，用测定的一定时间内的耗氧量乘以20. 20kJ/L，即可得到这时间内的产热量。用简化方法所获得数值与经典测算方法所得数值非常接近。","","N"],["1990-N45",10,"第6节 胰岛内分泌","对蛋白质代谢的作用",1990,45,"A","","下列哪种激素是蛋白质合成与贮存不可缺少的",[["A","胰高血糖素"],["B","胰岛素"],["C","胰多肽"],["D","生长抑素"],["E","氢化可的松"]],"B","胰高血糖素、生长抑素和氢化可的松（糖皮质激素的一种）均为促进蛋白质分解代谢为主的激素（ADE错）；胰岛素则促进蛋白质合成和储存，抑制蛋白质的分解（B对）；胰多肽（十版生理学P168）由胰腺的PP细胞分泌，可抑制胰液的分泌，对蛋白质的合成无明显影响（C错）。","","N"],["1990-N46",3,"第1节 心脏的泵血功能","第一心音",1990,46,"A","","第一心音的产生主要是由于",[["A","半月瓣关闭"],["B","主动脉瓣关闭"],["C","肺动脉瓣关闭"],["D","房室瓣开放"],["E","房室瓣关闭"]],"E","第一心音发生在心室收缩期，标志着心室收缩的开始，其产生主要与房室瓣突然关闭引起心室内血液和室壁的振动（E对），以及心室射血引起的大血管壁和血液涡流所发生的振动有关。第一心音在心尖搏动处（左第五肋间锁骨中线上）听诊时最清楚，其特点是音调较低，持续时间较长。","","N"],["1990-N47",5,"第7节 吸收","糖的吸收",1990,47,"A","","糖类、蛋白质和脂肪的消化产物大部分吸收的部位是在",[["A","十二指肠"],["B","空肠及回肠"],["C","十二指肠和空肠"],["D","十二指肠、空肠及回肠"],["E","回肠"]],"C","消化道不同部位的吸收能力和吸收速度是不同的，这主要取决于各部分消化道的组织结构，以及食物在各部位被消化的程度和停留的时间。食物在口腔和食管内一般不被吸收。食物在胃内的吸收也很少，胃仅能吸收乙醇和少量水。小肠是吸收的主要部位，糖类、蛋白质和脂肪的消化产物大部分在十二指肠和空肠被吸收（C对），回肠具有其独特的功能，即能主动吸收胆盐和维生素B₁₂。食物中大部分营养在到达回肠时，通常已被吸收完毕，因此回肠乃是吸收功能的储备部分。小肠内容物在进入大肠后可被吸收的物质已非常少。大肠可吸收的主要是水和盐类，大肠一般可吸收大肠内容物中80%的水和90%的 Na⁺和Cl⁻。","","N"],["1990-N48",2,"第4节 血型和输血原则","血型与红细胞凝集",1990,48,"A","","通常所说的血型是指",[["A","红细胞上受体的类型"],["B","红细胞表面特异凝集素的类型"],["C","红细胞表面特异凝集原的类型"],["D","血浆中特异凝集素的类型"],["E","血浆中特异凝集原的类型"]],"C","狭义地讲，血型指红细胞膜上特异性抗原（凝集原）的类型（C对），自1901年ABO血型系统被发现以来，至今已经发现近30种不同的红细胞血型系统，其中最重要的两种为“ABO血型系统”和“Rh血型系统”。广义地讲，血型还包括白细胞、血小板等各类血细胞的抗原类型，如人类白细胞抗原（HLA）。","","N"],["1990-N49",4,"第1节 肺通气","肺内压",1990,49,"A","","肺内压在下列哪一个呼吸时相中等于大气压",[["A","吸气初和呼气初"],["B","呼气初和吸气末"],["C","呼气初和呼气末"],["D","吸气初和呼气末"],["E","呼气末和吸气末"]],"E","肺泡（肺内压）与外界环境（大气压）之间的压力差是肺通气的直接动力，呼气末和吸气末（E对），肺内压与大气压相等，肺通气过程停止。","","N"],["1990-N50",4,"第1节 肺通气","肺容量",1990,50,"A","","对肺泡气分压变化起缓冲作用的肺容量是",[["A","补吸气量"],["B","深吸气量"],["C","余气量"],["D","功能余气量"],["E","补呼气量"]],"D","平静呼气末尚存留于肺内的气体量为功能余气量，功能余气量的生理意义是缓冲呼吸过程中肺泡气氧分压（PO₂）和二氧化碳分压（PCO₂）的变化幅度（D对）。由于功能余气量的稀释作用，吸气时，肺内PO₂不致突然升得太高，PCO₂不致降得太低；呼气时，则PO₂不会降得太低，PCO₂不会升得太高。这样，肺泡气和动脉血液的PO₂和PCO₂就不会随呼吸而发生大幅度的波动，有利于肺换气。","","N"],["1990-N60",4,"第3节 气体在血液中的运输","CO₂的运输形式",1990,60,"A","","在血液中运输的CO₂主要是",[["A","溶解状态的CO₂"],["B","H₂CO₃"],["C","氨基甲酰血红蛋白"],["D","血浆的HCO₃⁻"],["E","细胞内的HCO₃⁻"]],"D","血液中物理溶解的CO₂约占CO₂总运输量的5％，化学结合的约占95％。化学结合的形式主要是碳酸氢盐和氨基甲酰血红蛋白，前者约占CO₂总运输量的88％，而后者约占7％。从组织扩散入血的CO₂首先溶解于血浆，小部分溶解的CO₂与水结合生成H₂CO₃，H₂CO₃又解离成HCO₃⁻和H⁺。因为血浆中缺乏碳酸酐酶，所以这一反应过程较为缓慢，需要数分钟才能达到平衡，红细胞内则含有较高浓度的碳酸酐酶。因此，溶解于血浆中的绝大部分CO₂扩散入红细胞内，在红细胞内解离成HCO₃⁻和H⁺。十版生理学P155解释说“红细胞内生成的大部分HCO₃⁻顺浓度梯度通过红细胞膜HCO₃⁻-Cl⁻交换体扩散进入血浆”，按此解释本题的答案应为D。七版生理学P153却明确说明“溶解于血浆中的CO₂绝大部分扩散进入红细胞，在红细胞内以碳酸氢盐和氨基甲酰血红蛋白形式运输”按此解释本题的答案应为E。","","N"],["1990-N83",3,"第2节 心脏的电生理学及生理特性","兴奋在心脏内的传导",1990,83,"B","","心脏中传导速度最慢的是",[["A","窦房结"],["B","心房肌"],["C","房室结"],["D","希氏束"],["E","浦肯野纤维"]],"C","心肌的传导速度与心肌细胞的直径有关，直径较小的细胞，纵向电阻较大，电紧张电位的扩布距离较近，兴奋的传导速度较慢 。心房肌、心室肌和浦肯野细胞的直径都较大，末梢浦肯野细胞的直径最大，在某些动物，其直径可达70μm，因此兴奋的传导速度很快。窦房结P细胞的直径很小（5～10μm），传导速度很慢；房室交界结区细胞的直径更小，约0.3μm，传导速度最慢（C对）。","","N"],["1990-N84",3,"第2节 心脏的电生理学及生理特性","兴奋在心脏内的传导",1990,84,"B","","心脏中传导速度最快的是",[["A","窦房结"],["B","心房肌"],["C","房室结"],["D","希氏束"],["E","浦肯野纤维"]],"E","心肌的传导速度与心肌细胞的直径有关，直径较小的细胞，纵向电阻较大，电紧张电位的扩布距离较近，兴奋的传导速度较慢 。心房肌、心室肌和浦肯野细胞的直径都较大，末梢浦肯野细胞的直径最大，在某些动物，其直径可达70μm，因此兴奋的传导速度最快（E对）。窦房结P细胞的直径很小（5～10μm），传导速度很慢；房室交界结区细胞的直径更小，约0.3μm，传导速度最慢。","","N"],["1990-N89",3,"第3节 血管生理","血流量和血流速度",1990,89,"B","","血管中血流速度最快是在",[["A","微静脉"],["B","腔静脉"],["C","毛细血管"],["D","微动脉"],["E","主动脉"]],"E","主动脉的血流量最大，血流阻力最小，且距离心脏最近，直接接受心室射血，故血流速度最快（E对）。","","N"],["1990-N90",3,"第3节 血管生理","血流量和血流速度",1990,90,"B","","血管中血流速度最慢是在",[["A","微静脉"],["B","腔静脉"],["C","毛细血管"],["D","微动脉"],["E","主动脉"]],"C","在各类血管中，毛细血管的管壁最薄，口径最小，数量最多，总的横截面积最大，血流速度最慢（C对），有利于血液与组织进行物质交换，故毛细血管被称为交换血管。","","N"],["1990-N91",4,"第3节 气体在血液中的运输","Hb与O₂结合的特征",1990,91,"B","","血液氧饱合度",[["A","血红蛋白能结合氧的最大量"],["B","血红蛋白实际结合氧的量"],["C","血液氧含量占氧容量的百分比"],["D","单位时间内氧扩散的总量"],["E","溶解在血浆中的氧量"]],"C","在100ml血液中，Hb所能结合的最大O₂量称为Hb氧容量，而Hb实际结合的O₂量称为Hb氧含量。Hb氧含量与氧容量的百分比为Hb氧饱和度（C对）。在100％O₂饱和状态下，1g Hb可结合的最大O₂量为1.39ml，正常时红细胞中含有少量不能结合O₂的高铁Hb，因此1g Hb实际结合的O₂量低于1.39ml，通常按1.34ml计算。例如，血液中Hb浓度为15g/100ml时，Hb的氧容量为20.1ml/100ml（血液），如果Hb的氧含量是20.1ml，则Hb氧饱和度是100％，如果Hb氧含量是15ml，则Hb氧饱和度约75％。","","N"],["1990-N92",4,"第3节 气体在血液中的运输","Hb与O₂结合的特征",1990,92,"B","","血液氧含量",[["A","血红蛋白能结合氧的最大量"],["B","血红蛋白实际结合氧的量"],["C","血液氧含量占氧容量的百分比"],["D","单位时间内氧扩散的总量"],["E","溶解在血浆中的氧量"]],"B","在100ml血液中，Hb实际结合的O₂量称为Hb氧含量。由于血浆中溶解的O₂极少，可忽略不计，因此Hb氧含量可视为血氧含量（B对）。","","N"],["1990-N105",5,"第7节 吸收","糖的吸收",1990,105,"C","","葡萄糖和氨基酸的吸收途径",[["A","通过毛细血管吸收"],["B","通过毛细淋巴管吸收"],["C","两都兼有"],["D","两者均无"]],"A","经消化后的营养成分透过消化道黏膜进入血液或淋巴液的过程，称为吸收，葡萄糖和氨基酸主要经过毛细血管吸收入血液（A对），脂肪分解产物则可经毛细血管或毛细淋巴管吸收入血液或淋巴液。","","N"],["1990-N106",5,"第7节 吸收","脂肪的吸收",1990,106,"C","","脂肪分解产物在小肠的吸收途径",[["A","通过毛细血管吸收"],["B","通过毛细淋巴管吸收"],["C","两都兼有"],["D","两者均无"]],"C","脂肪的分解产物中，长链脂肪酸是脂溶性的，与一酰甘油在肠上皮细胞的内质网中重新合成脂肪，并与细胞中生成的载脂蛋白合成乳糜微粒，通过毛细淋巴管吸收（B对）；中、短链脂肪酸是水溶性的，与一酰甘油一起可直接进入血液被吸收（A对）。本题AB均对，正确答案为C。","","N"],["1990-N132",10,"第2节 下丘脑-垂体及松果体内分泌","促进生长",1990,132,"X","","对人体生长和发育有影响的激素有",[["A","生长激素"],["B","性激素"],["C","甲状腺激素"],["D","肾上腺素"]],"ABC","生长激素是最重要的促进生长发育的激素，生长激素能促进全身器官生长，尤其对骨骼、肌肉和内脏器官的生长发育有促进作用（A对）；性激素包括雄激素、雌激素和孕激素等，性激素能够促进生殖器官的生长发育（B对）；甲状腺激素能够促进神经系统的生长发育（C对）。肾上腺素（十版生理学P371）主要调节物质代谢和参与应急反应，对人体生长和发育无影响（D错）。","","N"],["1990-N143",3,"第3节 血管生理","影响组织液生成的因素",1990,143,"X","","影响组织液生成的因素有",[["A","毛细血管静脉端的压力"],["B","毛细血管壁的通透性"],["C","血浆胶体渗透压"],["D","淋巴回流"]],"ABCD","毛细血管静脉端的压力升高，即毛细血管后阻力增大，导致毛细血管血压升高，促进组织液的生成，反之则抑制组织液的生成（A对）。正常情况下，毛细血管壁对蛋白质几乎不通透，从而能维持正常的有效胶体渗透压。但在感染、烧伤、过敏等情况下，毛细血管的通透性异常增高，血浆蛋白可随液体渗出毛细血管，使胶体渗透压下降，组织胶体渗透压升高，有效滤过压增大，结果导致组织液生成增多而出现水肿（B对）。血浆胶体渗透压是限制组织液生成的主要力量。主要取决于血浆蛋白尤其是白蛋白的浓度。当血浆蛋白减少时，如营养不良或某些肝肾疾病，可因血浆胶体渗透压降低，导致组织液生成增加发生水肿（C对）。由于从毛细血管滤出的液体约有10%需经淋巴系统回流，故淋巴系统是否畅通可直接影响组织液回流。在某些病理情况下，如丝虫病患者的淋巴管被堵塞，使淋巴回流受阻，含蛋白质的淋巴液在组织间隙中聚集形成淋巴水肿（D对）。","","N"],["1990-N144",2,"第2节 血细胞生理","红细胞的生理特征",1990,144,"X","","下列情况，使血沉加快的是",[["A","血沉加快的红细胞置入正常血浆"],["B","正常红细胞置入血沉加快的血浆"],["C","血液中的白蛋白增加"],["D","血液中的球蛋白增加"]],"BD","决定血沉的因素不在红细胞本身，而在于血浆成分的变化，将正常红细胞置入血沉加快的血浆，红细胞的血沉将加快（B对）。血浆中纤维蛋白原、球蛋白（D对）及胆固醇含量增高时，可加速红细胞叠连和沉降；血浆中白蛋白、卵磷脂的含量增多时则可延缓叠连的发生，使沉降率减慢。","","N"],["1990-N145",1,"第1节 细胞膜的物质转运功能","跨细胞膜的物质转运",1990,145,"X","","细胞膜蛋白质的功能包括",[["A","物质转运功能"],["B","受体功能"],["C","酶的功能"],["D","免疫功能"]],"ABCD","膜蛋白的功能是多方面的。有些膜蛋白可作为“载体”而将物质转运进出细胞（A对）；有些膜蛋白能够作为受体参与细胞的信号转导，如离子通道型受体、G蛋白耦联受体、酶联型受体等（B对），其中酶联型受体本身还具有酶的活性（C对）；细胞的识别功能也决定于膜表面的蛋白质，这些蛋白常常是表面抗原，表面抗原能和特异的抗体结合，如人细胞表面有一种蛋白质抗原HLA，参与器官移植的免疫排斥反应（D对）。该考点考试大纲已不作要求。","","N"],["1990-N146",3,"第1节 心脏的泵血功能","心脏泵血功能的储备",1990,146,"X","","心力贮备包括",[["A","收缩期贮备"],["B","心率贮备"],["C","舒张期贮备"],["D","余血贮备"]],"ABC","心泵功能储备的大小主要决定于搏出量和心率能够提高的程度，因而心泵功能储备包括搏出量储备和心率储备两部分（B对）。搏出量是心室舒张末期容积和收缩末期容积之差，所以，搏出量储备又可分为收缩期储备和舒张期储备两部分（AC对），前者是通过增强心肌收缩能力和提高射血分数来实现的，而后者则是通过增加舒张末期容积而实现的。","","N"],["1990-N147",5,"第4节 小肠内消化","缩胆囊素",1990,147,"X","","胆囊收缩素的主要生理作用有",[["A","抑制HCO₃⁻分泌"],["B","促进肝胆汁分泌"],["C","引起胰岛素释放"],["D","促进胰酶分泌"]],"BCD","胆囊收缩素又称缩胆囊素，由小肠黏膜I细胞分泌。其生理功能极为广泛及多样化，且大部分功能与促胰液素（1998N11A和2010N12A）一致，七、八、九、十版生理学教材提及的功能包括：舒血管作用（七版生理学P170）、促进胃蛋白酶原分泌（七版生理学P176）、促进胰腺外分泌部组织的生长（十版生理学P168）、舒张食管下括约肌（十版生理学P171）、抑制胃的运动，延缓胃排空（十版生理学P168、七版生理学P180）、促进或抑制（为主）胃酸的分泌、促进胰酶分泌（十版生理学P181）（D对）、引起胆囊收缩，促进胆汁排出（十版生理学P181）、促进胆汁分泌（十版生理学P182）（B对）、促进小肠液分泌（十版生理学P183）、促进胰岛素分泌（十版生理学P377）（C对）、促进胰高血糖素分泌（十版生理学P378）、促进胰HCO₃⁻分泌（七版生理学P170 表6-3）（A错）、抑制食管-胃括约肌收缩（七版生理学P170 表6-3）、刺激小肠平滑肌收缩、促进小肠运动（七版生理学P170 表6-3）等等。","","N"],["1990-N148",2,"第3节 生理性止血","纤维蛋白的生成",1990,148,"X","","血清与血浆的区别在于前者",[["A","缺乏纤维蛋白原"],["B","增加了血小板释放的物质"],["C","缺乏某些凝血因子"],["D","含有大量的清蛋白"]],"ABC","血液凝固后1～2小时，因血凝块中的血小板激活，使血凝块回缩，释出的淡黄色液体称为血清，血清是血液发生凝血后的产物，清蛋白（白蛋白）并不参与凝血过程，二者的清蛋白含量没有差别（D错）。","","N"],["1991-N1",1,"第3节 细胞的电活动","动作电位的概念及特点",1991,1,"A","","神经细胞动作电位的主要组成是",[["A","阈电位"],["B","锋电位"],["C","负后电位"],["D","正后电位"],["E","局部电位"]],"B","以神经细胞为例，当受到一个有效刺激时，其膜电位从-70mV逐渐去极化到阈电位水平，此后迅速上升至+30mV，形成动作电位的升支（去极化），随后又迅速下降至接近静息电位水平，形成动作电位的降支（复极化）。两者共同形成尖峰状电位变化，称为锋电位。锋电位是动作电位的主要部分（B对），锋电位之后包括膜电位低幅、缓慢波动的后电位。","","N"],["1991-N2",4,"第4节 呼吸运动的调节","CO₂、H⁺、O₂对呼吸运动的调节",1991,2,"A","","在动脉血CO₂分压轻度升高而引起每分通气量增加的反应中，下列哪种结构起的作用最重要",[["A","颈动脉体化学感受器"],["B","主动脉体化学感受器"],["C","肺牵张感受器"],["D","肺血管化学感受器"],["E","延髓化学感受器"]],"E","CO₂刺激呼吸运动有两条途径，即刺激中枢化学感受器或外周化学感受器，其中中枢化学感受器发挥主要的作用。中枢化学感受器位于延髓中，又称延髓化学感受器（E对）。","","N"],["1991-N3",4,"第3节 气体在血液中的运输","氧解离曲线",1991,3,"A","","正常人动脉血液中血红蛋白的氧饱和度为",[["A","100%"],["B","97%"],["C","87%"],["D","77%"],["E","67%"]],"B","正常人动脉血液中血红蛋白的氧饱和度约为97.4%（B对），混合静脉血液中血红蛋白的氧饱和度约为75%。","","N"],["1991-N4",4,"第1节 肺通气","肺通气的动力",1991,4,"A","","肺通气的动力来自",[["A","肺的舒缩运动"],["B","肺的弹性和回缩"],["C","呼吸肌的舒缩"],["D","肺内负压的周期性变化"],["E","肺内压和胸内压之差"]],"C","肺通气是气体流动进出肺的过程，要实现肺通气，必须在肺泡与外界环境之间存在一定的压力差。在一定的海拔高度，大气压是相对恒定的，因此肺泡与外界环境之间的压力差是由肺泡内的压力（肺内压）决定的。肺内压的高低取决于肺的扩张和缩小，但肺自身并不具有主动扩张和缩小的能力，其扩张和缩小依赖于呼吸肌的收缩和舒张引起的胸廓运动。因此，由肺内压的变化建立的肺泡与外界环境之间的压力差是肺通气的直接动力，而呼吸肌的舒缩活动（C对）引起的节律性呼吸运动则是肺通气的原动力。","","N"],["1991-N5",4,"第1节 肺通气","弹性阻力和顺应性",1991,5,"A","","以下关于肺泡表面活性物质的描述，哪一项是错误的",[["A","维持肺泡的扩张状态"],["B","降低肺泡表面张力"],["C","稳定肺泡容积"],["D","降低肺的顺应性"],["E","防止毛细血管内液体滤入肺内"]],"D","由于肺表面活性物质可以降低肺泡表面张力，肺泡表面张力又是肺弹性阻力的主要来源，故肺表面活性物质可以减少肺的弹性阻力。而弹性阻力与顺应性在数值上互为倒数，所以肺表面活性物质可以增加肺的顺应性（D错，为本题正确答案）。","","N"],["1991-N6",5,"第4节 小肠内消化","胰液的性质、成分和作用",1991,6,"A","","胰蛋白酶原转变为胰蛋白酶的激活物是",[["A","Cl⁻"],["B","HCl"],["C","肠致活酶（肠激酶）"],["D","内因子"],["E","Ca²⁺"]],"C","胰蛋白酶原本身没有活性，在小肠中通过肠致活酶（肠激酶）的作用（C对），转变为有活性的胰蛋白酶。HCl主要激活胃蛋白酶原，对胰蛋白酶原也有激活作用，故B选项也可认为是正确的。内因子、Cl⁻ 、Ca²⁺均与胰蛋白酶原的激活无关。","","N"],["1991-N20",10,"第4节 甲状旁腺、维生素D与甲状腺C细胞内分泌","对肾脏的作用",1991,20,"A","","PTH的作用为抑制",[["A","溶骨"],["B","肾小管对磷的重吸收"],["C","肠吸收钙"],["D","1，25-（OH）₂D₃的形成"],["E","腺苷酸环化酶活性"]],"B","PTH（甲状旁腺激素）的靶器官主要是肾与骨，PTH与靶细胞的PTH受体结合后，激活腺苷酸环化酶（AC）（E错）和磷脂酶C（PLC），经AC-cAMP和PLC-IP₃/DG信号转导通路而产生调节作用（升血钙和降血磷）：①对肾脏的作用，一方面PTH可以促进肾远曲小管和集合管重吸收Ca²⁺，减少钙的排泄，升高血钙。另一方面PTH抑制近端和远端小管对磷的重吸收（B对），促进磷的排泄，降低血磷。此外，PTH还可激活肾近端小管细胞线粒体中的1α-羟化酶，激活25-OH-D₃转变为生物活性更高的1，25-（OH）₂D₃（钙三醇）（D错），进而间接促进小肠黏膜上皮细胞吸收钙（C错）和磷；②对骨的作用，PTH可作用于破骨细胞，增强溶骨作用（A错），释放Ca²⁺和Pi，也可以作用于成骨细胞，增强成骨作用，沉积Ca²⁺和Pi。","","N"],["1991-N27",7,"第3节 肾小管和集合管的物质转运功能","葡萄糖和氨基酸的重吸收",1991,27,"A","","肾小球滤过的葡萄糖被重吸收的部位是",[["A","近曲小管"],["B","髓袢升支"],["C","髓袢降支"],["D","远曲小管"],["E","集合管"]],"A","肾重吸收葡萄糖的部位均在近端小管，特别是在近端小管的前半段即近曲小管（A对）被重吸收。说一下近端小管和近曲小管的关系：近端小管是与肾小囊相连，空间上离肾小体距离较近的肾小管，依其走行的曲直，又有曲部和直部之分，其中曲部即近端小管的前半段，又名近曲小管，直部为髓袢降支粗段（十版生理学P214 图8-1）。","","N"],["1991-N28",8,"第2节 躯体和内脏感觉","内脏痛",1991,28,"A","","内脏痛的主要特点是",[["A","刺痛"],["B","慢痛"],["C","定位不精确"],["D","必有牵涉痛"],["E","对牵拉不敏感"]],"C","定位不准确，这是内脏痛最主要的特点（C对），如腹痛时患者常不能说出所发生疼痛的明确位置，因为痛觉感受器在内脏的分布比在躯体稀疏得多。","","N"],["1991-N29",9,"第1节 神经系统功能活动的基本原理","抑制性突触后电位",1991,29,"A","","关于抑制性突触后电位（IPSP）的生产过程的描述，哪一项是错误的",[["A","突触前末梢去极化"],["B","Ca²⁺由膜外进入突触前膜内"],["C","突触小泡释放递质，并与突触后膜受体结合"],["D","突触后膜对K⁺、Cl⁻的通透性升高"],["E","突触后膜膜电位增大，引起突触后神经元发放冲动"]],"E","突触后膜在某种神经递质作用下产生的局部超极化电位变化称为抑制性突触后电位（IPSP）。抑制性突触后电位的产生过程：突触前神经元的兴奋传到末梢，突触前膜去极化（A对），当去极化达一定水平时，突触前膜中的电压门控钙通道开放，Ca²⁺从细胞外进入突触前末梢轴浆内（B对），导致轴浆内Ca²⁺浓度的瞬时升高，由此触发突触小泡出胞，并释放抑制性递质，作用于突触后膜受体（C对），使突触后膜的氯通道或钾通道开放，突触后膜对K⁺、Cl⁻的通透性升高（D对），K⁺外流或Cl⁻内流增加，引起外向电流，导致突触后膜膜电位增大（超极化），但并不能触发动作电位的形成，也就无法引起突触后神经元发放冲动（E错，为本题正确答案）。","","N"],["1991-N30",10,"第3节 甲状腺内分泌","促进生长发育",1991,30,"A","","影响神经系统的最重要的激素是",[["A","糖皮质激素"],["B","生长素"],["C","盐皮质激素"],["D","肾上腺素"],["E","甲状腺激素"]],"E","影响神经系统发育最主要的激素是甲状腺激素（TH）（E对），在胚胎期，TH能促进神经元的增殖和分化以及突起和突触的形成；促进胶质细胞的生长和髓鞘的形成，诱导神经生长因子和某些酶的合成，促进神经元骨架的发育等。","","N"],["1991-N31",11,"第2节 女性生殖功能及其调节","卵巢的生卵作用",1991,31,"A","","无排卵月经是由于缺少",[["A","雌激素"],["B","孕激素"],["C","雌激素和孕激素"],["D","卵泡刺激素"],["E","以上都不是"]],"E","黄体生成素（LH）是促进排卵的关键因素：初级卵母细胞由于周围的颗粒细胞分泌一种卵母细胞成熟抑制因子（OMI），使卵母细胞的成熟分裂停止于初级卵母细胞阶段。当LH峰出现时，高浓度的LH可抵消OMI的抑制作用，使初级卵母细胞恢复分裂，形成次级卵母细胞和第一极体。随即次级卵母细胞开始第二次成熟分裂，最后，次级卵泡逐渐发育为成熟卵泡并突出于卵巢表面，形成透明的卵泡小斑（排卵孔）。LH峰的出现还能促进卵泡细胞分泌孕激素和前列腺素，孕激素可激活纤溶酶、胶原酶、蛋白水解酶及透明质酸酶等，使卵泡壁溶解破裂，前列腺素可使卵泡壁肌上皮细胞收缩，这些作用都有助于卵细胞从排卵孔排出。故黄体生成素（LH）缺乏时，不能完成排卵过程，出现无排卵月经（E对）。","","N"],["1991-N73",5,"第3节 胃内消化","促进胃液分泌的主要因素",1991,73,"A","","下列哪一项不能促进胃酸分泌",[["A","促胰液素"],["B","酒精"],["C","咖啡因"],["D","糖皮质激素"],["E","低血糖"]],"A","能够影响胃液（胃酸）分泌的因素太多了，现将生理学七、八、十版教材提及的能够促进或抑制胃液分泌的因素总结如下：促进胃液分泌的因素包括进食（通过机械扩张或蛋白质消化产物肽和氨基酸的化学刺激）、ACh（迷走神经释放）、铃蟾素（蛙皮素）、组胺、促胃液素、Valosin（缬酪肽）、Ca²⁺、低血糖（E错）、咖啡因（咖啡、可口可乐、茶中含咖啡因）（C错）、酒精（B错）、肠泌酸素、糖皮质激素（D错）等；抑制胃液分泌的因素包括胃酸、脂肪、高张溶液、促胰液素（A对）、缩胆囊素、血管活性肠肽、生长抑素、表皮生长因子、抑胃肽等。","","N"],["1991-N74",2,"第2节 血细胞生理","血小板的数量和功能",1991,74,"A","","血小板减少导致皮肤出现出血斑点的主要原因是",[["A","血小板不易聚集成团"],["B","血小板释放的血管活性物质的量不足"],["C","不能修复和保持血管内皮细胞完整性"],["D","血凝块回缩障碍"],["E","以上都不是"]],"C","血小板可以黏附并融合到血管内皮中，从而维持血管内皮的完整性，血小板还可释放血管内皮生长因子和血小板源生长因子，促进血管内皮细胞、平滑肌细胞和成纤维细胞的增殖，也有利于受损血管的修复（C对）。","","N"],["1991-N75",3,"第2节 心脏的电生理学及生理特性","兴奋性的周期性变化与收缩活动的关系",1991,75,"A","","室性期前收缩之后出现代偿间歇的原因是",[["A","窦房结的节律性兴奋延迟发放"],["B","窦房结的节律性兴奋少发放一次"],["C","窦房结的节律性兴奋传出速度大大减慢"],["D","室性期前收缩时的有效不应期特别长"],["E","窦房结的一次节律性兴奋落在室性期前收缩的有效不应期中"]],"E","室性期前收缩是一种最常见的心律失常，是指心室肌的有效不应期后、下一次窦房结兴奋到达前，心室受到一次外来刺激，提前产生的一次收缩。期前收缩有其自身的有效不应期，当紧接在期前兴奋后的一次窦房结兴奋传导到心室时，如果正好落在期前兴奋的有效不应期内（E对），则此次正常下传的窦房结兴奋将不能引起心室的兴奋和收缩，即形成一次兴奋和收缩的“脱失”，须待再下一次窦房结的兴奋传来时才能引起兴奋和收缩。这样，在一次期前收缩之后往往会出现一段较长的心室舒张期，称为代偿间歇。","","N"],["1991-N76",3,"第1节 心脏的泵血功能","心室收缩的后负荷",1991,76,"A","","心室肌的后负荷是指",[["A","心房压力"],["B","快速射血期心室内压"],["C","减慢射血期心室内压"],["D","等容收缩期初心室内压"],["E","大动脉血压"]],"E","肌肉在收缩过程中所承受的负荷，称为后负荷。对心室肌来说，收缩过程中所承受的负荷为大动脉血压（E对）。与后负荷对应的概念是前负荷，前负荷是指肌肉在收缩前所承受的负荷，该负荷可以用心室舒张末期容积或心室舒张末期压力来表示。","","N"],["1991-N77",3,"第3节 血管生理","动脉血压的形成",1991,77,"A","","主动脉在维持舒张压中起重要作用，主要是由于主动脉",[["A","口径大"],["B","管壁厚"],["C","管壁有可扩张性和弹性"],["D","血流速度快"],["E","对血流的摩擦阻力小"]],"C","由于外周阻力的存在以及主动脉和大动脉管壁具有较大的可扩张性和弹性（C对），因此左心室一次收缩所射出的血液在心缩期内仅约1/3流至外周，其余约2/3暂时储存于主动脉和大动脉内，并使主动脉压升高。由于主动脉和大动脉的弹性储器作用，主动脉压升高的速度和幅度得到缓冲而达到适当的水平。心室舒张时，半月瓣关闭，射血停止，被扩张的主动脉和大动脉依其弹性回缩，将心缩期储存的那部分势能释放出来，并将血液继续推向外周，使主动脉压在心舒期仍能维持在较高水平。","","N"],["1991-N81",5,"第4节 小肠内消化","胆盐",1991,81,"B","","给狗静脉注射稀释的胆汁10ml，可引起",[["A","胰液和胆汁分泌都减少"],["B","胰液和胆汁分泌增加"],["C","胰液和胆汁分泌都不变"],["D","胰液分泌不变，胆汁分泌增加"],["E","胰液分泌增加，胆汁分泌不变"]],"D","胆汁含有胆盐，胆盐有刺激肝胆汁分泌的作用，但无促进胰液分泌的作用（D对）。","","N"],["1991-N82",5,"第3节 胃内消化","盐酸",1991,82,"B","","给狗十二指肠腔内注入0.5%盐酸50ml，可引起",[["A","胰液和胆汁分泌都减少"],["B","胰液和胆汁分泌都增加"],["C","胰液和胆汁分泌都不变"],["D","胰液分泌不变，胆汁分泌增加"],["E","胰液分泌增加，胆汁分泌不变"]],"B","盐酸是促胰液素分泌的最强刺激因素，促胰液素的主要作用是促进胰液分泌，对肝胆汁分泌也有一定刺激作用，故给狗十二指肠腔内注入盐酸时可引起胰液和胆汁分泌同时增加（B对）。","","N"],["1991-N97",2,"第1节 血液生理概述","血浆渗透压",1991,97,"C","","对维持血管内、外水平衡有重要作用的是",[["A","血浆与组织液的晶体渗透压"],["B","血浆的胶体渗透压"],["C","两者都是"],["D","两者都不是"]],"B","毛细血管壁是一种半透膜，分隔着血浆和组织间液，可以让低分子量的水和NaCl等晶体物质自由通过，但不允许高分子量的血浆蛋白质通过。由于水和晶体物质可自由通过毛细血管壁，以至于血浆与组织液中晶体物质的浓度几乎相等，它们形成的晶体渗透压也基本相等，故血浆和组织液的晶体渗透压对维持血管内、外水平衡基本不起作用（A错）。由于血浆蛋白不易通过毛细血管壁，故虽然血浆胶体渗透压低于血浆晶体渗透压，但在维持血管内、外水平衡中发挥重要作用（B对）。","","N"],["1991-N98",2,"第1节 血液生理概述","血浆渗透压",1991,98,"C","","对维持细胞内、外水平衡有重要作用的是",[["A","组织液的晶体渗透压"],["B","血浆的胶体渗透压"],["C","两者都是"],["D","两者都不是"]],"A","细胞膜是体内的一种半透膜，它将细胞内液和细胞外液隔开，并只让水分子自由透过膜内外，而Na⁺、Cl⁻等晶体物质则不易自由通过。因此，水在细胞内外的流通，受到离子所产生的晶体渗透压的影响。也因此，晶体渗透压对维持细胞内外水分的相对平衡起着重要作用（A对）。","","N"],["1991-N99",3,"第4节 心血管活动的调节","颈动脉窦和主动脉弓压力感受性反射",1991,99,"C","","颈动脉窦内压力升高时，可引起",[["A","动脉血压降低"],["B","心输出量减少"],["C","两者均有"],["D","两者均无"]],"C","颈动脉窦内含压力感受器，动脉血压升高时，压力感受器传入冲动增多，引起压力感受性反射增强，导致心迷走紧张加强，心交感紧张和交感缩血管紧张减弱，表现为心率减慢，心输出量减少（B对），外周阻力减小，动脉血压下降（A对）。本题AB均对，正确答案为C。","","N"],["1991-N100",3,"第4节 心血管活动的调节","颈动脉窦和主动脉弓压力感受性反射",1991,100,"C","","电刺激右侧迷走神经外周端，可引起",[["A","动脉血压降低"],["B","心输出量减少"],["C","两者均有"],["D","两者均无"]],"C","电刺激右侧迷走神经外周端，可使心率减慢，进而使心输出量减少（心输出量又称每分输出量，等于心率与每搏输出量的乘积）（B对）；心率减慢时，心室舒张期延长，从大动脉流向外周的血量增加，存留在主动脉内的血量减少，使舒张压明显降低（A对）。由于舒张期末主动脉内存留的血量减少，致使心缩期主动脉内血量减少，收缩压也相应降低（A对）。本题AB均对，正确答案为C。","","N"],["1991-N113",1,"第1节 细胞膜的物质转运功能","跨细胞膜的物质转运",1991,113,"X","","下列各种物质通过细胞膜的转运方式正确的说法为",[["A","O₂、CO₂和NH₃属于单纯扩散"],["B","葡萄糖进入红细胞膜属于主动转运"],["C","安静时细胞内K⁺向细胞外移动为易化扩散"],["D","Na⁺从细胞内到细胞外为主动转运"]],"ACD","O₂、CO₂、N₂、NH₃等气体分子都是以单纯扩散的形式进行跨膜转运（A对）。葡萄糖主要有两种转运方式，包括红细胞、脑细胞等在内大多数种类的细胞通过经载体中介的易化扩散实现葡萄糖的转运（B错）；而小肠黏膜上皮细胞和近端肾小管上皮细胞则是以继发性主动转运实现葡萄糖的转运。安静时细胞内的钾离子通过钾离子通道以易化扩散的形式向细胞外移动（C对），这种钾离子外向流动是细胞产生静息电位的离子基础。Na⁺从细胞内到细胞外为逆浓度梯度和电位梯度的转运过程，由钠泵介导，为原发性主动转运（D对）。","","N"],["1991-N114",1,"第1节 细胞膜的物质转运功能","钠-钾泵",1991,114,"X","","钠泵的生理作用是",[["A","逆浓度差将细胞内的Na⁺移出膜外，同时将细胞外的K⁺移入膜内"],["B","阻止水分进入细胞"],["C","建立离子势能贮备"],["D","是神经、肌肉组织具有兴奋性的离子基础"]],"ABCD","在哺乳动物，细胞膜上的钠泵不断逆浓度差将细胞内的Na⁺移出膜外（A对），同时将细胞外的K⁺移入膜内，维持细胞膜两侧Na⁺和K⁺的浓度差，对维持细胞的正常功能具有重要作用：①维持细胞内代谢所需的高K⁺环境；②阻止水分进入细胞（B对），维持细胞内渗透压和细胞容积；③形成细胞内高K⁺细胞外高Na⁺的离子分布，构成神经、肌肉等组织电活动的离子基础（D对）；④为继发性主动转运建立离子势能贮备（C对）等。","","N"],["1991-N115",9,"第1节 神经系统功能活动的基本原理","神经递质的概念",1991,115,"X","","属于神经递质的是",[["A","γ-氨基丁酸"],["B","5-羟色氨酸"],["C","5-羟色胺"],["D","多巴胺"]],"ACD","神经递质是指由突触前神经元合成并在末梢处释放，能特异性作用于突触后神经元或效应细胞的受体，并产生一定效应的信息传递物质。还有一类物质与神经递质类似，但它不在神经元之间直接起信息传递作用，而是增强或削弱递质的信息传递效应，这类物质为神经调质。γ-氨基丁酸是脑内主要的抑制性递质（十版生理学P298）（A对）。5-羟色胺是一种单胺类神经递质（十版生理学P296）（C对）。5-羟色氨酸是一种氨基酸类物质，为5-羟色胺的前体物质，有助于提高5-羟色胺水平，对5-羟色胺的信息传递起调节作用，因此它是一种神经调质（B错）。多巴胺与5-羟色胺一样是单胺类神经递质（十版生理学P296），是黑质-纹状体通路的神经递质（D对）。","","N"],["1991-N148",9,"第2节 神经系统的感觉分析功能","感觉投射系统",1991,148,"X","","网状结构上行激活系统",[["A","可由传递冲动到丘脑的感觉神经元的侧支所激活"],["B","将冲动弥散性投射到大脑皮层各区"],["C","电刺激时，引起觉醒"],["D","经过多突触联系，将冲动传导到高级中枢"]],"ABCD","网状结构是指在脑干内除界限清楚、机能明确的神经细胞核团和神经纤维束外的神经细胞和神经纤维交织成网状的结构，分布在从脊髓到丘脑底部各个部位。网状结构可由传递冲动到丘脑的感觉神经元（即位于薄束核和楔束核内的传导特异感觉的第二级神经元）的侧支所激活（A对），并通过丘脑内非特异投射系统，将冲动弥散性投射到大脑皮层各区（B对）。网状结构接受特异感觉传导通路第二级神经元传入纤维的侧支投射，但由于网状结构是个多突触系统（D对），神经元的联系在此高度聚合，形成复杂的神经网络，使各种特异感觉的传入失去专一性，其主要功能在于通过非特异投射系统维持和改变大脑皮层的兴奋状态，从而起到激活和唤醒睡眠的作用（实验证明，刺激猫的中脑网状结构可将其从睡眠中唤醒）（C对），故又称网状结构上行激活系统。","","N"],["1991-N149",3,"第4节 心血管活动的调节","心脏的神经支配",1991,149,"X","","迷走神经",[["A","当受到刺激时，对血管收缩的强度几乎没有直接的影响"],["B","在神经干中含有传入和传出纤维"],["C","对于长跑运动员来说，在安静时对心脏的紧张性作用较明显"],["D","在神经干中含有副交感节后纤维"]],"ABC","迷走神经是12对脑神经中的第10对神经，与其他脑神经相比，迷走神经行程最长，分布也广，从运动器官到感觉器官从颈部到胸腔，直至腹腔，因其“远走他乡”，“容易迷路”，所以叫迷走神经。迷走神经为混合性神经，包含特殊内脏运动纤维（传出纤维）、一般内脏运动纤维（传出纤维）、一般内脏感觉纤维（传入纤维）、一般躯体感觉纤维（传入纤维）等四种纤维成分（B对）。其中一般内脏运动纤维即为副交感神经的节前纤维（D错），是迷走神经的主要成分，经神经节换元之后支配心脏、支气管、食管、胃、肝、胰、脾、小肠、部分大肠等胸腹腔脏器的平滑肌及腺体。由于支配胸腹腔脏器的副交感神经节前纤维走行于迷走神经内，我们经常把支配胸腹腔脏器的副交感神经称为迷走神经，如教材上会说“心脏受交感神经和迷走神经的双重支配”，更严谨的说法应为“心脏受交感神经和副交感神经的双重支配，其中副交感部分来自迷走神经的副交感纤维”。那是否意味着副交感神经是迷走神经的一部分呢，也不是，副交感神经除了在第十对脑神经迷走神经中走行的部分外，还有部分在动眼神经（第3对脑神经）、面神经（第7对脑神经）、舌咽神经（第9对脑神经）及盆神经中走行。因此，迷走神经与副交感神经之间并不对等，它们之间具有相互包含的关系。实际上，迷走神经是神经纤维的一种解剖学上的一种定义，而副交感神经是功能上的定义，与副交感神经具有功能上的对应关系的是交感神经，交感神经和副交感神经构成内脏神经系统（十版生理学P319），交感神经分布极为广泛，副交感神经分布则较为局限，以心血管系统为例，体内几乎所有的血管平滑肌都接受交感缩血管神经纤维的支配，只有少数器官如脑膜、唾液腺、胃肠外分泌腺和外生殖器的血管平滑肌副交感神经支配。因此，副交感神经（迷走神经）当受到刺激时，对血管收缩的强度几乎没有直接的影响（A对）。心脏受交感神经和迷走神经的双重支配，心交感神经和心迷走神经平时都具有紧张性，两者相互拮抗，共同调节心脏活动，但是在安静状态下，心迷走神经更占优势（C对）（不论普通人还是长跑运动员）。","","N"],["1991-N150",10,"","",1991,150,"X","","能直接刺激肾上腺皮质球状带使之分泌醛固酮的因素有",[["A","血K⁺浓度升高"],["B","肾素"],["C","血管紧张素Ⅰ"],["D","血管紧张素Ⅱ"]],"AD","醛固酮的分泌调节：①肾素-血管紧张素系统的调节：肾素是一种酸性蛋白酶（十版生理学P124），可激活血管紧张素原生成血管紧张素Ⅰ，后者再在血管紧张素转换酶的激活下生成血管紧张素Ⅱ，血管紧张素Ⅱ在血浆和组织中进一步酶解成血管紧张素Ⅲ，血管紧张素Ⅱ和血管紧张素Ⅲ均可促进肾上腺皮质球状带合成和释放醛固酮（D对BC错）。②血K⁺和血Na⁺的调节：血K⁺水平升高和血Na⁺水平降低均能刺激醛固酮的分泌（A对）。","","N"],["1991-N156",3,"第4节 心血管活动的调节","心脏的神经支配",1991,156,"X","","刺激心交感神经",[["A","使心脏起搏点细胞的舒张期去极化速率增加"],["B","使心功能曲线（纵坐标为心缩力或心室搏动，横坐标为心舒末期容积）右下移"],["C","使心肌的β受体激活"],["D","引起心缩力增强"]],"ACD","心交感神经节后纤维释放去甲肾上腺素，作用于心肌细胞膜中的β肾上腺能受体（C对），通过cAMP转导通路，激活细胞膜上的L型钙通道，增强Ca²⁺内流，再通过钙触发钙释放机制促进胞质内Ca²⁺浓度升高，从而使心肌收缩力增强（D对），心室功能曲线向左上方移位（B错）。心脏起搏点细胞即窦房结P细胞，舒张期去极化即4期自动去极化，在心交感神经的作用下，窦房结P细胞T型钙通道介导的4期钙内流增加，If型钠通道介导的4期钠内流也增加，导致4期自动去极化速率增加（A对）。","","N"],["1991-N157",4,"第2节 肺换气和组织换气","通气_血流比值",1991,157,"X","","在正常肺",[["A","每分钟肺通气量大于每分钟肺毛细血管血流量"],["B","在直立姿势时，通气/血流比值从肺底部向肺尖部增加"],["C","氧气在肺内的交换是被动弥散"],["D","当最大吸气时，死区的容积增加"]],"BCD","如人取直立位时，由于重力作用，从肺底部到肺尖部，肺泡通气量和肺毛细血管血流量都逐渐减少，但血流量的减少更为显著，所以肺尖部的VA/Q较大，可高达3.3，而肺底部的VA/Q较小，可低至0.63（B对）。混合静脉血流经肺毛细血管时，血液PO₂为40mmHg，比肺泡气的102mmHg低，O₂就在分压差的作用下由肺泡气向血液净扩散，使血液PO₂逐渐上升，最后接近肺泡气的PO₂，该扩散过程没有生物学机制的参与，无需代谢耗能，属于被动弥散过程（C对），也称单纯扩散（十版生理学P14）。最大吸气时，气管及支气管也随着肺扩张，解剖无效腔（死区）容积增加（D对）。每分钟肺通气量约为 4-6L，每分钟肺毛细血管血流量（心输出量）约为 5L 左右，正常情况下每分钟肺通气量与每分钟肺毛细血管血流量是相匹配的，即通气/血流比值约为 0.84，并非肺通气量大于肺毛细血管血流量（A错）。","","N"],["1991-N158",5,"第1节 消化生理概述","电生理特性",1991,158,"X","","消化道平滑肌基本电节律的特点是",[["A","在胃肠不收缩的情况下也可记录到基本电节律"],["B","消化道各个部位基本电节律的频率相同"],["C","基本电节律的产生是肌源性的"],["D","动作电位总是在基本电节律的基础上产生"]],"AD","基本电节律（即慢波）起源于广泛存在于胃体、胃窦及幽门部的环形肌和纵行肌交界处间质中的Cajal细胞（ICC），ICC既非神经细胞又非平滑肌细胞，是一种兼有成纤维细胞和平滑肌细胞特性的间质细胞，所以，基本电节律的产生既不是神经源性的，也不是肌源性的（C错）。另外一种理解是，消化道平滑肌基本电节律的产生不是源自神经（区别于骨骼肌），而是源自肌肉本身（的间质细胞），故其基本电节律的产生是肌源性的，所以也可以认为C是对的。基本电节律的频率变动在每分钟3～12次，随所在消化道部位的不同而异，人类胃平滑肌的慢波频率为每分钟3次，十二指肠为每分钟11～12次，回肠末端为每分钟8～9次（B错）。在基本电节律的基础上（D对），消化道平滑肌在受到各种理化因素的刺激后可进一步去极化，当达到阈电位（约-40mV）时，即可爆发动作电位。只有当基本电节律去极化到达到或超过机械阈或电阈时（十版生理学P166），肌细胞才会收缩，所以胃肠未收缩时，基本电节律也是存在的，只是未去极化到机械阈或电阈（A对）。","","N"],["1991-N159",7,"第2节 肾小球的滤过功能","肾小球毛细血管压",1991,159,"X","","急性失血时尿量减少的原因有",[["A","肾小球毛细血管血压下降"],["B","抗利尿激素分泌增加"],["C","血浆胶体渗透压降低"],["D","滤过膜通透性减低"]],"ABD","急性失血时，血量减少，血压下降，可反射性兴奋肾交感神经，引起肾入球小动脉强烈收缩，肾血流量减少，肾小球毛细血管血压下降（A对），肾小球滤过率降低，尿量生成减少。急性失血时，血量减少，对心肺感受器刺激减弱，经迷走神经传入至下丘脑的冲动减少，对血管升压素释放的抑制作用减弱或取消，故血管升压素释放增加，水重吸收增多，尿量减少（B对）。急性失血时丢失大量血浆蛋白，血浆胶体渗透压下降，有效滤过压和肾小球滤过率增加，尿量增多（C错）。急性失血时，交感神经兴奋、血管升压素、血管紧张素Ⅱ等因素均可引起系膜细胞收缩（十版生理学P215），降低滤过膜的通透性，进而降低肾小球滤过率，尿量减少（D对）。","","N"],["1991-N160",8,"第5节 平衡感觉","椭圆囊和球囊",1991,160,"X","","椭圆囊",[["A","是一个重力感受器"],["B","与半规管和耳蜗的内淋巴液相通"],["C","囊斑处的毛细胞的纤毛埋植在含有碳酸钙的耳石膜内"],["D","能引起肌紧张的反射性改变"]],"ABCD","椭圆囊是内耳前庭器官的三大组成部分之一（半规管、球囊、椭圆囊），囊内充满淋巴液，与半规管和耳蜗的内淋巴液相通（B对）。与耳蜗及其他前庭器官一样，椭圆囊的感受器细胞也是毛细胞，椭圆囊的毛细胞位于囊斑上，毛细胞的纤毛埋植于位砂膜（覆盖在上皮表面的一层厚的蛋白样胶质膜，其内含碳酸钙）（C对）。每个毛细胞的纤毛排列方向各不相同，当头的位置发生改变或囊斑受到不同方向的重力（A对）及变速运动刺激时，其中有的毛细胞兴奋，有的抑制，不同毛细胞综合活动的结果可反射性引起躯干和四肢肌紧张发生改变，从而维持身体的平衡（D对）。","","N"],["1992-N20",7,"第3节 肾小管和集合管的物质转运功能","肾小管和集合管重吸收量大并具有高度选择性",1992,20,"A","","正常情况下，肾小球滤液（原尿）在肾小管内被吸收的液体量占总量的",[["A","50%"],["B","60%"],["C","75%"],["D","90%"],["E","以上都不是"]],"E","正常人两肾生成的超滤液每天达180L，而终尿量仅1.5L左右，超滤液中的水分约99％被肾小管和集合管重吸收（E对）。此外，小管液中的葡萄糖和氨基酸全部被重吸收，Na⁺、Ca²⁺和尿素等可不同程度地被重吸收，而肌酐、H ⁺和K ⁺等则可被分泌到小管液中而排出体外。","","N"],["1992-N51",5,"第4节 小肠内消化","胆汁的作用",1992,51,"A","","关于胆汁的生理作用，下列哪项是错误的",[["A","胆盐、胆固醇和卵磷脂都可乳化脂肪"],["B","胆汁酸可与脂肪酸结合，促进脂肪酸的吸收"],["C","胆汁可促进脂溶性维生素的吸收"],["D","胆汁的消化酶可促进脂肪的消化"],["E","胆汁在十二指肠可中和一部分胃酸"]],"D","胆汁中含有水、胆盐、卵磷脂、胆固醇和胆色素等有机物和Na⁺、K⁺、Ca²⁺、HCO₃⁻等无机物，但是不含有消化酶（D错，为本题正确答案）。胆汁的作用包括三个方面：①促进脂肪的消化：胆汁中的胆盐、胆固醇和卵磷脂都可作为乳化剂乳化脂肪（A对），降低脂肪的表面张力，使脂肪乳化成微滴分散在水性的肠液中，因而可增加胰脂肪酶的作用面积，促进脂肪的分解消化；②促进脂肪和脂溶性维生素的吸收：在小肠绒毛表面覆盖有一层不流动水层，即静水层，脂肪分解产物不易穿过静水层到达肠黏膜表面而被上皮细胞吸收。肠腔中的脂肪分解产物，如脂肪酸（B对）、一酰甘油等均可掺入由胆盐聚合成的微胶粒中，形成水溶性的混合微胶粒，混合微胶粒则很容易穿过静水层而到达肠黏膜表面，从而促进脂肪分解产物的吸收。胆汁的这一作用，也有助于脂溶性维生素A、D、E、K的吸收（C对）；③中和胃酸及促进胆汁自身分泌：胆汁排入十二指肠后，可中和一部分胃酸（E对），进入小肠的胆盐绝大部分由回肠黏膜吸收入血，通过门静脉回到肝脏再形成胆汁，这一过程称为胆盐的肠-肝循环，返回到肝脏的胆盐有刺激肝胆汁分泌的作用，称为胆盐的利胆作用。","","N"],["1992-N52",4,"第2节 肺换气和组织换气","气体的分压差",1992,52,"A","","决定肺部气体交换方向的主要因素是",[["A","气体的溶解度"],["B","气体和血红蛋白的亲和力"],["C","气体分子量的大小"],["D","肺泡膜的通透性"],["E","气体的分压差"]],"E","气体分子不停地进行无定向的运动，当不同区域存在气压差时，气体分子将从气压高处向气压低处发生净转移，直至取得动态平衡，因此气体的分压差是气体扩散的动力，决定了气体扩散的方向（E对）。","","N"],["1992-N53",3,"第2节 心脏的电生理学及生理特性","兴奋在心脏内的传导",1992,53,"A","","心肌细胞中，传导速度最慢的是",[["A","窦房结"],["B","心房"],["C","房室交界"],["D","浦肯野纤维"],["E","心室"]],"C","心肌的传导速度与心肌细胞的直径有关，房室结细胞直径最小，局部电流沿细胞纵轴流动的纵向电阻最大，电紧张电位的扩布距离最近，因而兴奋的传导速度最慢（C对）。","","N"],["1992-N54",3,"第3节 血管生理","血管的功能性分类",1992,54,"A","","阻力血管主要指",[["A","大动脉"],["B","小动脉及微动脉"],["C","毛细血管"],["D","小静脉"],["E","大静脉"]],"B","阻力血管包括毛细血管前阻力血管和毛细血管后阻力血管两种。毛细血管前阻力血管包括小动脉和微动脉，其管径较细，对血流的阻力较大，是人体内最主要的阻力血管（B对）。毛细血管后阻力血管指微静脉，其管径较小，可以对血流产生一定的阻力，但与小动脉和微动脉相比，其阻力仅占血管系统总阻力的一小部分。","","N"],["1992-N55",3,"第3节 血管生理","重力对静脉压的影响",1992,55,"A","","关于静脉，下列叙述中哪一项是错误的",[["A","接受交感缩血管神经纤维的支配"],["B","管壁平滑肌在静脉被扩张时发生收缩"],["C","容纳全身血量的一半以上"],["D","回心血量不受体位变化的影响"],["E","静脉有较高的可扩张性，对血流阻力较小"]],"D","除毛细血管外，包括动脉、静脉、毛细血管前括约肌等在内的其他所有类型血管都受交感缩血管神经纤维的支配（A对）。在某些器官和组织，血管平滑肌经常保持一定的紧张性收缩，这一现象称为肌源性活动。静脉管壁平滑肌在静脉被扩张时，紧张性收缩活动加强（B对）。静脉又称容量血管，在安静状态下，静脉系统可以容纳全身60%～70%的循环血量（C对）。体位的改变会导致血液的重新分配，如人体从平卧位转为直立位时，大量血液积滞在下肢，回心血量减少（D错，为本题正确答案）。静脉有较高的可扩张性，对血流阻力较小（E对），因此血液从微静脉回流到右心房，压力仅降低约15mmHg。","","N"],["1992-N56",2,"第3节 生理性止血","生理性止血的基本过程",1992,56,"A","","关于生理性止血下列哪项是错误的",[["A","包括局部血管收缩、止血栓形成和血凝块的出现"],["B","血小板与止血栓形成和凝血块出现有关"],["C","局部血管反应持续时间较短"],["D","出血时间比凝血时间短"],["E","血小板减少时，止血和凝血时间均延长"]],"E","出血时间指在一定条件下，人为刺破皮肤后，血液从自然流出到自然停止所需的时间，这是反映毛细血管壁和血小板止血功能的常用测定试验，出血时间的常用测定方法有Duke法（正常值1～3min）、IVY法（正常值2～7min）和TBT法（正常值2.3～9.5min），凝血时间是指血液离开血管，在体外发生凝固的时间，它主要是测定内源性凝血途径中各种凝血因子是否缺乏，功能是否正常，或者是否有抗凝物质增多，凝血时间的常用测定方法有玻璃管法（正常值4～12min）、塑料管法（正常值10～19min）、硅管法（正常值15～32min）等，从正常值来看，出血时间明显比凝血时间短（D对）。血小板既参与了止血过程，也参与了凝血过程，但血小板减少时，一般止血时间延长而凝血时间正常，这是因为血小板在止血过程发挥了核心作用（血小板止血栓的形成），出血时间本身就是用来测定血小板止血功能的试验，血小板在凝血过程为凝血因子的激活提供磷脂表面，凝血过程中需要的血小板数量很少，血小板较少，一般并不会影响凝血时间的长短（E错，为本题正确答案）。引起局部血管反应的原因包括损伤性刺激反射性引起血管收缩、血管壁损伤引起血管肌源性收缩、黏附于损伤处的血小板释放5-HT、TXA₂等缩血管物质等，但是这些因素作用时间有限，局部血管反应持续时间较短（C对）。","","N"],["1992-N57",1,"第3节 细胞的电活动","阈电位",1992,57,"A","","阈电位是指",[["A","造成膜对钾离子通透性突然增大的临界膜电位"],["B","造成膜对钾离子通透性突然减小的临界膜电位"],["C","超极化到刚能引起动作电位时的膜电位"],["D","造成膜对钠离子通透性突然增大的临界膜电位"],["E","造成膜对钠离子通透性突然减小的临界膜电位"]],"D","引起细胞膜中钠离子通透性突然增大而触发动作电位的临界膜电位称为阈电位（D对），尽管适度的阈下刺激也能引起部分Na⁺通道开放，出现Na⁺内流而产生轻度的去极化，但由于达不到阈电位水平，其去极化效应很快就被增加的K⁺外流（去极化使K⁺化学驱动力增大）所抵消而出现复极化，而不是继续去极化。","","N"],["1992-N58",8,"第3节 视觉","晶状体变凸",1992,58,"A","","当睫状肌收缩时，可使",[["A","角膜曲度增大"],["B","角膜曲度减小"],["C","瞳孔缩小"],["D","晶状体曲度增大"],["E","晶状体曲度减小"]],"D","当眼视近物时，可反射性地引起睫状肌收缩，导致连接于晶状体囊的悬韧带松弛，晶状体因其自身的弹性而向前和向后凸出，曲度变大（D对E错）。对于特定的个体来说，角膜曲度是固定值，不能调节（AB错）。瞳孔缩小是由瞳孔括约肌（虹膜环形肌）收缩引起（C错）。","","N"],["1992-N59",9,"第4节 神经系统对内脏活动、本能行为和情绪的调节","副交感神经系统的功能",1992,59,"A","","下列哪项属于副交感神经的作用",[["A","瞳孔扩大"],["B","糖原分解增加"],["C","逼尿肌收缩"],["D","骨骼肌血管舒张"],["E","消化道括约肌收缩"]],"C","大多数副交感神经的节后纤维释放的递质是乙酰胆碱（少数节后纤维释放肽类和嘌呤类递质），因此副交感神经兴奋的症状即为M型或N型胆碱能受体被激活的症状。副交感神经兴奋时，作用于虹膜环行肌（又称瞳孔括约肌）的M受体使虹膜环行肌收缩，瞳孔缩小（A错）。作用于膀胱逼尿肌的M受体使逼尿肌收缩（C对）。作用于消化道括约肌的M受体使消化道括约肌舒张（E错）。交感神经系统兴奋时，可通过激活β₂受体促进糖原的分解增加（B错）。骨骼肌血管确实存在M型胆碱能受体，也接受乙酰胆碱（ACh）支配，可引起骨骼肌血管舒张，但此处释放ACh的是交感神经，而不是副交感神经（D错）。","","N"],["1992-N60",10,"第6节 胰岛内分泌","对蛋白质代谢的作用",1992,60,"A","","下列哪种激素是蛋白质合成与贮存所不可缺少的",[["A","胰高血糖素"],["B","胰多肽"],["C","胰岛素"],["D","生长抑素"],["E","氢化可的松"]],"C","胰高血糖素、生长抑素和氢化可的松（糖皮质激素的一种）均为促进蛋白质分解代谢为主的激素（ADE错）；胰岛素则促进蛋白质合成和储存，抑制蛋白质的分解（C对）；胰多肽（十版生理学P168）由胰腺的PP细胞分泌，可抑制胰液的分泌，对蛋白质的合成无明显影响（B错）。","","N"],["1992-N61",1,"第3节 细胞的电活动","细胞兴奋后兴奋性的变化",1992,61,"A","","神经纤维中相邻两个锋电位的时间间隔至少应大于其",[["A","相对不应期"],["B","绝对不应期"],["C","超常期"],["D","绝对不应期加相对不应期"],["E","低常期"]],"B","在神经细胞或骨骼肌细胞，由于绝对不应期的长短正好对应于锋电位发生的时期。在锋电位升支期间，大部分Na⁺（或Ca²⁺）通道已处于激活状态，不存在再激活的问题，在锋电位降支期间，大部分Na⁺（或Ca²⁺）通道处于失活状态，不可能再次接受刺激而被激活，因而在整个锋电位期间，细胞的兴奋性才为零，无论给予多强的刺激，也不能使细胞再次兴奋，这一段时间称为绝对不应期。而在绝对不应期之后，兴奋性逐渐恢复，受刺激后可发生兴奋。故相邻两次兴奋，即相邻两个锋电位的时间间隔至少应大于其绝对不应期（B对）。","","N"],["1992-N62",1,"第3节 细胞的电活动","钠泵的生电作用",1992,62,"A","","人工增加离体神经纤维浸浴液中K⁺浓度，静息电位的绝对值将",[["A","不变"],["B","增大"],["C","减小"],["D","先增大后减小"],["E","先减小后增大"]],"C","增加细胞外K⁺浓度，细胞内外K⁺浓度差减小（细胞内液K⁺浓度由细胞外液的39倍变成不到39倍了），K⁺所受到的由内向外的浓度差驱动力减小，K⁺外流减少，K⁺平衡电位减小，静息电位也相应减小”（C对）。","","N"],["1992-N63",9,"第1节 神经系统功能活动的基本原理","突触后神经元动作电位的产生",1992,63,"A","","神经细胞兴奋时，首先产生扩布性动作电位的部位是",[["A","树突"],["B","胞体"],["C","轴突"],["D","始段"],["E","轴突末梢"]],"D","动作电位并不是首先发生在胞体，而是发生在运动神经元和中间神经元的轴突始段，或是感觉神经元的轴突始段（D对）或第一个郎飞结处。这是因为电压门控钠通道在轴突始段密度较大，而在胞体和树突膜中则很少分布（十版生理学P290）。","","N"],["1992-N64",7,"第3节 肾小管和集合管的物质转运功能","集合管",1992,64,"A","","肾脏维持体内水平衡的功能，主要靠调节下列哪项活动来实现",[["A","肾小球滤过量"],["B","远曲小管与髓袢的重吸收水量"],["C","集合管的重吸收水量"],["D","肾小管的分泌功能"],["E","近曲小管的重吸收水量"]],"C","肾脏维持水平衡的功能，主要靠调节远曲小管（九版P245、十版P231认为只有集合管）和集合管的重吸收水量来实现（C对）：当体内水过多时，血浆晶体渗透压降低，抗利尿激素的释放减少，使远曲小管和集合管对水的通透性降低（九版P245认为只有集合管），导致水的重吸收减少；当体内缺水时，血浆晶体渗透压升高，抗利尿激素的释放增多，远曲小管（九版P245、十版P231认为只有集合管）和集合管对水的通透性增加，水的重吸收也增加。","","N"],["1992-N65",0,"第5节 机体生理功能的调节","自身调节",1992,65,"A","","下述情况中，属于自身调节的是",[["A","人在过度通气后呼吸暂停"],["B","动脉血压维持相对恒定"],["C","体温维持相对恒定"],["D","血糖水平维持相对恒定"],["E","平均血压在一定范围内升降时，肾血流量维持相对恒定"]],"E","机体对各种生理功能活动的调节方式有3种：神经调节、体液调节和自身调节。其中自身调节是指组织细胞不依赖于神经或体液因素，自身对环境刺激发生的一种适应性反应。机体的许多生理功能活动均涉及自身调节：如调节肾血流量的肌源性自身调节（E对）和管-球反馈（十版生理学P216）、尿生成过程中的渗透性利尿和球-管平衡（十版生理学P226）、局部组织的代谢性自身调节、脑血流量的肌源性自身调节（十版生理学P132）、心肌骨骼肌的异长自身调节（十版生理学P83）以及内分泌系统存在的大量自身调节等等。但目前为止只考过肾血流的肌源性自身调节（1992N65A，1999N1A）和脑血流的肌源性自身调节（2012N121B）。人在过度通气后呼吸暂停，是因为过度通气时，肺通气量增加，呼出的CO₂增多，血液中PCO₂下降，呼吸中枢因缺少足够的CO₂刺激而受到抑制造成的，属于化学感受器介导的神经调节（A错）。动脉血压维持相对恒定，主要与心血管系统的压力感受性反射有关，为典型的神经调节（B错）。体温维持相对恒定，依赖于体温调节中枢控制下的皮肤血流量、发汗、代谢水平的改变等等，也属于典型的神经调节（C错）。维持血糖水平恒定最重要的因素是胰岛素，胰岛素对血糖的调节属于体液调节（D错）。","","N"],["1992-N66",7,"第2节 肾小球的滤过功能","肾小球滤过率和滤过分数",1992,66,"A","","滤过分数是指",[["A","肾小球滤过率／肾血浆流量"],["B","肾血浆流量／肾血流量"],["C","肾血流量／肾血浆流量"],["D","肾小球滤过率／肾血流量"],["E","肾血流量／心输出量"]],"A","单位时间内（每分钟）两肾生成的超滤液量称为肾小球滤过率，单位时间内（每分钟）流经肾的血浆量为肾血浆流量，肾小球滤过率与肾血浆流量的比值称为滤过分数（A对）。","","N"],["1992-N87",3,"第3节 血管生理","组织液的生成",1992,87,"B","","阻止液体从毛细血管滤出的是",[["A","血流速度"],["B","血浆胶体渗透压"],["C","血浆晶体渗透压"],["D","毛细血管压"],["E","血液黏滞性"]],"B","阻止液体从毛细血管滤出的因素包括组织液静水压和血浆胶体渗透压（B对），促进液体从毛细血管滤出的因素包括毛细血管血压和组织液胶体渗透压。","","N"],["1992-N88",7,"第5节 尿生成的调节","血浆晶体渗透压",1992,88,"B","","调节ADH分泌的主要是",[["A","血流速度"],["B","血浆胶体渗透压"],["C","血浆晶体渗透压"],["D","毛细血管压"],["E","血液黏滞性"]],"C","ADH（antidiuretic hormone）即抗利尿激素，也称血管升压素，由下丘脑视上核和室旁核神经元合成。Na⁺和Cl⁻形成的晶体渗透压是调节血管升压素分泌的最重要因素（C对）：大量出汗、严重呕吐或腹泻等情况可引起机体失水多于溶质丧失，使体液晶体渗透压升高，可刺激血管升压素的分泌，通过肾小管和集合管增加对水的重吸收，使尿量减少，尿液浓缩；相反，大量饮水后，体液被稀释，血浆晶体渗透压降低，引起血管升压素释放减少或停止，肾小管和集合管对水的重吸收减少，尿量增加，尿液稀释。","","N"],["1992-N89",4,"第2节 肺换气和组织换气","通气_血流比值",1992,89,"B","","测定肺换气效率的较好指标是",[["A","潮气量"],["B","肺活量"],["C","时间肺活量"],["D","通气/血流比值"],["E","肺扩散容量"]],"D","通气/血流比值是指每分钟肺泡通气量（VA）和每分钟肺血流量（Q）之间的比值（VA/Q）。正常成年人安静时，VA约为4.2L/min，Q约为5L/min，因此，VA/Q约为0.84。如果VA/Q比值增大，就意味着通气过剩，血流相对不足，部分肺泡气体未能与血液气体充分交换，致使肺泡无效腔增大。反之，VA/Q比值下降，则意味着通气不足，血流相对过多，部分血液流经通气不良的肺泡，混合静脉血中的气体不能得到充分更新，犹如发生了功能性动-静脉短路。因此，VA/Q比值可作为衡量肺换气功能的指标（D对）。","","N"],["1992-N90",4,"第1节 肺通气","肺容量",1992,90,"B","","测定肺通气功能的较好指标是",[["A","潮气量"],["B","肺活量"],["C","时间肺活量"],["D","通气/血流比值"],["E","肺扩散容量"]],"C","肺活量是反映了肺一次通气的最大能力，在一定程度上可作为肺通气功能的指标。但由于测定肺活量时不限制呼气的时间，所以不能充分反映肺组织的弹性状态和气道的通畅程度，即肺通气功能的好坏。例如，某些患者肺组织弹性降低或呼吸道狭窄，通气功能已经受到损害，但是如果延长呼气时间，所测得的肺活量是正常的。因此，提出了时间肺活量的概念，时间肺活量是指一次最大吸气后，第1秒内尽力尽快呼气所能呼出的最大气体量。肺组织弹性降低或呼吸道狭窄的患者肺活量可正常，但时间肺活量是下降的，时间肺活量不仅反映了肺活量的大小，而且反映了肺组织的弹性状态和气道的通畅程度，因此是评论肺通气功能的较好指标（C对）。","","N"],["1992-N105",1,"第1节 细胞膜的物质转运功能","单纯扩散",1992,105,"C","","氧由肺泡进入血液的方式是",[["A","易化扩散"],["B","主动转运"],["C","两者都是"],["D","两者都不是"]],"D","氧气（O₂）是脂溶性小分子物质，可以单纯扩散（D对）的形式通过肺泡细胞，实现肺泡与肺毛细血管血液之间的气体交换过程（肺换气）。本题AB均错，正确答案为D。","","N"],["1992-N106",1,"第1节 细胞膜的物质转运功能","易化扩散",1992,106,"C","","葡萄糖由血液进入脑细胞的方式是",[["A","易化扩散"],["B","主动转运"],["C","两者都是"],["D","两者都不是"]],"A","葡萄糖主要有两种转运方式，大多数种类的细胞通过经载体易化扩散实现葡萄糖的转运，如红细胞、脑细胞等（A对）；而小肠黏膜上皮细胞和近端肾小管上皮细胞则是以继发性主动转运实现葡萄糖的转运（P22）。","","N"],["1992-N107",10,"第2节 下丘脑-垂体及松果体内分泌","下丘脑调节激素",1992,107,"C","","下丘脑对生长激素分泌的调节因子是",[["A","下丘脑释放因子（或激素）"],["B","下丘脑释放抑制因子（或激素）"],["C","两者都是"],["D","两者都不是"]],"C","生长激素（GH）由腺垂体分泌，接受下丘脑调节肽的调节，下丘脑分泌的生长激素释放激素（GHRH）（A对）和生长激素抑制激素（GHIH）（B对）作用于腺垂体，前者促进生长激素的分泌，而后者抑制生长激素的分泌。本题AB均对，正确答案为C。","","N"],["1992-N108",10,"第2节 下丘脑-垂体及松果体内分泌","下丘脑调节激素",1992,108,"C","","下丘脑对促性腺激素分泌的调节因子是",[["A","下丘脑释放因子（或激素）"],["B","下丘脑释放抑制因子（或激素）"],["C","两者都是"],["D","两者都不是"]],"A","下丘脑-腺垂体-性腺形成分泌轴系，而调节腺垂体释放促性腺激素的下丘脑调节肽只有促性腺激素释放激素（GnRH/LHRH）（A对）","","N"],["1992-N146",3,"第3节 血管生理","影响静脉回心血量的因素",1992,146,"X","","如果紧闭声门用力呼气，胸膜腔内压将升高至100mmHg左右，可以引起下列哪些变化",[["A","右心室输出量增加"],["B","左心室输出量减少"],["C","体循环动脉压下降"],["D","心率减慢"]],"BC","紧闭声门用力呼气，胸内压升高到100mmHg左右，静脉回心血量急剧减少，心室前负荷减小，心脏搏出量减少，心输出量减少（B对A错）。搏出量减少时，收缩压和舒张压均下降（十版生理学P112），故体循环动脉压下降是正确的（C对）。血压下降使压力感受器传入冲动减少，压力感受性反射减弱，引起心率加快（十版生理学P123-P124）（D错）。","","N"],["1992-N147",5,"第4节 小肠内消化","胰液的性质、成分和作用",1992,147,"X","","下面关于胰腺功能的论述哪项是正确的",[["A","刺激迷走神经引起胰腺迅速分泌含酶较少的水样胰液"],["B","在交叉循环实验中，当向一只动物的十二指肠内灌注酸时，另一只动物发生胰液分泌"],["C","胰腺腺泡含有胰蛋白酶"],["D","能引起富含胰酶的胰液分泌的激素，也能引起胆囊收缩"]],"BD","胰腺腺泡含有的是胰蛋白酶原而不是胰蛋白酶，只有在小肠中通过肠激酶、酸、组织液等的作用，胰蛋白酶原才会转变为胰蛋白酶（C错）。在交叉循环试验中，向一只动物的十二指肠内灌注酸时，能刺激促胰液素的分泌，促胰液素通过体液途径使另一只动物发生胰液分泌（B对），该考点已过时。","","N"],["1992-N148",5,"第3节 胃内消化","内因子",1992,148,"X","","全胃切除术预计可导致下列问题",[["A","进食后由于水吸收过于迅速，使血液稀释"],["B","由于胃蛋白酶缺乏，使蛋白质吸收障碍"],["C","维生素B₁₂吸收障碍"],["D","脂肪吸收不良"]],"AC","胃是消化道中最膨大的部分，成年人胃的容量为1-2L，具有储存和初步消化食物的功能（十版生理学P171），食物在胃内的吸收很少，胃仅能吸收少量的水，其他大部分水在小肠（为主）和大肠内被吸收，全胃切除术后，进食的水未经过胃的储存直接排入小肠，导致水迅速被小肠吸收，血液被稀释（A对）。胃蛋白酶与胰蛋白酶在功能上是重叠的，即可将蛋白质分解成䏡、胨、多肽和游离氨基酸（十版生理学P172），胃蛋白酶缺乏时，其功能可以由胰蛋白酶替代，不会出现蛋白质吸收障碍（B错）。胃壁细胞可以分泌一种叫内因子的糖蛋白，内因子与维生素B₁₂结合，可防止维生素B₁₂被肠内水解酶破坏，全胃切除术后，内因子缺乏，维生素B₁₂失去保护因素而被肠内水解酶破坏，出现吸收障碍（C对）。脂肪的消化和吸收主要在小肠内进行，全胃切除术不会导致脂肪吸收不良（D错）。","","N"],["1992-N149",9,"第3节 神经系统对躯体运动的调控","运动传出通路",1992,149,"X","","下运动神经元损伤时",[["A","肌紧张降低"],["B","腱反射减弱或消失"],["C","肌萎缩明显"],["D","巴宾斯基征阳性"]],"ABC","临床上常将运动控制系统分为下、上运动神经元，下运动神经元是指脊髓运动神经元。脊髓运动神经元损伤时（如脊髓灰质炎），机体出现柔软性麻痹（软瘫），表现为牵张反射（包括腱反射和肌紧张）减弱或消失（AB对），肌肉松弛，并逐渐出现肌肉萎缩（C对），巴宾斯基征阴性（D错）等。","","N"],["1992-N150",3,"第3节 血管生理","血管的功能性分类",1992,150,"X","","一个器官的小动脉收缩的结果可能有",[["A","流经该器官的血流量减少"],["B","该器官血管床的毛细血管压增高"],["C","该器官动-静脉血氧分压差减小"],["D","该器官的淋巴回流率减小"]],"AD","小动脉为毛细血管前阻力血管的一种（另一种为微动脉），当一个器官的小动脉收缩时，管径变小，血流阻力增加，致使血流量减少（A对）。小动脉收缩，毛细血管前阻力增加，毛细血管前、后阻力的比值增大，毛细血管血压降低（B错），组织液生成减少。由于血流量减少，外周组织对单位体积血液的血氧利用率升高，使动-静脉血氧分压差增大（C错）。组织液和毛细淋巴管内淋巴液之间的压力差是促进组织液进入淋巴管的动力，小动脉收缩，毛细血管血压降低，组织液生成减少，导致淋巴生成减少（D对）。","","N"],["1992-N151",2,"第1节 血液生理概述","血浆渗透压",1992,151,"X","","下面关于血浆渗透压的概念，哪项正确",[["A","血浆总渗透压近似于0.9％NaCl溶液"],["B","血浆总渗透压主要是由Na⁺和Cl⁻形成的"],["C","血浆胶体渗透压约为25mmHg"],["D","血浆总渗透压阻止液体从毛细血管滤出"]],"ABC","渗透压与血浆渗透压相等的溶液称为等渗溶液，浓度为0.85%～0.9%的NaCl溶液为等渗溶液（八版生理学数据为 0.85%，九版生理学数据为 0.9%，临床上实际应用0.9%NaCl 注射液作为等渗溶液更多一些）（A对）。由血浆中的电解质、葡萄糖、尿素等小分子晶体物质所形成的渗透压叫晶体渗透压，而在小分子物质中约80%来自Na⁺和Cl⁻（B对）。血浆中虽含有大量蛋白质，但蛋白质分子量大，分子数量少，所产生的渗透压较小（相比较晶体物质形成的渗透压），大约只有3.3kPa或25mmHg（C对）。血浆总渗透压包括晶体渗透压和胶体渗透压两种（以前者为主），只有胶体渗透压可以维持毛细血管内外的水平衡（D错），而晶体渗透压维持的是细胞内外的水平衡。","","N"],["1992-N152",10,"第4节 甲状旁腺、维生素D与甲状腺C细胞内分泌","概述",1992,152,"X","","参与钙磷代谢调节的激素有",[["A","甲状旁腺素"],["B","维生素D"],["C","降钙素"],["D","1，25-（OH）₂D₃"]],"ACD","甲状旁腺激素、降钙素及1，25-（OH）₂D₃均有调节钙磷代谢的作用（ACD对）。维生素D是1，25-（OH）₂D₃的前体物质，本身不具有调节钙磷代谢的作用（十版生理学P365）（B错）。","","N"],["1993-N1",10,"第3节 甲状腺内分泌","促进生长发育",1993,1,"A","","影响神经系统发育的最主要的激素是",[["A","糖皮质激素"],["B","生长激素"],["C","盐皮质激素"],["D","肾上腺素"],["E","甲状腺激素"]],"E","影响神经系统发育最主要的激素是甲状腺激素（TH）（E对），在胚胎期，TH能促进神经元的增殖和分化以及突起和突触的形成；促进胶质细胞的生长和髓鞘的形成，诱导神经生长因子和某些酶的合成，促进神经元骨架的发育等。","","N"],["1993-N2",2,"第1节 血液生理概述","血浆渗透压",1993,2,"A","","0.9％NaCl溶液和10％葡萄糖溶液对人细胞内液来说",[["A","两者都是等渗液"],["B","两者都是高渗液"],["C","两者都是低渗液"],["D","前者是低渗液，后者是高渗液"],["E","前者是等渗液，后者是高渗液"]],"E","此处的“正常血浆渗透压”在教材中未找到","","N"],["1993-N3",3,"第1节 心脏的泵血功能","心动周期",1993,3,"A","","心动周期中从房室瓣关闭到开放的时间约相当于",[["A","心房收缩期+心室等容收缩期"],["B","心房舒张期"],["C","心室收缩期"],["D","心室舒张期"],["E","心室收缩期+等容舒张期"]],"E","房室瓣的关闭与开放与心室的活动周期有关。心室的活动周期包括收缩期和舒张期，收缩期可分为等容收缩期和射血期，而射血期又可分为快速射血期和减慢射血期，舒张期可分为等容舒张期和心室充盈期，心室充盈期又可分为快速充盈期、减慢充盈期和心房收缩期。房室瓣关闭从等容收缩期开始：心室开始收缩后，心室内压力立即升高，当室内压升高到超过房内压时，即可推动房室瓣使之关闭，因而血液不会倒流入心房。但此时室内压尚低于主动脉压，因此半月瓣仍处于关闭状态，心室暂时成为一个封闭的心腔，从房室瓣关闭到主动脉瓣开启前的这段时期，心室的收缩不能改变心室的容积，称为等容收缩期。等容收缩期之后是射血期：当心室收缩使室内压升高至超过主动脉压时，半月瓣开放，这标志着等容收缩期结束而进入射血期，整个射血期房室瓣都是关闭的，以防止血液由心室流入心房。射血期之后是等容舒张期：射血后，心室开始舒张，室内压下降，主动脉内的血液向心室方向反流，推动半月瓣关闭；但此时室内压仍高于房内压，故房室瓣仍处于关闭状态，心室又暂时成为一个封闭的心腔，从半月瓣关闭至房室瓣开启前的这一段时间内，心室舒张而心室的容积并不改变，故称为等容舒张期。等容舒张期之后是快速充盈期：当室内压下降到低于房内压时，血液冲开房室瓣进入心室，心室便开始充盈。故从等容收缩期、射血期到等容舒张期，房室瓣都是关闭的，即从房室瓣关闭到开放的时间约相当于心室收缩期+等容舒张期（E对）。","","N"],["1993-N4",3,"第3节 血管生理","影响动脉血压的因素",1993,4,"A","","心输出量增加或外周阻力减小对动脉血压的影响是",[["A","前者会使收缩压升高，后者会使舒张压降低"],["B","前者会使舒张压升高，但不影响收缩压；后者会使舒张压降低，但不影响收缩压"],["C","脉搏压降低"],["D","平均动脉压升高"],["E","以上都不对"]],"A","心输出量增加时，收缩压和舒张压均升高，收缩压升高更明显，脉压增大；外周阻力减小时，收缩压和舒张压均下降，舒张压降低更明显，脉压增大（A对）。","","N"],["1993-N5",3,"第4节 心血管活动的调节","颈动脉窦和主动脉弓压力感受性反射",1993,5,"A","","当动脉血压骤降时可引起",[["A","窦神经、主动脉神经传入冲动增加，心交感神经紧张性增加"],["B","窦神经、主动脉神经传入冲动减少，心迷走神经紧张性增加"],["C","窦神经、主动脉神经传入冲动增加，心迷走神经紧张性增加"],["D","窦神经、主动脉神经传入冲动减少，心交感神经传出冲动增加"],["E","窦神经、主动脉神经传入冲动增加，心迷走神经传出冲动减少"]],"D","动脉血压骤降时，颈动脉窦和主动脉弓的压力感受器所受的机械牵张刺激减少，窦神经（颈动脉窦的传入神经）、主动脉神经（主动脉弓的传入神经）传入冲动减少，压力感受性反射减弱，导致心交感神经活动加强（D对），心迷走神经活动减弱。","","N"],["1993-N6",4,"第1节 肺通气","弹性阻力和顺应性",1993,6,"A","","肺泡表面活性物质减少将会使",[["A","肺弹性阻力减小"],["B","肺顺应性增大"],["C","肺泡内液体层表面张力减小"],["D","小肺泡内压大于大肺泡内压"],["E","肺毛细血管内液体不易渗出"]],"D","由于肺表面活性物质可以降低肺泡表面张力，肺泡表面张力又是肺弹性阻力的主要来源，故肺表面活性物质可以减少肺的弹性阻力。而弹性阻力与顺应性在数值上互为倒数，所以肺表面活性物质可以增加肺的顺应性。当肺泡表面活性物质减少时，肺的表面张力增大（C错），肺的弹性阻力增加（A错），肺的顺应性减小（B错）。","","N"],["1993-N7",4,"第3节 气体在血液中的运输","氧解离曲线",1993,7,"A","","氧离曲线表示",[["A","血氧含量与空气中的氧分压的关系曲线"],["B","血红蛋白的氧含量与血液氧分压的关系曲线"],["C","氧分压与血红蛋白氧饱和度的关系曲线"],["D","溶解的血红蛋白与血液中氧分压的关系曲线"],["E","血液中氧的溶解度与氧分压的关系曲线"]],"C","氧解离曲线是表示血液PO₂与Hb氧饱和度关系的曲线（C对），影响氧解离曲线的主要因素包括血液pH和PCO₂、温度、红细胞内的2，3-二磷酸甘油酸、CO、以及Hb自身性质和含量等。","","N"],["1993-N8",5,"第3节 胃内消化","胃排空及其控制",1993,8,"A","","促使胃排空的原动力来源于",[["A","迷走神经兴奋引起胃排空"],["B","交感神经兴奋引起胃排空"],["C","食物在胃内的刺激引起胃的运动"],["D","食物在十二指肠的刺激引起胃排空"],["E","促胰液素和抑胃肽的刺激引起胃排空"]],"C","胃排空的原动力为胃平滑肌的收缩，而迷走神经兴奋（A）和食物在胃内的刺激（C）均能促进胃平滑肌的收缩。本题的标准答案给出的是C，可能与迷走神经兴奋往往因食物在胃内的刺激引起，食物在胃内的刺激才是胃排空原动力产生的源头有关（食物在胃内的刺激→迷走神经兴奋→胃平滑肌的收缩）。","","N"],["1993-N9",6,"第1节 能量代谢","间接测热法",1993,9,"A","","呼吸商数值不同表示",[["A","耗氧量不同"],["B","产热量不同"],["C","氧化的营养物质不同"],["D","代谢水平不同"],["E","以上都不对"]],"C","呼吸商是指一定时间内机体呼出的CO₂量和吸入的O₂量的比值，由于不同营养物质中所含C、H和O元素的比例不同，因此不同营养物质氧化时所需要的O₂量和产生的CO₂量各不相同，即不同营养物质的呼吸商各不相同：糖氧化时的呼吸商等于1.00，蛋白质和脂肪氧化时的呼吸商分别为0.80和0.71。因此，呼吸商数值不同表示氧化的营养物质不同（C对）。","","N"],["1993-N10",7,"第2节 肾小球的滤过功能","肾小球滤过率和滤过分数",1993,10,"A","","肾小球滤过率是指",[["A","每分钟滤过的血液量"],["B","每分钟两侧肾形成的超滤液量"],["C","每分钟每侧肾形成的超滤液量"],["D","每分钟每侧肾形成的超滤液量与肾血浆流量之比"],["E","每分钟两侧肾形成的超滤液量与肾血浆流量之比"]],"B","每分钟两肾生成的超滤液量称为肾小球滤过率（B对）。每分钟两侧肾形成的超滤液量与肾血浆流量之比为滤过分数（E错）。ACD选项的说法不存在。","","N"],["1993-N11",7,"第3节 肾小管和集合管的物质转运功能","肾小管和集合管重吸收量大并具有高度选择性",1993,11,"A","","正常情况下，每天由肾小管和集合管重吸收的液体量占肾小球滤过量的",[["A","50％～60％"],["B","60％～70％"],["C","70％～80％"],["D","80％～90％"],["E","99%"]],"E","正常人两肾生成的超滤液每天达180L，而终尿量仅1.5L左右，超滤液中的水分约99％被肾小管和集合管重吸收（E对）。此外，小管液中的葡萄糖和氨基酸全部被重吸收，Na⁺、Ca²⁺和尿素等可不同程度地被重吸收，而肌酐、H⁺和K⁺等则可被分泌到小管液中而排出体外。","","N"],["1993-N12",7,"第5节 尿生成的调节","概述",1993,12,"A","","抗利尿激素",[["A","是由神经垂体合成的一种激素"],["B","当血浆晶体渗透压升高时分泌增加"],["C","在循环血量显著减少时分泌减少"],["D","使远曲小管和集合管对水的通透性降低"],["E","大量应用时可使血管扩张"]],"B","抗利尿激素又称血管升压素，是由下丘脑视上核和室旁核神经元合成，经下丘脑-垂体束运输到神经垂体储存的多肽类激素，故神经垂体是抗利尿激素的储存部位，而不是合成部位（A错）。血浆晶体渗透压升高时，刺激位于下丘脑的渗透压感受器，引起抗利尿激素分泌增加（B对）。当循环血量减少时，静脉回心血量减少，对心肺感受器的刺激减弱，经迷走神经传入至下丘脑的冲动减少，对抗利尿激素释放的抑制作用减弱或取消，故抗利尿激素分泌增加（C错）。抗利尿激素有V₁和V₂两种受体，V₁受体分布于血管平滑肌，激活后可引起平滑肌收缩，血管收缩（E错），V₂受体主要分布在肾远端小管后段（远曲小管）（九版生理学P245、十版生理学P231认为只分布在集合管）和集合管上皮细胞，激活后使上皮细胞内含水孔蛋白AQP-2的小泡镶嵌到上皮细胞的顶端膜中，形成水通道，增加对水的通透性（D错）。","","N"],["1993-N13",7,"第5节 尿生成的调节","醛固酮的功能",1993,13,"A","","醛固酮",[["A","是由肾上腺皮质束状带分泌的一种激素"],["B","分泌调节的主要因素是ACTH"],["C","肾素-血管紧张素系统对其分泌调节的作用极微"],["D","血浆中Na⁺和K⁺浓度变化对其分泌的调节无作用"],["E","其生理作用是促进远曲小管和集合管对Na⁺的主动重吸收，同时促进K⁺的排出"]],"E","醛固酮是由肾上腺皮质球状带分泌的，而不是束状带分泌的（束状带分泌糖皮质激素）（A错），其主要作用于肾远曲小管和集合管的上皮细胞，增加K⁺的排泄和Na⁺、水的重吸收（E对）。醛固酮的分泌调节机制包括：①肾素-血管紧张素系统的调节：血管紧张素Ⅱ和血管紧张素Ⅲ可促进肾上腺皮质球状带细胞分泌醛固酮（C错）；②血K⁺和血Na⁺的调节：血K⁺水平升高和血Na⁺水平降低均能刺激醛固酮分泌（D错）；③应激性调节：生理情况下，ACTH（促肾上腺皮质激素）对醛固酮的分泌无明显影响，只有在应激反应时才会出现ACTH促进醛固酮分泌的情况（B错）。","","N"],["1993-N14",8,"第3节 视觉","晶状体变凸",1993,14,"A","","人眼的近点表示",[["A","视力"],["B","眼的折光能力"],["C","眼的调节能力"],["D","视杆细胞的功能"],["E","视锥细胞的功能"]],"C","在注视近物时，物体上各点发出的光从四面八方进入人眼后呈不同程度的辐射状，需要经过一定的调节才能在视网膜上形成准确清晰的物像，物体眼越近，进入人眼的光线就越发散，就越需要调节，因此可以用近点来表示人眼的调节能力的大小（C对）。视力又称为视敏度，是眼对物体细小结构的分辨能力（十版生理学P265）。眼的折光能力表示光线从一种媒介进入另一种媒介时发生折射的能力，折光能力最强的是角膜前表面（十版生理学P254）。视杆细胞的功能是昏暗环境中感受弱光刺激而引起暗视觉（十版生理学P260）。视锥细胞的功能是在强光条件下分辨物体的细微结构和颜色（十版生理学P262）。","","N"],["1993-N15",9,"第3节 神经系统对躯体运动的调控","牵张反射的类型",1993,15,"A","","腱反射或骨骼肌牵张反射",[["A","是由于刺激了肌腱内的感受器引起的反射活动"],["B","传出神经是前角小运动神经元"],["C","效应器是被牵拉的肌肉"],["D","此反射在屈肌较明显"],["E","以上各项都对"]],"C","牵张反射包括腱反射和肌紧张，它是指有完整神经支配的骨骼肌在受外力牵拉伸长时引起的被牵拉的同一肌肉发生收缩的反射，它的感受器是肌梭，肌梭位于一般肌纤维之间而不是肌腱内（位于肌腱内的是腱器官）（A错）。脊髓灰质前角中存在α、β、γ三类运动神经元，γ运动神经元的胞体较小，称小运动神经元，α运动神经元的胞体较大，称大运动神经元。牵张反射传出神经包括了α运动神经元（大）传出纤维和γ运动神经元（小）传出纤维两个部分，但腱反射的传出神经只有α运动神经元（大）传出纤维（B错）。腱反射属于牵张反射的一种类型，牵张反射的效应器均为被牵拉的同一肌肉（C对）。伸肌和屈肌都有牵张反射，人类的牵张反射主要发生在伸肌（D错），因为伸肌是人类的抗重力肌。","","N"],["1993-N16",8,"第4节 听觉","基底膜的振动和行波学说",1993,16,"A","","按照行波理论，低频振动（低音调）",[["A","只引起耳蜗顶部基底膜发生振动"],["B","只引起耳蜗底部基底膜发生振动"],["C","整个基底膜均有振动，振幅大小相同，终止于顶部"],["D","首先引起耳蜗底部基底膜振动，振幅逐渐增大，近顶端达到最大振幅"],["E","首先引起耳蜗底部基底膜振动，开始较大而后逐渐减小，近顶端处逐渐消失"]],"D","行波理论，又称为行波学说，是指声波振动自基底膜底部向顶部传播的原理。声波在基底膜传播的过程：声波的振动经中耳传到卵圆窗膜，引起卵圆窗膜处基底膜（即蜗底部）的振动（不同频率的声波引起的行波都是从基底膜的蜗底部开始的），再以行波原理向蜗顶部传播，引起其他部位基底膜的振动。在向蜗顶部传播时，频率越低的声波，传播越远，最大行波振幅出现的部位越靠近基底膜顶部，而频率越高的声波传播越近，最大行波振幅出现的部位越靠近基底膜底部。这就类似于人们抖动一条绸带，抖动的频率越低，才能传播越远、最大振幅出现的位置越远，且最大振幅出现后，行波很快消失。因此低频振动首先引起耳蜗底部基底膜振动，振幅逐渐增大，近顶端达到最大振幅（D对），而高频率的声音引起的基底膜振动只局限于卵圆窗膜附近。","","N"],["1993-N28",10,"第4节 甲状旁腺、维生素D与甲状腺C细胞内分泌","维生素D的概述",1993,28,"A","","下列关于1，25-（OH）₂D₃的叙述，哪项是错误的",[["A","调节钙磷代谢，使血钙升高"],["B","可看成是一种激素"],["C","是由维生素D₃经肝脏直接转化而成"],["D","是维生素D₃的活性形式"],["E","其作用的主要靶器官为骨及肾"]],"C","1，25-（OH）₂D₃又称钙三醇，是调节钙磷代谢的重要激素（B对），其受体主要分布于小肠、骨和肾（E对），通过一系列生物学机制发挥升高血钙和升高血磷的作用（A对）。1，25-（OH）₂D₃是维生素D₃的活性形式（D对），可由维生素D₃在肝内25-羟化酶催化下生成25-羟维生素D₃，再经近端肾小管上皮细胞内1α-羟化酶催化而成（C错，为本题正确答案）。","","N"],["1993-N47",5,"第3节 胃内消化","内因子",1993,47,"A","","与维生素B₁₂吸收有关的内因子是胃黏膜中哪种细胞产生的",[["A","表层柱状上皮"],["B","黏液细胞"],["C","主细胞"],["D","壁细胞"],["E","G细胞"]],"D","表层柱状上皮是指除胃三大外分泌腺（贲门腺、泌酸腺、幽门腺）之外的分布于胃的所有区域的上皮细胞（七版生理学P172），主要功能是分泌黏稠的黏液，构成胃表面黏液层的主要成分（A错）。黏液细胞的主要功能也是分泌黏液（B错）。主细胞分泌胃蛋白酶原（C错）。壁细胞分泌盐酸和内因子（D对）。G细胞（十版生理学P171）分泌胃泌素和ACTH样物质（E错）。","","N"],["1993-N56",3,"第1节 心脏的泵血功能","心室收缩的后负荷",1993,56,"A","","通过下述哪项可估价左心室后负荷",[["A","心率"],["B","心排血量"],["C","外周动脉压"],["D","左心室舒张末压"],["E","肺毛细血管楔压"]],"C","肌肉在收缩过程中所承受的负荷，称为后负荷。对心室肌来说，收缩过程中所承受的负荷为大动脉血压。外周动脉压是指中小动脉压，由大动脉血压传递而来，其大小可以反映大动脉血压的大小，故外周动脉压可以估价左心室后负荷（大动脉血压）（C对）。","","N"],["1993-N81",5,"第3节 胃内消化","促进胃液分泌的主要因素",1993,81,"B","","胃泌素的主要作用是",[["A","促进胃酸分泌"],["B","促进胰液中HCO₃⁻分泌"],["C","促进胰液中胰酶分泌"],["D","促进胆汁分泌"],["E","促进胃蛋白酶分泌"]],"A","胃泌素又称促胃液素，是由胃窦部和小肠黏膜G细胞分泌的一种肽类激素，胃泌素的作用较为广泛，对胃酸分泌、胰液中HCO₃⁻分泌、胰液中胰酶分泌、胆汁分泌和胃蛋白酶原分泌均有促进作用，但最主要的作用在于促进胃酸分泌（A对）。","","N"],["1993-N82",5,"第4节 小肠内消化","缩胆囊素",1993,82,"B","","胆囊收缩素-促胰酶素的作用是",[["A","促进胃酸分泌"],["B","促进胰液中HCO₃⁻分泌"],["C","促进胰液中胰酶分泌"],["D","促进胆汁分泌"],["E","促进胃蛋白酶分泌"]],"C","胆囊收缩素-促胰酶素由小肠黏膜I细胞分泌，其主要功能是促进胆囊收缩和促进胰酶分泌，实际上胆囊收缩素-促胰酶素的生理功能极为广泛及多样化，且大部分功能与促胰液素（1998N11A和2010N12A）一致，七、八、九、十版生理学教材提及的功能包括：舒血管作用（七版生理学P170）、促进胃蛋白酶原分泌（七版生理学P176）（E错）、促进胰腺外分泌部组织的生长（十版生理学P168）、舒张食管下括约肌（十版生理学P171）、抑制胃的运动，延缓胃排空（十版生理学P168、七版生理学P180）、促进或抑制（为主）胃酸的分泌（A对）、促进胰酶分泌（十版生理学P181）（C对）、引起胆囊收缩，促进胆汁排出（十版生理学P181）、促进胆汁分泌（十版生理学P182）（D对）、促进小肠液分泌（十版生理学P183）、促进胰岛素分泌（十版生理学P377）、促进胰高血糖素分泌（十版生理学P378）、促进胰HCO₃⁻分泌（七版生理学P170 表6-3）（B对）、抑制食管-胃括约肌收缩（七版生理学P170 表6-3）、刺激小肠平滑肌收缩、促进小肠运动（七版生理学P170 表6-3）等等。故A选项促进胃酸分泌、B选项促进胰液中HCO₃⁻分泌、C选项促进胰液中胰酶分泌、D选项促进胆汁分泌均可算作胆囊收缩素-促胰酶素的作用，但本题给出的答案为C，若将题干改为“胆囊收缩素-促胰酶素的主要作用是”更严谨一些。","","N"],["1993-N83",6,"第2节 体温及其调节","辐射散热",1993,83,"B","","气温低于皮肤温度时散热方式是",[["A","蒸发"],["B","辐射"],["C","传导"],["D","对流"],["E","辐射、传导和对流"]],"E","气温低于皮肤温度时主要散热方式是辐射、传导和对流（E对），气温高于皮肤温度时唯一的散热方式是蒸发。","","N"],["1993-N84",6,"第2节 体温及其调节","蒸发散热",1993,84,"B","","气温高于皮肤温度时散热方式是",[["A","蒸发"],["B","辐射"],["C","传导"],["D","对流"],["E","辐射、传导和对流"]],"A","气温低于皮肤温度时主要散热方式是辐射、传导和对流，气温高于皮肤温度时唯一的散热方式是蒸发（A对）。","","N"],["1993-N105",10,"第5节 肾上腺内分泌","概述",1993,105,"C","","肾上腺皮质可分泌的激素有",[["A","性激素"],["B","皮质醇"],["C","二者均有"],["D","二者均无"]],"C","肾上腺皮质可分泌盐皮质激素（醛固酮为代表）、糖皮质激素（皮质醇为代表）（B对）、和性激素（雄激素）（A对）。本题AB均对，正确答案为C。","","N"],["1993-N106",11,"第1节 男性生殖功能及其调节","雄激素的合成、代谢和利用",1993,106,"C","","性腺可分泌的激素有",[["A","性激素"],["B","皮质醇"],["C","二者均有"],["D","二者均无"]],"A","性腺主要指男性的睾丸和女性的卵巢，二者均可分泌性激素：睾丸可分泌雄激素，卵巢可分泌雌激素、孕激素和少量雄激素（A对）。皮质醇又称氢化可的松，属于糖皮质激素，由肾上腺皮质分泌（B错）。","","N"],["1993-N107",3,"第2节 心脏的电生理学及生理特性","心室肌细胞动作电位",1993,107,"C","","心室肌细胞动作电位的特征是",[["A","0期除极速度快、幅度高"],["B","4期电位不稳定"],["C","二者都是"],["D","二者都不是"]],"A","心室肌细胞由0期、1期、2期、3期和4期五个时相组成，其中0期为去极期，由快钠通道介导，去极化速度快、幅度高（A对）。心室肌细胞为工作细胞，主要执行收缩功能，其4期为静息期，静息期的电位为-80～-90mV，比较稳定（B错）。","","N"],["1993-N108",3,"第2节 心脏的电生理学及生理特性","浦肯野细胞动作电位",1993,108,"C","","浦肯野细胞动作电位的特征是",[["A","0期除极速度快、幅度高"],["B","4期电位不稳定"],["C","二者都是"],["D","二者都不是"]],"C","浦肯野细胞与心室肌细胞一样，动作电位由0期、1期、2期、3期和4期五个时相组成，其中0期为去极期，由快钠通道介导，去极化速度快（比心室肌细胞更快），幅度高（A对）。与心室肌细胞不一样的是，心室肌细胞为工作细胞，主要执行收缩功能，其4期为静息期，比较稳定；而浦肯野细胞为自律细胞，可自动产生节律性兴奋，其4期膜电位水平不稳定（B对），发生自动去极化。本题AB均对，正确答案为C。","","N"],["1993-N111",10,"第1节 内分泌与激素","激素受体",1993,111,"C","","胰高血糖素是与肝细胞的何类受体相结合",[["A","细胞膜受体"],["B","细胞核受体"],["C","两者都是"],["D","两者都不是"]],"A","受体是指细胞中具有接受和转导信息功能的蛋白质，分布于细胞膜中的受体称为膜受体，位于胞质内和核内的受体则分别称为胞质受体和核受体（十版生理学P22）。胰高血糖素为29个氨基酸残基组成的多肽类激素（十版生理学P377），通过与靶细胞膜受体（G蛋白耦联受体）（A对）结合，启动细胞内信号转导系统而引起细胞生物效应。","","N"],["1993-N112",10,"第1节 内分泌与激素","激素受体",1993,112,"C","","肾上腺皮质激素是与细胞的何类受体相结合",[["A","细胞膜受体"],["B","细胞核受体"],["C","两者都是"],["D","两者都不是"]],"C","受体是指细胞中具有接受和转导信息功能的蛋白质，分布于细胞膜中的受体称为膜受体，位于胞质内和核内的受体则分别称为胞质受体和核受体（P24）。膜受体位于细胞膜上，主要有G蛋白耦联受体、酪氨酸激酶受体、酪氨酸激酶结合型受体和鸟苷酸环化酶受体等；核受体则定位于细胞质或细胞核中，包括类固醇激素受体、甲状腺激素受体、维生素D受体和维甲酸受体等，肾上腺皮质激素（P392）包括盐皮质激素（如醛固酮）、糖皮质激素（如皮质醇）和雄激素（如睾酮），属于类固醇激素，与胞核受体相结合（B对）。十版生理学P343认为“我国生理学家陈宜张首次发现糖皮质激素可在数秒钟内引起神经细胞超极化，其作用显然是通过膜受体以及离子通道所引起的快速反应（数分钟甚至数秒）”，按照十版生理学观点，该题答案应该选C，但原官方参考答案为B。","","N"],["1993-N129",4,"第1节 肺通气","胸膜腔内压",1993,129,"X","","胸内负压的生理意义为",[["A","维持肺的扩张状态"],["B","降低气道阻力"],["C","保持肺泡大、小的稳定性"],["D","有利于静脉血和淋巴液的回流"]],"ABD","保持大、小肺泡的稳定性是肺表面活性物质的作用，与胸膜腔负压无关（C错）。","","N"],["1993-N130",1,"第3节 细胞的电活动","兴奋性",1993,130,"X","","与神经元兴奋具有同样意义的是",[["A","阈电位水平"],["B","神经冲动"],["C","动作电位"],["D","突触后电位"]],"BC","当机体、器官、组织或细胞受到刺激时，功能活动由弱变强或由相对静止转变为比较活跃的反应过程或反应形式，称为兴奋。神经元、肌细胞和部分腺细胞很容易接受刺激并发生明显的兴奋反应，这些细胞由于具有较多的电压门控钠通道或电压门控钙通道，受刺激后首先发生的共同反应就是基于这些离子通道激活而产生的动作电位（C对），而后才表现出不同的兴奋反应，如肌细胞通过兴奋-收缩耦联发生收缩，腺细胞通过兴奋-分泌耦联引起分泌，神经元出现动作电位在神经纤维上的传导，即产生神经冲动（B对）。","","N"],["1993-N131",3,"第3节 血管生理","静脉血压",1993,131,"A","","中心静脉压的高低可反映",[["A","动脉血压高低"],["B","心脏射血能力和静脉回心血量之间的相互关系"],["C","胸膜腔的压力"],["D","静脉系统的容量"]],"B","中心静脉压的高低取决于心脏射血能力和静脉回心血量之间的相互关系（B对）。若心脏射血能力减弱（如心力衰竭），右心房和腔静脉淤血，中心静脉压就升高。另一方面，如果静脉回心血量增多或回流速度过快（如输液、输血过多或过快），中心静脉压也会升高。","","N"],["1993-N132",5,"第4节 小肠内消化","胆汁的作用",1993,132,"X","","胆汁的生理作用包括",[["A","在十二指肠中，中和一部分胃酸，有利于肠内消化"],["B","乳化脂肪"],["C","促进脂肪酸的吸收"],["D","促进维生素A、D、E、K的吸收"]],"ABCD","胆汁的作用包括三个方面：①促进脂肪的消化：胆汁中的胆盐、胆固醇和卵磷脂都可作为乳化剂乳化脂肪（B对），降低脂肪的表面张力，使脂肪乳化成微滴分散在水性的肠液中，因而可增加胰脂肪酶的作用面积，促进脂肪的分解消化；②促进脂肪和脂溶性维生素的吸收：在小肠绒毛表面覆盖有一层不流动水层，即静水层，脂肪分解产物不易穿过静水层到达肠黏膜表面而被上皮细胞吸收。肠腔中的脂肪分解产物，如脂肪酸（C对）、一酰甘油等均可掺入由胆盐聚合成的微胶粒中，形成水溶性的混合微胶粒，混合微胶粒则很容易穿过静水层而到达肠黏膜表面，从而促进脂肪分解产物的吸收。胆汁的这一作用，也有助于脂溶性维生素A、D、E、K的吸收（D对）；③中和胃酸及促进胆汁自身分泌：胆汁排入十二指肠后，可中和一部分胃酸（A对），进入小肠的胆盐绝大部分由回肠黏膜吸收入血，通过门静脉回到肝脏再形成胆汁，这一过程称为胆盐的肠-肝循环。返回到肝脏的胆盐有刺激肝胆汁分泌的作用，称为胆盐的利胆作用。","","N"],["1993-N133",8,"第1节 感觉概述","感受器的换能作用",1993,133,"X","","感受器的换能作用涉及",[["A","将刺激能量转为传入神经纤维上的动作电位"],["B","先产生发生器电位，当达到一定水平时，可产生动作电位"],["C","发生器电位是“全或无”的"],["D","发生器电位传入中枢一定部位，就会产生主观感觉"]],"AB","受刺激时，在感受器细胞或感觉神经末梢引起相应的电位变化，前者称为感受器电位，后者称为发生器电位，感受器电位和发生器电位均为局部电位，不具有“全或无”性质（C错）。感受器电位或发生器电位以电紧张的形式传播，当其传播到轴突始段并且达到一定水平时（阈电位）时，便爆发动作电位并向远处传导（AB对）。发生器电位传入中枢一定部位，不一定会产生主观感觉，有些电位传入只是向中枢提供内外环境中某些因素改变的信息而引起某些调节反应，如颈动脉窦压力感受器的传入冲动（D错）。","","N"],["1993-N134",7,"第1节 肾的功能解剖和肾血流量","肾脏的血液供应",1993,134,"X","","肾脏的血液供应特点是",[["A","血液供应丰富"],["B","肾髓质血流量多而皮质血流量少"],["C","经过两次毛细血管分支"],["D","肾小管周围毛细血管中血压较高，有利于肾小管的分泌作用"]],"AC","在安静状态下，健康成年人两肾的血液灌注量（肾血流量）约为1200ml/min，相当于心输出量的20%～25%，而肾仅占体重的0.5％左右，因此肾脏血液供应丰富（A对）。肾脏不同部位的供血不均，约94％的血流供应肾皮质，约5％供应外髓部，剩余不到1％供应内髓部，故肾皮质血流量多，肾髓质血流量少（B错）。肾脏血流经过两次毛细血管分支（C对）：第一次毛细血管分支为肾小球毛细血管网，肾小球毛细血管网血压较高，有利于肾小球滤过；第二次毛细血管分支为肾小管周围毛细血管网，肾小管周围毛细血管网血压较低，有利于肾小管重吸收（D错）。","","N"],["1993-N149",7,"第6节 清除率","无溶质水清除率",1993,149,"X","","肾小管浓缩功能减退时",[["A","尿量减少"],["B","尿量增加"],["C","自由水清除率增加"],["D","高钾血症"]],"BC","解析中有八版教材页码，无法根据十版教材修改","","N"],["1994-N15",3,"第1节 心脏的泵血功能","心动周期",1994,15,"A","","心动周期中，在下列哪个时期主动脉压最低",[["A","等容收缩期末"],["B","等容舒张期末"],["C","心房收缩期末"],["D","快速充盈期末"],["E","减慢充盈期末"]],"A","主动脉压的大小与主动脉血液充盈量成正比，等容收缩期末是主动脉血液充盈量最少的时候，也是主动脉压最低的时候（A对）。","","N"],["1994-N16",3,"第2节 心脏的电生理学及生理特性","心脏的起搏点",1994,16,"A","","窦房结能成为心脏正常起搏点的原因是",[["A","静息电位仅为-70mV"],["B","阈电位为-40mV"],["C","0期去极速率快"],["D","动作电位没有明显的平台期"],["E","4期去极速率快"]],"E","窦房结能成为心脏正常起搏点的原因是窦房结在所有心脏自律细胞中，4期自动去极化速度最快（E对），自律性最高。生理情况下，整个心脏的活动总是按照当时自律性最高的组织所发出的节律性兴奋来进行。正常情况下，窦房结的自律性最高，由它发出的节律性兴奋依次激动心房肌、房室交界、房室束、心室内传导组织和心室肌，引起整个心脏的节律性兴奋和收缩。","","N"],["1994-N17",9,"第4节 神经系统对内脏活动、本能行为和情绪的调节","自主神经系统功能活动的基本特征",1994,17,"A","","交感神经系统功能活动的意义在于",[["A","促进消化"],["B","保存能量"],["C","加速排泄"],["D","生殖"],["E","应付环境急骤变化"]],"E","交感神经和副交感神经共同组成自主神经系统，大部分的器官受到两者的共同支配。交感神经系统的活动可以在环境急剧变化的条件下，动员机体许多器官的潜在力量，促使机体适应环境的变化（E对）。而副交感神经系统的活动相对局限，其意义主要在于保护机体、休整恢复、促进消化（A错）、积蓄能量（B错）以及加强排泄（C错）和生殖（D错）功能等。","","N"],["1994-N18",9,"第3节 神经系统对躯体运动的调控","运动传出通路",1994,18,"A","","锥体束最主要的机能是",[["A","支配对侧肢体肌肉运动"],["B","精细调节四肢远端肌肉活动"],["C","抑制腱反射"],["D","使肌群运动协调"],["E","调节肌紧张"]],"B","运动传出通路在传统上分为锥体系和锥体外系两个系统。锥体系包括皮层脊髓束和皮层脑干束（锥体外系是指锥体系以外的运动传出通路），皮层脊髓束是指由皮层发出，经内囊、脑干下行，到达脊髓前角运动神经元的传导束，皮层脑干束是指由皮层发出，经内囊到达脑干内各脑运动神经元的传导束。皮层脊髓束中80%的纤维在对侧脊髓外侧索下行而形成皮层脊髓侧束，其功能是控制四肢远端肌肉的活动，与精细的、技巧性的运动有关（B对），其余20%的纤维下行形成皮层脊髓前束，其功能是控制躯干和四肢近端肌肉的活动，与姿势的维持和粗略的运动有关。支配对侧肢体活动的是大脑皮层运动区（A错）。腱反射、肌紧张、肌群运动协调，受皮层脊髓前束（只占20%）的调节，它不是锥体系的主要功能（CDE错）。","","N"],["1994-N19",10,"","",1994,19,"A","","激素的半衰期用来表示",[["A","激素作用的速度"],["B","激素作用持续的时间"],["C","激素更新的速度"],["D","激素释放的速度"],["E","激素和受体结合的速度"]],"C","激素从分泌入血，经过代谢到消失（或消失生物活性）所经历的时间长短不同。为表示激素更新的速度（C对），一般采用激素活性在血中消失一半的时间，称为半衰期，作为衡量指标。不同激素的半衰期各不相同，儿茶酚胺类的半衰期只有2～3分钟；同属于胺类激素的甲状腺激素的半衰期可有7天（十版生理学P358），是所有激素中半衰期最长的；多肽类的半衰期一般为4-40分钟，蛋白质类激素则为15～170分钟；类固醇激素的半衰期为数十分钟到数小时（十版生理学P368）。","","N"],["1994-N20",6,"第1节 能量代谢","间接测热法",1994,20,"A","","呼吸商是",[["A","在一定时间内机体摄入O₂与呼出CO₂量的比值"],["B","呼出气与吸入气的比值"],["C","一次呼吸中，机体呼出CO₂的量与吸入O₂量的比值"],["D","呼出气与肺容量的比值"],["E","一定时间内机体CO₂产生量与耗O₂量的比值"]],"E","营养物质在细胞内进行氧化供能的过程中，需要消耗O₂，并产生CO₂。将一定时间内机体呼出的CO₂量与吸入的O₂量的比值，称为呼吸商。而不是一次呼吸中，机体呼出的CO₂量与吸入的O₂量的比值（C错）。呼吸商和呼出气与吸入气的比值无关（B错）。呼吸商和呼出气与肺容量的比值无关（D错）。教材将呼吸商定义为“一定时间内机体呼出的CO₂量与吸入的O₂量的比值”，实际上是用“呼出的CO₂量”代表“CO₂的产生量”，用“吸入的O₂量”代表“耗O₂量”，呼吸商严格意义上应定义为“一定时间内机体CO₂产生量与耗O₂量的比值”（E对）。","","N"],["1994-N21",8,"第3节 视觉","瞳孔对光反射",1994,21,"A","","当光照增强时，瞳孔缩小，此反射称为",[["A","瞳孔近反射"],["B","直接缩小反射"],["C","瞳孔对光反射"],["D","直接光反射"],["E","减弱的瞳孔开大反射"]],"C","瞳孔近反射是指在视近物时反射性的引起双眼瞳孔缩小的反射，又称为瞳孔调节反射（十版生理学P255）（A错）。瞳孔对光反射是指瞳孔在强光照射时缩小而在光线变弱时散大的反射（C对）。无直接缩小反射、直接光反射、减弱的瞳孔开大反射等提法或概念（BDE错）。","","N"],["1994-N22",3,"第1节 心脏的泵血功能","心室舒张期",1994,22,"A","","心动周期中，心室血液充盈主要是由于",[["A","血液依赖地心引力而回流"],["B","骨骼肌的挤压作用加速静脉回流"],["C","心房收缩的挤压作用"],["D","心室舒张的抽吸作用"],["E","胸内负压促进静脉回流"]],"D","心室充盈期包括快速充盈期、减慢充盈期和心房收缩期。快速充盈期和减慢充盈期的血液充盈源自于心室舒张时对心房和大静脉内血液的抽吸作用，且占据了心室总充盈量的绝大部分（D对）。心房收缩期的血液充盈源自于心房的收缩，占心室总充盈量的10%-30%，不能算心室血液充盈的主要原因（C错）。血液依赖地心引力而回流、骨骼肌的挤压作用加速静脉回流、胸内负压促进静脉回流等因素均可增加心室血液充盈量，但不能称之为心室血液充盈的原因（ABE错）。","","N"],["1994-N23",2,"第1节 血液生理概述","血浆渗透压",1994,23,"A","","机体细胞内液与组织液通常具有相同的",[["A","Na⁺浓度"],["B","总渗透压"],["C","胶体渗透压"],["D","Cl⁻浓度"],["E","K⁺浓度"]],"B","组织液即细胞外液，受钠泵影响，组织液的Na⁺、Cl⁻浓度大于细胞内液，而K⁺浓度小于细胞内液（ADE错）。细胞内液富含蛋白，而组织液内蛋白含量很少（蛋白质是在细胞内合成的，细胞选择其中的一小部分，即分泌蛋白通过胞吐作用运输到组织液等中 ）（C错）。渗透压是指溶液中溶质微粒对水的吸引力，只要有渗透压差的存在，就会有水分子由低渗透压侧向高渗透压侧的自由渗透。细胞内液与组织液由细胞膜分隔，只要有渗透压差就会造成水的跨膜流动，直至两侧的渗透压差为0，所以细胞内液与组织液的总渗透压是相等的（B对）。","","N"],["1994-N24",0,"第6节 人体内自动控制系统","反馈控制系统",1994,24,"A","","反馈信息是指",[["A","控制部分发出的信息"],["B","受控变量的改变情况"],["C","外界干扰的强度"],["D","调定点的改变"],["E","中枢的紧张性"]],"B","控制部分对受控部分施加影响后，受控部分发生改变，这种改变信息（B对）反过来纠正控制部分的活动，称为反馈，反馈有负反馈和正反馈两种形式。与反馈对应的一个概念是前馈（十版生理学P11），前馈是指控制部分在反馈信息尚未到达前已受到纠正信息（前馈信息）的影响，及时纠正其可能出现偏差的活动。","","N"],["1994-N25",4,"第2节 肺换气和组织换气","气体的分压差",1994,25,"A","","正常人体气体交换的关键因素是",[["A","生物膜的通透性"],["B","气体的溶解度"],["C","交换部位两侧气体的分压差"],["D","通气／血流比值"],["E","温度"]],"C","气体交换与生物膜的通透性、气体的溶解度、交换部位两侧气体的分压差、通气／血流比值、温度等因素均有关。其中交换部位两侧气体的分压差决定了气体扩散的动力和扩散方向，是最关键的因素（C对）。","","N"],["1994-N26",5,"第3节 胃内消化","内因子",1994,26,"A","","与维生素B₁₂吸收有关的内因子是胃黏膜中哪种细胞产生的",[["A","贲门腺细胞"],["B","黏液细胞"],["C","主细胞"],["D","壁细胞"],["E","G细胞"]],"D","贲门腺主要由黏液细胞组成，分泌稀薄的碱性黏液（七版生理学P172）（A错）。黏液细胞分泌黏液（B错）。主细胞分泌胃蛋白酶原（C错）。壁细胞分泌盐酸和内因子（D对）。G细胞分泌胃泌素和ACTH样物质（E错）。","","N"],["1994-N27",4,"第4节 呼吸运动的调节","肺牵张反射",1994,27,"A","","切断双侧迷走神经后呼吸的改变是",[["A","呼吸频率加快"],["B","呼吸幅度减少"],["C","吸气时相缩短"],["D","血液CO₂分压暂时升高"],["E","呼吸频率减慢，幅度增大"]],"E","肺牵张反射包括肺扩张反射和肺萎陷反射两个部分。肺扩张反射是肺扩张时抑制吸气活动的反射，可以使呼吸变浅变快；肺萎陷反射是肺萎陷时增强吸气活动的反射，可以使呼吸变深变慢。肺扩张反射和肺萎陷反射的传入神经均为迷走神经，切断迷走神经后，肺扩张反射被抑制的效应是呼吸变深变慢，肺萎陷反射被抑制的效应是呼吸变浅变快，动物实验表明，切断迷走神经的综合效应是呼吸变深变慢，即呼吸频率减慢，幅度增大（E对）。","","N"],["1994-N28",3,"第1节 心脏的泵血功能","心动周期",1994,28,"A","","心动周期中，在下列哪个时期左心室容积最大",[["A","心房收缩期末"],["B","等容舒张期末"],["C","减慢充盈期末"],["D","快速充盈期末"],["E","快速射血期末"]],"A","心室容积与心室血量有关，左心室血量最多时，左心室容积也最大，左心室血量最多的时期包括心房收缩期末、整个等容收缩期和快速射血期初（A对）。","","N"],["1994-N29",7,"第5节 尿生成的调节","醛固酮的功能",1994,29,"A","","下列有关醛固酮的叙述，哪项是正确的",[["A","由肾上腺皮质束状带分泌的一种激素"],["B","分泌调节的主要因素是ACTH"],["C","肾素-血管紧张素系统对其分泌调节的作用极微"],["D","血浆中Na⁺和K⁺浓度变化对其分泌的调节无作用"],["E","其生理作用是促进远曲小管和集合管对Na⁺的主动重吸收，同时促进K⁺的排出"]],"E","醛固酮是由肾上腺皮质球状带分泌的，而不是束状带分泌的（束状带分泌糖皮质激素）（A错），其主要作用于肾远曲小管和集合管的上皮细胞，增加K⁺的排泄和Na⁺、水的重吸收（E对）。醛固酮的分泌调节机制包括：①肾素-血管紧张素系统的调节：血管紧张素Ⅱ和血管紧张素Ⅲ可促进肾上腺皮质球状带细胞分泌醛固酮（C错）；②血K⁺和血Na⁺的调节：血K⁺水平升高和血Na⁺水平降低均能刺激醛固酮分泌（D错）；③应激性调节：生理情况下，ACTH（促肾上腺皮质激素）对醛固酮的分泌无明显影响，只有在应激反应时才会出现ACTH促进醛固酮分泌的情况（B错）。","","N"],["1994-N30",10,"第5节 肾上腺内分泌","对组织器官活动的影响",1994,30,"A","","糖皮质激素的作用有",[["A","促进肝组织蛋白质分解和葡萄糖的利用"],["B","抑制肝内糖异生"],["C","抑制脂肪分解"],["D","使血糖降低"],["E","使外周血液中红细胞、血小板、中性粒细胞增加，嗜酸性粒细胞和淋巴细胞减少"]],"E","糖皮质激素的作用广泛而复杂（十版生理学P369-P371）：①糖皮质激素对体内糖、脂肪和蛋白质代谢均有明显影响：包括减少组织对糖的利用和加速肝糖异生而使血糖升高（BD错），提高四肢部分的脂肪酶活性而促进脂肪分解（C错），促进肝内组织细胞蛋白质合成等（A错）；②参加应激反应，提高机体对有害刺激的耐受能力；③对组织器官活动的影响，如促使血液中红细胞、血小板和中性粒细胞的数量增加，而淋巴细胞和嗜酸性粒细胞的数量减少（所以长期应用糖皮质激素可导致机体免疫功能下降，容易发生感染）等（E对）。","","N"],["1994-N31",1,"第1节 细胞膜的物质转运功能","经通道的易化扩散",1994,31,"A","","产生生物电的跨膜离子移动属于",[["A","单纯扩散"],["B","载体中介的易化扩散"],["C","通道中介的易化扩散"],["D","入胞"],["E","出胞"]],"C","经通道易化扩散能够产生生物电（C对），如骨骼肌终板膜电位由化学门控通道易化扩散介导，动作电位去极化电位变化由电压门控通道易化扩散介导，耳蜗微音器电位变化由机械门控通道易化扩散介导等。","","N"],["1994-N32",1,"第3节 细胞的电活动","动作电位的传播",1994,32,"A","","下列关于有髓神经纤维跳跃传导的叙述，哪项是错误的",[["A","以相邻郎飞结间形成局部电流进行传导"],["B","传导速度比无髓纤维快得多"],["C","离子跨膜移动总数多，耗能多"],["D","双向传导"],["E","不衰减扩布"]],"C","动作电位在有髓神经纤维郎飞结之间形成局部电流（A对），进行跳跃式传导，与无髓神经纤维相比，有髓神经纤维的这种跳跃式传导方式不仅能够提高动作电位的传导速度（B对），还能够减少离子跨膜移动和能量消耗（C错，为本题正确答案）。人为刺激神经纤维上任何一点，只要刺激足够强，引起的兴奋可沿纤维进行双向传导（十版生理学P281）（D对），双向传导是神经纤维兴奋传播的重要特征，区别于突触兴奋传播的单向传播（十版生理学P300）。","","N"],["1994-N47",7,"第6节 清除率","内生肌酐清除率",1994,47,"A","","肌酐清除率与下列哪项无关",[["A","滤过膜孔径增大"],["B","肾血浆流量"],["C","滤过膜的通透性"],["D","滤过面积"],["E","有效滤过压"]],"A","肌酐清除率与肾小球滤过率基本相等，所有影响肾小球滤过率的因素，均可影响肌酐清除率。肾血浆流量、滤过膜通透性、滤过面积和有效滤过压等均可影响肾小球滤过率，故均与肌酐清除率有关（BCDE对）。滤过膜孔径大小一般不影响肾小球滤过率（A错），但如果滤过膜孔径增大至可使血浆蛋白质特别是清蛋白滤出，则可降低血浆胶体渗透压，进而使有效滤过压和肾小球滤过率增加，这种情况也能对肌酐清除率造成影响。","","N"],["1994-N57",7,"第1节 肾的功能解剖和肾血流量","肾的功能解剖",1994,57,"A","","有关肾脏分泌的生理活性物质及其产生部位，下列哪项不正确",[["A","肾素——肾小球旁器"],["B","促红细胞生成素——肾小球旁器"],["C","前列腺素——肾皮质和髓质"],["D","激肽释放酶——肾髓质"],["E","1α-羟化酶——肾脏间质"]],"D","肾小球旁器是肾小管与肾小体血管极相接触部位的一个具有内分泌功能的特殊结构。位于入球小动脉、出球小动脉及远端肾小管之间的区域，由球旁细胞、致密斑、球外系膜细胞和极周细胞组成，其中球旁细胞可分泌肾素（A对）。全身各部位的组织细胞几乎都含有生成前列腺素的前体和酶（十版生理学P128），肾皮质和髓质均可合成前列腺素（C对）。激肽释放酶主要由肾皮质产生（D错，为本题正确答案）。本题给出的参考答案为D，但按照八、九、十版生理学教材的说法，BE选项也是错误的：促红细胞生成素是由肾间质（肾脏血管和肾小管间的结缔组织细胞）分泌的，而不是由肾小球旁器（主要由肾血管细胞和肾小管细胞组成）分泌的；1α-羟化酶主要由肾小管上皮细胞合成，而不由肾间质分泌。","","N"],["1994-N97",1,"第3节 细胞的电活动","局部电位的概念",1994,97,"B","","终板电位是",[["A","动作电位"],["B","阈电位"],["C","局部电位"],["D","静息电位"],["E","后电位"]],"C","局部电位是动作电位之外的另一类重要的电信号，局部电位具有电紧张电位的电学特征，包括非“全或无”电位、衰减性传导、没有不应期等。体内的局部电位有多种类型，包括骨骼肌膜上的终板电位（C对）、平滑肌细胞上的慢波电位、神经元突触后膜上的兴奋性突触后电位和抑制性突触后电位、感觉神经末梢上的去极化感受器（发生器）电位等等。","","N"],["1994-N98",1,"第3节 细胞的电活动","局部电位的概念",1994,98,"B","","兴奋性突触后电位是",[["A","动作电位"],["B","阈电位"],["C","局部电位"],["D","静息电位"],["E","后电位"]],"C","局部电位是动作电位之外的另一类重要的电信号，局部电位具有电紧张电位的电学特征，包括非“全或无”电位、衰减性传导、没有不应期等。体内的局部电位有多种类型，包括骨骼肌膜上的终板电位、平滑肌细胞上的慢波电位、神经元突触后膜上的兴奋性突触后电位（C对）和抑制性突触后电位、感觉神经末梢上的去极化感受器（发生器）电位等等。","","N"],["1994-N99",10,"第3节 甲状腺内分泌","甲状腺激素",1994,99,"B","","生物活性最大的甲状腺激素是",[["A","一碘酪氨酸"],["B","三碘甲腺原氨酸"],["C","甲状腺素"],["D","逆三碘甲腺原氨酸"],["E","二碘酪氨酸"]],"B","一碘酪氨酸、二碘酪氨酸均是甲状腺激素合成的前体物质（十版生理学P357），无甲状腺激素的生物活性作用（AE错）。逆三碘甲腺原氨酸（rT₃）是T₄脱碘降解的代谢产物，也无甲状腺激素的生物活性作用（D错）。具有生物活性的甲状腺激素是甲状腺素（或称四碘甲腺原氨酸，T₄）和三碘甲腺原氨酸（T₃），其中三碘甲腺原氨酸的生物活性远高于甲状腺素，约为后者5倍（B对C错）。","","N"],["1994-N100",10,"第3节 甲状腺内分泌","甲状腺激素",1994,100,"B","","甲状腺分泌的激素主要是",[["A","一碘酪氨酸"],["B","三碘甲腺原氨酸"],["C","甲状腺素"],["D","逆三碘甲腺原氨酸"],["E","二碘酪氨酸"]],"C","甲状腺分泌的激素包括甲状腺素（四碘甲腺原氨酸，T₄）和三碘甲腺原氨酸（T₃），分别约占总量的93%和7%（C对）。一碘酪氨酸、二碘酪氨酸均是甲状腺激素合成的前体物质（十版生理学P357）。逆三碘甲腺原氨酸是甲状腺素脱碘降解的代谢产物（十版生理学P358）。","","N"],["1994-N101",4,"第1节 肺通气","肺泡通气量",1994,101,"B","","每分钟肺内更新的气体量为",[["A","肺通气"],["B","肺通气量"],["C","肺换气"],["D","肺泡通气量"],["E","组织换气"]],"D","肺通气（十版生理学P135）指肺与外界环境之间的气体交换过程（A错）。肺换气指肺泡气通过肺泡（呼吸膜）与血液之间的气体交换过程（C错）。肺通气量（十版生理学P145）指每分钟吸入或呼出的气体总量，等于潮气量与呼吸频率的乘积（B错）。肺泡通气量（十版生理学P146）是指每分钟吸入肺泡的新鲜空气量（即肺内更新的气体量）（D对），等于潮气量和无效腔气量之差与呼吸频率的乘积。组织换气（十版生理学P147）又称内呼吸，指组织毛细血管血液与组织、细胞之间的气体交换过程（E错）。","","N"],["1994-N102",4,"第2节 肺换气和组织换气","肺换气",1994,102,"B","","肺泡气通过呼吸膜与血液之间的气体交换过程为",[["A","肺通气"],["B","肺通气量"],["C","肺换气"],["D","肺泡通气量"],["E","组织换气"]],"C","肺通气（十版生理学P135）指肺与外界环境之间的气体交换过程（A错）。肺换气指肺泡气通过肺泡（呼吸膜）与血液之间的气体交换过程（C对）。肺通气量（十版生理学P145）指每分钟吸入或呼出的气体总量，等于潮气量与呼吸频率的乘积（B错）。肺泡通气量（十版生理学P146）是指每分钟吸入肺泡的新鲜空气量，等于潮气量和无效腔气量之差与呼吸频率的乘积（D错）。组织换气（十版生理学P147）又称内呼吸，指组织毛细血管血液与组织、细胞之间的气体交换过程（E错）。","","N"],["1994-N121",3,"第3节 血管生理","影响动脉血压的因素",1994,121,"C","","血量增加可引起",[["A","动脉血压升高"],["B","中心静脉压降低"],["C","两者都有"],["D","两者都无"]],"A","血量增加时，循环系统平均充盈压增高，回心血量增加，动脉血压和中心静脉压均升高（A对B错）。","","N"],["1994-N122",3,"第3节 血管生理","影响动脉血压的因素",1994,122,"C","","心脏射血能力增强时",[["A","动脉血压升高"],["B","中心静脉压降低"],["C","两者都有"],["D","两者都无"]],"C","心脏射血能力增强时，心缩期射入主动脉的血量增多，动脉血压升高（A对）。由于射血量增多，心室内剩余血量减少，心舒期室内压降低，从而对心房和静脉内血液的抽吸力量增强，使中心静脉压下降（B对），促使回心血量增多。血量增加和心脏射血能力增强均可使回心血量增加，但前者引起中心静脉压升高，后者引起中心静脉压下降，这是因为血量增加→回心血量增加→中心静脉压升高，而心脏射血能力增强→中心静脉压降低→回心血量增加。本题AB均对，正确答案为C。","","N"],["1994-N123",7,"第6节 清除率","推测肾小管的功能",1994,123,"C","","某种物质的血浆清除率等于肾小球滤过率时意味着",[["A","肾小管对该物质有重吸收作用"],["B","肾小管对该物质有分泌作用"],["C","两者均有"],["D","两者均无"]],"D","两肾在单位时间（一般为每分钟）内能将一定毫升血浆中所含的某种物质完全清除，这个能完全清除某物质的血浆毫升数就称为该物质的血浆清除率。血浆清除率等于肾小球滤过率时可见于两种情况：①肾小管对该物质既没有重吸收作用，也没有分泌作用（D对）；②肾小管对该物质既有重吸收作用，也有分泌作用，且重吸收的量与分泌的量相等（C对）。故C选项和D选项的情况均有可能发生，本题并不严谨。","","N"],["1994-N124",7,"第6节 清除率","推测肾小管的功能",1994,124,"C","","某种物质的血浆清除率大于肾小球滤过率时意味着",[["A","肾小管对该物质有重吸收作用"],["B","肾小管对该物质有分泌作用"],["C","两者均有"],["D","两者均无"]],"B","两肾在单位时间（一般为每分钟）内能将一定毫升血浆中所含的某种物质完全清除，这个能完全清除某物质的血浆毫升数就称为该物质的血浆清除率。如果某种物质清除率大于肾小球滤过率，则表明肾小管必定能分泌该物质（B对），但不能排除该物质也可被肾小管重吸收的可能性，因为当其分泌量大于重吸收量时，清除率仍高于肾小球滤过率。","","N"],["1994-N142",10,"第4节 甲状旁腺、维生素D与甲状腺C细胞内分泌","概述",1994,142,"X","","下列激素中，何者具有调节钙磷代谢的作用",[["A","甲状旁腺激素"],["B","降钙素"],["C","1，25-（OH）₂D₃"],["D","维生素D"]],"ABC","甲状旁腺激素、降钙素及1，25-（OH）₂D₃均有调节钙磷代谢的作用（ABC对）。维生素D是1，25-（OH）₂D₃的前体物质，本身不具有调节钙磷代谢的作用（十版生理学P365）（D错）。","","N"],["1994-N143",9,"第2节 神经系统的感觉分析功能","感觉投射系统",1994,143,"X","","感觉的非特异性投射系统",[["A","外周感受野与皮层有点对点的投射关系"],["B","是由各种特异感觉传导途径共同组成的"],["C","脑干网状结构上行激动系统是很重要的结构"],["D","有多级神经元参与传递"]],"CD","丘脑是感觉传入通路的重要中继站，根据丘脑各部分向大脑皮层投射特征的不同，将感觉投射系统分为特异投射系统和非特异投射系统。非特异投射系统是指丘脑非特异投射核及其投射到大脑皮层的神经通路。该系统一方面经多级神经元传递（多次换元）（D对）弥散性投射到大脑皮层的广泛区域，因而与皮层不具有点对点的投射关系（A错）；另一方面通过脑干网状结构上行激动系统（C对），间接接受来自特异感觉传导途径中第二级神经元侧支的纤维投射，但是该系统没有专一的感觉传导功能，因而不能引起各种特异感觉（B错）。","","N"],["1994-N144",8,"第2节 躯体和内脏感觉","痛觉信息的感受和传导",1994,144,"X","","当脚趾受到机械性损伤刺激时，可引起快痛与慢痛",[["A","快痛由Aδ纤维传导，慢痛由C纤维传导"],["B","快痛在传递过程中在脊髓要换神经元"],["C","慢痛在皮层的代表区与外周刺激部位间有点对点的关系"],["D","痛觉传入纤维兴奋的原因是伤害性刺激引起组织损伤，释放化学物质"]],"ABD","痛觉是指伤害性刺激引起组织损伤时，受损细胞释放出致痛物质激活痛觉感受器，而引起的不愉快感觉和情感性体验（D对）。根据传导速度不同，可以将痛觉分成快痛和慢痛两类：沿Aδ有髓纤维传导的伤害性信息到达大脑皮质后引起的痛觉称为快痛，沿C类无髓纤维传导的伤害性信息到达大脑皮质后引起的痛觉称为慢痛（A对）。快痛定位准确，经特异性投射系统到达大脑皮层的第一、二感觉区，与皮层具有点对点投射关系。慢痛经脑干网状结构投射到丘脑的非特异投射系统，经过多次换元弥散性投射到大脑皮层边缘系统中的扣带回，与皮层不具有点对点的关系（C错）。快痛是一种浅感觉，传导浅感觉的纤维进入脊髓后在后角换元（B对），第二级神经元发出纤维经白质前连合交叉至对侧，在脊髓前外侧部上行，形成前外侧索传入系统。","","N"],["1994-N145",4,"第4节 呼吸运动的调节","CO₂、H⁺、O₂对呼吸运动的调节",1994,145,"X","","动脉血中CO₂分压的增加",[["A","在适当的体育锻炼时出现"],["B","通过外周化学感受器刺激呼吸"],["C","通过中枢化学感受器刺激呼吸"],["D","引起血压的反射性下降"]],"BC","适当的体育锻炼时，机体的代谢活动增强，代谢产生的CO₂增多，使动脉血中的CO₂分压升高，但是动脉血中CO₂分压升高能够通过化学感受性呼吸反射，引起呼吸加深加快，促进CO₂的排出，使动脉血中的CO₂分压降至接近正常水平（A错）。动脉血中CO₂分压增加刺激呼吸运动是通过外周化学感受器和中枢化学感受器共同实现的，其中中枢化学感受器起主要作用（BC对）。动脉血CO₂分压升高会引起呼吸运动加强，进而反射性引起心率加快，心输出量增多，外周阻力增大，血压升高等心血管活动的改变（D错）。","","N"],["1994-N146",8,"第3节 视觉","视觉传入通路与皮层代表区",1994,146,"X","","从物体射向视轴右侧的光线",[["A","被双眼中央凹左侧的视网膜所感受"],["B","产生的冲动沿着右侧视束传导"],["C","产生的冲动在额叶视区内引起有意识的感觉"],["D","在视网膜上形成一个倒像"]],"BD","从物体射向视轴右侧的光线（来自左侧视野），被双眼中央凹右侧的视网膜所感受（A错），中央凹右侧视网膜包括右眼颞侧视网膜和左眼鼻侧视网膜，二者汇集成右侧视束（B对），投射到右侧外侧膝状体，然后经同侧膝状体距状束投射至枕叶皮层内侧面的距状沟上、下缘（而不是额叶视区），产生视觉（C错）。视网膜上的成像是小孔成像的原理，在视网膜上的像是倒像（D对）。","","N"],["1995-N13",1,"第3节 细胞的电活动","细胞兴奋后兴奋性的变化",1995,13,"A","","在神经纤维一次兴奋后的相对不应期时",[["A","全部Na⁺通道失活"],["B","较强的刺激也不能引起动作电位"],["C","多数K⁺通道失活"],["D","部分Na⁺通道失活"],["E","膜电位处在去极过程中"]],"D","相对不应期是在绝对不应期之后细胞的兴奋性逐渐向正常恢复的时期。这段时间内，细胞的兴奋性比正常时低，但是较强的刺激（阈上刺激）也能引起动作电位（B错）。细胞在相对不应期兴奋性较低的原因是，绝对不应期失活的电压门控Na⁺通道此时开始复活，但复活的通道数量较少（部分Na⁺通道还处于失活之中）（D对A错）。在神经纤维，相对不应期的持续时间相当于动作电位负后电位的前半段，处于复极化过程中（E错）。K⁺只有静息态和激活态，而没有失活态（参见1999N4A和2007N3A）（C错）。","","N"],["1995-N14",1,"第4节 肌细胞的收缩","骨骼肌神经肌肉接头处的兴奋传递",1995,14,"A","","在肌纤维，可以记录到微终板电位，其原因是",[["A","运动神经末梢释放一个递质分子引起的终板膜电活动"],["B","肌膜上一个受体离子通道打开"],["C","自发释放小量递质引起的多个离子通道打开"],["D","神经末梢不释放递质时肌膜离子通道的自发性开放"],["E","神经末梢单个动作电位引起的终板膜多个离子通道打开"]],"C","运动神经末梢释放ACh是以囊泡为单位进行的，每个突触囊泡含有约1万个ACh分子（十版生理学生理学P43），在静息状态下（E错），囊泡的随机运动也会发生单个囊泡的自发释放（与Ca²⁺内流触发的囊泡出胞机制无关）（D错），并引起终板膜电位的微小去极化，即微终板电位（小终板电位）。运动神经末梢释放的并非一个ACh递质分子，而是一个囊泡，一个囊泡内含有很多个ACh分子（A错），可引起多个离子通道开放（C对B错）。","","N"],["1995-N15",3,"第4节 心血管活动的调节","心脏的神经支配",1995,15,"A","","刺激迷走神经，其末梢释放乙酰胆碱，可以引起",[["A","窦房结超极化，使节律性降低"],["B","房室交界区去极化，使传导性增高"],["C","M受体的K⁺通道打开，使窦房结细胞去极化"],["D","心肌收缩力增强"],["E","窦房结细胞Na⁺内流，使节律性降低"]],"A","乙酰胆碱激活心肌细胞膜中的M受体，通过G蛋白-AC-cAMP-PKA通路，使胞内cAMP水平降低，PKA活性降低，进而表现出与去甲肾上腺素激活β₁受体相反的效应：负性变力作用，负性变时作用，负性变传导作用。涉及生物电活动包括：窦房结P细胞4期T型钙通道介导的钙内流较少和If型钠通道介导的钠内流减少，引起4期去极化速度减慢，IK-Ach通道介导的K⁺外流增加，引起最大复极电位增大，窦房结出现超极化（A对C错），窦房结超极化和4期去极化速度减慢均使自律性降低（E错），即为负性变时作用；房室交界区0期L型钙通道（ICa-L）介导的钙内流较少，0期间去极化速度和幅度减小，房室传导速度减慢，传导性降低（B错），即为负性变传导作用；心肌细胞2期平台期L型钙通道（ICa-L）介导的钙内流较少，收缩力降低（D错），即为负性变力作用。","","N"],["1995-N16",5,"第3节 胃内消化","内因子",1995,16,"A","","VitB₁₂是许多代谢过程所必需的，下列哪种情况不会引起其缺乏",[["A","慢性胃炎引起的胃酸缺乏"],["B","胃壁细胞的自身免疫性破坏"],["C","外科切除空肠"],["D","外科切除回肠"],["E","胃全切除"]],"C","慢性胃炎、胃壁细胞的自身免疫性破坏、胃全切除均可引起由胃壁细胞合成的内因子的缺乏，内因子的缺乏使维生素B₁₂失去保护而易被肠内水解酶破坏（ABE对）。虽然大部分消化产物在十二指肠和空肠被吸收，但回肠具有其独特的功能，即能主动吸收胆盐和维生素B₁₂，故外科切除回肠引起维生素B₁₂的缺乏（D 对）（C错，为本题正确答案）。","","N"],["1995-N17",3,"第1节 心脏的泵血功能","每搏输出量和射血分数",1995,17,"A","","某人氧耗量为300ml／分，动脉氧含量为20ml／100ml血，肺动脉氧含量为15ml／100ml血，心率为60次／分，试问他的每搏输出量是多少",[["A","1ml"],["B","10ml"],["C","60ml"],["D","100ml"],["E","200ml"]],"D","动脉血氧含量为20ml/100ml血，静脉血（肺动脉中流静脉血）氧含量为15ml/100ml血，即每100ml血可供氧5ml，氧耗量为300ml/分时，需要6000ml/分（心输出量）的血来供氧，若心率为60次/分，即需要100ml/次（每搏输出量）的血来供氧（D对）。","","N"],["1995-N18",1,"第4节 肌细胞的收缩","收缩总和",1995,18,"A","","下列关于心肌与骨骼肌的不同点的描述，哪项是正确的",[["A","只有心肌是由肌小节组成的"],["B","只有骨骼肌的收缩机制可用滑行理论解释"],["C","从心肌的长度-张力曲线关系中，看不出有最适初长度"],["D","骨骼肌的收缩是有等级性的，而心肌的收缩是“全或无”的"],["E","只有骨骼肌有粗、细两种肌丝"]],"D","骨骼肌和心肌统称为横纹肌，横纹肌都是由肌小节构成的（A错），都包含粗肌丝和细肌丝（E错），也都可以用肌丝滑行理论来解释（B错）。从心肌的长度-张力曲线关系图（十版生理学P84图4-3 心肌长度-张力关系曲线及其变化）可以看出，在一定范围心肌张力随初长度的增加而增大，但过度增加初长度则可使收缩张力下降，说明肌肉收缩存在最适初长度（C错）。骨骼肌的收缩是有等级性的：当收缩较弱时，仅有少量的和较小的运动单位发生收缩，随着收缩的增强，可有越来越多的和越来越大的运动单位参加收缩，产生的收缩张力也越来越大；而心肌的收缩是“全或无”的：心肌细胞要么同时收缩（全），要么都不收缩（无）（D对）。","","N"],["1995-N19",4,"第1节 肺通气","肺泡通气量",1995,19,"A","","潮气量为500ml，呼吸频率为12次／分，则肺泡通气量为",[["A","3L"],["B","4L"],["C","5L"],["D","6L"],["E","7L"]],"B","肺泡通气量=（潮气量-无效腔气量）×呼吸频率，已知潮气量为500ml，呼吸频率为12次/分，而正常人的无效腔气量约为150ml，则肺泡通气量=（500ml-150ml）×12=4200ml，即4.2升（B对）。","","N"],["1995-N20",4,"第2节 肺换气和组织换气","呼吸气体和人体不同部位气体的分压",1995,20,"A","","CO₂分压由高至低的顺序通常是",[["A","呼出气、肺泡气、组织细胞、静脉血"],["B","静脉血、呼出气、肺泡气、组织细胞"],["C","肺泡气、静脉血、组织细胞、呼出气"],["D","组织细胞、静脉血、肺泡气、呼出气"],["E","呼出气、组织细胞、静脉血、肺泡气"]],"D","气体分子在体内的一定是由分压高处向分压低处转移。CO₂分压由高到低依次为：组织细胞的细胞内液（CO₂由此处产生）＞组织液＞组织毛细血管血液＞静脉血液＞肺动脉内的混合静脉血＞肺泡气＞呼出气＞大气（D对）。","","N"],["1995-N21",6,"第2节 体温及其调节","体温的生理性波动",1995,21,"A","","运动时，下列哪一种叙述不正确",[["A","因潮气量和呼吸频率增加，引起肺泡通气量增加"],["B","由于每搏输出量和心率增加，引起心输出量增加"],["C","因蒸发散热增加导致体温下降"],["D","运动肌肉的小动脉舒张，而不参加运动的肌肉及内脏小动脉收缩"],["E","氧合血红蛋白解离曲线右移、增加氧的利用"]],"C","运动时肌肉活动能使代谢增强，产热量增加，虽然蒸发带走了部分热量，但整体上体温并不会下降（C错，为本题正确答案）。运动时机体代谢增高，呼吸系统、循环系统和运动系统都将发生一系列变化以适应增高了的机体代谢的需要：包括肺泡通气量增加（A对）、氧合血红蛋白解离曲线右移（E对）、心输出量增加（B对）、活动肌肉的小动脉舒张（D对）等。","","N"],["1995-N22",5,"第6节 大肠的功能","大肠运动的形式",1995,22,"A","","下列哪一种运动可以出现在结肠而不在小肠",[["A","分节运动"],["B","集团蠕动"],["C","紧张性收缩"],["D","0.5～2.0cm／s的蠕动"],["E","蠕动冲"]],"B","分节运动是小肠特有的运动形式（A错）。集团蠕动是结肠特有的运动形式（B对）。紧张性收缩是结肠和小肠共有的运动形式（C错）。0.5～2.0cm/s的蠕动在结肠和小肠内均存在（D错）。蠕动冲是小肠特有的运动形式（E错）。","","N"],["1995-N23",7,"第1节 肾的功能解剖和肾血流量","滤过膜的构成",1995,23,"A","","在肾小球滤液中几乎没有蛋白质，其原因是",[["A","所有血浆蛋白分子均较大，不能通过滤过膜上的孔"],["B","滤过膜上有带负电荷的涎基，可以排斥血浆蛋白"],["C","滤过膜上孔的大小和带负电荷的涎基两个因素共同作用"],["D","肾小球内皮细胞可将滤过的蛋白质主动重吸收"],["E","滤过膜中的内皮细胞层和基膜层有相同大小的网孔"]],"C","肾小球滤过膜由毛细血管内皮细胞、基膜和肾小囊脏层足细胞的足突构成，三层结构的孔径分别为70～90nm、2～8nm和4～11nm，以2nm为分界点，大于2nm的血浆蛋白不能通过滤过膜网孔，此为滤过膜的机械屏障，而小于2nm的小分子量蛋白质是可以通过滤过膜上的孔的（A错）；滤过膜的三层结构都是由带负电荷的蛋白质组成，因此带负电荷的物质不易通过滤过膜，此为滤过膜的电荷屏障。因此，肾小球滤过屏障包括机械屏障和电荷屏障，二者共同阻止血浆蛋白滤过（C对）。肾小球内皮细胞是滤过膜的组成结构，不是重吸收的结构，负责将滤过的蛋白质（少量小分子蛋白质）主动重吸收的是肾小管上皮细胞（D错）。滤过膜的内层是毛细血管内皮细胞，细胞上有许多直径为70～90nm的窗孔 ，基膜层上有直径为2～8nm的多角形网孔，二者网孔大小不同（E错）。B选项本身没有错，但C选项为最佳答案。","","N"],["1995-N24",9,"第4节 神经系统对内脏活动、本能行为和情绪的调节","副交感神经系统的功能",1995,24,"A","","下列哪项属于副交感神经的作用",[["A","瞳孔扩大"],["B","糖原分解增加"],["C","逼尿肌收缩"],["D","骨骼肌血管舒张"],["E","消化道括约肌收缩"]],"C","大多数副交感神经的节后纤维释放的递质是乙酰胆碱（少数节后纤维释放肽类和嘌呤类递质），因此副交感神经兴奋的症状即为M型或N型胆碱能受体被激活的症状。副交感神经兴奋时，作用于虹膜环行肌（又称瞳孔括约肌）的M受体使虹膜环行肌收缩，瞳孔缩小（A错）。作用于膀胱逼尿肌的M受体使逼尿肌收缩（C对）。作用于消化道括约肌的M受体使消化道括约肌舒张（E错）。交感神经系统兴奋时，可通过激活β₂受体促进糖原的分解增加（B错）。骨骼肌血管确实存在M型胆碱能受体，也接受乙酰胆碱（ACh）支配，可引起骨骼肌血管舒张，但此处释放ACh的是交感神经，而不是副交感神经（D错）。","","N"],["1995-N25",9,"第4节 神经系统对内脏活动、本能行为和情绪的调节","本能行为",1995,25,"A","","破坏下列哪一脑区，动物会出现食欲增加而逐渐肥胖",[["A","边缘叶"],["B","中脑网状结构"],["C","延脑背侧区"],["D","下丘脑外侧区"],["E","下丘脑腹内侧核"]],"E","摄食行为是人体的本能行为，摄食中枢和饱中枢共同参与摄食行为的调节。摄食中枢位于下丘脑外侧区（D错），破坏该区引起动物拒食，饱中枢位于下丘脑的腹内侧核，破坏此核则导致食欲增加而逐渐肥胖（E对）。边缘叶主要与嗅觉有关（十版生理学P278），中脑网状结构与觉醒的产生有关（十版生理学P330）。","","N"],["1995-N26",9,"第3节 神经系统对躯体运动的调控","牵张反射的感受器",1995,26,"A","","在整体中，当某一肌肉受到牵拉时将发生牵张反射，表现为",[["A","同一关节的协同肌抑制"],["B","同一关节的拮抗肌兴奋"],["C","受牵拉的肌肉收缩"],["D","其他关节的肌肉也同时收缩"],["E","伸肌和屈肌都收缩"]],"C","牵张反射包括腱反射和肌紧张，它是指有完整神经支配的骨骼肌在受外力牵拉伸长时引起的被牵拉的同一肌肉发生收缩的反射。它的感受器是肌梭，传入纤维是Ⅰa和Ⅱ类纤维，基本中枢位于脊髓，传出纤维是α和γ纤维，效应器是被牵拉的同一肌肉（C对）。","","N"],["1995-N27",8,"第1节 感觉概述","感受器的适应现象",1995,27,"A","","正常情况下，下列哪一种感受器最容易适应",[["A","肌梭"],["B","伤害性感受器"],["C","触觉感受器"],["D","内脏化学感受器"],["E","肺牵张感受器"]],"C","若以一个强度恒定的刺激持续作用于某一感受器，相应的感觉神经纤维上的动作电位频率将随刺激持续时间的延长而降低，这一现象称为感受器的适应。根据感受器发生适应的快慢，可将感受器分为快适应感受器和慢适应感受器两类。肌梭、伤害性感受器、内脏化学感受器、肺牵张感受器等均属于慢反应感受器。触觉感受器又称触压觉感受器（也有把触觉和压觉分开的），环层小体、麦斯纳小体、梅克尔盘和鲁菲尼小体均属于触觉感受器，环层小体、麦斯纳小体为快适应感受器，但梅克尔盘和鲁菲尼小体为慢适应感受器，笼统地说触觉感受器最容易适应是不严谨的。","","N"],["1995-N28",8,"第5节 平衡感觉","半规管",1995,28,"A","","冷水进入一侧耳内，可引起下列哪一变化，从而导致出现头晕和恶心等植物性（自主）功能改变",[["A","冷却了耳石器官"],["B","壶腹嵴的运动减弱"],["C","前庭传入神经放电增加"],["D","前庭传入神经放电减少"],["E","内淋巴液流动"]],"E","半规管是一种前庭器官，它的感受器是位于壶腹嵴的毛细胞，毛细胞的纤毛游离在内淋巴当中，它的适宜刺激是与纤毛发出处平面平行方向的机械力作用，半规管受到过强或长时间的刺激时，可通过前庭神经核与网状结构的联系引起自主神经功能失调，导致心率加快、血压下降、呼吸频率增加、出汗以及皮肤苍白、恶心、呕吐、唾液分泌增多等现象，称为前庭自主神经反应。冷水进入一侧耳内时，外耳道温度降低，温度的改变经鼓膜、鼓室及骨壁影响到外半规管，内淋巴液因热胀冷缩而改变比重，造成内淋巴液“热升冷降”的对流现象，使壶腹嵴的毛细胞纤毛发生弯曲（此过程不涉及头部空间位置的改变，并无壶腹嵴的运动改变）（B错），半规管受到刺激，出现头晕和恶心等植物性功能改变的症状（自主神经反应）（E对）。耳石器官是指椭圆囊和球囊，其适宜刺激为超速运动，而不是低温，低温不能有效刺激耳石器官导致其兴奋，进而引起自主神经功能改变（A错）。冷水进入侧耳引起内淋巴液流动，半规管受到刺激，前庭传入神经放电增加（D错），导致出现头晕和恶心等自主神经反应，因此C选项“前庭传入神经放电增加”本身是正确的，只不过前庭传入神经放电增加并不直接由冷水进入侧耳引起（C错）。","","N"],["1995-N29",8,"第3节 视觉","视杆细胞的感受器电位",1995,29,"A","","光线刺激视杆细胞可引起",[["A","Na⁺内流增加和超极化"],["B","Na⁺内流增加和去极化"],["C","Na⁺内流减少和超极化"],["D","Na⁺内流减少和去极化"],["E","K⁺外流停止和去极化"]],"C","视杆细胞是使人产生暗视觉的感光细胞，其静息电位约为-30～-40mV，在暗处时，视杆细胞主要存在两种电流：一是外段膜cGMP门控通道介导的Na⁺内流，二是内段膜非门控钾敏感通道介导的K⁺外流。光线刺激视杆细胞时，cGMP浓度下降，外段膜cGMP门控通道关闭，cGMP介导的Na⁺内流减小或消失，而内段膜非门控钾敏感通道继续开放，K⁺继续外流，于是膜电位向着K⁺的平衡电位（约-70mV）的方向变化，因而出现膜的超极化（相对于-30～-40mV）（C对）。","","N"],["1995-N30",7,"第3节 肾小管和集合管的物质转运功能","集合管",1995,30,"A","","肾脏维持水平衡的功能，主要靠调节下列哪项活动来实现",[["A","肾小球滤过量"],["B","近曲小管与髓袢的重吸收水量"],["C","远曲小管和集合管的重吸收水量"],["D","近曲小管和远曲小管的重吸收水量"],["E","肾小管的分泌功能"]],"C","肾脏维持水平衡的功能，主要靠调节集合管的重吸收水量来实现：当体内水过多时，血浆晶体渗透压降低，抗利尿激素的释放减少，使集合管对水的通透性降低（九版P245、十版P231抗利尿激素可促进集合管上形成水通道），导致水的重吸收减少；当体内缺水时，血浆晶体渗透压升高，抗利尿激素的释放增多，集合管对水的通透性增加，水的重吸收也增加。本题的参考答案为C，按照八版教材的观点（八版生理学P140、P257），远曲小管与集合管均对水具有通透性，均可通过抗利尿激素调节重吸收水量（C对），但是最新的九、十版教材则认为远曲小管并不具备对水的通透性，不能重吸收水，即按照九、十版教材观点，本题已无正确答案。","","N"],["1995-N31",6,"第2节 体温及其调节","辐射散热",1995,31,"A","","在常温下，机体散热的主要机制是",[["A","辐射"],["B","蒸发"],["C","出汗"],["D","不感蒸发"],["E","传导"]],"A","常温也叫一般温度或者室温，通常定义为25℃，远低于人体表面温度，人体散热方式主要为辐射、传导和对流，其中尤其以辐射散热为主（A对）。蒸发包括出汗和不感蒸发，为环境温度高于表层温度时的主要散热方式。","","N"],["1995-N67",7,"第1节 肾的功能解剖和肾血流量","肾单位",1995,67,"A","","关于肾单位，下列哪一项叙述不正确",[["A","是肾的解剖功能单位，双肾共200万个左右"],["B","由肾小体及与之相连的肾小管组成"],["C","肾小球由毛细血管网与肾小囊两部分组成"],["D","肾小管包括近端小管、髓袢细段及远端小管三部分"],["E","因肾小球多在皮质，亦称皮质肾单位，肾小管在髓质，故称髓旁肾单位"]],"E","肾单位是肾的解剖功能单位，人的每个肾中约有100万个肾单位，即双肾共有200万个肾单位（A对）。肾单位由肾小体及与之相连接的肾小管构成（B对）：①肾小体又由肾小球和肾小囊组成，肾小球则由入球小动脉和出球小动脉之间的一团彼此之间分支又再吻合的毛细血管网构成，故肾小球并不包含肾小囊（C错），二者是平行关系，共同构成了肾小体；②肾小管包括近端小管（包括近曲小管和髓袢降支粗段），髓袢细段和远端小管（包括远曲小管和髓袢升支粗段）（D错）。肾单位按其所在的部位可分为皮质肾单位和近髓肾单位（髓旁肾单位）两类：肾小体位于外皮质和中皮质的肾单位称为皮质肾单位，肾小体位于靠近髓质的内皮质层的为近髓肾单位（E错，为本题正确答案）。本题参考答案是E，实际上CD选项也是错的。","","N"],["1995-N97",10,"第5节 肾上腺内分泌","对组织器官活动的影响",1995,97,"B","","肾上腺切除的动物",[["A","血管平滑肌对儿茶酚胺的反应降低"],["B","体内水潴留"],["C","ACTH降低"],["D","血脂降低"],["E","血糖水平升高"]],"A","肾上腺是人体重要的内分泌腺，分皮质和髓质两部分，分别可分泌肾上腺皮质激素和肾上腺髓质激素，前者包括盐皮质激素（醛固酮）、糖皮质激素（皮质醇）和性激素（雄激素），后者包括肾上腺素和去甲肾上腺素。肾上腺被切除以后，肾上腺皮质激素和肾上腺髓质激素分泌消失，表现出缺乏症状：糖皮质激素（GC）对儿茶酚胺类激素（肾上腺素和去甲肾上腺素）有允许作用，能够增加血管平滑肌细胞肾上腺素能受体的数量，并使这些受体与儿茶酚胺的亲和力增加，糖皮质激素缺乏时，血管平滑肌对儿茶酚胺的反应降低（A对）；醛固酮具有保钠、保水和排钾的功能，醛固酮缺乏时，水排出增多（B错）；糖皮质激素可反馈性抑制腺垂体分泌ACTH（促肾上腺皮质激素），糖皮质激素缺乏时，抑制效应消失，ACTH分泌增多（C错）；糖皮质激素、肾上腺素和去甲肾上腺素均可促进脂肪分解，使血脂升高，肾上腺被切除后，这三种激素分泌均减少，血脂降低（D对）；糖皮质激素最重要的功能之一就是升高血糖，糖皮质激素缺乏时，血糖水平降低（E错）。故本题AD均正确，但给出的参考答案仅为A。","","N"],["1995-N98",10,"第6节 胰岛内分泌","对糖代谢的作用",1995,98,"B","","用药物破坏动物胰岛β细胞后",[["A","血管平滑肌对儿茶酚胺的反应降低"],["B","体内水潴留"],["C","ACTH降低"],["D","血脂降低"],["E","血糖水平升高"]],"E","胰岛β细胞被破坏将导致胰岛素分泌缺乏，机体表现出胰岛素缺乏的症状：胰岛素是体内唯一能直接降低血糖的激素，胰岛素分泌缺乏时血糖水平将显著升高（E对）；胰岛素可促进脂肪的合成与储存，抑制脂肪的分解和利用，降低血脂浓度，胰岛素分泌缺乏时将导致血脂升高（D错）。胰岛素与血管平滑肌对儿茶酚胺的敏感性、水代谢调节和ACTH分泌调节无关（ABC错）。","","N"],["1995-N99",11,"第2节 女性生殖功能及其调节","卵巢的生卵作用",1995,99,"B","","引起排卵的激素是",[["A","雌激素"],["B","孕激素"],["C","黄体生成素"],["D","卵泡刺激素"],["E","睾酮"]],"C","成熟卵泡在LH分泌高峰的作用下，向卵巢表面移动，卵泡壁破裂，出现排卵孔，卵细胞与透明带、放射冠及卵泡液排出，此过程称为排卵（C对）。","","N"],["1995-N100",11,"第1节 男性生殖功能及其调节","下丘脑－垂体－睾丸轴的调节",1995,100,"B","","起着始动生精作用的激素是",[["A","雌激素"],["B","孕激素"],["C","黄体生成素"],["D","卵泡刺激素"],["E","睾酮"]],"D","卵泡刺激素（FSH）起着始动生精的作用（D对）：FSH与支持细胞FSH受体结合后，促进支持细胞分泌雄激素结合蛋白（ABP），ABP与睾酮结合转运至曲细精管内，提高睾丸微环境中雄激素的局部浓度，有利于生精过程。睾酮起维持生精的作用（E错），黄体生成素（LH）起调节生精的作用（C错）。雌激素和孕激素与生精作用无关（AB错）。","","N"],["1995-N101",3,"第2节 心脏的电生理学及生理特性","心室肌细胞动作电位",1995,101,"B","","心室肌细胞动作电位的主要特点是",[["A","动作电位去极相有超射现象"],["B","复极时间长于去极时间"],["C","有复极2期平台期"],["D","有明显的4期自动去极化"],["E","动作电位的总时间长于骨骼肌"]],"C","心室肌的复极化过程比较缓慢，包括动作电位的1期、2期和3期三个阶段，1期又称快速复极初期，此期中仅发生部分复极，膜内电位由+30mV迅速下降至0mV左右，在1期复极化结束后进入2期，2期复极化过程开始变得非常缓慢，记录的动作电位图形较平坦，又称为平台期，平台期是心室肌细胞动作电位持续时间较长的主要原因，也是区别于神经细胞和骨骼肌细胞动作电位的主要特征（C对）。","","N"],["1995-N102",3,"第2节 心脏的电生理学及生理特性","窦房结细胞动作电位",1995,102,"B","","窦房结细胞动作电位的主要特点是",[["A","动作电位去极相有超射现象"],["B","复极时间长于去极时间"],["C","有复极2期平台期"],["D","有明显的4期自动去极化"],["E","动作电位的总时间长于骨骼肌"]],"D","窦房结为自律细胞，并且是自律性最高的自律细胞，自律细胞与心房肌、心室肌等工作细胞相比，其动作电位的主要特点是有明显的4期自动去极化（D对）。","","N"],["1995-N107",5,"第3节 胃内消化","促进胃液分泌的主要因素",1995,107,"B","","胃泌素产生于",[["A","壁细胞"],["B","主细胞"],["C","黏液细胞"],["D","G细胞"],["E","肥大细胞"]],"D","壁细胞分泌盐酸和内因子（A错）。主细胞分泌胃蛋白酶原（B错）。黏液细胞分泌黏液（C错）。G细胞分泌促胃液素（胃泌素）和ACTH样物质（D对）。肥大细胞分泌肝素、组胺、5-羟色胺等细胞炎性介质（E错）。","","N"],["1995-N108",5,"第3节 胃内消化","胃蛋白酶原",1995,108,"B","","胃蛋白酶原产生于",[["A","壁细胞"],["B","主细胞"],["C","黏液细胞"],["D","G细胞"],["E","肥大细胞"]],"B","胃蛋白酶原主要由胃泌酸腺的主细胞（B对）合成和分泌，颈黏液细胞、贲门腺和幽门腺的黏液细胞（C对）以及十二指肠近端的腺体也能分泌胃蛋白酶原。壁细胞分泌盐酸和内因子（A错）。G细胞分泌胃泌素和ACTH样物质（D错）。肥大细胞分泌肝素、组胺、5-羟色胺等细胞炎性介质（E错）。本题的正确答案应为BC，但给出的参考答案仅为B。","","N"],["1995-N123",3,"第3节 血管生理","血流阻力",1995,123,"C","","红细胞比容降低",[["A","通过动脉的血流量增加"],["B","血管阻力降低"],["C","两者皆有"],["D","两者皆无"]],"C","由于血流量与血流阻力成反比，血流阻力与又与血液黏滞度成正比，血液黏滞度又与红细胞比容（红细胞在血液中所占的容积百分比）的高低成正比。故红细胞比容降低→血液黏滞度降低→血流阻力降低→通过动脉的血流量增加（C对）。","","N"],["1995-N124",3,"第3节 血管生理","血流阻力",1995,124,"C","","血管舒张",[["A","通过动脉的血流量增加"],["B","血管阻力降低"],["C","两者皆有"],["D","两者皆无"]],"C","由于血流量与血流阻力成反比，血流阻力又与血管半径的4次方成反比，故血管舒张→血流阻力降低（B对）→通过动脉的血流量增加（A对）。本题AB均对，正确答案为C。","","N"],["1995-N141",10,"第4节 甲状旁腺、维生素D与甲状腺C细胞内分泌","维生素D的概述",1995,141,"X","","下列对维生素D的说法，何者是正确的",[["A","可看成是一种激素"],["B","由肾进行1α羟化"],["C","由肝进行1α及25位羟化"],["D","体内不能合成"]],"B","维生素D₃既可由肝、乳、鱼肝油等食物中获取，也可在紫外线照射下由皮肤合成（D错）。维生素D₃本身无生物活性，不可看成是一种激素（A错），维生素D₃需要在肝内25-羟化酶催化下生成25-羟维生素D₃，再经近端肾小管上皮细胞内1α-羟化酶的催化（B对C错），才能生成具有生物活性的激素1，25-二羟维生素D₃。","","N"],["1995-N143",9,"第3节 神经系统对躯体运动的调控","对侧伸肌反射",1995,143,"X","","较强烈的屈反射",[["A","有关的运动神经元有后放电"],["B","是多突触反射"],["C","由伤害性刺激引起"],["D","常常同时出现对侧伸反射"]],"ABCD","当脊动物一侧肢体的皮肤受到伤害性刺激（C对）时，受刺激的一侧的肢体出现屈曲反应，关节的屈肌收缩和伸肌舒张，称屈（肌）反射。随着刺激的加大，除引起同侧肢体屈曲外，还可引起对侧下肢的伸展，这称为对侧伸肌反射（D对）。屈反射的神经通路中存在环式联系，在刺激停止的最初一段时间，由于神经冲动通过环状联系反复兴奋，屈肌活动仍在进行，称为后放电（A对）。屈反射是一种多突触反射（B对），它的基本中枢在脊髓，可受高位中枢的调节，脊髓离断后该反射增强。","","N"],["1995-N144",3,"第3节 血管生理","影响组织液生成的因素",1995,144,"X","","下列哪些变化可以使组织间液增多",[["A","心衰引起的静脉压升高"],["B","肾病引起的蛋白尿"],["C","丝虫病引起的淋巴管阻塞"],["D","过敏反应引起的毛细血管通透性增高"]],"ABCD","在正常情况下，组织液的生成与回流保持动态平衡，因此组织液总量维持相对恒定。如果这种动态平衡遭到破坏，使组织液生成过多或重吸收减少，就有过多的液体潴留在组织间隙而形成水肿。影响组织液生成的因素包括：毛细血管有效流体静压、有效胶体渗透压、毛细血管壁通透性和淋巴回流。心衰引起的静脉压升高（A对）导致毛细血管有效流体静压增高，引起全身性水肿。肾病引起的蛋白尿（B对）可使血浆胶体渗透压降低，导致有效胶体渗透压下降，有效滤过压增大而发生水肿。丝虫病引起的淋巴管阻塞（C对）使淋巴回流受阻，含蛋白质的淋巴液就在组织间隙中积聚而形成淋巴水肿。过敏反应引起的毛细血管通透性增高（D对），血浆蛋白随液体渗出毛细血管，血浆胶体渗透压下降，组织胶体渗透压升高，有效滤过压增大，组织液生成增多而出现水肿。","","N"],["1995-N145",3,"第4节 心血管活动的调节","血管紧张素家族主要成员的生理作用",1995,145,"X","","可以引起血管平滑肌收缩的物质有",[["A","血管紧张素Ⅱ"],["B","前列腺素E"],["C","抗利尿激素"],["D","去甲肾上腺素"]],"ACD","血管紧张素Ⅱ是已知最强的缩血管活性物质之一，既可收缩动脉，又可收缩静脉（A对）。抗利尿激素又称血管升压素，作用于集合管上皮细胞可促进水的重吸收，起到抗利尿的作用，作用于血管平滑肌可引起血管收缩，血压升高（C对）。血管紧张素和血管升压素“顾名思义”就能知道具有收缩血管平滑肌，升高血压的作用。去甲肾上腺素属于儿茶酚胺类物质，循环血液中去甲肾上腺素大部分来自肾上腺髓质，小部分来自肾上腺能神经末梢，去甲肾上腺素作用于血管平滑肌的α受体引起血管收缩（D对）。前列腺素是存在于动物和人体中的一类不饱和脂肪酸组成的、具有多种生理作用的活性物质，根据结构不同，前列腺素分为A、B、C、D、E、F、G、H、I等类型，不同类型的前列腺素具有不同的功能，其中前列腺素E具有舒张血管（B错），降低血管外周阻力，降低血压，增加器官血流量的作用，目前被广泛应用于高血压肾病的治疗。","","N"],["1995-N146",0,"第6节 人体内自动控制系统","正反馈控制系统",1995,146,"X","","下列现象中，哪些存在着正反馈",[["A","肺牵张反射"],["B","排尿反射"],["C","神经纤维膜上达到阈电位时Na⁺通道的开放"],["D","血液凝固过程"]],"BCD","受控部分发出的反馈信息调整控制部分的活动，最终使受控部分朝着与它原来活动相反的方向改变，称为负反馈。肺牵张反射包括肺扩张反射和肺萎陷反射。肺扩张时，牵拉呼吸道，使牵张感受器受到刺激，其传入纤维为迷走神经中的有髓神经纤维，冲动传入延髓，经延髓和脑桥呼吸中枢的作用，促使吸气转换为呼气，肺扩张反射的生理意义在于加速吸气向呼气的转换，属于典型的负反馈；肺萎陷时，平滑肌内的感受器受到刺激，其结果是增强吸气活动或促进呼气转换为吸气，也属于负反馈。因此肺牵张反射不存在正反馈过程（A错）。排尿反射（B对）、神经纤维膜上达到阈电位时Na⁺通道的开放（C对）和血液凝固过程（D对）均属于正反馈。","","N"],["1996-N1",1,"第1节 细胞膜的物质转运功能","钠-钾泵",1996,1,"A","","细胞膜内外Na⁺和K⁺浓度差的形成和维持是由于",[["A","膜在安静时K⁺通透性大"],["B","膜在兴奋时Na⁺通透性增加"],["C","Na⁺和K⁺易化扩散的结果"],["D","膜上Na⁺-K⁺泵的作用"],["E","膜上ATP的作用"]],"D","细胞膜内、外Na⁺和K⁺浓度差是细胞发生电活动的基础，其形成和维持源自于膜上Na⁺-K⁺泵消耗能量逆浓度梯度吸入K⁺排出Na⁺的作用（D对）。","","N"],["1996-N2",1,"第3节 细胞的电活动","动作电位期间膜离子通透性的变化",1996,2,"A","","人工地增加细胞外液中Na⁺浓度时，单根神经纤维动作电位的幅度将",[["A","增大"],["B","减小"],["C","不变"],["D","先增大后减小"],["E","先减小后增大"]],"A","动作电位幅度=静息电位绝对值（接近于K⁺的平衡电位）+超射值（接近Na⁺的平衡电位）。增加细胞外液Na⁺浓度，会加大细胞外液与细胞内液之间的浓度差，Na⁺内流增多，超射值增大，动作电位的幅度也增大（A对）。","","N"],["1996-N3",1,"第3节 细胞的电活动","局部电位",1996,3,"A","","下列关于生物电的叙述中，哪一项是错误的",[["A","感受器电位和突触后电位的幅度可随刺激强度的增加而增大"],["B","感受器电位和突触后电位的幅度在产生部位较其周围大"],["C","感受器电位和突触后电位均可以总和"],["D","感受器电位和突触后电位的幅度比动作电位大"],["E","感受器电位和突触后电位都是局部电位"]],"D","感受器电位及突触后电位（包括兴奋性突触后电位和抑制性突触后电位）均属于局部电位的范畴（E对），具有局部电位的电学特征：幅度与刺激强度相关，可随刺激强度的增加而增大（A对）；传导呈衰减式，从产生局部电位的部位开始，随着传播距离的增大，局部电位的幅度下降，传播距离一般不超过1mm（B对）；由于局部反应没有不应期，多个局部反应可以在空间或时间上发生叠加和总和（C对）；局部电位去极化尚未达到阈电位水平，其幅度远远小于达到阈电位水平后继续去极化最终完成超射的动作电位（D错，为本题正确答案）。","","N"],["1996-N4",1,"第3节 细胞的电活动","动作电位",1996,4,"A","","下列关于神经纤维（单根）的描述中，哪一项是错误的",[["A","电刺激可以使其兴奋"],["B","阈刺激可以引起动作电位"],["C","动作电位是“全或无”的"],["D","动作电位传导时幅度可逐渐减小"],["E","动作电位传导的原理是局部电流学说"]],"D","尽管不同细胞的动作电位具有不同的形态，但所有动作电位都具有“全或无”及不衰减传播的特性（D错，为本题正确答案）。","","N"],["1996-N5",2,"第1节 血液生理概述","血细胞",1996,5,"A","","红细胞比容是指红细胞",[["A","与血浆容积之比"],["B","与白细胞容积之比"],["C","在血液中所占的重量百分比"],["D","异常红细胞与正常红细胞的容积百分比"],["E","在血液中所占的容积百分比"]],"E","血细胞在血液中所占的容积百分比称为血细胞比容（E对），红细胞在血液中所占的容积百分比即为红细胞比容，实际上，红细胞比容很接近血细胞比容，因为白细胞和血小板仅占血液总容积的0.15%～1%。","","N"],["1996-N6",3,"第2节 心脏的电生理学及生理特性","心肌细胞兴奋性的周期性变化",1996,6,"A","","心肌不会产生强直收缩的原因是",[["A","心脏是机能上的合胞体"],["B","心肌肌浆网不发达，Ca²⁺贮存少"],["C","心肌有自动节律性，会自动舒张"],["D","心肌呈“全或无”收缩"],["E","心肌的有效不应期特别长"]],"E","当肌肉接受一连串彼此间隔时间很短的连续兴奋冲动时，由于各个刺激间的时间间隔很短，后一个刺激都落在由前一刺激所引起的收缩尚未结束之前，就又引起下一次收缩，称强直收缩。强直收缩包括完全强直收缩和不完全强直收缩两种类型，当刺激频率比较高时，后一刺激引起的收缩落在前一收缩的收缩期内，肌肉将始终保持收缩状态，这种现象称为完全强直收缩。当刺激频率比较低时，后一刺激引起的收缩落在前一收缩的舒张期内，肌肉在收缩后有过短暂的舒张，但还未恢复到正常的舒张状况又进入下一次收缩，这种现象称为不完全强直收缩。骨骼肌细胞既可以产生完全强直收缩，也可以产生不完全强直收缩，心肌细胞由于有效不应期特别长（E对），一直延续到心肌收缩活动的舒张早期，因此不会发生完全强直收缩，但可能发生不完全强直收缩，故本题改为“心肌不会产生完全强直收缩的原因”更严谨一些。","","N"],["1996-N7",3,"第1节 心脏的泵血功能","心率",1996,7,"A","","正常人心率超过180次／分时，心输出量减少的原因主要是",[["A","心室充盈期缩短"],["B","快速射血期缩短"],["C","减慢射血期缩短"],["D","心室肌氧气供应不足"],["E","经减压反射调节后心缩力减弱"]],"A","在一定范围内，心率加快可使心输出量增加。当心率增快但尚未超过一定限度时，尽管此时心室充盈时间有所缩短，但由于静脉回心血量的大部分在快速充盈期内进入心室，因此心室充盈量和搏出量不会明显减少，而心率的增加可使每分输出量明显增加。但是，如果心率过快，当超过每分钟160～180次时，将使心室舒张期（充盈期）明显缩短（A对），心舒期充盈量明显减少，因此搏出量明显减少，从而导致心输出量下降。","","N"],["1996-N8",3,"第1节 心脏的泵血功能","心肌收缩能力",1996,8,"A","","心脏的等长调节是通过下列哪个因素对心脏泵血功能进行调节的",[["A","心肌初长度"],["B","肌小节的初长度"],["C","粗、细肌丝间横桥结合的数目"],["D","心脏收缩能力"],["E","心室舒张末期容积"]],"D","等长调节是指肌长度保持不变，但是收缩能力增加的调节方式（D对）。儿茶酚胺（去甲肾上腺素和肾上腺素）、钙增敏剂（如茶碱）、甲状腺激素等均可通过各种机制增强心肌的收缩能力，进行等长调节。与等长调节相对应的调节方式是异长调节，异长调节是指通过改变心肌细胞初长度而影响心肌收缩能力的调节方式，心肌初长度、肌小节的初长度、心室舒张末期容积均涉及心肌细胞初长度的改变，为异长调节的原因（ABE错）。心肌细胞初长度的改变本质上改变的是粗细肌丝间横桥结合的数目，故粗细肌丝间横桥结合的数目也为异长调节的原因（C错）。","","N"],["1996-N9",3,"第2节 心脏的电生理学及生理特性","心室肌细胞动作电位",1996,9,"A","","心室肌细胞动作电位平台期是下列哪些离子跨膜流动的综合结果",[["A","Na⁺内流、Cl⁻内流"],["B","Na⁺内流、K⁺外流"],["C","Na⁺内流、Cl⁻外流"],["D","Ca²⁺内流、K⁺外流"],["E","K⁺外流、Ca²⁺外流"]],"D","平台期即动作电位的2期，因复极化速度极其缓慢，膜电位几乎停滞于同一水平形成平台而得名。平台期的存在是心室肌细胞动作电位时程较长的主要原因，也是区别于神经、骨骼肌动作电位的主要特征。平台期之所以复极化速度缓慢，是因为复极化过程既有外向电流，又有内向电流，外向电流为Iₖ通道介导的延迟整流钾电流，内向电流为ICa-L通道介导的L型钙电流（D对）。注：在外向电流中，教材上还提到了Iₖ₁通道介导的内向整流钾电流，Iₖ₁通道的特性是只在静息电位水平或超极化状态下有较大的通透性，而在去极化状态下通透性较低，由于平台期处于复极化状态，故Iₖ₁通道介导的内向整流钾电流并未参与平台期的复极化过程，这也是造成平台期持续时间较长的重要原因。","","N"],["1996-N10",5,"第4节 小肠内消化","胰液的性质、成分和作用",1996,10,"A","","下列关于正常人胰液的叙述，哪一项是错误的",[["A","胰液的pH约为8"],["B","胰液的碳酸氢钠含量高"],["C","每天分泌量超过1000ml"],["D","胰液中含有羧基肽酶"],["E","胰液的分泌以神经调节为主"]],"E","胰液由胰腺的腺泡细胞和小导管管壁细胞所分泌，人每日分泌的胰液量为1000ml～2000ml（C对）。胰液中含有无机物和有机物：无机物中，水和HCO₃⁻、Cl⁻、Na⁺、K⁺、Ca²⁺等无机离子含量较高（B对），由于HCO₃⁻含量较高，胰液偏碱性，pH约为8（A对）；有机物主要由多种消化酶组成，包括胰淀粉酶、胰脂肪酶、胰蛋白酶、糜蛋白酶、羧基肽酶（D对）、核糖核酸酶、脱氧核糖核酸酶等，它是由腺泡细胞分泌的。胰液分泌受神经和体液双重控制，但以体液调节为主（E错，为本题正确答案），调节胰液分泌的体液因素主要有促胰液素和缩胆囊素。","","N"],["1996-N11",5,"第3节 胃内消化","胃蛋白酶原",1996,11,"A","","关于胃液分泌的描述，哪一项是错误的",[["A","壁细胞分泌盐酸"],["B","主细胞分泌胃蛋白酶"],["C","黏液细胞分泌糖蛋白"],["D","幽门腺分泌黏液"],["E","内因子由壁细胞分泌"]],"B","主细胞分泌的是胃蛋白酶原，而不是胃蛋白酶（B错，为本题正确答案），胃蛋白酶是由胃蛋白酶原进入胃腔后，在HCl的作用下，从酶原分子中脱去一个小分子肽段后形成的。","","N"],["1996-N12",7,"第4节 尿液的浓缩和稀释","肾髓质间液渗透浓度梯度的形成",1996,12,"A","","进入集合管的尿液是",[["A","低渗的"],["B","等渗的"],["C","高渗的"],["D","低渗或等渗，但不会是高渗的"],["E","等渗或高渗，但不会是低渗的"]],"D","肾小管液流经肾单位的顺序为：近曲小管→髓袢降支粗段→髓袢降支细段→髓袢升支细段→髓袢升支粗段→远曲小管→集合管。在近曲小管和髓袢降支粗段（二者合称近端小管）为等渗重吸收，小管液为等渗液；进入髓袢降支细段，小管液为高渗重吸收，渗透浓度开始升高，至髓袢反折处，小管液渗透浓度达到峰值；髓袢升支细段、髓袢升支粗段和远曲小管，均为通透NaCl而不通透水的低渗重吸收，小管液渗透浓度依次逐渐下降，至远曲小管时，小管液的渗透浓度降至最低。集合管上存在水通道蛋白（AQP），开始变得对水具有通透性，可以在抗利尿激素的调控下对水进行重吸收，这种重吸收是基于肾小管内外的渗透浓度梯度（基于小管液的渗透浓度低于管周组织液），又由于远曲小管位于皮髓质交界，该处组织液渗透浓度≤血浆渗透浓度，故小管液的渗透浓度在离开远曲小管进入集合管之前只能为低渗（小管液的渗透浓度<组织液渗透浓度≤血浆渗透浓度）（A对）。以上是基于九、十版教材的分析结果，但是，按照八版教材的观点（八版生理学P257），远曲小管与集合管一样可受抗利尿激素的调节而重吸收水，在这种情况下，经过远曲小管渗透作用重吸收水之后，小管液最多可以上升至等渗（等渗之后达到平衡，不可能为高渗），故认为小管液的渗透浓度在离开远曲小管进入集合管之前为低渗或等渗，但不会是高渗的（D对），当年给出的参考答案为D。","","N"],["1996-N13",4,"第3节 气体在血液中的运输","氧解离曲线",1996,13,"A","","正常人动脉血液中血红蛋白的氧饱和度为",[["A","100%"],["B","97%"],["C","87%"],["D","77%"],["E","67%"]],"B","正常人动脉血液中血红蛋白的氧饱和度约为97.4%（B对），混合静脉血液中血红蛋白的氧饱和度约为75%。","","N"],["1996-N14",4,"第4节 呼吸运动的调节","CO₂、H⁺、O₂对呼吸运动的调节",1996,14,"A","","正常人吸入下列哪种混合气体时，肺通气量增加最明显",[["A","21％O₂和79％N₂"],["B","17％O₂和83％N₂"],["C","2％CO₂和98％O₂"],["D","20％CO₂和80％O₂"],["E","30％CO₂和70％O₂"]],"C","吸入气中PO₂降低和PCO₂升高均可使呼吸运动反射性加深加快，尤其PCO₂升高是促进呼吸运动加深加快的最重要的生理性化学物质，但是PO₂过度降低时或PCO₂过度升高时则会抑制呼吸中枢，导致呼吸运动减弱。A选项21%O₂和79%N₂为正常的大气成分，吸入该混合气体肺通气量是不变的。B选项17%O₂和83%N₂为PO₂降低的混合气体，吸入该混合气体呼吸运动增强，肺通气量增加。C选项2%CO₂和98%O₂为PCO₂升高的混合气体，吸入该混合气体呼吸运动显著增强，肺通气量显著增加（C对）。D选项20%CO₂和80%O₂和E选项30%CO₂和70%O₂为PCO₂过度升高的混合气体，吸入该混合气体会抑制呼吸中枢，导致呼吸运动减弱（PCO₂＞15%时即可出现出现CO₂麻醉）。","","N"],["1996-N15",10,"第5节 肾上腺内分泌","对组织器官活动的影响",1996,15,"A","","糖皮质激素可以",[["A","抑制蛋白质分解"],["B","使血糖浓度降低"],["C","使肾脏排水能力降低"],["D","使血浆白蛋白含量减少"],["E","增强血管对儿茶酚胺的敏感性"]],"E","糖皮质激素的作用广泛而复杂（十版生理学P369-P371）：①糖皮质激素对体内糖、脂肪和蛋白质代谢均有明显影响：包括减少组织对糖的利用和加速肝糖异生而使血糖升高（B错），提高四肢部分的脂肪酶活性而促进脂肪分解，抑制肝外组织细胞合成蛋白质并促进蛋白质分解（A错），促进肝内组织细胞合成蛋白质使血浆白蛋白含量升高（D错）等；②参加应激反应，提高机体对有害刺激的耐受能力；③对组织器官活动的影响，如通过增加肾小球滤过率和抑制血管升压素分泌提高肾脏排水能力（C错）、通过允许作用增强血管对儿茶酚胺的敏感性（E对）等。","","N"],["1996-N16",11,"第3节 妊娠","胎盘的功能",1996,16,"A","","妊娠时维持黄体功能的主要激素是",[["A","雌激素"],["B","孕酮"],["C","卵泡刺激素"],["D","黄体生成素"],["E","绒毛膜促性腺激素"]],"E","未妊娠时，黄体（月经黄体）在排卵后9～10天开始退化，雌激素、孕激素分泌量逐渐减少，对腺垂体的负反馈作用减弱，FSH和LH分泌增加，以进入下一个卵巢周期；妊娠时，人绒毛膜促性腺激素（hCG）（E对）刺激月经黄体转变成妊娠黄体，继续分泌孕激素和雌激素，以适应妊娠的需要。","","N"],["1996-N17",8,"第3节 视觉","晶状体变凸",1996,17,"A","","当悬韧带放松时可使",[["A","晶状体曲度减小"],["B","晶状体曲度增大"],["C","角膜曲度增大"],["D","角膜曲度减小"],["E","瞳孔缩小"]],"B","当眼视近物时，可反射性地引起睫状肌收缩，导致连接于晶状体囊的悬韧带松弛，晶状体因其自身的弹性而向前和向后凸出，曲度变大（B对A错）。对于特定的个体来说，角膜曲度是固定值，不能调节（CD错）。瞳孔缩小是由瞳孔括约肌（虹膜环形肌）收缩引起（E错）。","","N"],["1996-N18",6,"第1节 能量代谢","间接测热法",1996,18,"A","","食物的氧热价是指",[["A","1g食物氧化时所产生的热量"],["B","1g食物燃烧时所产生的热量"],["C","食物氧化时消耗1L氧所产生的热量"],["D","氧化1g食物消耗1L氧所产生的热量"],["E","食物的物理卡价的同义语"]],"C","1g某种食物氧化时所释放的能量，称为这种食物的热价（A错）。1g食物燃烧时所产生的热量是该食物的物理热价（B错）。食物氧化时消耗1L氧所产生的热量为食物的氧热价（C对）。氧热价与物理热价（物理卡价）不是同一概念（E错）。氧化1g食物消耗1L氧时所释放的能量则无对应概念（D错）。（注：氧化1g某种食物所需要消耗的氧气量不一定是1L，十版生理学P198 表7-1氧化1g糖时消耗的氧气为0.83L，氧化1g蛋白质时消耗的氧气为0.95L，氧化1g脂肪时消耗的氧气为2.03L，所以当糖、蛋白质、脂肪以特定比例混合时，才会出现氧化1g食物消耗1L氧的情况，此时该食物的热价和氧热价相等）。","","N"],["1996-N23",10,"第4节 甲状旁腺、维生素D与甲状腺C细胞内分泌","对肾脏的作用",1996,23,"A","","PTH的作用为抑制",[["A","溶骨"],["B","肾小管对磷的重吸收"],["C","肠钙吸收"],["D","1，25-（OH）₂D₃的形成"],["E","腺苷酸环化酶的活性"]],"B","PTH（甲状旁腺激素）的靶器官主要是肾与骨，PTH与靶细胞的PTH受体结合后，激活腺苷酸环化酶（AC）（E错）和磷脂酶C（PLC），经AC-cAMP和PLC-IP₃/DG信号转导通路而产生调节作用（升血钙和降血磷）：①对肾脏的作用，一方面PTH可以促进肾远曲小管和集合管重吸收Ca²⁺，减少钙的排泄，升高血钙。另一方面PTH能抑制近端和远端小管重吸收Pi（B对），促进磷的排泄，降低血磷。此外，PTH还可激活肾近端小管细胞线粒体中的1α-羟化酶，激活25-OH-D₃转变为生物活性更高的1，25-（OH）₂D₃（钙三醇）（D错），进而间接促进小肠黏膜上皮细胞吸收钙（C错）和磷；②对骨的作用，PTH可作用于破骨细胞，增强溶骨作用（A错），释放Ca²⁺和Pi，也可以作用于成骨细胞，增强成骨作用，沉积Ca²⁺和Pi。","","N"],["1996-N93",2,"第2节 血细胞生理","红细胞的生理特征",1996,93,"B","","将血沉快的人的红细胞放入血沉正常的人的血浆中，红细胞的沉降率",[["A","增快"],["B","减慢"],["C","在正常范围"],["D","先不变后增快"],["E","先不变后减慢"]],"C","决定红细胞沉降率的因素不在红细胞本身，而在于血浆成分的变化。因此，将血沉快的人的红细胞放入血沉正常的人的血浆中，红细胞的沉降率在正常范围（C 对）。血浆中纤维蛋白原、球蛋白及胆固醇含量增高时，可加速红细胞叠连和沉降；血浆中白蛋白、卵磷脂的含量增多时则可抑制叠连的发生，使沉降率减慢（十版生理学P58）。","","N"],["1996-N94",2,"第2节 血细胞生理","红细胞的生理特征",1996,94,"B","","将血沉正常的人的红细胞放入血沉快的人的血浆中，红细胞的沉降率",[["A","增快"],["B","减慢"],["C","在正常范围"],["D","先不变后增快"],["E","先不变后减慢"]],"A","决定红细胞沉降率的因素不在红细胞本身，而在于血浆成分的变化。血浆中纤维蛋白原、球蛋白及胆固醇含量增高时，可加速红细胞叠连和沉降；血浆中白蛋白、卵磷脂的含量增多时则可抑制叠连的发生，使沉降率减慢（十版生理学P58）。","","N"],["1996-N95",3,"第3节 血管生理","影响动脉血压的因素",1996,95,"B","","外周阻力和心率不变而每搏输出量增大时，动脉血压的主要变化是",[["A","收缩压升高"],["B","舒张压升高"],["C","收缩压和舒张压升高幅度相同"],["D","收缩压降低、舒张压升高"],["E","收缩压升高、舒张压降低"]],"A","生理情况下，动脉血压的变化是多种因素综合作用的结果，为了便于分析，在讨论某一因素时，往往假定其他因素恒定不变。外周阻力和心率不变而每搏输出量增大时，动脉血压的收缩压和舒张压均升高，但主要是收缩压升高（A对）。","","N"],["1996-N96",3,"第3节 血管生理","影响动脉血压的因素",1996,96,"B","","每搏输出量和外周阻力不变而心率加快时，动脉血压的主要变化是",[["A","收缩压升高"],["B","舒张压升高"],["C","收缩压和舒张压升高幅度相同"],["D","收缩压降低、舒张压升高"],["E","收缩压升高、舒张压降低"]],"B","生理情况下，动脉血压的变化是多种因素综合作用的结果，为了便于分析，在讨论某一因素时，往往假定其他因素恒定不变。每搏输出量和外周阻力不变而心率加快时，动脉血压的收缩压和舒张压均升高，但主要是舒张压升高（B对）。","","N"],["1996-N97",4,"第3节 气体在血液中的运输","Hb与O₂结合的特征",1996,97,"B","","血液中，血红蛋白的氧含量是指",[["A","血红蛋白能结合的最大氧量"],["B","血红蛋白实际结合的氧量"],["C","血液氧含量占氧容量的百分比"],["D","氧扩散的总量"],["E","血浆中溶解的氧量"]],"B","在100ml血液中，Hb所能结合的最大O₂量称为Hb氧容量，而Hb实际结合的O₂量称为Hb氧含量（B对）。Hb氧含量与氧容量的百分比为Hb氧饱和度。通常情况下，血浆中溶解的O₂极少，可忽略不计，因此，Hb氧容量、Hb氧含量和Hb氧饱和度可分别视为血氧容量、血氧含量和血氧饱和度。","","N"],["1996-N98",4,"第3节 气体在血液中的运输","Hb与O₂结合的特征",1996,98,"B","","血液中，血红蛋白的氧容量是指",[["A","血红蛋白能结合的最大氧量"],["B","血红蛋白实际结合的氧量"],["C","血液氧含量占氧容量的百分比"],["D","氧扩散的总量"],["E","血浆中溶解的氧量"]],"A","在100ml血液中，Hb所能结合的最大O₂量称为Hb氧容量（A对）。1g Hb可结合的最大O₂量为1.39ml，正常时红细胞中含有少量不能结合O₂的高铁Hb，因此1g Hb实际结合的O₂量低于1.39ml，通常按1.34ml计算，血液中Hb浓度为15g/100ml时，Hb的氧容量为20.1ml/100ml（血液）。","","N"],["1996-N117",5,"第4节 小肠内消化","胰液的性质、成分和作用",1996,117,"C","","胰蛋白酶原激活的过程有",[["A","正反馈机制"],["B","负反馈机制"],["C","两者均有"],["D","两者均无"]],"A","胰蛋白酶原的激活过程属于典型的正反馈过程：肠液中的肠激酶激活胰蛋白酶原，使无活性的胰蛋白酶原变为有活性的胰蛋白酶，已被激活的胰蛋白酶也能激活胰蛋白酶原而形成正反馈（A对），加速其活化。胃蛋白酶原也有类似的正反馈过程：胃液中的胃酸激活胃蛋白酶原，使无活性的胃蛋白酶原变为有活性的胃蛋白酶，已被激活的胃蛋白酶激活胃蛋白酶原形成正反馈。","","N"],["1996-N118",11,"第2节 女性生殖功能及其调节","雌激素、孕激素的作用",1996,118,"C","","雌激素对促性腺激素的调节中有",[["A","正反馈机制"],["B","负反馈机制"],["C","两者均有"],["D","两者均无"]],"C","卵巢的周期性活动受下丘脑-腺垂体的调节，而卵巢分泌激素的周期性变化不但使子宫内膜发生周期性变化，还可以对下丘脑-腺垂体活动进行反馈调节（P411），包括第一次雌激素高峰的正反馈调节（P411）（A对）和第二次雌激素高峰的负反馈调节（P411）（B对）。第一次雌激素高峰通过正反馈机制促进LH大量分泌而形成LH峰，以促进排卵。第二次雌激素高峰则通过负反馈机制抑制GnRH、FSH和LH的分泌，以维持卵巢周期的正常进行。本题AB均对，正确答案为C。","","N"],["1996-N119",7,"第5节 尿生成的调节","血浆晶体渗透压",1996,119,"C","","一次饮0.9%盐水1000ml，可导致",[["A","尿比重明显增加"],["B","尿量明显减少"],["C","两者都有"],["D","两者都无"]],"D","一次性饮1000ml生理盐水，血浆晶体渗透压变化不大，但循环血量增多，可刺激心肺感受器，抑制血管升压素释放，使尿量增多（B错），又由于生理盐水与血浆晶体渗透压相近，不易吸收入血，所以尿量不会显著增加，而尿比重也不会有明显变化（A错）。本题AB均错，正确答案为D。","","N"],["1996-N120",7,"第5节 尿生成的调节","血浆晶体渗透压",1996,120,"C","","大量出汗时，可导致",[["A","尿比重明显增加"],["B","尿量明显减少"],["C","两者都有"],["D","两者都无"]],"C","由于汗液为低渗液（十版生理学P208），大量出汗后体内水的丢失多于氯化钠的丢失，引起血浆晶体渗透压升高，进而刺激抗利尿激素分泌增多，水重吸收增加，尿量减少（B对），比重增加（A对）。本题AB均对，正确答案为C。","","N"],["1996-N139",10,"第3节 甲状腺内分泌","下丘脑－腺垂体－甲状腺轴的调节",1996,139,"X","","下列哪些情况下促甲状腺激素分泌增多",[["A","切除一侧甲状腺后"],["B","在热环境中长期生存时"],["C","切断下丘脑与垂体的联系后"],["D","当食物中长期缺碘时"]],"AD","促甲状腺激素（TSH）由腺垂体分泌，其分泌水平受下丘脑（促甲状腺激素释放激素，TRH）-腺垂体（促甲状腺激素，TSH）-甲状腺（甲状腺素，TH）轴调节系统的调节。切除一侧甲状腺后，血中甲状腺激素水平下降，对促甲状腺激素的反馈抑制减弱，导致促甲状腺激素分泌增多（A对）。寒冷环境下，寒冷刺激沿上行的神经传导通路进入中枢神经系统，引起下丘脑释放促甲状腺激素释放激素（P220），后者再刺激腺垂体释放促甲状腺激素，使机体代谢率升高，产热增加，在热环境中长期生存时，缺少寒冷刺激，促甲状腺激素分泌减少（B错）。切断下丘脑与垂体的联系后，促甲状腺激素释放激素对促甲状腺激素的刺激效应被切断，促甲状腺激素分泌减少（C错）。当食物中长期缺碘时，甲状腺激素合成减少，对促甲状腺激素的负反馈抑制减弱，导致促甲状腺激素分泌增多（D对）。","","N"],["1996-N140",2,"第1节 血液生理概述","血浆渗透压",1996,140,"X","","血浆总渗透压",[["A","近似于7个大气压"],["B","与0.85％NaCl溶液的渗透压相等"],["C","主要由Na⁺和Cl⁻所形成"],["D","可维持毛细血管内外的水平衡"]],"ABC","血浆总渗透压为770 kPa，一个大气压为101kPa，血浆总渗透压为大气压的7.7倍，故近似于7个大气压的说法是对的（A对）。渗透压与血浆渗透压相等的溶液称为等渗溶液，浓度为0.85%-0.9%的NaCl溶液为等渗溶液（八版生理学数据为 0.85%，十版生理学数据为 0.9%，临床上实际应用0.9%NaCl 注射液作为等渗溶液更多一些）。由血浆中的电解质、葡萄糖、尿素等小分子晶体物质所形成的渗透压叫晶体渗透压，而在小分子物质中约80%来自Na⁺和Cl⁻（C对）。血浆总渗透压包括晶体渗透压和胶体渗透压两种（以前者为主），只有胶体渗透压可以维持毛细血管内外的水平衡（D错）。","","N"],["1996-N141",10,"第1节 内分泌与激素","内分泌",1996,141,"X","","激素传递的方式是",[["A","经血液运送"],["B","经组织液扩散"],["C","经腺体导管分泌"],["D","经神经轴浆运送到特定部位释放"]],"ABD","分泌是腺上皮组织的基本功能，分泌的方式表现为两种，即为外分泌和内分泌（十版生理学P337）。外分泌是腺泡细胞产生的物质通过腺体导管分泌（C错）到体内管腔或体外的分泌形式，如胰腺等消化腺将消化液分泌到消化管腔内发挥作用，这些腺体也统称为外分泌腺。内分泌是指腺细胞或神经细胞（经神经轴浆运送到特定部位释放）（D对）将产生的物质，即激素，通过血液（远距分泌）（A对）、组织液（旁分泌）（B对）等体液为媒介对靶细胞产生调节效应的一种分泌形式。","","N"],["1996-N142",4,"第4节 呼吸运动的调节","化学感受器",1996,142,"X","","贫血和一氧化碳中毒时，可携带氧的血红蛋白都减少，但并不引起呼吸加强，这是因为",[["A","颈动脉体血流量减少"],["B","动脉血液内总的氧含量仍维持在正常水平"],["C","动脉血氧分压在正常水平"],["D","颈动脉体化学感受器受到刺激"]],"C","外周化学感受器所感受的刺激是其所处环境动脉血PO₂的下降，而不是动脉血O₂含量的降低。贫血或CO中毒时，血红蛋白的携氧量下降，动脉血O₂含量的降低，但动脉血氧分压是正常的（动脉血氧分压来自肺泡气，所以只要外呼吸肺换气过程不出问题，动脉血氧分压总是正常的）（C对），所以并不引起呼吸加强。","","N"],["1997-N1",1,"第3节 细胞的电活动","动作电位",1997,1,"A","","下列有关同一细胞兴奋传导的叙述，哪一项是错误的",[["A","动作电位可沿细胞膜传导到整个细胞"],["B","传导方式是通过产生局部电流刺激未兴奋部位，使之出现动作电位"],["C","有髓纤维的跳跃传导速度与直径成正比"],["D","有髓纤维传导动作电位的速度比无髓纤维快"],["E","动作电位的幅度随直径增加而降低"]],"E","动作电位具有不衰减传播的特点，在传播过程中幅度和波形始终保持不变，与细胞的直径变化无关（E错，为本题正确答案），但是细胞的直径变化会影响动作电位的传播速度。一句话概括：直径影响速度不影响幅度；直径越大，传播速度越快。","","N"],["1997-N2",1,"第3节 细胞的电活动","动作电位",1997,2,"A","","下列关于神经纤维膜上Na⁺通道的叙述，哪一项是错误的",[["A","是电压门控的"],["B","在去极化达阈电位时，可引起正反馈"],["C","有开放和关闭两种状态"],["D","有髓纤维，主要分布在朗飞结处"],["E","与动作电位的去极相有关"]],"C","Na⁺通道属于电压门控通道（十版生理学P15）（A对），静息状态下，Na⁺通道的通透性很小，处于关闭状态，当细胞受到外来刺激时，Na⁺通道被激活，发生去极化（E对），去极化到阈电位水平，通过正反馈机制促进更多的Na⁺通道被激活（B对），发生动作电位，动作电位达到峰值之后，Na⁺通道逐渐进入失活状态，故Na⁺通道有关闭（静息）、开放（激活）和失活三种状态（C错，为本题正确答案）。有髓纤维的轴突具有胶质细胞反复包绕形成的髓鞘，有髓鞘包裹的轴突区域几乎没有钠通道，钠通道几乎全部集中在轴突的裸露区域，即郎飞结处（D对）。","","N"],["1997-N3",3,"第2节 心脏的电生理学及生理特性","心室肌细胞动作电位",1997,3,"A","","心室肌细胞动作电位平台期，主要是由哪些离子跨膜运动形成的",[["A","Na⁺内流，Cl⁻外流"],["B","Na⁺内流，K⁺外流"],["C","Na⁺内流，Cl⁻内流"],["D","Ca²⁺内流，K⁺外流"],["E","K⁺内流，Ca²⁺外流"]],"D","平台期即动作电位的2期，因复极化速度及其缓慢，膜电位几乎停滞于同一水平形成平台而得名。平台期的存在是心室肌细胞动作电位时程较长的主要原因，也是区别于神经、骨骼肌动作电位的主要特征。平台期之所以复极化速度缓慢，是因为复极化过程既有外向电流，又有内向电流，外向电流为Iₖ通道介导的延迟整流钾电流，内向电流为ICa-L通道介导的L型钙电流（D对）。注：在外向电流中，教材上还提到了Iₖ₁通道介导的内向整流钾电流，Iₖ₁通道的特性是只在静息电位水平或超极化状态下有较大的通透性，而在去极化状态下通透性较低，平台期即处于去极化状态，故Iₖ₁通道介导的内向整流钾电流并未参与平台期的复极化过程，这也是造成平台期持续时间较长的重要原因。","","N"],["1997-N4",1,"第3节 细胞的电活动","动作电位期间膜离子通透性的变化",1997,4,"A","","减少浸浴液中的Na⁺浓度，将使单根神经纤维动作电位的超射值",[["A","增大"],["B","减小"],["C","不变"],["D","先增大后减小"],["E","先减小后增大"]],"B","动作电位因Na⁺内流而产生（去极化），Na⁺内流可使膜电位的负值不断减小至零电位，并进一步变成正值，达到Na⁺的平衡电位，高于零电位的正值部分即为超射值。超射值的大小与Na⁺内流的数量有关，Na⁺内流越多，超射值越大，反之则越小。减小细胞外液Na⁺浓度，会缩小细胞外液与细胞内液之间的浓度差，Na⁺内流较少，超射值也减小（B对）。","","N"],["1997-N5",3,"第3节 血管生理","影响静脉回心血量的因素",1997,5,"A","","下列哪一种情况可使心输出量减少",[["A","阻断心脏迷走神经的传导"],["B","刺激心脏的交感神经"],["C","颈动脉窦内压力降低"],["D","心舒末期容积增加"],["E","由平卧转为站立"]],"E","心脏迷走神经对心脏起负性变时作用、负性变力作用、负性变传导作用，当阻断心脏迷走神经的传导，心脏收缩力增强（心房为主），心率加快，因而心输出量（心输出量=每搏输出量×心率）增多（A错）。心脏交感神经对心脏起正性变时作用、正性变力作用、正性变传导作用，当刺激心脏交感神经时，心脏收缩力增强，心率加快，心输出量增多（B错）。颈动脉窦压力降低，压力感受器传入冲动减少，压力感受性反射减弱，使交感神经紧张性增强，引起心率加快，心输出量增多（C错）。心舒末期容积增加，即前负荷增加，通过异长调节使心脏收缩力加强，每搏输出量增加，进而心输出量增加（D错）。由平卧位转为站立时，重力的作用使跨壁压升高，静脉充盈扩张，回心血量减少，前负荷减少，通过异长调节使心脏收缩力减弱，每搏输出量减小，最终心输出量减少（E对）。","","N"],["1997-N6",3,"第3节 血管生理","影响动脉血压的因素",1997,6,"A","","关于急性失血引起的变化，下列哪一项是错误的",[["A","动脉血压下降"],["B","红细胞的比容升高"],["C","心率加快"],["D","中心静脉压下降"],["E","皮肤苍白湿冷"]],"B","急性失血使得循环血量和静脉回心血量均减少，体循环平均充盈压降低，动脉血压下降，中心静脉压也下降（AD对），动脉血压下降使得压力感受器传入冲动减少，压力感受性反射减弱，导致心交感神经紧张加强，引起心率加快（C对）。急性失血会导致血液再分配，为保证重要器官的供血量，皮肤血管收缩，供血量减少，所以皮肤表现为苍白湿冷（E对）。红细胞在血液中所占的容积百分比称为红细胞比容，急性失血时，交感神经兴奋，毛细血管前阻力增大，组织液生成和尿量生成均减少，经过代偿之后，血容量得到一定程度恢复，但红细胞大量丢失导致红细胞比容下降（B错，为本题正确答案）。","","N"],["1997-N7",3,"第1节 心脏的泵血功能","心输出量和心指数",1997,7,"A","","在体循环和肺循环中，基本相同的是",[["A","收缩压"],["B","舒张压"],["C","脉压"],["D","外周阻力"],["E","心输出量"]],"E","正常人的体循环收缩压为100～120mmHg，舒张压为60-80mmHg，脉压为30～40mmHg；而肺循环收缩压平均约为22mmHg，舒张压0～1mmHg，脉压21～22mmHg（收缩压-舒张压）。故体循环的收缩压、舒张压和脉压均远远大于肺循环（ABC错）。肺动脉较主动脉管壁薄，并且肺动脉处于胸腔负压环境中，胸腔负压有利于肺动脉扩张，因此肺循环的外周阻力较体循环低（D错）。血液由左心室射出，经体循环回流至右心房，再由右心室射出，进入肺循环，故体循环和肺循环是相通的，故单位时间流经的血量是相同的，即心输出量是相同的（E对）。","","N"],["1997-N8",3,"第3节 血管生理","血流阻力",1997,8,"A","","血管对血流的阻力",[["A","当血管半径加倍时，降至原先阻力的1/2"],["B","当血管半径加倍时，降至原先阻力的1/8"],["C","取决于血管壁的厚度"],["D","在血液黏滞度升高时增大"],["E","和血管的长度无关"]],"D","血流阻力R=8ηL/πr⁴，其中η为血液黏度，L为血管长度，r为血管半径。由公式可知：当血管半径加倍时，血流阻力降低至原来的1/16（AB错）；血流阻力与血管壁厚度无关（C错）；血流阻力与血液黏度η成正比，血流阻力随着η的升高而增大（D对）；血流阻力与血管长度成正比（E错）。","","N"],["1997-N9",7,"第3节 肾小管和集合管的物质转运功能","小管液中溶质的浓度",1997,9,"A","","家兔静脉内注入20％葡萄糖10ml，尿量将增加，其原因是",[["A","肾小管液溶质浓度增高"],["B","肾小球滤过率增加"],["C","肾小球有效滤过压增高"],["D","ADH分泌减少"],["E","醛固酮分泌增多"]],"A","家兔静脉内注入20%葡萄糖10ml，尿量增加的原因是渗透性利尿，即由于血糖浓度升高而使超滤液中的葡萄糖超过近端小管对糖的最大转运率，造成小管液葡萄糖浓度升高（A对），渗透压升高，使小管内外渗透压梯度减小，从而使水和NaCl的重吸收减少，尿量增加，与肾小球滤过率和肾小球有效滤过压无关（BC错）。ADH（抗利尿激素）的释放主要受Na⁺和Cl⁻形成的晶体渗透压的刺激，与葡萄糖形成的晶体渗透压关系不大（十版生理学P231），并且即使葡萄糖形成的晶体渗透压能够刺激ADH的分泌，体内血糖浓度升高时，ADH应该分泌增多而不是减少（D错）。醛固酮的释放主要受肾素-血管紧张素系统及血钾、血钠浓度的影响，不受血糖浓度的影响（E错）。","","N"],["1997-N10",10,"第5节 肾上腺内分泌","下丘脑-垂体-肾上腺轴的调节",1997,10,"A","","关于ACTH分泌的调节，下列哪项是错误的",[["A","受下丘脑促皮质激素释放激素的调节"],["B","受肾上腺分泌糖皮质激素的反馈调节"],["C","受醛固酮的反馈调节"],["D","受下丘脑-垂体-肾上腺皮质轴调节"],["E","有与光照无关的日周期变化"]],"C","ACTH（促肾上腺皮质激素）由腺垂体分泌，受下丘脑分泌的促皮质激素释放激素（CRH）（A对）及肾上腺分泌的糖皮质激素（GC）（B对）的双重调控，即受下丘脑-垂体-肾上腺皮质轴调节（D对）。CRH的分泌由视交叉上核生物钟控制，CRH的分泌发生与光照无关的日周期变化，ACTH分泌也发生相应的日周期变化（E对）。在生理情况下，ACTH对醛固酮的分泌无明显影响，故不受醛固酮的反馈调节；发生应激反应时，ACTH可促进醛固酮分泌，但在应激反应条件下ACTH的分泌完全受控于上游的CRH，而不受下游反应产物的反馈调节（十版生理学P371）（C错，为本题正确答案）。","","N"],["1997-N11",1,"第1节 细胞膜的物质转运功能","主动转运",1997,11,"A","","肠上皮细胞由肠腔吸收葡萄糖，是属于",[["A","单纯扩散"],["B","易化扩散"],["C","主动转运"],["D","入胞作用"],["E","吞噬"]],"C","葡萄糖从肠道进入肠上皮细胞和从肾小管管腔进入肾小管上皮细胞的方式均是继发性主动转运（C对），葡萄糖进入其他细胞（如红细胞、脑细胞）则是通过经载体介导的易化扩散的形式。","","N"],["1997-N12",11,"第2节 女性生殖功能及其调节","月经周期的分期",1997,12,"A","","女性正常排卵的黄体",[["A","分泌孕酮"],["B","分泌雌激素"],["C","分泌黄体生成素"],["D","分泌孕酮及雌激素"],["E","分泌孕酮、雌激素和黄体生成素"]],"D","排卵后，卵巢周期进入黄体期，卵泡颗粒细胞和内膜细胞分别转化为颗粒黄体细胞和膜黄体细胞，黄体细胞在LH的作用下分泌孕激素（孕酮）和雌激素（D对）。黄体生成素（LH）由腺垂体分泌（十版生理学P338），而不由黄体细胞分泌。","","N"],["1997-N13",4,"第1节 肺通气","弹性阻力和顺应性",1997,13,"A","","下列关于肺泡表面活性物质的叙述，哪一项是错误的",[["A","能降低肺泡内衬液的表面张力"],["B","能增加肺的顺应性"],["C","当肺泡直径变小时，使肺泡内衬液的表面张力增加"],["D","当缺乏时，肺泡出现明显的萎陷"],["E","当缺乏时，间接的结果可能使体循环动脉血的pH下降"]],"C","肺表面活性物质可以降低肺泡表面张力（A对），降低肺弹性阻力，增加肺的顺应性（B对）。根据Laplace定律（十版生理学P141），肺泡的回缩力与肺泡半径成反比，即肺泡直径变小时的肺泡的回缩力增大，但是肺泡直径变小时，表面活性物质的密度也增大，降低表面张力的作用加强（C错，为本题正确答案），从而避免了小肺泡萎陷关闭而大肺泡过度膨胀的情况，保持了大小肺泡的稳定性。成年人患肺炎、肺血栓时，或新生儿肺泡Ⅱ型细胞尚未发育成熟时，均可因为肺表面活性物质缺乏而引起小肺泡萎陷关闭（D对），产生肺不张，引起通气不足，导致呼吸性酸中毒，当机体不能代偿时，可间接导致动脉血pH降低（E对）。","","N"],["1997-N14",6,"第1节 能量代谢","间接测热法",1997,14,"A","","食物的氧热价是指",[["A","1g食物氧化时所释放的能量"],["B","食物氧化消耗1L氧时所释放的能量"],["C","氧化1g食物消耗1L氧时所释放的能量"],["D","1g食物在体内代谢过程中所释放的能量"],["E","1g食物在体外燃烧时所产生的热量"]],"B","1g某种食物氧化时所产生的热量为食物的热价（A错）。1g食物在体内代谢过程时所产生的热量是食物的生物热价（D错）。1g食物燃烧时所产生的热量是食物的物理热价（E错）。食物氧化时消耗1L氧所产生的热量为食物的氧热价（B对）。氧化1g食物消耗1L氧时所释放的能量则无对应概念（C错）（注：氧化1g某种食物所需要消耗的氧气量不一定是1L，十版生理学P198 表7-1氧化1g糖时消耗的氧气为0.83L，氧化1g蛋白质时消耗的氧气为0.95L，氧化1g脂肪时消耗的氧气为2.03L，所以当糖、蛋白质、脂肪以特定比例混合时，才会出现氧化1g食物消耗1L氧的情况，此时该食物的热价和氧热价相等）。","","N"],["1997-N15",10,"第2节 下丘脑-垂体及松果体内分泌","血管升压素",1997,15,"A","","刺激视上核主要可引起",[["A","催产素释放减少"],["B","催产素释放增加"],["C","抗利尿激素释放减少"],["D","抗利尿激素释放增加"],["E","瞳孔扩大"]],"D","下丘脑视上核和室旁核的神经内分泌大细胞能合成抗利尿激素（血管升压素）和催产素（缩宫素），其中视上核以分泌抗利尿激素为主，室旁核以分泌催产素为主，故刺激视上核主要可引起抗利尿激素释放增加（D对）。","","N"],["1997-N16",9,"第1节 神经系统功能活动的基本原理","中枢兴奋传播的特征",1997,16,"A","","在中枢神经系统内，兴奋性化学传递的特征，哪一项是错误的",[["A","单向传递"],["B","中枢延搁"],["C","总和"],["D","兴奋节律不变"],["E","易受内环境改变的影响"]],"D","在中枢神经系统内，兴奋性化学传递明显不同于神经纤维上的冲动传导（十版生理学P300），其特征主要表现为以下几个方面：①单向传递：在反射活动中，兴奋经化学性突触传递，只能从突触前末梢传向突触后神经元，这一现象称为单向传播（A对）；②中枢延搁：兴奋在中枢传播时往往需要较长时间，这一现象称为中枢延搁（B对）；③总和：在反射活动中，单根神经纤维的传入冲动一般不能使中枢发出传出效应，需有若干神经纤维的传入冲动同时或几乎同时到达同一中枢，发生空间和时间的总和，才可能产生传出效应（C对）；④兴奋节律的改变：如果测定某一反射弧的传入神经（突触前神经元）和传出神经（突触后神经元）在兴奋传递过程中的放电频率，两者往往不同。这是因为突触后神经元常同时接受多突触前神经元的突触传递，突触后神经元自身的功能状态也可能不同，且反射中枢常经过多个中间神经元接替，因此最后传出冲动的频率（兴奋节律）取决于各种影响因素的综合效应，即在此过程中兴奋节律可能发生改变（D错，为本题正确答案）；⑤后发放与反馈；⑥对内环境变化敏感和易疲劳：因为突触间隙与细胞外液相通，因此内环境理化因素的变化，如缺氧、CO₂过多、麻醉剂以及某些药物等均可影响化学性突触传递（E对）。","","N"],["1997-N17",3,"第4节 心血管活动的调节","延髓",1997,17,"A","","平时维持交感缩血管纤维紧张性活动的基本中枢位于",[["A","大脑"],["B","下丘脑"],["C","中脑和脑桥"],["D","延髓"],["E","脊髓中间外侧柱"]],"D","中枢神经系统中与控制心血管活动有关的神经元集中的部位称为心血管中枢，控制心血管活动的神经元广泛分布于从脊髓到大脑皮层的各个水平，其中延髓（延脑）是调控心血管活动最重要的心血管中枢部位（D对）。交感缩血管中枢是延髓心血管中枢的一部分。","","N"],["1997-N18",2,"第2节 血细胞生理","白细胞的分类及数量",1997,18,"A","","关于淋巴细胞的叙述，哪一项是错误的",[["A","占白细胞总数的20％～40％"],["B","B淋巴细胞与体液免疫有关"],["C","T淋巴细胞与细胞免疫有关"],["D","B淋巴细胞从骨髓迁移，在胸腺中胸腺激素的作用下发育成熟"],["E","T淋巴细胞寿命较长，可达数月至1年以上"]],"D","淋巴细胞是白细胞的一种，绝对数量为（0.8～4）×10⁹/L，占白细胞总数量（3.5～9.5）×10⁹/L的20%～40%（A对），根据淋巴细胞的发育部位、表面抗原及功能特点等不同，可将淋巴细胞分为B淋巴细胞和T淋巴细胞，B淋巴细胞和T淋巴细胞均由骨髓中的造血干细胞分化而来，B细胞留在骨髓内发育成熟（D错，为本题正确答案），而T细胞则迁移至胸腺最终发育成熟，正因为如此，B细胞的全称为骨髓（Bonemarrow）依赖性淋巴细胞，T细胞的全称为胸腺（Thymus）依赖性淋巴细胞，B和T分别为Bonemarrow和Thymus的首字母缩写。B细胞是通过产生抗体起作用，抗体存在于体液里，所以B细胞的免疫作用叫做“体液免疫”（B对），T细胞不产生抗体，而是直接起作用，所以T细胞的免疫作用叫做“细胞免疫”（C对）。B淋巴细胞寿命较短，一般3～5天，T淋巴细胞寿命较长，可达数月至一年以上（E对）。","","N"],["1997-N93",2,"第1节 血液生理概述","血浆渗透压",1997,93,"B","","血浆胶体渗透压主要来自",[["A","葡萄糖"],["B","Na⁺"],["C","K⁺"],["D","球蛋白"],["E","白蛋白"]],"E","溶质渗透压的高低取决于溶液中溶质颗粒数目的多少，而与溶质的种类和颗粒的大小无关。由血浆蛋白等胶体物质所形成的渗透压叫胶体渗透压，在血浆蛋白中，白蛋白的分子量小，其分子数量远多于球蛋白，故血浆胶体渗透压主要来自白蛋白（E对）。","","N"],["1997-N94",2,"第1节 血液生理概述","血浆渗透压",1997,94,"B","","血浆晶体渗透压主要来自",[["A","葡萄糖"],["B","Na⁺"],["C","K⁺"],["D","球蛋白"],["E","白蛋白"]],"B","溶质渗透压的高低取决于溶液中溶质颗粒数目的多少，而与溶质的种类和颗粒的大小无关。由血浆中的电解质、葡萄糖、尿素等小分子晶体物质所形成的渗透压叫晶体渗透压，而在小分子物质中约80%来自Na⁺和Cl⁻，故晶体渗透压主要来自Na⁺和Cl⁻（B对）。","","N"],["1997-N95",9,"第3节 神经系统对躯体运动的调控","牵张反射的感受器",1997,95,"B","","脊髓动物实现的骨骼肌牵张反射",[["A","传出神经为到骨骼肌的Aα纤维"],["B","传出神经为到骨骼肌的Aγ纤维"],["C","传入纤维为C类纤维"],["D","传入纤维为B类纤维"],["E","传入纤维为Aβ类纤维"]],"A","牵张反射是指有完整神经支配的骨骼肌在受外力牵拉伸长时引起的被牵拉的同一肌肉发生收缩的反射。牵张反射发生的过程：当肌肉受外力牵拉而使肌梭感受装置被拉长时，螺旋形末梢发生变形而引起Ⅰₐ类纤维传出冲动增加，肌梭的传入冲动增加可引起支配同一肌肉的α运动神经元兴奋，使梭外肌收缩，从而形成一次牵张反射。所以牵张反射的传入纤维是Ⅰₐ类纤维（相当于Aα类），传出纤维是由α运动神经元兴奋发出Aα类纤维（A对）。","","N"],["1997-N96",8,"第2节 躯体和内脏感觉","痛觉信息的感受和传导",1997,96,"B","","完整动物的内脏疼痛反射",[["A","传出神经为到骨骼肌的Aα纤维"],["B","传出神经为到骨骼肌的Aγ纤维"],["C","传入纤维为C类纤维"],["D","传入纤维为B类纤维"],["E","传入纤维为Aβ类纤维"]],"C","疼痛是常见的临床症状，根据发生部位不同，可以分为躯体痛和内脏痛，内脏痛发生缓慢，持续时间长，即主要表现为慢痛，其传入纤维为传导较慢的C类无髓纤维（C对）。内脏疼痛反射的效应可以有多种，例如恶心、呕吐、肌肉紧张、肌肉收缩等，所以其传出神经并不一定是到骨骼肌的Aα或Aγ纤维（AB错）。","","N"],["1997-N97",8,"第3节 视觉","感光细胞及其特征",1997,97,"B","","视网膜上既无视锥也无视杆细胞的部位是",[["A","视盘"],["B","视盘的周边部"],["C","中央凹"],["D","中央凹周边部"],["E","视网膜周边部"]],"A","视网膜上既无视锥也无视杆细胞的部位是视盘（A对），视盘又称为视神经乳头，是视神经起始处的一境界清楚略呈椭圆形的盘状结构，此处有视网膜中央动静脉穿过。","","N"],["1997-N98",8,"第3节 视觉","感光细胞及其特征",1997,98,"B","","视网膜上仅有视锥细胞的部位是",[["A","视盘"],["B","视盘的周边部"],["C","中央凹"],["D","中央凹周边部"],["E","视网膜周边部"]],"C","不同感光细胞在视网膜中的分布不同，视杆细胞主要分布于视网膜的周边部，而视锥细胞主要分布于视网膜的中央凹处（C对）。视锥细胞对光的敏感性较低，但视物时可辨别颜色，且对被视物的细节具有较高的分辨能力，所以中央凹处对颜色和被视物细微结构的分辨能力最强。","","N"],["1997-N117",9,"第4节 神经系统对内脏活动、本能行为和情绪的调节","交感神经系统的功能",1997,117,"C","","交感神经的作用有",[["A","支气管平滑肌收缩"],["B","膀胱逼尿肌收缩"],["C","两者均有"],["D","两者均无"]],"D","大多数交感节后纤维释放的递质是去甲肾上腺素（除支配汗腺和骨骼肌血管的交感节后纤维释放乙酰胆碱外），交感神经系统的活动与各器官上去甲肾上腺素受体的分布有关，交感神经兴奋时，作用于膀胱逼尿肌的β₂受体使逼尿肌舒张（B错）。作用于支气管平滑肌的β₂受体使支气管平滑肌舒张（A错）。本题AB均错，正确答案为D。","","N"],["1997-N118",9,"第4节 神经系统对内脏活动、本能行为和情绪的调节","副交感神经系统的功能",1997,118,"C","","副交感神经的作用有",[["A","支气管平滑肌收缩"],["B","膀胱逼尿肌收缩"],["C","两者均有"],["D","两者均无"]],"C","大多数副交感神经的节后纤维释放的递质是乙酰胆碱（少数节后纤维释放肽类和嘌呤类递质），因此副交感神经兴奋的症状即为M型或N型胆碱能受体被激活的症状。副交感神经兴奋时，作用于支气管平滑肌的M受体使支气管平滑肌收缩（A对）；作用于膀胱逼尿肌的M受体使逼尿肌收缩（B对）。本题AB均对，正确答案为C。","","N"],["1997-N119",4,"第4节 呼吸运动的调节","CO₂、H⁺、O₂对呼吸运动的调节",1997,119,"C","","低氧引起呼吸兴奋，主要是直接作用于",[["A","延髓呼吸中枢"],["B","中枢化学感受器"],["C","两者均是"],["D","两者均不是"]],"D","化学感受器是指其适宜刺激是 O₂ 、CO₂和 H⁺等化学物质的感受器。根据所在部位的不同，化学感受器分为外周化学感受器和中枢化学感受器两种。外周化学感受器位于颈动脉体和主动脉体，在动脉血 PO₂ 降低、PCO₂ 或H⁺ 浓度升高时均受到刺激，反射性地引起呼吸中枢兴奋。中枢化学感受器位于延髓腹外侧部的浅表部位，生理性刺激是脑脊液中的 H⁺，动脉血 H⁺ 浓度升高时，H⁺ 通过血 - 脑屏障进入脑脊液发挥作用（但进入速度较慢，限制了H⁺ 对中枢化学感受器的作用），动脉血 PCO₂ 升高时，血液中的 CO₂ 能够通过血 - 脑屏障，间接引起脑脊液H⁺ 浓度升高，从而刺激中枢化学感受器，引起呼吸中枢兴奋。因此，低氧对呼吸运动的刺激作用完全是通过刺激外周化学感受器实现的（AB 错），CO₂ 和H⁺ 对呼吸运动的刺激作用则可以通过中枢化学感受器和外周化学感受器共同实现。低氧对延髓呼吸中枢的直接作用是抑制的。本题 AB 均错 ， 正确答案为 D。","","N"],["1997-N120",4,"第4节 呼吸运动的调节","CO₂、H⁺、O₂对呼吸运动的调节",1997,120,"C","","二氧化碳过多引起呼吸兴奋，主要是通过刺激",[["A","延髓呼吸中枢"],["B","中枢化学感受器"],["C","两者均是"],["D","两者均不是"]],"B","中枢化学感受器虽然也位于延髓中，但和延髓呼吸中枢是两回事，二者分别对应神经反射弧中的感受器和神经中枢。二氧化碳增多时刺激是感受器，而非神经中枢（B对A错）。","","N"],["1997-N139",2,"第3节 生理性止血","血液凝固",1997,139,"X","","正常机体血液在血管内不凝固的原因是",[["A","血液流动快"],["B","血管内膜光滑完整"],["C","纤维蛋白溶解系统的作用"],["D","有抗凝物质存在"]],"ABCD","正常人在日常活动中常发生轻微的血管损伤，体内也常有低水平的凝血系统的激活，但循环血液并不凝固。即使当组织损伤而发生生理性止血时，止血栓也只局限于损伤部位，并不延及周围未损伤部位。这表明体内的生理性凝血过程在时间和空间上都受到严格的控制，并且是多因素综合作用的结果：正常机体血液流动快，进入循环的活化的凝血因子不容易在局部聚集，血流稀释作用强，不利于血液凝固的发生（A对）。血管内膜光滑完整，可防止凝血因子、血小板与内皮细胞下的成分接触，从而避免凝血系统的激活和血小板的活化（B对）。纤维蛋白溶解系统（纤溶系统）可以将纤维蛋白和纤维蛋白原分解为可溶性小肽而发生抗凝作用（C对）。人体内存在大量的抗凝物质，包括丝氨酸蛋白酶抑制物、蛋白质C系统和组织因子途径抑制物等（D对）。","","N"],["1997-N140",3,"第5节 器官循环","冠脉循环的生理特点",1997,140,"X","","在下列哪些情况下，冠状动脉血流量增多",[["A","动脉舒张压升高"],["B","主动脉瓣闭锁不全"],["C","心室舒张期延长"],["D","心搏频率增加"]],"AC","动脉舒张压的高低和心舒期的长短是影响CBF的重要因素。舒张压越高，舒张期越长，冠脉血流量越多，故舒张压升高和舒张期延长时，冠状动脉血流量增多（AC对）。心搏频率增加时舒张期缩短，主动脉瓣关闭不全时则舒张压降低，此二者情况均导致冠脉血流量下降（BD错）。","","N"],["1997-N141",5,"第3节 胃内消化","盐酸",1997,141,"X","","向十二指肠内注入大量HCl可引起",[["A","肠液分泌"],["B","胃液分泌"],["C","胰液与胆汁大量分泌"],["D","胃运动增强"]],"AC","向十二指肠内注入大量HCl所引起的生理学效应与胃酸增多类似。胃酸增多时可抑制胃酸分泌（B错），可促进肠液、胰液和胆汁分泌（AC对），可使胃运动减弱（D错）等。","","N"],["1997-N142",5,"第4节 小肠内消化","胆汁的作用",1997,142,"X","","下列关于胆汁的描述，哪些是正确的",[["A","胆盐是血红蛋白的代谢产物"],["B","肠对胆盐的重吸收导致胆汁进一步分泌"],["C","脂肪的消化吸收需要一定浓度的胆盐"],["D","NaCl自胆囊的主动转移出去是胆汁在胆囊内借以浓缩的机制"]],"BCD","胆盐是初级胆汁酸或次级胆汁酸与钠离子或钾离子形成的钠盐或钾盐（十版生物化学与分子生物学P470），初级胆汁酸在肝内以胆固醇为原料生成，次级胆汁酸由肠道内肠菌作用于初级胆汁酸而生成（A错）。血红蛋白的代谢产物是胆红素（十版生物化学与分子生物学P474）。","","N"],["1998-N1",0,"第6节 人体内自动控制系统","负反馈控制系统",1998,1,"A","","维持机体稳态的重要调节过程是",[["A","神经调节"],["B","体液调节"],["C","自身调节"],["D","正反馈调节"],["E","负反馈调节"]],"E","神经调节、体液调节和自身调节属于生理功能的调节方式（十版生理学P8），负反馈调节和正反馈调节属于反馈控制系统（十版生理学P10），调节方式与反馈控制系统之间的关系十分微妙，为了方便记忆，可进行如下理解：神经调节、体液调节和自身调节是人体对各种功能活动进行调节的三种调节方式，经过这三种调节方式的调节之后，会呈现两种结果，一种结果是受控部分的活动朝着与它原先活动相反的方向改变，称为负反馈调节，负反馈调节极为多见，在机体生理功能稳态的维持中发挥重要作用（E对），如动脉血压的压力感受性反射（属于神经调节）（十版生理学P122）、胰岛素的降糖作用（属于体液调节）（十版生理学P374）、动脉血压的肌源性自身调节（属于自身调节）（十版生理学P128）等；另外一种结果是使受控部分的活动朝着与它原先活动相同的方向改变，称为正反馈调节，正反馈调节相对少见，并且没有纠正偏差的功能，一般对稳态的维持不发挥作用，正反馈调节的主要意义在于促进某一生理活动的正常进行，如排尿反射（属神经调节）（十版生理学P239）、排卵前夕雌激素对LH的促分泌作用（属体液调节）（十版生理学P389）、蛋白酶原的激活（属自身调节）等。具体到本题，神经调节、体液调节和自身调节大多数情况下介导了负反馈调节，参与了机体内环境稳态的维持；在少数情况下介导了正反馈调节，促进了某一生理活动的正常进行。","","N"],["1998-N2",1,"第1节 细胞膜的物质转运功能","经载体的易化扩散",1998,2,"A","","葡萄糖从细胞外液进入红细胞内属于",[["A","单纯扩散"],["B","经通道易化扩散"],["C","经载体易化扩散"],["D","主动转运"],["E","入胞作用"]],"C","除进入肠黏膜上皮细胞和肾小管上皮细胞属于继发性主动转运外，葡萄糖进入其他细胞均属于经载体介导的易化扩散，其中最典型的代表是红细胞和脑细胞（C对）。","","N"],["1998-N3",1,"第1节 细胞膜的物质转运功能","钠-钾泵",1998,3,"A","","细胞膜内、外，正常的Na⁺和K⁺浓度差的维持主要是由于",[["A","膜在安静时对K⁺的通透性高"],["B","膜在兴奋时对Na⁺的通透性增加"],["C","Na⁺、K⁺易化扩散的结果"],["D","膜上Na⁺-K⁺泵的作用"],["E","膜上ATP的作用"]],"D","细胞膜内、外Na⁺和K⁺浓度差是细胞发生电活动的基础，其形成和维持源自于膜上Na⁺-K⁺泵消耗能量逆浓度梯度吸入K⁺排出Na⁺的作用（D对）。","","N"],["1998-N4",9,"","",1998,4,"A","","从信息论的观点看，神经纤维所传导的信号是",[["A","递减信号"],["B","高耗能信号"],["C","模拟信号"],["D","数字式信号"],["E","易干扰信号"]],"D","神经纤维通过产生动作电位来传导电信号，因此神经纤维所传导的信号既有神经纤维传导兴奋的特征，又具备动作电位的一般特点：动作电位是不衰减传播的（A错）；神经纤维分为有髓神经纤维和无髓神经纤维两种，其中有髓神经纤维动作电位以跳跃式进行传导，耗能较低（B错）；模拟信号是指用连续变化的物理量所表达的信息，又称为连续信号，如我们感受器官所感受到的光，声音，压力等外界刺激都为模拟信号。而数字式信号在取值上是离散的，不连续的信号，例如计算机编程所用的脉冲信号。神经纤维上的动作电位是“全或无”的、不连续的，类似于计算机语言中的“0”或“1”，所以神经纤维所传导的信号是数字式信号而不是模拟信号（D对）。","","N"],["1998-N5",3,"第1节 心脏的泵血功能","心肌异长自身调节",1998,5,"A","","异长调节是指心脏的每搏输出量取决于",[["A","平均动脉压"],["B","心率贮备"],["C","心力贮备"],["D","心室舒张末期容积"],["E","心室收缩末期容积"]],"D","通过改变心肌初长度而引起心肌收缩力改变的调节，称为异长调节。对中空球形的心脏来说，心室肌的初长度决定于心室舒张末期的容积（D对）。","","N"],["1998-N6",3,"第2节 心脏的电生理学及生理特性","决定和影响自律性的因素",1998,6,"A","","下列哪项可用来衡量心肌自动节律性的高低",[["A","动作电位的幅值"],["B","最大复极电位水平"],["C","自动兴奋的频率"],["D","阈电位水平"],["E","4期膜电位自动去极化速率"]],"C","自律性是指心肌细胞在没有外来刺激情况下自动兴奋的特性，自律性的高低即自动兴奋频率的高低（C对），但是自律性的高低主要取决于4期自动去极化的速率，所以E选项也应该算正确答案（如2012N8A）。自律性的高低也受最大复极电位与阈电位之间差距的影响，最大复极电位的绝对值减小，或阈电位水平下移，都能使二者之间的差距缩短，进而使自动去极化达到阈电位水平所需的时间减少，最终导致自律性增高，反之则自律性降低。但是单独就最大复极电位水平或阈电位水平而言，并不足以用来衡量心肌自动节律性的高低，所以B和D不能算正确答案。动作电位的幅值即动作电位的超射值（最大值），与心肌自动节律性的高低无关（A错）。","","N"],["1998-N7",3,"第3节 血管生理","微循环",1998,7,"A","","关于微动脉，下列哪一项是错误的",[["A","在调节动脉血压中起主要作用"],["B","在调节器官血流量中起主要作用"],["C","其管壁的可扩张性比中动脉的大"],["D","收缩时，组织液的生成量减少"],["E","其管壁平滑肌的张力主要受局部代谢产物调节"]],"E","所有血管类型中，微动脉对血流的阻力最大，构成循环系统的外周阻力的主要部分。微动脉收缩时，外周阻力增加，心舒期血液流向外周的速度减慢，心舒期末存留在主动脉中的血量增多，故舒张压升高，由于舒张期末存留的血量增多，致使心缩期主动脉内血量增多，收缩压也相应升高。微动脉舒张时则相反。故微动脉在调节动脉血压中起重要作用（A对）。血管的可扩展性是指血管跨壁压改变时血管容积可以发生相应的改变，血管的可扩展性可用顺应性来表示，血管的顺应性与血管的初始容积有关，血管的初始容积愈小，可扩张性就愈大，微动脉的初始容积比中动脉小，故微动脉的可扩张性比中动脉大（C对）。微动脉受神经调节（微动脉是交感缩血管神经纤维分布密度最高的血管类型）、体液调节和自身调节（包括代谢性自身调节和肌源性自身调节两类）等三大调节方式的调节，其中神经调节和体液调节是主要的调节方式，自身调节相对来说是次要的（E错，为本题正确答案），微动脉管壁平滑肌张力受局部代谢产物调节属于代谢性自身调节的范畴（十版生理学P128）。备注：主要受局部代谢产物调节的部位是毛细血管前括约肌，因为毛细血管前括约肌上神经纤维分布极少（十版生理学P119），其舒缩活动几乎不受神经纤维的支配。","","N"],["1998-N8",3,"第3节 血管生理","动脉血压的形成",1998,8,"A","","关于动脉血压形成的机理，以下哪一项是错误的",[["A","与心室射血和外周阻力两个因素都有关"],["B","心室收缩时可释放动能和势能"],["C","在每个心动周期中心室内压和主动脉压的变化幅度相同"],["D","一般情况下，左心室每次收缩，向主动脉射出60ml～80ml血液"],["E","左心室射血是间断的，动脉血流是连续的"]],"C","在心动周期中，随着心室的收缩与舒张，室内压出现较大幅度的变化：室内压最高值出现在快速射血期末，大小为100～120mmHg，室内压的最低值出现在快速充盈期，由于心室肌快速舒张，室内压明显下降，甚至形成负压，对心房和大静脉内的血液产生“抽吸”作用（十版生理学P81）。而主动脉压由于主动脉和大动脉的弹性储器作用，血压的波动幅度相对较小：受心室射血影响，主动脉压的最高值也出现在快速射血期末，大小与室内压最高值接近，主动脉压最低值出现在等容收缩期末，大小为60～80mmHg。相对于心室压由负压到100～120mmHg的变化幅度，主动脉压由60～80mmHg到100～120mmHg的变化幅度显然要小得多（C错，为本题正确答案）。","","N"],["1998-N9",4,"第2节 肺换气和组织换气","气体的分子量和溶解度",1998,9,"A","","CO₂通过呼吸膜扩散的速率比O₂快20倍，主要原因是CO₂",[["A","为主动转运"],["B","易通过呼吸膜"],["C","分压梯度比较大"],["D","分子量比O₂大"],["E","在血中溶解度较大"]],"E","气体经呼吸膜扩散的速度与扩散系数成正比，扩散系数=气体溶解度/气体分子量的平方根，CO₂在血浆中的溶解度（51.5）约为O₂的（2.14）24倍，CO₂的分子量（44）略大于O₂的分子量（32），经计算CO₂的扩散系数约为O₂的20倍，故CO₂通过呼吸膜扩散的速度比 O₂快 20倍，主要原因是CO₂在血中溶解度较大（E对）。","","N"],["1998-N10",4,"第4节 呼吸运动的调节","CO₂、H⁺、O₂对呼吸运动的调节",1998,10,"A","","低氧对呼吸的兴奋作用是通过",[["A","直接兴奋延髓吸气神经元"],["B","直接兴奋脑桥呼吸调整中枢"],["C","外周化学感受器所实现的反射性效应"],["D","刺激中枢化学感受器而兴奋呼吸中枢"],["E","直接刺激呼吸中枢"]],"C","化学感受器是指其适宜刺激是O₂、CO₂和H⁺等化学物质的感受器。根据所在部位的不同，化学感受器分为外周化学感受器和中枢化学感受器两种。外周化学感受器位于颈动脉体和主动脉体，在动脉血PO₂降低、PCO₂或H⁺浓度升高时均受到刺激，反射性地引起呼吸中枢兴奋。中枢化学感受器位于延髓腹外侧部的浅表部位，生理性刺激是脑脊液中的H⁺，动脉血H⁺浓度升高时，H⁺通过血-脑屏障进入脑脊液发挥作用（但进入速度较慢，限制了H⁺对中枢化学感受器的作用），动脉血PCO₂升高时，血液中的CO₂能够通过血-脑屏障，间接引起脑脊液H⁺浓度升高，从而刺激中枢化学感受器，引起呼吸中枢兴奋。因此，低氧对呼吸运动的刺激作用完全是通过刺激外周化学感受器实现的（C对D错），CO₂和H⁺对呼吸运动的刺激作用则可以通过中枢化学感受器和外周化学感受器共同实现。低氧对中枢的直接作用是抑制的（ABE错）。","","N"],["1998-N11",5,"第4节 小肠内消化","促胰液素",1998,11,"A","","关于促胰液素的作用，下列哪项是错误的",[["A","促进肝胆汁分泌"],["B","促进胰液分泌"],["C","促进胃运动"],["D","促进胰腺分泌HCO₃⁻"],["E","促进小肠液分泌"]],"C","促胰液素由小肠上段黏膜的S细胞分泌，其生理功能极为广泛及多样化，且大部分功能与缩胆囊素（1990N147X）一致，生理学教材提及的功能包括：舒血管作用（七版生理学P170）、促进胰酶分泌（七版生理学P170 表6-3）、促进胆囊平滑肌收缩（七版生理学P170 表6-3）、抑制食管-胃括约肌收缩（七版生理学P170 表6-3）、收缩幽门括约肌（十版生理学P168）、促进胰腺外分泌部生长（十版生理学P168）、舒张食管下括约肌（十版生理学P171）、促进胃蛋白酶原分泌、抑制促胃液素和胃酸的分泌（十版生理学P168）、抑制胃的运动（十版生理学P168）（C错，为本题正确答案）、抑制胃排空（十版生理学P168）、促进胰腺小导管上皮细胞分泌水和HCO₃⁻分泌（十版生理学P181）（B对）、促进肝胆汁分泌（十版生理学P182）（A对）、促进小肠液分泌（十版生理学P183）（D对）、抑制小肠运动（十版生理学P184）、促进降钙素分泌（十版生理学P367）、促进胰岛素分泌（十版生理学P377）、抑制胰高血糖素分泌（十版生理学P378）等。","","N"],["1998-N12",7,"第2节 肾小球的滤过功能","肾小球滤过率和滤过分数",1998,12,"A","","滤过分数是指",[["A","肾小球滤过率/肾血浆流量"],["B","肾血浆流量/肾血流量"],["C","肾血流量/肾血浆流量"],["D","肾小球滤过率/肾血流量"],["E","肾血流量/心输出量"]],"A","单位时间内（每分钟）两肾生成的超滤液量称为肾小球滤过率，单位时间内（每分钟）流经肾的血浆量为肾血浆流量，肾小球滤过率与肾血浆流量的比值称为滤过分数（A对）。","","N"],["1998-N13",7,"","",1998,13,"A","","各段肾小管中，重吸收占首位的是",[["A","集合管"],["B","远曲小管"],["C","髓袢升支粗段"],["D","近曲小管"],["E","髓袢降支"]],"D","在各段肾小管中，近端小管（包括近曲小管（D对）和髓袢降支粗段）是最重要的重吸收部位。正常情况下，近端小管可重吸收由肾小球滤过的100%的葡萄糖和氨基酸、65%～70%的Na⁺、Cl⁻和水、80%HCO₃⁻、65%～70%K⁺、70%Ca²⁺等。","","N"],["1998-N14",0,"第5节 机体生理功能的调节","体液调节",1998,14,"A","","“神经激素”是指",[["A","作用于神经细胞的激素"],["B","具有酶功能的神经递质"],["C","神经细胞分泌的激素"],["D","神经系统内存在的激素"],["E","使神经兴奋的激素"]],"C","神经激素是指由神经细胞分泌的激素（C对），最典型的神经激素包括抗利尿激素（也称血管升压素）（十版生理学P231、P353）、缩宫素（十版生理学P353）和下丘脑调节肽（十版生理学P348）。","","N"],["1998-N15",9,"第1节 神经系统功能活动的基本原理","突触前抑制",1998,15,"A","","突触前抑制的特点是",[["A","突触前膜超极化"],["B","突触前轴突末梢释放抑制性递质"],["C","突触后膜的兴奋性降低"],["D","突触后膜的兴奋性突触后电位降低"],["E","通过轴突-树突突触的活动实现"]],"D","兴奋在反射中枢的传播过程中，各类神经元通过空间和时间上的多重复杂组合，可产生抑制和易化两种效应，称为中枢抑制和中枢易化。突触前抑制是通过轴突-轴突突触的活动实现的（E错），根据发生部位不同，中枢抑制可分为突触后抑制和突触前抑制两种类型：突触后抑制是由抑制性中间神经元释放抑制性递质，作用于突触后神经元，通过产生抑制性突触后电位（IPSP），使突触后膜的兴奋性降低（C错），从而使突触后神经元发生抑制；突触前抑制是由兴奋性外来神经元（非突触前神经元和突触后神经元）作用于突触前神经元，通过使突触前膜发生去极化或使突触前膜复极化速度加快等机制（AB错），最终使突触后神经元兴奋性突触后电位（EPSP）降低（D对），从而使突触后神经元发生抑制。","","N"],["1998-N16",9,"第3节 神经系统对躯体运动的调控","牵张反射的感受器",1998,16,"A","","当γ运动神经元的传出冲动增加时，可使",[["A","肌梭传入冲动减少"],["B","α运动神经元传出冲动减少"],["C","牵张反射加强"],["D","梭外肌收缩"],["E","梭内肌舒张"]],"C","当肌肉受外力牵拉而使肌梭被动拉长时，一方面，传入纤维传入冲动增加使α运动神经元兴奋，梭外肌收缩，形成一次牵张反射，而梭外肌收缩可以引起与其并联的肌梭（梭内肌）长度变短，肌梭感受装置所受的牵拉刺激减少，传入冲动减少，从而使梭外肌停止收缩，牵张反射减弱；另一方面，传入纤维传入冲动增加也会使γ运动神经元的传出冲动增加，梭内肌收缩（由位于肌梭两端的收缩成分介导）（E错），与肌梭收缩成分串联的肌梭感受装置所受的牵拉刺激增加，肌梭传入冲动增加（A错），支配梭外肌的α运动神经元传出冲动增强（B错），牵张反射增强（C对）。若存在牵拉刺激，γ运动神经元的传出冲动增加，梭外肌可收缩；若不存在牵拉刺激，γ运动神经元的传出冲动增加，不足以引起梭外肌收缩，题目所给信息不完整，D选项存在争议。","","N"],["1998-N17",9,"第5节 脑电活动及睡眠与觉醒","觉醒与睡眠的产生机制",1998,17,"A","","关于网状结构上行激动系统的描述，哪一项是错误的",[["A","经丘脑非特异投射系统发挥作用"],["B","维持与改变大脑皮层的兴奋状态"],["C","为多突触接替的上行系统"],["D","弥散投射至大脑皮层的广泛区域"],["E","电刺激时，出现同步化脑电图"]],"E","脑干网状结构是指在脑干内除界限清楚、功能明确的神经细胞核团和神经纤维束外的神经细胞和神经纤维交织成网状的结构，分布在从脊髓到丘脑底部各个部位。网状结构是一个反复换元的部位（故存在多突触接替）（C对），它接受躯体和内脏的各种传入冲动，由丘脑的非特异性投射系统弥散性投射到达大脑皮层（AD对），以维持和改变大脑皮层的兴奋状态（B对）。网状结构具有上行唤醒作用，刺激网状结构可以将猫从睡眠中唤醒，而破坏网状结构动物便进入持久的昏睡状态，脑电图呈同步化慢波（E错，为本题正确答案）。","","N"],["1998-N18",9,"第4节 神经系统对内脏活动、本能行为和情绪的调节","交感神经系统的功能",1998,18,"A","","交感神经兴奋可引起",[["A","瞳孔缩小"],["B","逼尿肌收缩"],["C","消化道括约肌舒张"],["D","妊娠子宫收缩"],["E","支气管平滑肌收缩"]],"D","大多数交感节后纤维释放的递质是去甲肾上腺素（除支配汗腺和骨骼肌血管的交感节后纤维释放乙酰胆碱外），交感神经系统的活动与各器官上去甲肾上腺素受体的分布有关。交感神经兴奋时，作用于虹膜辐射状肌（瞳孔开大肌）的α₁受体使虹膜辐射状肌收缩，瞳孔扩大（A错）。作用于膀胱逼尿肌的β₂受体使逼尿肌舒张（B错）。作用于消化道括约肌的α₁受体使消化道括约肌收缩（C错）；作用于支气管平滑肌的β₂受体使支气管平滑肌舒张（E错）。作用于妊娠子宫的α₁受体使妊娠子宫收缩（D对）。交感神经兴奋的状态可以用机体在剧烈运动时的生理状态来协助记忆：机体在剧烈运动时交感神经兴奋（十版生理学P322），心率加快、心肌收缩力增强，心输出量增加，目的是为全身的肌肉提供更多的血液和氧气；呼吸运动加强，支气管平滑肌舒张，肺泡通气量，目的是为了血液提供更多的氧气；皮肤、肾、胃肠等全身各处的血管平滑肌均收缩，但骨骼肌血管舒张，目的是为了让血液重新分配，为肌肉提供更多的血液；由于全身血液分配至骨骼肌，导致胃肠道供血不足，不利于胃肠道进行消化和吸收，故消化道平滑肌舒张，括约肌收缩，消化腺分泌减少；剧烈运动时，一般不会有特别强烈的尿意，也尿不出来；剧烈运动时妊娠子宫收缩，容易导致流产等等。","","N"],["1998-N93",3,"第4节 心血管活动的调节","颈动脉体和主动脉体化学感受性反射",1998,93,"B","","在低氧环境中",[["A","心率加快、血压升高"],["B","心率加快、血压降低"],["C","心率减慢、血压降低"],["D","心率减慢、血压升高"],["E","心率和血压不变"]],"A","低氧可以刺激颈动脉体和主动脉体的化学感受器，引起化学感受性反射。化学感受性反射的效应主要是调节呼吸，反射性地引起呼吸加深加快，通过呼吸运动的改变，再反射性影响心血管活动：心率加快（A对），心输出量增加，外周血管阻力增加，血压升高。呼吸加深加快引起心率加快的机制比较复杂，教材也没有说明，不必深究。如果不考虑呼吸加深加快的情况，化学感受性反射对心血管活动的影响为：心率减慢，心输出量减少，血压降低。","","N"],["1998-N94",3,"第4节 心血管活动的调节","肾上腺素和去甲肾上腺素",1998,94,"B","","静脉注射去甲肾上腺素时",[["A","心率加快、血压升高"],["B","心率加快、血压降低"],["C","心率减慢、血压降低"],["D","心率减慢、血压升高"],["E","心率和血压不变"]],"D","去甲肾上腺素与血管平滑肌的α受体和心肌的β₁受体都能结合，但与α受体结合能力较强，与β₁受体结合能力较弱，静脉注射去甲肾上腺素时，去甲肾上腺素与血管平滑肌的α受体结合，全身血管广泛收缩，动脉血压升高，但是血压升高又可使压力感受性反射活动加强，由于压力感受性反射对心脏的效应超过去甲肾上腺素与心肌的β₁受体的结合效应，故引起心率减慢（D对）。静脉注射肾上腺激素的效果则不一样，由于肾上腺素与血管平滑肌的α受体和心肌的β₁受体的结合能力都很强，动脉血压升高引起的压力感受性反射对心脏的抑制效应不足以对抗肾上腺素与心肌的β₁受体结合的刺激效应，因而血压升高的同时，心率也加快。","","N"],["1998-N95",10,"第6节 胰岛内分泌","营养成分的调节作用",1998,95,"B","","胰岛素分泌",[["A","以激素调节为主"],["B","以神经调节为主"],["C","以代谢物反馈调节为主"],["D","受靶腺激素与下丘脑调节肽双重控制"],["E","以自身调节为主"]],"C","胰岛素分泌主要接受代谢物葡萄糖的反馈调节（C对），胰岛β细胞对血糖变化十分敏感，正常人空腹血糖浓度为80～90mg/100ml时胰岛素分泌很少，当血糖升高300mg/100ml时，产生最大分泌反应。胰岛素分泌也受激素调节、神经调节和自身调节（十版生理学P377），但不受靶腺激素与下丘脑调节肽的调节。","","N"],["1998-N96",10,"第3节 甲状腺内分泌","下丘脑－腺垂体－甲状腺轴的调节",1998,96,"B","","促甲状腺素分泌",[["A","以激素调节为主"],["B","以神经调节为主"],["C","以代谢物反馈调节为主"],["D","受靶腺激素与下丘脑调节肽双重控制"],["E","以自身调节为主"]],"D","促甲状腺素（TSH）由腺垂体分泌，受下丘脑调节肽刺激作用和甲状腺激素反馈调节的双重控制（D对）：下丘脑释放促甲状腺激素释放激素（TRH），促甲状腺激素释放激素通过垂体门脉系统刺激腺垂体分泌促甲状腺激素，促甲状腺激素刺激甲状腺激素（TH）的合成与分泌，当血液中的甲状腺激素达到一定水平又产生负反馈效应，抑制促甲状腺素和促甲状腺激素释放激素的分泌。","","N"],["1998-N117",2,"第3节 生理性止血","生理性止血的基本过程",1998,117,"C","","血小板聚集可形成",[["A","牢固的止血栓"],["B","松软的止血栓"],["C","两者都是"],["D","两者都不是"]],"B","生理性止血包括三个基本步骤：①血管收缩：小血管受损后，损伤性刺激立即引起局部血管收缩，若破损不大即可使小血管封闭；②血小板血栓的形成：血管内膜下损伤暴露了内膜下组织可以激活血小板和血浆中的凝血系统，以及血管收缩使血流暂停或减慢，利于血小板黏附与聚集，形成松软的血小板止血栓（B对），达到初步止血，也称一期止血；③血液凝固：血凝系统被激活后，血浆中可溶的纤维蛋白原转变成不溶的纤维蛋白多聚体，血液发生凝固，纤维蛋白与血小板共同交织成网，形成牢固的止血栓，称二期止血。","","N"],["1998-N118",2,"第3节 生理性止血","生理性止血的基本过程",1998,118,"C","","纤维蛋白与血小板可形成",[["A","牢固的止血栓"],["B","松软的止血栓"],["C","两者都是"],["D","两者都不是"]],"A","生理性止血包括三个基本步骤：①血管收缩：小血管受损后，损伤性刺激立即引起局部血管收缩，若破损不大即可使小血管封闭；②血小板血栓的形成：血管内膜下损伤暴露了内膜下组织可以激活血小板和血浆中的凝血系统，以及血管收缩使血流暂停或减慢，利于血小板黏附与聚集，形成松软的血小板止血栓，达到初步止血，也称一期止血；③血液凝固：血凝系统被激活后，血浆中可溶的纤维蛋白原转变成不溶的纤维蛋白多聚体，血液发生凝固，纤维蛋白与血小板共同交织成网，形成牢固的止血栓（A对），称二期止血。","","N"],["1998-N119",3,"第2节 心脏的电生理学及生理特性","窦房结细胞动作电位",1998,119,"C","","窦房结细胞动作电位的特征是",[["A","0期去极速度快、幅度高"],["B","4期自动去极"],["C","两者均有"],["D","两者均无"]],"B","窦房结P细胞为慢反应自律细胞：窦房结缺乏快钠通道（INa通道），其动作电位0期的产生主要依赖L型钙通道（ICa-L通道）介导的Ca²⁺内流，由于L型钙通道的激活过程比较缓慢，因而0期去极化速度较慢（A错）。窦房结4期的膜电位不稳定，在3期复极完毕就自动去极化，使膜电位逐渐减小，即发生4期自动去极化（B对）。","","N"],["1998-N120",3,"第2节 心脏的电生理学及生理特性","浦肯野细胞动作电位",1998,120,"C","","浦肯野细胞动作电位的特征是",[["A","0期去极速度快、幅度高"],["B","4期自动去极"],["C","两者均有"],["D","两者均无"]],"C","浦肯野细胞为快反应自律细胞，由快钠通道介导动作电位0期去极化过程，去极化的速度和幅度甚至比心室肌细胞还要高（A对）。由于其属于自律细胞，故其4期的膜电位并不稳定，会发生自动去极化（B对）。本题AB均对，正确答案为C。","","N"],["1998-N121",11,"第2节 女性生殖功能及其调节","雌激素、孕激素的作用",1998,121,"C","","雌激素",[["A","促进肾脏对水和钠的重吸收"],["B","促进肾脏对钾的排泄"],["C","两者均有"],["D","两者均无"]],"C","高浓度的雌激素可使液体向组织间隙转移，由于循环血量减少而引起醛固酮分泌，促进肾远曲小管和集合管上皮细胞对水和钠的重吸收及对钾的排泄（AB对）。本题AB均对，正确答案为C。","","N"],["1998-N122",11,"第2节 女性生殖功能及其调节","雌激素、孕激素的作用",1998,122,"C","","孕激素",[["A","促进肾脏对水和钠的重吸收"],["B","促进肾脏对钾的排泄"],["C","两者均有"],["D","两者均无"]],"D","孕激素与醛固酮受体具有高亲和力，可竞争性拮抗醛固酮的生物学效应，抑制肾远曲小管和集合管上皮细胞对水和钠的重吸收（A错）及对钾的排泄（B错）。由于雌激素能促进醛固酮分泌，故孕激素与雌激素也表现为拮抗作用。本题AB均错，正确答案为D。","","N"],["1998-N139",2,"第4节 血型和输血原则","ABO血型系统",1998,139,"X","","如果某男是B型血",[["A","他的基因型可以是AB型"],["B","他的父亲可以是O型血"],["C","他的孩子不是B型血就是O型血"],["D","如果他的妻子是B型血，孩子的血型只能是B型或O型"]],"BD","血型为B型，基因型只可能为BB和BO（A错）。当该男基因型为BO时，其父亲可以是O型血（提供BO中的O）（B对），其孩子可能是B型血和O型血，但也可能是AB型（该男提供B，孩子母亲提供A）和A型（该男提供O，孩子母亲提供A）（C错）。如果他的妻子也是B型血，即基因型为BB或BO，根据基因的自由组合规律，小孩的基因型有三种可能，即BB、BO、OO，对应的血型表现型为B型、B型和O型，所以，孩子的血型只能是B型或O型的说法是正确的（D对）。","","N"],["1998-N140",6,"第2节 体温及其调节","体温的生理性波动",1998,140,"X","","下列因素中，哪些因素能引起皮肤温度发生变化",[["A","发汗"],["B","环境温度"],["C","皮肤血流量"],["D","精神因素"]],"ABCD","皮肤温度与皮肤血流量密切有关（C对），凡能影响皮肤血管舒缩的因素都能改变皮肤温度。环境温度和精神因素可影响交感神经的兴奋状态，从而影响皮肤血管的舒缩活动，引起皮肤温度发生变化（BD对）。当皮肤血流量增多时，有较多的体热可从机体深部被带到表层，皮肤温度升高，可感蒸发（发汗）（A 对）增强，机体散热增加。","","N"],["1998-N141",7,"第1节 肾的功能解剖和肾血流量","球旁器",1998,141,"X","","肾素",[["A","是肾脏近球小体中近球细胞分泌的"],["B","使肾小球滤过率减少"],["C","引起血中血管紧张素Ⅱ增多"],["D","引起血中醛固酮增多"]],"ACD","肾素是由肾脏近球细胞分泌的一种酸性蛋白酶（A对）。肾素分泌增多时，可以通过肾素-血管紧张素-醛固酮系统促使血管紧张素Ⅱ和醛固酮的释放（CD对）。肾素可以催化生成血管紧张素Ⅱ发挥作用，生理浓度下AngⅡ可选择性使出球小动脉收缩，进而升高肾小球毛细血管静水压，使肾小球滤过率升高；而血容量不足等情况下AngⅡ可使入球小动脉强烈收缩，肾小球滤过率减少，B选项存在争议，当年给出的参考答案为ACD。","","N"],["1998-N142",8,"第3节 视觉","晶状体变凸",1998,142,"X","","眼的视近物调节机制包括",[["A","支配睫状肌的副交感神经释放ACh"],["B","晶状体前后面变得更凸"],["C","内直肌收缩"],["D","瞳孔括约肌松弛"]],"ABC","正常人眼视远物时不需要调节而视近物时需要调节，参与眼视近物调节的肌肉包括睫状肌、瞳孔括约肌、内直肌等。视近物的调节机制为：视觉信息上传到大脑皮层后，皮层发出下行冲动，冲动到达中脑正中核，继而传至中脑动眼神经缩瞳核，然后进入位于视神经外侧的副交感神经节（睫状神经节），在节内更换神经元，其节后纤维释放ACh（A对），支配眼球的睫状肌、瞳孔括约肌和内直肌：①睫状肌收缩，悬韧带松弛，晶状体变凸（B对）；②瞳孔括约肌（虹膜环形肌）收缩，瞳孔缩小（D错）；③内直肌收缩（C对），视轴会聚，使物像落在两眼视网膜的对称点上。","","N"],["1998-N159",7,"第5节 尿生成的调节","维持机体酸碱平衡",1998,159,"X","","肾脏调节酸碱平衡的机理是",[["A","H⁺与Na⁺的交换"],["B","HCO₃⁻的重吸收"],["C","分泌NH₃与H⁺结合成NH₄⁺排出"],["D","尿的酸化而排出H⁺"]],"ABCD","细胞外液的正常pH为7.35～7.45。保持机体内环境的酸碱平衡是正常生命活动必备的重要条件。正常人在普通饮食情况下，机体在代谢活动中不断产生酸性或碱性物质，且酸性物质的产生量远多于碱性物质，通常，细胞外液中的缓冲系统首先发挥作用，缓冲过多的酸性物质，但它只能起即时效应；肺主要通过排出挥发性酸（CO₂）来缓冲体内的酸性产物，也只能起即时和部分作用。体内缓冲酸碱最重要、作用最持久的是肾，它可将体内除CO₂外的所有酸性物质即固定酸排出体外，从而保持细胞外液中的pH于正常范围内。ABCD均为肾脏调节酸碱平衡的机理。","","N"],["1999-N1",0,"第5节 机体生理功能的调节","自身调节",1999,1,"A","","下列情况中，属于自身调节的是",[["A","人在过度通气后呼吸暂停"],["B","动脉血压维持相对恒定"],["C","体温维持相对恒定"],["D","血糖水平维持相对恒定"],["E","平均血压在一定范围内升降时，肾血流量维持相对恒定"]],"E","机体对各种生理功能活动的调节方式有3种：神经调节、体液调节和自身调节。其中自身调节是指组织细胞不依赖于神经或体液因素，自身对环境刺激发生的一种适应性反应。机体的许多生理功能活动均涉及自身调节：如调节肾血流量的肌源性自身调节（E对）和管-球反馈、尿生成过程中的渗透性利尿和球-管平衡（十版生理学P226）、局部组织的代谢性自身调节（十版生理学P128）、脑血流量的肌源性自身调节（十版生理学P132）、心肌骨骼肌的异长自身调节（十版生理学P83）以及内分泌系统存在的大量自身调节等等。但目前为止只考过肾血流的肌源性自身调节（1992N65A，1999N1A）和脑血流的肌源性自身调节（2012N121B）。人在过度通气后呼吸暂停，是因为过度通气时，肺通气量增加，呼出的CO₂增多，血液中PCO₂下降，呼吸中枢因缺少足够的CO₂刺激而受到抑制造成的，属于化学感受器介导的神经调节（A错）。动脉血压维持相对恒定，主要与心血管系统的压力感受性反射有关，为典型的神经调节（B错）。体温维持相对恒定，依赖于体温调节中枢控制下的皮肤血流量、发汗、代谢水平的改变等等，也属于典型的神经调节（C错）。维持血糖水平恒定最重要的因素是胰岛素，胰岛素对血糖的调节属于体液调节（D错）。","","N"],["1999-N2",1,"第3节 细胞的电活动","细胞膜两侧离子的浓度差与平衡电位",1999,2,"A","","当达到K⁺平衡电位时",[["A","细胞膜两侧K⁺浓度梯度为零"],["B","细胞膜外K⁺浓度大于膜内"],["C","细胞膜两侧电位梯度为零"],["D","细胞膜内较膜外电位相对较正"],["E","细胞膜内侧K⁺的净外流为零"]],"E","K⁺平衡电位的形成过程：钠泵通过吸入K⁺排出Na⁺造成细胞内高K⁺低Na⁺、细胞外高Na⁺低K⁺的离子不均匀分布，在浓度差驱动力（化学驱动力）的作用下，细胞内的高K⁺有由内向外流动的趋势，细胞外的高Na⁺有由外向内流动的趋势。在安静状态下，细胞膜对各种离子的通透性并不相同，K⁺通透性较高，Na⁺则通透性很低，K⁺在浓度差驱动力的作用下，完成了由内向外流动的过程，Na⁺却几乎不能实现由外向内流动。K⁺外流的过程也是正电荷外流的过程，形成了膜内负电位，膜内负电位对带正电荷的K⁺有吸引作用，此为电驱动力，电驱动力与浓度差驱动力方向相反，能够阻止K⁺外流，K⁺外流越多，膜内负电位就越大，电驱动力也越大，当K⁺受到的电驱动力增加到与浓度差驱动力相等时，电-化学驱动力即为零，此时K⁺的净外流为零（E对），膜两侧的电位差便稳定下来。这种K⁺扩散为零的跨膜电位差即为K⁺的平衡电位。K⁺达到平衡电位时，依然存在浓度差驱动力，只不过该驱动力与电驱动力大小相等，方向相反，K⁺的浓度差驱动力源自于细胞内高K⁺、细胞外低K⁺的浓度梯度，故K⁺达到平衡电位时，细胞膜两侧K⁺浓度梯度并不为零（A错），细胞内K⁺浓度应该大于细胞外（B错）；电位驱动力也不为零（C错），K⁺的平衡电位接近静息电位，为负值（D错）。","","N"],["1999-N3",1,"第3节 细胞的电活动","动作电位的概念及特点",1999,3,"A","","下列关于动作电位的描述中，哪一项是正确的",[["A","刺激强度低于阈值时，出现低幅度的动作电位"],["B","刺激强度达到阈值后，再增加刺激强度能使动作电位幅度增大"],["C","动作电位的扩布方式是电紧张性的"],["D","动作电位随传导距离增加而变小"],["E","在不同的可兴奋细胞，动作电位的幅度和持续时间是不同的"]],"E","动作电位具有“全或无”的特性，即要么达到最大值（全），要么不发生（无），刺激强度低于阈值时，不产生动作电位（无），而是产生局部电位（A错），刺激强度达到阈值时，动作电位幅度即可达到最大值（全），不随刺激强度增大而增大（B错），由于动作电位“全或无”的特性，在传导过程中并不会随传导距离增加而变小（D错）。不同的细胞，动作电位的幅度和持续时间是不同的，如神经细胞的动作电位时程很短，锋电位仅持续1ms，而心室肌细胞动作电位时程较长，可达300ms左右，期间形成一个平台期（E对）。七版生理学认为动作电位的扩布是以电紧张性为基础的，但十版生理学中指出动作电位的扩布可用局部电流学说解释，即局部电流在膜内由兴奋区流向未兴奋区，向外穿过细胞膜后，又返回兴奋区，构成电流回路，在此过程中动作电位的传播不衰减，而电紧张性扩布，范围小，易衰减，属于局部电位的传导方式（C错），这里需要注意“局部电流”和“局部电位”并不是一个概念，局部电流是动作电位的传播方式，局部电位则是一种区别于动作电位的电位形式。","","N"],["1999-N4",1,"第3节 细胞的电活动","动作电位期间膜离子通透性的变化",1999,4,"A","","神经纤维电压门控的Na⁺通道与K⁺通道的共同点中，错误的是",[["A","都有开放状态"],["B","都有关闭状态"],["C","都有激活状态"],["D","都有失活状态"],["E","都有静息状态"]],"D","失活状态是指通道在激活态之后对去极化刺激不再反应的状态，膜电导实验表明，钠离子在去极化过程中逐渐失活，而钾离子则不存在失活状态（D对）。","","N"],["1999-N5",1,"第4节 肌细胞的收缩","骨骼肌神经肌肉接头处的兴奋传递",1999,5,"A","","在神经-骨骼肌接点的终板膜处",[["A","受体和离子通道是两个独立的蛋白质分子"],["B","递质与受体结合后不能直接影响通道蛋白质"],["C","受体与第二信使同属于一个蛋白质分子"],["D","受体与离子通道是一个蛋白质分子"],["E","受体通过第二信使触发肌膜兴奋"]],"D","神经-骨骼肌接点的终板膜处的受体为N₂型乙酰胆碱受体，也称N₂型乙酰胆碱受体阳离子通道，这是一类兼有通道和受体功能的蛋白分子（D对）。该受体膜外侧有两个乙酰胆碱结合位点，结合位点与乙酰胆碱结合后可使通道的构象发生改变，引起闸门开放，产生Na⁺和K⁺的跨膜移动且以Na⁺内流为主，导致膜电位改变，最终引起肌细胞兴奋。兼有通道和受体功能的分子，除N₂型乙酰胆碱受体之外，还包括甘氨酸受体、γ-氨基丁酸A受体等（十版生理学P23）。","","N"],["1999-N6",2,"第4节 血型和输血原则","输血原则",1999,6,"A","","下列关于输血的叙述，哪一项是错误的",[["A","ABO血型系统相符合便可输血，不需进行交叉配血"],["B","O型血的人为“万能供血者”"],["C","AB型血的人为“万能受血者”"],["D","将O型血液输给其他血型的人时，应少量而且缓慢"],["E","Rh阳性的人可接受Rh阴性的血液"]],"A","即使在ABO系统血型相同的人之间进行输血，输血前也必须进行交叉配血试验（A错，为本题正确答案）。把供血者的红细胞与受血者的血清进行配合试验，称为交叉配血主侧，再将受血者的红细胞与供血者的血清作配合试验，称为交叉配血次侧。交叉配血试验既可检验血型鉴定是否有误，又能发现供血者和受血者的红细胞或血清中是否还存在其他不相容的血型。把O型血的人称为“万能供血者”，认为他们的血液可输给任何ABO血型的人，这种说法其实是不严谨的，因为O型血的红细胞上虽然没有A和B抗原，不会被受血者的血浆所凝集，但O型血的血浆中存在抗A和抗B抗体，这些抗体能与其他血型受血者的红细胞发生聚集反应，换言之，O型血的人作为“万能供血者”为非O型血的人供血时，交叉配血的主侧不发生凝集反应，但交叉配血的次侧会发生凝集反应，当输入血量较大时，供血者血浆中的抗体未被受血者的血浆足够稀释时，受血者的红细胞会被广泛凝集。把AB型血的人称为“万能受血者”这种说法同样是不可取的，因为AB型血的血浆中虽无抗A、抗B抗体，交叉配血主侧不会发生凝集反应，但是供血者血浆中可能存在抗A抗体和/或抗B抗体，当大量输入其他不同类型的ABO血型血液时，也可使受血者红细胞发生凝集。将O型血液输给其它血型的人时，交叉配血次侧会发生凝集反应，输血应少量而且缓慢，使供血者血浆中的抗体被受血者的血浆充分稀释，以免受血者的红细胞被广泛凝集（D对）。Rh血型系统是红细胞中最复杂的一个系统，已发现40多种Rh抗原，与临床关系密切的是D、E、C、c、e五种，其中D抗原的抗原性最强，医学上通常将红细胞上含有D抗原者称为Rh阳性，而红细胞上缺乏D抗原者称为Rh阴性。Rh阳性的人接受Rh阴性的血液时，交叉配血主侧（受血者血浆对供血者红细胞）不发生凝集反应，交叉配血次侧（供血者血浆对受血者红细胞）发生凝集反应，根据输血原则，主侧不凝集，次侧凝集，必要时可少量、慢速输血（E对）。本题答案ABC均不正确，原答案选A。","","N"],["1999-N7",3,"第1节 心脏的泵血功能","心肌收缩能力",1999,7,"A","","在肾上腺素作用下，心室功能曲线向哪个方向移位",[["A","正上方"],["B","左上方"],["C","左下方"],["D","右上方"],["E","右下方"]],"B","逐步改变心室舒张末期压力值，并测量相对应的心室搏出量或每搏功，将心室舒张末期压力值（横坐标）与相对应的搏出量或每搏功（纵坐标）的数据绘制成的曲线，称为心室功能曲线。在肾上腺素作用下，心肌收缩能力增强，相同的心室舒张末期压力值对应更高的搏出量或每搏功，心室功能曲线向左上方移位（B对）。","","N"],["1999-N8",3,"第3节 血管生理","动脉血压",1999,8,"A","","关于动脉血压的叙述，下列哪一项是正确的",[["A","心室收缩时，血液对动脉管壁的侧压称为收缩压"],["B","平均动脉血压是收缩压和舒张压的平均值"],["C","动脉血压偏离正常水平愈远，压力感受器纠正异常血压的能力愈强"],["D","其它因素不变时，心率加快使脉搏压增大"],["E","男、女性的动脉血压均随年龄的增长而变化"]],"E","血液对动脉管壁的侧压称为动脉血压，心室收缩时，主动脉压力急剧升高，在快速射血期末达到最高，这时的动脉血压才称为收缩压（A错）。心室舒张时，主动脉压力下降，在心舒末期为最低值，称舒张压。平均动脉压是指一个心动周期中每一瞬间动脉血压的平均值，大约等于舒张压加1/3脉压，而不等于收缩压和舒张压的平均值（B错）。由压力感受性反射功能曲线可知，动脉血压偏离正常水平越远，压力感受性反射纠正异常血压的能力越弱（C错）。心率加快时，舒张压和收缩压均升高，但舒张压升高更明显，因此脉压减小（等于收缩压-舒张压）（D错）。男、女性的动脉血压均随年龄的增长而升高（E对），且收缩压比舒张压升高更为明显。","","N"],["1999-N9",3,"第3节 血管生理","影响动脉血压的因素",1999,9,"A","","生理情况下，下列哪一项对收缩压的影响最大",[["A","心率的变化"],["B","心输出量的变化"],["C","外周阻力的变化"],["D","循环血量的变化"],["E","大动脉管壁弹性的变化"]],"B","生理情况下，对收缩压影响最大的是每搏输出量的变化，故本题答案B不严谨，因为心输出量还受到心率的影响。心率和外周阻力的变化主要影响舒张压（AC错）。循环血量的变化主要影响平均充盈压（D错）。大动脉管壁弹性的变化主要影响动脉血压的波动幅度（E错）。","","N"],["1999-N10",3,"第4节 心血管活动的调节","心脏的神经支配",1999,10,"A","","心交感神经引起心缩力加强的主要机制是",[["A","明显增加Ca²⁺通道开放概率"],["B","减弱自律细胞4期的内向电流"],["C","使复极相K⁺外流减慢"],["D","减弱肌钙蛋白的Ca²⁺亲和力"],["E","能量的利用效率提高"]],"A","心交感神经节后纤维释放去甲肾上腺素，作用于心肌细胞膜的β肾上腺素能受体，经过信号转导增加Ca²⁺通道开放概率（A对），引起胞质Ca²⁺浓度升高，Ca²⁺浓度升高使Ca²⁺与肌钙蛋白结合而触发肌肉收缩（参见P51横纹肌兴奋-收缩耦联的基本步骤），引起心收缩力增强。","","N"],["1999-N11",3,"第3节 血管生理","影响静脉回心血量的因素",1999,11,"A","","心脏收缩力增强时，静脉回心血量增加，这主要是因为",[["A","动脉血压升高"],["B","血流速度加快"],["C","心输出量增加"],["D","舒张期室内压低"],["E","静脉压增高"]],"D","心脏收缩为推动血液在心血管系统内循环提供动力。因此，静脉回心血量与心肌收缩力呈正变关系。心肌收缩力增强时，射血时心室排空就较完全，在心舒期室内压就较低（D对），因而对心房和静脉内血液的抽吸力量就较大，回心血量增多。","","N"],["1999-N12",4,"第1节 肺通气","肺通气量",1999,12,"A","","每分通气量和肺泡通气量之差为",[["A","无效腔气量×呼吸频率"],["B","潮气量×呼吸频率"],["C","功能余气量×呼吸频率"],["D","余气量×呼吸频率"],["E","肺活量×呼吸频率"]],"A","每分通气量=潮气量×呼吸频率，肺泡通气量=（潮气量-无效腔气量）×呼吸频率。因此，每分通气量-肺泡通气量=无效腔气量×呼吸频率（A对）。","","N"],["1999-N13",4,"第1节 肺通气","肺容量",1999,13,"A","","正常呼气末，肺内的气体量相当于",[["A","余气量"],["B","呼气储备量"],["C","功能残气量"],["D","吸气储备量"],["E","总肺容量"]],"C","余气量是指最大呼气末尚存留于肺内不能呼出的气体量（A错）。呼气储备量即补呼气量，指平静呼气末，再尽力呼气所能呼出的气体量（B错）。功能残气量（功能余气量）是指平静呼气末尚存留于肺内的气体量（C对）。吸气储备量即补吸气量，指平静吸气末，再尽力吸气所能吸入的气体量（D错）。总肺容量即肺总量，指肺所能容纳的最大气体量（E错）。","","N"],["1999-N14",4,"第3节 气体在血液中的运输","氧的运输",1999,14,"A","","关于气体在血液中运输的叙述，下列哪项是错误的",[["A","O₂和CO₂都以物理溶解和化学结合的两种形式存在于血液中"],["B","O₂的结合形式是氧合血红蛋白"],["C","O₂与血红蛋白结合快、可逆、需要酶催化"],["D","CO₂主要以HCO₃ -形式运输"],["E","CO₂和血红蛋白的氨基结合不需酶的催化"]],"C","O₂和CO₂都以物理溶解和化学结合两种形式存在于血液中（A对）。其中O₂仅约1.5%以物理溶解的形式存在，其余98.5%则以化学结合（氧合血红蛋白）（B对）的形式存在；CO₂约5%以物理溶解的形式运输，其余95%则以化学结合（88%碳酸氢盐+7%氨基甲酰血红蛋白）的形式运输（D对）。氧合血红蛋白和氨基甲酰血红蛋白分别为Hb与O₂和CO₂的结合形式，Hb与O₂和CO₂的结合反应均快速、可逆，无需酶的催化（E 对）（C 错，为本题正确答案）。","","N"],["1999-N15",5,"第2节 口腔内消化和吞咽","食管期",1999,15,"A","","关于食管-胃括约肌的叙述，下列哪项是错误的",[["A","该部位平滑肌增厚"],["B","其内压力比胃内高0.67～1.33kPa（5～10mmHg）"],["C","食物经过食管时可反射性舒张"],["D","胃泌素可刺激其收缩"],["E","可防止胃内容物逆流入食管"]],"A","食管-胃括约肌又称食管下括约肌（low esophageal sphincter），简称LES。生理学第六版教材明确指出：在食管与胃连接处（1～2cm）的环形肌轻度增厚，称为食管下括约肌，查阅众多资料，给出的结论也是“增厚”。生理学第八、九、十版教材则解释：食管下端近贲门处在解剖上并不存在括约肌。看似矛盾，其实不然，括约肌的定义是分布在人和动物体某些管腔壁的一种明显增厚的环形肌肉，而食管下括约肌的环形肌只是轻度增厚（未达到括约肌的增厚标准），因此，严格来说本题的A选项也是正确的。","","N"],["1999-N16",5,"第3节 胃内消化","胃的运动形式",1999,16,"A","","胃容受性舒张是通过下列哪一途径实现的",[["A","交感神经兴奋"],["B","迷走神经末梢释放ACh"],["C","迷走神经末梢释放某种肽类物质"],["D","壁内神经丛兴奋"],["E","迷走神经引起胃黏膜释放前列腺素"]],"C","容受性舒张是指进食时食物刺激口腔、咽、食管等处的感受器反射性引起胃底和胃体舒张的过程，其传入神经和传出神经均为迷走神经，其中传出纤维属于抑制性纤维，节后纤维释放的递质是某种肽类物质（C对）。","","N"],["1999-N17",5,"第4节 小肠内消化","胆汁的作用",1999,17,"A","","关于胆汁的生理作用，下列哪项是错误的",[["A","胆盐、胆固醇和卵磷脂都可乳化脂肪"],["B","胆盐可促进脂肪的吸收"],["C","胆汁可促进脂溶性维生素的吸收"],["D","肝胆汁在十二指肠可中和一部分胃酸"],["E","胆囊胆汁在十二指肠可中和一部分胃酸"]],"E","由于肝胆汁呈弱碱性（pH7.4），在十二指肠中可以中和酸性较强的胃酸（D对）。而胆囊胆汁因HCO₃⁻在胆囊中被吸收呈弱酸性（pH6.8），所以在十二指肠中胆囊胆汁不能中和胃酸（E错，为本题正确答案）。","","N"],["1999-N18",5,"第3节 胃内消化","胃排空及其控制",1999,18,"A","","下列因素中，哪一种可促进胃排空",[["A","胃泌素"],["B","肠-胃反射"],["C","促胰液素"],["D","抑胃肽"],["E","胆囊收缩素"]],"A","胃排空是指食糜由胃排入十二指肠的过程。进入十二指肠的食糜可以刺激肠壁上的化学、渗透压和机械感受器，一方面可通过肠-胃反射而抑制胃的运动，延缓胃排空（神经调节）（B错），一方面可刺激小肠黏膜细胞释放促胰液素（C错）、抑胃肽（D错）、缩胆囊素（E错）等胃肠激素，抑制胃的运动，使胃排空减慢（体液调节）。关于促胃液素也就是胃泌素，五版及之前的生理学教材认为促胃液素可以促进胃排空，故本题给出的参考答案为A（1999年使用的生理学教材为第五版）；而六版及之后的生理学教材则认为促胃液素能促进胃的运动，也能增强幽门括约肌的收缩，其总效应是延缓胃排空，按照最新教材的说法，本题无正确答案。","","N"],["1999-N93",1,"第1节 细胞膜的物质转运功能","继发性主动转运",1999,93,"B","","葡萄糖通过小肠黏膜或肾小管吸收属于",[["A","单纯扩散"],["B","载体中介的易化扩散"],["C","通道中介的易化扩散"],["D","原发性主动转运"],["E","继发性主动转运"]],"E","葡萄糖主要有两种转运方式，包括红细胞、脑细胞等在内大多数种类的细胞通过经载体易化扩散实现葡萄糖的转运；而小肠黏膜上皮细胞和近端肾小管上皮细胞则是以继发性主动转运实现葡萄糖的转运（E对）。","","N"],["1999-N94",1,"第1节 细胞膜的物质转运功能","经载体的易化扩散",1999,94,"B","","葡萄糖通过一般细胞膜属于",[["A","单纯扩散"],["B","载体中介的易化扩散"],["C","通道中介的易化扩散"],["D","原发性主动转运"],["E","继发性主动转运"]],"B","葡萄糖主要有两种转运方式，包括红细胞、脑细胞等在内大多数种类的细胞通过经载体中介的易化扩散实现葡萄糖的转运（B对）；而小肠黏膜上皮细胞和近端肾小管上皮细胞则是以继发性主动转运实现葡萄糖的转运。","","N"],["1999-N95",4,"第1节 肺通气","肺泡通气量",1999,95,"B","","真正的有效通气量是",[["A","肺活量"],["B","时间肺活量"],["C","每分通气量"],["D","肺总容量"],["E","肺泡通气量"]],"E","每次吸入的气体，一部分将留在鼻或口与终末细支气管之间的呼吸道内，不参与肺泡与血液之间的气体交换，这部分呼吸道的容积称为解剖无效腔。进入肺泡的气体，也可因血流在肺内分布不均而不能都与血液进行气体交换，未能发生交换的这一部分肺泡容量称为肺泡无效腔。肺泡无效腔与解剖无效腔一起合称为生理无效腔 。由于无效腔的存在，每次吸入的新鲜空气不能都到达肺泡与血液进行气体交换。因此，为了计算真正有效的气体交换量，应以肺泡通气量为准（E对）。肺泡通气量是指每分钟吸入肺泡的新鲜空气量，它等于潮气量和无效腔气量之差与呼吸频率的乘积。","","N"],["1999-N96",4,"第1节 肺通气","肺容量",1999,96,"B","","评价肺通气功能较好的指标是",[["A","肺活量"],["B","时间肺活量"],["C","每分通气量"],["D","肺总量"],["E","肺泡通气量"]],"B","肺活量是反映了肺一次通气的最大能力，在一定程度上可作为肺通气功能的指标。但由于测定肺活量时不限制呼气的时间，所以不能充分反映肺组织的弹性状态和气道的通畅程度，即肺通气功能的好坏。例如，某些患者肺组织弹性降低或呼吸道狭窄，通气功能已经受到损害，但是如果延长呼气时间，所测得的肺活量是正常的。因此，提出了时间肺活量的概念，时间肺活量是指一次最大吸气后，第1秒内尽力尽快呼气所能呼出的最大气体量。肺组织弹性降低或呼吸道狭窄的患者肺活量可正常，但时间肺活量是下降的，时间肺活量不仅反映了肺活量的大小，而且反映了肺组织的弹性状态和气道的通畅程度，因此是评论肺通气功能的较好指标（B对）。","","N"],["1999-N117",3,"第3节 血管生理","影响动脉血压的因素",1999,117,"C","","心脏射血功能增加时",[["A","动脉血压升高"],["B","中心静脉压降低"],["C","两者都有"],["D","两者都无"]],"C","心脏射血能力（收缩能力）增强时，心缩期射入主动脉的血量增多，动脉血压升高（A对）；由于射血量增多，心室内剩余血量减少，心舒期室内压降低，从而对心房和静脉内血液的抽吸力量增强，使中心静脉压下降（B对）。本题AB均对，正确答案为C。","","N"],["1999-N118",3,"第3节 血管生理","影响动脉血压的因素",1999,118,"C","","外周小动脉收缩时",[["A","动脉血压升高"],["B","中心静脉压降低"],["C","两者都有"],["D","两者都无"]],"C","外周小动脉收缩时，外周阻力增大，动脉血压升高（A对）。外周小动脉收缩时，流入外周静脉的血量减少，中心静脉压降低（B对）。本题AB均对应选C。","","N"],["1999-N119",3,"第4节 心血管活动的调节","颈动脉窦和主动脉弓压力感受性反射",1999,119,"C","","电刺激右迷走神经外周端可引起",[["A","动脉血压降低"],["B","心输出量减少"],["C","两者都有"],["D","两者都无"]],"C","电刺激右侧迷走神经外周端，可使心率减慢，进而使心输出量减少（心输出量又称每分输出量，等于心率与每搏输出量的乘积）（B对）。心率减慢时，心室舒张期延长，从大动脉流向外周的血量增加，存留在主动脉内的血量减少，使舒张压明显降低（A对）。由于舒张期末主动脉内存留的血量减少，致使心缩期主动脉内血量减少，收缩压也相应降低（A对）。本题AB均对，正确答案为C。","","N"],["1999-N120",3,"第4节 心血管活动的调节","颈动脉窦和主动脉弓压力感受性反射",1999,120,"C","","夹闭两侧颈总动脉可引起",[["A","动脉血压降低"],["B","心输出量减少"],["C","两者都有"],["D","两者都无"]],"D","夹闭两侧颈总动脉，阻断了颈动脉血流，颈动脉窦压力感受器所受到的刺激减小，压力感受性反射减弱，从而使心输出量增加（B错）、动脉压升高（A错）。本题AB均错，正确答案为D。","","N"],["1999-N121",4,"第1节 肺通气","弹性阻力和顺应性",1999,121,"C","","与肺通气弹性阻力有关的是",[["A","肺泡表面张力"],["B","肺组织本身的弹性回缩力"],["C","两者均有"],["D","两者均无"]],"C","肺通气过程中所遇到的阻力为肺通气的阻力，可分为弹性阻力（70％）和非弹性阻力（30%）两类，前者包括肺的弹性阻力和胸廓的弹性阻力，后者包括气道阻力、惯性阻力和组织的黏滞阻力。肺的弹性阻力又包括肺组织本身的弹性回缩力（源自肺内弹力纤维和胶原纤维等结构）（B对）和肺泡表面张力（源自肺泡内表面的液-气界面 ）（A对）两个部分。本题AB均对，正确答案为C。","","N"],["1999-N122",4,"第1节 肺通气","非弹性阻力",1999,122,"C","","与肺通气非弹性阻力有关的是",[["A","肺泡表面张力"],["B","肺组织本身的弹性回缩力"],["C","两者均有"],["D","两者均无"]],"D","肺通气过程中所遇到的阻力为肺通气的阻力，可分为弹性阻力（70％）和非弹性阻力（30%）两类，前者包括肺的弹性阻力和胸廓的弹性阻力，后者包括气道阻力、惯性阻力和组织的黏滞阻力。肺的弹性阻力又包括肺组织本身的弹性回缩力（源自肺内弹力纤维和胶原纤维等结构）（B错）和肺泡表面张力（源自肺泡内表面的液-气界面 ）（A错）两个部分。本题AB均错，正确答案为D对。","","N"],["1999-N139",0,"第6节 人体内自动控制系统","正反馈控制系统",1999,139,"X","","下列哪些现象中存在正反馈",[["A","血液凝固过程"],["B","心室肌纤维动作电位0期去极时的Na⁺内流"],["C","排卵前，成熟的卵泡分泌大量雌激素对腺垂体分泌黄体生成素的影响"],["D","妇女绝经后，由于卵巢激素分泌减少引起的血和尿中的促性腺激素浓度升高"]],"ABC","正反馈是指受控部分发出的反馈信息促进与加强控制部分的活动，正反馈远不如负反馈常见，正反馈主要包括血液凝固过程（十版生理学P67）（A对）、动作电位去极化过程中Na⁺内流（十版生理学P32）（B对）、排卵前夕雌激素对LH的促进作用（十版生理学P389）（C对）、蛋白酶原的激活、排尿（十版生理学P239）、排便、分娩（十版生理学P396）等，除此之外的绝大部分调节过程均为负反馈。妇女绝经后，卵巢功能逐渐衰退，卵巢激素分泌较少，对下丘脑和垂体抑制作用减弱，引起血和尿中的促性腺激素浓度升高，是典型的负反馈调节过程（D错）。","","N"],["1999-N140",1,"第1节 细胞膜的物质转运功能","钠-钾泵",1999,140,"X","","下述哪些过程需要细胞本身耗能",[["A","维持正常的静息电位"],["B","膜去极化达阈电位时的大量Na⁺内流"],["C","动作电位复极相中的K⁺外流"],["D","骨骼肌细胞胞浆中，Ca²⁺向肌浆网内部的聚集"]],"AD","维持正常的静息电位及Ca²⁺向肌质网内部的聚集分别依赖于钠泵和钙泵的活动，二者均属主动转运，需要消耗能量（AD对）；膜去极化至阈电位时的大量钠离子内流及动作电位复极相中的钾离子外流，都是顺浓度梯度发生的，属于经通道介导的易化扩散，无能量的消耗（BC错）。","","N"],["1999-N141",2,"第3节 生理性止血","生理性止血的基本过程",1999,141,"X","","小血管损伤后，生理止血过程包括",[["A","受损小血管收缩"],["B","血小板聚集形成止血栓"],["C","受损局部血液凝固形成血凝块"],["D","血管壁修复、伤口愈合"]],"ABC","生理性止血是指小血管损伤，血液从血管内流出数分钟后出血自行停止的现象。生理性止血主要包括以下三个基本步骤：①小血管受损后，损伤性刺激立即引起局部血管收缩，若破损不大即可使小血管封闭（A对）；②血管内膜下损伤暴露了内膜下组织可以激活血小板和血浆中的凝血系统，以及血管收缩使血流暂停或减慢，利于血小板黏附与聚集，形成松软的血小板止血栓（B对），达到初步止血，也称一期止血；③血凝系统被激活后，血浆中可溶的纤维蛋白原转变成不溶的纤维蛋白多聚体，血液发生凝固（C对），纤维蛋白与血小板共同构成的牢固止血栓，称二期止血。","","N"],["1999-N142",4,"第1节 肺通气","弹性阻力和顺应性",1999,142,"X","","肺泡表面活性物质的作用有",[["A","防止液体渗入肺泡"],["B","保持大小肺泡的稳定性"],["C","成年人患肺炎、肺血栓时，可因此物减少而发生肺不张"],["D","新生儿可因缺乏此物造成“呼吸窘迫综合征”"]],"ABCD","肺表面活性物质的主要作用是降低肺泡表面张力，降低肺泡表面张力对肺毛细血管血浆和肺组织间液可产生“抽吸”作用，防止液体渗入肺泡（A对）。根据Laplace定律（十版生理学P141），肺泡的回缩力与肺泡半径成反比，即小肺泡的回缩力大，而大肺泡的回缩力小，但肺表面活性物质的存在，降低了小肺泡的回缩力（小肺泡分布的肺表面活性物质密度较大，降低了表面张力），从而避免了小肺泡萎陷关闭而大肺泡过度膨胀的情况，保持了大小肺泡的稳定性（B对）。成年人患肺炎、肺血栓时，或新生儿肺泡Ⅱ型细胞尚未发育成熟时，均可因为肺表面活性物质缺乏而引起小肺泡萎陷关闭，产生肺不张（CD对）。","","N"],["2000-N1",1,"第1节 细胞膜的物质转运功能","易化扩散",2000,1,"A","","在细胞膜的物质转运中，Na⁺跨膜转运的方式是",[["A","单纯扩散"],["B","易化扩散"],["C","易化扩散和主动转运"],["D","主动转运"],["E","单纯扩散和主动转运"]],"C","跨细胞膜的物质转运包括单纯扩散、易化扩散、主动转运、膜泡运输等方式。其中单纯扩散主要介导脂溶性物质或少数不带电荷的极性小分子物质的转运，如O₂、CO₂、N₂、NH₃、类固醇激素、乙醇、尿素、甘油、水等；易化扩散包括经通道易化扩散和经载体易化扩散两种形式，经通道易化扩散主要以离子通道的形式（如Na⁺通道、K⁺通道等）介导各种带电离子顺浓度梯度或电位梯度的跨膜转运，经载体易化扩散主要介导葡萄糖、氨基酸等水溶性小分子物质进行顺浓度梯度的跨膜转运；主动转运包括原发性主动转运和继发性主动转运两种形式，原发性主动转运通常以离子泵的形式（如Na⁺泵、Ca²⁺泵、H⁺泵等）转运各种带电离子，继发性主动转运是载体介导的易化扩散与原发性主动转运相耦联的转运系统，可使水溶性小分子物质、带电离子逆浓度梯度或电位梯度的跨膜转运（易化扩散和继发性主动转运的区别是前者顺浓度梯度或电位梯度，不耗能；后者逆浓度梯度或电位梯度，耗能）；膜泡运输包括出胞和入胞两种形式，主要介导大分子和颗粒物质的跨膜转运。综上，Na⁺跨膜转运的方式包括易化扩散（经通道易化扩散）和主动转运两种方式（C对）。","","N"],["2000-N2",1,"第1节 细胞膜的物质转运功能","单纯扩散",2000,2,"A","","下列各项跨膜转运中，哪一项没有饱和现象",[["A","继发性主动转运"],["B","原发性主动转运"],["C","易化扩散"],["D","单纯扩散"],["E","Na⁺-Ca²⁺交换"]],"D","由于细胞膜中载体的数量和转运速率有限，当被转运的底物浓度增加到一定程度时，底物的扩散速度便达到最大值，不再随底物浓度的增加而增大，这种现象称为载体转运的饱和现象。继发性主动转运（A错）、原发性主动转运（B错）、易化扩散（C错）、Na⁺-Ca²⁺交换（E错）都需要借助载体完成跨膜转运，均存在饱和现象。单纯扩散（D对）是一种简单的穿越质膜的物理现象，无需载体参与，其速率主要取决于被转运物在膜两侧的浓度差和膜对该物质的通透性，不存在饱和现象。","","N"],["2000-N3",9,"第1节 神经系统功能活动的基本原理","影响递质释放的因素",2000,3,"A","","下列哪一项在突触前末梢释放递质中的作用最关键",[["A","动作电位到达神经末梢"],["B","神经末梢去极化"],["C","神经末梢处的Na⁺内流"],["D","神经末梢处的K⁺外流"],["E","神经末梢处的Ca²⁺内流"]],"E","当神经纤维传来的动作电位到达神经末梢时，造成神经末梢发生去极化，神经末梢处的电压门控Ca²⁺通道开放，Ca²⁺借助于膜两侧的电化学驱动力流入神经末梢内，使末梢轴浆内Ca²⁺浓度升高。Ca²⁺可启动突触囊泡的出胞机制，将囊泡内的神经递质排放到突触间隙（E对）。","","N"],["2000-N4",3,"第1节 心脏的泵血功能","心肌异长自身调节",2000,4,"A","","心室肌前负荷增加时",[["A","心室肌舒张末期压力降低"],["B","心室肌最大张力减小"],["C","心室肌收缩初速度减慢"],["D","心室肌达到最大张力所需的时间缩短"],["E","心室肌收缩产生的张力增加"]],"E","心室肌的前负荷是指心室肌在收缩前所承受的负荷，该负荷可以用心室舒张末期容积或心室舒张末期压力来表示。心室肌前负荷增加时，心室舒张末期压力升高（A错）。心室肌的前负荷的增加，即心室舒张末期容积增大，心肌细胞肌节初长度增加，粗、细肌丝的有效重叠程度增加，活化时形成的横桥连接的数目增多，因而肌节以至整个心室的收缩力加强（E对B错）。心室肌缩短初速度、心室肌达到最大张力所需的时间均与后负荷有关，与前负荷无关（CD错）。","","N"],["2000-N5",3,"第3节 血管生理","影响动脉血压的因素",2000,5,"A","","当每搏输出量和外周阻力不变时，心率降低可引起下列哪一项增加",[["A","动脉收缩压"],["B","动脉舒张压"],["C","动脉平均压"],["D","动脉脉搏压"],["E","心输出量"]],"D","心率降低时，心室舒张期延长，因此在心舒期从大动脉流向外周的血量增加，存留在主动脉内的血量减少，致使舒张压明显降低（B错）。由于舒张期末主动脉内存留的血量减少，致使收缩期动脉内的血量减少，收缩压也相应降低（A错），但收缩压的大小主要受心脏每搏输出量的影响，由于心脏每搏输出量不变，因此收缩压降低不如舒张压降低明显，故脉压增加（D对）。平均动脉压是指一个心动周期中每一瞬间动脉血压的平均值，由于代表最高血压的收缩压和最低血压的舒张压均降低，故平均动脉压也降低（C错）。心输出量即每分输出量，等于每搏输出量与心率的乘积，每搏输出量不变，心率降低时，心输出量也降低（E错）。","","N"],["2000-N6",3,"","",2000,6,"A","","下列哪一项变化可以在心电图中看到",[["A","窦房结去极化"],["B","心房肌去极化"],["C","房间束去极化"],["D","房室结去极化"],["E","希氏束去极化"]],"B","正常心电图由P波、QRS波群、T波和U波等组成。心电图的各段波形反映心脏不同部位的去极化或复极化过程。窦房结位于右心房外膜上，窦房结的激动首先传导至右心房，再通过房间束传到左心房。在此转导过程中，左右心房肌细胞被激活，完成去极化过程，产生明显的综合电位，形成心电图上可以记录到的P波（B对），而窦房结和房间束去极化过程中产生的综合电位很小，在体表心电图上记录不到（AC错）。激动继续沿前中后结间束传导到房室结，由于房室结传导速度缓慢，形成了心电图上PR间期，激动越过房室结后经希氏束、左右束支传导，同步激动左右心室，形成QRS波群，在此转导过程中，房室结和希氏束去极化过程中产生的综合电位很小，在体表心电图上记录不到（DE错）。","","N"],["2000-N7",3,"第3节 血管生理","血压",2000,7,"A","","当安静卧位时，下列哪一项前后两个部位的血压差最大",[["A","升主动脉和桡动脉"],["B","大隐静脉和右心房"],["C","股动脉和股静脉"],["D","肺动脉和左心房"],["E","毛细血管的动脉端和静脉端"]],"C","从左心室射出的血液流经外周血管时，由于不断克服血管对血流的阻力而消耗能量，血压逐渐降低。血压在各段血管中的下降幅度与该段血管对血流阻力的大小成正比。在主动脉和大动脉段，血压降幅较小，到小动脉时，血流阻力增大，血压降落的幅度也变大。在体循环中，微动脉段的血流阻力最大，血压降幅也最显著。各选项中只有股动脉→股静脉（C对）和肺动脉→左心房（D错）流经了微动脉，故首先排除A、B、E选项。由于肺动脉压只有主动脉压的1/6（十版生理学P81），肺循环的血压下降幅度远小于体循环，故股动脉→股静脉的血压差大于肺动脉→左心房的血压差（C对）。","","N"],["2000-N8",3,"第3节 血管生理","静脉血压",2000,8,"A","","下列关于中心静脉压的叙述，哪一项是错误的",[["A","是指胸腔大静脉和右心房的血压"],["B","心脏射血能力减弱时，中心静脉压较低"],["C","正常变动范围为0.4～1.2kPa（4～12cmH₂O）"],["D","是反映心脏功能的一项指标"],["E","静脉输液量大且过快时，中心静脉压升高"]],"B","心脏射血能力减弱时，心室内剩余血量增加，心舒期室内压升高，从而对心房和静脉内血液的抽吸作用减弱，血液淤积于右心房和大静脉内，中心静脉压升高（B错，为本题正确答案）。例如，右心衰时，右心室射血能力明显减弱，心舒期血液淤积于右心房和大静脉内，致使右心室内压较高，回心血量显著减少，患者可出现颈静脉怒张、肝充血肿大、下肢水肿等体征。","","N"],["2000-N9",4,"第1节 肺通气","肺容量",2000,9,"A","","下列有关肺总量的叙述，哪一项是错误的",[["A","在不同个体，有年龄和性别的差异"],["B","与体型大小、运动锻炼情况有关"],["C","是指肺所容纳的最大气量"],["D","因体位变化而异"],["E","是肺活量与功能余气量之和"]],"E","肺总量指深吸气后肺内所含的气体量，为肺所能容纳的最大气体量，等于肺活量与余气量之和（E错，为本题正确答案），其大小可因性别（成年男性平均约为5000ml，女性约为3500ml）、年龄、身材、运动锻炼情况和体位改变而异。患有限制性通气功能障碍疾病（肺纤维化、胸腔积液等）时肺总量将明显下降，患有阻塞性通气功能障碍疾病（COPD、哮喘等）时肺总量则正常或增高。","","N"],["2000-N10",4,"第2节 肺换气和组织换气","气体的分子量和溶解度",2000,10,"A","","O₂的弥散系数与CO₂的弥散系数相比较",[["A","前者大，因为O₂可与血红蛋白结合"],["B","前者小，因为O₂的溶解度低"],["C","前者大，因为O₂分压梯度大"],["D","前者小，因为O₂的相对分子质量小"],["E","基本相同"]],"B","扩散系数（弥散系数）与气体溶解度成正比，与气体分子量的平方根成反比，O₂在血浆中的溶解度比CO₂小得多，导致O₂的弥散系数与CO₂的弥散系数相比要小得多（B对）。","","N"],["2000-N11",4,"第4节 呼吸运动的调节","CO₂、H⁺、O₂对呼吸运动的调节",2000,11,"A","","下列哪种情况下动脉血CO₂分压降低",[["A","贫血"],["B","CO中毒"],["C","中等度运动"],["D","氰化物中毒"],["E","过度通气后"]],"E","动脉血CO₂分压与溶解于血浆中CO₂量有关，它反映肺泡通气量的水平，只要外呼吸肺换气过程不出问题，动脉血CO₂分压总是正常的。如果肺通气量不足，CO₂在体内潴留，动脉血CO₂分压将上升，PCO₂＞6kPa时为高碳酸血症，发生呼吸性酸中毒，如果肺过度通气，CO₂排出过多，动脉血CO₂分压将下降（E对），PCO₂＜5.30kPa时为低碳酸血症，发生呼吸性碱中毒。贫血（A错）、CO中毒（B错）、氰化物中毒（D错）时，肺泡通气量并无改变，动脉血CO₂分压均正常（经过肺换气过程后，动脉血CO₂分压总是接近于肺泡气CO₂分压的，约为40mmHg）。运动时，机体的代谢活动增强，代谢产生的CO₂增多，使动脉血中的CO₂分压升高，但是动脉血中CO₂分压升高能够通过化学感受性呼吸反射，引起呼吸加深加快，促进CO₂的排出，使动脉血中的CO₂分压降至接近正常水平。中等运动时，动脉血中的CO₂分压一般正常（C错），剧烈运动时，动脉血中的CO₂分压一般略微升高。","","N"],["2000-N12",5,"第3节 胃内消化","胃的运动形式",2000,12,"A","","胃容受性舒张的主要刺激物是",[["A","胃中的食物"],["B","小肠中的食物"],["C","咽部和食管中的食物"],["D","胆囊收缩素"],["E","促胰液素"]],"C","当咀嚼与吞咽食物时，由于食物对口腔、咽、食管等处感受器的刺激（C对），通过迷走-迷走反射，引起胃底、胃体部肌肉发生一定程度的舒张，即容受性舒张。容受性舒张的生理意义在于适应大量食物的暂时储存，同时保持胃内压基本不变，从而防止食糜过早排入小肠，有利于食物在胃内的充分消化。","","N"],["2000-N13",5,"第2节 口腔内消化和吞咽","唾液分泌的调节",2000,13,"A","","下列哪一项分泌最依赖副交感神经",[["A","唾液"],["B","胃液"],["C","胃蛋白酶原"],["D","胰液"],["E","胆汁"]],"A","胃液、胃蛋白酶原、胰液和胆汁接受神经调节和体液调节的双重调节，唾液则主要接受神经调节，支配唾液腺的神经纤维包括副交感神经和交感神经两种，副交感神经引起量多而固体成分少的稀薄唾液分泌，交感神经则引起量少而固体成分多的黏稠唾液分泌，其中副交感神经对唾液的分泌刺激起主要作用（A对）。","","N"],["2000-N14",5,"第3节 胃内消化","内因子",2000,14,"A","","胃壁细胞分泌",[["A","胃泌素"],["B","黏液"],["C","胆囊收缩素"],["D","内因子"],["E","促胰液素"]],"D","胃泌素是由胃窦部G细胞分泌的（A错）。黏液由胃黏膜表面的上皮细胞、泌酸腺、贲门腺、幽门腺的黏液细胞共同分泌的（十版生理学P173）（B错）。胆囊收缩素是由小肠黏膜I细胞分泌（C错）。促胰液素是由小肠黏膜S细胞分泌（E错）。","","N"],["2000-N15",7,"","",2000,15,"A","","血中某种物质的肾阈是指",[["A","该溶质的最大滤过率"],["B","该溶质的最大重吸收率"],["C","该溶质开始在尿中出现的血浆浓度"],["D","该溶质的分泌率"],["E","该溶质在肾小管的最大分泌能力"]],"C","血中某种物质的肾阈是指该溶质开始在尿中出现的血浆浓度（C对）。","","N"],["2000-N16",7,"第5节 尿生成的调节","肾素分泌的调节",2000,16,"A","","肾素分泌增多时，可引起下列哪一项升高",[["A","血浆K⁺浓度"],["B","细胞外液量"],["C","红细胞比容"],["D","血浆胶体渗透压"],["E","血液中H⁺浓度"]],"B","当血浆肾素分泌增加时，通过交感-肾素-血管紧张素-醛固酮调节轴，促进醛固酮分泌增加，醛固酮可以促进远曲小管和集合管保钠保水排钾，使血钾浓度降低（A错）、细胞外液容积增加（B对），血液被稀释，红细胞比容、血液中H⁺浓度和血浆胶体渗透压均降低（CDE错）。","","N"],["2000-N17",9,"第3节 神经系统对躯体运动的调控","牵张反射的感受器",2000,17,"A","","下列有关肌梭感受器的论述中，错误的是",[["A","感受装置位于肌梭中间部位"],["B","肌梭的传入神经为Ⅰa类和Ⅱ类纤维"],["C","肌梭是感受肌纤维长度的感受器"],["D","梭外肌收缩时，感受器受到的牵拉刺激增加"],["E","梭内肌收缩时，感受器的敏感性提高"]],"D","肌梭是牵张反射的感受器，它位于一般肌纤维之间，呈梭状，其外包被一层结缔组织囊，囊内含6～12根肌纤维，称为梭内肌纤维，梭内肌纤维由位于两端的收缩成分和位于中间的感受装置所构成（A对），两者呈串联关系。当肌肉受外力牵拉而使肌梭被拉长时（C对），作为传入神经的Ⅰa类和Ⅱ类纤维的传入冲动增加（B对），引起支配同一肌肉的α运动神经元兴奋，使梭外肌收缩，形成一次牵张反射，梭外肌收缩可以引起与其并联的梭内肌缩短（被动缩短，非主动收缩，后者使肌梭感受器所受的牵拉刺激增加），肌梭感受器所受的牵拉刺激减少（D错，为本题正确答案）。肌梭感受器所受的牵拉刺激减少将导致Ⅰa纤维传入冲动减少，α运动神经元兴奋减弱，传出冲动减少，梭外肌松弛，按照此调节机制，受牵拉时持续收缩的肌紧张状态将不会存在。但是肌紧张是维持身体姿势最基本的反射活动，也是随意运动的基础，肌紧张是持续存在的，这与γ运动神经元介导梭内肌收缩，提高肌梭感受器的敏感性有关：肌梭（梭内肌）受γ运动神经元支配，当γ传出纤维受刺激，使肌梭收缩成分收缩时，其收缩强度虽不足以引起整块肌肉缩短，但可牵拉肌梭感受装置（肌梭收缩成分与感受装置为串联关系），引起Ⅰa类传入纤维放电增加。γ运动神经元兴奋性很高，可以在高位脑中枢的影响下以较高频率持续放电，在整体情况下，即使肌肉不活动，α运动神经元无放电时，有些γ运动神经元仍持续放电，当α运动神经元活动增加时，γ运动神经元放电也相应增加，这可防止当梭外肌收缩时肌梭因受牵拉刺激减少而停止放电的发生，所以，γ运动神经元介导的梭内肌收缩可以提高调节肌梭感受器的敏感性（E对）。","","N"],["2000-N18",9,"第4节 神经系统对内脏活动、本能行为和情绪的调节","交感神经系统的功能",2000,18,"A","","交感神经活动增强时，下列哪一项不出现",[["A","肠蠕动抑制"],["B","瞳孔开大肌收缩"],["C","肾素分泌"],["D","胰岛素分泌"],["E","骨骼肌血管舒张"]],"D","大多数交感节后纤维释放的递质是去甲肾上腺素（除支配汗腺和骨骼肌血管的交感节后纤维释放乙酰胆碱外），交感神经系统的活动与各器官上去甲肾上腺素受体的分布有关。交感神经兴奋时，作用于小肠平滑肌的α₂受体或β₂受体使小肠平滑肌舒张，抑制肠蠕动（A对）；作用于瞳孔开大肌（虹膜辐射状肌）的α₁受体使瞳孔开大肌收缩（B对），瞳孔扩大；作用于骨骼肌血管的β₂受体（去甲肾上腺素介导）或M受体（乙酰胆碱介导）使骨骼肌血管舒张（E对）；作用于肾脏颗粒细胞（球旁细胞）膜中的β₁受体使肾素分泌增多（C对）；作用于胰岛β细胞（即B细胞）上的α₂受体抑制胰岛素分泌（D错，为本题正确答案）。交感神经兴奋的状态可以用机体在剧烈运动时的生理状态来协助记忆：机体在剧烈运动时交感神经兴奋（十版生理学P322），心率加快、心肌收缩力增强，心输出量增加，目的是为全身的肌肉提供更多的血液和氧气；呼吸运动加强，支气管平滑肌舒张，肺泡通气量，目的是为了血液提供更多的氧气；皮肤、肾、胃肠等全身各处的血管平滑肌均收缩，但骨骼肌血管舒张，目的是为了让血液重新分配，为肌肉提供更多的血液；由于全身血液分配至骨骼肌，导致胃肠道供血不足，不利于胃肠道进行消化和吸收，故消化道平滑肌舒张，括约肌收缩，消化腺分泌减少；由于全身血液分配至骨骼肌，肾供血也不足，故肾素分泌增多；剧烈运动时，甲状腺激素、胰高血糖素等分解代谢的激素分泌增多，胰岛素等促进合成代谢的激素分泌减少，目的是为了骨骼肌提供更多的能量来源等等。","","N"],["2000-N93",3,"","",2000,93,"B","","影响脑血管舒缩活动的主要因素有",[["A","机能性充血"],["B","组织胺"],["C","高血压"],["D","CO₂分压变化"],["E","毛细血管血压"]],"D","脑血流量主要受两个方面的调节1.当平均动脉压在60-140mmHg范围内变动时，脑血管可通过肌源性自身调节机制使脑血流量保持相对稳定；2.CO₂分压升高（D对）和O₂分压下降时，脑血管舒张，脑血流量增加。至于在全身心血管活动调节中发挥重要作用的神经调节，对脑血管的调节作用并不大，正是这一调节特点保证了脑组织在人体缺血、缺氧等紧急状况下的血液供应：缺血缺氧时，在压力感受性反射和化学感受性反射等心血管反射活动的调节下，交感神经兴奋性增强，人体内的大部分血管收缩，总外周阻力增大，血压升高，由于脑血管无明显收缩或发生轻微舒张（受CO₂分压升高和低氧的舒血管作用），使循环血量得以重新分配，从而保证了脑血流的优先供应（冠脉血流也存在优先供血机制，参见2003N130X的答案解析）。","","N"],["2000-N94",3,"第3节 血管生理","影响组织液生成的因素",2000,94,"B","","正常时影响毛细血管滤过量变化的主要因素是",[["A","机能性充血"],["B","组织胺"],["C","高血压"],["D","CO₂分压变化"],["E","毛细血管血压"]],"E","毛细血管滤过量主要由有效滤过压和滤过系数决定。有效滤过压=（毛细血管血压+组织液胶体渗透压）-（组织液静水压+血浆胶体渗透压），滤过系数的大小取决于毛细血管壁对液体的通透性和滤过面积。因此影响毛细血管滤过量变化的因素包括毛细血管血压（E对）、组织液静水压、组织液胶体渗透压、血浆胶体渗透压、毛细血管壁通透性、毛细血管管壁的滤过面积等。","","N"],["2000-N95",5,"第4节 小肠内消化","促胰液素",2000,95,"B","","引起胰腺分泌大量水分和碳酸氢盐的是",[["A","胃泌素"],["B","促胰液素"],["C","胆囊收缩素"],["D","血管活性肠肽"],["E","乙酰胆碱"]],"B","胰腺兼有外分泌（分泌胰液）和内分泌（分泌胰岛素）的双重功能，其中分泌胰液的外分泌部分由腺泡及导管两个部分组成，腺泡主要分泌胰酶，导管则主要分泌水和碳酸氢盐。促胰液素主要作用于胰腺导管上皮细胞，可引起胰液分泌大量水分和碳酸氢盐（B对）。胆囊收缩素和迷走神经（释放乙酰胆碱）则主要作用于胰腺腺泡细胞，促进胰酶分泌，水分和碳酸氢盐的分泌量较少（CE错）。胃泌素具有与缩胆囊素相似的作用，以促进胰酶分泌为主，且作用较弱（A错）。血管活性肠肽虽然具有与促胰液素有相似的作用，但作用较弱，不足以引起胰液分泌大量水分和碳酸氢盐（D错）。","","N"],["2000-N96",5,"第3节 胃内消化","促进胃液分泌的主要因素",2000,96,"B","","主要刺激胃酸分泌的激素是",[["A","胃泌素"],["B","促胰液素"],["C","胆囊收缩素"],["D","血管活性肠肽"],["E","乙酰胆碱"]],"A","胃泌素又称促胃液素，是促进胃酸分泌最主要的激素（A对）。乙酰胆碱也可促进胃酸分泌，但其作用不及促胃液素大，且不属于激素（E错）。促胰液素（B错）、胆囊收缩素（C错）、血管活性肠肽（D错）表现为抑制胃酸分泌。","","N"],["2000-N117",3,"第3节 血管生理","影响动脉血压的因素",2000,117,"C","","心室收缩力降低时",[["A","心室舒张末期压力增高"],["B","动脉舒张压增高"],["C","二者都有"],["D","二者都无"]],"A","心室收缩力下降时，心脏每搏输出量减少，射血后心室内剩余血量增多，即心室收缩末期容积增多，若舒张期静脉回心血量不变或无明显减少，则心室舒张末期容积增大（压力升高）（A对）。心室收缩力下降时，心脏每搏输出量减少，心缩期射入主动脉的血量减少，动脉收缩压和舒张压均减小（B错）。","","N"],["2000-N118",3,"第3节 血管生理","影响动脉血压的因素",2000,118,"C","","心率增快时",[["A","心室舒张末期压力增高"],["B","动脉舒张压增高"],["C","二者都有"],["D","二者都无"]],"B","心率增快时，心室舒张期缩短，静脉回流量减少，心室舒张末期压力降低（A错），心室舒张期缩短也使心舒期从大动脉流向外周的血量减少，存留在主动脉内的血量增多，导致舒张压升高（B对）。","","N"],["2000-N119",6,"第2节 体温及其调节","温度感受器",2000,119,"C","","参与体温调节的神经元是",[["A","热敏神经元"],["B","冷敏神经元"],["C","二者都是"],["D","二者都无"]],"C","根据感受器存在的部位，可将温度感受器分为外周温度感受器和中枢温度感受器。外周温度感受器是存在于皮肤、黏膜和内脏中的对温度变化敏感的游离神经末梢，包括热感受器和冷感受器；中枢温度感受器是存在于中枢神经系统内对温度变化敏感的神经元，包括热敏神经元（A对）和冷敏神经元（B对），在一定范围内，热敏神经元表现为在局部组织温度升高时发放冲动频率增加，冷敏神经元则在局部组织温度降低时发放冲动频率增加。本题AB均对，正确答案为C。","","N"],["2000-N120",6,"第2节 体温及其调节","温度感受器",2000,120,"C","","脑组织温度下降时，放电频率增加的是",[["A","热敏神经元"],["B","冷敏神经元"],["C","二者都是"],["D","二者都无"]],"B","热敏神经元和冷敏神经元均属于中枢温度感受器，在一定范围内，热敏神经元表现为在脑组织温度升高时发放冲动频率增加；冷敏神经元则在脑组织温度下降时发放冲动频率增加（B对）。","","N"],["2000-N121",10,"第5节 肾上腺内分泌","反馈调节",2000,121,"C","","腺垂体分泌ACTH的活动",[["A","受靶腺激素反馈调节"],["B","受下丘脑控制"],["C","两者都有"],["D","两者都无"]],"C","ACTH即促肾上腺皮质激素（adreno-cortico-tropic-hormone），由腺垂体ACTH细胞所分泌（十版生理学P370），ACTH细胞同时受下丘脑控制和靶腺激素反馈调节（AB对）：下丘脑室旁核分泌促肾上腺皮质激素释放激素（CRH）与血管升压素（VP），通过垂体门脉系统到达腺垂体，分别与ACTH细胞CRH受体-1和V₃R结合，促进腺垂体分泌ACTH，继而促进糖皮质激素（GC）的分泌。当血中GC浓度升高以后，又可反馈抑制腺垂体ACTH细胞和下丘脑CRH神经元的活动，使ACTH、CRH的合成和分泌减少。本题AB均对，正确答案为C。","","N"],["2000-N122",10,"第2节 下丘脑-垂体及松果体内分泌","腺垂体激素的概述",2000,122,"C","","腺垂体分泌生长激素的活动",[["A","受靶腺激素反馈调节"],["B","受下丘脑控制"],["C","二者都有"],["D","二者都无"]],"B","腺垂体分泌生长激素的活动受下丘脑GHRH（生长激素释放激素）与GHIH（生长激素抑制激素）的双重调节（B对），但是由于生长激素不是作用于靶腺，而是直接作用于靶组织或靶细胞，故腺垂体分泌生长激素的活动不存在靶腺激素反馈调节（A错）。","","N"],["2000-N139",7,"第5节 尿生成的调节","抗利尿激素",2000,139,"X","","下列哪些可引起大量饮水和尿量增多",[["A","ADH释放减少"],["B","胰岛素分泌明显减少"],["C","大量出汗、严重呕吐或腹泻"],["D","有效循环血量增多"]],"AB","ADH（抗利尿激素）释放减少时，水的重吸收减少，尿量增加，致体内缺水，失水严重时，血浆晶体渗透压升高，刺激下丘脑渗透压感受器，引发渴觉，促使机体饮水量增加（A对）。胰岛素分泌减少，导致血糖升高，超过肾糖阈时引起渗透性利尿，尿量增多，引起机体失水，血浆晶体渗透压升高，引起渴觉，促使机体饮水量增加（B对）。大量出汗、严重呕吐或腹泻等情况可引起机体大量失水，血浆晶体渗透压升高，刺激抗利尿激素分泌，肾小管和集合管对水的重吸收增多，尿量减少（C错）。有效循环血量增多，静脉回心血量增加，可刺激心肺感受器，抑制抗利尿激素（血管升压素）释放，尿量增多，但由于晶体渗透压无明显变化，不会导致大量饮水（D错）。","","N"],["2000-N140",10,"","",2000,140,"X","","调节肾上腺髓激素分泌的因素有",[["A","交感神经"],["B","ACTH和糖皮质激素"],["C","自身负反馈机制"],["D","肾素-血管紧张素"]],"ABC","肾上腺髓质激素包括肾上腺素、去甲肾上腺素和多巴胺，均为儿茶酚胺类激素。其分泌调节因素包括：①交感神经的作用：交感神经兴奋时，节前纤维末梢释放乙酰胆碱，作用于嗜铬细胞膜中的N₁受体，促使肾上腺髓质激素的合成和分泌（A对）；②ACTH和糖皮质激素的作用：腺垂体分泌的ACTH可直接或间接（通过引起糖皮质激素分泌）提高嗜铬细胞内肾上腺髓激素合成酶的活性，促进肾上腺髓激素的分泌（B对）；③自身负反馈机制：当肾上腺髓质嗜铬细胞中去甲肾上腺素或多巴胺含量增多到一定水平时，可反馈抑制酪氨酸羟化酶的活性；而当肾上腺素合成增多到一定程度时，则可负反馈抑制PNMT的活性，阻止肾上腺髓质激素的进一步合成（C对）。肾素-血管紧张素系统（十版生理学P371）可调节肾上腺盐皮质激素（醛固酮）的分泌，但与肾上腺髓质激素分泌无关（D错）。","","N"],["2000-N141",9,"第3节 神经系统对躯体运动的调控","对侧伸肌反射",2000,141,"X","","关于屈反射",[["A","是多突触反射"],["B","脊髓离断后减弱"],["C","后放是它的一个特征"],["D","Babinski's征属于屈反射"]],"ACD","当脊动物一侧肢体的皮肤受到伤害性刺激时，受刺激的一侧的肢体出现屈曲反应，关节的屈肌收缩和伸肌舒张，称屈（肌）反射。屈肌反射是多突触反射（A对），它的基本中枢在脊髓，可受高位中枢的调节，由于高位中枢平时具有易化伸肌反射和抑制屈肌反射的作用，所以当脊髓离断后，抑制屈肌反射的作用消失，屈反射增强（B错），注意当脊髓离断时，脊休克未恢复时，屈反射消失。屈反射的神经通路中存在环式联系，在刺激停止的最初一段时间，由于神经冲动通过环状联系反复兴奋，屈肌活动仍在进行，称为后放（电）（C对）。成年人Babinski's征的正常表现是一种屈肌反射（D对）：用一钝物划足跖外侧，所有足趾均发生跖屈，称为Babinski's征阴性，当刺激加强时，还可出现踝、膝、髋关节的屈曲。但在皮层脊髓束受损的病人，Babinski's征呈阳性，表现为𧿹趾背屈和其他四趾外展呈扇形散开的体征，这是一种异常的伸肌反射。","","N"],["2000-N142",8,"第4节 听觉","中耳的功能(1)",2000,142,"X","","鼓膜",[["A","使传入耳内的声波频率明显改变"],["B","有较好的频率响应和较小的失真度"],["C","咽鼓管阻塞时，可使其内陷"],["D","是一个平面膜"]],"BC","鼓膜是中耳内的一个压力承受装置，声波经外耳道传入中耳时可以引起鼓膜振动，并将声波的振动频率转换为其本身的振动频率，再向下传到听骨链，经卵圆窗膜进入耳蜗。在这个转换过程中鼓膜有较好的频率响应（即鼓膜本身的振动频率和声波的振动频率有较好的相关性）和较小失真度（即转换过程中不会增加新的不相关的频率）（Ｂ对A错）。咽鼓管是连接鼓室和鼻咽部的通道，它使鼓室与大气相通，因而正常情况下鼓室内压力与大气压相同，咽鼓管阻塞时，鼓室内的空气可被吸收，气压降低，鼓膜可向内凹陷（Ｃ对）。鼓膜呈椭圆形，浅漏斗状，而不是平面膜（D错）。","","N"],["2001-N1",1,"第1节 细胞膜的物质转运功能","单纯扩散",2001,1,"A","","下列跨膜转运的方式中，不出现饱和现象的是",[["A","与Na⁺耦联的继发性主动转运"],["B","原发性主动转运"],["C","易化扩散"],["D","单纯扩散"],["E","Na⁺-Ca²⁺交换"]],"D","由于细胞膜中载体的数量和转运速率有限，当被转运的底物浓度增加到一定程度时，底物的扩散速度便达到最大值，不再随底物浓度的增加而增大，这种现象称为载体转运的饱和现象。继发性主动转运（A错）、原发性主动转运（B错）、易化扩散（C错）、Na⁺-Ca²⁺交换（E错）都需要借助载体完成跨膜转运，均存在饱和现象。单纯扩散（D对）是一种简单的穿越质膜的物理现象，无需载体参与，其速率主要取决于被转运物在膜两侧的浓度差和膜对该物质的通透性，不存在饱和现象。","","N"],["2001-N2",1,"第3节 细胞的电活动","静息电位的产生机制",2001,2,"A","","神经纤维安静时，下面说法错误的是",[["A","跨膜电位梯度和Na⁺的浓度梯度方向相同"],["B","跨膜电位梯度和Cl⁻的浓度梯度方向相同"],["C","跨膜电位梯度和K⁺的浓度梯度方向相同"],["D","跨膜电位梯度阻碍K⁺外流"],["E","跨膜电位梯度阻碍Na⁺外流"]],"C","安静时（静息状态），神经纤维细胞膜电位处于外正内负的状态，跨膜电位梯度为细胞内小于细胞外，Na⁺的浓度梯度和Cl⁻的浓度梯度也是细胞内小于细胞外（AB对），而K⁺的浓度梯度则是细胞内大于细胞外（C错，为本题正确答案）。外正内负的跨膜电位梯度，可以阻碍带正电荷的K⁺和Na⁺的外流（DE对）。需要注意的是，静息状态下，K⁺的电驱动力由外向内，浓度差驱动力却由内向外，两种驱动力方向相反，大小相等，而Na⁺的电驱动力由外向内（与K⁺同为正电荷，故所受电驱动力方向一致），浓度差驱动力也是由外向内，与电驱动力方向相同，导致Na⁺在静息状态下受到强大的内向驱动力，一旦细胞受到刺激，Na⁺通道开放，Na⁺将在内向驱动力的作用下大量内流。","","N"],["2001-N3",1,"第3节 细胞的电活动","钠泵的生电作用",2001,3,"A","","细胞外液的K⁺浓度明显降低时，将引起",[["A","Na⁺-K⁺泵向胞外转运Na⁺增多"],["B","膜电位负值减小"],["C","膜的K⁺电导增大"],["D","Na⁺内流的驱动力增加"],["E","K⁺平衡电位的负值减小"]],"D","细胞外液K⁺浓度下降时，细胞内K⁺外流增多，K⁺平衡电位的负值增大（或叫绝对值增大）（E错），由于细胞的静息膜电位约等于K⁺平衡电位，故膜电位的负值也增大（B错），膜电位的负值增大，Na⁺作为正电荷受到的内向驱动力也增大（D对）。细胞外K⁺浓度改变只影响内向整流钾通道的电导，而内向整流钾通道存在于心肌细胞膜上，骨骼肌和神经细胞的非门控钾通道不受细胞外K⁺浓度降低的影响，因此细胞外K⁺浓度明显降低对两类细胞的影响也有所不同：对于心肌细胞而言，低钾血症时，K⁺的通透性降低，K⁺电导下降；对于神经细胞和骨骼肌细胞而言，低钾血症时，细胞膜发生超极化，K⁺电导不变（C错）。细胞外液的K⁺浓度升高时，Na⁺-K⁺泵被激活，向胞外转运Na⁺增多；相反，细胞外液的K⁺浓度降低时，Na⁺-K⁺泵被抑制，向胞外转运Na⁺减少（A错）。","","N"],["2001-N4",1,"第3节 细胞的电活动","动作电位期间膜离子通透性的变化",2001,4,"A","","在神经纤维，Na⁺通道失活的时间在",[["A","动作电位的上升相"],["B","动作电位的下降相"],["C","动作电位超射时"],["D","绝对不应期"],["E","相对不应期"]],"B","当神经细胞受到有效刺激时，Na⁺通道激活，Na⁺内流引起细胞的去极化，使膜电位急剧上升，形成动作电位的上升相，Na⁺通道大量激活使去极化电位到达峰值后，Na⁺通透性迅速下降，Na⁺通道逐渐失活，Na⁺内流减少，而K⁺通透性逐渐增大，K⁺通道开放增多，K⁺外流增多，细胞膜迅速复极化，形成动作电位的下降相（B对）。超射为细胞膜电位高于零电位的部分，既包括部分动作电位的上升相也包括部分动作电位的下降相，既包括Na⁺通道的激活也包括Na⁺通道的失活（C对）。绝对不应期时，大部分Na⁺通道已进入失活状态（D对），细胞兴奋性为零，不可能再次接受刺激而激活。相对不应期时，失活的电压门控钠通道虽已开始复活，但复活的通道数量较少，部分仍处于失活状态（E对）。因此，对神经纤维来说，BCDE选项均存在Na⁺通道失活，但本题给出的正确答案仅为B。值得注意的是，对心肌细胞来说，本题的A选项也是正确的，因为介导心肌细胞去极化的INa通道是一种快通道，它不但激活快，而且激活后失活也快，当膜去极化到一定程度（0mV左右）时（此时仍处于动作电位的上升相），INa通道就开始失活而关闭，最后使INa终止（十版生理学P91）。","","N"],["2001-N5",1,"第4节 肌细胞的收缩","骨骼肌神经肌肉接头处的兴奋传递",2001,5,"A","","下列有关神经-肌肉接点处终板膜上离子通道的叙述，错误的是",[["A","对Na⁺和K⁺均有选择性"],["B","当终板膜去极化时打开"],["C","开放时产生终板电位"],["D","是N₂-ACh受体通道"],["E","受体和通道是一个大分子"]],"B","神经-肌接头处兴奋传导的具体过程为：运动神经纤维传到末梢的动作电位触发接头前膜Ca²⁺依赖性突触囊泡出胞，释放ACh至接头间隙，再由ACh激活终板膜中的N₂型ACh受体阳离子通道，产生终板膜电位变化（去极化）。所以，神经-肌接头处终板膜上离子通道开放使终板膜发生了去极化，而不是终板膜去极化使神经-肌接头处终板膜上离子通道开放，B选项属于典型的因果倒置（B错，为本题正确答案）。","","N"],["2001-N6",3,"第3节 血管生理","毛细淋巴管的结构特点及通透性",2001,6,"A","","成人每天的淋巴液流量大约为",[["A","20～40L"],["B","2～4L"],["C","200～400ml"],["D","20～40ml"],["E","2～4ml"]],"B","组织液进入淋巴管即成为淋巴液，成人每天的淋巴液流量大约为2～4L（B对）。淋巴管收集全身的淋巴液，最后经右淋巴导管和胸导管流入静脉，淋巴回流的生理意义在于回收蛋白质，运输脂肪及其他营养物质，同时可调节体液平衡，具有防御和免疫功能。","","N"],["2001-N7",3,"第1节 心脏的泵血功能","心室收缩的后负荷",2001,7,"A","","动脉血压突然升高时，将引起",[["A","左室射血速度增快"],["B","心输出量增加"],["C","左室收缩末期容积增加"],["D","左室射血时达到最高室压的时间缩短"],["E","左室射血时的最高室压下降"]],"C","心室收缩时须克服大动脉血压的阻力，才能将血液射入动脉。因此，动脉血压是心室收缩时所遇到的后负荷。动脉血压升高即后负荷增加，后负荷增加，心室开始射血的时间延长，心室射血时达到最高室压的时间（快速射血期末室内压最高，参见2003N93B）也相应延长（D错）。","","N"],["2001-N8",3,"第3节 血管生理","微循环的血流动力学",2001,8,"A","","调节器官血流量的主要血管是",[["A","毛细血管"],["B","微动脉"],["C","静脉"],["D","动-静脉吻合支"],["E","毛细血管后静脉"]],"B","微动脉为毛细血管前阻力血管的一种（另一种为小动脉），管壁富含平滑肌，其舒缩活动可使血管口径发生明显变化，从而调节对血流的阻力和所在器官、组织的血流量（B对）。","","N"],["2001-N9",3,"第3节 血管生理","影响动脉血压的因素",2001,9,"A","","心率减慢（其他影响血压的因素不变）时，将增加的是",[["A","动脉舒张压"],["B","动脉收缩压"],["C","平均动脉压"],["D","心输出量"],["E","动脉脉搏压"]],"E","心率减慢时，心室舒张期延长，因此在心舒期从大动脉流向外周的血量增加，存留在主动脉内的血量减少，致使舒张压明显降低（A错）。由于舒张期末主动脉内存留的血量减少，致使收缩期动脉内的血量减少，收缩压也相应降低（B错），但收缩压的大小主要受心脏每搏输出量的影响，由于心脏每搏输出量不变，因此收缩压降低不如舒张压降低明显，故脉压增加（E对）。平均动脉压是指一个心动周期中每一瞬间动脉血压的平均值，由于代表最高血压的收缩压和最低血压的舒张压均降低，故平均动脉压也降低（C错）。心输出量即每分输出量，等于每搏输出量与心率的乘积，每搏输出量不变，心率降低时，心输出量也降低（D错）。","","N"],["2001-N10",3,"第1节 心脏的泵血功能","心肌异长自身调节",2001,10,"A","","心室肌前负荷增加时，将出现",[["A","心室舒张末期室内压下降"],["B","心室收缩时最大张力下降"],["C","心室开始收缩时的速度减慢"],["D","心室收缩时达到最大张力的时间延迟"],["E","心室收缩时最大张力增加"]],"E","心室肌的前负荷是指心室肌在收缩前所承受的负荷，该负荷可以用心室舒张末期容积或心室舒张末期压力来表示。心室肌前负荷增加时，心室舒张末期压力升高（A错）。心室肌的前负荷的增加，即心室舒张末期容积增大，心肌细胞肌节初长度增加，粗、细肌丝的有效重叠程度增加，活化时形成的横桥连接的数目增多，因而肌节以至整个心室的收缩力加强（E对B错）。心室开始收缩时的速度、心室肌达到最大张力所需的时间均与后负荷有关，与前负荷无关（CD错）。","","N"],["2001-N11",4,"第2节 肺换气和组织换气","气体的分子量和溶解度",2001,11,"A","","与CO₂比较，O₂在体内的扩散系数",[["A","较大，因为O₂与血红蛋白结合"],["B","较小，因为O₂的溶解度低"],["C","较大，因为O₂的分压梯度大"],["D","较小，因为O₂的相对分子质量小"],["E","二者基本相同"]],"B","扩散系数与气体溶解度成正比，与气体分子量的平方根成反比，O₂在血浆中的溶解度比CO₂小得多，导致O₂的弥散系数与CO₂的弥散系数相比要小得多（B对）。","","N"],["2001-N12",4,"第1节 肺通气","胸膜腔内压",2001,12,"A","","吸气时膈肌收缩，胸内压将",[["A","等于零"],["B","负值减小"],["C","更负"],["D","等于肺泡内压"],["E","等于大气压"]],"C","胸内压即胸膜腔内压，等于肺内压与肺回缩压之差。胸膜腔内压在平静呼吸时始终低于大气压，若以大气压为0计算，则胸膜腔内压为负压，故胸膜腔内压又称胸膜腔负压。吸气时，肺容积增大，肺内压随之降低（P149），而肺的弹性回缩力（回缩压）却增加，故胸膜腔负压将变得会更负（C对）。","","N"],["2001-N13",4,"第1节 肺通气","肺泡通气量",2001,13,"A","","潮气量增加（其他因素不变）时，下列项目中将增加的是",[["A","死区通气"],["B","机能余气量"],["C","补吸气量"],["D","肺泡通气量"],["E","肺泡CO₂张力"]],"D","死区即无效腔，包括解剖无效腔和肺泡无效腔，亦可称为生理无效腔。健康人平卧时，生理无效腔等于或接近于解剖无效腔，约为150ml，无效腔的大小与潮气量的大小无关（A错）。机能余气量是指平静呼气末（呼气出的气体量称为潮气量）尚存留于肺内的气体量，潮气量增加时，存留于肺内的气体量减少，机能余气量减少（B错）。补吸气量是指平静吸气末（吸入的气体量称为潮气量）再尽力吸气所能吸入的气体量，潮气量增加时，再尽力吸气所能吸入的气体量减少，补吸气量也减少（C错）。肺泡通气量是指每分钟吸入肺泡的新鲜空气量，等于潮气量和无效腔气量之差与呼吸频率的乘积，故潮气量增加时，肺泡通气量增加（D对）。每分钟吸入肺泡的新鲜空气量增加，由于将肺泡的CO₂排出体外，降低肺泡CO₂张力（E错）。","","N"],["2001-N14",4,"第3节 气体在血液中的运输","氧的运输",2001,14,"A","","导致静脉O₂分压增高的情况有",[["A","氰化物中毒"],["B","体育锻炼"],["C","心输出量降低"],["D","贫血"],["E","CO中毒"]],"A","氰化物（CN⁻）可以阻断氧化呼吸链的电子传递过程（十版生物化学与分子生物学P216），使组织细胞不能利用氧，导致静脉O₂分压升高（A对），静脉血呈鲜红色。体育锻炼增加组织耗氧量，导致静脉O₂分压下降（B错）。心输出量减少时，流经组织的动脉血减少，单位体积的血流供氧量增加，导致静脉O₂分压下降（C错）。贫血时，动脉血氧分压虽正常（动脉血氧分压是指物理溶解于动脉血中的O₂产生的压力，而动脉血物理溶解的O₂来自肺换气过程中的肺泡气的直接供氧，故贫血时动脉血氧分压正常），但动脉血氧含量是下降的（动脉血氧含量的O₂仅1.5%是以物理溶解的形式运输的，其余98.5%是以与Hb化学结合的形式运输的，贫血时Hb含量下降，故动脉血氧含量下降），在组织耗氧量无明显改变的情况下，静脉血氧含量也是相应下降的，最终导致静脉O₂分压下降（静脉血分压是指物理溶解于静脉血中的O₂产生的压力，但是静脉血物理溶解的O₂来自化学结合的HbO₂的解离，静脉血氧含量下降，即HbO₂的含量下降，物理溶解的O₂相应减少）（D错）。动脉血流经组织时，物理溶解的O₂直接为组织供氧，氧分压下降，化学结合的O₂再解离出来，补充物理溶解的O₂，提高血氧分压，继续为组织供氧。CO中毒时，动脉血氧分压是正常的（原因与贫血时氧分压正常相同），但是CO与Hb分子中的一个血红素结合后，将增加其余3个血红素对O₂的亲和力，妨碍Hb与O₂的解离，使为组织供氧的物理溶解的O₂（氧分压的来源）得不到及时的补充，组织缺氧的同时静血氧分压显著下降（E错）。总结：动脉血氧分压和静脉血氧分压的来源是不同的，动脉血氧分压来自肺泡气，静脉血氧分压来自氧合血红蛋白。由于动脉血氧分压来自肺泡气，所以只要外呼吸肺换气过程不出问题，动脉血氧分压总是正常的，跟血红蛋白的数量和功能状态无关。由于静脉血氧分压来自氧合血红蛋白，只要血红蛋白的数量和功能状态出现问题（如贫血和CO中毒），静脉血氧分压就会下降。","","N"],["2001-N15",7,"","",2001,15,"A","","某物质的肾阈是指",[["A","该物质的最大滤过率"],["B","该物质的最大重吸收率"],["C","该物质开始在尿中出现的血浆浓度"],["D","该物质的最大分泌率"],["E","该物质的最大分泌能力"]],"C","血中某种物质的肾阈是指该溶质开始在尿中出现的血浆浓度（C对）。","","N"],["2001-N16",7,"第5节 尿生成的调节","肾素分泌的调节",2001,16,"A","","血浆中肾素增加时，将引起增加的是",[["A","血浆K⁺浓度"],["B","细胞外液容积"],["C","红细胞比容"],["D","血浆胶体渗透压"],["E","血液中H⁺浓度"]],"B","当血浆肾素分泌增加时，通过交感-肾素-血管紧张素-醛固酮调节轴，促进醛固酮分泌增加，醛固酮可以促进远曲小管和集合管保钠保水排钾，使血钾浓度降低（A错）、细胞外液容积增加（B对），血液被稀释，红细胞比容、血液中H⁺浓度和血浆胶体渗透压均降低（CDE错）。","","N"],["2001-N17",5,"第2节 口腔内消化和吞咽","唾液分泌的调节",2001,17,"A","","下列消化系统分泌物中，最依赖于迷走神经的是",[["A","唾液"],["B","盐酸"],["C","胃蛋白酶"],["D","胰液"],["E","胆汁"]],"A","盐酸、胃蛋白酶、胰液和胆汁接受神经调节和体液调节的双重调节，唾液则受神经调节，支配唾液腺的神经纤维包括副交感神经和交感神经两种，其中副交感神经对唾液的分泌刺激起主要作用。有必要讲一下副交感神经与迷走神经的区别和联系：迷走神经是12对脑神经中的第10对神经，与其他脑神经相比，迷走神经行程最长，分布也广，从运动器官到感觉器官，从颈部到胸腔，直至腹腔，因其“远走他乡”，“容易迷路”，所以叫迷走神经。迷走神经为混合性神经，包含特殊内脏运动纤维（传出纤维）、一般内脏运动纤维（传出纤维）、一般内脏感觉纤维（传入纤维）和一般躯体感觉纤维（传入纤维）四种纤维成分。其中一般内脏运动纤维即为副交感神经的节前纤维，是迷走神经的主要成分，经神经节换元之后支配心脏、支气管、食管、胃、肝、胰、脾、小肠、部分大肠等胸腹腔脏器的平滑肌及腺体。由于支配胸腹腔脏器的副交感神经节前纤维走行于迷走神经内，我们经常把支配胸腹腔脏器的副交感神经称为迷走神经，如教材上会说“心脏受交感神经和迷走神经的双重支配”，更严谨的说法应为“心脏受交感神经和副交感神经的双重支配，其中副交感部分来自迷走神经的副交感纤维”。那是否意味着副交感神经是迷走神经的一部分呢？也不是，副交感神经除了在第10对脑神经迷走神经中走行的部分外，还有部分在动眼神经（第3对脑神经）、面神经（第7对脑神经）、舌咽神经（第9对脑神经）及盆神经中走行。因此，迷走神经与副交感神经之间并不对等，它们之间具有相互包含的关系，而支配唾液腺的副交感神经是第7对脑神经—面神经和第9对脑神经—舌咽神经，并不是第10对脑神经—迷走神经。所以，本题给出题干迷走神经，并把支配唾液腺的副交感神经当成迷走神经是不正确的。实际上，迷走神经是神经纤维的一种解剖学上的定义，而副交感神经是功能上的定义，与副交感神经具有功能上的对应关系的是交感神经，交感神经和副交感神经构成了内脏神经系统（十版生理学P319）。","","N"],["2001-N18",5,"第3节 胃内消化","抑制胃液分泌的主要因素",2001,18,"A","","抑制胃液分泌的有",[["A","生长抑素"],["B","低张溶液"],["C","高pH"],["D","氨基酸"],["E","ACh"]],"A","能够影响胃液（胃酸）分泌的因素太多了，现将生理学七、八、九、十版教材提及的能够促进或抑制胃液分泌的因素总结如下：促进胃液分泌的因素包括进食（通过机械扩张或蛋白质消化产物肽和氨基酸的化学刺激）（D错）、ACh（迷走神经释放）（E错）、铃蟾素（蛙皮素）、组胺、促胃液素、Valosin（缬酪肽）、Ca²⁺、低血糖、咖啡因（咖啡、可口可乐、茶中含咖啡因）、酒精、肠泌酸素、糖皮质激素等；抑制胃液分泌的因素包括胃酸（C错）、脂肪、高张溶液（B错）、促胰液素、缩胆囊素、血管活性肠肽、生长抑素（A对）、表皮生长因子、抑胃肽等。","","N"],["2001-N93",5,"第3节 胃内消化","促进胃液分泌的主要因素",2001,93,"B","","分泌胃泌素的主要部位是",[["A","胃底部"],["B","胃窦部"],["C","小肠上部"],["D","回肠"],["E","结肠"]],"B","胃底部（A错）主要细胞是壁细胞和主细胞，壁细胞分泌盐酸和内因子，主细胞分泌胃蛋白酶原。小肠上部（C错）的I细胞分泌的是胆囊收缩素（CCK），K细胞分泌的是抑胃肽，S细胞分泌的是促胰液素。","","N"],["2001-N94",5,"第7节 吸收","铁的吸收",2001,94,"B","","吸收铁的主要部位是",[["A","胃底部"],["B","胃窦部"],["C","小肠上部"],["D","回肠"],["E","结肠"]],"C","铁主要在小肠上部（十二指肠和空肠上段）被吸收（C对）。回肠可吸收胆盐以及维生素B₁₂（D错）。结肠可吸收的主要是水和盐类（E错）。","","N"],["2001-N95",9,"第4节 神经系统对内脏活动、本能行为和情绪的调节","本能行为",2001,95,"B","","与摄水有关的中枢位于",[["A","丘脑的感觉接替核"],["B","丘脑的髓板内核群"],["C","下丘脑外侧区"],["D","基底神经节"],["E","下丘脑视交叉上核神经元"]],"C","下丘脑内控制摄水的区域与摄食中枢极为靠近，均位于下丘脑外侧区（C对）（十版生理学P324-P325）。破坏下丘脑外侧区后，动物除拒食外，饮水也明显减少；刺激下丘脑外侧区某些部位，则可引致动物饮水增多。","","N"],["2001-N96",9,"第2节 神经系统的感觉分析功能","丘脑的核团",2001,96,"B","","与非特异投射系统有关的结构是",[["A","丘脑的感觉接替核"],["B","丘脑的髓板内核群"],["C","下丘脑外侧区"],["D","基底神经节"],["E","下丘脑视交叉上核神经元"]],"B","丘脑是除嗅觉外的各种感觉传入通路的重要中继站，丘脑的核团或细胞群可以分为三类，分别为特异感觉接替核、联络核以及非特异投射核。非特异投射核主要是髓板内核群，包括中央中核、束旁核、中央外侧核等，这些细胞通过多突触换元后弥散地投射到整个大脑皮层，具有维持和改变大脑皮层兴奋状态的作用（B对）。","","N"],["2001-N117",10,"第5节 肾上腺内分泌","反馈调节",2001,117,"C","","腺垂体分泌ACTH的细胞",[["A","受靶腺激素反馈调节"],["B","受下丘脑控制"],["C","二者都是"],["D","二者都不是"]],"C","ACTH即促肾上腺皮质激素（adreno-cortico-tropic-hormone），由腺垂体ACTH细胞所分泌（十版生理学P370），ACTH细胞同时受下丘脑控制和靶腺激素反馈调节（AB对）：下丘脑室旁核分泌促肾上腺皮质激素释放激素（CRH）与血管升压素（VP），通过垂体门脉系统到达腺垂体，分别与ACTH细胞CRH受体-1和V₃R结合，促进腺垂体分泌ACTH，继而促进糖皮质激素（GC）的分泌。当血中GC浓度升高以后，又可反馈抑制腺垂体ACTH细胞和下丘脑CRH神经元的活动，使ACTH、CRH的合成和分泌减少。本题AB均对，正确答案为C。","","N"],["2001-N118",10,"第2节 下丘脑-垂体及松果体内分泌","缩宫素",2001,118,"C","","神经垂体分泌催产素的细胞",[["A","受靶腺激素反馈调节"],["B","受下丘脑控制"],["C","二者都是"],["D","二者都不是"]],"B","催产素又称缩宫素，由下丘脑视上核和室旁核等部位的神经细胞合成，经下丘脑-垂体束运输至神经垂体储存。机体受到适宜刺激时，下丘脑视上核和室旁核神经元兴奋（B对），神经冲动传至神经垂体，引起Ca²⁺内流，储存于神经垂体内的催产素以囊泡的形式释放入血。","","N"],["2001-N119",3,"第3节 血管生理","影响动脉血压的因素",2001,119,"C","","全身小动脉阻力增高时",[["A","左心室等容收缩期延长"],["B","动脉舒张压升高"],["C","二者都有"],["D","二者都无"]],"C","全身小动脉阻力增高时，外周阻力增大，心舒期内血液外流的速度减慢，存留在主动脉内的血量增多，动脉舒张压升高（B对），由于舒张期末主动脉内存留的血量增多，致使收缩期动脉内的血量增多，收缩压也相应升高。血压增高时，等容收缩期室内压的峰值增高，等容收缩期将延长（A对）。本题AB均正确，正确答案为C。","","N"],["2001-N120",3,"第3节 血管生理","影响动脉血压的因素",2001,120,"C","","心动周期缩短时",[["A","左心室等容收缩期延长"],["B","动脉舒张压升高"],["C","二者都有"],["D","二者都无"]],"B","心动周期缩短（心率加快）时，收缩期（A错）和舒张期都相应缩短，舒张期缩短更明显，心舒期从大动脉流向外周的血量减少，存留在主动脉内的血量增多，致使舒张压升高（B对）。","","N"],["2001-N121",9,"第1节 神经系统功能活动的基本原理","突触后抑制",2001,121,"C","","超极化抑制是指",[["A","突触前抑制"],["B","突触后抑制"],["C","二者都是"],["D","二者都不是"]],"B","突触抑制分为突触前抑制和突触后抑制两种，突触前抑制是通过使突触前膜发生去极化（A错）而降低突触前膜动作电位幅度，最终使突触后膜的EPSP减小，从而使突触后神经元发生抑制；突触后抑制是由抑制性中间神经元释放抑制性递质，使突触后神经元发生超极化（B对），产生IPSP，从而使突触后神经元发生抑制。","","N"],["2001-N122",9,"第1节 神经系统功能活动的基本原理","突触后抑制",2001,122,"C","","传入侧支性抑制是指",[["A","突触前抑制"],["B","突触后抑制"],["C","二者都是"],["D","二者都不是"]],"B","哺乳动物的突触后抑制都是由抑制性中间神经元释放抑制性递质，使突触后神经元产生IPSP，从而使突触后神经元发生抑制的。突触后抑制（B对）有传入侧支性抑制和回返性抑制两种形式：传入冲动进入中枢后，一方面通过突触联系兴奋某一中枢神经元，另一方面通过侧支兴奋一个抑制性中间神经元，再通过后者的活动抑制另一个中枢神经元，这种抑制称为传入侧支性抑制；中枢神经元兴奋时，传出冲动沿轴突外传，同时又经轴突侧支兴奋一个抑制性中间神经元，后者释放抑制性递质，反过来抑制原先发生兴奋的神经元及同一中枢的其他神经元，这种抑制称为回返性抑制。","","N"],["2001-N139",9,"第1节 神经系统功能活动的基本原理","神经纤维的分类",2001,139,"X","","C类神经纤维包括",[["A","自主神经节后纤维"],["B","自主神经节前纤维"],["C","后根中的痛觉传入纤维"],["D","皮肤触压觉传入纤维"]],"AC","根据神经纤维兴奋传导速度的差异，将哺乳动物的周围神经纤维分为A、B、C三类。其中A类神经纤维是直径最大的有髓纤维，传导速度最快；B类神经纤维也是有髓神经纤维，但直径较A类神经纤维小，传导速度较A类神经纤维慢；而C类神经纤维是无髓鞘神经纤维，直径最小，传导速度最慢。C类神经纤维包括：①后根中的痛觉，C类神经传导速度慢，负责产生慢痛，即内脏痛；②温度觉（C对），C类传入纤维上有热感受器和冷感受器，所以可以传导冷热觉；③交感节后纤维（交感神经属于自主神经）（A对）；④触压觉，最新十版教材提出C类神经纤维具有传导触压觉的功能，但未明确说明具体类型，而关于选项D“皮肤触压觉传入纤维”，皮肤触压觉的传导是需要快速传递到中枢，并且精确定位然后做出反应的特点，而C类神经纤维传导速度最慢，不具有上述性质，所以皮肤触压觉的传导应该是A类神经纤维（D错）。自主神经节前纤维是B类神经纤维（B错）。","","N"],["2001-N140",2,"第3节 生理性止血","血液凝固",2001,140,"X","","正常人的血液在血管内不发生凝固的原因有",[["A","血液流动快"],["B","血管内膜光滑完整"],["C","纤维蛋白溶解系统的作用"],["D","有抗凝血物质存在"]],"ABCD","正常人在日常活动中常发生轻微的血管损伤，体内也常有低水平的凝血系统的激活，但循环血液并不凝固。即使当组织损伤而发生生理性止血时，止血栓也只局限于损伤部位，并不延及周围未损伤部位。这表明体内的生理性凝血过程在时间和空间上都受到严格的控制，并且是多因素综合作用的结果：正常机体血液流动快，进入循环的活化的凝血因子不容易在局部聚集，血流稀释作用强，不利于血液凝固的发生（A对）。血管内膜光滑完整，可防止凝血因子、血小板与内皮细胞下的成分接触，从而避免凝血系统的激活和血小板的活化（B对）。纤维蛋白溶解系统（纤溶系统）可以将纤维蛋白和纤维蛋白原分解为可溶性小肽而发生抗凝作用（C对）。人体内存在大量的抗凝物质，包括丝氨酸蛋白酶抑制物、蛋白质C系统和组织因子途径抑制物等（D对）。","","N"],["2001-N141",7,"第5节 尿生成的调节","概述",2001,141,"X","","关于ADH的正确叙述有",[["A","经垂体门脉由下丘脑运至神经垂体"],["B","可增加肾脏远曲小管及集合管对水的通透性"],["C","血浆渗透压下降是刺激它分泌的主要因素"],["D","血容量减少可使它分泌增多"]],"BD","ADH即抗利尿激素，又称血管升压素，由下丘脑视上核和室旁核分泌，经下丘脑-垂体束的轴突（而不是经垂体门脉，经垂体门脉运输的激素是下丘脑调节肽）运输到神经垂体储存（A错）。ADH可作用于肾集合管上皮细胞（十版生理学P231）（八版P258为肾远端小管末段和集合管上皮细胞）的V₂受体，激活后通过兴奋性G蛋白激活腺苷酸环化酶，使细胞内cAMP增加，cAMP再激活蛋白激酶A，使上皮细胞内含水孔蛋白AQP-2的小泡镶嵌在上皮细胞的管腔膜上，形成水通道，从而增加管腔膜对水的通透性（B对）。ADH的释放主要受血浆渗透压和血容量的调节和影响：体液渗透压下降时，下丘脑渗透压感受器刺激减少，抗利尿激素分泌也减少（C错）；血容量减少时，静脉回心血量减少，对心肺感受器的刺激减弱，经迷走神经传入下丘脑的冲动减少，对ADH释放的抑制作用减弱或取消，故ADH分泌增多（D对）。本题的参考答案为BD，但按照九、十版教材的观点，B选项并不正确：八版教材P258认为ADH可作用于肾远端小管后段（远曲小管）和集合管上皮细胞的V₂受体，十版生理学P231只提及集合管上皮细胞，并且P228明确指出远曲小管对水不通透。","","N"],["2001-N142",9,"第1节 神经系统功能活动的基本原理","影响递质释放的因素",2001,142,"X","","影响突触前膜递质释放量的因素有",[["A","动作电位的传导速度"],["B","锋电位的幅度"],["C","进入突触前膜的Ca²⁺的数量"],["D","递质小泡的大小"]],"BC","突触前膜递质释放由Ca²⁺触发，递质的释放量与进入突触前膜的Ca²⁺量呈正相关（C对）。锋电位（动作电位）的幅度增加，则进入突触前膜的Ca²⁺数量增加，由此引起递质的释放增加（B对）。递质的释放量与动作电位的传导速度无明显关系（A错）。递质小泡的大小与递质种类有关而与递质的释放量无关（D错）：小而清亮透明的囊泡内含乙酰胆碱或氨基酸类递质；小而具有致密中心的囊泡内含儿茶酚胺类递质；大而具有致密中心的囊泡内含神经肽类递质。","","N"],["2002-N1",0,"第5节 机体生理功能的调节","神经调节",2002,1,"A","","破坏反射弧中的任何一个环节，下列哪一种调节将不能进行",[["A","神经调节"],["B","体液调节"],["C","自身调节"],["D","旁分泌调节"],["E","自分泌调节"]],"A","神经调节是通过反射而影响生理功能的一种调节方式，而反射的结构基础是反射弧，所以破坏反射弧，神经调节将不能进行（A对）。","","N"],["2002-N2",1,"第3节 细胞的电活动","兴奋性",2002,2,"A","","可兴奋细胞兴奋的共同标志是",[["A","反射活动"],["B","肌肉收缩"],["C","腺体分泌"],["D","神经冲动"],["E","动作电位"]],"E","生理学中常将神经细胞、肌细胞和腺细胞这三类能够产生动作电位（E对）的细胞称为可兴奋细胞，这些细胞由于具有较多的电压门控Na⁺通道或电压门控Ca²⁺通道，受刺激后首先发生的共同反应，就是基于这些离子通道激活而产生的动作电位，而后才表现出不同的功能活动，如肌细胞通过兴奋-收缩耦联发生收缩、腺细胞通过兴奋-分泌耦联引起分泌、神经细胞则以动作电位在神经纤维上的传导即神经冲动作为活动特征。","","N"],["2002-N3",1,"第3节 细胞的电活动","细胞兴奋后兴奋性的变化",2002,3,"A","","神经纤维上前后两次兴奋，后一次兴奋最早可出现于前一次兴奋后的",[["A","绝对不应期"],["B","相对不应期"],["C","超常期"],["D","低常期"],["E","低常期结束后"]],"B","神经细胞兴奋后兴奋性的变化先后依次为：绝对不应期、相对不应期、超常期和低常期。这种兴奋性的周期性变化与离子通道的功能状态有关，以电压门控的钠离子通道为例，钠离子通道存在三种功能状态，分别为静息态、激活态和失活态，静息态是钠离子通道可以随时接受去极化刺激而开放的状态，激活态是钠离子通道接受去极化刺激之后开放的状态，失活态是钠离子通道对去极化刺激不再反应的状态。钠离子通道进入失活态后，将持续一段时间，然后逐渐恢复到静息态，在此期间，细胞的兴奋性将依次经历绝对不应期、相对不应期、超常期、低常期的过程。当细胞的大部分钠离子通道都处在失活态的时候，细胞的兴奋性为零，这段时间称为绝对不应期；随着时间的推移，部分钠离子通道恢复到静息态，给予阈上刺激能够发生动作电位，这段时间称为相对不应期，相对不应期是最早能够发生兴奋的时期（B对）。","","N"],["2002-N4",2,"第2节 血细胞生理","红细胞的生理特征",2002,4,"A","","红细胞沉降率加速主要是由于",[["A","血细胞比容增大"],["B","血浆卵磷脂含量增多"],["C","血浆白蛋白含量增多"],["D","血浆球蛋白含量增多"],["E","血浆纤维蛋白原减少"]],"D","血流中的红细胞，因胞膜表面的唾液酸所具有的负电荷等因素而互相排斥，使细胞保持一定间距，故彼此分散悬浮而下沉缓慢。正常情况下，血浆蛋白所带的正、负电荷呈平衡状态（白蛋白带负电荷，球蛋白与纤维蛋白原带正电荷），如果血浆中纤维蛋白原或球蛋白含量增加（D对）或白蛋白含量减少，改变了电荷的平衡，致使红细胞表面的负电荷减少，容易使红细胞叠连而血沉加快，反之则血沉减慢。血浆中脂类物质对红细胞聚集也有影响，胆固醇和甘油三酯有促进的作用，可使血沉加快；而卵磷脂则有抑制作用使血沉减慢。","","N"],["2002-N5",3,"第2节 心脏的电生理学及生理特性","心肌细胞兴奋性的周期性变化",2002,5,"A","","心肌细胞不会发生完全强直收缩的原因是",[["A","肌浆网Ca²⁺贮存少"],["B","受自动节律性控制"],["C","有效不应期特别长"],["D","“全或无”式收缩"],["E","传导的房室延搁"]],"C","当肌肉接受一连串彼此间隔时间很短的连续兴奋冲动时，由于各个刺激间的时间间隔很短，后一个刺激都落在由前一刺激所引起的收缩尚未结束之前，就又引起下一次收缩，称强直收缩。强直收缩包括完全强直收缩和不完全强直收缩两种类型，当刺激频率比较高时，后一刺激引起的收缩落在前一收缩的收缩期内，肌肉将始终保持收缩状态，这种现象称为完全强直收缩。当刺激频率比较低时，后一刺激引起的收缩落在前一收缩的舒张期内，肌肉在收缩后有过短暂的舒张，但还未恢复到正常的舒张状况又进入下一次收缩，这种现象称为不完全强直收缩。骨骼肌细胞既可以产生完全强直收缩，也可以产生不完全强直收缩，心肌细胞由于有效不应期特别长（C对），一直延续到心肌收缩活动的舒张早期，因此不会发生完全强直收缩。","","N"],["2002-N6",3,"第3节 血管生理","影响动脉血压的因素",2002,6,"A","","动脉舒张压的高低主要反映",[["A","每搏输出量的多少"],["B","外周阻力的大小"],["C","大动脉弹性的好坏"],["D","心脏泵血功能的好坏"],["E","血管充盈的程度"]],"B","外周阻力的改变主要影响舒张压，舒张压的高低主要反映外周阻力的大小（B对）。每搏输出量的改变主要影响收缩压，收缩压的高低主要反映每搏输出量的多少。","","N"],["2002-N7",3,"第4节 心血管活动的调节","颈动脉窦和主动脉弓压力感受性反射",2002,7,"A","","下列关于压力感受性反射的叙述，哪一项是错误的",[["A","感受器的适宜刺激是动脉壁的机械牵张"],["B","传入神经是窦神经和主动脉神经"],["C","动脉血压升高时可通过反射使血压下降"],["D","对正常血压的维持具有重要的意义"],["E","切断传入神经后动脉血压明显升高"]],"E","压力感受性反射也称减压反射 ，是通过对颈动脉窦和主动脉弓压力感受器的刺激而引起的。颈动脉窦和主动脉弓压力感受器的适宜刺激是血管壁的被动机械扩张，而非血压本身（A对）。动脉血压升高时，压力感受器传入冲动增多，通过有关的心血管中枢整合作用，使心迷走紧张加强，心交感紧张和交感缩血管紧张降低，其效应为心率减慢，心输出量减少，外周血管阻力降低，故动脉血压回降（C对）。压力感受性反射在心输出量、外周血管阻力、血量等发生突然改变的情况下，对动脉血压进行快速调节的过程中起重要的作用（D对）。颈动脉窦和主动脉弓压力感受器的传入神经分别为窦神经和主动脉神经（B对），传入神经被切断后，动脉血压会变得不稳定（血压升高时不能降压，血压下降时不能升压），但全天的血压平均值并不升高（E错，为本题正确答案）。","","N"],["2002-N8",4,"第1节 肺通气","肺泡通气量",2002,8,"A","","如果潮气量减少一半，而呼吸频率加快一倍，则",[["A","肺通气量增加"],["B","肺通气量减少"],["C","肺泡通气量增加"],["D","肺泡通气量减少"],["E","肺泡通气量不变"]],"D","肺泡通气量是指每分钟吸入肺泡的新鲜空气量，它等于潮气量和无效腔气量之差与呼吸频率的乘积。如果潮气量为500ml，无效腔为150ml，呼吸频率为12次/分，则肺泡通气量为4.2L/min；如果潮气量为250ml（减少一半），无效腔为150ml（不会随潮气量改变而改变），呼吸频率为24次/分（加快一倍），则肺泡通气量为2.4L/min。因此潮气量减少一半，呼吸频率加快一倍的情况下，肺泡通气量显著减少（D对），即肺泡内气体的更新率显著降低，故浅而快的呼吸对肺换气而言是不利的。","","N"],["2002-N9",4,"第3节 气体在血液中的运输","影响氧解离曲线的因素",2002,9,"A","","下列哪一种情况下氧解离曲线发生右移",[["A","肺通气阻力减小"],["B","代谢性碱中毒"],["C","2，3-二磷酸甘油酸增多"],["D","血温降低"],["E","血CO₂分压下降"]],"C","氧解离曲线的位置发生偏移意味着Hb对O₂的亲和力发生了变化。通常用P₅₀来表示Hb对O₂的亲和力。P₅₀是使Hb饱和度达50%时的PO₂，P₅₀增大时氧解离曲线右移，表示Hb对O₂的亲和力降低，需要更高的PO₂才能使Hb氧饱和度达到50%；P₅₀降低时氧解离曲线左移，则表示Hb对O₂的亲和力增加，达50%Hb氧饱和度所需要的PO₂降低。使氧解离曲线右移的常见因素包括PCO₂↑、pH↓、温度↑、2，3-DPG↑（C对）等，使氧解离曲线左移的常见因素包括PCO₂↓（E错）、pH↑（B错）、温度↓（D错）、2，3-DPG↓等。肺通气阻力减小时，肺通气量增加，呼出的CO₂增多，血液的PCO₂↓，氧解离曲线左移（A错）。","","N"],["2002-N10",5,"第1节 消化生理概述","电生理特性",2002,10,"A","","控制消化道平滑肌收缩节律的基础是",[["A","慢波"],["B","动作电位"],["C","壁内神经丛活动"],["D","迷走神经兴奋"],["E","交感神经兴奋"]],"A","消化道平滑肌在静息膜电位基础上，可自发地周期性地产生去极化和复极化，形成缓慢的节律性电位波动，由于其频率较慢，因而称为慢波。平滑肌细胞存在机械阈和电阈两个临界膜电位值（十版生理学P166），当慢波去极化达到或超过机械阈（未发生动作电位，收缩轻微）或电阈（发生动作电位，收缩强烈）时，消化道平滑肌细胞收缩。所以，慢波是平滑肌收缩的起步电位，控制着消化道平滑肌收缩节律（A对），决定了消化道运动的方向、节律和速度。","","N"],["2002-N11",5,"第4节 小肠内消化","胰液的性质、成分和作用",2002,11,"A","","能使胰蛋白酶原转变为胰蛋白酶最重要的物质是",[["A","胃酸"],["B","胰蛋白酶"],["C","糜蛋白酶"],["D","肠致活酶（肠激酶）"],["E","组织液"]],"D","胰蛋白酶原本身没有活性，在小肠中通过肠致活酶（肠激酶）的作用（D对），转变为有活性的胰蛋白酶。胰蛋白酶本身（正反馈调节）、胃酸、组织液也可激活胰蛋白酶原为胰蛋白酶，但相对肠激酶来说，作用比较次要（ABE错）。糜蛋白酶对胰蛋白酶原无激活作用（但胰蛋白酶可激活糜蛋白酶原）（C错）。","","N"],["2002-N12",6,"第2节 体温及其调节","辐射散热",2002,12,"A","","在环境温度低于30℃，机体处于安静状态下的主要散热方式是",[["A","辐射散热"],["B","传导散热"],["C","对流散热"],["D","不感蒸发"],["E","可感蒸发"]],"A","当环境温度低于人体表面温度，人体散热方式主要为辐射、传导和对流，其中尤其以辐射散热为主（A对）。蒸发包括可感蒸发（出汗）和不感蒸发，为环境温度高于表层温度时的主要散热方式（DE错）。人体因传导散热而散失的热量并不多，而对流散热是传导散热的一种（BC错）。","","N"],["2002-N13",7,"第7节 尿的排放","排尿异常",2002,13,"A","","胸段脊髓受损在脊休克过去之后，排尿功能障碍的表现为",[["A","尿失禁"],["B","尿频"],["C","尿急"],["D","尿多"],["E","排尿困难"]],"A","脊休克指脊髓突然横断失去与高位中枢的联系，断面以下脊髓暂时丧失反射活动能力进入无反应状态，但在脊休克发生后，一些以脊髓为基本中枢的反射可逐渐在不同程度上恢复（八版生理学P334）。排尿反射的初级中枢在骶段脊髓，胸段脊髓受损时，在脊髓休克期间，由于骶段脊髓排尿中枢处于休克状态，排尿反射消失，排尿困难，在脊髓休克恢复以后，由于反射弧完好，排尿反射可逐渐恢复，但得不到高位中枢大脑皮层的控制，故出现尿失禁（A对）。","","N"],["2002-N14",8,"第3节 视觉","晶状体变凸",2002,14,"A","","眼球前后径正常的人，眼的近点愈近，说明其",[["A","角膜愈呈球形"],["B","晶状体弹性愈好"],["C","缩瞳能力愈强"],["D","双眼球会聚能力愈强"],["E","对光反应能力愈强"]],"B","在注视近物时，物体上各点发出的光从四面八方进入人眼后呈不同程度的辐射状，需要调节晶状体变凸的程度才能使物像在视网膜上形成准确清晰的物像，物体离眼越近，进入人眼的光线就越发散，就越需要调节（使晶状体变凸），因此可以用近点来表示晶状体的弹性，近点越近，说明晶状体变凸的能力越大，即晶状体的弹性愈好（B对）。","","N"],["2002-N15",9,"第5节 脑电活动及睡眠与觉醒","觉醒与睡眠的产生机制",2002,15,"A","","在中脑头端切断网状结构，则动物（如猫）处于下列何种状态",[["A","脊休克"],["B","去大脑僵直"],["C","觉醒"],["D","昏睡"],["E","运动共济失调"]],"D","脑干网状结构是指在脑干内除界限清楚、功能明确的神经细胞核团和神经纤维束外的神经细胞和神经纤维交织成网状的结构，分布在从脊髓到丘脑底部各个部位。它接受躯体和内脏的各种传入冲动，由丘脑的非特异性投射系统到达大脑皮质。网状结构与觉醒的产生有关，刺激网状结构可以将猫从睡眠中唤醒（C错），而破坏网状结构动物便进入持久的昏睡状态，脑电图呈同步化慢波（D对）。脊休克（十版生理学P309）是指人和动物的脊髓在与高位中枢离断后，以脊髓为中枢的反射活动能力暂时丧失而进入无反应状态的现象（A错）。去大脑僵直（十版生理学P312）是在中脑上、下丘脑之间切断脑干引起的伸肌紧张增强的表现（B错）。运动共济失调（十版生理学P317）为脊髓小脑受损的表现（E错）。","","N"],["2002-N16",9,"第3节 神经系统对躯体运动的调控","帕金森病",2002,16,"A","","帕金森病的产生是由于下列哪个递质系统受损所致",[["A","黑质-纹状体多巴胺能系统"],["B","脑干网状结构胆碱能系统"],["C","纹状体-黑质γ-氨基丁酸能系统"],["D","中缝核5-羟色胺能系统"],["E","蓝斑上部去甲肾上腺素能系统"]],"A","黑质内存在大量多巴胺能神经元，纹状体内存在大量胆碱能神经元，黑质多巴胺递质系统与纹状体乙酰胆碱递质系统之间的功能失衡是帕金森病发病的原因：黑质多巴胺递质系统的作用在于抑制纹状体乙酰胆碱递质系统，当黑质多巴胺神经元受损后（A对），对纹状体内胆碱能神经元的抑制作用减弱，导致乙酰胆碱递质系统功能亢进，进而影响新纹状体传出神经元的活动而引起一系列症状，即为帕金森病。","","N"],["2002-N17",10,"第3节 甲状腺内分泌","调节新陈代谢",2002,17,"A","","甲状腺功能亢进患者血中，下列哪一种物质的浓度降低",[["A","氨基酸"],["B","葡萄糖"],["C","胆固醇"],["D","血钙"],["E","尿酸"]],"C","甲状腺激素（TH）对糖、脂肪、胆固醇、蛋白质的合成和分解代谢均有调节作用，十分复杂。就整体而言，在生理浓度范围内的甲状腺激素对糖、脂肪、蛋白质的合成和分解代谢均有调节作用，而分泌过量时则促进分解代谢的作用更明显一些。甲亢患者甲状腺激素过量分泌，甲状腺激素可使骨骼肌为主的外周组织蛋白分解加速，血中氨基酸浓度升高（A错），引起尿酸含量增加（E错），尿氮排泄增加，骨基质蛋白质分解，Ca²⁺析出，导致血钙升高（D错）；甲状腺激素可加速肠黏膜吸收葡萄糖、促进肝糖异生，同时又能增强肾上腺素、胰高血糖素、皮质醇和生长激素的生糖效应，升高血糖水平，但甲状腺激素同时能加强外周组织对糖的利用，也能降低血糖，但总体而言，甲状腺激素升血糖的作用强于降血糖作用，甲亢患者往往表现为糖耐量减低或轻型糖尿病（B错）；甲状腺激素可使体内胆固醇合成增加，但胆固醇分解排泄亦相应增加，总体而言分解作用大于合成作用，因而甲亢患者血清胆固醇水平会有所降低（C对）。","","N"],["2002-N18",11,"第2节 女性生殖功能及其调节","卵巢的生卵作用",2002,18,"A","","月经周期中控制排卵发生的关键因素是",[["A","排卵前雌激素高峰"],["B","孕激素高峰"],["C","卵泡刺激素高峰"],["D","黄体生成素高峰"],["E","促性腺激素释放激素高峰"]],"D","LH峰是月经周期中控制排卵发生的关键因素（D对）：在LH峰出现之前，初级卵母细胞由于周围的颗粒细胞分泌一种卵母细胞成熟抑制因子（OMI），使卵母细胞的成熟分裂停止于初级卵母细胞阶段。当LH峰出现时，高浓度的LH可抵消OMI的抑制作用，使初级卵母细胞恢复分裂，形成次级卵母细胞和第一极体。随即次级卵母细胞开始第二次成熟分裂，最后，次级卵泡逐渐发育为成熟卵泡并突出于卵巢表面，形成透明的卵泡小斑（排卵孔）。LH峰的出现还能促进卵泡细胞分泌孕激素和前列腺素，孕激素可激活纤溶酶、胶原酶、蛋白水解酶及透明质酸酶等，使卵泡壁溶解破裂，前列腺素可使卵泡壁肌上皮细胞收缩，这些作用都有助于卵细胞从排卵孔排出。","","N"],["2002-N93",1,"第3节 细胞的电活动","静息时细胞膜对离子的相对通透性",2002,93,"B","","神经细胞膜在静息时通透性最大的离子是",[["A","Na⁺"],["B","K⁺"],["C","Ca²⁺"],["D","Cl⁻"],["E","HCO₃⁻"]],"B","神经细胞膜在静息时，K⁺通透性最大（B对），K⁺受浓度差驱动，由细胞内向细胞外流动，形成静息电位。","","N"],["2002-N94",1,"第3节 细胞的电活动","动作电位期间膜离子通透性的变化",2002,94,"B","","神经细胞膜在受刺激兴奋时通透性最大的离子是",[["A","Na⁺"],["B","K⁺"],["C","Ca²⁺"],["D","Cl⁻"],["E","HCO₃⁻"]],"A","神经细胞在受刺激兴奋时，钠离子通道开放，发生去极化，去极化与钠离子电导（钠离子通透性）之间形成正反馈，Na⁺通道进入激活态（十版生理学P35），通透性增加500～5000倍（A对），Na⁺内流形成动作电位的升支。","","N"],["2002-N95",3,"第1节 心脏的泵血功能","心输出量和心指数",2002,95,"B","","比较不同个体之间的心泵功能，宜选用的评定指标是",[["A","每搏输出量"],["B","每分输出量"],["C","射血分数"],["D","心指数"],["E","心脏做功量"]],"D","一侧心室每分钟射出的血液量，称为每分输出量，简称心输出量。心输出量与机体的新陈代谢水平相适应，可因性别、年龄及其他生理情况的不同而不同，对不同身材的个体测量心功能时，若用心输出量作为指标进行比较是不全面的。因为身材矮小和身材高大的机体具有不同的耗氧量和能量代谢水平，心输出量也不同。研究表明，人在安静时的心输出量和基础代谢率一样，并不与体重成正比，而是与体表面积成正比。以单位体表面积计算的心输出量称为心指数，在安静和空腹情况下测定的心指数称为静息心指数，可作为比较不同个体心功能的评定指标（D对）。","","N"],["2002-N96",3,"第1节 心脏的泵血功能","每搏输出量和射血分数",2002,96,"B","","心室扩大早期，泵血功能减退时，宜选用的评定指标是",[["A","每搏输出量"],["B","每分输出量"],["C","射血分数"],["D","心指数"],["E","心脏做功量"]],"C","一侧心室在一次心搏中射出的血液量，称为每搏输出量，简称搏出量，搏出量占心室舒张末期容积的百分比，称为射血分数。正常情况下，由于异长调节，搏出量与心室舒张末期容积是相适应的，即当心室舒张末期容积增加时，搏出量也相应增加，而射血分数基本保持不变。在心室功能减退、心室异常扩大的病人，其搏出量可能与正常人无明显差异，但与已经增大的舒张末期容积不相适应，实际上射血分数已明显下降。因此，与搏出量相比，射血分数能更准确地反映心脏泵血功能，对早期发现心脏泵血功能异常具有重要意义（C对）。","","N"],["2002-N117",3,"第2节 心脏的电生理学及生理特性","心室肌细胞动作电位",2002,117,"C","","心室肌细胞动作电位平台期离子流有",[["A","K⁺外流"],["B","Ca²⁺内流"],["C","二者均有"],["D","二者均无"]],"C","平台期即动作电位的2期，因复极化速度及其缓慢，膜电位几乎停滞于同一水平形成平台而得名。平台期的存在是心室肌细胞动作电位时程较长的主要原因，也是区别于神经、骨骼肌动作电位的主要特征。平台期之所以复极化速度缓慢，是因为复极化过程既有外向电流，又有内向电流，外向电流为Ik通道介导的延迟整流钾电流（A对），内向电流为ICa-L通道介导的L型钙电流（B对）。本题AB均对，正确答案为C。","","N"],["2002-N118",3,"第2节 心脏的电生理学及生理特性","窦房结细胞动作电位",2002,118,"C","","窦房结细胞动作电位4期离子流有",[["A","K⁺外流"],["B","Ca²⁺内流"],["C","二者均有"],["D","二者均无"]],"C","窦房结P细胞的4期为自动去极期，4期自动去极化的离子基础包括：窦房结P细胞3期复极的Iₖ通道逐渐关闭，K⁺外流减少（A对）、If通道介导的Na⁺内流增加、ICa-T通道介导的Ca²⁺内流增加等（B对）。本题AB均对，正确答案为C。","","N"],["2002-N119",4,"第3节 气体在血液中的运输","氧的运输",2002,119,"C","","O₂在血液中的运输形式有",[["A","氨基甲酰血红蛋白"],["B","碳酸氢根"],["C","二者均有"],["D","二者均无"]],"D","氧气在血液中运输形式包括占1.5%的物理溶解和占98.5%的化学结合两种，化学结合为O₂与红细胞内血红蛋白结合的方式：血红蛋白由珠蛋白和血红素组成，血红素基团中心的Fe²⁺可与O₂结合，形成氧合血红蛋白（HbO₂）（D对）。","","N"],["2002-N120",4,"第3节 气体在血液中的运输","CO₂的运输形式",2002,120,"C","","CO₂在血液中的运输形式有",[["A","氨基甲酰血红蛋白"],["B","碳酸氢根"],["C","二者均有"],["D","二者均无"]],"C","碳酸氢盐（B对）和氨基甲酰血红蛋白（A对）均是CO₂的化学结合形式，前者约占CO₂总运输量的88％，而后者约占7％。本题AB均对，正确答案为C。","","N"],["2002-N121",5,"第3节 胃内消化","胃的运动形式",2002,121,"C","","参与胃容受性舒张的有",[["A","迷走-迷走反射"],["B","肠-胃反射"],["C","二者均有"],["D","二者均无"]],"A","容受性舒张是指进食时食物刺激口腔、咽、食管等处的感受器反射性引起胃底和胃体舒张的过程，其传入神经和传出神经均走行于迷走神经内，故属于迷走-迷走反射（胃期胃液分泌、胃期胰液分泌及胃排空过程也存在迷走-迷走反射调节）（A对）。","","N"],["2002-N122",5,"第3节 胃内消化","胃排空及其控制",2002,122,"C","","参与胃排空调控的有",[["A","迷走-迷走反射"],["B","肠-胃反射"],["C","二者均有"],["D","二者均无"]],"C","食物由胃排入十二指肠的过程称为胃排空。胃内因素能够促进胃排空：食物对胃的扩张刺激可通过迷走-迷走反射（A对）和壁内神经丛局部反射引起胃运动的加强，促进胃排空；而十二指肠内因素则能抑制胃排空：食物对十二指肠的扩张刺激则可通过肠-胃反射（B对）抑制胃的运动，使胃排空减慢。本题AB均对，正确答案为C。","","N"],["2002-N139",1,"第3节 细胞的电活动","动作电位的概念及特点",2002,139,"X","","动作电位的“全或无”特点表现在",[["A","刺激太小时不能引发"],["B","一旦产生即达到最大"],["C","不衰减性传导"],["D","兴奋节律不变"]],"ABC","动作电位的“全或无”本身的定义是指：要使细胞产生动作电位，所给的刺激必须达到一定的强度。若刺激未达到一定强度，动作电位就不会产生（无）（A对）；当刺激达到一定的强度时，所产生的动作电位，其幅度便到达该细胞动作电位的最大值，不会随刺激强度的继续增强而增大（全）（B对）。动作电位“全或无”的特点决定了动作电位可以进行不衰减性传导（C对）。兴奋节律与动作电位的发生频率有关，与其“全或无”特点无关。本题给出的参考答案为ABC，存在一定争议。","","N"],["2002-N140",3,"第3节 血管生理","静脉血压",2002,140,"X","","引起中心静脉压升高的原因有",[["A","左心功能不全"],["B","输液过多过快"],["C","静脉回流加速"],["D","卧位转为立位"]],"BC","中心静脉压是指右心房和胸腔内大静脉血压。右心功能不全时，右心室射血能力明显减弱，心舒期血液淤积于右心房和大静脉内，中心静脉压升高；左心功能不全时，左心室射血能力明显减弱，心舒期血液淤积于左心房和肺静脉内，肺静脉压升高，因肺静脉和右心有一定的代偿能力，所以左心衰时并不会立马发生右心衰（A错）。输液过多过快或静脉回流加速可使回心血量增加，促使中心静脉压升高（BC对）。当体位由平卧位转为直立位时，身体低垂部分的静脉因跨壁压增大而扩张，可容纳更多的血液，因而回心血量减少，中心静脉压降低（D错）。","","N"],["2002-N141",7,"","",2002,141,"X","","关于近端肾小管重吸收水的描述，正确的有",[["A","伴Na⁺重吸收的等渗性重吸收"],["B","重吸收量约占滤过量的67％"],["C","在腔面膜上水通道的帮助下进行"],["D","根据水、盐平衡的需要而受到调节"]],"ABC","近端小管对水的重吸收主要是通过水通道蛋白1（AQP1）在渗透压作用下完成的（C对）。AQP1主要分布在近端小管上皮细胞顶端膜和基底侧膜，参与超滤液中60%～70%水的重吸收（B对），具有极高的水渗透通透性，是完成水的跨细胞重吸收的主要通道。因为上皮细胞主动和被动重吸收Na⁺、HCO₃⁻、Cl⁻、葡萄糖和氨基酸后，小管液渗透压降低，细胞间液渗透压升高。水在这一渗透压差的作用下经跨细胞（通过AQP1）和细胞旁两条途径进入细胞间液，然后进入管周毛细血管而被重吸收。因此，近端小管中物质的重吸收为等渗性重吸收（A对），小管液为等渗液。能够根据水、盐平衡的需要而受到调节的部位是集合管（D错）。近端小管通过水通道重吸收水为九、十版教材新增内容，八版及更早版本教材并未提及，当年给出的参考答案仅为AB，依照九、十版教材，本题的正确答案应为ABC。","","N"],["2002-N142",9,"第1节 神经系统功能活动的基本原理","乙酰胆碱及其受体",2002,142,"X","","下列各项中属于胆碱能神经纤维的有",[["A","α运动神经元传出纤维"],["B","γ运动神经元传出纤维"],["C","骨骼肌交感舒血管节后纤维"],["D","支配汗腺的交感节后纤维"]],"ABCD","以ACh为递质的神经元称为胆碱能神经元，胆碱能神经元发出的纤维称为胆碱能纤维。在外周，支配骨骼肌的运动神经纤维、大多数副交感节后纤维、少数交感节后纤维（如支配多数小汗腺的纤维和支配骨骼肌血管的舒血管纤维）都属于胆碱能纤维（C对）。α运动神经元传出纤维和γ运动神经元传出纤维是支配骨骼肌的运动神经纤维，故也属于胆碱能纤维（AB对）。引起汗腺分泌的因素不同，其出汗情形也不同，当机体接受温热性刺激时，中枢通过支配汗腺的交感胆碱能纤维使全身小汗腺分泌汗液，精神因素刺激时，中枢通过支配汗腺的交感肾上腺素能纤维引起汗液分泌，本题D选项存在争议，但当年给出的参考答案为ABCD。","","N"],["2003-N1",0,"第6节 人体内自动控制系统","负反馈控制系统",2003,1,"A","","属于负反馈调节的过程见于",[["A","排尿反射"],["B","减压反射"],["C","分娩过程"],["D","血液凝固"],["E","排便反射"]],"B","受控部分发出的反馈信息调整控制部分的活动，最终使受控部分朝着与它原来活动相反的方向改变，称为负反馈。减压反射（压力感受性反射）属于典型的负反馈调节（B对）：动脉血压升高时，压力感受器传入冲动增多，引起压力感受性反射增强，导致心迷走神经加强，心交感紧张和交感缩血管紧张减弱，表现为心率减慢，心输出量减少，外周阻力减小，动脉血压下降（十版生理学P122-P123）。血液凝固（十版生理学P67）（D错）、排尿反射（十版生理学P239）（A错）、排便反射（E错）、分娩过程（十版生理学P396）（C错）等均属于正反馈调节过程。","","N"],["2003-N2",1,"第1节 细胞膜的物质转运功能","钠-钾泵",2003,2,"A","","下列关于Na⁺-K⁺泵的描述，错误的是",[["A","仅分布于可兴奋细胞的细胞膜上"],["B","是一种镶嵌于细胞膜上的蛋白质"],["C","具有分解ATP而获能的功能"],["D","能不断将Na⁺移出细胞膜外，而把K⁺移入细胞膜内"],["E","对细胞生物电的产生具有重要意义"]],"A","可兴奋细胞（P42）是指能够产生动作电位的细胞，如神经细胞、肌细胞、部分腺细胞等，而对于钠泵来说，产生动作电位只是其功能之一，钠泵还有维持细胞内代谢所需的高K⁺环境、维持细胞内渗透压和细胞容积等重要功能，因此钠泵是哺乳动物细胞膜中普遍存在的离子泵，而不仅分布于可兴奋细胞的细胞膜上（A错，为本题正确答案）。","","N"],["2003-N3",2,"第2节 血细胞生理","红细胞的生理特征",2003,3,"A","","红细胞悬浮稳定性差会导致",[["A","溶血"],["B","红细胞凝聚"],["C","血液凝固"],["D","血沉加快"],["E","出血时间延长"]],"D","将盛有抗凝血的血沉管垂直静置，尽管红细胞的比重大于血浆，但正常时红细胞下沉缓慢，表明红细胞能相对稳定地悬浮于血浆中，红细胞的这一特性称为悬浮稳定性。通常以红细胞在第一小时末下沉的距离来表示红细胞的沉降速度，称为红细胞沉降率，简称血沉。血沉越快，表示红细胞的悬浮稳定性越差（D对）。","","N"],["2003-N4",3,"第1节 心脏的泵血功能","第二心音",2003,4,"A","","第二心音的产生主要是由于",[["A","房室瓣开放"],["B","房室瓣关闭"],["C","动脉瓣开放"],["D","动脉瓣关闭"],["E","心室壁振动"]],"D","第二心音发生在心室舒张期，标志着心室舒张期的开始，其产生主要与主动脉瓣和肺动脉瓣关闭（D对），血流冲击大动脉根部引起血液、管壁及心室壁的振动有关。第二心音在胸骨旁第2肋间（即主动脉瓣和肺动脉瓣听诊区）听诊时最清楚，其特点是音调较高，持续时间较短。","","N"],["2003-N5",3,"第3节 血管生理","微循环的血流动力学",2003,5,"A","","决定微循环营养通路周期性开闭的主要因素是",[["A","血管升压素"],["B","肾上腺素"],["C","去甲肾上腺素"],["D","血管紧张素"],["E","局部代谢产物"]],"E","测量一个器官的血流量时，常可见到在一定时间内其血流量是稳定的。但如果在显微镜下观察微循环营养通路中单个血细胞的移动速度，则可看到在同一时间内不同微血管中的流速有很大差别，可从完全不流动到每秒几毫米，而且同一血管在不同时间内流速也有较大变化。其原因是后微动脉和毛细血管前括约肌在局部代谢产物（E对）的作用下不断发生每分钟5～10次的周期性开闭活动，即血管舒缩活动。","","N"],["2003-N6",4,"第1节 肺通气","弹性阻力和顺应性",2003,6,"A","","下列关于肺表面活性物质的描述，错误的是",[["A","能降低肺的顺应性"],["B","能降低肺泡表面张力"],["C","能减少肺的弹性阻力"],["D","由肺泡Ⅱ型细胞分泌"],["E","脂质成分为二棕榈酰卵磷脂"]],"A","由于肺表面活性物质可以降低肺泡表面张力，肺泡表面张力又是肺弹性阻力的主要来源，故肺表面活性物质可以减少肺的弹性阻力（C对）。而弹性阻力与顺应性在数值上互为倒数，所以肺表面活性物质可以增加肺的顺应性（A错，为本题正确答案）。","","N"],["2003-N7",4,"第2节 肺换气和组织换气","通气_血流比值",2003,7,"A","","下列关于通气/血流比值的描述，正确的是",[["A","为肺通气量和心输出量的比值"],["B","比值增大或减小都降低肺换气效率"],["C","人体直立时肺尖部比值较小"],["D","比值增大犹如发生了动-静脉短路"],["E","比值减小意味着肺泡无效腔增大"]],"B","通气／血流比值是指每分钟肺泡通气量和每分钟肺血流量的比值，而不是每分钟肺通气量和心输出量的比值（A 错）。人体平卧时，平均比值等于0.84，该比值增大意味着通气过度，肺泡无效腔增大（E错），该比值减小则意味着通气不足，血流相对过度，犹如发生了功能性动-静脉短路（D错），所以，通气／血流比值无论增大或减小都不利于肺换气（B对）。人体直立时，受重力影响，从肺底部到肺尖部，肺泡通气量和肺毛细血管血流量都逐渐减少，但血流量的减少更为显著，所以肺尖部的通气/血流比值增大（C错）。","","N"],["2003-N8",5,"第3节 胃内消化","盐酸",2003,8,"A","","分泌胃酸的细胞为",[["A","壁细胞"],["B","主细胞"],["C","颗粒细胞"],["D","黏液细胞"],["E","Cajal细胞"]],"A","主细胞分泌胃蛋白酶原（B错）。黏液细胞主要分泌黏液（D错）。Cajal细胞是位于消化道平滑肌纵行肌和环形肌之间的一种间质细胞（十版生理学P166），其功能在于产生慢波电位（E错）。颗粒细胞是一种形态学的描述，因胞内含有分泌颗粒而得名，人体内的颗粒细胞包括白细胞中的粒细胞（十版生理学P61）、肾单位球旁器中的球旁细胞（十版生理学P214）、卵巢中的卵泡颗粒细胞（十版生理学P387）、胃肠黏膜中的肠嗜铬样细胞（十版生理学P171）等，本题提及的颗粒细胞应指肠嗜铬样细胞。肠嗜铬样细胞分布于胃泌酸区内，主要功能是合成和分泌组胺（C错）。","","N"],["2003-N9",5,"第4节 小肠内消化","神经调节",2003,9,"A","","迷走神经兴奋引起胰液分泌的特点是",[["A","水分少，碳酸氢盐和酶的含量丰富"],["B","水分和碳酸氢盐的含量少，酶的含量丰富"],["C","水分多，碳酸氢盐和酶的含量均少"],["D","水分、碳酸氢盐和酶的含量均多"],["E","水分和碳酸氢盐的含量多，酶的含量少"]],"B","胰液分泌受神经调节和体液调节的双重控制：①神经调节以迷走神经为主，迷走神经兴奋时，末梢释放乙酰胆碱，作用于胰腺的腺泡细胞使其分泌大量的酶，而水和碳酸氢盐的量却很少（B对）；②体液调节由促胰液素和缩胆囊素介导，促胰液素主要作用于胰腺小导管上皮细胞，使其分泌大量的水和碳酸氢盐，而酶的含量则不高，缩胆囊素主要作用于胰腺的腺泡细胞使其分泌大量的酶，而水和碳酸氢盐的量却很少。","","N"],["2003-N10",6,"第1节 能量代谢","肌肉活动",2003,10,"A","","影响能量代谢最主要的因素是",[["A","寒冷"],["B","高温"],["C","肌肉活动"],["D","精神活动"],["E","进食"]],"C","影响能量代谢的主要因素包括肌肉活动、精神活动、食物特殊动力作用、环境温度等，其中肌肉活动的影响最为显著，机体任何轻微的运动即可提高代谢率（C对）。","","N"],["2003-N11",7,"第3节 肾小管和集合管的物质转运功能","葡萄糖和氨基酸的重吸收",2003,11,"A","","肾重吸收葡萄糖的部位是",[["A","近曲小管"],["B","髓袢细段"],["C","髓袢升支粗段"],["D","远曲小管"],["E","集合管"]],"A","肾重吸收葡萄糖的部位均在近端小管，特别是在近端小管的前半段即近曲小管（A对）被重吸收。说一下近端小管和近曲小管的关系：近端小管是与肾小囊相连，空间上离肾小体距离较近的肾小管，依其走行的曲直，又有曲部和直部之分，其中曲部即近端小管的前半段，又名近曲小管，直部为髓袢降支粗段（十版生理学P214 图8-1）。","","N"],["2003-N12",7,"第5节 尿生成的调节","血浆晶体渗透压",2003,12,"A","","大量饮清水后，尿量增多的主要原因是",[["A","肾小球滤过率增加"],["B","肾血浆流量增多"],["C","血浆胶体渗透压降低"],["D","血管升压素分泌减少"],["E","醛固酮分泌减少"]],"D","饮大量清水后，血浆晶体渗透压下降，抗利尿激素（血管升压素）分泌减少，进而造成肾小管和集合管对水的重吸收减少，尿量增多（D对）。","","N"],["2003-N13",8,"第3节 视觉","感光细胞及其特征",2003,13,"A","","下列关于视网膜上两种感光细胞的叙述，错误的是",[["A","视杆细胞分布于视网膜周边部，而视锥细胞分布于中心部"],["B","视杆细胞对光敏感度较视锥细胞低"],["C","视杆细胞不能分辨颜色，而视锥细胞能分辨颜色"],["D","视杆细胞对被视物结构的分辨能力较视锥细胞低"],["E","视杆细胞传入通路的会聚程度较视锥细胞高"]],"B","视网膜中有视杆细胞和视锥细胞两种感光细胞，它们在视网膜中的分布不同，视杆细胞主要分布于视网膜的周边部，而视锥细胞主要分布于视网膜的中央凹处（A对）。视杆细胞主要与暗视觉有关，对光的敏感度较高（B错，为本题正确答案），能在昏暗环境中感受弱光刺激，但无色觉，对被视物细节的分辨力较低；而视锥细胞主要与明视觉有关，对光的敏感性较低，只有在强光条件下才能被激活，但视物时可辨别颜色（C对），且对被视物的细节具有较高的分辨能力（D对）。感光细胞的感觉分辨能力与其在感觉传入通路中的会聚程度成反比，视杆细胞传入通路的会聚程度较视锥细胞高（E对），故其对颜色和被视物细节的分辨能力较视锥细胞低。","","N"],["2003-N14",9,"第1节 神经系统功能活动的基本原理","反射的定义和分类",2003,14,"A","","下列各项中，属于条件反射的是",[["A","咀嚼、吞咽食物引起胃液分泌"],["B","异物接触眼球引起眼睑闭合"],["C","叩击股四头肌腱引起小腿前伸"],["D","强光刺激视网膜引起瞳孔缩小"],["E","闻到食物香味引起唾液分泌"]],"E","反射是神经活动的基本方式，俄罗斯著名生理学家巴甫洛夫将人和高等动物的反射分为非条件反射和条件反射两类。前者是指生来就有、数量有限、比较固定和形式低级的反射活动，是人和动物在长期的种系发展中形成的，它使人和动物能够初步适应环境，对于个体生存和种系生存具有重要意义。后者是指通过后天学习和训练而形成的反射，它是反射活动的高级形式，是人和动物在个体生活过程中按照所处的生活环境，在非条件反射的基础上不断建立起来的，其数量无限，可以建立，也能消退。本题ABCD选项涉及的反射活动均为与生俱来的，为非条件反射，E选项闻到食物香味引起唾液分泌为后天习成的，为条件反射。","","N"],["2003-N15",9,"第4节 神经系统对内脏活动、本能行为和情绪的调节","交感神经系统的功能",2003,15,"A","","交感神经兴奋可使",[["A","胃肠运动加强"],["B","消化腺分泌增多"],["C","膀胱逼尿肌收缩"],["D","支气管平滑肌舒张"],["E","瞳孔缩小"]],"D","大多数交感节后纤维释放的递质是去甲肾上腺素（除支配汗腺和骨骼肌血管的交感节后纤维释放乙酰胆碱外），交感神经系统的活动与各器官上去甲肾上腺素受体的分布有关。交感神经兴奋时，作用于胃平滑肌β₂受体或小肠平滑肌的α₂、β₂受体使胃肠道平滑肌舒张，抑制胃肠运动（A错）；作用于消化腺的α₂受体使消化腺分泌减少（B错）；作用于膀胱逼尿肌的β₂受体使逼尿肌舒张（C错）；作用于支气管平滑肌的β₂受体使支气管平滑肌舒张（D对）；作用于虹膜辐射状肌（瞳孔开大肌）的α₁受体使瞳孔开大肌收缩，瞳孔扩大（E错）。交感神经兴奋的状态可以用机体在剧烈运动时的生理状态来协助记忆：机体在剧烈运动时交感神经兴奋（十版生理学P322），心率加快、心肌收缩力增强，心输出量增加，目的是为全身的肌肉提供更多的血液和氧气；呼吸运动加强，支气管平滑肌舒张，肺泡通气量，目的是为了血液提供更多的氧气；皮肤、肾、胃肠等全身各处的血管平滑肌均收缩，但骨骼肌血管舒张，目的是为了让血液重新分配，为肌肉提供更多的血液；由于全身血液分配至骨骼肌，导致胃肠道供血不足，不利于胃肠道进行消化和吸收，故消化道平滑肌舒张，括约肌收缩，消化腺分泌减少；剧烈运动时，一般不会有特别强烈的尿意，也尿不出来等等。","","N"],["2003-N16",10,"第3节 甲状腺内分泌","促进生长发育",2003,16,"A","","影响神经系统发育最重要的激素是",[["A","生长素"],["B","甲状腺激素"],["C","皮质醇"],["D","肾上腺素"],["E","胰岛素"]],"B","影响神经系统发育最主要的激素是甲状腺激素（TH）（B对），在胚胎期，TH能促进神经元的增殖和分化以及突起和突触的形成；促进胶质细胞的生长和髓鞘的形成，诱导神经生长因子和某些酶的合成，促进神经元骨架的发育等。","","N"],["2003-N17",10,"第5节 肾上腺内分泌","对组织器官活动的影响",2003,17,"A","","下列关于肾上腺糖皮质激素的叙述，正确的是",[["A","促进蛋白质合成"],["B","促进脂肪的合成和贮存"],["C","促进细胞利用葡萄糖"],["D","保持血管对儿茶酚胺的正常反应"],["E","减少血中红细胞的数量"]],"D","糖皮质激素的作用广泛而复杂（十版生理学P369-P371）：①糖皮质激素对体内糖、脂肪和蛋白质代谢均有明显影响：包括减少组织对糖的利用和加速肝糖异生而使血糖升高（C错），提高四肢部分的脂肪酶活性而促进脂肪分解（B错），抑制肝外组织细胞内的蛋白质合成等（A错）；②参加应激反应，提高机体对有害刺激的耐受能力；③对组织器官活动的影响，包括促进红细胞生成（E错）、通过允许作用保持血管对儿茶酚胺的正常反应（D对）等。","","N"],["2003-N18",11,"第2节 女性生殖功能及其调节","月经周期各期的内分泌调控",2003,18,"A","","正常月经周期中雌激素出现第二次高峰的直接原因是",[["A","雄激素的正反馈作用"],["B","孕激素的正反馈作用"],["C","催乳素的作用"],["D","黄体生成素的作用"],["E","促卵泡激素的作用"]],"D","正常月经周期中将出现两次雌激素高峰：在卵泡期，卵泡刺激素（FSH）和黄体生成素（LH）共同作用于卵泡，促使卵泡发育成熟，卵泡颗粒细胞分泌的雌激素水平在卵泡发育成熟过程中持续升高，在排卵前一天血中雌激素浓度到达最高值，形成月经周期中雌激素的第一次分泌高峰，在这一雌激素峰的作用下，下丘脑促性腺激素释放激素（GnRH）分泌增强，刺激LH与FSH分泌，其中LH分泌增加更为明显，形成LH峰并诱发排卵。排卵后，卵巢周期进入黄体期，卵泡颗粒细胞转换为黄体细胞，黄体细胞在LH的作用下（D对）分泌孕激素和雌激素，形成月经周期中孕激素唯一一次分泌高峰和雌激素的第二次分泌高峰。","","N"],["2003-N93",3,"第1节 心脏的泵血功能","心室收缩期",2003,93,"B","","左心室内压最高的是",[["A","等容收缩期末"],["B","等容舒张期末"],["C","快速射血期末"],["D","快速充盈期末"],["E","心房收缩期末"]],"C","心室的活动周期包括收缩期和舒张期，收缩期可分为等容收缩期和射血期，而射血期又可分为快速射血期和减慢射血期，舒张期可分为等容舒张期和心室充盈期，心室充盈期又可分为快速充盈期、减慢充盈期和心房收缩期。舒张期的心室压力（甚至能形成负压，对心房和大静脉血液起抽吸作用）肯定小于收缩期，所以属于舒张期的等容舒张期末、快速充盈期和心房收缩期肯定不是压力最高的。心室收缩使室内压升高至超过主动脉压时，半月瓣开放，等容收缩期结束，进入快速射血期，即等容收缩期进入快速射血期的前提是室内压继续升高，快速射血期的室内压大于等容收缩期。快速射血期心室内的血液很快进入主动脉，但由于心室肌强烈收缩，心室容积迅速缩小，室内压仍继续上升，并在快速射血期末达到峰值（C对）。","","N"],["2003-N94",3,"第1节 心脏的泵血功能","心动周期",2003,94,"B","","左心室内容积最小的是",[["A","等容收缩期末"],["B","等容舒张期末"],["C","快速射血期末"],["D","快速充盈期末"],["E","心房收缩期末"]],"B","心室容积与心室血量有关，左心室容积最小时，左心室血量也最少，左心室血量最少的时期包括减慢射血期末、整个等容舒张期和快速充盈期初（B对）。","","N"],["2003-N95",4,"第4节 呼吸运动的调节","CO₂、H⁺、O₂对呼吸运动的调节",2003,95,"B","","动脉血氧分压降低时引起呼吸加强的主要机制是",[["A","刺激颈动脉体感受器"],["B","刺激主动脉体感受器"],["C","刺激中枢化学感受器"],["D","直接刺激脑桥呼吸调整中枢"],["E","直接刺激延髓呼吸中枢"]],"A","化学感受器是指其适宜刺激是O₂、CO₂和H⁺等化学物质的感受器。根据所在部位的不同，化学感受器分为外周化学感受器和中枢化学感受器两种。外周化学感受器位于颈动脉体和主动脉体，在动脉血PO₂降低、PCO₂或H⁺浓度升高时均受到刺激，反射性地引起呼吸中枢兴奋和血液循环功能的变化（十版生理学P158），颈动脉体和主动脉体虽都参与呼吸和循环的调节，但颈动脉体主要参与呼吸调节，而主动脉体在循环调节方面较为重要。中枢化学感受器位于延髓腹外侧部的浅表部位，生理性刺激是脑脊液中的H⁺，动脉血H⁺浓度升高时，H⁺通过血-脑屏障进入脑脊液发挥作用（但进入速度较慢，限制了H⁺对中枢化学感受器的作用），动脉血PCO₂升高时，血液中的CO₂能够通过血-脑屏障，间接引起脑脊液H⁺浓度升高，从而刺激中枢化学感受器，引起呼吸中枢兴奋。因此，低氧对呼吸运动的刺激作用主要是通过刺激外周化学感受器（颈动脉体）实现的（A对），CO₂和H⁺对呼吸运动的刺激作用则可以通过中枢化学感受器和外周化学感受器共同实现。低氧对中枢的直接作用是抑制的。","","N"],["2003-N96",4,"第4节 呼吸运动的调节","CO₂、H⁺、O₂对呼吸运动的调节",2003,96,"B","","动脉血氢离子浓度增加时引起呼吸加强的主要机制是",[["A","刺激颈动脉体感受器"],["B","刺激主动脉体感受器"],["C","刺激中枢化学感受器"],["D","直接刺激脑桥呼吸调整中枢"],["E","直接刺激延髓呼吸中枢"]],"A","H⁺对中枢化学感受器和外周化学感受器均有刺激作用，并且中枢化学感受器对H⁺的敏感度远大于外周化学感受器，但是动脉血H⁺浓度增加时，增加的H⁺不能直接作用中枢化学感受器，而是需要通过血-脑屏障进入脑脊液（过程很缓慢）才能发挥作用，因此动脉血H⁺浓度增加对中枢化学感受器的作用有限，主要通过刺激外周化学感受器而起作用。外周化学感受器又可分为颈动脉体化学感受器和主动脉体化学感受器两种，其中颈动脉体化学感受器主要参与呼吸功能的调节（A对），而主动脉体化学感受器主要参与循环功能的调节。","","N"],["2003-N111",5,"第3节 胃内消化","促进胃液分泌的主要因素",2003,111,"C","","胆囊收缩素能刺激",[["A","胃液分泌"],["B","胰液分泌"],["C","二者均有"],["D","二者均无"]],"C","胆囊收缩素（CCK）又称促胰酶素（十版生理学P181），由小肠黏膜I细胞分泌。胆囊收缩素的主要功能是促进胆囊收缩和促进胰酶分泌（B对），除此之外，胆囊收缩素对包括胃酸（既有促进，又有抑制，整体是抑制）（A对）、胃蛋白酶原（A对）、胰HCO₃⁻（B对）、肝胆汁、小肠液在内的几乎所有胃肠道消化腺分泌物均有促进作用（七版生理学P170 表6-3）。本题AB均对，正确答案为C。","","N"],["2003-N112",5,"第3节 胃内消化","抑制胃液分泌的主要因素",2003,112,"C","","盐酸能刺激",[["A","胃液分泌"],["B","胰液分泌"],["C","二者均有"],["D","二者均无"]],"B","盐酸分泌过多时，可负反馈抑制胃液（胃酸）分泌（A错）：①抑制胃窦黏膜G细胞分泌促胃液素，从而抑制胃液分泌；②刺激胃黏膜δ细胞分泌生长抑素，间接抑制促胃液素和胃液分泌；③刺激小肠黏膜释放促胰液素和球抑胃素，二者均可抑制胃液分泌，促胰液素还可促进胰液（B对）大量分泌。","","N"],["2003-N113",7,"第1节 肾的功能解剖和肾血流量","滤过膜的构成",2003,113,"C","","正常情况下，尿中不出现红细胞是由于",[["A","肾小球滤过膜的机械屏障作用"],["B","肾小球滤过膜的电荷屏障作用"],["C","二者均有"],["D","二者均无"]],"A","肾小球滤过膜由毛细血管内皮细胞、基膜和肾小囊脏层足细胞的足突构成，三层结构的孔径分别为 70～90nm、2～8nm 和 4～11nm，此为滤过膜的机械屏障，可阻挡大分子量蛋白质和红细胞的滤过（A对）。滤过膜的三层结构都是由带负电荷的蛋白质组成，因此带负电荷的物质（如蛋白质和红细胞）不易通过滤过膜（B对），此为滤过膜的电荷屏障。因此，本题 AB 均对，正确答案应为 C，但参考答案为A，可能与A选项机械屏障发挥主要作用有关。","","N"],["2003-N114",7,"第1节 肾的功能解剖和肾血流量","滤过膜的构成",2003,114,"C","","正常情况下，尿中不出现蛋白质是由于",[["A","肾小球滤过膜的机械屏障作用"],["B","肾小球滤过膜的电荷屏障作用"],["C","二者均有"],["D","二者均无"]],"C","肾小球滤过膜由毛细血管内皮细胞、基膜和肾小囊脏层足细胞的足突构成，三层结构的孔径分别为70～90nm、2～8nm和4～11nm，蛋白质分子的直径一般都大于三层结构的最小孔径2nm，因此不能自由滤过，此为滤过膜的机械屏障（A对）。滤过膜的三层结构都是由带负电荷的蛋白质组成，因此带负电荷的蛋白质（人体内大部分蛋白质都带负电荷）不易通过滤过膜，此为滤过膜的电荷屏障（B对）。因此尿中不出现蛋白质是由于肾小球滤过膜的机械屏障和电荷屏障共同在起作用。本题AB均对，正确答案为C。","","N"],["2003-N129",1,"第3节 细胞的电活动","局部电位的特征和意义",2003,129,"X","","局部电位的特点是",[["A","没有不应期"],["B","有“全或无”现象"],["C","可以总和"],["D","传导较慢"]],"AC","局部电位是动作电位之外的另一类重要的电信号，其产生和传播的特点与动作电位截然不同：①动作电位“全或无”的特性，其幅度大小不受刺激强度的影响，局部电位不具有“全或无”的特性（B错），其幅度大小受刺激强度的影响，呈等级性；②动作电位为不衰减传播，能够在膜上作远距离传播，局部电位为衰减式传播，不能在膜上作远距离传播；③动作电位因为绝对不应期的存在，不会发生叠加总和，局部反应没有不应期（A对），多个局部反应可以在时间或空间上发生叠加总和（C对）。局部电位为衰减性传播，传导距离较近，而非传导较慢（D错）。","","N"],["2003-N130",3,"第5节 器官循环","冠脉循环的生理特点",2003,130,"X","","下列哪些情况可使冠脉血流量增加",[["A","心室收缩期延长"],["B","心室舒张期延长"],["C","动脉舒张压升高"],["D","交感神经兴奋"]],"BCD","动脉舒张压的高低和心舒期的长短是影响CBF的重要因素。舒张压越高，舒张期越长，冠脉血流量越多，故舒张压升高和舒张期延长时，冠状动脉血流量增多（BC对）。心室收缩期延长则相应地心室舒张期缩短，冠状动脉血流量减少（A错）。交感神经的直接作用是使冠脉收缩，这主要是通过激活血管平滑肌上的α受体而实现的；但交感活动加强可通过激活心肌上的β₁受体使心率加快，心肌收缩力增强，耗氧量增加，代谢加强而使代谢产物增多，经过代谢性自身调节机制（参见十版生理学P128），继发性引起冠脉舒张。剧烈运动或大失血的情况下，交感神经兴奋使全身血管收缩，而冠脉血管却无明显收缩，从而通过全身血量的重新分配保证了冠脉血流的优先供应（脑血流也存在优先供血机制，参见2000N93B的答案解析）。","","N"],["2003-N131",9,"第1节 神经系统功能活动的基本原理","中枢兴奋传播的特征",2003,131,"X","","突触的传递特征有",[["A","双向性"],["B","总和现象"],["C","相对不疲劳"],["D","对内环境改变敏感"]],"BD","在中枢神经系统内，兴奋性化学传递明显不同于神经纤维上的冲动传导（十版生理学P300），其特征主要表现为以下几个方面：①单向传递：在反射活动中，兴奋经化学性突触传递，只能从突触前末梢传向突触后神经元，这一现象称为单向传播（A错）；②中枢延搁：兴奋在中枢传播时往往需要较长时间，这一现象称为中枢延搁；③总和：在反射活动中，单根神经纤维的传入冲动一般不能使中枢发出传出效应，需有若干神经纤维的传入冲动同时或几乎同时到达同一中枢，发生空间和时间的总和，才可能产生传出效应（B对）；④兴奋节律的改变：如果测定某一反射弧的传入神经（突触前神经元）和传出神经（突触后神经元）在兴奋传递过程中的放电频率，两者往往不同。这是因为突触后神经元常同时接受多突触前神经元的突触传递，突触后神经元自身的功能状态也可能不同，且反射中枢常经过多个中间神经元接替，因此最后传出冲动的频率（兴奋节律）取决于各种影响因素的综合效应，即在此过程中兴奋节律可能发生改变；⑤后发放与反馈；⑥对内环境变化敏感和易疲劳：因为突触间隙与细胞外液相通，因此内环境理化因素的变化，如缺氧、CO₂过多、麻醉剂以及某些药物等均可影响化学性突触传递（D对）。另外，用高频电脉冲连续刺激突触前神经元，突触后神经元的放电频率将逐渐降低；而将同样的刺激施加于神经纤维，则神经纤维的放电频率在较长时间内不会降低。说明突触传递相对容易发生疲劳（C错），其原因可能与递质的耗竭有关。","","N"],["2003-N132",10,"第1节 内分泌与激素","激素作用的一般特征",2003,132,"X","","激素的一般特性有",[["A","特异性作用"],["B","高效能生物放大作用"],["C","信息传递作用"],["D","允许作用"]],"ABCD","虽然各种激素对靶细胞的调节效应不尽相同，但可表现出一些共同的作用特征：①特异作用（A对）：尽管多数激素均可通过血液循环广泛接触各部位的器官、腺体、组织和细胞，但各种激素只选择性作用于分布有该激素受体的靶器官、靶腺、靶组织和靶细胞；②信使作用（C对）：激素是一种信使物质或传讯分子，它携带了某种特定含义的信号，仅起传递某种信息的作用；③高效作用（B对）：在生理状态下，激素的血浓度很低，多在pmol/L～nmol/L的数量级，但信号转导环节具有生物放大效应，激素与受体结合后，引发细胞内的信号转导程序，经逐级放大后可产生效能极高的效应；④相互作用：内分泌腺体和分泌激素的细胞布于全身，各种激素又都以体液为媒介递送信息，所产生的效应总会相互影响、彼此关联，错综复杂，如协同作用、拮抗作用和允许作用（D对）等。","","N"],["2004-N1",0,"第6节 人体内自动控制系统","负反馈控制系统",2004,1,"A","","维持内环境稳态的重要调节方式是",[["A","负反馈调节"],["B","自身调节"],["C","正反馈调节"],["D","体液性调节"],["E","前馈调节"]],"A","负反馈调节极为常见，具有纠正偏差的功能，在维持机体生理功能的稳态中具有重要意义（A对），如动脉血压的压力感受性反射（十版生理学P122），肺的牵张反射（十版生理学P161）等。正反馈调节相对少见，并且没有纠正偏差的功能，其意义不在于维持稳态，而在于促进某一生理活动的正常进行（C错），如血液凝固（十版生理学P67）、蛋白酶原的激活、排卵前夕雌激素对LH的促分泌作用（十版生理学P389）等。自身调节和体液调节为生理功能的调节方式，可能介导维持稳态的负反馈调节，如胰岛素的降糖作用（体液调节）（十版生理学P374）、动脉血压的肌源性自身调节（自身调节）（十版生理学P128），也可能介导促进某一生理活动正常进行的正反馈调节，如排卵前夕雌激素对LH的促分泌作用（体液调节）（十版生理学P389）、蛋白酶原的激活（自身调节）等（BD错）。控制部分在反馈信息尚未到达前已收到纠正信息的影响，及时纠正其指令可能出现偏差，这种调节方式称为前馈调节（十版生理学P11），前馈具有预见性，能够克服反馈“滞后”和“波动”的缺点，但相对反馈控制系统来说并不常见，在机体稳态调控过程中发挥的作用有限（E错）。","","N"],["2004-N2",1,"第1节 细胞膜的物质转运功能","钠-钾泵",2004,2,"A","","细胞膜内外正常Na⁺和K⁺浓度差的形成和维持是由于",[["A","膜安静时对K⁺通透性大"],["B","膜兴奋时Na⁺通透性增加"],["C","Na⁺易化扩散的结果"],["D","膜上Na⁺泵的作用"],["E","膜上Ca²⁺泵的作用"]],"D","细胞膜内、外Na⁺和K⁺浓度差是细胞发生电活动的基础，其形成和维持源自于膜上Na⁺-K⁺泵消耗能量逆浓度梯度吸入K⁺排出Na⁺的作用（D对）。","","N"],["2004-N3",1,"第1节 细胞膜的物质转运功能","出胞",2004,3,"A","","运动神经纤维末梢释放乙酰胆碱（ACh）属于",[["A","单纯扩散"],["B","易化扩散"],["C","主动转运"],["D","出胞作用"],["E","入胞作用"]],"D","运动神经纤维末梢释放ACh的具体过程为运动神经末梢传到末梢的动作电位触发接头前膜Ca²⁺依赖性突触囊泡出胞（D对），释放ACh至接头间隙，再由ACh激活终板膜中的N₂型ACh受体阳离子通道，产生终板膜电位变化。","","N"],["2004-N4",1,"第1节 细胞膜的物质转运功能","继发性主动转运",2004,4,"A","","与肠黏膜细胞吸收葡萄糖关系密切的转运过程是",[["A","HCO₃⁻的被动吸收"],["B","Na⁺的主动吸收"],["C","K⁺的主动吸收"],["D","Cl⁻的被动吸收"],["E","Ca²⁺的主动吸收"]],"B","肠黏膜细胞吸收葡萄糖属于Na⁺-葡萄糖同向转运体继发性主动转运过程，其驱动力并不直接来自ATP的分解，而是来自Na⁺的主动吸收所形成的离子浓度梯度（B对）。","","N"],["2004-N5",2,"第3节 生理性止血","生理性抗凝物质",2004,5,"A","","肝素抗凝血的主要作用机制是",[["A","抑制Ⅹ因子激活"],["B","增强抗凝血酶Ⅲ的活性"],["C","去除Ca²⁺"],["D","促进纤维蛋白溶解"],["E","抑制血小板的作用"]],"B","肝素首先从肝脏发现而得名，主要由肥大细胞和嗜碱性粒细胞产生，肝素具有较强的抗凝作用，但在缺乏抗凝血酶（过去曾称抗凝血酶Ⅲ）的条件下，肝素的抗凝作用很弱，肝素主要通过增强抗凝血酶的活性而间接发挥抗凝作用（B对），后者为丝氨酸蛋白酶抑制物，能与内源性凝血途径产生的凝血酶、FⅨa、FⅩa、FⅪa和FⅫa等分子活性中心的丝氨酸残基结合而抑制其活性，与肝素结合后，其抗凝作用可增强2000倍以上。但在正常情况下，循环血浆中几乎无肝素存在，抗凝血酶主要通过与内皮细胞表面的硫酸乙酰肝素结合而增强血管内皮的抗凝功能。","","N"],["2004-N6",3,"第2节 心脏的电生理学及生理特性","心肌细胞兴奋性的周期性变化",2004,6,"A","","心肌细胞有效不应期特别长的生理意义是",[["A","使心肌不发生强直性收缩"],["B","使心肌“全或无”式收缩"],["C","使心肌收缩更有力"],["D","使心肌产生自动节律性兴奋"],["E","使心肌同步收缩"]],"A","心肌细胞的有效不应期包括绝对不应期和局部反应期，从动作电位0期开始到3期复极化至-60mV的这段时期内，膜的兴奋性暂时缺失或极度下降，即任何刺激都不能产生兴奋和收缩的时期，心肌细胞的有效不应期特别长，保证了心肌细胞在收缩期不会接受新刺激再次发生收缩，使心肌不会像骨骼肌那样发生完全强直收缩（A对），而始终进行收缩和舒张交替的活动，从而保证心脏泵血功能的正常进行。","","N"],["2004-N7",4,"第3节 气体在血液中的运输","CO₂的运输形式",2004,7,"A","","CO₂在血液中运输的主要形式是",[["A","物理溶解"],["B","H₂CO₃"],["C","HCO₃⁻"],["D","HbNHCOOH"],["E","HbCO₂"]],"C","CO₂在血液中的运输形式包括物理溶解和化学结合，其中物理溶解仅占5%，化学结合占95%，化学结合又包括占88%的HCO₃⁻和占7%的氨基甲酰血红蛋白，故CO₂在血液中运输的主要形式是化学结合中的HCO₃⁻（C对）。","","N"],["2004-N8",4,"第1节 肺通气","肺通气的动力",2004,8,"A","","肺通气的原动力是",[["A","气体分压大小"],["B","肺内压变化"],["C","胸内压变化"],["D","肺本身的舒缩活动"],["E","呼吸肌的舒缩活动"]],"E","肺通气是气体流动进出肺的过程，要实现肺通气，必须在肺泡与外界环境之间存在一定的压力差。在一定的海拔高度，大气压是相对恒定的，因此肺泡与外界环境之间的压力差是由肺泡内的压力（肺内压）决定的。肺内压的高低取决于肺的扩张和缩小，但肺自身并不具有主动扩张和缩小的能力，其扩张和缩小依赖于呼吸肌的收缩和舒张引起的胸廓运动。因此，由肺内压的变化建立的肺泡与外界环境之间的压力差是肺通气的直接动力，而呼吸肌的舒缩活动（E对）引起的节律性呼吸运动则是肺通气的原动力。","","N"],["2004-N9",5,"第1节 消化生理概述","电生理特性",2004,9,"A","","下列关于消化道平滑肌基本电节律的叙述，错误的是",[["A","是指节律性去极化波"],["B","又称慢波电位"],["C","其产生不依赖于神经的存在"],["D","节律不受神经和激素的影响"],["E","波幅在10～15mV之间"]],"D","消化道平滑肌的细胞电活动比骨骼肌复杂，除静息电位和动作电位外，平滑肌细胞还存在第三种电位形式——慢波电位。慢波电位在静息电位的基础上产生，为节律性去极化波（含去极化和复极化过程）（A对），幅度为10～15mV（E对），慢波电位对平滑肌的收缩节律起决定性作用，故又称基本电节律（B对）。慢波电位的产生不依赖于神经的存在（C对），但是其节律受神经和激素的影响（D错，为本题正确答案）。","","N"],["2004-N10",5,"第4节 小肠内消化","缩胆囊素",2004,10,"A","","CCK刺激胰液分泌的特点是",[["A","水分少，HCO₃⁻和酶含量多"],["B","水分和HCO₃⁻含量少，酶含量多"],["C","水分和HCO₃⁻含量多，酶含量少"],["D","水分多，HCO₃⁻和酶含量少"],["E","水分、HCO₃⁻和酶含量都多"]],"B","胰液分泌受神经调节和体液调节的双重控制，以体液调节为主。体液调节主要由促胰液素和缩胆囊素介导，促胰液素主要作用于胰腺小导管上皮细胞，使其分泌大量的水和碳酸氢盐，而酶的含量则不高。缩胆囊素主要作用于胰腺的腺泡细胞使其分泌大量的酶，而水和碳酸氢盐的量却很少（B对）。","","N"],["2004-N11",6,"第1节 能量代谢","食物的特殊动力效应",2004,11,"A","","下列物质中，食物的特殊动力作用最强的是",[["A","糖"],["B","脂肪"],["C","蛋白质"],["D","维生素"],["E","无机盐"]],"C","人在进食后的一段时间内，即使在安静状态下，也会出现能量代谢率增高的现象，说明进食能刺激机体额外消耗能量，此为食物特殊动力作用。实验证明，食物的成分不同，所产生的食物特殊动力作用也不同，在三种主要营养物质中，进食蛋白质产生的食物特殊动力作用最为显著（C对）。","","N"],["2004-N12",8,"第4节 听觉","耳蜗的功能结构要点",2004,12,"A","","听觉感受器位于",[["A","耳蜗"],["B","鼓膜"],["C","半规管"],["D","椭圆囊"],["E","球囊"]],"A","听觉的产生过程：声波通过外耳和中耳组成的传音系统传向内耳，再经内耳中的耳蜗的感音换能作用将声波的机械能转变为听神经纤维上的神经冲动，后者传到大脑皮层引起听觉。鼓膜是中耳中的结构，所以它是传音装置（B错），内耳中的耳蜗是听觉感受器螺旋器所在部位（A对）。内耳中的半规管、椭圆囊和球囊是前庭器官，与听觉无关（CDE错）。","","N"],["2004-N13",8,"第3节 视觉","感光细胞及其特征",2004,13,"A","","下列关于视杆细胞的叙述，错误的是",[["A","不能产生动作电位"],["B","能产生感受器电位"],["C","视敏度高"],["D","光敏度高"],["E","司暗视觉"]],"C","视杆细胞是视网膜中的感光细胞，可以将作用于它的光能转换为传入神经的动作电位。视杆细胞本身并不产生动作电位（A对），而产生一种过渡型的超极化型感受器电位（B对），并以电紧张的形式扩布至细胞终足处，影响此处递质释放，从而引起初级传入神经末梢发生膜电位变化。视杆细胞的光敏度高（D对），能在昏暗环境中感受弱光刺激，司暗视觉（E对），但是其视敏度低（C错，为本题正确答案），对被视物细节的分辨能力较差。","","N"],["2004-N14",7,"第3节 肾小管和集合管的物质转运功能","肾小管和集合管重吸收量大并具有高度选择性",2004,14,"A","","原尿在肾脏被重吸收的比率为",[["A","67%"],["B","85%"],["C","89%"],["D","95%"],["E","99%"]],"E","正常人两肾生成的超滤液每天达180L，而终尿量仅1.5L左右，超滤液中的水分约99％被肾小管和集合管重吸收（E对）。此外，小管液中的葡萄糖和氨基酸全部被重吸收，Na⁺、Ca²⁺和尿素等可不同程度地被重吸收，而肌酐、H⁺和K⁺等则可被分泌到小管液中而排出体外。","","N"],["2004-N15",10,"第6节 胰岛内分泌","胰高血糖素的生理作用",2004,15,"A","","下列哪种激素与水、钠代谢无关",[["A","氢化可的松"],["B","醛固酮"],["C","雌激素"],["D","胰高血糖素"],["E","抗利尿激素"]],"D","醛固酮进入肾远曲小管和集合管上皮细胞胞质后，与胞质内受体结合，形成的激素-受体复合物进入细胞核内，生成多种醛固酮诱导蛋白，进而增加K⁺的排泄和Na⁺、水的重吸收（B对）。氢化可的松是糖皮质激素的一种，糖皮质激素有相当于醛固酮1/500的保Na⁺排K⁺的作用，但是，与醛固酮不同的是，糖皮质激素能够降低入球小动脉的血流阻力，增加肾血浆流量，进而通过使滤过平衡点向出球小动脉移动，增加了肾小球滤过率，此外，糖皮质激素还能抑制血管升压素的分泌，使肾小管对水的通透性降低，水的重吸收减少，因此有利于肾排水（A对）。高浓度的雌激素可使体液向组织间隙转移，使循环血量减少而引起醛固酮分泌，促进肾小管对钠和水的重吸收，导致钠、水潴留（C对）。抗利尿激素又称血管升压素，有V₁和V₂两种受体，V₁分布于血管平滑肌，激活后可引起平滑肌收缩，血流阻力增大，血压升高；V₂受体主要分布在肾集合管上皮细胞，抗利尿激素与V₂受体结合后，可以增大顶端膜对水的通透性，促进水的重吸收（E对）。胰高血糖素（D错，为本题正确答案）是胰岛α细胞分泌的、主要作用是通过增加血糖的来源和减少血糖的去路而实现血糖升高的一种激素，与水、钠代谢无关。","","N"],["2004-N16",11,"第2节 女性生殖功能及其调节","月经周期的分期",2004,16,"A","","排卵后形成的黄体可分泌的激素是",[["A","黄体生成素"],["B","卵泡刺激素"],["C","促性腺激素释放激素"],["D","人绒毛膜生长素"],["E","孕激素和雌激素"]],"E","排卵后，卵巢周期进入黄体期，卵泡颗粒细胞和内膜细胞分别转化为颗粒黄体细胞和膜黄体细胞，黄体细胞在黄体生成素（LH）的作用下分泌孕激素和雌激素（E对）。黄体生成素（LH）和卵泡刺激素（FSH）均为腺垂体激素，由腺垂体分泌（十版生理学P338）（AB错）。促性腺激素释放激素（GnRH）为下丘脑调节肽，由下丘脑促垂体区小细胞神经元分泌（C错）。人绒毛膜生长素（hCS）由胎盘分泌（十版生理学P395）。","","N"],["2004-N17",11,"第1节 男性生殖功能及其调节","雄激素的合成、代谢和利用",2004,17,"A","","睾丸间质细胞的生理功能是",[["A","分泌雄激素"],["B","营养和支持生殖细胞"],["C","起血睾屏障作用"],["D","产生精子"],["E","分泌雄激素结合蛋白"]],"A","睾丸实质由睾丸小叶组成，睾丸小叶内有曲细精管和间质细胞，而曲细精管由生精细胞和支持细胞构成（十版生理学P383）。间质细胞的生理功能是分泌雄激素（记忆方法：奸（间）雄）（A对）；营养和支持生殖细胞、起血睾屏障作用及分泌雄激素结合蛋白的是支持细胞（BCE错）；产生精子的是生精细胞（D错）。","","N"],["2004-N18",9,"第1节 神经系统功能活动的基本原理","兴奋性突触后电位",2004,18,"A","","兴奋性突触后电位的电变化是",[["A","极化"],["B","去极化"],["C","超极化"],["D","反极化"],["E","复极化"]],"B","根据突触后膜发生去极化或超极化，可将突触后电位分为兴奋性和抑制性突触后电位两种。当兴奋性递质作用于突触后膜的相应受体时，使突触后膜对Na⁺和K⁺的通透性增大，且Na⁺内流大于K⁺外流，故发生净内向电流，使静息电位减小，即突触后膜发生去极化（B对）。而抑制性突触后电位是当抑制性递质作用于突触后膜的相应受体时，突触后膜中的Cl⁻通道开放，Cl⁻内流，引起净外向电流，使静息电位增大，即突触后膜发生超极化（C错）。极化（十版生理学P29）是指安静时细胞膜两侧处于外正内负的状态，是细胞的静息状态。反极化（十版生理学P29）是指去极化至零电位后膜电位进一步变为正值，使膜两侧电位的极性与原来的极化状态相反。复极化（十版生理学P29）是指细胞膜去极化后再向静息电位方向恢复的过程。","","N"],["2004-N93",9,"第1节 神经系统功能活动的基本原理","突触后抑制",2004,93,"B","","闰绍细胞轴突末梢释放的递质是",[["A","甘氨酸"],["B","多巴胺"],["C","乙酰胆碱"],["D","5-羟色胺"],["E","P物质"]],"A","中枢神经元兴奋时，传出冲动沿轴突外传，同时又经轴突侧支兴奋一个抑制性中间神经元，后者释放抑制性递质，反过来抑制原先发生兴奋的神经元及同一中枢的其他神经元，这种抑制称为回返性抑制。闰绍细胞是回返性抑制的一种抑制性中间神经元，其释放的递质是甘氨酸（A对）。多巴胺是黑质-纹状体通路中的主要递质（十版生理学P297），乙酰胆碱是大多数副交感神经释放的递质（十版生理学P295），5-羟色胺是肠嗜铬样细胞释放的递质（十版生理学P297），P物质是一种速激肽，多存在于脊髓初级传入通路，主要介导痛觉的传导。","","N"],["2004-N94",9,"第3节 神经系统对躯体运动的调控","黑质-纹状体投射系统",2004,94,"B","","黑质-纹状体通路中的主要递质是",[["A","甘氨酸"],["B","多巴胺"],["C","乙酰胆碱"],["D","5-羟色胺"],["E","P物质"]],"B","黑质-纹状体通路中的主要递质是多巴胺（B对），黑质-纹状体多巴胺能系统的作用在于抑制纹状体内的乙酰胆碱能系统，帕金森病就是由于黑质多巴胺能神经元受损，其对纹状体内胆碱能神经元的抑制作用减弱，导致乙酰胆碱能系统功能亢进，进而影响了新纹状体传出神经元的活动而引起的一系列症状。","","N"],["2004-N95",3,"第2节 心脏的电生理学及生理特性","窦房结细胞动作电位",2004,95,"B","","窦房结细胞动作电位0期去极化的原因是",[["A","Na⁺内流"],["B","Ca²⁺内流"],["C","Cl⁻内流"],["D","K⁺内流"],["E","K⁺外流"]],"B","窦房结内含有丰富的自律细胞，这些自律细胞称为P细胞。窦房结P细胞的跨膜电位及其产生机制明显不同于心室肌细胞。心室肌0期去极化的离子机制为INa⁺通道（快钠通道）介导的Na⁺内流，窦房结P细胞缺乏INa⁺通道，其去极化主要依赖于L型钙通道（慢钙通道）介导的Ca²⁺内流（B对）。","","N"],["2004-N96",3,"第2节 心脏的电生理学及生理特性","心室肌细胞动作电位",2004,96,"B","","心室肌细胞动作电位3期复极化的原因是",[["A","Na⁺内流"],["B","Ca²⁺内流"],["C","Cl⁻内流"],["D","K⁺内流"],["E","K⁺外流"]],"E","心室肌细胞3期复极化是由2期L型钙通道失活关闭，内向离子流减弱，而Iₖ通道介导的K⁺外流进一步增加所致（E对），到3期末，随着膜电位负值增加，Iₖ₁通道介导的K⁺外流也增大，后者又进一步使复极化过程加快，这种再生性循环使3期复极化越来越快，直至复极化完成。","","N"],["2004-N111",1,"第1节 细胞膜的物质转运功能","继发性主动转运",2004,111,"C","","葡萄糖的重吸收需要",[["A","钠泵"],["B","载体"],["C","二者均是"],["D","二者均非"]],"C","葡萄糖在近端肾小管的重吸收是通过钠-葡萄糖同向转运体实现的，属于继发性主动转运，不仅需要载体，还需要钠泵提供势能（AB均对，正确答案为C）。","","N"],["2004-N112",1,"第1节 细胞膜的物质转运功能","单纯扩散",2004,112,"C","","肾小管上皮细胞分泌氨需要",[["A","钠泵"],["B","载体"],["C","二者均是"],["D","二者均非"]],"D","肾小管上皮细胞分泌氨（NH₃）属于单纯扩散的过程，无需用到载体和钠泵。本题AB均错，正确答案为D。","","N"],["2004-N113",10,"第3节 甲状腺内分泌","调节新陈代谢",2004,113,"C","","能促进蛋白质合成的激素是",[["A","生长激素"],["B","甲状腺激素"],["C","二者均是"],["D","二者均非"]],"C","生长激素（GH）既可促进蛋白质的合成代谢，又可促进蛋白质的分解代谢，总体来说以促进合成代谢为主（A对），特别是促进肝外组织蛋白质的合成；甲状腺激素与生长激素一样，既可促进蛋白质合成代谢（B对），也可促进蛋白质分解代谢，甲状腺激素分泌适量时，以促进合成代谢为主，甲状腺激素分泌过量时，以促进分解代谢为主。本题AB均对，正确答案为C。","","N"],["2004-N114",10,"第3节 甲状腺内分泌","促进生长发育",2004,114,"C","","幼年时缺乏，可引起呆小症的激素是",[["A","生长激素"],["B","甲状腺激素"],["C","二者均是"],["D","二者均非"]],"B","生长激素和甲状腺激素均有促进生长发育的作用。生长激素主要促进骨骼与肌肉的生长发育，幼年时缺乏生长激素，可引起以智力正常、身材矮小为特征的侏儒症；甲状腺激素不仅可协同生长激素促进骨骼与肌肉的生长发育，还能促进脑的发育，幼年时缺乏甲状腺激素，可引起以严重智力迟钝、身材矮小为特征的呆小症（B对）。","","N"],["2004-N129",9,"第4节 神经系统对内脏活动、本能行为和情绪的调节","交感神经系统的功能",2004,129,"X","","交感神经节后纤维支配的组织有",[["A","肾上腺髓质"],["B","血管平滑肌"],["C","胰腺和胃腺"],["D","心传导组织"]],"BCD","交感神经属于自主神经，自主神经由节前神经元和节后神经元组成，节前神经元胞体位于中枢内，发出的神经纤维称为节前纤维，节前纤维在抵达效应器官前进入神经节内换元，由节内神经元发出节后纤维支配效应器官，血管平滑肌、胰腺和胃腺、心传导组织均属于交感神经节后纤维支配的效应器官（BCD对）。肾上腺髓质属于例外，它直接接受交感神经节前纤维的支配（A错）。","","N"],["2004-N130",10,"第5节 肾上腺内分泌","应激性调节",2004,130,"X","","在应激反应中，血中浓度升高的激素有",[["A","肾上腺素"],["B","胰岛素"],["C","甲状腺激素"],["D","肾上腺皮质激素"]],"AD","当机体遭受到各种有害刺激，如创伤、手术、感染、中毒、疼痛、缺氧、寒冷、恐惧等，腺垂体立即释放大量ACTH，并使GC（D对）快速大量分泌，引起机体发生非特异性的防御性反应，即应激反应。应激反应能够提高机体对有害刺激的耐受能力，减轻各种不良反应，对维持机体生命活动具有极其重要的意义。应激反应机制十分复杂，除ACTH、GC分泌迅速增多外，儿茶酚胺（A对）、催乳素、生长激素、血管升压素、β-内啡肽、胰高血糖素和醛固酮等激素的分泌也明显增加。应激反应时，甲状腺素降解增加，血中甲状腺激素浓度应降低（C错）。","","N"],["2004-N131",3,"第4节 心血管活动的调节","心脏的神经支配",2004,131,"X","","下列关于心肌生物电活动的叙述，正确的有",[["A","迷走神经兴奋引起心房肌超极化"],["B","交感神经兴奋引起心室肌超极化"],["C","细胞外高钠可引起心肌细胞超极化"],["D","细胞外高钾可引起心肌细胞去极化"]],"AD","迷走神经兴奋时，其节后纤维末梢释放的乙酰胆碱作用于心肌细胞膜上的M型胆碱能受体，进而通过G蛋白直接激活乙酰胆碱依赖性钾通道，引起K⁺外流增加，窦房结P细胞（自律性降低）、心房肌细胞、心室肌细胞等心肌细胞均发生超极化（A对B错）。细胞外高钠时，静息状态下进入细胞内的 Na⁺增加（静息状态下Na⁺ 通透性小，只能轻微增加），内流的Na⁺可部分抵消 K⁺ 外流所形成的膜内负电位，使静息电位轻微减小而引起心肌细胞去极化（C错）。细胞外高钾时，细胞内液和细胞外液之间的K⁺ 浓度差减小，静息状态下K⁺ 外流减少，静息电位的绝对值减小，心肌细胞呈现去极化状态（D对）。","","N"],["2004-N132",7,"第4节 尿液的浓缩和稀释","肾髓质间液渗透浓度梯度的形成",2004,132,"X","","尿液的浓缩与稀释取决于",[["A","肾小球滤过率"],["B","血浆胶体渗透压"],["C","肾髓质渗透梯度"],["D","ADH的分泌"]],"CD","尿液的浓缩与稀释实际上取决于肾小管和集合管对小管液中水和溶质重吸收的比率，而水的重吸收较易改变，因而是其主要方面。水的重吸收取决于两个基本条件，一是肾小管内外的渗透浓度梯度，是水重吸收的动力；二是集合管对水的通透性。所以，尿的浓缩与稀释一方面取决于肾髓质渗透梯度（C对），另一方面取决于集合管对水的通透性，后者主要受血液中ADH（血管升压素）浓度的影响（D对）。血浆胶体渗透压变化可使有效滤过压变化而影响肾小球滤过率，肾小球滤过率则影响原尿的生成量，与尿液的浓缩与稀释无关（AB错）。","","N"],["2005-N1",0,"第4节 机体的内环境、稳态和生物节律","机体的内环境",2005,1,"A","","机体的内环境是指",[["A","体液"],["B","细胞内液"],["C","细胞外液"],["D","血浆"],["E","组织间液"]],"C","人体内绝大多数细胞并不与外界环境相接触，而是浸浴在机体内部的细胞外液中，因此细胞外液是细胞直接接触和赖以生存的环境，生理学中将围绕在多细胞动物体内细胞周围的体液，即细胞外液，称为内环境（C对），以区别于整个机体所处的外环境。细胞外液包括血浆、组织液、淋巴液、脑脊液等。","","N"],["2005-N2",1,"第1节 细胞膜的物质转运功能","易化扩散",2005,2,"A","","在细胞膜的物质转运中，Na⁺跨膜转运的方式是",[["A","单纯扩散和易化扩散"],["B","单纯扩散和主动转运"],["C","易化扩散和主动转运"],["D","易化扩散和出胞或入胞"],["E","单纯扩散、易化扩散和主动转运"]],"C","跨细胞膜的物质转运包括单纯扩散、易化扩散、主动转运、膜泡运输等方式。其中单纯扩散主要介导脂溶性物质或少数不带电荷的极性小分子物质的转运，如O₂、CO₂、N₂、NH₃、类固醇激素、乙醇、尿素、甘油、水等等；易化扩散包括经通道易化扩散和经载体易化扩散两种形式，经通道易化扩散主要以离子通道的形式（如Na⁺通道、K⁺通道等）介导各种带电离子顺浓度梯度或电位梯度的跨膜转运，经载体易化扩散主要介导葡萄糖、氨基酸等水溶性小分子物质进行顺浓度梯度的跨膜转运；主动转运包括原发性主动转运和继发性主动转运两种形式，原发性主动转运通常以离子泵的形式（如Na⁺泵、Ca²⁺泵、H⁺泵等）转运各种带电离子，继发性主动转运是载体介导的易化扩散与原发性主动转运相耦联的转运系统，可使水溶性小分子物质、带电离子逆浓度梯度或电位梯度的跨膜转运（易化扩散和继发性主动转运的区别是前者顺浓度梯度或电位梯度，不耗能，后者逆浓度梯度或电位梯度，耗能）；膜泡运输包括出胞和入胞两种形式，主要介导大分子和颗粒物质的跨膜转运。综上，Na⁺跨膜转运的方式包括易化扩散（经通道易化扩散）和主动转运两种方式（C对）。","","N"],["2005-N3",1,"第3节 细胞的电活动","动作电位的概念及特点",2005,3,"A","","能以不衰减的形式沿可兴奋细胞膜传导的电活动是",[["A","静息膜电位"],["B","锋电位"],["C","终板电位"],["D","感受器电位"],["E","突触后电位"]],"B","静息电位是细胞在安静状态时膜内外的电位差，不能够传导（A错）。锋电位是动作电位的主要组成部分，具有“全或无”特性，可进行不衰减传导（B对）。终板电位、感受器电位和突触后电位均为局部电位，局部电位以电紧张的方式向周围扩布，为衰减性传导（CDE错）。","","N"],["2005-N4",2,"第2节 血细胞生理","红细胞生成的调节",2005,4,"A","","下列选项中，能有效刺激促红细胞生成素血浆含量增加的是",[["A","缺O₂"],["B","CO₂滞留"],["C","雌激素"],["D","肾疾病"],["E","再生障碍性贫血"]],"A","EPO主要由肾脏分泌（肝脏也能分泌少许），组织缺氧（A对）是促进EPO分泌的主要刺激因素，任何引起肾脏氧供应不足的因素如低氧、贫血（E对）或肾血流减少等，均可促进EPO的合成和分泌，使血浆中EPO的含量增加。性激素也能影响EPO的生成，雄激素可以提高血浆中EPO的浓度，促进红细胞的生成，而雌激素则可降低红系祖细胞对EPO的反应，抑制红细胞的生成（C错），雄激素和雌激素对红细胞生成的不同效应，可能是成年男性红细胞数高于女性的原因之一。患有肾脏疾病时，产生EPO的肾单位受到破坏，EPO的产生减少（D错），EPO减少影响红细胞的分化与成熟，是发生肾性贫血的主要原因之一。CO₂的含量与促红细胞生成素的生成无直接关系（B错）。本题A为最佳选项，E亦为正确选项，给出的参考答案仅为A。","","N"],["2005-N5",2,"第3节 生理性止血","纤维蛋白与纤维蛋白原的降解",2005,5,"A","","纤维蛋白降解产物的主要作用是",[["A","促进凝血酶的活性"],["B","防止血小板的激活"],["C","对抗血液凝固"],["D","促进纤维蛋白单体聚合"],["E","抑制纤维蛋白溶解"]],"C","在纤溶酶的作用下，纤维蛋白和纤维蛋白原可被分解为许多可溶性小肽，称为纤维蛋白降解产物，这些降解产物通常不再发生凝固，其中部分小肽还具有抗凝血作用（C对）。","","N"],["2005-N6",3,"第1节 心脏的泵血功能","每分功",2005,6,"A","","高血压患者与正常人相比，下列哪项指标明显升高",[["A","每搏输出量"],["B","射血分数"],["C","心输出量"],["D","心指数"],["E","心脏做功量"]],"E","与单纯的心输出量相比，用心脏做功量来评定心脏泵血功能将更为全面。尤其是在动脉血压高低不同的个体之间进行比较，高血压患者动脉血压升高，为克服加大的射血阻力，心肌必须增加其收缩强度才能使搏出量保持不变，因而心脏做功量将增加（E对）。由于心肌收缩加强，使搏出量保持不变，故高血压患者每搏输出量、心输出量、射血分数（搏出量占心室舒张末期容积的百分比）、心指数（单位体表面积的心输出量）等指标并无明显变化（ABCD错）。","","N"],["2005-N7",3,"第3节 血管生理","微循环的血流动力学",2005,7,"A","","在微循环中，下列哪种结构主要受局部代谢产物的调节",[["A","微动脉"],["B","微静脉"],["C","通血毛细血管"],["D","毛细血管前括约肌"],["E","真毛细血管"]],"D","微循环由微动脉、后微动脉、毛细血管前括约肌、真毛细血管、通血毛细血管（或称直捷通路）、微静脉和动-静脉吻合支等部分组成。其中后微动脉和毛细血管前括约肌（D对）主要受局部代谢产物（如CO₂、H⁺、腺苷、ATP、K⁺等）的调节（代谢性自身调节）而发生交替性血管舒缩活动。微动脉也接受局部代谢产物的调节，但微动脉主要受神经调节（微动脉是交感缩血管神经纤维分布密度最高的血管类型）和体液调节（A错）。较小的微静脉、通血毛细血管和真毛细血管几乎无血管平滑肌分布，不参与心血管活动的调节（BCE错）。较大的微静脉有血管平滑肌，主要受神经调节和体液调节（B错）。","","N"],["2005-N8",4,"第2节 肺换气和组织换气","通气_血流比值",2005,8,"A","","下列关于通气／血流比值的叙述，正确的是",[["A","指肺通气量和肺血流量的比值"],["B","人体平卧时，平均比值等于0.64"],["C","人体直立时，肺尖部的比值减小"],["D","比值增大意味着肺泡无效腔减小"],["E","比值无论增大或减小，都不利于肺换气"]],"E","通气／血流比值是指每分钟肺泡通气量和每分钟血流量的比值，而不是每分钟肺通气量和每分钟血流量的比值（A错）。人体平卧时，平均比值等于0.84（B错），该比值增大意味着通气过度，肺泡无效腔增大（D错），该比值减小则意味着通气不足，血流相对过度，犹如发生了功能性动-静脉短路，所以，通气／血流比值无论增大或减小都不利于肺换气（E对）。人体直立时，受重力影响，从肺底部到肺尖部，肺泡通气量和肺毛细血管血流量都逐渐减少，但血流量的减少更为显著，所以肺尖部的通气/血流比值增大（C错）。","","N"],["2005-N9",4,"第3节 气体在血液中的运输","影响氧解离曲线的因素",2005,9,"A","","下列哪项能使氧解离曲线发生右移",[["A","糖酵解加强"],["B","温度降低"],["C","pH升高"],["D","CO₂分压降低"],["E","CO中毒"]],"A","氧解离曲线的位置发生偏移意味着Hb对O₂的亲和力发生了变化。通常用P₅₀来表示Hb对O₂的亲和力。P₅₀是使Hb饱和度达50%时的PO₂，P₅₀增大时氧解离曲线右移，表示Hb对O₂的亲和力降低，需要更高的PO₂才能使Hb氧饱和度达到50%；P₅₀降低时氧解离曲线左移，则表示Hb对O₂的亲和力增加，达50%Hb氧饱和度所需要的PO₂降低。使氧解离曲线右移的常见因素包括PCO₂↑、pH↓、温度↑、2，3-DPG↑等，使氧解离曲线左移的常见因素包括PCO₂↓、pH↑、温度↓、2，3-DPG↓等。糖酵解加强时，2，3-DPG生成增多，使氧解离曲线发生右移（A对）。","","N"],["2005-N10",5,"第3节 胃内消化","消化期的胃液分泌",2005,10,"A","","下列关于胃液分泌调节的叙述，正确的是",[["A","头期调节属于纯神经反射"],["B","胃期调节包括神经长、短反射和体液调节"],["C","迷走神经引起的胃泌素释放可被阿托品阻断"],["D","肠期调节约占进食分泌总量的30％以上"],["E","三个时期的分泌是顺序发生，互不重叠的"]],"B","头期胃液分泌以神经调节为主，但并非单纯神经调节，如存在神经-体液调节：头期神经调节的传出神经为迷走神经，迷走神经节后纤维释放铃蟾素（蛙皮素），引起促胃液素的释放，进而促进壁细胞分泌胃酸（A错）。胃期调节包括神经长反射（迷走-迷走反射）、神经短反射（壁内神经丛短反射）和体液调节（促胃液素释放）（B对）。支配胃黏膜壁细胞的迷走神经节后纤维释放的是ACh，可被阿托品阻断；支配G细胞引起胃泌素释放的迷走神经节后纤维释放的是铃蟾素（蛙皮素），不能被阿托品阻断（C错）。肠期分泌的胃液量只占总分泌量的10%（头期30%，胃期60%）（D错），肠期分泌的胃液量不仅量少，酸度和酶的含量也不高，这可能与酸、脂肪、高张溶液进入小肠后对胃液分泌的抑制作用有关。头期、胃期和肠期三个时期几乎是同时开始，互相重叠的（E错）。","","N"],["2005-N11",5,"第4节 小肠内消化","促胰液素",2005,11,"A","","胰泌素引起胰腺分泌胰液的特点是",[["A","H₂O和HCO₃⁻多，酶少"],["B","H₂O和HCO₃⁻少，酶多"],["C","H₂O多，HCO₃⁻和酶少"],["D","H₂O、HCO₃⁻和酶都少"],["E","H₂O、HCO₃⁻和酶都多"]],"A","胰液分泌受神经调节和体液调节的双重控制，以体液调节为主。体液调节主要由促胰液素和缩胆囊素介导，促胰液素主要作用于胰腺小导管上皮细胞，使其分泌大量的水和HCO₃⁻，而酶的含量则较少（A对），缩胆囊素主要作用于胰腺的腺泡细胞使其分泌大量的酶，而水和碳酸氢盐的量却很少。","","N"],["2005-N12",6,"第1节 能量代谢","能量的利用",2005,12,"A","","机体各种功能活动所消耗的能量中，最终不能转化为体热的是",[["A","心脏泵血并推动血液流动"],["B","细胞合成各种功能蛋白质"],["C","兴奋在神经纤维上传导"],["D","肌肉收缩对外界物体做功"],["E","内、外分泌腺体的分泌活动"]],"D","机体的能量代谢符合能量守恒定律，机体所消耗的化学能等于产生的热能以及对外所做功之和。机体进行各种生理活动，如肌肉的收缩和舒张，合成组织细胞成分及生物活性物质，物质的跨膜主动转运，产生生物电活动，腺体的分泌和递质的释放等都需要消耗ATP或GTP，储存在其中的化学能最终都转变为热能释放。细胞合成各种蛋白质时需要消耗ATP来转运各种氨基酸，所消耗的能量最终也转变为热能。兴奋在神经纤维上的传导需要消耗ATP来实现离子的跨膜转运，ATP中所含的化学能最终转变为热能释放（C错）。心脏泵血时用于推动血液流动所消耗的大部分能量转变为血液的势能和动能，由于血液与血管壁以及血液内部分子之间的相互摩擦，最终这部分能量转变为热能释放（A错）。肌肉本身的收缩和舒张所消耗的能量最终转变为热能，但是肌肉对外界做功时有部分能量转变成为了外界物体的势能或者是动能，这一部分能量并不转化为热能（D对）。","","N"],["2005-N13",6,"第2节 体温及其调节","体温调节过程——体温调定点学说",2005,13,"A","","发热开始前，先出现寒战的原因是",[["A","身体特别虚弱"],["B","体温调节中枢功能障碍"],["C","机体过度散热"],["D","机体产热量不足"],["E","体温调定点上移"]],"E","从20世纪70年代开始，人们用体温调节的调定点学说解释机体在各种环境温度下保持体温相对稳定的机制（调定点学说详情见P224）。人的正常体温调定点为37℃，体温调节中枢按照这个设定温度进行调节活动，当体温与调定点的水平一致时，说明机体的产热量与散热量取得平衡；当体温高于调定点水平时，体温调节中枢促使机体产热活动减弱，散热活动加强；反之，当体温低于调定点水平时（体温调定点上移）（E对），促使机体产热活动加强（如寒战），散热活动减弱，体温上升（发热），直到体温回到调定点水平。","","N"],["2005-N14",7,"第3节 肾小管和集合管的物质转运功能","近端小管",2005,14,"A","","下列关于HCO₃⁻在近端小管重吸收的叙述，正确的是",[["A","人重吸收率约为67％"],["B","以HCO₃⁻的形式重吸收"],["C","与小管分泌H⁺相耦联"],["D","滞后于Cl⁻的重吸收"],["E","与Na⁺的重吸收无关"]],"C","近端小管对各种物质的重吸收过程（H⁺为分泌）十分复杂：首先各种物质均包括跨细胞途径和细胞旁途径两种重吸收方式，跨细胞途径又包括由小管液经顶端膜进入小管上皮细胞、再由小管上皮细胞经基底膜进入组织间液、最后由组织间液进入血液循环的过程，最重要的是不同物质在近端小管重吸收的方式和顺序均不一样。肾脏的核心功能是调节水盐（H₂O、Na⁺、Cl⁻）平衡和酸碱（H⁺、HCO₃⁻）平衡，H₂O、Na⁺、Cl⁻、H⁺、HCO₃⁻在近端小管跨细胞途径重吸收（H⁺为分泌）过程正是考研的重点和难点，需要作重点分析。虽然跨细胞途径重吸收包括由小管液进入小管上皮细胞、再由小管上皮细胞进入组织液、再由组织液进入血液循环的过程，但是应对考研，只需要记住由小管液进入小管上皮细胞的过程即可。H₂O、Na⁺、Cl⁻、H⁺、HCO₃⁻进入小管上皮细胞的过程可以概括为Na⁺ → H⁺ → HCO₃⁻ →Cl⁻ → H₂O，类似一个接力过程，每种物质在此过程中都发挥着各自的功能与使命：①在所有物质的重吸收过程中，处于核心地位的是Na⁺（E错），首先小管液中的Na⁺顺浓度梯度进入上皮细胞内，同时带动H⁺被分泌至小管液中（由顶端膜的Na⁺-H⁺交换体介导），即Na⁺进入上皮细胞的同时完成了把H⁺带出上皮细胞的使命；②被带出上皮细胞进入小管液的H⁺也有自己的使命，那就是将HCO₃⁻从小管液带入到上皮细胞内：进入小管液的H⁺与HCO₃⁻结合为H₂CO₃，H₂CO₃在碳酸酐酶的催化下解离成CO₂和水，CO₂以单纯扩散的方式进入上皮细胞，在上皮细胞内，CO₂和水又在碳酸酐酶的催化下形成H₂CO₃，后者又很快离解成H⁺和HCO₃⁻，就这样，HCO₃⁻与H⁺耦联（C对），以CO₂的形式（B错）完成了重吸收；③进入上皮细胞的HCO₃⁻也是有自己的使命的，那就是将Cl⁻从小管液带入到上皮细胞内：部分HCO₃⁻会通过Cl⁻-HCO₃⁻交换的方式将Cl⁻带入上皮细胞内，HCO₃⁻则再次进入小管液（进入小管液的HCO₃⁻可以CO₂的形式重新进入上皮细胞），所以HCO₃⁻是先于Cl⁻进行重吸收的（D错）；④进入上皮细胞的Na⁺、HCO₃⁻、Cl⁻有一个共同的使命，即将作为溶质将H₂O带入到上皮细胞内：上皮细胞重吸收Na⁺、HCO₃⁻、Cl⁻（还包括葡萄糖、氨基酸等其他溶质）后，小管液渗透压降低，细胞间液渗透压升高，H₂O在这一渗透压差的作用下经跨细胞和细胞旁两条途径进入细胞间液，然后进入管周毛细血管而被重吸收。","","N"],["2005-N15",7,"第3节 肾小管和集合管的物质转运功能","小管液中溶质的浓度",2005,15,"A","","糖尿病患者尿量增多的原因是",[["A","饮水过多"],["B","肾小球滤过率增高"],["C","肾小管重吸收NaCl量减少"],["D","小管液溶质浓度增高"],["E","肾交感神经紧张度降低"]],"D","糖尿病患者尿量增多的原因是渗透性利尿，即由于血糖浓度升高而使超滤液中的葡萄糖超过近端小管对糖的最大转运率，造成小管液葡萄糖浓度升高，渗透压升高，使小管内外渗透压梯度减小，从而使水和NaCl的重吸收减少，尿量增加（D对）。","","N"],["2005-N16",8,"第3节 视觉","晶状体变凸",2005,16,"A","","下列关于正常人眼调节的叙述，正确的是",[["A","视远物时需调节才能清晰成像于视网膜"],["B","晶状体变凸有助于消除球面像差和色像差"],["C","瞳孔缩小可避免强光对视网膜的有害刺激"],["D","双眼球会聚可避免复视而形成单视视觉"],["E","调节能力随年龄的增长而得到加强"]],"D","双眼球会聚可以使物像始终落在两眼视网膜的对称点上，以避免产生复视而形成单视视觉（D对）。正常人眼视远物时不需要调节（A错），而视近物时需要调节，视近物时发生的调节主要有晶状体变凸，使折光能力增强，从而使物像前移而成像于视网膜上。人眼的调节能力可用近点（即眼做充分调节时所能看到的最近的点）来表示，近点越近，人眼的调节能力越强，随着年龄的增长，近点将逐渐移远（E错）。瞳孔缩小可见于两种情况，一种是视近物时发生瞳孔近反射，另一种是视强光时发生瞳孔对光反射，前者有助于减少折光系统的球面像差和色像差（B错），后者可使视网膜不至于因光量过强而受到损害。C选项存在争议，可能因“避免”说法有些绝对，如改为“减少”似乎更为合适，本题官方给出的参考答案为D。","","N"],["2005-N17",8,"第4节 听觉","气传导(1)",2005,17,"A","","声波传入内耳最主要的途径是",[["A","颅骨→颞骨中耳蜗内淋巴"],["B","外耳道→鼓膜→听骨链→卵圆窗膜→耳蜗"],["C","外耳道→鼓膜→听骨链→圆窗膜→耳蜗"],["D","外耳道→鼓膜→鼓室空气→圆窗膜→耳蜗"],["E","外耳道→鼓膜→颞骨中耳蜗内淋巴"]],"B","声波传入内耳有两条途径，即气传导和骨传导，正常情况下以气传导为主，骨传导所起的作用甚微。气传导又包括两种：①外耳道－鼓膜－听骨链－卵圆窗膜－耳蜗，这是声波传导的主要途径（B对）；②外耳道－鼓膜－鼓室－空气－圆窗膜－耳蜗，这一途径在正常情况下不重要，仅听骨链运动障碍时才发挥一定作用，此时的听力较正常时大为下降。骨传导是指声波直接作用于颅骨，经颅骨和耳蜗壁传入耳蜗的途径。","","N"],["2005-N18",9,"第1节 神经系统功能活动的基本原理","乙酰胆碱及其受体",2005,18,"A","","在周围神经系统，毒蕈碱受体分布于",[["A","自主神经节"],["B","骨骼肌终板膜"],["C","多数副交感神经支配的效应器"],["D","多数交感神经支配的效应器"],["E","消化管壁内神经丛所有的神经元"]],"C","胆碱能受体可分成两类，毒蕈碱受体（M型受体）和烟碱受体（N型受体），毒蕈碱受体又可分为M₁～M₅五种亚型，烟碱受体则可分为N₁、N₂两种亚型。在周围神经系统，毒蕈碱受体分布于大多数副交感节后纤维（除少数释放肽类或嘌呤类递质的纤维外）支配的效应细胞（C对）、交感节后纤维支配的汗腺和骨骼肌血管的平滑肌细胞膜上，N₁型烟碱受体分布于自主神经节后神经元上（A错），N₂型烟碱受体分布于骨骼肌神经-肌肉接头处的终板膜处（B错）。除交感神经支配的汗腺和骨骼肌血管上分布的是毒蕈碱受体外（十版生理学P297），多数交感神经支配的效应器上分布的受体为肾上腺能受体（D错）。消化道壁内神经丛又称为肠神经系统，释放多种递质，包括乙酰胆碱、去甲肾上腺素、5-羟色胺、P物质、血管活性肠肽等，乙酰胆碱的毒蕈碱受体可见于消化管壁内神经丛，但并非壁内神经丛的所有神经元都分布有毒蕈碱受体（E错）。","","N"],["2005-N19",9,"第3节 神经系统对躯体运动的调控","前庭小脑",2005,19,"A","","人小脑绒球小结叶损伤后，将会出现下列哪种症状",[["A","站立不稳"],["B","四肢乏力"],["C","运动不协调"],["D","静止性震颤"],["E","意向性震颤"]],"A","小脑皮层可按原裂及后外侧裂横向分为前叶、后叶和绒球小结叶，也可根据其传入、传出纤维联系分为前庭小脑、脊髓小脑和皮层小脑。前庭小脑主要由绒球小结叶构成，接受前庭核的纤维投射，主要参与身体姿势平衡和眼外肌活动的调节。切除绒球小结叶的猴，或肿瘤压迫绒球小结叶的患者，会出现步基宽、站立不稳、步态蹒跚、容易跌倒等身体平衡失调的症状（A对）和位置性眼球震颤等眼外肌活动障碍的症状，但其随意运动的协调不受影响（C错）。静止性震颤（十版生理学P315）见于帕金森病（D错）。意向性震颤和四肢乏力（十版生理学P317）见于脊髓小脑受损（E错）。","","N"],["2005-N20",10,"第1节 内分泌与激素","激素受体介导的细胞内机制",2005,20,"A","","下列哪种激素是通过基因调节机制而发挥生物学效应",[["A","肾上腺素"],["B","心房钠尿肽"],["C","胆囊收缩素"],["D","甲状腺激素"],["E","促肾上腺皮质激素"]],"D","由胞内受体介导信号转导的激素是通过基因调节机制而发挥生物学效应的：胞内受体（核受体）为单肽链结构，都含有共同的功能区段，在与特定的激素结合后作用于DNA分子的激素反应元件，通过调节靶基因转录以及所表达的产物而发挥生物学效应。各选项所提及的激素中，只有甲状腺激素的受体为胞核受体，是通过基因调节机制而发挥生物学效应的（D对）。","","N"],["2005-N21",10,"第5节 肾上腺内分泌","反馈调节",2005,21,"A","","患者长期大量使用糖皮质激素时，下列哪种变化正确",[["A","血中CRH增加"],["B","血中ACTH减少"],["C","血中TSH增加"],["D","血中GH减少"],["E","血中PRL增加"]],"B","患者长期大量使用糖皮质激素时，可通过负反馈机制抑制CRH与ACTH的合成和分泌，使血中CRH和ACTH均减少（B对A错）。除此之外，糖皮质激素对腺垂体激素（GH、TSH、ACTH、FSH、LH、PRL）均有抑制作用（D对CE错）。故本题的答案应为BD均正确，但参考答案仅为B。","","N"],["2005-N22",11,"第2节 女性生殖功能及其调节","雌激素、孕激素的作用",2005,22,"A","","下列关于孕激素作用的叙述，正确的是",[["A","使子宫内膜发生增生期变化"],["B","使子宫内膜发生分泌期变化"],["C","降低血浆低密度脂蛋白含量"],["D","促使并维持女性第二性征的出现"],["E","促进子宫收缩"]],"B","孕激素可以使子宫内膜发生分泌期变化（B对），使子宫内膜腺体、血管增生，为受精卵的着床提供适宜环境。使子宫内膜发生增生期变化（A错）、降低血浆低密度脂蛋白含量（C错）、促使并维持女性第二性征的出现（D错）均为雌激素的生理作用。孕激素能够使子宫肌兴奋性降低，抑制其收缩（E错），防止妊娠期胚胎排出。","","N"],["2005-N107",3,"第3节 血管生理","影响动脉血压的因素",2005,107,"B","","一般情况下，动脉收缩压主要反映",[["A","心脏搏出量"],["B","心率"],["C","外周阻力"],["D","大动脉顺应性"],["E","循环血量"]],"A","心脏搏出量的改变主要影响收缩压，收缩压的高低主要反映心脏搏出量的多少（A对）。","","N"],["2005-N108",3,"第3节 血管生理","影响动脉血压的因素",2005,108,"B","","一般情况下，动脉舒张压主要反映",[["A","心脏搏出量"],["B","心率"],["C","外周阻力"],["D","大动脉顺应性"],["E","循环血量"]],"C","外周阻力的改变主要影响舒张压，舒张压的高低主要反映外周阻力的大小（C对）。","","N"],["2005-N109",9,"第2节 神经系统的感觉分析功能","感觉投射系统",2005,109,"B","","特异感觉投射系统的主要功能是",[["A","参与睡眠形成机制"],["B","参与学习与记忆机制"],["C","维持和改变大脑皮层的兴奋状态"],["D","协调各种感觉在皮层和皮层下结构间的联系"],["E","引起特定感觉并激活大脑皮层的传出活动"]],"E","丘脑是感觉传入通路的重要中继站，根据丘脑各部分向大脑皮层投射特征的不同，将感觉投射系统分为特异投射系统和非特异投射系统。特异投射系统是第一类细胞群丘脑特异感觉接替核及其投射至大脑皮层的神经通路，其主要功能是投射到大脑皮层特定区域，引起特定感觉并激发大脑皮层发出传出冲动（E对）。丘脑的第二类细胞群联络核在结构上大部分也可以投射到大脑皮层的特定区域，因而也归于特异投射系统，联络核的主要功能是协调各种感觉在皮质与皮质下结构间的联系，但这不是特异投射系统的主要功能（D错）。非特异投射系统是指丘脑第三类细胞群非特异投射核及其投射至大脑皮层的神经通路，其主要功能是维持和改变大脑皮质的兴奋状态（C错）。睡眠形成、学习与记忆均与特异感觉投射系统无关（AB错）。","","N"],["2005-N110",9,"第2节 神经系统的感觉分析功能","感觉投射系统",2005,110,"B","","非特异感觉投射系统的主要功能是",[["A","参与睡眠形成机制"],["B","参与学习与记忆机制"],["C","维持和改变大脑皮层的兴奋状态"],["D","协调各种感觉在皮层和皮层下结构间的联系"],["E","引起特定感觉并激发大脑皮层的传出活动"]],"C","丘脑是感觉传入通路的重要中继站，根据丘脑各部分向大脑皮层投射特征的不同，将感觉投射系统分为特异投射系统和非特异投射系统。特异投射系统是丘脑的第一类细胞群丘脑特异感觉接替核及其投射至大脑皮层的神经通路，其主要功能是投射到大脑皮层特定区域，引起特定感觉并激发大脑皮层发出传出冲动（E错）。能够协调各种感觉在皮质与皮质下结构间的联系的是丘脑的第二类细胞群联络核，由于联络核在结构上大部分也可以投射到大脑皮层的特定区域，因而也属于特异投射系统（D错）。非特异投射系统是指丘脑第三类细胞群非特异投射核及其投射至大脑皮层的神经通路，其主要功能是维持和改变大脑皮质的兴奋状态（C对）。睡眠形成、学习与记忆均与非特异感觉投射系统无关（AB错）。","","N"],["2005-N129",4,"第1节 肺通气","胸膜腔内压",2005,129,"X","","胸膜腔内负压有助于",[["A","保持胸膜腔的密闭"],["B","肺的扩张和实现肺通气"],["C","维持大、小肺泡的稳定性"],["D","胸腔大静脉血液和淋巴回流"]],"BD","胸膜腔的密闭有助于保持胸膜腔内负压，而不是胸膜腔内负压有助于保持胸膜腔的密闭（因果关系搞反了）（A错）。维持大、小肺泡的稳定性是肺表面活性物质的作用，与胸膜腔负压无关（C错）。","","N"],["2005-N130",5,"第4节 小肠内消化","小肠的运动形式",2005,130,"X","","下列关于小肠分节运动的叙述，正确的是",[["A","以纵行肌为主的运动"],["B","小肠上部频率较下部低"],["C","有利于营养成分的吸收"],["D","有利于肠壁内血液和淋巴回流"]],"CD","小肠分节运动是一种以环形肌（A错）为主的节律性收缩和舒张运动，由上至下，小肠的分节运动存在频率梯度，小肠上部频率较下部高（B错），分节运动的意义在于：①使食糜与消化液充分混合，有利于化学性消化；②增加食糜与小肠黏膜的接触，并不断挤压肠壁以促进血液和淋巴回流（D对），有助于吸收（C对）；③分节运动由上而下的频率梯度对食糜有一定推进作用。","","N"],["2005-N131",7,"第2节 肾小球的滤过功能","影响肾小球滤过的因素",2005,131,"X","","下列哪些生理或病理因素可影响肾小球超滤液的生成量",[["A","剧烈运动和交感强烈兴奋"],["B","肾盂或输尿管结石引起尿路梗阻"],["C","糖尿病伴有尿量增多"],["D","高血压引起小动脉硬化"]],"ABD","剧烈运动和交感神经强烈兴奋时，肾入球小动脉收缩，肾血流量和肾血浆流量减少，滤过平衡点移向入球小动脉端，即有效滤过面积减小，使肾小球滤过率降低，导致超滤液生成减少（A对）。肾盂或输尿管结石引起尿路阻塞时，囊内压升高，超滤的阻力增加，使有效滤过压减低，肾小球滤过率降低，导致超滤液生成减少（B对）。糖尿病时，由于尿中过量的糖不能被全部重吸收，多余的葡萄糖残留在小管内，导致小管液渗透压升高，引起渗透性利尿，导致尿量增多，与超滤液的生成量无关，但糖尿病发展为糖尿病肾病时，肾小球滤过率升高，也会影响超滤液的生成，C选项略存在争议。高血压引起小动脉硬化后，肾血流量和肾血浆流量减少，有效滤过面积减小，肾小球滤过率降低，导致超滤液生成减少（D对）。","","N"],["2005-N132",10,"第3节 甲状腺内分泌","调节新陈代谢",2005,132,"X","","生理状态下，下列哪些激素可促进蛋白质合成",[["A","糖皮质激素"],["B","生长激素"],["C","胰岛素"],["D","甲状腺激素"]],"BCD","生长激素（GH）、甲状腺激素（TH）、糖皮质激素（GC）均为既可促进蛋白质合成，又可促进蛋白质分解的激素：生长激素既可促进蛋白质的合成代谢，又可促进蛋白质的分解代谢，总体来说以促进合成代谢为主，特别是促进肝外组织蛋白质的合成（B对）；甲状腺激素既可促进蛋白质合成代谢，也可促进蛋白质分解代谢，甲状腺激素分泌适量（生理状态下），以促进合成代谢为主（D对），甲状腺激素分泌过量（甲亢时），以促进分解代谢为主；糖皮质激素既可促进蛋白质合成代谢，也可促进蛋白质分解代谢，糖皮质激素对肝内组织以促进合成代谢为主，对肝外组织以促进分解代谢为主，总体来说以促进分解代谢为主（A错）。胰岛素则是全面促进物质合成代谢的关键激素，当机体营养物质（糖、脂肪、蛋白质）供应充足时，胰岛素反应性分泌，可有效促进组织细胞利用这些营养物质，增强合成代谢，如促进肝糖原和肌糖原的合成与储存、促进脂肪的合成与储存、促进蛋白质的合成与储存等（C对）。","","N"],["2006-N1",0,"第5节 机体生理功能的调节","体液调节",2006,1,"A","","机体处于寒冷环境时，甲状腺激素分泌增多属于",[["A","神经调节"],["B","自身调节"],["C","局部调节"],["D","体液调节"],["E","神经-体液调节"]],"E","机体处于寒冷环境时，外周温度感受器兴奋，信息传递至中枢神经系统引起交感神经兴奋，进而促进下丘脑释放促甲状腺激素释放激素，经“下丘脑-垂体-甲状腺”轴，最终促进甲状腺激素的分泌，在此过程中，体液调节是神经调节的一个传出环节，为典型的神经-体液调节过程（E对）。","","N"],["2006-N2",1,"第1节 细胞膜的物质转运功能","单纯扩散",2006,2,"A","","O₂和NH₃在体内跨细胞膜转运属于",[["A","单纯扩散"],["B","易化扩散"],["C","胞吐或胞吞"],["D","原发性主动转运"],["E","继发性主动转运"]],"A","脂溶性（非极性）分子，如O₂、CO₂、N₂、NH₃、类固醇激素等，能够以单纯扩散的方式从膜一侧通过到另一侧（A对），不带电荷极性共价键的小分子，如乙醇、尿素、甘油等也能够通过单纯扩散进行跨膜转运。虽然利用单纯扩散进行跨膜转运的物质很多，但是到目前为止，只以气体分子为例出过考题，如1991N113X（O₂、CO₂、NH₃）、1992N103C（O₂）、2006N2A（CO₂、NH₃）和2012N1A（NH₃）。","","N"],["2006-N3",1,"第3节 细胞的电活动","细胞兴奋后兴奋性的变化",2006,3,"A","","组织细胞处于绝对不应期时，其兴奋性为",[["A","无限大"],["B","大于正常"],["C","等于正常"],["D","小于正常"],["E","零"]],"E","可兴奋细胞在发生一次兴奋后，其兴奋性将出现一系列周期性变化，依次为绝对不应期、相对不应期、超常期、低常期、正常期。绝对不应期是指在兴奋发生的最初一段时间内，无论施加多强的刺激，也不能使细胞再次兴奋的时期，“细胞在绝对不应期的兴奋性为零”这一说法不够严谨，因为绝对不应期大致相当于整个锋电位的持续时间，在锋电位升支期间，大部分Na⁺（或Ca²⁺）通道已处于激活状态，不存在再激活的问题，只有在锋电位降支期间，细胞的兴奋性才为零，细胞暂时失去兴奋性。","","N"],["2006-N4",1,"第4节 肌细胞的收缩","骨骼肌神经肌肉接头处的兴奋传递",2006,4,"A","","当神经冲动到达运动神经末梢时可引起接头前膜",[["A","Na⁺通道关闭"],["B","Ca²⁺通道开放"],["C","K⁺通道关闭"],["D","Cl⁻通道开放"],["E","Ca²⁺通道关闭"]],"B","神经-肌接头处兴奋传导的具体过程为：运动神经纤维传到末梢的动作电位激活接头前膜中的电压门控钙通道开放（B对），导致Ca²⁺内流而触发接头前膜Ca²⁺依赖性突触囊泡出胞，释放ACh至接头间隙，再由ACh激活终板膜中的N₂型ACh受体阳离子通道，产生Na⁺内流和K⁺外流（以Na⁺内流为主），导致膜电位改变，最终引起肌细胞兴奋。","","N"],["2006-N5",7,"第2节 肾小球的滤过功能","肾小球滤过率和滤过分数",2006,5,"A","","生理情况下，肾小球的滤过分数约为",[["A","10%"],["B","20%"],["C","30%"],["D","40%"],["E","50%"]],"B","肾小球滤过率与肾血浆流量的比值称为滤过分数，滤过分数的正常值为18%-20%（B对）。","","N"],["2006-N6",2,"第3节 生理性止血","凝血因子",2006,6,"A","","下列凝血因子中，最不稳定的是",[["A","因子Ⅴ"],["B","因子Ⅶ"],["C","因子Ⅹ"],["D","因子Ⅻ"],["E","因子ⅩⅢ"]],"A","凝血因子Ⅴ由内皮细胞和血小板合成，可以作为辅因子加速FⅩa对凝血酶原的激活。凝血因子Ⅴ在体内极不稳定（A对），在血清中可呈现活化状态，且容易被体内蛋白质C系统（生理性抗凝物质）灭活，因此被称为不稳定因子或易变因子。","","N"],["2006-N7",3,"第1节 心脏的泵血功能","心室舒张期",2006,7,"A","","在一个心动周期中，二尖瓣（左房室瓣）开放始于",[["A","等容收缩期初"],["B","等容收缩期末"],["C","心室射血期初"],["D","等容舒张期初"],["E","等容舒张期末"]],"E","二尖瓣即左房室瓣，二尖瓣开放始于等容舒张期末（E对）：等容舒张期期间，心室肌持续舒张，室内压急剧下降，至等容舒张期末，室内压下降到低于房内压，心房内的血液冲开二尖瓣（房室瓣）流入心室，进入快速充盈期。","","N"],["2006-N8",3,"第2节 心脏的电生理学及生理特性","心室肌细胞动作电位",2006,8,"A","","下列关于心室肌细胞钠通道的叙述，错误的是",[["A","是电压依从性的"],["B","激活和失活的速度都快"],["C","可被河豚毒阻断"],["D","除极化到-40mV时被激活"],["E","只有Na⁺可以通过"]],"D","心室肌细胞的钠通道，介导心室肌细胞的去极化过程，是典型的电压门控通道，具有电压依从性（A对）：当心肌细胞受刺激使膜去极化达到阈电位水平（-70mV）时（D错，为本题正确答案），膜中的钠通道（INa）发生构象改变而被大量激活，Na⁺顺其浓度梯度和电位梯度快速进入细胞，使膜进一步去极化。除具有电压依从性的电压门控通道外，离子通道还包括化学门控通道和机械门控通道等，具体可参考教材十版生理学P15关于离子通道门控特性的介绍。离子通道除具有门控特性之外，还具有离子选择性，即每种通道只对一种或几种离子具有较高的通透性，而对其他离子的通透性很小或不通透，如Na⁺离子通道只允许Na⁺通过（E对），K⁺离子通道只允许K⁺通过，乙酰胆碱受体阳离子通道只允许小的阳离子如Na⁺、K⁺通过等等。","","N"],["2006-N9",3,"第4节 心血管活动的调节","心脏的神经支配",2006,9,"A","","迷走神经兴奋使心率慢，是由于窦房结细胞发生下列哪种改变所致",[["A","K⁺通透性降低"],["B","K⁺通透性增高"],["C","Ca²⁺通透性增高"],["D","Na⁺通透性增高"],["E","Cl⁻通透性增高"]],"B","迷走神经兴奋使心率变慢的生物电活动过程：迷走神经神经释放Ach，作用于心肌细胞膜的M型胆碱能受体，通过G蛋白-AC-cAMP-PKA通路，使胞内cAMP水平降低，PKA活性降低，窦房结P细胞的T型钙通道和If钠通道受到抑制，4期T型钙通道介导的Ca²⁺内流减少和If钠通道介导的Na⁺内流减少，引起4期去极化速度减慢，自律性降低，心率减慢。此外，M型胆碱能受体还可通过G蛋白直接激活一种称为乙酰胆碱依赖性钾通道（IK-ACh通道），使K⁺通透性增高（B对），K⁺外流增加，最终使最大复极电位负值增大而远离阈电位水平，进一步降低了窦房结P细胞的自律性，也能使心率减慢。","","N"],["2006-N10",4,"第1节 肺通气","弹性阻力和顺应性",2006,10,"A","","肺表面活性物质减少时可导致",[["A","肺弹性阻力减小"],["B","肺顺应性增大"],["C","肺泡表面张力降低"],["D","小肺泡内压小于大肺泡内压"],["E","肺不易扩张"]],"E","由于肺表面活性物质可以降低肺泡表面张力，肺泡表面张力又是肺弹性阻力的主要来源，故肺表面活性物质可以减少肺的弹性阻力。而弹性阻力与顺应性在数值上互为倒数，所以肺表面活性物质可以增加肺的顺应性。当肺泡表面活性物质减少时，肺的表面张力增大（C错），肺的弹性阻力增加（A错），肺的顺应性减小（B错）。根据Laplace定律（十版生理学P141），肺泡的回缩力与肺泡半径成反比，即小肺泡的回缩力大，而大肺泡的回缩力小，但肺表面活性物质的存在，大大降低了小肺泡的回缩力（小肺泡分布的肺表面活性物质密度较大，降低了表面张力），从而避免了小肺泡萎陷关闭而大肺泡过度膨胀的情况，保持了大小肺泡的稳定性。成年人患肺炎、肺血栓时，或新生儿肺泡Ⅱ型细胞尚未发育成熟时，均可因为肺表面活性物质缺乏而引起小肺泡萎陷关闭，产生肺不张（E对）。当肺泡表面活性物质减少时，小肺泡的表面张力显著增加，小肺泡内压大于大肺泡内压（D错）。","","N"],["2006-N11",5,"第3节 胃内消化","促进胃液分泌的主要因素",2006,11,"A","","下列选项中，不属于促胃液素生理作用的是",[["A","刺激胃酸分泌"],["B","促进胃运动"],["C","刺激胰酶分泌"],["D","促进唾液分泌"],["E","促进胆汁分泌"]],"D","唾液分泌的调节完全是神经调节（交感神经和副交感神经），促胃液素等体液性因素不参与唾液分泌的调节（D错，为本题正确答案）。","","N"],["2006-N12",5,"第7节 吸收","钙的吸收",2006,12,"A","","促进小肠吸收钙的主要因素是",[["A","维生素A"],["B","维生素B"],["C","维生素C"],["D","维生素D"],["E","维生素E"]],"D","维生素D的活性形式是1，25-（OH）₂VitD₃（即钙三醇），钙三醇可诱导小肠上皮细胞合成钙结合蛋白、钙通道、钙泵等钙吸收促进蛋白，从而促进钙的吸收（十版生理学P190）（D对）。维生素C能够将Fe³⁺还原为Fe²⁺而促进铁的吸收（十版生理学P190）（C错）。","","N"],["2006-N13",11,"第3节 妊娠","受精",2006,13,"A","","精子获能发生于",[["A","输精管"],["B","曲细精管"],["C","附睾"],["D","前列腺"],["E","女性生殖道"]],"E","睾丸的曲细精管产生精子（B错），新生成的精子自身没有运动能力，被输送至附睾（C错）中发育成熟，后进入输精管（A错）。发生性兴奋时，精子经输精管和尿道排出，排出过程中掺入了精囊腺分泌的精囊腺液和前列腺（D错）分泌的前列腺液，形成了精液。但由于在附睾和精液中存在一些称为去获能因子的物质，它们大多含有糖蛋白，可附着于精子表面，抑制精子的受精能力。精子进入女性生殖道后（E对），女性生殖道中存在的α-淀粉酶、β-淀粉酶、β-葡萄糖苷酸酶、胰蛋白酶及唾液酸酶，可水解由糖蛋白组成的去获能因子，去获能因子的作用被解除，精子才具有真正的受精能力，此为精子获能。","","N"],["2006-N14",6,"第1节 能量代谢","基础代谢",2006,14,"A","","下列哪种情况下，基础代谢率明显升高",[["A","肢端肥大症"],["B","甲状腺功能亢进"],["C","糖尿病"],["D","呆小症"],["E","肾上腺皮质功能亢进"]],"B","甲状腺激素是调节非战栗产热活动最重要的体液因素（十版生理学P207），甲状腺激素能使全身绝大多数组织的基础氧消耗量增加，基础代谢率升高。甲状腺功能亢进时，甲状腺激素分泌增多，基础代谢率明显升高（B对）。呆小症时，甲状腺激素减少，基础代谢率明显降低（D错）。肢端肥大症（成年后体内生长激素分泌过多引起）、糖尿病和肾上腺功能亢进时，基础代谢率均升高，但是升高程度较甲状腺功能亢进时低（ACE错）。","","N"],["2006-N15",8,"第4节 听觉","听觉的概述",2006,15,"A","","正常人耳对声音频率的最敏感范围是",[["A","20～20000Hz"],["B","100～6000Hz"],["C","1000～3000Hz"],["D","1000～10000Hz"],["E","5000～20000Hz"]],"C","人耳能感受的声音频率范围是20～20000Hz，人耳最敏感的声音频率范围是1000～3000Hz（C对），人类的语言声音频率范围是300～3000Hz。","","N"],["2006-N16",7,"第6节 清除率","测定肾小球滤过率",2006,16,"A","","可由肾小球滤过、但不能被肾小管重吸收和分泌的物质可用于测定",[["A","肾对尿的浓缩与稀释功能"],["B","肾小管重吸收功能"],["C","肾小管分泌功能"],["D","肾小球滤过率"],["E","肾血浆流量"]],"D","肾小球滤过率是指单位时间（每分钟）两肾生成的超滤液的量。如某种物质（如菊粉）可自由通过肾小球滤过膜，则该物质在肾小囊超滤液中的浓度与血浆浓度相同；同时若该物质既不被肾小管分泌，也不被重吸收，则单位时间内该物质在肾小球处滤过的量应等于从尿中排出该物质的量，因此该物质的清除率就等于肾小球滤过率。某种物质的清除率（Cx）是可以测定和计算的：测定三个数据①尿中该物质的浓度（Ux）；②每分钟尿量（V）；③血浆中该物质的浓度（Px），可计算出清除率（Cx=Ux×V/Px）。该物质的清除率即为其肾小球滤过率（D对）。","","N"],["2006-N17",10,"第1节 内分泌与激素","脂类激素",2006,17,"A","","下列哪种激素属于类固醇激素",[["A","甲状腺激素"],["B","甲状旁腺激素"],["C","抗利尿激素"],["D","肾上腺素"],["E","糖皮质激素"]],"E","激素分子结构形式多样，其化学本质直接决定激素对靶细胞的作用机制。激素一般按化学性质可分为胺类、肽与蛋白质类和脂类。胺类激素的典型代表为儿茶酚胺类激素（去甲肾上腺素、肾上腺素和多巴胺等）（D错）、甲状腺激素（A错）、褪黑素等。肽类和蛋白质类激素的典型代表包括下丘脑调节肽、腺垂体激素、甲状旁腺素（B错）、胰岛素、胃肠激素等。脂类激素的典型代表为类固醇激素，如孕酮、醛固酮、皮质醇、睾酮、雌二醇和胆钙化醇，其中皮质醇即为糖皮质激素的典型代表（E对）。","","N"],["2006-N18",10,"第1节 内分泌与激素","激素受体介导的细胞内机制",2006,18,"A","","甲状腺激素作用的主要机制是",[["A","与核受体结合，刺激mRNA生成"],["B","与膜受体结合，促进cAMP生成"],["C","与核受体结合，促进cGMP生成"],["D","与膜受体结合，抑制cAMP生成"],["E","与膜受体结合，抑制cGMP生成"]],"A","甲状腺激素为亲脂性激素，其绝大部分生物效应由靶细胞核内的甲状腺激素受体（TR）介导。甲状腺激素受体为核受体，与DNA分子的甲状腺激素反应元件片段结合，使相关基因处于沉默状态，当甲状腺激素进入核内与甲状腺激素受体结合后，可形成同二聚体或异二聚体，唤醒沉默基因的转录，刺激mRNA生成（A对），产生一系列生物学效应。","","N"],["2006-N19",9,"第1节 神经系统功能活动的基本原理","乙酰胆碱及其受体",2006,19,"A","","下列药物或毒物中，可阻断N型胆碱能受体的物质是",[["A","筒箭毒"],["B","心得安"],["C","酚妥拉明"],["D","阿托品"],["E","烟碱"]],"A","筒箭毒碱能阻断N型胆碱能受体（A对）；心得安（普萘洛尔）能阻断β肾上腺素能受体；酚妥拉明能阻断α肾上腺素能受体；阿托品能阻断M型胆碱能受体；烟碱能激动N型胆碱能受体。","","N"],["2006-N20",9,"第1节 神经系统功能活动的基本原理","中枢兴奋传播的特征",2006,20,"A","","完成一个反射所需时间的长短主要取决于",[["A","传入与传出纤维的传导速度"],["B","刺激的强弱和性质"],["C","经过中枢突触的多少"],["D","感受器的敏感性"],["E","效应器的敏感性"]],"C","反射的基本过程是兴奋经感受器、传入神经、中枢、传出神经和效应器五个反射弧环节顺序传递的过程。在此传递过程中，中枢传播时所需时间是最长的，存在“中枢延搁”：中枢传播是通过化学性突触传递，它须经历递质释放、递质在突触间隙内扩散并与后膜受体结合、以及后膜离子通道开放等多个环节，中枢传播过程中往往又不止经历一次化学性突触传递，因此兴奋在中枢传播往往需要较长的时间，这一现象称为中枢延搁，中枢传播过程中经过中枢突触的多少决定了中枢延搁时间的长短，也就决定了完成一个反射所需时间的长短（C对）。","","N"],["2006-N21",9,"第1节 神经系统功能活动的基本原理","抑制性突触后电位",2006,21,"A","","下列关于抑制性突触后电位的叙述，正确的是",[["A","是局部去极化电位"],["B","具有“全或无”性质"],["C","是局部超极化电位"],["D","由突触前膜递质释放量减少所致"],["E","由突触后膜对钠通透性增加所致"]],"C","抑制性突触后电位（IPSP），是由抑制性中间神经元释放的抑制性递质作用于突触后膜产生的超极化电位（C对AD错）。其产生机制是突触后膜氯通道开放，Cl⁻内流（产生外向电流，造成超极化）。此外，其产生还可能和K⁺通透性增加（K⁺外流增加，造成超极化）或Na⁺、Ca²⁺的通透性减小（Na⁺、Ca²⁺内流减少，造成超极化）有关（E错）。抑制性突触后电位是局部电位，其电位幅度大小与刺激强度相关，不具有“全或无”特点（B错）。","","N"],["2006-N22",9,"第3节 神经系统对躯体运动的调控","牵张反射的感受器",2006,22,"A","","下列关于牵张反射的叙述，错误的是",[["A","肌梭是其感受器"],["B","脊髓是其基本中枢"],["C","脊髓横断后将永久消失"],["D","是维持姿势的基本反射"],["E","α和γ纤维是其传出纤维"]],"C","牵张反射是指有完整神经支配的骨骼肌在受外力牵拉伸长时引起的被牵拉的同一肌肉发生收缩的反射。它的感受器是肌梭（A对），有Ⅰa和Ⅱ类两种传入纤维，基本中枢位于脊髓（B对），传出纤维是α和γ纤维（E对），效应器是被牵拉的同一肌肉。脊髓横断后将发生脊髓休克，横断面以下的脊髓所支配的牵张反射暂时消失而进入无反应状态，但随着时间的推移以脊髓为基本中枢的牵张反射可逐渐在不同程度上恢复（C错，为本题正确答案）。牵张反射包括腱反射和肌紧张两种类型，其中肌紧张是维持身体姿势最基本的反射活动（D对）。","","N"],["2006-N107",4,"第3节 气体在血液中的运输","Hb与O₂结合的特征",2006,107,"B","","血中Hb所能结合的最大氧量是",[["A","氧分压"],["B","氧含量"],["C","氧容量"],["D","氧和Hb的亲和力"],["E","氧饱和度"]],"C","在100ml血液中，Hb所能结合的最大O₂量称为Hb氧容量（C对）。在100％O₂饱和状态下，1g Hb可结合的最大O₂量为1.39ml，正常时红细胞中含有少量不能结合O₂的高铁Hb，因此1g Hb实际结合的O₂量低于1.39ml，通常按1.34ml计算，血液中Hb浓度为15g/100ml时，Hb的氧容量为20.1ml/100ml（血液）。","","N"],["2006-N108",4,"第3节 气体在血液中的运输","Hb与O₂结合的特征",2006,108,"B","","血中Hb实际结合的氧量是",[["A","氧分压"],["B","氧含量"],["C","氧容量"],["D","氧和Hb的亲和力"],["E","氧饱和度"]],"B","在100ml血液中，Hb所能结合的最大O₂量称为Hb氧容量，而Hb实际结合的O₂量称为Hb氧含量（B对）。Hb氧含量与氧容量的百分比为Hb氧饱和度。通常情况下，血浆中溶解的O₂极少，可忽略不计，因此，Hb氧容量、Hb氧含量和Hb氧饱和度可分别视为血氧容量、血氧含量和血氧饱和度。","","N"],["2006-N109",5,"第4节 小肠内消化","促胰液素",2006,109,"B","","主要促使胰腺小导管细胞分泌大量H₂O和HCO₃⁻的是",[["A","血管活性肠肽"],["B","去甲肾上腺素"],["C","胆囊收缩素"],["D","促胃液素"],["E","促胰液素"]],"E","胰液分泌受神经调节和体液调节的双重控制，以体液调节为主，体液调节主要由促胰液素和缩胆囊素介导，促胰液素主要作用于胰腺小导管上皮细胞，使其分泌大量的水和HCO₃⁻（E对），而酶的含量则较少，缩胆囊素主要作用于胰腺的腺泡细胞使其分泌大量的酶，而水和碳酸氢盐的量却很少（C错）。促胃液素（与缩胆囊素相似）和血管活性肠肽（与促胰液素相似）对胰液分泌也有刺激作用（十版生理学P181），但均不是各自的主要功能（AD错）。去甲肾上腺素为肾上腺能纤维递质，可使胰腺血管收缩，导致胰液分泌的水源明显不足而抑制胰液分泌（十版生理学P180）（B错）。","","N"],["2006-N110",5,"第4节 小肠内消化","缩胆囊素",2006,110,"B","","主要促使胰腺腺泡细胞分泌消化酶的是",[["A","血管活性肠肽"],["B","去甲肾上腺素"],["C","胆囊收缩素"],["D","促胃液素"],["E","促胰液素"]],"C","胰液分泌受神经调节和体液调节的双重控制，以体液调节为主。体液调节主要由促胰液素和缩胆囊素介导，促胰液素主要作用于胰腺小导管上皮细胞，使其分泌大量的水和HCO₃⁻（E错），而酶的含量则较少。缩胆囊素主要作用于胰腺的腺泡细胞使其分泌大量的酶，而水和碳酸氢盐的量却很少（C对）。促胃液素（与缩胆囊素相似）和血管活性肠肽（与促胰液素相似）对胰液分泌也有刺激作用（十版生理学P181），但均不是各自的主要功能（AD错）。去甲肾上腺素为肾上腺能纤维递质，可使胰腺血管收缩，导致胰液分泌的水源明显不足而抑制胰液分泌（十版生理学P180）（B错）。","","N"],["2006-N129",1,"","",2006,129,"X","","细胞膜外表面糖链可作为",[["A","离子通道"],["B","抗原决定簇"],["C","膜受体的可识别部分"],["D","糖跨膜转运载体"]],"BC","细胞膜中的糖类主要是一些寡糖和多糖链，它们以共价键的形式与膜蛋白或膜脂质结合，生成糖蛋白或糖脂。结合于糖蛋白或糖脂上的糖链仅存在于细胞膜的外侧，通常可以作为抗原决定簇（B对）或膜受体的可识别部分（C对）。例如，霍乱毒素的受体就是一种称为GM₁的糖脂；而红细胞膜上ABO血型系统的抗原，就是由结合于糖蛋白或糖脂上的寡糖链所决定的。","","N"],["2006-N130",3,"第4节 心血管活动的调节","心脏的神经支配",2006,130,"X","","儿茶酚胺对心肌生物电活动的作用有",[["A","使慢反应动作电位0期Ca²⁺内流增快"],["B","加强自律细胞4期自动去极化速度"],["C","使复极相K⁺外流减慢"],["D","使快反应动作电位上升速度减慢"]],"AB","虽然乙酰胆碱（心迷走神经释放）可以激活Ik-ACh，使复极相K⁺外流加速，但儿茶酚胺（心交感神经释放，常常介导与乙酰胆碱相反的生理学效应）并不能使复极相K⁺外流减慢（C错）。快反应动作电位即由快钠通道（INa）介导的动作电位，儿茶酚胺对快钠通道并无生理学活性（D错）。","","N"],["2006-N131",9,"第4节 神经系统对内脏活动、本能行为和情绪的调节","副交感神经系统的功能",2006,131,"X","","副交感神经系统兴奋时可引起",[["A","心率减慢"],["B","胃肠运动减弱"],["C","瞳孔缩小"],["D","糖原分解增加"]],"AC","副交感神经系统的主要意义在于保护机体，休整恢复、促进消化、积蓄能量以及加强排泄和生殖功能等（十版生理学P322）。副交感神经兴奋时，作用于窦房结细胞M受体使心率减慢（A对）；作用于胃肠道平滑肌M受体使胃肠道平滑肌收缩，胃肠运动增强（B错），促进消化；作用于虹膜环行肌（又称瞳孔括约肌）M受体使虹膜环行肌收缩，瞳孔缩小（C对）。交感神经系统兴奋时，可通过激活β₂受体促进糖原的分解增加（D错）。","","N"],["2006-N132",10,"第6节 胰岛内分泌","激素的调节作用",2006,132,"X","","对胰岛素释放有刺激作用的激素有",[["A","促胰液素"],["B","醛固酮"],["C","胰高血糖素"],["D","抑胃肽"]],"ACD","胰岛素的分泌活动受营养物质（以血糖最为重要）、体液调节（激素调节）、神经调节等诸多因素的调节，本题考察的是激素调节。参与胰岛素分泌调节的激素很多：①胃肠激素：在胃肠激素中，促胃液素、促胰液素、缩胆囊素和抑胃肽（GIP）等均可促进胰岛素分泌（AD对）；②胰岛激素：胰岛内胰高血糖素可通过直接作用于β细胞及升高血糖间接促进胰岛素的分泌（C对），生长抑素通过旁分泌抑制β细胞分泌胰岛素，胰岛素本身通过自分泌负反馈抑制β细胞分泌胰岛素等；③其他激素：生长激素、皮质醇、甲状腺激素、GHRH、TRH、CRH、胰高血糖样肽（GLP）、VIP等均可刺激胰岛素分泌，而胰抑素、瘦素、甘丙肽、神经肽Y、C肽等则抑制胰岛素分泌。醛固酮（十版生理学P370）的主要作用是促进肾远曲小管和集合管上皮细胞重吸收Na⁺和水，排出K⁺，调节水和电解质平衡，对血糖无调节作用，不影响胰岛素的分泌和释放（B错）。","","N"],["2007-N1",0,"第5节 机体生理功能的调节","体液调节",2007,1,"A","","下列关于体液调节的叙述，错误的是",[["A","不受神经系统控制"],["B","通过特殊化学物质实现"],["C","不一定都是全身性的"],["D","反应比神经调节缓慢"]],"A","某些特殊化学物质（如激素）（B对），通过体液运送的方式对人和动物的生理活动所进行的调节，称为体液调节，体液调节可单独发挥作用，如肠期胃液分泌（十版生理学P175），食糜刺激十二指肠分泌促胃液素，进而促进胃酸分泌的过程，是典型的以体液调节为主的调节机制（神经调节在此过程中并不重要），但更多的时候，体液调节是神经调节的一个传出环节，受到神经调节的上游调控（A错，为本题正确答案），这种调节称为神经-体液调节，如交感神经兴奋时，肾上腺髓质分泌的肾上腺素和去甲肾上腺素增加；交感神经兴奋时，甲状腺分泌的甲状腺激素增加等等。体液调节可以是全身性的，如远距分泌，也可以是局部性的（C对），如旁分泌。相对于神经调节，体液调节的调节过程缓慢、持久而弥散（D对）。","","N"],["2007-N2",1,"第3节 细胞的电活动","细胞兴奋后兴奋性的变化",2007,2,"A","","与低常期相对应的动作电位时相是",[["A","锋电位升支"],["B","锋电位降支"],["C","正后电位"],["D","负后电位"]],"C","电生理学发展早期使用细胞外记录的方法对后电位命名：在细胞外记录方法中，静息电位时细胞外电位为零，发生动作电位时，位于静息电位基线之上的部分为负电位，位于静息电位基线之下的部分（超极化的部分）为正电位，故把细胞内记录到的后去极化电位称为负后电位，将后超极化电位称为正后电位（C对）。最新十版生理学教材已删除“低常期”的相关内容。","","N"],["2007-N3",1,"第3节 细胞的电活动","动作电位期间膜离子通透性的变化",2007,3,"A","","下列关于电压门控Na⁺通道与K⁺通道共同点的叙述，错误的是",[["A","都有开放状态"],["B","都有关闭状态"],["C","都有激活状态"],["D","都有失活状态"]],"D","失活状态是指通道在激活态之后对去极化刺激不再反应的状态，膜电导实验表明，钠离子在去极化过程中逐渐失活，而钾离子则不存在失活状态（D对）。","","N"],["2007-N4",2,"第3节 生理性止血","生理性止血的基本过程",2007,4,"A","","血凝块回缩的主要原因是",[["A","红细胞发生叠连而压缩"],["B","白细胞发生变形运动"],["C","血小板发生收缩"],["D","纤维蛋白发生收缩"]],"C","血小板的收缩能力与其收缩蛋白有关，在血小板内存在类似肌肉的收缩蛋白系统（C对），包括肌动蛋白（血小板微丝）、肌球蛋白等等，血凝块中的血小板收缩，血凝块回缩，挤出其中的血清，使血凝块更加坚实，牢固封住血管的破口。","","N"],["2007-N5",3,"第1节 心脏的泵血功能","心肌收缩能力",2007,5,"A","","心肌通过等长调节来调节心脏的泵血功能，其主要原因是",[["A","心肌收缩能力增强"],["B","肌节的初长度增加"],["C","横桥联结的数目增多"],["D","心室舒张末期容积增大"]],"A","等长调节是指肌长度保持不变，但是收缩能力增加的调节方式（A对）。儿茶酚胺（去甲肾上腺素和肾上腺素）、钙增敏剂（如茶碱）、甲状腺激素等均可通过各种机制增强心肌的收缩能力，进行等长调节。与等长调节相对应的调节方式是异长调节，异长调节是指通过改变心肌细胞初长度而影响心肌收缩力的调节方式，肌节的初长度增加、心室舒张末期容积增大均涉及心肌细胞初长度的改变，为异长调节的原因（BD错）。心肌细胞初长度的改变本质上改变的是粗细肌丝间横桥联结的数目，故粗细肌丝间横桥联结的数目也为异长调节的原因（C错）。","","N"],["2007-N6",3,"第2节 心脏的电生理学及生理特性","心肌细胞兴奋性的周期性变化",2007,6,"A","","心肌不会产生强直收缩的原因是",[["A","它是功能上的合胞体"],["B","有效不应期特别长"],["C","具有自动节律性"],["D","呈“全或无”收缩"]],"B","当肌肉接受一连串彼此间隔时间很短的连续兴奋冲动时，由于各个刺激间的时间间隔很短，后一个刺激都落在由前一刺激所引起的收缩尚未结束之前，就又引起下一次收缩，称强直收缩。强直收缩包括完全强直收缩和不完全强直收缩两种类型，当刺激频率比较高时，后一刺激引起的收缩落在前一收缩的收缩期内，肌肉将始终保持收缩状态，这种现象称为完全强直收缩。当刺激频率比较低时，后一刺激引起的收缩落在前一收缩的舒张期内，肌肉在收缩后有过短暂的舒张，但还未恢复到正常的舒张状况又进入下一次收缩，这种现象称为不完全强直收缩。骨骼肌细胞既可以产生完全强直收缩，也可以产生不完全强直收缩，心肌细胞由于有效不应期特别长（B对），一直延续到心肌收缩活动的舒张早期，因此不会发生完全强直收缩，但可能发生不完全强直收缩，故本题改为“心肌不会产生完全强直收缩的原因”更严谨一些。","","N"],["2007-N7",3,"第4节 心血管活动的调节","肾上腺素和去甲肾上腺素",2007,7,"A","","下列选项中，肾上腺素不具有的作用是",[["A","使心肌收缩力增强"],["B","使心率加快"],["C","使内脏和皮肤血管收缩"],["D","使骨骼肌血管收缩"]],"D","肾上腺素可与α和β（包括β₁和β₂）两类受体结合。在心脏，肾上腺素与β₁受体结合后，可使心肌收缩能力增强（A对）、心率加快（B对），产生正性变力和正性变时作用。在血管，肾上腺素的作用取决于血管平滑肌上α和β₂受体的分布情况：在皮肤、肾、胃肠、血管平滑肌上α受体在数量上占优势，肾上腺素能使这些器官的血管收缩。在骨骼肌和肝的血管上β₂受体占优势（但也分布有α受体），小剂量的肾上腺素常以兴奋β₂受体的效应为主，引起血管舒张，而大剂量时则因α受体也兴奋，故引起血管收缩。该题的正确答案给的是D，由于大剂量肾上腺素能够使骨骼肌血管收缩，因此该题的答案并不严谨。","","N"],["2007-N8",6,"第2节 体温及其调节","出汗",2007,8,"A","","下列关于汗液的叙述，错误的是",[["A","主要成分为水分"],["B","渗透压高于血浆"],["C","Na⁺浓度受醛固酮调节"],["D","由汗腺细胞主动分泌"]],"B","汗液是由汗腺细胞主动分泌的，其99%的成分是水分，刚分泌出来的汗液渗透压与血液是相等的，但在流经汗腺管腔时，在醛固酮的作用下，汗液中的Na⁺和Cl⁻被重吸收，最后排出的汗液是低渗的（B错，为本题正确答案）。","","N"],["2007-N9",4,"第3节 气体在血液中的运输","影响氧解离曲线的因素",2007,9,"A","","下列因素中，能引起氧解离曲线右移的是",[["A","CO₂分压降低"],["B","pH值降低"],["C","2，3-DPG降低"],["D","温度降低"]],"B","氧解离曲线的位置发生偏移意味着Hb对O₂的亲和力发生了变化。通常用P₅₀来表示Hb对O₂的亲和力。P₅₀是使Hb饱和度达50%时的PO₂，P₅₀增大时氧解离曲线右移，表示Hb对O₂的亲和力降低，需要更高的PO₂才能使Hb氧饱和度达到50%；P₅₀降低时氧解离曲线左移，则表示Hb对O₂的亲和力增加，达50%Hb氧饱和度所需要的PO₂降低。使氧解离曲线右移的常见因素包括PCO₂↑（A错）、Hb对O₂的亲和力发生了变化。通常用P₅₀来表示Hb对O₂的亲和力。P₅₀是使Hb饱和度达50%时的PO₂，P₅₀增大时氧解离曲线右移，表示Hb对O₂的亲和力降低，需要更高的PO₂才能使Hb氧饱和度达到50%；P₅₀降低时氧解离曲线左移，则表示Hb对O₂的亲和力增加，达50%Hb氧饱和度所需要的PO₂降低。使氧解离曲线右移的常见因素包括PCO₂↑（A错）、pH↓（B对）、温度↑（D错）、2，3-DPG↑（C错）等，使氧解离曲线左移的常见因素包括PCO₂↓、pH↑、温度↓、2，3-DPG↓等。","","N"],["2007-N10",4,"第2节 肺换气和组织换气","气体的分子量和溶解度",2007,10,"A","","CO₂通过呼吸膜的速度比O₂快的主要原因是",[["A","原理为易化扩散"],["B","分压差比O₂大"],["C","分子量比O₂大"],["D","在血中溶解度比O₂大"]],"D","气体经呼吸膜扩散的速度与扩散系数成正比，扩散系数=气体溶解度/气体分子量的平方根，CO₂在血浆中的溶解度（51.5）约为O₂的（2.14）24倍，CO₂的分子量（44）略大于O₂的分子量（32），经计算CO₂的扩散系数约为O₂的20倍，故CO₂通过呼吸膜扩散的速度比 O₂快的主要原因是CO₂在血中溶解度较大（D对）。","","N"],["2007-N11",5,"第3节 胃内消化","促进胃液分泌的主要因素",2007,11,"A","","下列选项中，不能引起促胃液素分泌的是",[["A","HCl灌注刺激幽门部黏膜"],["B","肉汤灌注刺激幽门部黏膜"],["C","扩张刺激幽门部黏膜"],["D","刺激支配幽门部迷走神经"]],"A","促胃液素（七版生理学称胃泌素）是由胃窦部（即幽门部）及十二指肠部的G细胞分泌的一种肽类激素。肉汤灌注（通过化学感受器和机械感受器）及扩张（通过机械感受器）刺激幽门部黏膜，通过壁内神经丛短反射及迷走-迷走神经长反射作用于G细胞，引起促胃液素分泌（BCD错）。促胃液素作用比较广泛，但最主要的作用是促进HCl分泌，HCl灌注刺激幽门部黏膜时，可通过负反馈机制抑制幽门部黏膜G细胞，使促胃液素分泌减少（A对）。","","N"],["2007-N12",5,"第4节 小肠内消化","胆汁的性质和成分",2007,12,"A","","胆汁中有利胆作用的成分是",[["A","胆色素"],["B","胆固醇"],["C","卵磷脂"],["D","胆盐"]],"D","胆色素是人体血红素等铁卟啉化合物的主要分解代谢产物，包括胆绿素、胆红素、胆素原、胆素等（十版生物化学与分子生物学P474），胆色素的种类和浓度决定了胆汁的颜色，但无利胆作用（A错）。胆汁中的卵磷脂和胆固醇等均可作为乳化剂（十版生理学P182），降低脂肪的表面张力，促进脂肪的分解消化，但是两者没有利胆的作用（BC错）。","","N"],["2007-N13",5,"第7节 吸收","糖的吸收",2007,13,"A","","下列关于糖类在小肠内吸收的叙述，错误的是",[["A","与Na⁺的吸收相耦联"],["B","需要载体蛋白参与"],["C","单糖的吸收是耗能的主动过程"],["D","果糖的吸收速率快于半乳糖"]],"D","葡萄糖在小肠黏膜上皮的吸收和在近端肾小管上皮的重吸收都是通过Na⁺-葡萄糖同向转运体实现的（AB对），该过程属于继发性主动转运，是需要消耗能量的（C对），而果糖的吸收机制与葡萄糖有所不同，它通过顶端膜上的非Na⁺依赖性转运体运入细胞，是一种不耗能的被动的过程，因此AC选项不够严谨。果糖的吸收速率是慢于半乳糖的（D错，为本题正确答案），半乳糖、果糖和葡萄糖一样，均为六个碳原子的己糖，己糖吸收速率的记忆技巧：半（半乳糖）个葡萄（葡萄糖），一个苹果（果糖），一个甘蓝（甘露糖），体积越小的吸收速率越快。","","N"],["2007-N14",7,"第6节 清除率","测定肾血浆流量、滤过分数和肾血流量",2007,14,"A","","如果某物质在肾动脉中有一定浓度，而在肾静脉中为零，其血浆清除率",[["A","等于零"],["B","等于肾小球滤过率"],["C","等于每分钟肾血浆流量"],["D","等于每分钟肾血流量"]],"C","两肾在单位时间（一般为每分钟）内能将一定毫升血浆中所含的某种物质完全清除，这个能完全清除某物质的血浆毫升数就称为该物质的血浆清除率。由血浆清除率的定义可知，具体计算某种物质（X）的血浆清除率（Cx），需要测定三个数据：①尿中该物质的浓度（Ux）；②每分钟尿量（V）；③血浆中该物质的浓度（Px）。由于尿中的物质均来自血浆，所以Ux×V=Cx×Px，如果某物质在肾动脉中有一定浓度，而在肾静脉中为零，则表示血浆中该物质经肾小球滤过和肾小管、集合管转运后，被全部从血浆清除，因此该物质在尿中的排出量（Ux×V）应等于每分钟肾血浆流量（RPF）与血浆中该物质浓度的乘积，即Ux×V=RPF×Px，此时Cx=RPF，即该物质的血浆清除率等于每分钟肾血浆流量（C对）。","","N"],["2007-N15",7,"第1节 肾的功能解剖和肾血流量","肾血流量的神经和体液调节",2007,15,"A","","剧烈运动使尿量减少的主要原因是",[["A","肾小球毛细血管血压增高"],["B","抗利尿激素分泌增多"],["C","肾小动脉收缩，肾血流量减少"],["D","醛固酮分泌增多"]],"C","剧烈运动时，交感神经兴奋，引起肾入球小动脉强烈收缩，肾血流量减少（C对），肾小球毛细血管血压下降（A错），肾小球滤过率降低，尿量生成减少。虽然交感神经兴奋可引起抗利尿激素分泌增多（通过血管紧张素Ⅱ的间接刺激作用等）和醛固酮分泌增多，但均不是尿量减少的主要原因。","","N"],["2007-N16",7,"第5节 尿生成的调节","血浆晶体渗透压",2007,16,"A","","下列因素中，刺激抗利尿激素分泌最强的是",[["A","循环血量减少"],["B","血浆晶体渗透压增高"],["C","血浆胶体渗透压增高"],["D","饮大量清水"]],"B","抗利尿激素又称血管升压素，其合成和分泌受多种因素调节：①体液渗透压增高是最重要的刺激因素，由于晶体渗透压是血浆渗透压的主要组成部分，因此血浆晶体渗透压增高是刺激抗利尿激素分泌的最强因素（B对CD错）；②循环血量减少时，经心肺感受器和迷走神经作用也能刺激抗利尿激素分泌，但相对于血浆晶体渗透压升高来说，是次要因素（A错）。八年制三版生理学P381指出在血容量明显减少的情况下，循环血量的调节作用超过晶体渗透压的调节作用。本题答案存在争议。","","N"],["2007-N17",8,"第3节 视觉","远视",2007,17,"A","","视远物和近物都需要眼进行调节的折光异常是",[["A","近视"],["B","远视"],["C","散光"],["D","老视"]],"B","远视眼是由于眼球的前后径过短或折光系统的折光能力过弱，使来自远物的平行光线聚集在视网膜后方，不能清晰地成像在视网膜上所致。远视眼视远物时，来自远物的光线是平行光线，成像在视网膜后方，需要经过调节使成像前移至视网膜上；视近物时，来自近物的光线是成辐射状态进入眼球的，成像后移至视网膜后方更远的地方，需做更大程度的调节才能使成像前移至视网膜上。因此，远视时视远物和近物均需要经过调节（B对）。近视眼是由于眼球的前后径过长或折光系统的折光能力过强，使来自远物的平行光线聚集在视网膜前方，不能清晰地成像在视网膜上所致，近视眼视近物时，落在视网膜前方的成像后移，在特定距离时可正好落在视网膜上，此时不需要作调节就能清晰成像（A错）。散光眼是由于折光曲面率异常，平行光线经角膜的表面不能形成焦点所致，视远物和近物都不清楚，与调节无关（C错）。老视眼视近物时调节能力下降，但视远物时不需要调节（D错）。","","N"],["2007-N18",10,"第2节 下丘脑-垂体及松果体内分泌","调节新陈代谢",2007,18,"A","","下列关于生长激素功能的叙述，错误的是",[["A","加速蛋白质的合成"],["B","促进脂肪的合成"],["C","促进生长发育"],["D","升高血糖水平"]],"B","生长激素的主要功能是促进生长发育，尤其对骨骼、肌肉和内脏器官的生长发育有促进作用（C对）。生长激素也能调节糖、脂肪、蛋白质等物质代谢：①抑制外周组织摄取和利用葡萄糖，减少葡萄糖消耗，升高血糖水平（D对）；②激活激素敏感的脂肪酶，促进脂肪分解（B错，为本题正确答案），增强脂肪酸氧化，提供能量；③促进蛋白质代谢，总效应是合成大于分解，特别是促进肝外组织合成蛋白质（A对）。","","N"],["2007-N19",9,"第1节 神经系统功能活动的基本原理","乙酰胆碱及其受体",2007,19,"A","","支配小汗腺的自主神经和其节后纤维末梢释放的递质分别是",[["A","交感神经，乙酰胆碱"],["B","副交感神经，乙酰胆碱"],["C","副交感神经，肽类递质"],["D","交感神经，去甲肾上腺素"]],"A","人体皮肤上分布有两种汗腺，即大汗腺和小汗腺。大汗腺局限于腋窝和阴部等处，开口于毛根附近，从青春期开始活动，可能和性功能有关，而与体温调节反应无关。小汗腺可见于全身皮肤，小汗腺与体温调节或机体应激反应有关。与体温调节有关的是温热性出汗，当机体接受温热性刺激时，中枢通过支配汗腺的交感胆碱能纤维（A对）使全身小汗腺分泌汗液。与机体应激反应有关的称为精神性发汗，当精神紧张或情绪激动时，中枢通过支配汗腺的交感肾上腺素能纤维（D对）引起小汗腺分泌汗液。故本题的答案应为AD，原参考答案为A。","","N"],["2007-N20",9,"第3节 神经系统对躯体运动的调控","牵张反射的感受器",2007,20,"A","","γ运动神经元在牵张反射中的作用是",[["A","直接诱发梭外肌收缩"],["B","直接发动牵张反射"],["C","使肌梭感受器处于敏感状态"],["D","引起腱器官兴奋"]],"C","脊髓灰质前角中存在α、β和γ三类运动神经元。α运动神经元是躯体运动反射的最后公路，诱发梭外肌收缩、发动牵张反射的都是α运动神经元（AB错）；γ运动神经元的作用是调节肌梭对牵拉刺激的敏感性（C对）；β运动神经元发出的纤维对梭内肌和梭外肌都有支配，但其功能尚不清楚。引起腱器官兴奋是肌肉所受的牵拉外力，与γ运动神经元无关。说一下γ运动神经元使肌梭感受器处于敏感状态的机制：当肌肉受外力牵拉而使肌梭感受装置被拉长时，肌梭的传入冲动增加引起支配同一肌肉的α运动神经元兴奋，使梭外肌收缩，形成一次牵张反射，梭外肌收缩可以引起与其并联的梭内肌缩短（被动缩短，非主动收缩，后者使肌梭感受器所受的牵拉刺激增加），肌梭感受器所受的牵拉刺激减少。肌梭感受器所受的牵拉刺激减少将导致Ⅰa纤维传入冲动减少，α运动神经元兴奋减弱，传出冲动减少，梭外肌松弛，按照此调节机制，受牵拉时持续收缩的肌紧张状态将不会存在。但是肌紧张是维持身体姿势最基本的反射活动，也是随意运动的基础，肌紧张是持续存在的，这与γ运动神经元介导梭内肌收缩，使肌梭感受器处于敏感状态有关：肌梭（梭内肌）受γ运动神经元支配，当γ传出纤维受刺激，使肌梭收缩成分收缩时，其收缩强度虽不足以引起整块肌肉缩短，但可牵拉肌梭感受装置（肌梭收缩成分与感受装置为串联关系），引起Ⅰa类传入纤维放电增加。γ运动神经元兴奋性很高，可以在高位脑中枢的影响下以较高频率持续放电，在整体情况下，即使肌肉不活动，α运动神经元无放电时，有些γ运动神经元仍持续放电，当α运动神经元活动增加时，γ运动神经元放电也相应增加，这可防止当梭外肌收缩时肌梭因受牵拉刺激减少而停止放电的发生。γ运动神经元使肌梭感受器处于敏感状态，从而使肌肉呈持续缩短状态，这是牵张反射（肌紧张）发生的基础。","","N"],["2007-N21",10,"第5节 肾上腺内分泌","参与应激反应",2007,21,"A","","下列关于糖皮质激素作用的叙述，错误的是",[["A","减弱机体对有害刺激的耐受"],["B","促进蛋白质分解，抑制其合成"],["C","分泌过多时可引起脂肪重新分布"],["D","对保持血管对儿茶酚胺的正常反应有重要作用"]],"A","糖皮质激素的作用广泛而复杂（十版生理学P369-P371）：①糖皮质激素对体内糖、脂肪和蛋白质代谢均有明显影响：包括减少组织对糖的利用和加速肝糖异生而使血糖升高，提高四肢部分的脂肪酶活性而促进脂肪分解（但是糖皮质可升高血糖间接刺激胰岛素分泌，胰岛素又可促进脂肪合成和沉积，使体内的脂肪重新分布）（C对），抑制肝外组织细胞合成蛋白质并促进蛋白质分解（B对）等；②参加应激反应，提高机体对有害刺激的耐受能力（A错，为本题正确答案）；③对组织器官活动的影响，如通过允许作用保持血管对儿茶酚胺的正常反应（D对）等。","","N"],["2007-N22",11,"第1节 男性生殖功能及其调节","雄激素的合成、代谢和利用",2007,22,"A","","下列关于睾丸生理功能的叙述，正确的是",[["A","储存精子"],["B","促使精子成熟"],["C","输送精子"],["D","分泌雄激素"]],"D","睾丸由睾丸小叶组成，睾丸小叶内有曲细精管和间质细胞，分别起生成精子和分泌雄激素的功能（D对）。储存精子、促使精子成熟和输送精子均在附属性器官进行（ABC错）。","","N"],["2007-N107",1,"第4节 肌细胞的收缩","肌丝的分子结构",2007,107,"B","","肌丝滑行时，与横桥结合的蛋白是",[["A","肌球蛋白"],["B","肌动蛋白"],["C","肌钙蛋白"],["D","原肌球蛋白"]],"B","肌原纤维由粗肌丝和细肌丝组成，粗肌丝由肌球蛋白（又称肌凝蛋白）组成，细肌丝由肌动蛋白（又称肌纤蛋白）、原肌球蛋白（又称原肌凝蛋白）和肌钙蛋白组成。粗肌丝的肌球蛋白上有横桥结构，与细肌丝肌动蛋白（B对）的特定位点结合可引起肌丝滑行，使肌肉收缩。","","N"],["2007-N108",1,"第4节 肌细胞的收缩","肌丝的分子结构",2007,108,"B","","骨骼肌收缩过程中作为钙受体的蛋白是",[["A","肌球蛋白"],["B","肌动蛋白"],["C","肌钙蛋白"],["D","原肌球蛋白"]],"C","肌原纤维由粗肌丝和细肌丝组成，粗肌丝由肌球蛋白（又称肌凝蛋白）组成，细肌丝由肌动蛋白（又称肌纤蛋白）、原肌球蛋白（又称原肌凝蛋白）和肌钙蛋白组成。粗肌丝的肌球蛋白上有横桥结构，与细肌丝肌动蛋白的特定位点结合即可引起肌肉收缩。但是肌肉在舒张状态下，肌动蛋白的横桥结合位点被原肌球蛋白所掩盖，当胞质中的钙离子浓度升高时，钙离子与钙受体肌钙蛋白C结合（C对），使肌钙蛋白的构象发生变化，进而使与肌钙蛋白结合的原肌球蛋白发生位移，暴露出肌动蛋白的横桥结合位点，横桥与肌动蛋白结合，肌肉发生收缩。","","N"],["2007-N129",4,"第1节 肺通气","弹性阻力和顺应性",2007,129,"X","","下列关于肺表面活性物质的叙述，正确的有",[["A","防止液体渗入肺泡"],["B","保持大小肺泡的稳定性"],["C","成年人患肺炎时，可因此物减少而发生肺不张"],["D","新生儿可因缺乏此物可发生“呼吸窘迫综合征”"]],"ABCD","肺表面活性物质的主要作用是降低肺泡表面张力，降低肺泡表面张力对肺毛细血管血浆和肺组织间液可产生“抽吸”作用，防止液体渗入肺泡（A对）。根据Laplace定律（十版生理学P141），肺泡的回缩力与肺泡半径成反比，即小肺泡的回缩力大，而大肺泡的回缩力小，但肺表面活性物质的存在，降低了小肺泡的回缩力（小肺泡分布的肺表面活性物质密度较大，降低了表面张力），从而避免了小肺泡萎陷关闭而大肺泡过度膨胀的情况，保持了大小肺泡的稳定性（B对）。成年人患肺炎、肺血栓时，或新生儿肺泡Ⅱ型细胞尚未发育成熟时，均可因为肺表面活性物质缺乏而引起小肺泡萎陷关闭，产生肺不张（CD对）。","","N"],["2007-N130",3,"第4节 心血管活动的调节","心脏的神经支配",2007,130,"X","","心交感神经效应的主要机制为",[["A","增加心肌细胞膜上Ca²⁺通道的开放概率"],["B","增强自律细胞4期的内向电流"],["C","减慢心肌复极相K⁺外流"],["D","减慢肌质网钙泵对Ca²⁺的回收"]],"AB","心交感神经节后纤维释放去甲肾上腺素，作用于心肌细胞膜中的β₁肾上腺素能受体，通过G蛋白-AC-cAMP-PKA通路，使细胞内cAMP水平升高，PKA活性增高，致使心肌细胞膜中L型钙通道、窦房结P细胞中T型钙通道、纵行肌质网膜中的钙泵（间接）均被磷酸化而激活，故心肌细胞膜上Ca²⁺通道（L型钙通道）的开放概率增加（A对），自律细胞（窦房结P细胞）4期的内向电流（T型钙通道介导）增强（B对），肌质网钙泵对钙离子的回收加快（D错）。虽然心迷走神经可以使复极相K⁺外流加速（通过激活Ik-ACh），但心交感神经（常常介导与心迷走神经相反的生理学效应）并不能使复极相K⁺外流减慢（C错）。","","N"],["2007-N131",5,"第1节 消化生理概述","电生理特性",2007,131,"X","","下列关于胃肠平滑肌动作电位的叙述，正确的有",[["A","在慢波基础上发生"],["B","去极相由Ca²⁺内流引起"],["C","复极相由K⁺外流引起"],["D","幅度越高，肌肉收缩强度越大"]],"ABC","动作电位的频率越高（而非幅度越高）（D错），肌肉收缩强度越大。动作电位具有“全或无”的特性（十版生理学P32），动作电位要么不产生，一旦产生，其幅度便到达该细胞动作电位的最大值，不会随刺激强度的增强而增大，故动作电位的幅度是一定的，动作电位“幅度越高”的说法本身就是不正确的。","","N"],["2007-N132",10,"第4节 甲状旁腺、维生素D与甲状腺C细胞内分泌","甲状旁腺激素的生理作用",2007,132,"X","","甲状腺手术时不慎将甲状旁腺切除后可出现",[["A","血钙过低"],["B","手足抽搐"],["C","血磷酸盐过低"],["D","呼吸困难"]],"ABD","甲状旁腺激素（PTH）由甲状旁腺合成和分泌，具有升高血钙和降低血磷的作用，甲状腺手术时不慎将甲状旁腺切除后，甲状旁腺激素分泌减少，血钙降低（A对）、血磷升高（C错）。血钙降低时，神经肌肉细胞的兴奋性增强，可引起手足抽搐（B对）和呼吸困难（D对），其形成的机制为：细胞外的钙离子水平可影响细胞膜上电压门控钠通道的激活，细胞外钙离子浓度升高，可使阈电位水平抬高，细胞的兴奋性下降，相反，当细胞外钙离子浓度降低，可使阈电位下移，细胞的兴奋性增高（十版生理学P37）；另一方面，参与肌浆内兴奋-收缩耦联的钙离子，并未因为细胞外低钙而减少，因为骨骼肌有丰富的肌浆网，肌浆网内贮存有足够的钙，肌浆网钙释放，可以迅速提高肌浆内钙浓度，引发兴奋-收缩耦联。所以血钙降低时，神经肌肉细胞的兴奋性增强，发生肌肉痉挛，导致手足抽搐和呼吸困难。","","N"],["2007-N151-J",1,"第4节 肌细胞的收缩","骨骼肌神经肌肉接头处的兴奋传递",2007,151,"A","B","下列关于骨骼肌终板电位特点的叙述，正确的是",[["A","其大小与乙酰胆碱释放量无关"],["B","不存在时间和空间总和"],["C","由Ca²⁺内流产生"],["D","只去极化，而不出现反极化"]],"D","终板电位属于局部电位，具有电紧张电位的电学特征：①终板电位不具有全或无的特征，其幅度与刺激强度相关，即其大小与乙酰胆碱释放量有关（A错）；②没有不应期，可以发生空间总和和时间总和（B错）。细胞膜内负外正的状态称为膜的极化状态，而膜内正外负的状态称为膜的反极化状态，骨骼肌静息电位在-90mV左右，终板电位幅度可达50-75mV，发生去极化，但膜电位并未超过0mV，故不出现反极化（D对）。Ca²⁺内流产生的是ACh释放，而不产生终板电位，终板电位由终板膜中的N₂型ACh受体阳离子通道介导的Na⁺内流产生（C错）。","","N"],["2007-N152-J",2,"第3节 生理性止血","生理性抗凝物质",2007,152,"A","B","肝素抗凝血的主要机制是",[["A","增强抗凝血酶Ⅲ的活性"],["B","增强纤溶酶的活性"],["C","抑制血小板聚集"],["D","抑制凝血酶原激活"]],"A","肝素首先从肝脏发现而得名，主要由肥大细胞和嗜碱性粒细胞产生，肝素具有较强的抗凝作用，但在缺乏抗凝血酶（过去曾称抗凝血酶Ⅲ）的条件下，肝素的抗凝作用很弱，肝素主要通过增强抗凝血酶的活性而间接发挥抗凝作用（A对），后者为丝氨酸蛋白酶抑制物，能与内源性凝血途径产生的凝血酶、FⅨa、FⅩa、FⅪa和FⅫa等分子活性中心的丝氨酸残基结合而抑制其活性，与肝素结合后，其抗凝作用可增强2000倍以上。但在正常情况下，循环血浆中几乎无肝素存在，抗凝血酶主要通过与内皮细胞表面的硫酸乙酰肝素结合而增强血管内皮的抗凝功能。","","N"],["2007-N153-J",4,"第2节 肺换气和组织换气","通气_血流比值",2007,153,"A","B","某人的无效腔容量为125ml，肺通气量为7500ml/min，呼吸频率为每分钟20次，其心输出量为5000ml时的通气/血流比值应为",[["A","0.8"],["B","0.9"],["C","1"],["D","1.1"]],"C","通气/血流比值=每分钟肺泡通气量/每分钟血流量，每分钟血流量（心输出量）已知为5000ml，故只需知道每分钟肺泡通气量，即可计算出通气/血流比值。每分钟肺泡通气量=（潮气量-无效腔气量）×呼吸频率=潮气量×呼吸频率-无效腔气量×呼吸频率=肺通气量-无效腔气量×呼吸频率=7500-20×125=5000ml，故通气/血流比值=5000ml/5000ml=1.0（C对）。","","N"],["2007-N154-J",6,"第1节 能量代谢","间接测热法",2007,154,"A","B","下列选项中，能引起呼吸商增大的是",[["A","长期饥饿"],["B","患糖尿病"],["C","代谢性碱中毒"],["D","肺通气过度"]],"D","呼吸商是指一定时间内机体呼出的CO₂量和吸入的O₂量的比值，糖、脂肪、蛋白质的呼吸商分别为1.00、0.71和0.80。一般情况下人进食的是混合食物，呼吸商在0.85左右，长期饥饿时，人体的能量主要来自自身蛋白质的分解，故呼吸商接近0.80（A错）。糖尿病患者，因葡萄糖的利用发生障碍，机体主要依靠脂肪代谢供能，呼吸商接近于0.71（B 错）。代谢性碱中毒时，为了维持酸碱平衡，呼出的CO₂减少，使呼吸商变小（C 错）；肺过度通气时，呼出的CO₂ 增加，呼吸商变大（D 对）。","","N"],["2007-N155-J",9,"第1节 神经系统功能活动的基本原理","乙酰胆碱及其受体",2007,155,"A","B","下列选项中，主要与毒蕈碱样作用有关的是",[["A","心脏活动加强"],["B","支气管痉挛"],["C","胃肠活动减弱"],["D","瞳孔扩大"]],"B","乙酰胆碱受体可分为毒蕈碱受体（M受体）和烟碱受体（N受体）两类，这两类受体广泛分布于中枢和周围神经系统。中枢胆碱能系统几乎参与所有的中枢神经系统功能。在外周，M受体分布于大多数副交感节后纤维支配的效应细胞、交感节后纤维支配的汗腺和骨骼肌血管的平滑肌细胞膜上。M受体激活后，通过改变细胞内第二信使的浓度，进而产生一系列自主神经效应：心脏活动受到抑制（迷走神经对心脏的负性变时变力变传导作用），支气管平滑肌（B对）、胃肠平滑肌（C错）、膀胱逼尿肌、虹膜环形肌（又称瞳孔括约肌，收缩时瞳孔缩小）（D错）收缩，消化腺、汗腺分泌增加，骨骼肌血管舒张等。","","N"],["2007-N156-J",10,"第6节 胰岛内分泌","对蛋白质代谢的作用",2007,156,"A","B","下列关于胰岛素的叙述，错误的是",[["A","促进糖的储存和利用"],["B","促进葡萄糖转变为脂肪"],["C","抑胃肽对胰岛素的分泌有调节作用"],["D","促进脂肪和蛋白质的分解和利用"]],"D","胰岛素最重要的作用就是调节糖代谢，发挥降血糖作用，降血糖是通过增加血糖的去路及减少血糖的来源实现的。增加血糖的去路包括：①促进肝脏和肌肉摄取、储存、利用葡萄糖，合成肝糖原和肌糖原（A对）；②促进脂肪的合成和储存，使葡萄糖转化为脂肪酸，储存于脂肪组织（B对）；等。减少血糖的来源包括：①抑制糖原分解有关酶的活性，阻止糖原分解；②抑制糖异生有关酶的活性，抑制糖原异生；③抑制蛋白质的分解，减少生糖氨基酸的来源，最终减少糖的来源（D错，为本题正确答案）；等。胰岛素也能调节脂肪代谢和蛋白质代谢：胰岛素可促进脂肪的合成与储存，抑制脂肪的分解和利用（D错，为本题正确答案），降低血中脂肪酸的浓度；胰岛素能促进蛋白质合成和储存，抑制蛋白质的分解（D错，为本题正确答案）。胰岛素在调节体内物质代谢等活动的同时，其分泌活动也受营养物质、神经体液等诸多因素的调节：血糖升高（最重要因素）、某些氨基酸（如赖氨酸，精氨酸）、游离脂肪酸、酮体、胃肠激素（促胃液素、促胰液素、缩胆囊素、抑胃肽等）（C对）、胰高血糖素、生长激素、皮质醇、甲状腺激素、迷走神经兴奋、GHRH、TRH、CRH、GLP、VIP等，均可促进胰岛素分泌。血糖降低、生长抑素、胰抑素、瘦素、甘丙肽、神经肽Y、C肽、交感神经兴奋等，均可抑制胰岛素分泌。","","N"],["2007-N157-J",5,"第7节 吸收","铁的吸收",2007,157,"A","B","下列关于小肠对铁吸收的叙述，错误的是",[["A","胃酸可促进铁的吸收"],["B","维生素D可促进铁的吸收"],["C","亚铁易被小肠吸收"],["D","铁的吸收量与机体需要程度有关"]],"B","食物中的铁在酸性环境中易溶解而便于吸收，故胃酸有促进铁吸收的作用（A对）。维生素D主要是促进钙的吸收而不是铁的吸收，促进铁吸收的是维生素C（B错，为本题正确答案）。食物中的铁绝大部分是高铁，不易被吸收，当它还原为亚铁时则较易被吸收（C对）。铁的吸收与机体对铁的需要程度有关，当服用相同剂量的铁后，缺铁患者可比正常人的铁吸收量高2～5倍（D对）。","","N"],["2007-N158-J",8,"第1节 感觉概述","感受器的适应现象",2007,158,"A","B","当刺激感受器时，如果刺激仍在持续，但传入神经冲动频率已开始下降，此现象称为",[["A","传导阻滞"],["B","衰减性传导"],["C","疲惫"],["D","适应"]],"D","适应是指感受器接受一定强度的刺激，感觉神经纤维动作电位的频率随刺激时间的延长逐渐降低的现象（D对），适应并非疲劳（C错），因为感受器对某一强度的刺激产生适应后，若进一步加大同样性质刺激的强度，其相应的传入冲动又可增加。传导阻滞一般指心脏兴奋传导过程中发生的减慢或阻滞（A错）。衰减性传导（十版生理学P41）是指电紧张电位的幅度在传导过程中随传播距离的增加而下降（B错）。","","N"],["2007-N159-J",3,"第4节 心血管活动的调节","血管的神经支配",2007,159,"A","B","交感缩血管纤维分布最密集的血管是",[["A","皮肤血管"],["B","骨骼肌血管"],["C","内脏血管"],["D","脑血管"]],"A","交感缩血管神经纤维的分布密度在不同类型的血管和不同部位的血管是有差异的。在不同类型的血管中，小动脉和微动脉的分布密度最高，静脉较相应的动脉为少，毛细血管前括约肌中的缩血管纤维也很少。在不同部位的血管中，皮肤、骨骼肌和内脏的小动脉和微动脉有丰富的交感缩血管神经纤维分布，特别是皮肤血管（A对）。而冠状血管和脑血管（D错）几乎没有此类神经纤维的分布。","","N"],["2007-N160-J",7,"第3节 肾小管和集合管的物质转运功能","近端小管",2007,160,"A","B","从肾小球滤出的HCO₃⁻在近端小管重吸收的主要形式是",[["A","CO₂"],["B","H⁺"],["C","HCO₃⁻"],["D","H₂CO₃"]],"A","从肾小球滤过的HCO₃⁻不能直接被近端小管重吸收（C错），需要与小管液中的H⁺在碳酸酐酶的催化下结合为H₂CO₃，再解离成CO₂和水，然后以CO₂（高度脂溶性）的形式（A对），通过单纯扩散的方式进入上皮细胞，在上皮细胞内，CO₂和水又在碳酸酐酶的催化下形成H₂CO₃，最后经过解离，再变回HCO₃⁻（和H⁺）。","","N"],["2007-N161-J",11,"第3节 妊娠","胎盘的功能",2007,161,"A","B","诊断早期妊娠需测定的血或尿中的激素是",[["A","孕激素"],["B","雌激素"],["C","卵泡刺激素"],["D","人绒毛膜促性腺激素"]],"D","人绒毛膜促性腺激素（hCG）是由胎盘绒毛组织的合体滋养层细胞分泌的一种糖蛋白激素。卵子受精后第6天左右，滋养层细胞便开始分泌hCG，到妊娠8～10周时达到高峰，随后分泌逐渐减少，到妊娠20周左右降至较低水平。因为hCG只有妊娠期女性可以分泌并且于妊娠早期便可以出现，所以可以作为诊断早期妊娠的一个指标（D对）。其他的三种激素（孕激素，雌激素，卵泡刺激素）未妊娠的女性也可以分泌，并且妊娠后胎盘所分泌的孕激素和胎盘胎儿共同分泌的雌激素分泌的时间均较晚，因此不能作为诊断早期妊娠的指标。","","N"],["2007-N162-J",9,"第1节 神经系统功能活动的基本原理","影响递质释放的因素",2007,162,"A","B","影响突触前膜递质释放量的主要因素是",[["A","动作电位的传导速度"],["B","突触蛋白Ⅰ磷酸化的程度"],["C","进入前膜Ca²⁺的量"],["D","突触小泡大小"]],"C","当突触前神经元的兴奋传到末梢时，突触前膜去极化，当去极化达一定水平时，突触前膜中的电压门控钙通道开放，Ca²⁺从细胞外进入突触前末梢轴浆内，导致轴浆内Ca²⁺浓度瞬间升高，Ca²⁺与轴浆中的钙调蛋白结合为Ca²⁺-CaM复合物，于是Ca²⁺-CaM依赖的蛋白激酶Ⅱ被激活，促使突触蛋白Ⅰ发生磷酸化，使其与细胞骨架丝的结合力减弱，突触囊泡便从骨架丝上游离出来（十版生理学P288）。由此可见，突触蛋白Ⅰ磷酸化的程度取决于进入前膜Ca²⁺的量（B错），进入前膜Ca²⁺的量才是影响突触前膜递质释放量的最主要因素（C对）。递质的释放量与到达突触末梢动作电位的频率和幅度有关（影响进入前膜Ca²⁺的量），而与动作电位的传导速度无关（A错）。突触小泡大小与递质种类有关而与递质的释放量无关（D错）：①小而清亮透明的囊泡，内含乙酰胆碱或氨基酸类递质；②小而具有致密中心的囊泡，内含儿茶酚胺类递质；③大而具有致密中心的囊泡，内含神经肽类递质。","","N"],["2008-N1",0,"第6节 人体内自动控制系统","负反馈控制系统",2008,1,"A","","从控制论的观点看，对维持内环境的稳态具有重要作用的调控机制是",[["A","非自动控制"],["B","负反馈控制"],["C","正反馈控制"],["D","前馈控制"]],"B","负反馈能够使受控部分的活动朝着与它原先活动相反的方向改变，具有纠偏功能，并且极为多见，在机体生理功能稳态的维持中发挥重要作用（B对）。正反馈使受控部分的活动朝着与它原先活动相同的方向改变，没有纠正偏差的功能，一般对稳态的维持不发挥作用（C错）。人体内控制系统分非自动控制系统、反馈控制系统和前馈控制系统三类，非自动控制系统中的受控部分不能反过来影响控制系统，不能调控机体内环境的稳态（A错），非控制系统在人体生理调节中较少见，典型的例子为应激对血压的影响。控制部分在反馈信息尚未到达前已收到纠正信息的影响，及时纠正其指令可能出现的偏差，这种自动控制形式称为前馈控制系统（十版生理学P11），前馈具有预见性，能够克服反馈“滞后”和“波动”的缺点，但相对反馈控制系统来说并不常见，在机体稳态调控过程中发挥的作用有限（D错）。","","N"],["2008-N2",1,"第3节 细胞的电活动","电-化学驱动力及其变化",2008,2,"A","","神经细胞在兴奋过程中，Na⁺内流和K⁺外流的量取决于",[["A","各自平衡电位"],["B","细胞的阈电位"],["C","钠泵活动程度"],["D","所给刺激强度"]],"A","离子的跨膜流动的动力来源于该离子所受的电化学驱动力，平衡电位时，离子的电化学驱动力为零，Na⁺净内流和K⁺净外流就停止了，故神经细胞在兴奋过程中，Na⁺内流和K⁺外流的量取决于各自的平衡电位（A对）。钠泵活动增强时，细胞内外Na⁺和K⁺浓度差增大，兴奋时Na⁺内流（去极化）和K⁺外流（复极化）的数量均增多，钠泵活动程度能够影响Na⁺内流和K⁺外流的量，但不能决定Na⁺内流和K⁺外流的量（C错）。细胞的阈电位、所给刺激强度是兴奋（动作电位）发生的起始影响因素（阈电位下移，兴奋更容易发生；刺激强度达到阈强度才能发生兴奋），但并不会影响兴奋过程中，Na⁺内流和K⁺外流的量（BD错）。","","N"],["2008-N3",1,"第4节 肌细胞的收缩","收缩总和",2008,3,"A","","能使骨骼肌发生完全强直收缩的刺激条件是",[["A","足够强度的单个阈刺激"],["B","足够持续时间的单个阈刺激"],["C","间隔小于收缩期的一串阈刺激"],["D","间隔大于收缩期的一串阈刺激"]],"C","肌肉接受一连串间隔时间很短的刺激时，后一个刺激落在前一个刺激所引起的收缩（包括收缩期和舒张期）尚未结束之前，导致肌肉一直处于收缩的状态，称为强直收缩。当刺激频率比较高时，后一刺激引起的收缩落在前一收缩的收缩期内（C对），肌肉将始终保持收缩状态，这种现象称为完全强直收缩。当刺激频率比较低时，后一刺激引起的收缩落在前一收缩的舒张期内，肌肉在收缩后有过短暂的舒张，但还未恢复到正常的舒张状况又进入下一次收缩，这种现象称为不完全强直收缩。","","N"],["2008-N4",2,"第2节 血细胞生理","红细胞生成的调节",2008,4,"A","","调节红细胞生成的特异性体液因子是",[["A","CSF"],["B","GH"],["C","IGF"],["D","EPO"]],"D","EPO的英文全称为Erythropoietin，中文名为促红细胞生成素，人体中的促红细胞生成素是由肾皮质肾小管周围间质细胞和肝脏分泌的一种激素样物质，能够促进红细胞生成（D对）。CSF（十版生理学P61）的英文全称为Colony-Stimulating Factor，中文名为集落刺激因子，该因子因可以刺激不同的造血干细胞在半固体培养基中形成细胞集落而成名，根据作用对象不同可分为粒细胞CSF、巨噬细胞CSF、粒细胞和巨噬细胞CSF、EPO等等。GH（十版生理学P349）的英文全称为Growth Hormone，中文名为生长激素，生长激素由腺垂体分泌，生长激素可以促进神经组织以外的所有组织生长（尤其是骨骼与肌肉组织）。IGF（十版生理学P349）的英文全称为Insulin-like Growth Factor，中文名胰岛素样生长因子，因与胰岛素的结构具有同源性而得名，与生长激素一样，是一类广谱性的促生长因子，对各类细胞的分化、增殖均有促进作用。","","N"],["2008-N5",2,"第3节 生理性止血","生理性抗凝物质",2008,5,"A","","实验中常用枸橼酸钠抗凝血，其机制是",[["A","抑制凝血酶的活性"],["B","加强抗凝血酶Ⅲ的作用"],["C","防止血小板激活"],["D","螯合血浆中的Ca²⁺"]],"D","柠檬酸钠又称枸橼酸钠，可Ca²⁺结合，生成难解离的可溶性络合物枸橼酸钙，Ca²⁺是凝血过程的重要辅助因子（Ca²⁺即FⅣ，可以作为辅因子辅助依赖维生素K的凝血因子FⅡ、FⅦ、FⅨ、FⅩ发生凝血作用，依赖维生素K的凝血因子的分子中均含有γ-羧基谷氨酸，和Ca²⁺结合后可发生变构，暴露出与磷脂结合的部位而参与凝血），血液中Ca²⁺减少，血液凝固受阻（D对）。抑制凝血酶活性的是体内的生理性抗凝物质，包括丝氨酸蛋白酶抑制物、蛋白质C系统和组织因子途径抑制物等（A错）。加强抗凝血酶Ⅲ作用的是肝素，肝素可以使抗凝血酶Ⅲ的抗凝作用增强2000倍以上（B错）。防止血小板激活的物质有很多，包括前列环素、NO、腺苷等等（C错）。","","N"],["2008-N6",3,"第1节 心脏的泵血功能","每分功",2008,6,"A","","高血压患者较正常人明显增高的心泵功能指标是",[["A","心输出量"],["B","射血分数"],["C","心指数"],["D","心脏做功量"]],"D","与单纯的心输出量相比，用心脏做功量来评定心脏泵血功能将更为全面。尤其是在动脉血压高低不同的个体之间进行比较，高血压患者动脉血压升高，为克服加大的射血阻力，心肌必须增加其收缩强度才能使搏出量保持不变，因而心脏做功量将增加（D对）。由于心肌收缩加强，使搏出量保持不变，故高血压患者心输出量、射血分数（搏出量占心室舒张末期容积的百分比）、心指数（单位体表面积的心输出量）等指标并无明显变化（ABC错）。","","N"],["2008-N7",3,"第3节 血管生理","微循环的血流动力学",2008,7,"A","","在微循环中，主要受局部代谢产物调节的结构是",[["A","微动脉"],["B","直捷通路"],["C","毛细血管前括约肌"],["D","真毛细血管"]],"C","微循环由微动脉、后微动脉、毛细血管前括约肌、真毛细血管、通血毛细血管（或称直捷通路）、微静脉和动-静脉吻合支等部分组成。其中后微动脉和毛细血管前括约肌（C对）主要受局部代谢产物（如CO₂、H⁺、腺苷、ATP、K⁺等）的调节（代谢性自身调节）而发生交替性血管舒缩活动。微动脉也接受局部代谢产物的调节（参考十版生理学P128代谢性自身调节的定义），但微动脉主要受神经调节（微动脉是交感缩血管神经纤维分布密度最高的血管类型）和体液调节（A错）。直捷通路（十版生理学P116）是指血液从微动脉经后微动脉和通血毛细血管进入微静脉的通路，直捷通路的开放与关闭主要由微动脉控制，故主要接受神经和体液调节（B错）。","","N"],["2008-N8",4,"第1节 肺通气","弹性阻力和顺应性",2008,8,"A","","下列选项中，能使肺的静态顺应性降低的因素是",[["A","肺气肿"],["B","肺表面活性物质缺乏"],["C","气道阻力增加"],["D","惯性阻力增加"]],"B","肺的顺应性可分为静态肺顺应性和动态肺顺应性。静态肺顺应性是指在呼吸周期中，气流暂时阻断时测得的肺顺应性（P151），受肺组织弹力影响；动态肺顺应性是指在呼吸周期中，气流未阻断时测得的肺顺应性，受肺组织弹力和气道阻力的双重影响。由于肺表面活性物质可以降低肺泡表面张力，肺泡表面张力又是肺的弹性阻力的主要来源（P152），故肺表面活性物质可以减少肺的弹性阻力。而弹性阻力与顺应性在数值上互为倒数，所以肺表面活性物质可以增加肺的顺应性。当肺泡表面活性物质减少时，肺的表面张力增大，肺的弹性阻力增加，肺的顺应性减小（静态顺应性和动态顺应性均降低）（B对）。","","N"],["2008-N9",4,"第1节 肺通气","肺容量",2008,9,"A","","可缓冲呼吸过程中肺泡气PO₂和PCO₂变化幅度的肺容量是",[["A","深吸气量"],["B","功能残气量"],["C","肺活量"],["D","用力呼气量"]],"B","平静呼气末尚存留于肺内的气体量为功能余气量（功能残气量），功能余气量的生理意义是缓冲呼吸过程中肺泡气氧分压（PO₂）和二氧化碳分压（PCO₂）的变化幅度（B对）。由于功能余气量的稀释作用，吸气时，肺内PO₂不致突然升得太高，PCO₂不致降得太低；呼气时，则PO₂不会降得太低，PCO₂不会升得太高。这样，肺泡气和动脉血液的PO₂和PCO₂就不会随呼吸而发生大幅度的波动，有利于肺换气。","","N"],["2008-N10",4,"第4节 呼吸运动的调节","CO₂、H⁺、O₂对呼吸运动的调节",2008,10,"A","","动脉血中H⁺浓度升高引起呼吸运动加强的感受器是",[["A","中枢化学敏感区"],["B","包钦格复合体"],["C","颈动脉窦和主动脉弓"],["D","颈动脉体和主动脉体"]],"D","H⁺对中枢化学感受器和外周化学感受器均有刺激作用，并且中枢化学感受器对H⁺的敏感度远大于外周化学感受器，但是动脉血H⁺浓度增加时，增加的H⁺不能直接作用中枢化学感受器，而是需要通过血-脑屏障进入脑脊液（过程很缓慢）才能发挥作用，因此动脉血H⁺浓度增加对中枢化学感受器的作用有限，主要通过刺激外周化学感受器（位于颈动脉体和主动脉体）而起作用（D对）。中枢化学敏感区即中枢化学感受器分布的区域，位于延髓腹外侧浅表部位，左右对称，可分为头、中、尾三个区（十版生理学P160）。包钦格复合体位于延髓呼吸中枢的，可能是哺乳动物呼吸节律起源的关键部位（十版生理学P157）。颈动脉窦和主动脉弓是动脉压力感受器（十版生理学P122），介导压力感受性反射，调节动脉血压的变化。","","N"],["2008-N11",5,"第3节 胃内消化","胃蛋白酶原",2008,11,"A","","能促使胃蛋白酶原转变为胃蛋白酶的物质是",[["A","盐酸"],["B","前列腺素E₂"],["C","丙谷胺"],["D","内因子"]],"A","胃蛋白酶原进入胃腔后，在盐酸（A对）的作用下或在酸性环境中，分离出1个小分子多肽，从而形成有活性的胃蛋白酶。已被激活的胃蛋白酶对胃蛋白酶原也有激活作用，即自我激活。前列腺素E₂（B错）的功能在于抑制胃酸和胃蛋白酶原的分泌，刺激黏液和碳酸氢盐的分泌，使胃黏膜的微血管扩张，增加黏膜的血流量（十版生理学P379）。丙谷胺（C错）又叫丙谷酰胺，属抗酸药及治疗消化性溃疡病药，其作用机制是与胃泌素竞争胃泌素受体，从而抑制胃酸分泌。内因子（D错）由胃黏膜的壁细胞产生，它与维生素B₁₂结合，形成内因子-B₁₂复合物，能保护维生素B₁₂免受消化酶的破坏，并通过回肠黏膜上特异受体的介导，促进维生素B₁₂在回肠远端的吸收。","","N"],["2008-N12",5,"第4节 小肠内消化","胰液的性质、成分和作用",2008,12,"A","","当胰液缺乏而其他消化液分泌正常时，可引起",[["A","血糖降低"],["B","脂肪泻"],["C","胰腺炎"],["D","恶性贫血"]],"B","当胰液分泌缺乏时，即使其他消化腺的分泌都很正常，食物中的脂肪仍然不能完全被消化和吸收，过多未经消化的脂肪在胃肠道内会带走大量的水分，从而引起脂肪泻（B对）。但是胰液分泌缺乏时，对糖的消化和吸收影响不大，当糖的消化和吸收正常时，血糖的高低主要受胰岛素和胰高血糖素等激素的调节，而与胰液的分泌无关（A错）。恶性贫血又称巨幼红细胞贫血，因叶酸或维生素B₁₂缺乏引起，与胰液的分泌无关（D错）。胰腺炎为胰蛋白酶原在胰腺内激活引起胰腺水肿、出血及坏死的炎性损伤，与胆结石、胆道感染、酗酒等因素（十版内科学P441）有关，与胰液缺乏无关（C错）。","","N"],["2008-N13",5,"第4节 小肠内消化","小肠的运动形式",2008,13,"A","","当小肠被食糜充盈时，小肠反复进行分节运动，其主要作用是",[["A","充分混合食糜和消化液"],["B","将食糜不断向前推进"],["C","刺激胃肠激素的释放"],["D","促进消化液继续分泌"]],"A","分节运动是一种以环行肌为主的节律性收缩和舒张交替进行的运动。这种形式的运动表现为食糜所在肠道的环行肌以一定的间隔交替收缩，把食糜分割成许多节段；随后，原收缩处舒张，原舒张处收缩，使原来节段的食糜分成两半，邻近的两半合在一起，形成新的节段，如此反复，使食糜和消化液充分混合（A对）。将食糜不断向前推进的主要小肠运动形式是蠕动（十版生理学P184），虽然分节运动也能将食糜向前推进，但作用有限（B错）。刺激小肠内分泌细胞释放胃肠激素及小肠腺分泌消化液的因素是机械性和化学性刺激（十版生理学P184），而不是小肠分节运动本身（CD错）。","","N"],["2008-N14",6,"第1节 能量代谢","食物的特殊动力效应",2008,14,"A","","特殊动力效应最为显著的食物是",[["A","糖类"],["B","脂肪"],["C","蛋白质"],["D","无机盐"]],"C","人在进食后的一段时间内，即使在安静状态下，也会出现能量代谢率增高的现象，说明进食能刺激机体额外消耗能量，此为食物特殊动力作用。实验证明，食物的成分不同，所产生的食物特殊动力作用也不同，在三种主要营养物质中，进食蛋白质产生的食物特殊动力作用最为显著（C对）。","","N"],["2008-N15",7,"第1节 肾的功能解剖和肾血流量","滤过膜的构成",2008,15,"A","","在肾小球滤过中阻碍带电荷的蛋白质通过滤过膜最主要的结构是",[["A","肾小球毛细血管内皮"],["B","毛细血管内皮下基膜"],["C","肾小囊脏层足细胞"],["D","足细胞足突间裂隙膜"]],"B","肾小球滤过膜由毛细血管内皮细胞、毛细血管下基膜和肾小囊脏层足细胞的足突构成，三层结构的孔径分别为70～90nm、2～8nm和4～11nm，蛋白质分子的直径一般较大，因此不能自由滤过，此为滤过膜的机械屏障。三层结构均带负电荷，对带负电荷的蛋白质分子（人体内大部分蛋白质都带负电荷）有阻碍作用，此为滤过膜的电荷屏障。对于蛋白质来说，肾小球滤过膜三层结构的电荷屏障作用基本相同，但是机械屏障有区别，三层结构中孔径最小的毛细血管内皮下基膜的机械屏障作用最强，是肾小球滤过中阻碍带电荷的蛋白质通过滤过膜最主要的结构（B对）。","","N"],["2008-N16",7,"","",2008,16,"A","","肾脏近端小管对小管液中有用成分重吸收的特点是",[["A","重吸收的物质种类少"],["B","各种物质的重吸收量少"],["C","受神经和体液因素调节"],["D","小管液与上皮细胞内液保持等渗"]],"D","近端小管对水的重吸收是通过渗透作用进行的，上皮细胞重吸收的Na⁺、HCO₃⁻、Cl⁻、葡萄糖和氨基酸进入细胞间隙后，小管液的渗透压降低，细胞间隙液的渗透压升高。水在这一渗透压差的作用下通过跨上皮细胞和紧密连接两条途径进入细胞间隙，然后进入管周毛细血管而被吸收，故近端小管中物质的重吸收为等渗性重吸收，小管液为等渗液，即小管液与上皮细胞内液保持等渗（D对）。在各段肾小管和集合管中，近端小管重吸收的物质的量和种类最多（AB错），可吸收100%的葡萄糖和氨基酸，65%～70%的Na⁺、Cl⁻和水，80%的HCO₃⁻，65%～70%的K⁺，70%的Ca²⁺等。近端小管重吸收受神经（交感神经）（十版生理学P230）和体液（血管紧张素Ⅱ）（十版生理学P232）因素的调节（C对？），本题的参考答案为D，可能与“受神经和体液因素调节”非近端小管的“特点”有关，因为远曲小管和集合管也受神经和体液因素调节。","","N"],["2008-N17",7,"第5节 尿生成的调节","血浆晶体渗透压",2008,17,"A","","饮大量清水后尿量增多的最主要原因是",[["A","肾血流量增加"],["B","肾小球滤过率增加"],["C","血浆胶体渗透压降低"],["D","抗利尿激素分泌减少"]],"D","饮大量清水后，血浆晶体渗透压下降，抗利尿激素（血管升压素）分泌减少，进而造成肾小管和集合管对水的重吸收减少，尿量增多（D对）。","","N"],["2008-N18",8,"第3节 视觉","感光细胞及其特征",2008,18,"A","","与视锥细胞相比，视杆细胞的特点是",[["A","数量少"],["B","对光敏感度高"],["C","能产生色觉"],["D","分辨能力强"]],"B","视网膜中有视杆细胞和视锥细胞两种感光细胞。与视锥细胞相比，视杆细胞数量较多（A错），对光的敏感度较高（B对），能在昏暗环境中感受弱光刺激，但无色觉（C错），对被视物细节的分辨力较低（D错）。","","N"],["2008-N19",9,"第2节 神经系统的感觉分析功能","感觉投射系统",2008,19,"A","","下列选项中，符合非特异性感觉投射系统功能的是",[["A","产生某种特定的感觉"],["B","维持和改变大脑皮质的兴奋状态"],["C","激发大脑皮质发出传出冲动"],["D","参与形成躯体平衡感觉"]],"B","丘脑是感觉传入通路的重要中继站，根据丘脑各部分向大脑皮层投射特征的不同，将感觉投射系统分为特异投射系统和非特异投射系统，特异投射系统是指特异感觉接替核及其投射到大脑皮层的神经通路，它们投射到大脑皮层的特定区域，与大脑皮层具有点对点的投射关系，可以引起特定的感觉并激发大脑皮层发出神经冲动，因此产生某种特定的感觉和激发大脑皮质发出传出冲动是特异投射系统的功能（AC错）。非特异投射系统是指丘脑的非特异投射核及其投射至大脑皮层的神经通路，它们投射到大脑皮层的广泛区域，与大脑皮层不具有点对点投射关系，不能引起特异感觉，主要功能是维持和改变大脑皮层的兴奋状态（B对）。躯体平衡感觉属特异感觉，由特异性感觉投射系统介导（D错）。","","N"],["2008-N20",9,"第3节 神经系统对躯体运动的调控","前庭小脑",2008,20,"A","","切除动物前庭小脑后，动物将表现为",[["A","站立不稳"],["B","四肢乏力"],["C","运动不协调"],["D","静止性震颤"]],"A","小脑皮层可按原裂及后外侧裂横向分为前叶、后叶和绒球小结叶，也可根据其传入、传出纤维联系分为前庭小脑、脊髓小脑和皮层小脑。前庭小脑主要由绒球小结叶构成，接受前庭核的纤维投射，主要参与身体姿势平衡和眼外肌活动的调节。切除前庭小脑的动物，会出现步基宽、站立不稳、步态蹒跚、容易跌倒等身体平衡失调的症状（A对）和位置性眼球震颤等眼外肌活动障碍的症状，但其随意运动的协调不受影响（C错）。四肢乏力（十版生理学P317）见于脊髓小脑受损（B错）。静止性震颤（十版生理学P315）见于帕金森病（D错）。","","N"],["2008-N21",10,"第3节 甲状腺内分泌","下丘脑－腺垂体－甲状腺轴的调节",2008,21,"A","","寒冷刺激可引起下丘脑促垂体区释放",[["A","CRH"],["B","TRH"],["C","GnRH"],["D","GHIH"]],"B","寒冷环境下，寒冷刺激沿上行的神经传导通路进入中枢神经系统，引起下丘脑释放促甲状腺激素释放激素（TRH）（B对），后者再刺激腺垂体释放促甲状腺激素（TSH），从而促进甲状腺产生和分泌甲状腺激素，使机体的基础代谢率升高，产热增加。","","N"],["2008-N22",10,"第4节 甲状旁腺、维生素D与甲状腺C细胞内分泌","甲状旁腺激素的分泌调节",2008,22,"A","","影响甲状旁腺分泌最重要的因素是",[["A","血钙浓度"],["B","血磷浓度"],["C","血碘浓度"],["D","血钾浓度"]],"A","血钙浓度是影响甲状旁腺分泌的最重要因素（A对），血钙降低时可促进甲状旁腺激素（PTH）的分泌和合成。血磷浓度也可影响甲状旁腺分泌（P384），血磷升高可降低血钙水平间接刺激甲状旁腺激素（PTH）的分泌和合成。血碘浓度影响甲状腺分泌甲状腺素（十版生理学P363）。血钾浓度影响肾上腺皮质分泌醛固酮激素（十版生理学P371）。","","N"],["2008-N23",10,"第5节 肾上腺内分泌","应激性调节",2008,23,"A","","机体受到刺激而发生应激反应的系统是",[["A","下丘脑-腺垂体-肾上腺皮质系统"],["B","下丘脑-神经垂体系统"],["C","交感-肾上腺髓质系统"],["D","迷走-胰岛素系统"]],"A","当机体受到刺激时，下丘脑-腺垂体-肾上腺皮质系统被激活（A对）：下丘脑CRH神经元分泌增强，刺激腺垂体ACTH分泌，最后引起肾上腺皮质激素（GC）的大量分泌，以提高机体对伤害性刺激的耐受能力。","","N"],["2008-N24",11,"第2节 女性生殖功能及其调节","雌激素、孕激素的作用",2008,24,"A","","下列关于雌激素生理作用的叙述，正确的是",[["A","抑制输卵管运动"],["B","促进子宫内膜腺体增生和分泌"],["C","促进阴道上皮细胞增生和角化"],["D","促进乳腺发育并引起泌乳"]],"C","雌激素能够促进输卵管运动，以有利于精子与卵子的运行（A错）。雌激素可以促进子宫内膜腺体增生，但并不促进其分泌（B错），能够促进子宫内膜分泌的是孕激素。雌激素可以促进阴道上皮细胞增生和角化（C对）。雌激素可以促进乳腺发育，但对泌乳起抑制作用（D错），能够促进泌乳的是催乳素（PRL）。","","N"],["2008-N121",1,"第2节 细胞的信号转导","G蛋白效应器",2008,121,"B","","与胞浆中cAMP生成有直接关系的G蛋白效应器是",[["A","磷脂酶A"],["B","磷脂酶C"],["C","腺苷酸环化酶"],["D","鸟苷酸环化酶"]],"C","G蛋白效应器是指G蛋白直接作用的靶标，G蛋白效应器的重要功能是催化生成第二信使，腺苷酸环化酶（AC）和磷脂酶C（PLC）是两种最常见的G蛋白效应器，腺苷酸环化酶可催化生成的第二信使为环磷酸腺苷（cAMP）（C对），磷脂酶C可催化生成的第二信使为三磷酸肌醇（IP₃）和二酰甘油（DG）。","","N"],["2008-N122",1,"第2节 细胞的信号转导","G蛋白效应器",2008,122,"B","","与IP₃和DG生成有直接关系的G蛋白效应器是",[["A","磷脂酶A"],["B","磷脂酶C"],["C","腺苷酸环化酶"],["D","鸟苷酸环化酶"]],"B","G蛋白效应器是指G蛋白直接作用的靶标，G蛋白效应器的重要功能是催化生成（或分解）第二信使，腺苷酸环化酶（AC）和磷脂酶C（PLC）是两种最常见的G蛋白效应器，腺苷酸环化酶可催化生成的第二信使为环磷酸腺苷（cAMP），磷脂酶C可催化生成的第二信使为三磷酸肌醇（IP₃）和二酰甘油（DG）（B对）。关于磷脂酶C可参考十版生物化学与分子生物学P158甘油磷脂的分解代谢。","","N"],["2008-N123",3,"第4节 心血管活动的调节","颈动脉窦和主动脉弓压力感受性反射",2008,123,"B","","能有效缓冲血压快速波动的心血管反射是",[["A","压力感受性反射"],["B","化学感受性反射"],["C","心肺感受器反射"],["D","脑缺血反应"]],"A","压力感受性反射（十版生理学P123）指动脉血压升高时，颈动脉窦和主动脉弓的压力感受器传入冲动增多，通过有关的心血管中枢整合作用，使心迷走紧张加强，心交感紧张和交感缩血管紧张降低，其效应为心率减慢，心输出量减少，外周血管阻力降低，动脉血压回降，压力感受性反射在心输出量、外周血管阻力、血量等发生突然改变的情况下，对动脉血压进行快速调节的过程中起重要的作用（A对）。化学感受性反射（十版生理学P123）指缺氧、窒息、失血、血压过低和酸中毒等情况下，颈动脉体和主动脉体化学感受性器接受刺激，反射性引起心率加快，心输出量增多，外周阻力增大，血压升高，由于心脏和脑的血管无明显收缩或发生轻微舒张，使循环血量得以重新分配，因此化学感受性反射在重新分配循环血量以保证心、脑等重要器官血液供应的调节中发挥重要的作用。心肺感受性反射（十版生理学P123）又称容量感受性反射，指血容量增多时，心房壁内的心肺感受器受牵张刺激，不仅引起交感神经抑制和迷走神经兴奋，使心率减慢，心输出量减少，外周阻力降低和血压下降，还降低血浆血管升压素和醛固酮水平，减少肾远曲小管和集合管对钠和水的重吸收，降低血容量和细胞外液量，因此心肺感受性反射在血容量和细胞外液量的调节中具有重要的生理意义。脑缺血反应（十版生理学P124）是指脑血流量减少时，交感缩血管紧张显著加强，外周血管高度收缩，动脉血压升高，以改善脑血液供应的过程。","","N"],["2008-N124",3,"第4节 心血管活动的调节","心肺感受器引起的心血管反射",2008,124,"B","","能抑制下丘脑释放血管升压素，调节机体血容量的心血管反射是",[["A","压力感受性反射"],["B","化学感受性反射"],["C","心肺感受器反射"],["D","脑缺血反应"]],"C","压力感受性反射（十版生理学P123）指动脉血压升高时，颈动脉窦和主动脉弓的压力感受器传入冲动增多，通过有关的心血管中枢整合作用，使心迷走紧张加强，心交感紧张和交感缩血管紧张降低，其效应为心率减慢，心输出量减少，外周血管阻力降低，动脉血压回降，压力感受性反射在心输出量、外周血管阻力、血量等发生突然改变的情况下，对动脉血压进行快速调节的过程中起重要的作用。（十版生理学P232）循环血量或动脉血压降低时，可降低引起抗利尿激素释放的血浆晶体渗透浓度阈，即提高渗透压感受器对相应刺激的敏感度；反之，当循环血量或动脉血压升高时，可升高引起抗利尿激素释放的血浆晶体渗透压浓度阈，即降低渗透压感受器的敏感度。化学感受性反射（十版生理学P123）指缺氧、窒息、失血、血压过低和酸中毒等情况下，颈动脉体和主动脉体化学感受性器接受刺激，反射性引起心率减慢，心输出量减少，冠状动脉舒张，骨骼肌和内脏血管收缩等效应，由于心脏和脑的血管无明显收缩或发生轻微舒张，使循环血量得以重新分配，因此化学感受性反射在重新分配循环血量以保证心、脑等重要器官血液供应的调节中发挥重要的作用。心肺感受性反射（十版生理学P123）又称容量感受性反射，指血容量增多时，心房壁内的心肺感受器受牵张刺激，不仅引起交感神经抑制和迷走神经兴奋，使心率减慢，心输出量减少，外周阻力降低和血压下降，还降低血浆血管升压素和醛固酮水平（C对），减少肾远曲小管和集合管对钠和水的重吸收，降低血容量和细胞外液量，因此心肺感受性反射在血容量和细胞外液量的调节中具有重要的生理意义。脑缺血反应（十版生理学P124）是指脑血流量减少时，交感缩血管紧张显著加强，外周血管高度收缩，动脉血压升高，以改善脑血液供应的过程。根据十版生理学，正确答案为AC，但给出答案为C。","","N"],["2008-N125",9,"第4节 神经系统对内脏活动、本能行为和情绪的调节","本能行为",2008,125,"B","","破坏下丘脑外侧区，可引起动物",[["A","拒食至饿死"],["B","食欲大增致肥胖"],["C","出现假怒现象"],["D","变得温顺驯服"]],"A","摄食行为是人体的本能行为，摄食中枢和饱中枢共同参与摄食行为的调节。摄食中枢位于下丘脑外侧区，破坏该区引起动物拒食（A对），饱中枢位于下丘脑的腹内侧核，破坏此核则导致食欲增加而逐渐肥胖（B错）。在间脑水平以上切除动物的大脑，可以引起动物出现假怒现象（十版生理学P325）（C错）。破坏杏仁核，动物变得温顺驯服（D错）。","","N"],["2008-N126",9,"第4节 神经系统对内脏活动、本能行为和情绪的调节","本能行为",2008,126,"B","","破坏下丘脑腹内侧核，可引起动物",[["A","拒食至饿死"],["B","食欲大增致肥胖"],["C","出现假怒现象"],["D","变得温顺驯服"]],"B","摄食行为是人体的本能行为，摄食中枢和饱中枢共同参与摄食行为的调节。摄食中枢位于下丘脑外侧区，破坏该区引起动物拒食（A错），饱中枢位于下丘脑的腹内侧核，破坏此核则导致食欲增加而逐渐肥胖（B对）。在间脑水平以上切除动物的大脑，可以引起动物出现假怒现象（十版生理学P325）（C错）。破坏杏仁核，动物变得温顺驯服（D错）。","","N"],["2008-N151",1,"第1节 细胞膜的物质转运功能","钠-钾泵",2008,151,"X","","用哇巴因抑制钠泵活动后，细胞功能发生的变化有",[["A","静息电位绝对值减小"],["B","动作电位幅度降低"],["C","Na⁺-Ca²⁺交换增加"],["D","胞质渗透压升高"]],"ABD","静息电位主要由K⁺外流产生的，而K⁺外流的驱动力来自钠泵建立起来的细胞内高K⁺，细胞外低K⁺的离子分布状态（浓度差驱动力），当钠泵受抑制，细胞内外K⁺浓度差减小，K⁺外流数量减少，静息电位的绝对值减小（A对）。动作电位主要由Na⁺离子内流介导，Na⁺内流的驱动力则来自钠泵建立起来的细胞外高Na⁺，细胞内低Na⁺的离子分布状态，当钠泵受抑制，细胞内外Na⁺浓度差减小，Na⁺内流数量减少，动作电位的绝对值减小，即动作电位的幅度降低（B对）。Na⁺-Ca²⁺交换属于继发性主动转运，其动力来自钠泵活动所建立的钠离子跨膜浓度梯度，故当钠泵活动受抑制时，Na⁺-Ca²⁺交换减弱（C错）。静息状态下，K⁺的平衡电位接近静息膜电位，电化学驱动力小，K⁺外流较少，而Na⁺的平衡电位偏离静息电位状态很远，虽然Na⁺通透性较低，但在强大的电化学驱动力驱动下，不断有Na⁺漏入细胞内（由外到内的净流动），漏入的Na⁺需要及时经钠泵排出，以保持细胞正常的渗透压和容积，以防细胞水肿，当钠泵受到抑制后，漏入细胞内Na⁺不能及时排出，胞质渗透压升高（D对）。","","N"],["2008-N152",2,"第2节 血细胞生理","血小板的生理特性",2008,152,"X","","血小板在生理性止血中的作用有",[["A","黏附于内皮下成分"],["B","释放ADP和TXA₂，引起血小板聚集"],["C","释放TXA₂促进血管收缩"],["D","释放PF₃促进凝血"]],"ABCD","血小板的生理特性包括：1.黏附：当血管内皮细胞受损时，血小板即可黏附于内皮下组织（A对）。2.释放：血小板受刺激后释放的物质主要有ADP、ATP、5-羟色胺（5-HT）、Ca²⁺、血栓烷A₂（TXA₂）等（B对），其中TXA₂具有强烈的聚集血小板和缩血管作用（C对）。3.聚集：血小板与血小板之间的相互黏着，称为血小板聚集。血小板因子（Platelet Factor，PF）有10余种，血管受损时，血小板与胶原组织接触发生黏附、聚集，血小板破裂，释放出PF，参与止血和凝血过程（D对）。PF₃为血小板第3因子，是血小板活化过程中形成的一种膜表面磷脂，它参与凝血因子X的激活过程，促进凝血酶原的激活，PF₃释放不足将导致凝血功能障碍。","","N"],["2008-N153",3,"第3节 血管生理","影响静脉回心血量的因素",2008,153,"X","","可使静脉回流加速的因素有",[["A","从卧位到站立"],["B","注射肾上腺素"],["C","慢速跑步"],["D","浸泡在水中"]],"BCD","注射肾上腺素，可增加心脏收缩力，使得心脏射血能力加强，中心静脉压下降，有利于静脉回流（B对）。浸泡在水中，由于浮力削弱了重力对静脉压的影响，使得跨壁压降低，外周静脉充盈减小，静脉血流向心脏回流增加（D对）。","","N"],["2008-N154",6,"第2节 体温及其调节","体温的生理性波动",2008,154,"X","","下列关于体温正常变动的叙述，正确的有",[["A","一昼夜中清晨较低，午后较高"],["B","成年男子体温平均较女子高"],["C","新生儿体温偏高"],["D","老年人体温偏低"]],"AD","正常情况下，体温可受一些内在因素的影响而发生波动，包括：①日节律的影响：体温在一昼夜之间存在周期性的波动，表现为体温在清晨2-6时最低，午后1-6时最高（A对）；②性别的影响：成年女性的体温平均高于男性0.3℃（B错）；③年龄的影响：儿童和青少年的体温较高，老年人因基础代谢率低而体温偏低（D对）。新生儿，特别是早产儿，由于其体温调节机构尚未发育完善，调节体温的能力较差，故体温易受环境因素影响而发生变动（C错）；④运动的影响：运动时肌肉活动能使代谢增强，产热量增加，体温升高。","","N"],["2008-N155",8,"第5节 平衡感觉","半规管",2008,155,"X","","发生晕船反应时，受到过度刺激的感受器有",[["A","上半规管"],["B","外半规管"],["C","后半规管"],["D","椭圆囊和球囊"]],"AC","内耳前庭器官由半规管、椭圆囊和球囊组成，半规管是角加速度感受器，椭圆囊和球囊是直线加速度感受器。人两侧内耳各有上、外、后三个半规管，其中外半规管又叫水平半规管，上半规管又称为前半规管，三个半规管互相垂直，分别代表三维空间的三个平面。当人体直立绕身体纵轴（水平面）旋转时，受刺激最大的是水平（外）半规管；当人体侧身翻转时（绕矢状轴在冠状面上旋转），受刺激最大的是上（前）半规管；当人体前后翻转时（绕冠状轴在矢状面上旋转），受刺激最大的是后半规管。当半规管受到过强或过长时间的刺激时，可引起与前庭神经相关的自主神经功能失调，导致心率加快，血压下降、恶心、呕吐等，晕船就是因为船在海上行驶时，船身上下颠簸过度刺激后半规管，以及船身左右摇摆过度刺激上（前）半规管等引起的前庭自主神经反应（AC对）。船不会在原地旋转，所以不会刺激水平（外）半规管（B错）。船也不会有直线加速运动，所以也不会刺激椭圆囊和球囊（D错）。","","N"],["2008-N156",9,"第1节 神经系统功能活动的基本原理","乙酰胆碱及其受体",2008,156,"X","","当发生有机磷农药中毒时，可出现",[["A","骨骼肌收缩颤动"],["B","瞳孔缩小"],["C","大汗淋漓"],["D","心率加速"]],"ABC","正常情況下，体内的乙酰胆碱（ACh）在胆碱酯酶的水解下失活，有机磷农药中毒时胆碱酯酶活性被抑制，体内ACh大量蓄积，出现中毒症状：①毒蕈碱样症状（M样症状）：瞳孔缩小（虹膜环形肌收缩）（B对）、大汗淋漓（小汗腺分泌增加）（C对）、心率减慢（负性变时作用）（D错）等。②烟碱样症状（N样症状）：骨骼肌收缩和颤动（A对）。","","N"],["2009-N1",0,"第6节 人体内自动控制系统","负反馈控制系统",2009,1,"A","","人体功能保持相对稳定依靠的调控系统是",[["A","非自动控制系统"],["B","负反馈控制系统"],["C","正反馈控制系统"],["D","前馈控制系统"]],"B","负反馈能够使受控部分的活动朝着与它原先活动相反的方向改变，具有纠偏功能，并且极为多见，在机体生理功能稳态的维持中发挥重要作用（B对）。正反馈使受控部分的活动朝着与它原先活动相同的方向改变，没有纠正偏差的功能，一般对稳态的维持不发挥作用（C错）。人体内控制系统分非自动控制系统、反馈控制系统和前馈控制系统三类，非自动控制系统中的受控部分不能反过来影响控制系统，不能调控机体内环境的稳态（A错），非控制系统在人体生理调节中较少见，典型的例子为应激对血压的影响。控制部分在反馈信息尚未到达前已收到纠正信息的影响，及时纠正其指令可能出现的偏差，这种自动控制形式称为前馈控制系统（十版生理学P11），前馈具有预见性，能够克服反馈“滞后”和“波动”的缺点，但相对反馈控制系统来说并不常见，在机体稳态调控过程中发挥的作用有限（D错）。","","N"],["2009-N2",1,"第3节 细胞的电活动","钠泵的生电作用",2009,2,"A","","神经细胞膜上的钠泵活动受抑制时，可导致的变化是",[["A","静息电位绝对值减小，动作电位幅度增大"],["B","静息电位绝对值增大，动作电位幅度减小"],["C","静息电位绝对值和动作电位幅度均减小"],["D","静息电位绝对值和动作电位幅度均增大"]],"C","钠泵通过吸入K⁺排出Na⁺造成细胞内高K⁺低Na⁺，细胞外高Na⁺低K⁺的离子不均匀分布，在浓度差驱动力（化学驱动力）的作用下，细胞内的高K⁺有由内向外流动的趋势，细胞外的高Na⁺有由外向内流动的趋势。在安静状态下，K⁺通透性较高，K⁺在浓度差驱动力的作用下，完成了由内向外流动的过程，K⁺外流的过程也是正电荷外流的过程，形成了膜内负电位，膜内负电位对带正电荷的K⁺有吸引作用，此为电驱动力，电驱动力与化学驱动力方向相反，能够阻止K⁺外流，K⁺外流越多，膜内负电位就越大，电驱动力也越大，当K⁺受到的电驱动力增加到与浓度差驱动力相等时，电-化学驱动力即为零，此时K⁺的净扩散量为零，膜两侧的电位差便稳定下来。这种K⁺扩散为零的跨膜电位差即为K⁺的平衡电位。而安静状态下膜对Na⁺的通透性很小，Na⁺由外向内流动很少（但是受到的驱动力很大），细胞内外的电荷分布主要受K⁺影响，使细胞安静状态下的电位（静息电位）与钾离子的平衡电位几乎相等。在兴奋状态下，膜对Na⁺的通透性增大，Na⁺在强大电化学驱动力的作用下（电驱动力和化学驱动力方向相同，均指向细胞内）内流，产生去极化乃至动作电位。钠泵活动受到抑制时，K⁺和Na⁺细胞内外的浓度梯度均减小，K⁺和Na⁺受到的浓度差驱动力均变小，K⁺外流减少，K⁺的平衡电位减小，静息电位的绝对值减小（或叫负值减小），而Na⁺内流减少，Na⁺的平衡电位减小，动作电位的超射值减小，动作电位的幅度等于静息电位绝对值与超射值之和，静息电位绝对值和动作电位的超射值均减小，动作电位的幅度自然也减小（C对）。","","N"],["2009-N3",1,"第4节 肌细胞的收缩","骨骼肌神经肌肉接头处的兴奋传递",2009,3,"A","","在神经-骨骼肌接头完成信息传递后，能消除接头处神经递质的酶是",[["A","Na⁺-K⁺-ATP酶"],["B","乙酰胆碱酯酶"],["C","腺苷酸环化酶"],["D","磷酸二酯酶"]],"B","乙酰胆碱酯酶（B对）可将与N₂型ACh受体阳离子通道结合的ACh迅速分解为胆碱和乙酸，使兴奋传递快速结束，避免神经动作电位消失后肌纤维的持续兴奋和收缩。有机磷中毒即与乙酰胆碱酯酶活性被抑制有关（十版内科学P890）：有机磷毒物进入体内后可迅速与体内的胆碱酯酶结合，生成磷酰化胆碱酯酶，使胆碱酯酶丧失了水解乙酰胆碱的功能，导致胆碱能神经递质大量积聚，作用于胆碱受体，产生严重的神经功能紊乱，特别是呼吸功能障碍，从而影响生命活动。","","N"],["2009-N4",2,"第1节 血液生理概述","血浆pH",2009,4,"A","","维持血浆pH相对恒定最重要的缓冲对是",[["A","Na₂HPO₄/NaH₂PO₄"],["B","NaHCO₃/H₂CO₃"],["C","K₂HPO₄/KH₂PO₄"],["D","KHCO₃/H₂CO₃"]],"B","正常人血浆PH为7.35～7.45，血浆PH的相对恒定有赖于血液内的缓冲物质，以及肺和肾的正常功能。血浆内的缓冲物质主要包括NaHCO₃/H₂CO₃、蛋白质钠盐/蛋白质和Na₂HPO₄/NaH₂PO₄三个缓冲对，其中最重要的是NaHCO₃/H₂CO₃（B对）。此外，红细胞内还有血红蛋白钾盐/血红蛋白、氧合血红蛋白钾盐/氧合血红蛋白、K₂HPO₄/KH₂PO₄、KHCO₃/H₂CO₃等缓冲对，参与维持血浆PH的恒定。","","N"],["2009-N5",2,"第3节 生理性止血","凝血因子",2009,5,"A","","凝血因子Ⅱ、Ⅶ、Ⅸ、Ⅹ在肝脏合成依赖于",[["A","维生素A"],["B","维生素C"],["C","维生素D"],["D","维生素K"]],"D","维生素K是γ-谷氨酰羧化酶的辅酶，可以促进FⅡ、FⅦ、FⅨ和FⅩ的谷氨酸残基被羧化为γ-羧基谷氨酸，从而具备与Ca²⁺结合的能力，FⅡ、FⅦ、FⅨ和FⅩ与Ca²⁺结合之后发生变构效应，暴露出与磷脂结合的部位而参与凝血。故FⅡ、FⅦ、FⅨ、FⅩ的的生成需要维生素K的参与，它们又被称为依赖维生素K的凝血因子（D对）。","","N"],["2009-N6",3,"第2节 心脏的电生理学及生理特性","兴奋在心脏内的传导",2009,6,"A","","心房和心室收缩在时间上不重叠，后者必定落在前者完毕后的原因是",[["A","窦房结到心房距离近，而到心室距离远"],["B","心房肌传导速度快，心室肌传导速度慢"],["C","房室交界处传导速度慢而形成房-室延搁"],["D","窦房结分别通过不同传导通路到达心房和心室"]],"C","心房和心室的收缩在时间上不发生重叠（心室收缩发生在心房收缩完毕之后），这是因为房室交界区细胞的传导速度很慢，而房室交界又是兴奋由心房传向心室的唯一通道，因此兴奋由心房传至心室需经一个时间延搁，这一现象称为房-室延搁（C对）。房-室延搁对心室的正常充盈和射血是十分重要的。","","N"],["2009-N7",3,"第3节 血管生理","影响动脉血压的因素",2009,7,"A","","如果血管总外周阻力不变，心脏每搏输出量增大，则动脉血压的变化是",[["A","收缩压不变，舒张压升高"],["B","收缩压升高，舒张压不变"],["C","收缩压升高比舒张压升高更明显"],["D","舒张压升高比收缩压升高更明显"]],"C","如果血管外周阻力、心率等其他因素不变，心脏每搏输出量增大，血压变化是收缩压和舒张压均升高，收缩压升高更明显（C对），脉压增大。","","N"],["2009-N8",4,"第1节 肺通气","肺泡通气量",2009,8,"A","","如果某人潮气量为500ml，无效腔气量为150ml，功能残气量是2500ml，那么此人每次平静呼吸能使肺泡气体更新约为",[["A","1/10"],["B","1/7"],["C","1/5"],["D","1/3"]],"B","平静呼气末尚存留于肺内的气体量为2500ml（功能残气量），每次吸入的新鲜空气量为350ml（潮气量-无效腔气量）。则每次平静呼吸时肺泡更新气体量为350/2500≈1/7（B对）。","","N"],["2009-N9",4,"第4节 呼吸运动的调节","CO₂、H⁺、O₂对呼吸运动的调节",2009,9,"A","","低氧刺激呼吸活动增强，其作用机制是",[["A","兴奋延髓呼吸中枢"],["B","兴奋脑桥呼吸调整中枢"],["C","兴奋中枢化学感受器"],["D","兴奋外周化学感受器"]],"D","化学感受器是指其适宜刺激是O₂、CO₂和H⁺等化学物质的感受器。根据所在部位的不同，化学感受器分为外周化学感受器和中枢化学感受器两种。外周化学感受器位于颈动脉体和主动脉体，在动脉血PO₂降低、PCO₂或H⁺浓度升高时均受到刺激，反射性地引起呼吸中枢兴奋。中枢化学感受器位于延髓腹外侧部的浅表部位，生理性刺激是脑脊液中的H⁺，动脉血H⁺浓度升高时，H⁺通过血-脑屏障进入脑脊液发挥作用（但进入速度较慢，限制了H⁺对中枢化学感受器的作用），动脉血PCO₂升高时，血液中的CO₂能够通过血-脑屏障，间接引起脑脊液H⁺浓度升高，从而刺激中枢化学感受器，引起呼吸中枢兴奋。因此，低氧对呼吸运动的刺激作用完全是通过刺激外周化学感受器实现的（D对C错），CO₂和H⁺对呼吸运动的刺激作用则可以通过中枢化学感受器和外周化学感受器共同实现。低氧对中枢的直接作用是抑制的（AB错）。","","N"],["2009-N10",5,"第3节 胃内消化","内因子",2009,10,"A","","行胃大部切除的患者易产生巨幼红细胞贫血的原因是",[["A","壁细胞数量减少，内因子分泌减少"],["B","壁细胞数量减少，胃酸分泌减少"],["C","主细胞数量减少，蛋白酶原分泌减少"],["D","胃容积减少，储存食物量减少"]],"A","行胃大部切除的患者，壁细胞数量减少，内因子分泌减少（A对），维生素B₁₂失去内因子的保护而被肠内水解酶破坏，出现吸收障碍。维生素B₁₂是甲硫氨酸合成酶的辅酶，缺乏时N₅-CH₃-FH₄上的甲基不能转移给同型半胱氨酸，这不仅影响甲硫氨酸的合成，同时也影响了四氢叶酸的再生，使组织中游离的四氢叶酸含量减少，导致核酸合成障碍，使核的发育和成熟落后于含血红蛋白的胞浆，胞体增大，出现巨幼红细胞性贫血（十版生物化学与分子生物学P189）。虽然胃蛋白酶和胃酸可促进维生素B₁₂的释放，但二者并不是产生巨幼红细胞的主要原因（BC错）。","","N"],["2009-N11",5,"第4节 小肠内消化","胆汁的性质和成分",2009,11,"A","","胆汁中与消化有关的主要成分是",[["A","消化酶"],["B","胆盐"],["C","卵磷脂"],["D","胆固醇"]],"B","胆汁中含有水、胆盐、卵磷脂、胆固醇和胆色素等有机物和Na⁺、K⁺、Ca²⁺、HCO₃⁻等无机物，但是不含有消化酶（A错）。胆盐、卵磷脂（C错）和胆固醇（D错）等均可作为乳化剂，降低脂肪的表面张力，通过乳化作用促进脂肪的消化吸收，但是发挥主要作用的是胆盐（B对）。","","N"],["2009-N12",6,"第2节 体温及其调节","主要产热器官",2009,12,"A","","安静状态下，人体产热量最高的器官或组织是",[["A","心脏"],["B","脑"],["C","肝"],["D","肾"]],"C","体内的热量由三大营养物质在组织细胞中进行分解代谢及机体利用ATP时产生，因此，代谢水平高的组织器官，其产热量也大，反之则产热量小。人体在安静时主要由内脏产热，其中尤其以肝脏代谢最旺盛，产热量最高（C对）。人体在运动时，骨骼肌则成为主要的产热器官。","","N"],["2009-N13",6,"第2节 体温及其调节","自主性体温调节",2009,13,"A","","循环系统实现体温调节的主要途径是",[["A","增加心输出量"],["B","调节血液温度"],["C","改变皮肤血流量"],["D","控制血流速度"]],"C","体温调节是通过调节产热和散热的平衡而实现的。人的主要散热部位是皮肤（十版生理学P207），当皮肤温度高于环境温度时，通过辐射、传导和对流的方式散热；当皮肤温度低于环境温度时，通过蒸发散热的方式散热。皮肤散热量的多少，取决于皮肤和周围环境之间的温度差，而皮肤温度的高低与皮肤血流量密切相关（十版生理学P208），因此机体可通过改变皮肤血流量来调节皮肤散热量，从而实现对体温的调节（C对）。","","N"],["2009-N14",7,"第3节 肾小管和集合管的物质转运功能","葡萄糖和氨基酸的重吸收",2009,14,"A","","肾小管将滤液中葡萄糖全部重吸收的主要部位是",[["A","近端小管"],["B","髓袢降支"],["C","髓袢升支粗段"],["D","远曲小管和集合管"]],"A","肾小囊超滤液中的葡萄糖浓度与血浆相等，但正常情况下，尿中几乎不含葡萄糖，表明葡萄糖全部被重吸收。微穿刺实验证明，滤过的葡萄糖均在近端小管（A对），特别是近端小管的前半段被重吸收。小管液中的葡萄糖是通过近端小管上皮细胞顶端膜中的Na⁺-葡萄糖同向转运体，以继发性主动转运的方式被转入细胞的。","","N"],["2009-N15",7,"第5节 尿生成的调节","血浆晶体渗透压",2009,15,"A","","大量饮水后，尿量增多的主要原因是",[["A","肾血流量增加"],["B","醛固酮分泌减少"],["C","抗利尿激素分泌减少"],["D","血浆胶体渗透压降低"]],"C","饮大量清水后，血浆晶体渗透压下降，抗利尿激素（血管升压素）分泌减少，进而造成肾小管和集合管对水的重吸收减少，尿量增多（C对）。","","N"],["2009-N16",8,"第3节 视觉","视网膜细胞的联系",2009,16,"A","","视网膜中央凹处对光的感受分辨力高的主要原因是",[["A","感光细胞密度大"],["B","感光细胞兴奋性高"],["C","感光细胞中感光色素含量高"],["D","传入通路的会聚程度小"]],"D","视网膜的中央凹是视锥细胞高度集中的部位，且此处仅有视锥细胞的分布，在中央凹处常见一个视锥细胞仅与一个双极细胞相联系，然后又只与一个神经节细胞相连接，这种单线式联系可以使得视锥细胞有较高的分辨能力（D对），因此人眼的分辨能力以中央凹处最强。","","N"],["2009-N17",8,"第4节 听觉","耳蜗的功能结构要点",2009,17,"A","","听觉器官的感音换能装置——螺旋器所在的部位是",[["A","盖膜"],["B","卵圆窗膜"],["C","基底膜"],["D","前庭膜"]],"C","耳蜗是感音装置所在部位，在耳蜗的横断面上，可见其被两个膜分为三个腔（三个腔分别称为前庭阶、蜗管和鼓阶），这两个膜分别是前庭膜和基底膜，听觉感受器螺旋器位于基底膜上（C对）。卵圆窗膜位于耳蜗底部，为耳蜗感受听骨链声波振动的部位（十版生理学P269），盖膜是位于耳蜗基底膜上方的一层薄膜（十版生理学P269）。","","N"],["2009-N18",9,"第1节 神经系统功能活动的基本原理","中枢兴奋传播的特征",2009,18,"A","","下列化学性突触传递特征的叙述，正确的是",[["A","双向传播"],["B","不衰减传递"],["C","兴奋节律不变"],["D","对内环境变化敏感"]],"D","在中枢神经系统内，兴奋性化学传递明显不同于神经纤维上的冲动传导（十版生理学P300），其特征主要表现为以下几个方面：①单向传递：在反射活动中，兴奋经化学性突触传递，只能从突触前末梢传向突触后神经元，这一现象称为单向传播（A错）；②中枢延搁：兴奋在中枢传播时往往需要较长时间，这一现象称为中枢延搁；③总和：在反射活动中，单根神经纤维的传入冲动一般不能使中枢发出传出效应，需有若干神经纤维的传入冲动同时或几乎同时到达同一中枢，发生空间和时间的总和，才可能产生传出效应；④兴奋节律的改变：如果测定某一反射弧的传入神经（突触前神经元）和传出神经（突触后神经元）在兴奋传递过程中的放电频率，两者往往不同。这是因为突触后神经元常同时接受多突触前神经元的突触传递，突触后神经元自身的功能状态也可能不同，且反射中枢常经过多个中间神经元接替，因此最后传出冲动的频率（兴奋节律）取决于各种影响因素的综合效应，即在此过程中兴奋节律可能发生改变（C错）；⑤后发放与反馈；⑥对内环境变化敏感和易疲劳：因为突触间隙与细胞外液相通，因此内环境理化因素的变化，如缺氧、CO₂过多、麻醉剂以及某些药物等均可影响化学性突触传递（D对）。另外，用高频电脉冲连续刺激突触前神经元，突触后神经元的放电频率将逐渐降低（B错）；而将同样的刺激施加于神经纤维，则神经纤维的放电频率在较长时间内不会降低。说明突触传递相对容易发生疲劳，其原因可能与递质的耗竭有关。","","N"],["2009-N19",9,"第5节 脑电活动及睡眠与觉醒","觉醒与睡眠的产生机制",2009,19,"A","","脑干网状结构上行激动系统的主要功能是",[["A","形成模糊的感觉"],["B","激发情绪生理反应"],["C","起上行唤醒作用"],["D","维持躯体姿势的平衡"]],"C","网状结构是指在脑干内除界限清楚、功能明确的神经细胞核团和神经纤维束外的神经细胞和神经纤维交织成网状的结构，分布在从脊髓到丘脑底部各个部位。网状结构是个多突触系统，神经元的联系在此高度聚合，形成复杂的神经网络，使各种特异感觉的传入失去专一性，其主要功能在于通过非特异投射系统维持和改变大脑皮层的兴奋状态，从而起到上行唤醒作用（C对），故又称网状结构上行激动系统。","","N"],["2009-N20",10,"第2节 下丘脑-垂体及松果体内分泌","调节新陈代谢",2009,20,"A","","生长激素分泌过多的患者可出现",[["A","尿氮含量增加"],["B","血糖升高甚至出现尿糖"],["C","血中脂肪酸含量降低"],["D","血中氨基酸含量降低"]],"B","生长激素（GH）能调节糖、脂肪、蛋白质等物质代谢：生长激素可抑制外周组织摄取和利用葡萄糖，减少葡萄糖消耗，使血糖升高甚至出现尿糖（B对）；生长激素可激活激素敏感的脂肪酶，促进脂肪分解，使血中的脂肪酸含量增加（C错）；生长激素可促进氨基酸进入肝外组织合成蛋白质，使血中的氨基酸含量降低（D对），减少尿氮（A错），呈正氮平衡。故本题的正确答案应为BD，但给出的参考答案仅为B。","","N"],["2009-N21",10,"第4节 甲状旁腺、维生素D与甲状腺C细胞内分泌","概述",2009,21,"A","","正常成年人，调节血钙平衡最重要的激素是",[["A","皮质醇"],["B","甲状旁腺激素"],["C","生长激素"],["D","甲状腺激素"]],"B","甲状旁腺激素（PTH）由甲状旁腺主细胞合成和分泌，具有升高血钙、降低血磷的功能，是人体调节血钙平衡最重要的激素（B对）。皮质醇、生长激素和甲状腺激素对血钙平衡均有调节作用，但重要性远不如甲状旁腺激素（ACD错）。","","N"],["2009-N22",11,"第2节 女性生殖功能及其调节","月经周期各期的内分泌调控",2009,22,"A","","下列哪种激素能在排卵前一天左右诱发排卵所必需的LH峰",[["A","雌二醇"],["B","孕酮"],["C","卵泡刺激素"],["D","雄激素"]],"A","在排卵前一天左右，血中雌激素（雌二醇为主）浓度到达最高值，形成月经周期中雌激素的第一高峰。雌激素（A对）通过正反馈机制，促进下丘脑GnRH分泌增强，进而刺激腺垂体分泌黄体生成素（LH），形成诱发排卵所必需的LH峰。","","N"],["2009-N23",4,"第1节 肺通气","弹性阻力和顺应性",2009,23,"A","","平静呼吸时，吸气的阻力主要来源于",[["A","肺泡内液-气表面张力"],["B","肺弹性成分的回缩力"],["C","胸廓弹性回缩力"],["D","气道阻力"]],"A","肺通气过程中所遇到的阻力为肺通气的阻力，可分为弹性阻力和非弹性阻力两类，前者包括肺的弹性阻力和胸廓的弹性阻力，后者包括气道阻力、惯性阻力和组织的黏滞阻力。平静呼吸时，弹性阻力约占肺通气总阻力的70％，非弹性阻力约占30％（D错）。吸气状态下，胸廓无变形，无弹性阻力（弹性回缩力）（C错），肺弹性阻力是肺吸气时的主要弹性阻力，包括占2/3的肺泡表面张力（A对）和占1/3的肺弹性成分的回缩力（B错）。","","N"],["2009-N24",2,"第1节 血液生理概述","血浆渗透压",2009,24,"A","","血浆渗透压的高低主要决定于",[["A","血浆蛋白总量"],["B","白蛋白含量"],["C","NaCl浓度"],["D","KCl浓度"]],"C","渗透压指的是溶质分子通过半透膜的一种吸水力量，其大小取决于溶质颗粒数目的多少，而与溶质的分子量、半径等特性无关。由于血浆中晶体溶质数目远远大于胶体数目，所以血浆渗透压主要由晶体渗透压构成，晶体渗透压又主要来自Na⁺和Cl⁻，故血浆渗透压的高低主要决定于NaCl浓度（C对）。","","N"],["2009-N121",3,"第4节 心血管活动的调节","动脉血压的长期调节",2009,121,"B","","动脉血压的短期调节主要依靠",[["A","压力感受性反射"],["B","化学感受性反射"],["C","心肺感受器反射"],["D","肾-体液控制机制"]],"A","根据各种神经、体液因素对动脉血压调节的时程，可将动脉血压调节分为短期调节和长期调节。短期调节是指对短时间内发生的血压变化进行调节，主要是经压力感受性反射（十版生理学P123）（A对）等神经调节方式，通过对阻力血管口径及心脏活动的调节来实现的；长期调节是指在较长时间内（数小时，数天，数月或更长）发生的血压变化进行调节，主要是通过肾对细胞外液量的调节实现的：当体内细胞外液量增多时，血量增多，血量和循环系统容量之间的相对关系发生改变，使动脉血压升高，而当动脉血压升高时，能直接导致肾排水和排钠增加，将过多的体液排出体外，从而使血压恢复到正常水平；体内细胞外液量减少时，发生相反的过程，即肾排水和排钠减少，使体液量和动脉血压恢复。这种机制被称为肾-体液控制机制。","","N"],["2009-N122",3,"第4节 心血管活动的调节","动脉血压的长期调节",2009,122,"B","","动脉血压的长期调节主要依靠",[["A","压力感受性反射"],["B","化学感受性反射"],["C","心肺感受器反射"],["D","肾-体液控制机制"]],"D","根据各种神经、体液因素对动脉血压调节的时程，可将动脉血压调节分为短期调节和长期调节。短期调节是指对短时间内发生的血压变化进行调节，主要是经神经调节方式，通过对阻力血管口径及心脏活动的调节来实现的；长期调节是指在较长时间内（数小时，数天，数月或更长）发生的血压变化进行调节，主要是通过肾对细胞外液量的调节实现的：当体内细胞外液量增多时，血量增多，血量和循环系统容量之间的相对关系发生改变，使动脉血压升高，而当动脉血压升高时，能直接导致肾排水和排钠增加，将过多的体液排出体外，从而使血压恢复到正常水平；体内细胞外液量减少时，发生相反的过程，即肾排水和排钠减少，使体液量和动脉血压恢复。这种机制被称为肾-体液控制机制（D对）。","","N"],["2009-N123",9,"第1节 神经系统功能活动的基本原理","乙酰胆碱及其受体",2009,123,"B","","乙酰胆碱与M受体结合引起收缩或收缩力增强的肌肉是",[["A","心肌"],["B","血管平滑肌"],["C","虹膜辐射状肌"],["D","支气管平滑肌"]],"D","M受体即毒蕈碱受体，为胆碱能受体的一种分型，分布于大多数副交感节后纤维支配的效应细胞、交感节后纤维支配的汗腺和骨骼肌血管的平滑肌细胞膜上。乙酰胆碱与M受体结合可引起M样作用，包括心脏活动受抑制（心率减慢、传导减慢、心肌收缩力减弱）（A错），支气管平滑肌（D对）、胃肠平滑肌、膀胱逼尿肌，虹膜环行肌收缩，消化腺、汗腺分泌增加和血管平滑肌舒张（B错）等。虹膜辐射状肌又称瞳孔开大肌，虹膜辐射状肌不含M受体（C错），而含α₁受体（肾上腺能受体），可在去甲肾上腺素的作用下收缩（十版生理学P297）。","","N"],["2009-N124",9,"第1节 神经系统功能活动的基本原理","NE和肾上腺素及其受体",2009,124,"B","","去甲肾上腺素与β受体结合引起收缩或收缩力增强的肌肉是",[["A","心肌"],["B","血管平滑肌"],["C","虹膜辐射状肌"],["D","支气管平滑肌"]],"A","肾上腺能受体可分为α型肾上腺素能受体和β型肾上腺素能受体，α型受体又可分为α₁和α₂两种亚型，β型受体可分为β₁、β₂、β₃三种亚型。心肌主要存在β₁受体，所产生的效应是兴奋性的，包括心率加快、传导加快、心肌收缩力增强等（A对）。血管平滑肌既有α₁受体，也有β₂受体，α₁受体所产生的效应是兴奋性的，引起血管收缩，β₂受体所产生的效应是抑制性的，引起血管舒张（B错）。虹膜辐射状肌只存在α₁受体（C错）。支气管平滑肌存在β₂受体，所产生的效应是支气管平滑肌舒张（D错）。","","N"],["2009-N125",9,"第4节 神经系统对内脏活动、本能行为和情绪的调节","交感神经系统的功能",2009,125,"B","","交感神经兴奋时，可引起",[["A","骨骼肌收缩"],["B","胰岛素分泌"],["C","糖原分解减少"],["D","皮肤血管收缩"]],"D","大多数交感节后纤维释放的递质是去甲肾上腺素（除支配汗腺和骨骼肌血管的交感节后纤维释放乙酰胆碱外），交感神经系统的活动与各器官上去甲肾上腺素受体的分布有关。交感神经兴奋时，作用于胰岛β细胞（即B细胞）上的α₂受体抑制胰岛素分泌（B错）；作用于骨骼肌细胞的β₂受体促进肌糖原的分解（C错）；作用于皮肤血管的α₁受体使皮肤血管收缩（D对）。骨骼肌收缩由躯体运动神经（十版生理学P380）支配，而不受内脏运动神经（交感神经和副交感神经）控制（A错），此处“骨骼肌”注意勿与“骨骼肌血管”相混淆，后者受内脏运动神经控制。交感神经兴奋的状态可以用机体在剧烈运动时的生理状态来协助记忆：机体在剧烈运动时交感神经兴奋（十版生理学P322），心率加快、心肌收缩力增强，心输出量增加，目的是为全身的肌肉提供更多的血液和氧气；呼吸运动加强，支气管平滑肌舒张，肺泡通气量，目的是为了血液提供更多的氧气；皮肤、肾、胃肠等全身各处的血管平滑肌均收缩，但骨骼肌血管舒张，目的是为了让血液重新分配，为肌肉提供更多的血液；由于全身血液分配至骨骼肌，导致胃肠道供血不足，不利于胃肠道进行消化和吸收，故消化道平滑肌舒张，括约肌收缩，消化腺分泌减少；剧烈运动时，甲状腺激素、胰高血糖素等分解代谢的激素分泌增多，糖原分解增加，目的是为了骨骼肌提供更多的能量来源等等。","","N"],["2009-N126",9,"第4节 神经系统对内脏活动、本能行为和情绪的调节","副交感神经系统的功能",2009,126,"B","","副交感神经兴奋时，可引起",[["A","骨骼肌收缩"],["B","胰岛素分泌"],["C","糖原分解减少"],["D","皮肤血管收缩"]],"B","骨骼肌收缩由躯体运动神经（十版生理学P380）支配，而不受内脏运动神经（交感神经和副交感神经）控制（A错），此处“骨骼肌”注意勿与“骨骼肌血管”相混淆，后者受内脏运动神经控制。副交感神经兴奋时释放乙酰胆碱，可直接作用于β细胞膜中的M受体，刺激胰岛素分泌，也可通过引起胃肠激素分泌增多而间接促进胰岛素分泌（B对）。糖原的分解主要受胰高血糖素、肾上腺素（十版生物化学与分子生物学P127）和交感神经的调节，而不受副交感神经的直接调节（副交感神经主要调节糖原的合成），但副交感神经可以通过刺激胰岛素分泌，间接抑制糖原的分解（C对），故本题答案存在争议。与糖原分解类似，皮肤血管也是只受交感神经的调节，而不受副交感神经的调节（D错）。","","N"],["2009-N151",4,"第1节 肺通气","弹性阻力和顺应性",2009,151,"X","","正常情况下，存在于肺泡内侧液气界面的肺表面活性物质有助于",[["A","降低吸气阻力，减少吸气做功"],["B","降低呼气阻力，减少呼气做功"],["C","维持大、小肺泡容积和压力的稳定性"],["D","防止肺水肿的发生"]],"ACD","由于肺表面活性物质可以降低肺泡表面张力，肺泡表面张力是肺弹性阻力（弹性回缩力）的主要来源，故肺表面活性物质有助于减少肺的弹性阻力。又由于肺的弹性阻力是吸气的阻力，呼气的动力，故肺表面活性物质能够降低吸气的阻力（A对）和呼气的动力（B错）。肺表面活性物质可以降低肺泡表面张力，进而降低肺泡表面张力对肺毛细血管血浆和肺组织间液可产生“抽吸”作用，从而防止肺水肿的发生（D对）。根据Laplace定律（十版生理学P141），肺泡的回缩力与肺泡半径成反比，即小肺泡的回缩力大，而大肺泡的回缩力小，但肺表面活性物质的存在，降低了小肺泡的回缩力（小肺泡分布的肺表面活性物质密度较大，降低了表面张力），从而避免了小肺泡萎陷关闭而大肺泡过度膨胀的情况，保持了大小肺泡容积和压力的稳定性（C对）。","","N"],["2009-N152",5,"第3节 胃内消化","胃排空及其控制",2009,152,"X","","促进胃内容物向十二指肠排空的因素有",[["A","迷走-迷走反射"],["B","壁内神经丛反射"],["C","肠-胃反射"],["D","促胰液素"]],"AB","食物由胃排入十二指肠的过程称为胃排空。一般胃内因素能够促进胃排空〔通过迷走-迷走长反射（A对）和壁内神经丛短反射（B对）等〕，而十二指肠内因素则能抑制胃排空〔通过肠-胃反射（C错）、促胰液素（D错）、缩胆囊素、抑胃肽等〕。","","N"],["2009-N153",7,"第5节 尿生成的调节","肾素分泌的调节",2009,153,"X","","引起肾的颗粒细胞释放肾素的因素",[["A","血浆晶体渗透压降低"],["B","肾交感神经兴奋增强"],["C","肾小球滤过的Na⁺量增多"],["D","肾血流量减少"]],"BD","肾素-血管紧张素-醛固酮系统对尿生成的调节作用是通过机体对肾素分泌的调节来实现的，肾素的分泌受多方面因素的调节，包括肾内机制、神经和体液机制：①肾内机制：肾内机制是指可在肾内完成的调节，其感受器是位于入球小动脉的牵张感受器和致密斑。前者能感受肾动脉的灌注压（对动脉壁的牵张程度），后者能感受流经该处小管液中的Na⁺量。当肾血流量减少时，肾动脉灌注压降低，入球小动脉壁受牵拉的程度减小，则刺激肾素释放（D对）；反之，当灌注压升高时则肾素释放减少。当肾小球滤过率减少或其他原因导致流经致密斑的小管液中Na⁺量减少时，肾素释放增加；反之，流经致密斑的Na⁺量增加时则肾素释放减少（C错）。②神经机制：肾交感神经兴奋时释放去甲肾上腺素，后者作用于颗粒细胞膜中的β受体，可直接刺激肾素释放（B对）。如急性大失血，血量减少，血压下降，可反射性兴奋肾交感神经，从而使肾素释放增加。③体液机制：循环血液中的儿茶酚胺（肾上腺素和去甲肾上腺素），肾内生成的PGE₂和 PGI₂，均可刺激颗粒细胞释放肾素，低盐饮食也可显著增加肾素表达水平。AngⅡ、血管升压素（抗利尿激素）、心房钠尿肽、内皮素和NO则可抑制肾素的释放。血浆晶体渗透压降低即血浆中Na⁺浓度降低，血浆中Na⁺浓度降低时超滤液中的Na⁺浓度也降低，使流经致密斑的小管液中Na⁺量随之减少，引起肾素释放增加（A 对）。故本题的正确答案应为ABD，但给出的参考答案为BD。","","N"],["2009-N154",10,"第6节 胰岛内分泌","对糖代谢的作用",2009,154,"X","","胰岛素降低血糖浓度的机制有",[["A","促进组织细胞对糖的摄取和利用"],["B","抑制蛋白质分解，减少糖的来源"],["C","促进肝糖原和肌糖原的合成，并抑制糖原异生"],["D","促进葡萄糖转变成为脂肪酸，并储存于脂肪组织"]],"ABCD","胰岛素具有降低血糖的作用，它是通过增加血糖的去路及减少血糖的来源实现的。增加血糖的去路包括：①促进肝脏和肌肉摄取、储存、利用葡萄糖，合成肝糖原和肌糖原（AC对）；②促进脂肪的合成和储存，使葡萄糖转化为脂肪酸，储存于脂肪组织（D对）。减少血糖的来源包括：①抑制糖原分解有关酶的活性，阻止糖原分解；②抑制糖异生有关酶的活性，抑制糖原异生（C对）；③抑制蛋白质的分解，减少生糖氨基酸的来源，最终减少糖的来源（B对）等。","","N"],["2009-N155",8,"第1节 感觉概述","感受器的适应现象",2009,155,"X","","下列感受器中，属于慢适应感受器的有",[["A","环层小体"],["B","关节囊感受器"],["C","肌梭"],["D","颈动脉体"]],"BCD","若以一个强度恒定的刺激持续作用于某一感受器，相应的感觉神经纤维上的动作电位频率将随刺激持续时间的延长而降低，这一现象称为感受器的适应。根据感受器发生适应的快慢，可将感受器分为快适应感受器和慢适应感受器两类。皮肤环层小体是快适应感受器（A错），因此皮肤对触压觉的变化很容易适应。慢适应感受器如肌梭（C对）、关节囊感受器（B对）和化学感受器（D对）有利于机体对某些功能状态进行长时间持续的监测，并根据其变化随时调整机体的活动：肌梭和关节囊感受器不易发生适应，有利于机体及时躲避有害刺激，避免肌肉和关节受到损害。化学感受器（十版生理学P158）不易发生适应，有利于机体对动脉血中PO₂、PCO₂和H⁺浓度进行实时的监控和调节。","","N"],["2009-N156",1,"第1节 细胞膜的物质转运功能","易化扩散",2009,156,"X","","与发生细胞生物电有关的跨膜物质转运形式有",[["A","经载体易化扩散"],["B","经化学门控通道易化扩散"],["C","经电压门控通道易化扩散"],["D","原发性主动转运"]],"BCD","涉及带电离子跨膜移动的跨膜物质转运形式与发生细胞生物电有关。经化学门控通道易化扩散，最典型的代表为骨骼肌终板膜中N₂型乙酰胆碱受体介导的Na⁺和K⁺的跨膜移动，导致终板膜电位改变（B对），最终引起骨骼肌细胞兴奋；经电压门控通道易化扩散，最典型的代表为去极化过程中电压门控的Na⁺通道介导的Na⁺内流，介导了去极化过程中的电位变化（C对）。原发性主动转运最典型的代表为钠-钾泵，钠-钾泵每分解一分子ATP可以逆浓度差将3个Na⁺移出胞外，将2个K⁺移入胞内，净移出一个正电荷，使膜内电位的负值增加（D对）。经载体介导的易化扩散通常介导葡萄糖、氨基酸、核苷酸等小分子溶质的跨膜物质转运，不产生生物电（A错）。","","N"],["2010-N1",0,"第4节 机体的内环境、稳态和生物节律","机体的内环境",2010,1,"A","","关于体液的叙述正确的是",[["A","分布在各部分的体液量大体相等"],["B","各部分体液彼此隔开又相互沟通"],["C","各部分体液的成分几乎没有差别"],["D","各部分体液中最活跃的是细胞内液"]],"B","人体内体液包括了细胞内液和细胞外液两种，其中细胞内液约占正常成年人体重的40%，细胞外液约占正常成年人体重的20%，细胞外液又包括了组织间液和血浆，组织间液约占体重的15%，血浆约占体重的5%，故分布在人体各部分的体液量是不相等的（A错）。细胞内液和细胞外液被细胞膜隔开，成分存在较大差别，如细胞外高钠、高钙、高氯，细胞内高钾等，但细胞内液和细胞外液可以通过细胞膜进行跨膜物质转运（互相沟通），跨膜物质转运的形式包括单纯扩散、易化扩散、主动转运等。同样，组织间液和血浆被毛细血管壁分隔，成分存在较大差别，如血浆中含有大量的血浆蛋白，而组织液中蛋白含量很少，血浆蛋白分子量大，不易通过毛细血管壁，但水和晶体物质等小分子物质却可以自由通过（互相沟通）（B对C错）。由于血浆是沟通各部分体液并与外界环境进行物质交换的重要媒介，因而各部分体液中最为活跃的部分是血浆，而不是细胞内液（D错）。","","N"],["2010-N2",1,"第2节 细胞的信号转导","G蛋白耦联受体",2010,2,"A","","需要依靠细胞内cAMP来完成跨膜信号转导的膜受体是",[["A","G蛋白耦联受体"],["B","离子通道型受体"],["C","酪氨酸激酶受体"],["D","鸟苷酸环化酶受体"]],"A","cAMP是G蛋白耦联受体介导信号转导过程（A对）中的第二信使物质，cAMP在G蛋白效应器腺苷酸环化酶（AC）的催化下合成，在G蛋白效应器磷酸二酯酶（PDE）的催化下分解。","","N"],["2010-N3",1,"第3节 细胞的电活动","阈电位",2010,3,"A","","外加刺激引起细胞兴奋的必要条件是",[["A","刺激达到一定的强度"],["B","刺激达到一定的持续时间"],["C","膜去极化达到阈电位"],["D","局部兴奋必须发生总和"]],"C","膜去极化达到阈电位是外加刺激引起细胞兴奋（发生动作电位）的必要条件（C对），刺激强度和刺激的持续时间是能够影响膜是否能够达到阈电位的影响因素，刺激强度大小和刺激持续时间长短与动作电位的发生无独立、直接的关联（AB错）；局部电位发生总和未必能去极化达到阈电位水平（D错）。","","N"],["2010-N4",2,"第2节 血细胞生理","红细胞生成所需物质",2010,4,"A","","发生巨幼细胞贫血的原因是",[["A","缺铁"],["B","蛋白质摄入不足"],["C","缺乏维生素B₁₂和叶酸"],["D","EPO生成不足"]],"C","叶酸以四氢叶酸的形式起作用，四氢叶酸作为一碳单位的载体，在体内参与嘌呤核苷酸和胸腺嘧啶核苷酸的合成，故叶酸缺乏时，嘌呤核苷酸和胸腺嘧啶核苷酸合成减少，红细胞中DNA合成受阻，细胞分裂增殖速度下降，细胞体积增大，核内染色质疏松，影响红细胞成熟，导致巨幼细胞性贫血（C对）。体内叶酸多以N⁵-甲基四氢叶酸形式存在，发挥作用时，N⁵-甲基四氢叶酸与同型半胱氨酸反应生成四氢叶酸与甲硫氨酸（十版生物化学与分子生物学P189），此反应需N⁵-甲基四氢叶酸转甲基酶催化，而维生素B₁₂是该酶的辅酶成分，故当维生素B₁₂缺乏时，转甲基反应受阻，影响四氢叶酸的周转利用，间接影响胸腺嘧啶脱氧核苷酸的生成，同样影响红细胞成熟，导致巨幼细胞性贫血（C对）。缺铁时，血红素合成量减少，发生小细胞低色素性贫血（缺铁性贫血）（十版内科学P549）（A错）。EPO主要由肾脏产生，EPO生成不足常见于肾功能不全患者，发生肾性贫血，为正常细胞性贫血（D错）。蛋白质是合成血红蛋白的原料，蛋白质摄入不足时，机体出现负氮平衡，血红蛋白合成减少，新生红细胞也相应减少，发生贫血，为正常细胞性贫血（B错）。","","N"],["2010-N5",2,"第3节 生理性止血","凝血因子",2010,5,"A","","肝硬化患者易发生凝血障碍和出血现象，其主要原因是",[["A","凝血因子合成减少"],["B","血小板生成减少"],["C","维生素K缺乏"],["D","抗凝血酶灭活延缓"]],"A","大多数凝血因子由肝脏合成，肝硬化时，肝细胞受损严重，使其合成凝血因子的能力下降，凝血因子合成减少，患者发生凝血障碍和出血现象（A对）。血小板由骨髓成熟的巨核细胞胞质裂解脱落而来，主要受血小板生成素（TPO）的调节，而TPO主要由肝细胞产生，肝硬化时TPO合成减少，间接导致血小板生成减少，但血小板主要影响出血时间，对凝血过程影响较小（参考1992N56A），因而血小板生成减少不是肝硬化患者易发生凝血障碍和出血现象的主要原因（B错）。肝硬化时胆汁的分泌和排出障碍，造成脂肪消化不良，脂肪吸收减少，间接导致脂溶性的维生素K吸收减少，产生维生素K缺乏症，肝硬化时常需要酌情补充维生素K，故维生素K缺乏也是肝硬化患者易发生凝血障碍和出血现象的原因，本题问的是主要原因，相对凝血因子合成减少来说，维生素K缺乏的影响是次要的（C错）。肝脏是合成抗凝血酶的主要器官，因此，肝功能障碍主要引起抗凝血酶合成减少，而不是灭活延缓（D错）。","","N"],["2010-N6",3,"第2节 心脏的电生理学及生理特性","窦房结细胞动作电位",2010,6,"A","","下列关于窦房结P细胞4期自动去极化机制的叙述，错误的是",[["A","Na⁺内流进行性增强"],["B","K⁺外流进行性衰减"],["C","Ca²⁺内流进行性增强"],["D","Cl⁻内流进行性衰减"]],"D","参与窦房结P细胞4期自动去极化的离子流较为复杂，目前仍未完全阐明，一般认为至少与Iₖ、If和ICa-T三种离子流有关：①Iₖ电流，Iₖ通道在动作电位0期去极化时就已开始激活开放，以后K⁺外流逐渐增强，成为窦房结P细胞3期复极的主要原因。但Iₖ通道在复极化接近最大复极电位时去激活关闭，K⁺的外流逐渐减少。由于此时外向的Iₖ电流还相当大，因此其衰减而使内向电流相对增强的作用也相当大。可见，Iₖ通道的去激活关闭所造成的K⁺外流进行性衰减（B对）是窦房结P细胞4期自动去极化最重要的离子基础；②If电流，If电流是一种进行性增强的内向离子流，主要是Na⁺内流（A对），在浦肯野细胞4期自动去极化过程中起重要作用。If通道的最大激活电位约-100mV。而在正常情况下，窦房结P细胞的最大复极电位约-70mV。在此电位水平，If通道的激活十分缓慢，电流强度也较小，因此If电流在窦房结P细胞4期自动去极化过程中所起作用可能不大；③T型钙流，除L型钙通道外，窦房结P细胞还存在T（transient）型钙通道，其阈电位约为-50mV。当4期自动去极化到-50mV时，T型钙通道被激活开放（C对），引起少量的内向T型钙流（ICa-T），成为4期自动去极化后期的一个组成成分，虽然ICa-T是快速衰减的内向电流，ICa-T的生理作用在于使细胞膜电位继续去极化达到能使ICa-L激活的阈电位水平，后者的激活使Ca²⁺内流进行性增强，形成动作电位的上升支 。窦房结P细胞4期自动去极化与Cl⁻内流无关（D错，为本题正确答案）。","","N"],["2010-N7",3,"第3节 血管生理","影响静脉回心血量的因素",2010,7,"A","","由下蹲位突然起立时发生晕厥的主要原因是",[["A","静脉回心血量减少"],["B","循环血量减少"],["C","外周阻力增加"],["D","心率突然减慢"]],"A","由蹲位突然起立时与由平卧位突然站立时一样，血液重新分配，身体下肢等低垂部分的静脉因跨壁压增大而扩张，可容纳更多的血液，静脉回心血量减少，大脑供血不足，从而发生昏厥（A对）。","","N"],["2010-N8",4,"第1节 肺通气","非弹性阻力",2010,8,"A","","影响气道阻力的主要原因是",[["A","肺泡表面张力"],["B","支气管口径"],["C","气流形式和速度"],["D","肺组织的弹性阻力"]],"B","气道阻力是指气体流经呼吸道时气体分子之间和气体分子与气道壁之间的摩擦力，是非弹性阻力（气道阻力、惯性阻力和组织的黏滞阻力）的主要组成部分，受气道口径、气流速度和气流形式的影响，其中以气道口径最为重要（B对CD错）。肺泡表面张力是肺弹性阻力的主要来源（A错）。","","N"],["2010-N9",4,"第3节 气体在血液中的运输","Hb与O₂结合的特征",2010,9,"A","","下列关于发绀的叙述，错误的是",[["A","见于血中去氧Hb≥50g/L时"],["B","出现发绀通常表示缺O₂"],["C","出现发绀不一定缺O₂"],["D","缺O₂一定出现发绀"]],"D","发绀是指血液中去氧血红蛋白大于50g/L时（A对），使皮肤和黏膜呈青紫色改变的一种表现，也可称为紫绀。这种改变常发生在皮肤较薄，色素较少和毛细血管较丰富的部位，如唇，指（趾），甲床等。出现发绀通常表示缺O₂（B对），但也有例外，如高原性红细胞增多症时，红细胞增多，有发绀症状但并不缺O₂（C对），缺O₂也不一定出现发绀（D错，为本题正确答案），如严重贫血或CO中毒时，机体有缺氧但并不出现发绀。","","N"],["2010-N10",4,"第4节 呼吸运动的调节","肺牵张反射",2010,10,"A","","切断家兔双侧颈迷走神经后，呼吸运动的改变是",[["A","变浅变快"],["B","变浅变慢"],["C","变深变快"],["D","变深变慢"]],"D","肺牵张反射包括肺扩张反射和肺萎陷反射两个部分。肺扩张反射是肺扩张时抑制吸气活动的反射，可以使呼吸变浅变快；肺萎陷反射是肺萎陷时增强吸气活动的反射，可以使呼吸变深变慢。肺扩张反射和肺萎陷反射的传入神经均为迷走神经，切断迷走神经后，肺扩张反射被抑制的效应是呼吸变深变慢，肺萎陷反射被抑制的效应是呼吸变浅变快，动物实验表明，切断迷走神经的综合效应是呼吸变深变慢（D对）。","","N"],["2010-N11",5,"第3节 胃内消化","消化期的胃液分泌",2010,11,"A","","关于胃液分泌调节的叙述，正确的是",[["A","头期分泌主要是体液调节"],["B","胃期分泌兼有神经和体液调节"],["C","肠期分泌主要是神经调节"],["D","头期、胃期和肠期分泌都有自身调节"]],"B","进食可刺激胃液大量分泌，称为消化期的胃液分泌。根据消化道感受食物刺激的部位，将消化期的胃液分泌分为头期、胃期和肠期三个时相。这三个时期都受神经和体液因素的双重调节（B对），但头期主要接受神经调节（A错），肠期主要接受体液调节（C错）。头期、胃期和肠期分泌均不存在自身调节（D错）。","","N"],["2010-N12",5,"第4节 小肠内消化","促胰液素",2010,12,"A","","下列关于促胰液素生理作用的叙述，错误的是",[["A","促进胰腺细胞分泌胰酶"],["B","促进胰腺小导管分泌水和HCO₃⁻"],["C","促进肝胆汁分泌"],["D","抑制胃液分泌"]],"A","促胰液素由小肠上段黏膜的S细胞分泌，其生理功能极为广泛及多样化，且大部分功能与缩胆囊素（1990N147X）一致，生理学教材提及的功能包括：舒血管作用（七版生理学P170）、促进胰酶分泌（七版生理学P170 表6-3）（A？）、促进胆囊平滑肌收缩（七生理学版P170 表6-3）、抑制食管-胃括约肌收缩（七版生理学P170 表6-3）、收缩幽门括约肌（十版生理学P168）、促进胰腺外分泌部生长（十版生理学P168）、舒张食管下括约肌（十版生理学P171）、促进胃蛋白酶原分泌、抑制促胃液素和胃酸的分泌（十版生理学P168）（D对）、抑制胃的运动（十版生理学P168）、抑制胃排空（十版生理学P168）、促进胰腺小导管上皮细胞分泌水和HCO₃⁻分泌（十版生理学P181）（B对）、促进肝胆汁分泌（十版生理学P182）（C对）、促进小肠液分泌（十版生理学P183）、抑制小肠运动（十版生理学P184）、促进降钙素分泌（十版生理学P367）、促进胰岛素分泌（十版生理学P377）、抑制胰高血糖素分泌（十版生理学P378）等。本题的参考答案为A，略有争议，具有促进胰腺细胞分泌胰酶的激素主要是缩胆囊素（又称促胰酶素），但促胰液素也有较弱的促进胰酶分泌的作用。","","N"],["2010-N13",5,"第7节 吸收","蛋白质的吸收",2010,13,"A","","小肠上皮细胞顶端膜上可将寡肽转运入细胞的转运体是",[["A","Na⁺-氨基酸同向转运体"],["B","K⁺-氨基酸反向转运体"],["C","Na⁺-肽同向转运体"],["D","H⁺-肽同向转运体"]],"D","曾经认为，蛋白质只有水解为氨基酸后才能被吸收。现已证明，小肠内的寡肽（指由2～6个氨基酸残基组成的肽）也可被上皮细胞摄取。在上皮细胞顶端膜上存在二肽和三肽转运系统，称为H⁺-肽同向转运体（D对），可顺浓度梯度由肠腔向细胞内转运H⁺，同时逆浓度梯度将寡肽同向转运入细胞。进入细胞的二肽和三肽可被细胞内的二肽酶和三肽酶进一步分解为氨基酸，后者经基底侧膜上的氨基酸载体转运出细胞，然后进入血液循环。","","N"],["2010-N14",6,"第2节 体温及其调节","产热的形式",2010,14,"A","","新生儿棕色脂肪组织具有产热功能的关键性生物分子是",[["A","瘦素"],["B","解耦联蛋白"],["C","增食因子"],["D","脂联素"]],"B","脂肪组织包括白色脂肪组织和褐色脂肪组织。白色脂肪组织的作用主要是储存脂肪，褐色脂肪组织的作用主要是将脂肪代谢并且产生大量热量。新生儿体内含有较多的褐色脂肪组织，在褐色脂肪组织细胞的线粒体内膜中存在解耦联蛋白（UCP）（B对），当受到甲状腺激素、肾上腺素作用时，UCP就成为易化质子通道，H⁺顺浓度梯度沿UCP返回到线粒体基质中，使经线粒体呼吸链电子传递建立的质子跨膜电-化学势能以热能的形式释放出来，而不能用于合成ATP。瘦素（十版生理学P380）主要存在于白色脂肪组织中，其主要作用是调节体内脂肪储存量并维持机体的能量平衡。增食因子与瘦素的作用相反，是一种具有增强食欲作用的神经肽，与肥胖的发生有关。脂联素（十版生理学P380）是脂肪细胞分泌的一种内源性生物活性多肽，在糖与脂代谢中发挥重要作用。","","N"],["2010-N15",7,"第2节 肾小球的滤过功能","肾小球滤液的成分",2010,15,"A","","与血浆比较，原尿中物质含量明显改变的是",[["A","水"],["B","蛋白质"],["C","Na⁺、K⁺"],["D","葡萄糖"]],"B","血液流经肾小球毛细血管网时，除蛋白质分子外的血浆成分被滤过进入肾小囊腔而形成原尿，故与血浆相比，原尿中蛋白质含量明显降低（正常人原尿中不含蛋白质）（B对），而水，Na⁺、K⁺、葡萄糖等各种晶体物质的成分含量基本相同（ACD错）。","","N"],["2010-N16",7,"第3节 肾小管和集合管的物质转运功能","NH₃和NH₄⁺的分泌与H⁺和HCO₃⁻的转运的关系",2010,16,"A","","肾小管和集合管上皮细胞分泌NH₄⁺和NH₃的主要生理意义是",[["A","完成细胞内代谢"],["B","排泄体内毒素"],["C","维持机体酸碱平衡"],["D","维持机体电解质平衡"]],"C","在肾小管和集合管上皮细胞，NH₄⁺和NH₃的分泌与HCO₃⁻的生成相耦联，小管上皮细胞内的谷氨酰胺在谷氨酰胺酶、谷氨酸脱氢酶等酶的作用下生成NH₃和NH₄⁺，同时生成HCO₃⁻，NH₃和NH₄⁺分泌入小管腔，HCO₃⁻则进入血液循环。慢性酸中毒时可刺激肾小管和集合管上皮细胞谷氨酰胺的代谢，增加NH₄⁺和NH₃的排泄和生成HCO₃⁻。故氨的分泌也是肾脏维持机体酸碱平衡的重要机制之一（C对）。","","N"],["2010-N17",7,"第5节 尿生成的调节","血浆晶体渗透压",2010,17,"A","","促进血管升压素合成和分泌的最重要因素是",[["A","动脉血压降低"],["B","循环血量减少"],["C","血浆晶体渗透压升高"],["D","情绪紧张"]],"C","血管升压素的合成和分泌受多种因素调节：①体液渗透压的改变是最重要的因素，由于晶体渗透压是血浆渗透压的主要组成部分，因此血浆晶体渗透压的变化是调节血管升压素分泌的最重要因素（C对）；②循环血量减少（经心肺感受器）、动脉血压降低（经压力感受器）、情绪紧张等因素均能刺激血管升压素的合成和分泌，但相对于血浆晶体渗透压升高来说，是次要因素（ABD错）。八年制三版生理学P381指出在循环血量明显减少的情况下，循环血量的调节作用超过晶体渗透压的调节作用。本题答案存在争议。","","N"],["2010-N18",8,"第3节 视觉","瞳孔对光反射",2010,18,"A","","正常情况下，用手电筒灯光照射左眼时出现的反射性反应是",[["A","左侧瞳孔缩小，右侧瞳孔不变"],["B","右侧瞳孔缩小，左侧瞳孔不变"],["C","左侧瞳孔明显缩小，右侧瞳孔略有增大"],["D","左、右侧瞳孔同等程度缩小"]],"D","瞳孔对光反射的效应是双侧性的，光照一侧眼的视网膜时，双眼的瞳孔均缩小，称为互感性对光反射。所以用手电筒灯光照射左眼时出现的反射性反应是左、右侧瞳孔同等程度缩小（D对）。","","N"],["2010-N19",9,"第1节 神经系统功能活动的基本原理","神经对效应组织的营养性作用",2010,19,"A","","脊髓灰质炎患者病愈后常有肢体肌萎缩后遗症，其主要原因是",[["A","病毒对肌肉的直接侵害作用"],["B","神经的兴奋性支配作用减弱"],["C","神经支配由兴奋转为抑制"],["D","肌肉失去神经的营养性作用"]],"D","神经末梢可以释放某些营养性因子等，以调整所支配组织的代谢活动，影响其持久性的结构、生化和生理的变化，从而发挥营养性作用，脊髓灰质炎患者前角运动神经元变性死亡后，它所支配的肌肉将发生萎缩就是肌肉失去神经营养性作用的结果（D对）。","","N"],["2010-N20",9,"第3节 神经系统对躯体运动的调控","基底神经节的功能",2010,20,"A","","下列关于基底神经节运动调节功能的叙述，错误的是",[["A","发动随意运动"],["B","调节肌紧张"],["C","处理本体感觉传入信息"],["D","参与运动的设计"]],"A","迄今为止，关于基底神经节功能仍不十分清楚。毁损动物的基底神经节几乎不出现任何症状；而记录基底神经节神经元放电，发现其放电发生在运动开始之前；新纹状体内的中型多棘神经元很少或没有自发放电活动，仅在大脑皮层有冲动传来时才开始活动。根据这些观察，结合对人类基底神经节损伤后出现的症状、药物治疗效应及其机制分析，可以认为基底神经节可能参与随意运动的设计和程序编制（D对），并将一个抽象的设计转换为一个随意运动。基底神经节与随意运动的产生和稳定协调、肌紧张的调节（B对）、本体感受传入冲动信息的处理（C对）可能都有关，此外，基底神经节中某些核团还参与自主神经的调节、感觉传入、心理行为和学习记忆等功能活动（十版生理学P315）。发动随意运动的是大脑皮层，而不是基底神经节（A错，为本题正确答案）。","","N"],["2010-N21",10,"第3节 甲状腺内分泌","调节新陈代谢",2010,21,"A","","甲状腺素在生理浓度范围内对物质代谢的影响是",[["A","加强蛋白质分解，出现负氮平衡"],["B","抑制组织利用糖，使血糖浓度升高"],["C","促进胆固醇合成，更加速其转化"],["D","促进脂肪酸合成，并抑制其降解"]],"C","甲状腺激素（TH）对糖、脂肪、蛋白质的合成和分解代谢均有调节作用，十分复杂。就整体而言，在生理浓度范围内的甲状腺激素对糖、脂肪、蛋白质的合成和分解代谢均有调节作用，而分泌过量时则促进分解代谢的作用更明显一些。","","N"],["2010-N22",10,"第6节 胰岛内分泌","胰岛素的作用机制",2010,22,"A","","转导胰岛素对靶细胞生物学作用的共同信号蛋白是",[["A","IRS"],["B","GLUT"],["C","PI-3K"],["D","CaM"]],"A","IRS（insulin receptor substrate，胰岛素受体底物）是胰岛素发挥生物学作用的关键信号蛋白，广泛分布于胰岛素敏感组织细胞内。目前已发现人组织细胞内含有多种IRS，如IRS1-IRS4，分别表达于不同的组织细胞，参与不同的信号转导通路（A对）：IRS-1表达于各种组织细胞中，但主要是骨骼肌细胞；IRS-2也表达于各种组织细胞中，但主要是肝脏和胰岛β细胞；IRS-3存在于脑和脂肪等组织中；IRS-4分布于垂体和脑组织中。GLUT是葡萄糖转运体（glucose transporter），主要作用是作为葡萄糖跨膜转运的载体（P388）。PI-3K为磷脂酰肌醇3-激酶，主要作用是介导胰岛素对GLUT的激活。CaM为钙调蛋白，可与Ca²⁺结合为Ca²⁺-CaM复合物，激活各种Ca²⁺-CaM依赖的蛋白激酶（P29）。","","N"],["2010-N23",10,"第5节 肾上腺内分泌","对组织器官活动的影响",2010,23,"A","","通过允许作用保持血管平滑肌对儿茶酚胺敏感性的激素是",[["A","生长激素"],["B","血管升压素"],["C","皮质醇"],["D","ACTH"]],"C","允许作用（十版生理学P344）是指某激素对特定、组织或细胞没有直接作用，但其存在却是另一种激素发挥生物效应的必备基础，这是一种支持性作用。例如，糖皮质激素（皮质醇）（C对）本身对心肌和血管平滑肌并无直接增强收缩的作用，但只有在它存在时儿茶酚胺类激素才能充分发挥调节心血管活动的作用。","","N"],["2010-N24",11,"第3节 妊娠","胎盘的功能",2010,24,"A","","妊娠后期孕妇血中雌激素和孕激素处于高水平的原因是",[["A","下丘脑促垂体区分泌活动加强"],["B","腺垂体分泌活动加强"],["C","卵巢分泌活动加强"],["D","胎盘分泌活动加强"]],"D","在hCG的刺激下，月经黄体转变成妊娠黄体，妊娠黄体分泌孕激素和雌激素，以适应妊娠的需要。但是妊娠黄体的寿命只有10周，以后便发生退缩，与此同时胎盘分泌孕激素和雌激素，逐渐接替妊娠黄体作用，到了妊娠后期孕妇血中雌激素和孕激素主要由胎盘分泌（D对）。","","N"],["2010-N121",1,"第3节 细胞的电活动","电-化学驱动力及其变化",2010,121,"B","","当神经细胞处于静息电位时，电化学驱动力最小的离子是",[["A","Na⁺"],["B","K⁺"],["C","Ca²⁺"],["D","Cl⁻"]],"D","离子的电-化学驱动力可用膜电位与离子平衡电位的差值（Em-Ex）表示，差值愈大，离子受到的电-化学驱动力就愈大，反之则愈小。静息电位时，电化学驱动力最小的离子一定是平衡电位最接近静息电位的，K⁺ 的平衡电位（-102mV）接近于静息电位（-70mV），但并不等于静息电位，而是略大于静息电位，而 Cl⁻ 具有随跨膜电位进行被动分布的特性，其平衡电位能更接近于甚至等于静息电位（-76mV），故静息电位时，Cl⁻ 所受到的电-化学驱动力最小（D 对）。","","N"],["2010-N122",1,"第3节 细胞的电活动","电-化学驱动力及其变化",2010,122,"B","","当神经细胞处于静息电位时，电化学驱动力最大的离子是",[["A","Na⁺"],["B","K⁺"],["C","Ca²⁺"],["D","Cl⁻"]],"C","离子的电-化学驱动力可用膜电位与离子平衡电位的差值（Em-Ex）表示，差值愈大，离子受到的电-化学驱动力就愈大，反之则愈小。静息电位时，电化学驱动力最大的离子一定是平衡电位最远离静息电位的，以哺乳动物为例，神经细胞的静息电位约为-70mV，Ca²⁺、Na⁺、K⁺、Cl⁻的平衡电位分别为+125mV、+56mV、-102mV和-76mV，因此Ca²⁺的平衡电位偏离静息电位是最多的，静息时受到的电化学驱动力自然最大（C对）。","","N"],["2010-N123",3,"第5节 器官循环","冠脉循环的生理特点",2010,123,"B","","在一次心动周期中，冠状动脉血流量急剧降低的时相是",[["A","等容收缩期"],["B","等容舒张期"],["C","射血期"],["D","充盈期"]],"A","由于冠脉的分支大部分深埋于心肌组织中，故心肌的节律性收缩对冠脉血流量有很大影响，左冠状动脉血流受心肌收缩的影响尤为显著。左心室在等容收缩期开始时，心室壁张力急剧升高，压迫肌纤维之间的小血管，使左冠状动脉血流量明显减少，甚至发生逆流（A对）。","","N"],["2010-N124",3,"第5节 器官循环","冠脉循环的生理特点",2010,124,"B","","在一次心动周期中，冠状动脉血流量急剧增加的时相是",[["A","等容收缩期"],["B","等容舒张期"],["C","射血期"],["D","充盈期"]],"B","由于冠脉的分支大部分深埋于心肌组织中，故心肌的节律性收缩对冠脉血流量有很大影响，左冠状动脉血流受心肌收缩的影响尤为显著。左心室在等容收缩期开始时，心室壁张力急剧升高，压迫肌纤维之间的小血管，使左冠状动脉血流量明显减少，甚至发生逆流。随着左心室射血，主动脉压升高，冠状动脉压也随之升高，冠脉血流量增加；但进入减慢射血期时，冠脉血流量又复减少。在舒张期开始时，心肌对冠脉的压迫减弱或消失，冠脉血流阻力减小，血流量迅速增加（B对），并在舒张早期达到高峰，然后再逐渐减少。","","N"],["2010-N125",9,"第1节 神经系统功能活动的基本原理","NE和肾上腺素及其受体",2010,125,"B","","在周围神经系统中α1肾上腺素能受体被阻断后，可出现的生理功能改变是",[["A","瞳孔开大"],["B","气道阻力增加"],["C","血压降低"],["D","血糖降低"]],"C","能与NE和E结合的受体称为肾上腺素能受体，这类受体可以分为ɑ型肾上腺素能受体和β型肾上腺素能受体。α型受体有α₁和α₂两种亚型，β型受体有β₁、β₂、β₃三种亚型。α₁受体可以介导血管平滑肌收缩，升高血压，也可以介导虹膜辐射状肌收缩，扩大瞳孔，故α₁肾上腺素能受体被阻断后，瞳孔缩小（A错）、血压降低（C对）。气道（支气管）平滑肌只有β₂受体分布，无α₁受体分布，故阻断α₁受体不影响气道阻力（B错）。糖原的合成（胰岛素的分泌）与α₂受体和β₂受体有关，糖原的分解与β₂受体有关，均不涉及α₁受体，故阻断α₁受体不影响血糖浓度的变化（D错）。","","N"],["2010-N126",9,"第1节 神经系统功能活动的基本原理","NE和肾上腺素及其受体",2010,126,"B","","在周围神经系统中，β1肾上腺素能受体被阻断后，可出现的生理功能改变是",[["A","瞳孔开大"],["B","气道阻力增加"],["C","血压降低"],["D","血糖降低"]],"C","能与NE和E结合的受体称为肾上腺素能受体，这类受体可以分为ɑ型肾上腺素能受体和β型肾上腺素能受体。ɑ型受体有α₁和α₂两种亚型，β型受体有β₁、β₂、β₃三种亚型。β₁受体主要分布于心肌细胞膜上，可以介导心肌的正性变时、正性变传导作用（十版生理学P126），β₁受体被阻断后，心肌收缩力减弱，每搏输出量减少，血压下降（C对）。气道（支气管）平滑肌只有β₂受体分布，无β₁受体分布，故阻断β₁受体不影响气道阻力（B错）。虹膜辐射状肌只有α₁受体分布，无β₁受体分布，故阻断β₁受体不影响瞳孔大小（A错）。糖原的合成（胰岛素的分泌）与α₂受体和β₂受体有关，糖原的分解与β₂受体有关，均不涉及β₁受体，故阻断β₁受体不影响血糖浓度的变化（D错）。","","N"],["2010-N151",1,"第4节 肌细胞的收缩","骨骼肌神经肌肉接头处的兴奋传递",2010,151,"X","","下列选项中，可使骨骼肌松弛的途径有",[["A","促使Ca²⁺进入运动神经末梢"],["B","抑制运动神经末梢释放递质"],["C","阻断终板膜上一价非选择性阳离子通道"],["D","抑制胆碱酯酶活性"]],"BC","神经-肌接头处兴奋传导的具体过程为：运动神经纤维传到末梢的动作电位激活接头前膜中的电压门控钙通道，导致Ca²⁺内流而触发接头前膜Ca²⁺依赖性突触囊泡出胞，释放ACh至接头间隙，再由ACh激活终板膜中的N₂型ACh受体阳离子通道，产生Na⁺内流和K⁺外流（以Na⁺内流为主），导致膜电位改变，最终引起肌细胞兴奋。促使Ca²⁺进入运动神经末梢，可促进神经-肌接头兴奋传导过程，可促进骨骼肌收缩（A错）；抑制运动神经末梢释放递质及阻断终板膜上一价非选择性阳离子通道（即N₂型ACh受体阳离子通道，可允许 Na⁺， K⁺ 和Ca²⁺跨膜移动，但主要是Na⁺内流和 K⁺外流）均会抑制神经－肌接头兴奋传导过程，导致骨骼肌松弛（BC对）；乙酰胆碱酯酶可将与N₂型ACh受体阳离子通道结合的ACh迅速分解为胆碱和乙酸，使兴奋传递快速结束，避免神经动作电位消失后肌纤维的持续兴奋和收缩，抑制乙酰胆碱酯酶使ACh大量聚集，促进骨骼肌收缩甚至痉挛（有机磷中毒表现）（D错）。","","N"],["2010-N152",2,"第4节 血型和输血原则","ABO血型系统",2010,152,"X","","父母中一方的血型为A型，另一方为B型，其子女的血型可为",[["A","A型"],["B","B型"],["C","AB型"],["D","O型"]],"ABCD","血型为A型，基因型可能为AA和AO，血型为B型，基因型可能为BB和BO。根据基因的自由组合规律，父母中一方的血型则为A型，另—方为B型的基因型组合结果可能为AB、AO、BO和OO，对应的血型表现型为AB型、A型、B型和O型（ABCD对）。","","N"],["2010-N153",3,"第4节 心血管活动的调节","血管紧张素家族主要成员的生理作用",2010,153,"X","","血管紧张素Ⅱ的缩血管作用机制有",[["A","促进交感神经末梢释放儿茶酚胺"],["B","降低中枢对压力感受性反射的敏感性"],["C","增强交感缩血管中枢紧张"],["D","直接刺激肾上腺皮质释放皮质醇"]],"ABC","肾素催化血管紧张素原生成血管紧张素Ⅰ，血管紧张素Ⅰ再由血管紧张素转换酶（ACE）催化生成血管紧张素Ⅱ，血管紧张素Ⅱ可以促进肾上腺皮质分泌醛固酮，这一系列的过程构成肾素-血管紧张素-醛固酮系统。所以血管紧张素Ⅱ能够直接刺激肾上腺皮质释放醛固酮（盐皮质激素），而不是释放皮质醇（糖皮质激素）（D错）。值得注意的是，血管紧张素Ⅱ能够通过增强促肾上腺皮质激素释放激素（CRH）的作用（十版生理学P125）间接刺激肾上腺皮质释放皮质醇发挥缩血管作用（皮质醇本身没有收缩血管的效应，但能通过“允许作用”加强儿茶酚胺类激素的缩血管作用）。","","N"],["2010-N154",6,"第1节 能量代谢","基础代谢",2010,154,"X","","测定基础代谢率的条件有",[["A","于清晨醒后不久测定"],["B","测定时取坐位"],["C","测定前至少禁食12小时"],["D","室温保持在20～25℃"]],"ACD","基础代谢率（BMR）是指人体在清醒而又极端安静的状态下，不受肌肉活动、环境温度、食物及精神紧张等影响时的能量代谢率。测定基础代谢率，一般选择在清晨未进早餐以前，静卧休息半小时（但要保持清醒）（A对），室温维持20℃上下，按间接测热法利用仪器进行测定。","","N"],["2010-N155",8,"第4节 听觉","耳蜗微音器电位",2010,155,"X","","耳蜗微音器电位的特点有",[["A","其频率和幅度与声波一致"],["B","不发生适应"],["C","有一定的阈值"],["D","有一定的不应期"]],"AB","耳蜗是感音换能装置，耳蜗微音器电位是耳蜗受到声音刺激时产生的感受器电位，它是一种局部电位，具有局部电位的特征，即等级性电位，衰减性传导，没有不应期（D错）。此外，它还有自己特有的一些特征，如它的频率和幅度与声波完全一致（A对），没有阈值（C错），没有潜伏期，不易疲劳，不发生适应现象（B对）。","","N"],["2010-N156",9,"第2节 神经系统的感觉分析功能","感觉投射系统",2010,156,"X","","特异性感觉投射系统的生理功能有",[["A","产生各种体表和内脏感觉"],["B","维持和改变大脑皮层的兴奋状态"],["C","激发大脑皮层发出传出冲动"],["D","建立丘脑和大脑皮层之间的反馈联系"]],"AC","丘脑是感觉传入通路的重要中继站，根据丘脑各部分向大脑皮层投射特征的不同，将感觉投射系统分为特异投射系统和非特异投射系统。特异投射系统是指特异感觉接替核及其投射到大脑皮层的神经通路，它们投射到大脑皮层的特定区域，与大脑皮层具有点对点的投射关系，可以引起特定的感觉（A对）并激发大脑皮层发出神经冲动（C对）。非特异投射系统是指丘脑的非特异投射核及其投射至大脑皮层的神经通路，它们投射到大脑皮层的广泛区域，与大脑皮层不具有点对点投射关系，不能引起特异感觉，主要功能是维持和改变大脑皮层的兴奋状态（B错）。反馈需要建立闭环系统（十版生理学P10），但中枢兴奋的传递具有单向性，故丘脑和大脑皮层之间不能建立反馈联系（D错）。","","N"],["2011-N1",0,"第6节 人体内自动控制系统","负反馈控制系统",2011,1,"A","","下列生理活动中，存在负反馈控制的是",[["A","动作电位的产生"],["B","血糖浓度的调节"],["C","排便反射的过程"],["D","兴奋的突触传播"]],"B","受控部分发出的反馈信息调整控制部分的活动，最终使受控部分朝着与它原来活动相反的方向改变，称为负反馈，血糖浓度调节过程中，血糖升高能刺激胰岛素分泌，而发挥降糖作用，属于典型的负反馈（B对）。实际上机体内除排尿、排便（C错）、分娩、动作电位去极化过程中Na⁺内流（A错）、血液凝固过程、排卵前夕雌激素对 LH 的促进作用、蛋白酶原的激活等属于正反馈外，绝大部分调节过程均为负反馈。突触的兴奋传播即动作电位的突触传播，兴奋到达突触前膜时，突触前膜发生去极化，引起Ca²⁺内流，进而触发神经递质释放，神经递质作用于突触后膜引起去极化突触后电位，去极化总和达到阈电位后爆发动作电位，完成兴奋的传播。以上，突触兴奋传播的某个步骤（突触后膜爆发动作电位）存在正反馈过程，但整体来看，突触的兴奋传播不存在反馈控制系统（包括正反馈和负反馈）（D错），突触的兴奋传播应归属于非自动控制系统，非自动控制系统是一个开环系统，其控制部分的活动不受受控部分活动的影响，即突触前膜的去极化和Ca²⁺内流不受突触后膜动作电位的影响。","","N"],["2011-N2",1,"第2节 细胞的信号转导","离子通道型受体介导的信号转导",2011,2,"A","","神经-肌接头的终板膜上，实现跨膜信号转导的方式是",[["A","受体-G蛋白-AC途径"],["B","受体-G蛋白-PLC途径"],["C","离子通道受体途径"],["D","酪氨酸激酶受体途径"]],"C","神经-肌接头的终板膜上，实现跨膜信号转导的过程为：ACh与终板膜上的N₂型乙酰胆碱受体阳离子通道结合，使之开放，出现Na⁺内流及K⁺外流（Na⁺内流大于K⁺外流），进而使得终板膜发生去极化，产生终板电位。该信号转导过程的受体本身就是离子通道，为典型的离子通道型受体介导的信号转导（C对）。","","N"],["2011-N3",1,"第3节 细胞的电活动","细胞膜两侧离子的浓度差与平衡电位",2011,3,"A","","与Nernst公式计算所得相比，实际测得的神经细胞静息电位值",[["A","恰等于K⁺平衡电位"],["B","恰等于Na⁺平衡电位"],["C","接近于Na⁺平衡电位"],["D","接近于K⁺平衡电位"]],"D","静息电位接近于K⁺的平衡电位（D对），更准确地说是略小于K⁺的平衡电位（P34），因为安静时细胞膜对Na⁺也有一定的通透性，少量进入细胞的Na⁺可部分抵消由K⁺外流所形成的膜内负电位。","","N"],["2011-N4",2,"第2节 血细胞生理","红细胞的生理特征",2011,4,"A","","可导致红细胞沉降速率增快的影响因素是",[["A","血细胞比容增大"],["B","血浆球蛋白含量增多"],["C","红细胞脆性增大"],["D","血浆白蛋白含量增多"]],"B","血流中的红细胞，因胞膜表面的唾液酸所具有的负电荷等因素而互相排斥，使细胞保持一定间距，故彼此分散悬浮而下沉缓慢。正常情况下，血浆蛋白所带的正、负电荷呈平衡状态（白蛋白带负电荷，球蛋白与纤维蛋白原带正电荷），如血浆中纤维蛋白原或球蛋白含量增加或白蛋白含量减少，改变了电荷的平衡，致使红细胞表面的负电荷减少，容易使红细胞叠连而血沉加快，反之则血沉减慢（B对D错）。血细胞比容增大（A错）时，红细胞沉降率减慢。红细胞脆性增大主要见于球形红细胞增多症，此时，红细胞沉降速度减慢（C错）。","","N"],["2011-N5",2,"第4节 血型和输血原则","Rh血型系统",2011,5,"A","","Rh阴性的母亲生下Rh阳性子女，有可能患",[["A","巨幼红细胞性贫血"],["B","血友病"],["C","新生儿溶血性贫血"],["D","红细胞增多症"]],"C","Rh阴性的孕妇怀有Rh阳性的胎儿时，Rh阳性胎儿的红细胞携带外源性抗原进入母体，使母体产生免疫性抗体，免疫性抗体为IgG，分子量小，能通透胎盘进入胎儿的血液，使胎儿的红细胞发生溶血，造成新生儿溶血性贫血（C对）。由于一般只有妊娠末期或分娩时才有足量的胎儿红细胞进入母体，而母体血液中抗体的浓度是缓慢增加的，故Rh阴性的孕妇怀第一胎Rh阳性的胎儿时，很少出现新生儿溶血的情况；但在第二次妊娠时，母体内的抗Rh抗体可进入胎儿体内而引起新生儿溶血。若在Rh阴性母亲生育第一胎之后，及时输注特异性免疫球蛋白，中和进入母体内的Rh抗原，以避免Rh母亲产生免疫性抗体，可预防第二次妊娠时新生儿溶血的发生。","","N"],["2011-N6",3,"第1节 心脏的泵血功能","心动周期",2011,6,"A","","一个心动周期中，心室内容积达到最大的时刻是",[["A","心房收缩期末"],["B","减慢充盈期末"],["C","减慢射血期末"],["D","快速充盈期末"]],"A","心室容积与心室血量有关，左心室血量最多时，左心室容积也最大，左心室血量最多的时期包括心房收缩期末、整个等容收缩期和快速射血期初（A对）。","","N"],["2011-N7",3,"第3节 血管生理","影响静脉回心血量的因素",2011,7,"A","","生理情况下，人的中心静脉压升高可见于",[["A","心脏射血能力加强"],["B","体位由直立变为平卧"],["C","从行走改为站立"],["D","由吸气相改为呼气相"]],"B","中心静脉压的高低取决于心脏射血能力和静脉回心血量之间的相互关系。心脏射血能力加强时，心脏能及时的将回流入心脏的血液射入动脉，使得中心静脉压降低（A错），促进外周静脉血液回流。体位由直立变为平卧时，身体低垂部分的静脉可因跨壁压减小而收缩，回心血量增加，中心静脉压升高（B对）。从行走改为站立，骨骼肌对肌肉内和肌肉间的静脉产生的挤压作用减弱，静脉回流减慢，回心血量相对减少，中心静脉压降低（C错）。吸气时，胸腔容积加大，胸膜腔负压增大，使胸腔内的大静脉和右心房更加扩张，中心静脉压降低，从而有利于外周静脉血液回流至右心房；相反，呼气时，胸膜腔负压减小，胸腔内的大静脉和右心房收缩，中心静脉压升高，不利于外周静脉回流。故由吸气相改为呼气相时，中心静脉压是升高的（D对）。本题BD均对，但官方参考答案仅为B。","","N"],["2011-N8",4,"第2节 肺换气和组织换气","呼吸气体和人体不同部位气体的分压",2011,8,"A","","体内CO₂分压最高的部位是",[["A","组织液"],["B","细胞内液"],["C","毛细血管血液"],["D","静脉血液"]],"B","气体分子在体内的一定是由分压高处向分压低处转移。CO₂分压由高到低依次为：细胞内液（CO₂由此处产生）＞组织液＞组织毛细血管血液＞静脉血液＞肺动脉内的混合静脉血＞肺泡气＞呼出气＞大气（B对）。","","N"],["2011-N9",4,"第4节 呼吸运动的调节","化学感受器",2011,9,"A","","中枢化学感受器的生理性刺激是",[["A","动脉血液中的CO₂分压"],["B","动脉血液中的O₂分压"],["C","功能血液中的H⁺浓度"],["D","脑脊液和局部细胞外的H⁺浓度"]],"D","中枢化学感受器的生理性刺激是脑脊液和局部细胞外液中的H⁺（D对），而不是CO₂。但血液中的CO₂能迅速通过血-脑屏障，使化学感受器周围细胞外液中的H⁺浓度升高，从而刺激中枢化学感受器，再引起呼吸中枢兴奋。由于脑脊液中碳酸酐酶含量很少，CO₂与水的水合反应很慢，所以对CO₂的反应有一定的时间延迟。血液中的H⁺不易通过血-脑屏障，故血液pH的变动对中枢化学感受器的作用较小，也较缓慢。","","N"],["2011-N10",5,"第3节 胃内消化","胃排空及其控制",2011,10,"A","","下列选项中，能促进胃排空的神经或体液因素是",[["A","迷走-迷走反射"],["B","肠-胃反射"],["C","胃酸"],["D","促胰液素"]],"A","食物由胃排入十二指肠的过程称为胃排空。一般胃内因素能够促进胃排空（通过迷走-迷走长反射（A对）和壁内神经丛短反射等），而十二指肠内因素则能抑制胃排空（通过肠-胃反射、促胰液素、缩胆囊素、抑胃肽等）。","","N"],["2011-N11",5,"第7节 吸收","钙的吸收",2011,11,"A","","下列选项中，能促进Ca²⁺在小肠吸收的因素是",[["A","葡萄糖"],["B","植酸"],["C","草酸盐"],["D","磷酸盐"]],"A","Ca²⁺只有在水溶性状态下才能被吸收，葡萄糖经氧化之后能与钙结合形成水溶性的葡萄糖酸钙，从而能促进钙的吸收（A对）。植酸、草酸盐、磷酸盐均可与Ca²⁺结合形成不溶性的沉淀而抑制钙的吸收（BCD错）。","","N"],["2011-N12",6,"第1节 能量代谢","间接测热法",2011,12,"A","","临床上测定能量代谢时，为了简便，通常只需测定",[["A","一定时间内的CO₂产生量"],["B","非蛋白氧热价"],["C","非蛋白呼吸商"],["D","一定时间内的氧耗量"]],"D","能量代谢率的经典测算方法：1.测定机体在一定时间内的尿氮排出量，根据尿氮排出量计算出体内消耗蛋白质的量（尿氮量除以0.16），然后根据蛋白质的生物热价（18KJ/g）计算出蛋白质部分的产热量；2.测定机体在一定时间内的耗氧量和CO₂产生量，减去蛋白质氧化时的耗氧量和CO₂产生量（根据第一步消耗蛋白质的量计算出来的），得出非蛋白物质氧化时的耗氧量和CO₂产生量，然后计算出非蛋白呼吸商（NPRQ），然后根据十版生理学P199表7-2得出相对应的非蛋白氧热价，从而计算出非蛋白部分的产热量；3.将氧化蛋白质的产热量与氧化非蛋白质的产热量相加，即可算出机体在一定时间内的总产热量，即能量代谢率。能量代谢率的简化测算方法：经典测算方法的步骤比较繁琐，在临床工作中，采用相对简便的测定方法，一种方法是将蛋白质的产热量和耗氧量忽略不计（体内能量主要来自糖和脂肪的氧化），将测得的一定时间内的耗氧量和CO₂产生量所求得的呼吸商视为非蛋白呼吸商，经查表找到相对应的氧热价，耗氧量与此氧热价相乘，便可计算出一定时间内的产热量。另外一种方法更简单，只需测定一定时间内的耗氧量（D对），根据国人的统计资料，受试者食用混合膳食时的非蛋白呼吸商定为0.82，与此相对应的氧热价为20. 20kJ/L，用测定的一定时间内的耗氧量乘以20. 20kJ/L，即可得到这时间内的产热量。用简化方法所获得数值与经典测算方法所得数值非常接近。","","N"],["2011-N13",6,"第2节 体温及其调节","辐射散热",2011,13,"A","","当环境温度低于皮肤温度时，人体散热的主要方式是",[["A","辐射"],["B","传导"],["C","对流"],["D","不感蒸发"]],"A","当环境温度低于人体表面温度，人体散热方式主要为辐射、传导和对流，其中尤其以辐射散热为主（A对）。蒸发包括可感蒸发（出汗）和不感蒸发，为环境温度高于表层温度时的主要散热方式（D错）。人体因传导散热而散失的热量并不多，而对流散热是传导散热的一种（BC错）。","","N"],["2011-N14",7,"第2节 肾小球的滤过功能","血浆胶体渗透压",2011,14,"A","","下列选项中，能使肾小球有效滤过压升高的是",[["A","肾血浆流量增多"],["B","肾小囊内压增高"],["C","血浆晶体渗透压降低"],["D","血浆胶体渗透压降低"]],"D","肾小球有效滤过压=（肾小球毛细血管血压+囊内液胶体渗透压）-（血浆胶体渗透压+肾小囊内压），因此，肾小囊内压增高时肾小球有效滤过压下降（B错），血浆胶体渗透压降低时肾小球有效滤过压升高（D对）。肾血浆流量主要通过改变滤过平衡点来影响肾小球滤过率，肾血浆流量增多时，滤过平衡点向出球小动脉端移动，肾小球滤过率增加，与肾小球有效滤过压无关（A错）。血浆中的晶体物质成分可以自由通透肾小球滤过膜，因此血浆晶体渗透压等于肾小囊晶体渗透压，血浆晶体渗透压降低时，肾小囊晶体渗透压也相应降低，对肾小球有效滤过压无影响（C错）。","","N"],["2011-N15",7,"第4节 尿液的浓缩和稀释","尿液的稀释机制",2011,15,"A","","肾小管液被显著稀释的部位是",[["A","近端小管"],["B","集合管"],["C","髓袢升支粗段"],["D","远曲小管"]],"C","肾小管液流经肾单位的顺序为：近曲小管→髓袢降支粗段→髓袢降支细段→髓袢升支细段→髓袢升支粗段→远曲小管→集合管。在近曲小管和髓袢降支粗段（二者合称近端小管），小管液为等渗性重吸收，既不浓缩也不稀释；在髓袢降支细段，水的通透性较高（可记忆为“降水”），而Na⁺、Cl⁻通透性很低，小管液为高渗性重吸收（只有水被重吸收）而被浓缩；在髓袢升支细段、髓袢升支粗段和远曲小管，对水不通透，而对 Na⁺ 、Cl⁻ 却易通透，尤其在髓袢升支粗段存在针对 Na⁺ 、Cl⁻的主动转运机制，NaCl 被不断重吸收（水不被重吸收），小管液为低渗性重吸收，被显著稀释（C对），在远曲小管渗透浓度降至最低；在集合管，Na⁺、Cl⁻ 和 H₂O 的重吸收需要根据机体水、盐平衡的状况进行调节，可能被稀释，也可能被浓缩。","","N"],["2011-N16",8,"第3节 视觉","视网膜细胞的联系",2011,16,"A","","视网膜中央凹对光的感受分辨力高，其主要原因是",[["A","感光色素含量高"],["B","感光细胞的兴奋性高"],["C","视觉传递系统呈单线联系"],["D","感光色素处于合成状态"]],"C","视网膜的中央凹是视锥细胞高度集中的部位，且此处仅有视锥细胞的分布，在中央凹处常见一个视锥细胞仅与一个双极细胞相联系，然后又只与一个神经节细胞相连接，这种单线式联系可以使得视锥细胞有较高的分辨能力（C对），因此人眼的分辨能力以中央凹处最强。","","N"],["2011-N17",8,"第4节 听觉","中耳的功能(1)",2011,17,"A","","声波由鼓膜经听骨链到达卵圆窗膜时，振动变化的特征是",[["A","压强增大，振幅不变"],["B","压强增大，振幅减小"],["C","压强增大，振幅增大"],["D","压强减小，振幅减小"]],"B","声波由鼓膜经听骨链到达卵圆窗膜时，其声压增强，振幅略有减小。这是因为：①鼓膜的实际振动面积约55mm²，而卵圆窗膜的面积仅3.2mm²，二者之比为17.2：1。如果听骨链传递声波时的总压力不变，而作用于卵圆窗膜上的压强则为鼓膜上压强的17.2倍。②听骨链杠杆的长臂与短臂之比为1.3：1（约为4：3），因而通过听骨链传递，杠杆短臂一侧的压力将比长臂侧增大1.3倍，而振幅约减小1/4。综上两方面的作用，声波在中耳传递过程中将增压22.4倍（17.2×1.3），而幅度约减小1/4（B对）。","","N"],["2011-N18",9,"第1节 神经系统功能活动的基本原理","神经纤维的轴浆运输功能",2011,18,"A","","顺向快速轴浆运输主要运送的物质是",[["A","具有膜的细胞器"],["B","递质合成酶"],["C","微丝和微管"],["D","神经营养因子"]],"A","轴浆运输是指借助于轴突内轴浆流动而进行的物质运输。根据运输方向可分为顺向轴浆运输和逆向轴浆运输。根据轴浆运输的速度，顺向轴浆运输又可分为快速和慢速轴浆运输：顺向快速运输主要运输具有膜结构的细胞器（A对），如线粒体、突触囊泡和分泌颗粒等和递质合成酶（B）（十版组织学与胚胎学P62）；顺向慢速运输主要运输轴浆内可溶性成分，如微管蛋白、神经微丝蛋白等结构（C错）。逆向轴浆运输可运输一些能被轴突末梢摄取的物质，如神经营养因子（D错）、狂犬病病毒、破伤风毒素等。按照组织学与胚胎学的观点B选项也正确，但原答案为A。","","N"],["2011-N19",9,"第3节 神经系统对躯体运动的调控","牵张反射的类型",2011,19,"A","","下列关于腱反射的叙述，正确的是",[["A","高位中枢病变时反射亢进"],["B","反射中枢位于延髓"],["C","效应器为同一关节的拮抗肌"],["D","为多突触反射"]],"A","腱反射是指快速牵拉肌腱时发生的牵张反射，如叩击股四头肌肌腱引起股四头肌收缩的膝反射、叩击跟腱引起小腿腓肠肌收缩的跟腱反射等。腱反射属于牵张反射，其反射中枢位于脊髓（B错），正常情况下高位中枢对其有抑制作用，当脊髓离断或高位中枢病变时，高位中枢对其调控作用减弱，表现为腱反射亢进（A对）。腱反射的效应器是被牵拉的同一肌肉而不是拮抗肌（C错）。","","N"],["2011-N20",10,"第2节 下丘脑-垂体及松果体内分泌","促进生长",2011,20,"A","","下列关于生长激素生理作用的叙述，错误的是",[["A","促进长骨生长"],["B","增大内脏器官"],["C","促进脑的发育"],["D","促进肌肉的生长"]],"C","生长激素可以促进全身组织器官的生长，尤其是促进骨骼（A对）、肌肉（D对）和内脏器官（B对）的生长，但脑（神经系统）的发育无明显促进作用（C错，为本题正确答案），能够促进脑发育的激素是甲状腺激素（十版生理学P359）。","","N"],["2011-N21",10,"第3节 甲状腺内分泌","调节新陈代谢",2011,21,"A","","下列关于甲状腺激素对于物质代谢的叙述，正确的是",[["A","正常情况下，加强蛋白质分解"],["B","分泌过多时，使组织间隙中黏蛋白增多"],["C","抑制组织利用糖，使血糖浓度升高"],["D","促进胆固醇合成，更加速其清除"]],"D","甲状腺激素（TH）对糖、脂肪、蛋白质的合成和分解代谢均有调节作用，十分复杂。就整体而言，在生理浓度范围内的甲状腺激素对糖、脂肪、蛋白质的合成和分解代谢均有调节作用，而分泌过量时则促进分解代谢的作用更明显一些。","","N"],["2011-N22",11,"第2节 女性生殖功能及其调节","月经周期的分期",2011,22,"A","","女性月经来潮是由于",[["A","血中的E₂水平降低，P水平升高"],["B","血中的E₂水平升高，P水平降低"],["C","血中的E₂和P水平均降低"],["D","血中的FSH和LH水平均降低"]],"C","在卵泡期早期，由于卵巢内的黄体退化，雌激素（雌二醇，E₂）和孕激素（P）分泌量骤然下降（C对），子宫内膜缺乏性激素的支持，引起子宫内膜功能层的螺旋动脉发生收缩、痉挛，造成子宫内膜缺血缺氧，子宫内膜的功能层失去营养而剥离、出血，经阴道流出，即为月经来潮。","","N"],["2011-N23",2,"第2节 血细胞生理","红细胞生成所需物质",2011,23,"A","","合成血红蛋白的基本原料是",[["A","铁和叶酸"],["B","钴和维生素B₁₂"],["C","铁和蛋白质"],["D","蛋白质和内因子"]],"C","血红蛋白由珠蛋白和血红素组成，合成血红素的基本原料是甘氨酸、琥珀酰CoA和Fe²⁺（十版生物化学与分子生物学P485）（C对）。叶酸（以四氢叶酸的形式，作为一碳单位的载体）和维生素B₁₂（影响四氢叶酸的生成）参与嘌呤核苷酸和胸腺嘧啶核苷酸的合成，叶酸或维生素B₁₂缺乏时，红细胞中DNA合成受阻，细胞分裂增殖速度下降，细胞体积增大，核内染色质疏松，导致巨幼细胞性贫血，故叶酸和维生素B₁₂是红细胞DNA合成的辅助因子，并不是血红蛋白的合成原料（AB错）。内因子由胃壁细胞分泌（十版生理学P59），可与维生素B₁₂形成复合物，防止维生素B₁₂被肠内水解酶破坏，促进维生素B₁₂在回肠内的吸收，内因子缺乏时，可因维生素B₁₂吸收障碍而影响红细胞生成，引起巨幼红细胞贫血，故内因子和叶酸、维生素B₁₂一样是红细胞DNA合成的辅助因子，与血红蛋白的合成无关（D错）。","","N"],["2011-N24",9,"第1节 神经系统功能活动的基本原理","环式或交互式联系",2011,24,"A","","下列中枢神经元联系方式中，能产生后发放效应的是",[["A","辐散式联系"],["B","聚合式联系"],["C","链锁式联系"],["D","环式联系"]],"D","在多突触反射中，以数量众多的中间神经元为桥梁，中枢神经元相互连接成网。神经元之间的联系方式多种多样，不同的联系方式产生不同的传递效应，归纳起来主要有以下几种：①单线式联系：一个突触前神经元仅与一个突触后神经元发生突触联系；②辐散和聚合式联系：一个神经元与多个神经元形成突触联系；③链锁式和环式联系：在神经通路中，若由中间神经元构成的辐散与聚合式联系同时存在，则可形成链锁式联系或环式联系，在环式联系中，即使最初的刺激已经停止，传出通路上冲动发放仍能继续一段时间，这种现象称为后发放或后放电（D对）。","","N"],["2011-N121",9,"第1节 神经系统功能活动的基本原理","NE和肾上腺素及其受体",2011,121,"B","","去甲肾上腺素作用于肾上腺素能受体的特点是",[["A","对α受体作用强，对β₁受体作用较强，对β₂受体作用弱"],["B","对α受体作用弱，对β₁受体作用较强，对β₂受体作用强"],["C","对α、β₁和β₂受体作用都很弱"],["D","对α、β₁和β₂受体作用都很强"]],"A","去甲肾上腺素（NE）是交感神经节后纤维释放的主要递质，能与去甲肾上腺素结合的受体称为肾上腺素能受体，包括α受体和β受体两大类，α受体又可分为α₁受体和α₂受体两种亚型，β受体可分为β₁受体、β₂受体和β₃受体三种亚型。去甲肾上腺素对α₁受体（主要分布于血管平滑肌细胞）的作用很强，对β₁受体（主要分布于心肌细胞）的作用较强，对β₂受体（主要分布于骨骼肌和肝脏的血管平滑肌）的作用较弱（A对）。","","N"],["2011-N122",9,"第1节 神经系统功能活动的基本原理","NE和肾上腺素及其受体",2011,122,"B","","肾上腺素作用于肾上腺素能受体的特点是",[["A","对α受体作用强，对β₁受体作用较强，对β₂受体作用弱"],["B","对α受体作用弱，对β₁受体作用较强，对β₂受体作用强"],["C","对α、β₁和β₂受体作用都很弱"],["D","对α、β₁和β₂受体作用都很强"]],"D","在中枢神经系统，肾上腺素（E）为神经递质，但在外周，肾上腺素为肾上腺髓质释放的一种内分泌激素。肾上腺素作用于肾上腺素能受体的特点是对α、β₁和β₂受体作用都很强（D对）：肾上腺素作用于皮肤、肾、胃肠血管平滑肌的α受体，引起血管收缩；作用于骨骼肌和肝脏血管平滑肌的β₂受体，引起血管舒张；作用于心脏平滑肌细胞的β₁受体，可产生正性变时、正性变力和正性变传导作用。","","N"],["2011-N123",7,"第5节 尿生成的调节","血浆晶体渗透压",2011,123,"B","","介导血浆晶体渗透压升高引起渴觉和饮水行为的神经肽是",[["A","血管紧张素Ⅱ"],["B","血管升压素"],["C","血管活性肠肽"],["D","心房钠尿肽"]],"B","血浆晶体渗透压升高时，血管升压素增多，二者均可通过刺激下丘脑渗透压感受器引起渴觉和饮水行为：血浆渗透浓度达289～307mOsm/（kg·H₂O）以上能引起渴觉，血浆血管升压素（B对）浓度达5pg/ml时也能引起渴觉。","","N"],["2011-N124",9,"第4节 神经系统对内脏活动、本能行为和情绪的调节","本能行为",2011,124,"B","","介导低血容量引起渴觉和饮水行为的神经肽是",[["A","血管紧张素Ⅱ"],["B","血管升压素"],["C","血管活性肠肽"],["D","心房钠尿肽"]],"A","低血容量引起渴觉主要由肾素-血管紧张素-醛固酮系统所介导：低血容量能刺激肾素分泌增加，使血管紧张素Ⅱ含量增高，血管紧张素Ⅱ（A对）能作用于间脑的特殊感受区穹窿下器和终板血管器，引起渴觉。","","N"],["2011-N125",7,"第3节 肾小管和集合管的物质转运功能","小管液中溶质的浓度",2011,125,"B","","上述措施中，可引起渗透性利尿的是",[["A","饮大量清水"],["B","静脉滴注大量生理盐水"],["C","饮大量生理盐水"],["D","静脉滴注甘露醇"]],"D","由于小管液某些溶质浓度增大导致水和NaCl排出量增多的现象称为渗透性利尿。甘露醇是一种可以经肾小球自由滤过，但不被肾小管重吸收的物质，当小管液中的甘露醇因未被重吸收而留在小管液中时，可使小管液溶质浓度增大，渗透压升高，水渗透入小管液内，水的排出量增多；小管液中水的渗入又导致小管液中的Na⁺被稀释而浓度降低，小管液和上皮细胞之间的Na⁺浓度梯度降低，而Na⁺在肾小管重吸收的动力来自Na⁺的浓度梯度，因此Na⁺浓度梯度的降低导致Na⁺重吸收减少，NaCl的排出量也增多（D对）。生理盐水是等渗溶液，因此饮用生理盐水和静脉注射生理盐水只会增加体液量，不会改变肾小管液溶质浓度，不会引起渗透性利尿（BC错）。","","N"],["2011-N126",7,"第5节 尿生成的调节","血浆晶体渗透压",2011,126,"B","","下述措施中，可引起水利尿的是",[["A","饮用大量清水"],["B","静脉滴注大量生理盐水"],["C","饮大量生理盐水"],["D","静脉滴注甘露醇"]],"A","饮用大量清水时，体液被稀释，使血浆晶体渗透压显著降低，血管升压素释放减少或停止，使肾小管和集合管对水的通透性降低，重吸收减少，尿量增加，这种现象称为水利尿（A对）。生理盐水是等渗溶液，饮用生理盐水和静脉注射生理盐水，虽然不会改变血浆晶体渗透压，但会增加体液量，刺激心肺感受器，抑制抗利尿激素的释放，从而增加尿量，这种尿量变化达不到饮用清水后的变化幅度，不符合水利尿的定义（BC错）。","","N"],["2011-N151",4,"第1节 肺通气","弹性阻力和顺应性",2011,151,"X","","存在于肺泡内液气界面的肺表面活性物质的生理意义有",[["A","维持大小肺泡的稳定性"],["B","防止肺水肿"],["C","降低呼气阻力"],["D","降低吸气阻力"]],"ABD","由于肺表面活性物质可以降低肺泡表面张力，肺泡表面张力是肺弹性阻力（弹性回缩力）的主要来源，故肺表面活性物质有助于减少肺的弹性阻力。又由于肺的弹性阻力是吸气的阻力，呼气的动力，故肺表面活性物质能够降低吸气的阻力（D对）和呼气的动力（C错）。肺表面活性物质可以降低肺泡表面张力，进而降低肺泡表面张力对肺毛细血管血浆和肺组织间液可产生‘抽吸’作用，从而防止肺水肿的发生（B对）。根据Laplace定律（十版生理学P141），肺泡的回缩力与肺泡半径成反比，即小肺泡的回缩力大，而大肺泡的回缩力小，但肺表面活性物质的存在，降低了小肺泡的回缩力（小肺泡分布的肺表面活性物质密度较大，降低了表面张力），从而避免了小肺泡萎陷关闭而大肺泡过度膨胀的情况，保持了大小肺泡的稳定性（A对）。","","N"],["2011-N152",5,"第4节 小肠内消化","胆汁的作用",2011,152,"X","","胆汁在消化和吸收营养物质中的作用有",[["A","酶解蛋白质"],["B","乳化脂肪"],["C","运载脂肪分解产物"],["D","促进脂溶性维生素的吸收"]],"BCD","胆汁中由于不含有消化酶，因此不能酶解蛋白质（A错）。胆汁中的胆盐、卵磷脂和胆固醇等均可作为乳化剂，通过乳化作用增加胰脂肪酶的作用面积（B对），促进脂肪的分解消化。胆汁中胆盐可与脂肪酸、一酰甘油等脂肪分解产物聚合形成水溶性的混合微胶粒，运载脂肪分解产物（C对）穿过小肠绒毛表面的静水层而到达肠黏膜表面，从而促进脂肪分解产物和脂溶性维生素A、D、E、K的吸收（D对）。","","N"],["2011-N153",7,"","",2011,153,"X","","在肾小管上皮的转运过程中伴有Na⁺重吸收的有",[["A","葡萄糖的重吸收"],["B","氨基酸的重吸收"],["C","H⁺的分泌"],["D","NH₃的分泌"]],"ABC","在肾小管，葡萄糖和氨基酸是以继发性主动转运方式被重吸收的，它们是由同向转运体和钠泵的耦联活动而完成的，伴随着Na⁺的重吸收而被吸收（AB对）。H⁺的分泌是通过Na⁺-H⁺交换体反向转运的方式进行的，即每分泌一个H⁺则伴随着一个Na⁺的重吸收（C对）。NH₃是脂溶性分子，它可以以单纯扩散的方式进入小管腔，与Na⁺的重吸收无关（D错）。","","N"],["2011-N154",10,"第4节 甲状旁腺、维生素D与甲状腺C细胞内分泌","概述",2011,154,"X","","下列激素中，参与机体钙、磷代谢的有",[["A","甲状腺激素"],["B","甲状旁腺激素"],["C","抗利尿激素"],["D","1，25-二羟维生素D₃"]],"BD","甲状旁腺激素、降钙素和1，25-二羟维生素D₃是调节机体钙、磷代谢最基础的三种激素（BD对）。甲状腺激素也参与了钙、磷代谢的调节，故A选项也正确，但给出的标准答案无A。抗利尿激素（十版生理学P231）在代谢调节过程中主要起调节水和电解质平衡的作用。","","N"],["2011-N155",10,"第3节 甲状腺内分泌","调节新陈代谢",2011,155,"X","","甲状腺激素分泌过多时，可引起升高的是",[["A","血糖水平"],["B","血胆固醇水平"],["C","能量代谢水平"],["D","神经活动兴奋性"]],"ACD","甲状腺激素几乎作用于机体的所有组织，其生物学效应极为广泛，十分复杂，当甲状腺激素分泌过多时，可引起升高的是血糖水平（A对）、能量代谢水平（C对）和神经活动兴奋性（D对），可引起血胆固醇水平降低（B错）。","","N"],["2011-N156",9,"第1节 神经系统功能活动的基本原理","NE和肾上腺素及其受体",2011,156,"X","","由α型肾上腺素能受体介导的生理活动有",[["A","瞳孔开大"],["B","骨骼肌血管收缩"],["C","胃肠平滑肌收缩"],["D","脂肪分解加强"]],"AB","能与NE和E结合的受体称为肾上腺素能受体，这类受体可以分为ɑ型肾上腺素能受体和β型肾上腺素能受体。α型受体有α₁和α₂两种亚型，β型受体有β₁、β₂、β₃三种亚型。NE与α受体（主要是α₁受体）结合后产生的平滑肌效应主要是兴奋性的，α₁受体可以使虹膜辐射状肌收缩，扩大瞳孔（A对），也可以使血管（含骨骼肌血管，虽然骨骼肌血管以β₂受体为主）的收缩（B对），但也有抑制性的，如α₂受体可以使小肠舒张（C错）。脂肪分解主要与β₃受体有关（D错）。","","N"],["2012-N1",1,"第1节 细胞膜的物质转运功能","单纯扩散",2012,1,"A","","人体的NH₃通过细胞膜的方式是",[["A","单纯扩散"],["B","易化扩散"],["C","原发性主动转运"],["D","继发性主动转运"]],"A","O₂、CO₂、N₂、NH₃等气体分子都是以单纯扩散的形式进行跨膜转运，这一知识点在考研真题里面反复出现！","","N"],["2012-N2",1,"第4节 肌细胞的收缩","骨骼肌神经肌肉接头处的兴奋传递",2012,2,"A","","微终板电位产生的原因是",[["A","运动神经末梢释放一个递质分子引起的终板膜电活动"],["B","肌接头后膜上单个受体离子通道开放"],["C","单囊泡递质自发释放引起终板膜多个离子通道开放"],["D","神经末梢单个动作电位引起终板膜多个离子通道开放"]],"C","运动神经末梢释放ACh是以囊泡为单位进行的，每个突触囊泡含有约1万个ACh分子（十版生理学生理学P43），在静息状态下（D错），囊泡的随机运动也会发生单个囊泡的自发释放（与Ca²⁺内流触发的囊泡出胞机制无关），并引起终板膜电位的微小去极化，即微终板电位（小终板电位）。运动神经末梢释放的并非一个ACh递质分子，而是一个囊泡，一个囊泡内含有很多个ACh分子（A错），可引起多个离子通道开放（C对B错）。","","N"],["2012-N3",1,"第4节 肌细胞的收缩","肌丝的分子结构",2012,3,"A","","与粗肌丝横桥头部结合，引起肌小节缩短的蛋白质是",[["A","肌球蛋白"],["B","肌动蛋白"],["C","原肌球蛋白"],["D","肌钙蛋白"]],"B","肌原纤维由粗肌丝和细肌丝组成，粗肌丝由肌球蛋白（又称肌凝蛋白）组成，细肌丝由肌动蛋白（又称肌纤蛋白）、原肌球蛋白（又称原肌凝蛋白）和肌钙蛋白组成。粗肌丝的肌球蛋白上有横桥结构，与细肌丝肌动蛋白（B对）的特定位点结合可引起肌丝滑行，使肌肉收缩。","","N"],["2012-N4",2,"第2节 血细胞生理","红细胞的破坏",2012,4,"A","","血管外破坏红细胞的主要场所是",[["A","肝脏"],["B","脾脏"],["C","肾脏"],["D","淋巴结"]],"B","90%的衰老红细胞被巨噬细胞吞噬，称为红细胞的血管外破坏，血管外破坏的最主要场所为脾脏（B对），其次为肝脏和骨髓。10%的衰老红细胞在血管中受机械冲击而破损，称为血管内破坏。","","N"],["2012-N5",2,"第3节 生理性止血","生理性止血的基本过程",2012,5,"A","","血凝块回缩的原因是",[["A","血凝块中纤维蛋白收缩"],["B","红细胞叠连而压缩"],["C","白细胞变形运动"],["D","血小板的收缩蛋白收缩"]],"D","血小板的收缩能力与其收缩蛋白有关，在血小板内存在类似肌肉的收缩蛋白系统（D对），包括肌动蛋白（血小板微丝）、肌球蛋白等等，血凝块中的血小板收缩，血凝块回缩，挤出其中的血清，使血凝块更加坚实，牢固封住血管的破口。","","N"],["2012-N6",2,"第4节 血型和输血原则","Rh血型系统",2012,6,"A","","Rh血型的主要抗体是",[["A","IgA"],["B","IgD"],["C","IgG"],["D","IgE"]],"C","与ABO血型系统不同，人的血清中不存在抗Rh的天然抗体，只有当Rh阴性者在接受Rh阳性的血液后，才会产生抗Rh的免疫性IgG抗体（C对）。而ABO系统的抗体则包括天然的IgM抗体和免疫性IgG抗体。","","N"],["2012-N7",3,"第1节 心脏的泵血功能","心室肌的前负荷",2012,7,"A","","生理情况下，能代表心室肌前负荷的指标是",[["A","收缩末期容积或压力"],["B","舒张末期容积或压力"],["C","等容收缩期容积或压力"],["D","等容舒张期容积或压力"]],"B","前负荷是指肌肉在收缩前所承受的负荷，前负荷使肌肉在收缩前处于一定的初长度。对中空球形的心脏来说，心室肌的初长度决定于心室舒张末期的血液充盈量，换言之，心室舒张末期容积相当于心室的前负荷。由于测量心室内压比测定心室容积方便，且心室舒张末期容积与心室舒张末期压力在一定范围内具有良好的相关性，故也可用心室舒张末期压力来反映前负荷（B对）。","","N"],["2012-N8",3,"第2节 心脏的电生理学及生理特性","决定和影响自律性的因素",2012,8,"A","","衡量心肌自律性高低的主要指标是",[["A","动作电位的幅值"],["B","最大复极电位水平"],["C","4期膜电位自动去极化速率"],["D","0期去极化速度"]],"C","自律性是指心肌细胞在没有外来刺激情况下自动兴奋的特性，自律性的高低即自动兴奋频率的高低，自律性的高低主要取决于4期自动去极化的速率（C对）。自律性的高低也受最大复极电位与阈电位之间差距的影响，最大复极电位的绝对值减小，或阈电位水平下移，都能使二者之间的差距缩短，进而使自动去极化达到阈电位水平所需的时间减少，最终导致自律性增高，反之则自律性降低，但最大复极电位水平本身不能用来衡量心肌自动节律性的高低（B错）。动作电位的幅值（最大值）和0期去极化速度与心肌自动节律性的高低无关（AD错）。","","N"],["2012-N9",3,"第3节 血管生理","影响动脉血压的因素",2012,9,"A","","影响收缩压最主要的因素是",[["A","心率的变化"],["B","每搏输出量的变化"],["C","外周阻力的变化"],["D","大动脉管壁弹性的变化"]],"B","生理情况下，对收缩压影响最大的是每搏输出量的变化（B对）。心率和外周阻力的变化主要影响舒张压（AC错）。大动脉管壁弹性的变化主要影响动脉血压的波动幅度（D错）。","","N"],["2012-N10",4,"第2节 肺换气和组织换气","通气_血流比值",2012,10,"A","","假设肺通气量为7000ml/min，呼吸频率为20次/分，无效腔容量为100ml，每分心输出量为5000ml时，其通气/血量比值为",[["A","0.7"],["B","0.8"],["C","0.9"],["D","1"]],"D","通气/血流比值=每分钟肺泡通气量/每分钟血流量，每分钟血流量已知为5000ml，故只需知道每分钟肺泡通气量，即可计算出通气/血流比值。每分钟肺泡通气量=（潮气量-无效腔气量）×呼吸频率=潮气量×呼吸频率-无效腔气量×呼吸频率=肺通气量-无效腔气量×呼吸频率=7000-20×100=5000ml，故通气/血流比值=5000ml/5000ml=1.0（D对）。","","N"],["2012-N11",4,"第3节 气体在血液中的运输","Hb与O₂结合的特征",2012,11,"A","","关于Hb和O₂结合的叙述，错误的是",[["A","Hb的4个亚基间有协同作用"],["B","1分子Hb最多结合4分子O₂"],["C","Hb和O₂的结合和解离曲线呈S型"],["D","100ml血中的Hb实际结合的O₂量称为Hb氧容量"]],"D","每个Hb（血红蛋白）分子由1个珠蛋白和4个血红素组成，珠蛋白有4条多肽链，每条多肽链与1个血红素相连接，构成Hb的亚单位（4个亚单位）。每个亚单位可借助血红素中的Fe²⁺结合1分子的O₂，故1分子Hb最多可结合4分子O₂（B对），100ml 血液中Hb最多可结合的O₂量称为Hb氧容量（D错，为本题正确答案）。Hb的4个亚单位彼此之间有协同效应（A对），即1个亚单位与O₂结合后，由于变构效应，其他亚单位更易与O₂结合，反之，当HbO₂的1个亚单位释放出O₂后，其他亚单位更易释放O₂，因此，氧解离曲线呈S形（C对）。","","N"],["2012-N12",5,"第3节 胃内消化","胃的运动形式",2012,12,"A","","在下列选项中，胃所具有的运动形式是",[["A","蠕动冲"],["B","容受性舒张"],["C","分节运动"],["D","袋状往返运动"]],"B","胃的运动形式包括紧张性收缩（十版生理学P177）、容受性舒张（十版生理学P177）（B对）和蠕动（十版生理学P178），其中容受性舒张是胃特有的运动形式。分节运动（十版生理学P183）和蠕动冲（十版生理学P184）是小肠的运动形式（AC错）。袋状往返运动是大肠的运动形式（十版生理学P187）（D错）。","","N"],["2012-N13",5,"第2节 口腔内消化和吞咽","唾液的性质和成分",2012,13,"A","","唾液中除含有唾液淀粉酶外，还有的酶是",[["A","凝乳酶"],["B","寡糖酶"],["C","溶菌酶"],["D","肽酶"]],"C","溶菌酶广泛存在于唾液（C对）、眼泪、血浆、尿、乳汁等多种体液中，具有杀灭细菌和病毒作用，是机体固有免疫的重要组成部分。凝乳酶主要存在于胃液中（酸性蛋白酶，被胃酸激活），可使乳汁内的蛋白质凝聚成乳酪后易为各种蛋白质酶所消化。寡糖酶主要存在于小肠上皮细胞内，具有分解蔗糖、麦芽糖等寡糖（2-10个单糖单位组成的低聚糖）为单糖的作用。肽酶是一种能够水解肽链的酶，消化道中的肽酶有三种：一种是羧基肽酶，来源于胰腺和小肠腺，作用是从肽链的羧基端顺序切下单个氨基酸；一种是氨基肽酶，来源于小肠腺，作用是从肽链的氨基端顺序切下单个氨基酸；还有一种是二肽酶，来源于小肠腺，能水解二肽成两个氨基酸。蛋白质在消化道内先由胃蛋白酶、胰蛋白酶、胰糜蛋白酶切断蛋白质中某几种特定氨基酸氨基或羧基端的肽键，使蛋白质分解成多肽或二肽，再由上述三种肽酶作用，从肽链的羧基端或氨基端按顺序切下一个个氨基酸，而使肽链彻底分解成单个氨基酸。","","N"],["2012-N14",7,"第5节 尿生成的调节","血浆晶体渗透压",2012,14,"A","","大量出汗时尿量减少的最主要原因是",[["A","血浆晶体渗透压升高，抗利尿激素分泌增加"],["B","交感神经兴奋，抗利尿激素分泌增加"],["C","血容量减少，肾小球滤过减少"],["D","血浆胶体渗透压升高，肾小球滤过减少"]],"A","由于汗液为低渗液（十版生理学P208），大量出汗后体内水的丢失多于氯化钠的丢失，引起血浆晶体渗透压升高，进而刺激抗利尿激素分泌增多，水重吸收增加，尿量减少（A对）。","","N"],["2012-N15",7,"第3节 肾小管和集合管的物质转运功能","近端小管",2012,15,"A","","在近球小管中滤出的HCO₃⁻被重吸收的主要形式是",[["A","H₂CO₃"],["B","（NH₂）₂CO"],["C","CO₂"],["D","HCO₃⁻"]],"C","HCO₃⁻带负电荷不易通过细胞膜，重吸收时首先与通过Na⁺-H⁺交换分泌到小管腔中的H⁺结合生成H₂CO₃，H₂CO₃在碳酸酐酶作用下分解为CO₂和水，CO₂具有高度脂溶性，以单纯扩散方式进入管腔上皮细胞内，在上皮细胞内，CO₂和水再在碳酸酐酶的催化下形成H₂CO₃，并解离为H⁺和HCO₃⁻。因此，在近球小管中滤出的HCO₃⁻是以CO₂的形式进行重吸收的（C对）。","","N"],["2012-N16",8,"第3节 视觉","晶状体变凸",2012,16,"A","","老视发生的主要原因是",[["A","玻璃体透明度改变"],["B","晶状体弹性减弱"],["C","角膜透明度改变"],["D","房水循环障碍"]],"B","近点是指眼作充分调节时所能看清楚的最近距离，近点越近说明晶状体的弹性越好，即眼的调节能力越强。正常人随着年龄的增长，近点将逐渐移远，晶状体弹性减弱（B对），眼的调节能力下降，这种现象称为老视。玻璃体和角膜透明度改变，光线不能透过眼的折光系统成像在视网膜上，导致视物不清，与老视无关（AC错）。房水循环障碍可使眼内压增高，眼内压的病理性增高称为青光眼（D错）。","","N"],["2012-N17",8,"第4节 听觉","基底膜的振动和行波学说",2012,17,"A","","关于耳蜗声波频率分析的行波学说，错误的叙述是",[["A","不同频率的声波引起的行波均从基底膜底部开始"],["B","声波频率愈低，行波的传播距离愈远"],["C","行波的起点与终点之间有一个振幅最大的部位"],["D","高频声波的最大行波振幅出现在蜗顶部附近"]],"D","行波学说，即行波原理，是指声波振动自基底膜底部向顶部传播的原理。声波在基底膜传播的过程：声波的振动经中耳传到卵圆窗膜，引起卵圆窗膜处基底膜（即蜗底部）的振动（不同频率的声波引起的行波都是从基底膜的蜗底部开始的）（A对），再以行波原理向蜗顶部传播，引起其他部位基底膜的振动。在向蜗顶部传播时，频率越低的声波，传播越远，最大行波振幅出现的部位越靠近基底膜顶部，而频率越高的声波传播越近，最大行波振幅出现的部位越靠近基底膜底部。这就类似于人们抖动一条绸带，抖动的频率越低，才能传播越远、最大振幅出现的位置越远，且最大振幅出现后，行波很快消失。因此低频振动首先引起耳蜗底部基底膜振动，振幅逐渐增大，近顶端达到最大振幅（BC对），而高频率的声音引起的基底膜振动只局限于卵圆窗膜附近（D错，为本题正确答案）。","","N"],["2012-N18",8,"第2节 躯体和内脏感觉","痛觉信息的感受和传导",2012,18,"A","","传导快痛的外周神经纤维主要是",[["A","Aα纤维"],["B","Aδ纤维"],["C","B类纤维"],["D","C类纤维"]],"B","根据神经纤维兴奋传导速度的差异，将哺乳动物的周围神经纤维分为A、B、C三类，其中A类纤维再分为α、β、γ、δ四个亚类。A类和B类是有髓神经纤维，传导速度较快，C类是无髓神经纤维，传导速度较慢。痛觉传入纤维有Aδ有髓纤维和C类无髓纤维两类，传导快痛的外周神经纤维主要是Aδ神经纤维（B对），传导慢痛的外周神经纤维主要是C类无髓神经纤维（D错）。Aα类纤维主要功能是传导本体感觉和躯体运动（A错），B类纤维是自主神经节前纤维（C错）。","","N"],["2012-N19",9,"第3节 神经系统对躯体运动的调控","牵张反射的感受器",2012,19,"A","","肌梭的传入冲动增加时，产生的生理效应是",[["A","兴奋同一肌肉的α运动神经元"],["B","抑制同一肌肉的β运动神经元"],["C","抑制同一肌肉的γ运动神经元"],["D","兴奋其他关节肌肉的α运动神经元"]],"A","肌梭是感受肌肉长度的感受器，当肌肉受外力牵拉而使肌梭感受装置被拉长时，传入神经传入冲动增加，肌梭的传入冲动增加可引起支配同一肌肉的α运动神经元兴奋（A对），使梭外肌收缩，形成一次牵张反射。此外，肌梭的传入冲动增加还可以引起支配同一肌肉的γ运动神经元兴奋（C错），使梭内肌收缩，从而调节肌梭对牵张反射的敏感性。β运动神经元与牵张反射的关系尚不清楚（B错）。牵张反射的效应器是受牵拉的同一肌肉，对其他肌肉没有作用（D错）。","","N"],["2012-N20",9,"第4节 神经系统对内脏活动、本能行为和情绪的调节","副交感神经系统的功能",2012,20,"A","","副交感神经系统兴奋时，引起的生理效应是",[["A","汗腺分泌增加"],["B","支气管平滑肌收缩"],["C","瞳孔开大肌收缩"],["D","胃肠运动减慢"]],"B","副交感神经兴奋时，作用于支气管平滑肌M受体使支气管平滑肌收缩（B对）；作用于胃肠道平滑肌M受体使胃肠道平滑肌收缩，胃肠运动增强（D错）。使瞳孔开大肌（又称虹膜辐射状肌）收缩的是交感神经，而不是副交感神经（C错）。汗腺与骨骼肌血管一样，虽然存在M型胆碱能受体，也接受乙酰胆碱（ACh）支配，但此处释放ACh的是交感神经，而不是副交感神经（A错）。","","N"],["2012-N21",1,"第2节 细胞的信号转导","第二信使",2012,21,"A","","以IP₃和DG作为第二信使的激素是",[["A","肾上腺素"],["B","醛固酮"],["C","促肾上腺皮质激素"],["D","甲状腺激素"]],"A","肾上腺素既可以cAMP作为第二信使（β肾上腺素能受体、α₂肾上腺素能受体，1995N122B考过），也可以IP₃和DG作为第二信使（α₁肾上腺素能受体）（A对）。九版生理学P394明确指出“ACTH与肾上腺素皮质细胞膜受体结合后，通过AC-cAMP-PKA或PLC-IP₃/DG-PKC通路促进胆固醇转化为孕烯醇酮，继而增加皮质醇的合成”，因此C选项也正确，但本题的参考答案为A。醛固酮（类固醇激素）及甲状腺激素属于脂溶性配体，可直接进入细胞与胞质受体或核受体结合发挥作用，无需第二信使的参与（BD错）。","","N"],["2012-N22",10,"第3节 甲状腺内分泌","调节新陈代谢",2012,22,"A","","下列关于甲状腺激素生理作用的叙述，错误的是",[["A","加强心肌收缩力"],["B","提高神经系统的兴奋性"],["C","促进骨骼和脑的生长发育"],["D","减少蛋白质合成"]],"D","甲状腺激素几乎作用于机体的所有组织，其生物学效应极为广泛，十分复杂，详情可参考十版生理学学P359-P361“甲状腺激素的生物作用”。重点说一下D选项，甲状腺激素功能的复杂性尤其体现在物质代谢的调节方面，就整体而言，甲状腺激素对糖、脂肪、蛋白质的合成和分解代谢均有调节作用，分泌适量时促进合成代谢的作用比较明显；而分泌过量时则促进分解代谢的作用更明显，对蛋白质来说，甲状腺激素分泌过量促进其分解代谢作用大于合成代谢作用，进而造成负氮平衡。生理作用指对正常生理活动的作用，正常生理活动下甲状腺激素是适量的，以促进蛋白质的合成代谢为主（D错，为本题正确答案）。","","N"],["2012-N23",11,"第3节 妊娠","胎盘的功能",2012,23,"A","","维持妊娠黄体功能的主要激素是",[["A","雌激素"],["B","孕激素"],["C","人绒毛膜促性腺激素"],["D","黄体生成素"]],"C","未妊娠时，黄体（月经黄体）在排卵后9～10天开始退化，雌激素、孕激素分泌量逐渐减少，对腺垂体的负反馈作用减弱，FSH和LH分泌增加，以进入下一个卵巢周期；妊娠时，人绒毛膜促性腺激素（hCG）（C对）刺激月经黄体转变成妊娠黄体，继续分泌孕激素和雌激素，以适应妊娠的需要。","","N"],["2012-N24",10,"第1节 内分泌与激素","脂类激素",2012,24,"A","","睾酮的化学本质是",[["A","胺类"],["B","类固醇类"],["C","肽类"],["D","蛋白质"]],"B","睾酮的化学本质是类固醇激素（B对），类固醇激素是脂类激素（十版生理学P340）的一种，类固醇激素除睾酮外，还包括孕酮、醛固酮、皮质醇、雌二醇和胆钙化醇等。胺类激素（十版生理学P340）多为氨基酸的衍生物，包括儿茶酚胺类激素、甲状腺激素等。肽类激素和蛋白质类激素一般统称为肽与蛋白质类激素（十版生理学P340），包括胰岛素、胰高血糖素、生长激素等。","","N"],["2012-N121",0,"第5节 机体生理功能的调节","自身调节",2012,121,"B","","当平均动脉压在60～140mmHg波动时，维持脑血流量恒定的调节属于",[["A","神经调节"],["B","体液调节"],["C","自身调节"],["D","神经-体液调节"]],"C","心血管活动的调节包括神经调节、体液调节和自身调节三种方式，其中自身调节包括了代谢性自身调节机制和肌源性自身调节机制两种（十版生理学P128），肌源性自身调节是指当供应某一器官血管的灌注压在一定范围内升高时，血管平滑肌受牵张刺激，血管（尤其是毛细血管前阻力血管）的肌源性活动增强，使器官血管的血流阻力增大，以免器官的血流量因灌注压升高而增多。反之，当器官血管的灌注压在一定范围内降低时，阻力血管舒张，局部血流阻力减小，以免器官的血流量因灌注压降低而减少。这种肌源性自身调节机制在肾血管特别明显，在脑（C对）、心、肝、肠系膜和骨骼肌的血管也能看到，但皮肤血管一般没有这种表现。","","N"],["2012-N122",0,"第5节 机体生理功能的调节","自身调节",2012,122,"B","","交感-肾上腺髓质系统兴奋引起血压升高的调节属于",[["A","神经调节"],["B","体液调节"],["C","自身调节"],["D","神经-体液调节"]],"D","肾上腺髓质嗜铬细胞直接受交感神经节前纤维的支配。交感神经兴奋时，节前纤维末梢释放乙酰胆碱，作用于嗜铬细胞膜中的N₁受体，促使肾上腺髓质激素的分泌，同时也提高靶细胞中儿茶酚胺合成酶系的活性，促进儿茶酚胺的合成（十版生理学P372），儿茶酚胺合成并分泌入血之后参与体液调节，在此过程中，体液调节成为神经调节的一个传出环节，为典型的神经-体液调节过程（D对）。","","N"],["2012-N123",6,"第2节 体温及其调节","主要产热器官",2012,123,"B","","安静状态下机体产热的主要组织是",[["A","脑组织"],["B","肝组织"],["C","肌肉组织"],["D","脂肪组织"]],"B","体内的热量由三大营养物质在组织细胞中进行分解代谢及机体利用ATP时产生，因此，代谢水平高的组织器官，其产热量也大，反之则产热量小。人体在安静时主要由内脏产热，其中尤其以肝脏代谢最旺盛，产热量最高（B对）。人体在运动时，骨骼肌则成为主要的产热器官。","","N"],["2012-N124",6,"第2节 体温及其调节","主要产热器官",2012,124,"B","","运动状态下机体产热的主要组织是",[["A","脑组织"],["B","肝组织"],["C","肌肉组织"],["D","脂肪组织"]],"C","体内的热量由三大营养物质在组织细胞中进行分解代谢及机体利用ATP时产生，因此，代谢水平高的组织器官，其产热量也大，反之则产热量小。人体在安静时主要由内脏产热，其中尤其以肝脏代谢最旺盛，产热量最高。人体在运动时，骨骼肌则成为主要的产热器官（C对），骨骼肌紧张度稍有增强，其产热量即可明显增加，运动时，骨骼肌的产热量可由总产热量的18%增加到73%，剧烈运动时可达总产热量的90%。","","N"],["2012-N125",5,"第4节 小肠内消化","促胰液素",2012,125,"B","","引起胰腺分泌大量水分和碳酸氢盐的激素是",[["A","胃泌素"],["B","促胰液素"],["C","缩胆囊素"],["D","蛙皮素"]],"B","胰腺兼有外分泌（分泌胰液）和内分泌（分泌胰岛素）的双重功能，其中分泌胰液的外分泌部分由腺泡及导管两个部分组成，腺泡主要分泌胰酶，导管则主要分泌水和碳酸氢盐。促胰液素主要作用于胰腺导管上皮细胞，可引起胰腺分泌大量水分和碳酸氢盐（B对）。胆囊收缩素则主要作用于胰腺腺泡细胞，促进胰酶分泌，水分和碳酸氢盐的分泌量较少（C错）。蛙皮素又称胃泌素释放肽，由支配G细胞的迷走神经节后纤维释放，以促进G细胞分泌胃泌素，胃泌素具有与缩胆囊素相似的作用，以促进胰酶分泌为主，且作用较弱（AD错）。","","N"],["2012-N126",5,"第3节 胃内消化","胃排空及其控制",2012,126,"B","","加强胃运动和胆囊收缩的激素是",[["A","胃泌素"],["B","促胰液素"],["C","缩胆囊素"],["D","蛙皮素"]],"A","蛙皮素对胃运动和胆囊收缩无直接作用（D错），但蛙皮素可以促进G细胞分泌胃泌素，而胃泌素可以加强胃运动和胆囊收缩，因此蛙皮素可以间接加强胃运动和胆囊收缩，因此也可认为D是对的。","","N"],["2012-N151",1,"第3节 细胞的电活动","静息电位的产生机制",2012,151,"X","","离子通过细胞膜的扩散量取决于",[["A","膜两侧该离子的浓度梯度"],["B","膜对该离子的通透性"],["C","该离子的化学性质"],["D","该离子所受的电场力"]],"ABD","离子跨细胞膜转运的两个基本要素是驱动力和通透性，既有驱动力，又有通透性才能实现跨膜转运。离子的驱动力又称电化学驱动力，由电位差驱动力和浓度差驱动力两种力组成，静息状态下，细胞膜对K⁺的通透性较大，但是K⁺的电位差驱动力和浓度差驱动力大小基本相等，方向相反，电化学驱动力接近于零，K⁺的净扩散量也将近为零。而静息状态下，Na⁺的电位差驱动力和浓度差驱动力方向相同，受到强烈的电化学驱动力驱动，该驱动力促使Na⁺由细胞外流向细胞内，但静息时Na⁺的通透性较小，故Na⁺内流较少，一旦外来刺激，Na⁺通透性增加，将导致Na⁺大量内流，产生去极化甚至产生动作电位。故离子通过细胞膜的扩散量取决于膜两侧该离子的浓度梯度（A对）、该离子所受的电场力（D对）（前两者决定驱动力）和膜对该离子的通透性（B对），而与该离子的化学性质无关。","","N"],["2012-N152",3,"第4节 心血管活动的调节","心脏的神经支配",2012,152,"X","","乙酰胆碱对心肌生物电活动的作用是",[["A","窦房结细胞最大复极电位超极化"],["B","心房肌动作电位时程延长"],["C","窦房结细胞4期去极速度减慢"],["D","减少内向Ca²⁺流"]],"ACD","乙酰胆碱激活心肌细胞膜中的M受体，通过G蛋白-AC-cAMP-PKA通路，使胞内cAMP水平降低，PKA活性降低，进而表现出与去甲肾上腺素激活β₁受体相反的效应：负性变力作用，负性变时作用，负性变传导作用。涉及生物电活动包括：窦房结P细胞4期T型钙通道介导的钙内流减少和If型钠通道介导的钠内流减少，引起4期去极化速度减慢（C对），IK-Ach通道介导的K⁺外流增加，引起最大复极电位增大，窦房结出现超极化（A对），窦房结超极化和4期去极化速度减慢均使自律性降低，即为负性变时作用；房室交界区0期L型钙通道（ICa-L）介导的钙内流减少，0期间去极化速度和幅度减小，房室交界区（而非心房肌）动作电位时程延长（B错），房室传导速度减慢，传导性降低，即为负性变传导作用；心肌细胞2期平台期L型钙通道（ICa-L）介导的钙内流减少（D对），收缩力降低，即为负性变力作用。","","N"],["2012-N153",4,"第4节 呼吸运动的调节","肺牵张反射",2012,153,"X","","关于肺牵张反射的叙述，正确的是",[["A","正常人平静呼吸调节的基本反射"],["B","其感受器位于肺泡壁内"],["C","迷走神经为其传入神经"],["D","反射的效果是使呼吸变浅变快"]],"CD","肺牵张反射又称黑-伯反射，包括肺扩张反射和肺萎陷反射两个部分。肺扩张反射是肺扩张时抑制吸气活动的反射，肺萎陷反射是肺萎陷时增强吸气活动或促进呼气转换为吸气的反射，两种反射的感受器均位于从气管到细支气管的气道平滑肌中（B错），均通过迷走神经将冲动传入中枢（C对）。在平静呼吸时，肺扩张反射和肺萎陷反射均不参与呼吸运动的调节（A错）。肺牵张反射包括了包括肺扩张反射和肺萎陷反射，前者在吸气相抑制吸气，后者在呼气相抑制呼气，二者共同促进了呼吸状态的转变，使呼吸变浅变快（D对）。","","N"],["2012-N154",7,"第4节 尿液的浓缩和稀释","肾髓质间液渗透浓度梯度的形成",2012,154,"X","","决定尿液浓缩与稀释机制的重要因素有",[["A","肾小球滤过率"],["B","血浆胶体渗透压"],["C","肾髓质渗透梯度"],["D","抗利尿激素的分泌"]],"CD","尿液的浓缩与稀释实际上取决于集合管对小管液中水和溶质重吸收的比率，而水的重吸收较易改变，因而是其主要方面。水的重吸收取决于两个基本条件，一是肾小管内外的渗透浓度梯度，是水重吸收的动力；二是集合管对水的通透性。所以，尿的浓缩与稀释一方面取决于肾髓质渗透梯度（C对），另一方面取决于集合管对水的通透性，后者主要受血液中抗利尿激素浓度的影响（D对）。血浆胶体渗透压变化可使有效滤过压变化而影响肾小球滤过率，肾小球滤过率则影响原尿的生成量，与尿液的浓缩和稀释无关（AB错）。","","N"],["2012-N155",9,"第3节 神经系统对躯体运动的调控","脊休克",2012,155,"X","","脊髓休克过后脊髓反射恢复的特征是",[["A","低等动物反射恢复快"],["B","人类不能恢复"],["C","屈肌反射、腱反射恢复较快"],["D","发汗反射增强"]],"ACD","脊休克是指人和动物的脊髓在与高位中枢离断后，反射活动能力暂时丧失而进入无反应状态的现象，表现为横断面以下的脊髓所支配的躯体与内脏反射均减退以致消失。发生脊休克后，一些以脊髓为基本中枢的反射可逐渐在不同程度上恢复，各种反射恢复的速度与这种活动对高位中枢的依赖程度有关，如低等动物脊髓反射对高位中枢的依赖程度低，恢复速度较人快（A对B错）。此外，同一物种的各种反射的恢复也有先后，比较简单和较原始的反射（如屈肌反射和腱反射）恢复较早（C对），相对较复杂的反射（如对侧伸肌反射、搔扒反射）恢复则较慢。发汗反射的神经中枢位于脊髓，正常情况下高位中枢对脊髓发汗反射有抑制作用，脊休克恢复时发汗反射增强（D对）。","","N"],["2012-N156",10,"第2节 下丘脑-垂体及松果体内分泌","腺垂体激素的概述",2012,156,"X","","下列激素中，没有明确靶腺的激素是",[["A","生长激素"],["B","ACTH"],["C","TSH"],["D","促黑激素"]],"AD","腺垂体主要分泌七种激素，其中生长激素（A对）、催乳素和促黑激素（D对）无明确靶腺，直接作用于靶组织或靶细胞，调节物质代谢、个体生长、乳腺发育与泌乳，以及黑色素代谢等生理过程。促甲状腺激素（TSH）（C错）、促肾上腺皮质激素（ACTH）（B错）、卵泡刺激素和黄体生成素（LH）可特异性作用于各自的靶腺而发挥调节作用，故统称为促激素。","","N"],["2013-N1",1,"第1节 细胞膜的物质转运功能","主动转运",2013,1,"A","","葡萄糖从肠道进入肠上皮细胞的方式是",[["A","入胞"],["B","单纯扩散"],["C","易化扩散"],["D","主动转运"]],"D","葡萄糖从肠道进入肠上皮细胞的方式是继发性主动转运（D对）：Na⁺在肠黏膜上皮细胞顶端膜两侧浓度梯度和电位梯度的作用下，被动转入胞内，葡萄糖分子则在Na⁺进入细胞的同时逆浓度梯度被带入胞内，实现从肠道进入肠上皮细胞的过程。","","N"],["2013-N2",1,"第4节 肌细胞的收缩","骨骼肌神经肌肉接头处的兴奋传递",2013,2,"A","","神经冲动到达肌接头前膜时，引起开放的通道是",[["A","Na⁺通道"],["B","Ca²⁺通道"],["C","K⁺通道"],["D","Cl⁻通道"]],"B","神经-肌接头处兴奋传导的具体过程为：运动神经纤维传到末梢的动作电位激活接头前膜中的电压门控Ca²⁺通道（B对），导致Ca²⁺内流而触发接头前膜Ca²⁺依赖性突触囊泡出胞，释放ACh至接头间隙，再由ACh激活终板膜中的N₂型ACh受体阳离子通道，产生Na⁺内流和K⁺外流（以Na⁺内流为主），导致膜电位改变，最终引起肌细胞兴奋。","","N"],["2013-N3",1,"第3节 细胞的电活动","动作电位的概念及特点",2013,3,"A","","下列关于动作电位的描述，正确的是",[["A","刺激强度小于阈值时，出现低幅度动作电位"],["B","刺激强度达到阈值后，再增加刺激强度能使动作电位幅度增大"],["C","动作电位一经产生，便可沿细胞膜作电紧张性扩布"],["D","传导距离较长时，动作电位的大小不发生改变"]],"D","能使细胞产生动作电位的最小刺激强度，称为阈强度或阈值，刺激强度小于阈值时，不会发生动作电位（A错），刺激强度达到阈值后，可产生动作电位，并且其幅度到达该细胞动作电位的最大值，不会随刺激强度的继续增强而增大（B错），这就是动作电位的“全或无”特性，动作电位产生后，该电位变化会产生电紧张扩布，但并不局限于单个动作电位电紧张扩布的范围，而是不断产生新动作电位沿着细胞膜迅速向四周传播，直至整个细胞都依次发生一次动作电位。动作电位的传播是不衰减的，可沿细胞膜传播至整个细胞，电紧张电位的扩布是有衰减的，传播范围有限，因此C选项是错的（C错）。由于在传播过程中动作电位是不衰减的，所以动作电位的大小不会随传导距离变化而发生改变（D对），这是动作电位除“全或无”特性之外的另一种重要特性（实际上传播不衰减是因为动作电位具有“全或无”特性，在传播过程中产生的新动作电位都会达到最大值，所以是不衰减的）。","","N"],["2013-N4",2,"第2节 血细胞生理","红细胞的生理特征",2013,4,"A","","红细胞悬浮稳定性降低的原因是",[["A","血浆白蛋白增多"],["B","血浆纤维蛋白原减少"],["C","红细胞叠连加速"],["D","红细胞脆性增加"]],"C","血流中的红细胞，因胞膜表面的唾液酸所具有的负电荷等因素而互相排斥，使细胞保持一定间距，故彼此分散悬浮而下沉缓慢。正常情况下，血浆蛋白所带的正、负电荷呈平衡状态（白蛋白带负电荷，球蛋白与纤维蛋白原带正电荷），如血浆中纤维蛋白原或球蛋白含量增加或白蛋白含量减少（AB错），改变了电荷的平衡，致使红细胞表面的负电荷减少，容易使红细胞叠连（C对）而血沉加快，悬浮稳定性降低。红细胞表面积与体积之比可以影响红细胞沉降率，但更主要的因素在于血浆成分的变化，红细胞渗透脆性增加提示红细胞衰老等红细胞本身的病变，与红细胞悬浮稳定性降低的相关性不大（D错）。","","N"],["2013-N5",2,"第3节 生理性止血","纤维蛋白的生成",2013,5,"A","","凝血酶的主要作用是",[["A","激活因子ⅩⅢ"],["B","分解因子Ⅰ"],["C","活化血小板"],["D","激活因子Ⅷ"]],"B","血液凝固是由凝血因子按照一定的顺序相继激活而生成凝血酶，最终由凝血酶催化使纤维蛋白原（凝血因子Ⅰ）变为纤维蛋白的过程，故凝血酶的主要作用是分解纤维蛋白原（凝血因子Ⅰ）（B对）。激活因子Ⅷ、XⅢ和活化血小板均为凝血酶的功能，但均不是主要功能。","","N"],["2013-N6",2,"第4节 血型和输血原则","ABO血型系统",2013,6,"A","","ABO血型系统的主要抗体是",[["A","IgA"],["B","IgM"],["C","IgE"],["D","IgG"]],"B","ABO天然抗体和免疫性抗体两类，天然抗体为IgM，免疫性抗体为IgG。新生儿出生后2～8个月，即开始出现ABO血型天然抗体，天然抗体在人体内天然存在，人人都有，是ABO血型的主要抗体（B对）。由于自然界广泛存在A抗原和B抗原，正常成年人可能因接受外源性刺激激而产生免疫性IgG型抗体，但免疫性抗体不属于ABO血型的主要抗体（D错）。","","N"],["2013-N7",3,"第1节 心脏的泵血功能","心室收缩的后负荷",2013,7,"A","","心室肌收缩的后负荷是",[["A","等容收缩期初心室内压"],["B","大动脉血压"],["C","快速射血期心室内压"],["D","减慢射血期心室内压"]],"B","肌肉在收缩过程中所承受的负荷，称为后负荷。对心室肌来说，收缩过程中所承受的负荷为大动脉血压（B对）。与后负荷对应的概念是前负荷，前负荷是指肌肉在收缩前所承受的负荷，该负荷可以用心室舒张末期容积或心室舒张末期压力来表示。","","N"],["2013-N8",3,"第2节 心脏的电生理学及生理特性","心脏的起搏点",2013,8,"A","","窦房结能成为心脏正常起搏点的原因是",[["A","静息电位仅为-70mV"],["B","阈电位为-40mV"],["C","0期去极化速度快"],["D","4期去极化速率快"]],"D","窦房结能成为心脏正常起搏点的原因是窦房结在所有心脏自律细胞中，4期自动去极化速度最快（D对），自律性最高。生理情况下，整个心脏的活动总是按照当时自律性最高的组织所发出的节律性兴奋来进行。正常情况下，窦房结的自律性最高，由它发出的节律性兴奋依次激动心房肌、房室交界、房室束、心室内传导组织和心室肌，引起整个心脏的节律性兴奋和收缩。","","N"],["2013-N9",3,"第3节 血管生理","血流阻力",2013,9,"A","","影响外周血管阻力的主要因素是",[["A","血液黏滞性"],["B","大动脉弹性"],["C","血管长度"],["D","小动脉口径"]],"D","血液在血管内流动时遇到的阻力称为血流阻力，血流阻力的计算公式为R=8ηL/πr⁴，其中r为血管半径、η为血液黏度、L为血管长度，该式表明血流阻力与血管的长度和血液的黏滞度成正比，而与血管半径的4次方成反比。一般情况下，血管的长度和血液黏滞度比较稳定，口径则可能随血管的收缩或舒张出现较大变化，故影响外周血管阻力的主要因素是小动脉口径（D对）。","","N"],["2013-N10",4,"第2节 肺换气和组织换气","通气_血流比值",2013,10,"A","","下列情况中，能够使肺通气/血流比值增高最明显的是",[["A","肺纤维化形成"],["B","肺水肿"],["C","支气管哮喘发作"],["D","肺栓塞"]],"D","肺通气/血流比值是指每分钟肺泡通气量和每分钟肺血流量的比值。肺栓塞（D对）时，每分钟肺血流量减少，故通气/血流比值增高；肺纤维化（A错）、肺水肿（B错）、支气管哮喘发作时（C错），每分钟肺泡通气量减少，导致通气/血流比值降低。","","N"],["2013-N11",4,"第3节 气体在血液中的运输","氧的运输",2013,11,"A","","关于气体在血液中运输的叙述，错误的是",[["A","CO₂和Hb结合不需酶的催化"],["B","CO₂主要以HCO₃⁻形式运输"],["C","O₂和Hb结合反应快并需酶催化"],["D","CO₂和O₂都有物理溶解形式"]],"C","O₂和CO₂都以物理溶解和化学结合两种形式存在于血液中（D对）。其中O₂仅约1.5%以物理溶解的形式存在，其余98.5%则以化学结合（氧合血红蛋白）的形式存在；CO₂约5%以物理溶解的形式运输，其余95%则以化学结合（88%碳酸氢盐+7%氨基甲酰血红蛋白）的形式运输（B对）。氧合血红蛋白和氨基甲酰血红蛋白分别为Hb与O₂和CO₂的结合形式，Hb与O₂和CO₂的结合反应均快速、可逆，无需酶的催化（A对）（C错，为本题正确答案）。","","N"],["2013-N12",5,"第4节 小肠内消化","小肠的运动形式",2013,12,"A","","胃和小肠都具有的运动形式是",[["A","紧张性收缩"],["B","容受性舒张"],["C","分节运动"],["D","袋状往返运动"]],"A","紧张性收缩是整个消化道共有的运动形式（A对）。容受性舒张（十版生理学P177）是胃特有的运动形式（B错）。分节运动（十版生理学P183）是小肠特有的运动形式（C错）。袋状往返运动（十版生理学P187）是结肠特有的运动形式（D错）。","","N"],["2013-N13",5,"第2节 口腔内消化和吞咽","唾液的性质和成分",2013,13,"A","","唾液淀粉酶发挥作用的最适pH值是",[["A","2.2～3.0"],["B","4.0～5.0"],["C","6.0～7.0"],["D","8.0～9.0"]],"C","唾液淀粉酶可水解淀粉为麦芽糖，该酶的最适pH为中性，pH低于4.5时将完全失活，所以唾液淀粉酶发挥作用的最适pH值是6.0～7.0（C对ABD错）。","","N"],["2013-N14",7,"第3节 肾小管和集合管的物质转运功能","K⁺的重吸收和分泌",2013,14,"A","","关于肾脏重吸收和分泌K⁺的叙述，正确的是",[["A","近端肾小管重吸收25%～30%的K⁺"],["B","髓袢重吸收约65%～70%的K⁺"],["C","远端肾小管分泌K⁺，但不重吸收K⁺"],["D","远曲小管分泌K⁺受醛固酮调节"]],"D","K⁺的重吸收以近端小管为主，小管液中的K⁺有65%～70%在近端小管被重吸收（A错），25%～30%在髓袢被重吸收（B错），也有少量K⁺在远端小管后半段和集合管（闰细胞）被重吸收（C错），当然K⁺在远端小管和集合管是以分泌为主的：远端小管和集合管上皮细胞内的K⁺浓度较高，顶端膜对K⁺有通透性，K⁺可顺化学梯度通过钾通道进入小管液，此为K⁺的分泌过程，该过程受醛固酮的调节，醛固酮可以作用于肾远曲小管和集合管的上皮细胞，增加K⁺的排泄（分泌）和增加Na⁺、水的重吸收（D对）。","","N"],["2013-N15",7,"第2节 肾小球的滤过功能","肾小球毛细血管压",2013,15,"A","","血液流经肾小球时，促进原尿生成的直接动力是",[["A","全身平均动脉压"],["B","血浆胶体渗透压"],["C","肾动脉压"],["D","肾小球毛细血管压"]],"D","肾小球滤过生成原尿的有效滤过压=（肾小球毛细血管血压+囊内液胶体渗透压）-（血浆胶体渗透压+肾小囊内压）。因此，肾小球毛细血管血压（D对）和囊内液胶体渗透压是促进原尿生成的直接动力，血浆胶体渗透压（B错）和肾小囊内压是超滤的直接阻力。当肾动脉灌注压在70～180mmHg（十版生理学P217）（八版P243数据为80～160mmHg）范围变动时，肾脏可通过自身调节保持肾血流量相对稳定，因此全身平均动脉压和肾动脉压对肾小球滤过的影响较小（AC错）。","","N"],["2013-N16",8,"第3节 视觉","晶状体变凸",2013,16,"A","","当睫状肌收缩时，可引起的生理效应是",[["A","睫状小带紧张性增加"],["B","角膜曲度增加"],["C","瞳孔增大"],["D","晶状体曲度增加"]],"D","当眼视近物时，可反射性地引起睫状肌收缩，导致连接于晶状体囊的睫状小带松弛（A错），晶状体因其自身的弹性而向前和向后凸出，曲度增加（D对）。对于特定的个体来说，角膜曲度是固定值，不能调节（B错）。瞳孔增大是由瞳孔开大肌（虹膜辐射状肌）收缩引起（C错）。","","N"],["2013-N17",8,"第4节 听觉","中耳的功能(1)",2013,17,"A","","声波由鼓膜经听骨链传向卵圆窗时出现的振动变化是",[["A","幅度增大，压强增大"],["B","幅度减小，压强减小"],["C","幅度增大，压强减小"],["D","幅度减小，压强增大"]],"D","声波由鼓膜经听骨链到达卵圆窗膜时，其声压增强，振幅略有减小。这是因为：①鼓膜的实际振动面积约55mm²，而卵圆窗膜的面积仅3.2mm²，二者之比为17.2：1。如果听骨链传递声波时的总压力不变，而作用于卵圆窗膜上的压强则为鼓膜上压强的17.2倍。②听骨链杠杆的长臂与短臂之比为1.3：1（约为4：3），因而通过听骨链传递，杠杆短臂一侧的压力将比长臂侧增大1.3倍，而振幅约减小1/4。综上两方面的作用，声波在中耳传递过程中将增压22.4倍（17.2×1.3），而幅度约减小1/4（Ｄ对）。","","N"],["2013-N18",8,"第2节 躯体和内脏感觉","痛觉信息的感受和传导",2013,18,"A","","传导慢痛的外周神经纤维是",[["A","Aγ纤维"],["B","Aδ纤维"],["C","B类纤维"],["D","C类纤维"]],"D","根据神经纤维兴奋传导速度的差异，将哺乳动物的周围神经纤维分为A、B、C三类，其中A类纤维再分为α、β、γ、δ四个亚类。A类和B类是有髓神经纤维，传导速度较快，C类是无髓神经纤维，传导速度较慢。痛觉传入纤维有Aδ有髓纤维和C类无髓纤维两类，传导快痛的外周神经纤维主要是Aδ神经纤维（B错），传导慢痛的外周神经纤维主要是C类无髓神经纤维（D对）。Aγ类纤维的主要功能是支配梭内肌（A错），B类纤维是自主神经节前纤维（C错）。","","N"],["2013-N19",9,"第3节 神经系统对躯体运动的调控","腱器官及反牵张反射",2013,19,"A","","腱器官传入冲动增加所引起的效应是",[["A","对同一肌肉的γ运动神经元起抑制作用"],["B","对同一肌肉的α运动神经元起抑制作用"],["C","使梭外肌收缩增强"],["D","使梭内肌收缩增强"]],"B","肌梭是一种感受肌肉长度的感受器，其传入冲动对同一肌肉的α运动神经元起兴奋作用。除肌梭外，骨骼肌中还有一种能感受肌肉张力的感受器，称为腱器官，腱器官位于肌腱内，与梭外肌纤维成串联关系，当肌肉受到的牵拉力量过强时致张力增加时，腱器官兴奋，引起支配同一肌肉的α运动神经元的活动受到抑制（B对），从而使梭外肌的活动受抑制（C错），该反射效应与牵张反射的效应是相反，称为反牵张反射。腱器官的传入冲动对γ运动神经元没有作用（A错），不能兴奋梭内肌（D错）。","","N"],["2013-N20",9,"第4节 神经系统对内脏活动、本能行为和情绪的调节","交感神经系统的功能",2013,20,"A","","交感神经系统兴奋时，引起的生理效应是",[["A","胃肠运动增强"],["B","支气管平滑肌收缩"],["C","瞳孔开大肌收缩"],["D","促进胰岛素的分泌"]],"C","大多数交感节后纤维释放的递质是去甲肾上腺素（除支配汗腺和骨骼肌血管的交感节后纤维释放乙酰胆碱外），交感神经系统的活动与各器官上去甲肾上腺素受体的分布有关。交感神经兴奋时，作用于胃平滑肌β₂受体或小肠平滑肌的α₂、β₂受体使胃肠道平滑肌舒张，抑制胃肠运动（A错）；作用于支气管平滑肌的β₂受体使支气管平滑肌舒张（B错）；作用于瞳孔开大肌（虹膜辐射状肌）的α₁受体使瞳孔开大肌收缩，瞳孔扩大（C对）；作用于胰岛β细胞（即B细胞）上的α₂受体抑制胰岛素分泌（D错）。交感神经兴奋的状态可以用机体在剧烈运动时的生理状态来协助记忆：机体在剧烈运动时交感神经兴奋（十版生理学P322），心率加快、心肌收缩力增强，心输出量增加，目的是为全身的肌肉提供更多的血液和氧气；呼吸运动加强，支气管平滑肌舒张，肺泡通气量，目的是为了血液提供更多的氧气；皮肤、肾、胃肠等全身各处的血管平滑肌均收缩，但骨骼肌血管舒张，目的是为了让血液重新分配，为肌肉提供更多的血液；由于全身血液分配至骨骼肌，导致胃肠道供血不足，不利于胃肠道进行消化和吸收，故消化道平滑肌舒张，括约肌收缩，消化腺分泌减少；剧烈运动时，甲状腺激素、胰高血糖素等分解代谢的激素分泌增多，胰岛素等促进合成代谢的激素分泌减少，目的是为了骨骼肌提供更多的能量来源等等。","","N"],["2013-N21",10,"","",2013,21,"A","","肾上腺皮质功能低下时出现的变化是",[["A","血容量减少"],["B","血压升高"],["C","血浆Na⁺浓度升高"],["D","血浆K⁺浓度降低"]],"A","肾上腺皮质功能低下时，盐皮质激素（醛固酮）分泌不足，使Na⁺、水排出过多，出现血容量减少（A对）、血压降低（B错）、低血钠（C错）、高血钾（D错）和酸中毒等症状。","","N"],["2013-N22",10,"第1节 内分泌与激素","胺类激素",2013,22,"A","","甲状腺激素的化学本质是",[["A","糖蛋白"],["B","肽类"],["C","胺类"],["D","类固醇类"]],"C","激素分子结构形式多样，其化学本质直接决定激素对靶细胞的作用机制。激素一般按化学性质可分为胺类、肽与蛋白质类和脂类。胺类激素的典型代表为儿茶酚胺类激素（去甲肾上腺素、肾上腺素和多巴胺等）、甲状腺激素（C对）、褪黑素等。肽类和蛋白质类激素的典型代表包括下丘脑调节肽、腺垂体激素、甲状旁腺素、胰岛素、胃肠激素等。脂类激素的典型代表为类固醇激素，如孕酮、醛固酮、皮质醇、睾酮、雌二醇和胆钙化醇等。","","N"],["2013-N23",11,"第2节 女性生殖功能及其调节","雌激素、孕激素的作用",2013,23,"A","","雌激素和孕激素作用的相同点是",[["A","促进乳腺导管增生和延长"],["B","使子宫内膜变厚"],["C","使子宫输卵管平滑肌活动减弱"],["D","减少宫颈黏液的分泌"]],"B","雌激素促进乳腺导管增生和延长，孕激素促进乳腺腺泡的发育和成熟（A错）。雌激素能够促进子宫发育，使子宫内膜增厚，孕激素虽然抑制子宫内膜细胞增殖，但可促进子宫内膜血管和腺体增生，使子宫内膜进一步增厚（B对），利于胚胎着床。雌激素使子宫输卵管平滑肌活动增强，孕激素使子宫输卵管平滑肌活动减弱（C错）。雌激素增加宫颈黏液的分泌，孕激素减少宫颈黏液的分泌（D错）。","","N"],["2013-N24",11,"第1节 男性生殖功能及其调节","雄激素的合成、代谢和利用",2013,24,"A","","灭活睾酮的器官是",[["A","肝脏"],["B","肾脏"],["C","肺脏"],["D","靶组织细胞"]],"A","与雌激素、孕激素一样，睾酮主要在肝内降解灭活（A对），灭活后的代谢产物随尿液排出，少数经粪便排出”。","","N"],["2013-N121",0,"第5节 机体生理功能的调节","体液调节",2013,121,"B","","胰岛素抑制胰岛A细胞分泌胰高血糖素属于",[["A","旁分泌调节"],["B","血分泌调节"],["C","自分泌调节"],["D","腔分泌调节"]],"A","旁分泌（十版生理学P9、P338）是指细胞产生的激素或调节因子通过细胞间隙对邻近的其他种类细胞起促进或抑制作用的调节方式，胰岛素抑制胰岛α细胞分泌胰高血糖素属于典型的旁分泌调节。血分泌（十版生理学P337）是远距分泌的另一种叫法，指内分泌细胞分泌的激素循血液途径作用于全身各处的靶细胞的调节方式。自分泌（十版生理学P9）是指激素分泌后在局部扩散又反馈作用于产生该激素的内分泌细胞本身，如胰岛素亦可抑制β细胞自身分泌胰岛素的活动。腔分泌（十版生理学P337）指胃肠激素由内分泌细胞释放后，沿着细胞之间的缝隙，弥散入胃肠腔而起作用的调节方式。","","N"],["2013-N122",10,"第2节 下丘脑-垂体及松果体内分泌","血管升压素",2013,122,"B","","血管升压素促进集合管上皮细胞重吸收水属于",[["A","旁分泌调节"],["B","血分泌调节"],["C","自分泌调节"],["D","腔分泌调节"]],"B","旁分泌（十版生理学P9）是指细胞产生的激素或调节因子通过细胞间隙对邻近的其他种类细胞起特定作用的调节方式；血分泌（十版生理学P337）是远距分泌的另一种叫法，指内分泌细胞分泌的激素循血液途径作用于全身各处的靶细胞的调节方式；自分泌（十版生理学P9）是指激素分泌后在局部扩散又反馈作用于产生该激素的内分泌细胞本身；腔分泌（十版生理学P337）指胃肠激素由内分泌细胞释放后，沿着细胞与细胞之间的缝隙，弥散入胃肠腔而起作用的调节方式。血管升压素由下丘脑视上核和室旁核神经元合成，合成后经下丘脑-垂体束运输到神经垂体储存，当机体活动需要时释放入血液循环，作用于全身各处的靶细胞，为典型的血分泌调节（B对）。","","N"],["2013-N123",6,"第2节 体温及其调节","蒸发散热",2013,123,"B","","环境温度等于皮肤温度时的主要散热方式是",[["A","传导散热"],["B","辐射散热"],["C","对流散热"],["D","蒸发散热"]],"D","环境温度等于或高于皮肤温度时的主要散热方式是蒸发散热（D对），环境温度低于皮肤温度时的主要散热方式是辐射散热、传导散热和对流散热。","","N"],["2013-N124",6,"第2节 体温及其调节","辐射散热",2013,124,"B","","环境温度25℃时，机体的主要散热方式是",[["A","传导散热"],["B","辐射散热"],["C","对流散热"],["D","蒸发散热"]],"B","环境温度为25℃时，远低于人体表面温度，人体散热方式主要为辐射散热、传导散热和对流散热，其中尤其以辐射散热为主（B对）。环境温度等于或高于皮肤温度时的主要散热方式是蒸发散热。","","N"],["2013-N125",5,"第7节 吸收","钙的吸收",2013,125,"B","","对钙吸收有阻碍作用的是",[["A","脂肪酸"],["B","磷酸盐"],["C","维生素D"],["D","维生素C"]],"B","钙盐只有在水溶液状态，并且不被肠腔中其他物质沉淀的情况下，才能被吸收。磷酸盐可与Ca²⁺形成不溶解的磷酸钙沉淀，而阻碍钙的吸收（B对）。脂肪酸可与Ca²⁺结合成钙皂，后者可和胆汁酸结合，形成水溶性复合物而被吸收，因此脂肪酸可促进钙的吸收（A错）。维生素D的活性形式是1，25-（OH）₂VitD₃（即钙三醇），钙三醇可诱导小肠上皮细胞合成钙结合蛋白、钙通道、钙泵等钙吸收促进蛋白，从而促进钙的吸收（十版生理学P190）（C错）。维生素C能够将Fe³⁺还原为Fe²⁺而促进铁的吸收（十版生理学P190），但是对钙的吸收没有影响（D错）。","","N"],["2013-N126",5,"第7节 吸收","铁的吸收",2013,126,"B","","对铁吸收有促进作用的是",[["A","脂肪酸"],["B","磷酸盐"],["C","维生素D"],["D","维生素C"]],"D","脂肪酸、磷酸盐和维生素D均为钙吸收的影响因素，不影响铁的吸收（ABC错）。食物中的铁绝大部分是高铁（Fe³⁺），不易被吸收，当它还原为亚铁（Fe²⁺）时则较易被吸收。维生素C能将Fe³ ⁺还原为Fe²⁺而促进铁的吸收（D对）。","","N"],["2013-N151",1,"第4节 肌细胞的收缩","兴奋-收缩耦联的基本步骤",2013,151,"X","","属于骨骼肌的兴奋-收缩耦联过程的有",[["A","电兴奋通过横管传向肌细胞的深处"],["B","三联管的信息传递，导致终池Ca²⁺释放"],["C","肌浆中的Ca²⁺与肌钙蛋白结合可触发肌丝滑行"],["D","钙泵活动将Ca²⁺泵到细胞外，降低肌浆中Ca²⁺浓度"]],"ABC","钙泵位于纵行肌质网（LSR）上，胞质内Ca²⁺浓度升高时钙泵被激活，将胞质内Ca²⁺泵入肌质网（SR）中（而不是将Ca²⁺泵到细胞外）（D错），降低肌浆中Ca²⁺浓度，引起肌肉舒张。","","N"],["2013-N152",3,"第4节 心血管活动的调节","心脏的神经支配",2013,152,"X","","儿茶酚胺对心肌生物电活动的作用有",[["A","加强自律细胞4期内向电流If"],["B","复极2期Ca²⁺内流加快"],["C","慢反应细胞0期Ca²⁺内流减慢"],["D","自律细胞4期自动去极速度加快"]],"ABD","儿茶酚胺（去甲肾上腺素）对心肌的生物学作用包括正性变时作用、正性变力作用和正性变传导作用，这些生物学作用与儿茶酚胺作用于心肌细胞之后产生的特定生物电活动有关。包括：促进自律细胞4期T型钙通道介导的钙内流和If型钠通道介导的钠内流（A对），使4期自动去极速度加快（D对），介导正性变时作用；促进心肌细胞复极2期（平台期）L型钙通道介导的钙内流增加（B对），介导正性变力作用；慢反应细胞（房室结细胞）0期去极化L型钙通道介导的钙内流速度加快（C错），房室传导速度加快，引起正性变传导作用。","","N"],["2013-N153",4,"第1节 肺通气","非弹性阻力",2013,153,"X","","引起气道阻力增加的调节因素有",[["A","迷走神经兴奋"],["B","交感神经兴奋"],["C","气流速度加快"],["D","肾上腺皮质激素分泌增多"]],"AC","气道阻力是指气体流经呼吸道时气体分子之间和气体分子与气道壁之间的摩擦力，是非弹性阻力（气道阻力、惯性阻力和组织的黏滞阻力）的主要组成部分，受气道口径、气流速度和气流形式的影响，气道口径减小、气流速度加快（C对）、气流呈湍流等情况均可使气道阻力增大。气道口径受自主神经系统的调节，其中迷走神经兴奋时，气道平滑肌收缩，气道口径减小，气道阻力增加（A对）。交感神经兴奋时，气道平滑肌舒张，气道口径增加，气道阻力减小（B错）。肾上腺皮质激素包括糖皮质激素、盐皮质激素和性激素（十版生理学P368），除了糖皮质激素具有气道抗炎作用（可用来治疗支气管哮喘等慢性气道炎症）外，盐皮质激素和性激素对气道无引起口径改变等其他作用（D错）。","","N"],["2013-N154",7,"第5节 尿生成的调节","醛固酮的功能",2013,154,"X","","能够增加尿钠重吸收的因素有",[["A","醛固酮分泌增多"],["B","抗利尿激素分泌增多"],["C","血钾浓度增高"],["D","血钠浓度增高"]],"AC","小管液中的钠约65%～70%在近端小管重吸收，约20%在髓袢重吸收，约12%在远曲小管和集合管重吸收，其中前两者吸收的比例较固定，后者根据机体水、盐平衡状况接受醛固酮的调节。醛固酮的主要作用是保钠保水排钾，醛固酮分泌增多能够增加尿钠重吸收（A对）。血K⁺浓度升高时，能够促进醛固酮分泌增多，进而增加尿钠重吸收（C对）；血钠浓度增高时，则抑制醛固酮的分泌，使尿钠重吸收减少（D错）。本题B选项存在争议，九版生理学P354认为血管升压素能促进肾脏重吸收水和Na⁺，保留细胞外液量。九版病理学P30认为抗利尿激素（ADH）能促进远曲肾小管和集合管对水钠的重吸收，引起水钠潴留。故B项也应为正确答案，官方参考答案为AC。","","N"],["2013-N155",9,"第3节 神经系统对躯体运动的调控","前庭小脑",2013,155,"X","","小脑功能异常可能出现的现象有",[["A","肌张力增高"],["B","意向性震颤"],["C","站立不稳"],["D","位置性眼震颤"]],"BCD","小脑根据其传入、传出纤维联系，可将小脑分为前庭小脑、脊髓小脑和皮层小脑三个主要功能区。前庭小脑主要由绒球小结叶构成，前庭小脑主要功能是控制躯体平衡和眼球运动，前庭小脑伤后表现为身体平衡失调，站立不稳（C对），步基宽，步态蹒跚，容易跌倒，位置性眼震颤（当其头部固定于某一特定位置时出现的眼震颤）（D对）等症状，但其随意运动的协调不受影响。脊髓小脑由蚓部和半球中间部组成，脊髓小脑主要功能是调节进行过程中的运动，协助大脑皮层对随意运动进行适时的控制。脊髓小脑伤后表现为患者的运动变得笨拙而不准确，随意运动的力量、方向及限度发生紊乱，意向性震颤（肌肉在动作过程中抖动而把握不住方向，在精细动作的终末出现震颤）（B对），小脑共济失调，肌张力减退（A），四肢乏力等，如果仅损伤肌张力抑制区（蚓部），也可能会出现肌张力增高，A选项存在争议。皮层小脑主要由半球外侧部构成，皮层小脑的主要功能是参与随意运动的设计和程序编程，皮层小脑受损后无明显的临床表现。","","N"],["2014-N1",0,"第5节 机体生理功能的调节","神经调节",2014,1,"A","","下列生理功能活动中，主要通过神经反射而完成的调节是",[["A","育龄期女性月经周期的正常进行"],["B","肢体在受伤害性刺激时的回撤动作"],["C","餐后血糖很快恢复正常水平的过程"],["D","正常人体的生长与发育过程"]],"B","月经是在卵巢激素周期性分泌的影响下，子宫内膜发生周期性剥落，产生流血的现象，故月经周期的正常进行主要与卵巢激素有关，属于体液调节（A错）。肢体在受伤害性刺激时的回撤动作为痛觉感受器介导的非条件反射，属于典型的神经反射（B对）。用餐以后血中的葡萄糖含量升高，促进胰岛β细胞分泌胰岛素，胰岛素通过增加血糖的去路及减少血糖的来源实现降糖作用，胰岛素对血糖的调节属于体液调节（C错）。人的生长发育受多种激素的调节，包括生长激素、甲状腺激素、胰岛素、肾上腺皮质激素、雄激素、雌激素等等（十版生理学P403），属于典型的体液调节（D错）。","","N"],["2014-N2",1,"第1节 细胞膜的物质转运功能","继发性主动转运",2014,2,"A","","葡萄糖在肾小管管腔面被重吸收的跨膜转运方式是",[["A","原发性主动转运"],["B","继发性主动转运"],["C","入胞作用"],["D","经通道易化扩散"]],"B","葡萄糖从肠道进入肠上皮细胞和从肾小管管腔进入肾小管上皮细胞的方式均是继发性主动转运（B对），葡萄糖进入其他细胞（如红细胞、脑细胞）则是通过经载体介导的易化扩散的形式，此考点在真题里面反复出现，需要牢记。","","N"],["2014-N3",1,"第3节 细胞的电活动","动作电位期间膜离子通透性的变化",2014,3,"A","","下列情况下，能加大神经细胞动作电位幅度的是",[["A","延长刺激持续时间"],["B","降低细胞膜阈电位"],["C","增加细胞外液中Na⁺浓度"],["D","增大刺激强度"]],"C","本题与1996N2A的题干与选项互换了。增加神经细胞外液Na⁺浓度，会加大细胞外液与细胞内液之间的浓度差，Na⁺内流增多，超射值增大，动作电位的幅度也增大（C对）。延长刺激持续时间、降低细胞膜阈电位、增大刺激强度可以使动作电位更容易发生，但不会影响动作电位的幅度（ABD错），因为动作电位具有全或无的特性，细胞接受的刺激强度未达到阈值，动作电位不会发生，刺激强度达到阈值之后，即可触发动作电位，而且其幅度立即达到该细胞动作电位的最大值，而不会因刺激强度的继续增强而随之增大。","","N"],["2014-N4",2,"第2节 血细胞生理","红细胞的生理特征",2014,4,"A","","红细胞在流经狭小毛细血管和血窦时不易被挤破，最主要的原因是",[["A","红细胞内的黏度较高"],["B","此处的血流速度缓慢"],["C","红细胞膜的弹性较好"],["D","红细胞呈双凹圆碟形"]],"D","正常的双凹圆碟形使红细胞具有较大的表面积与体积之比，使红细胞在受到外力时易于变形，是红细胞在流经狭小毛细血管和血窦时不易被挤破的主要原因（D对）。红细胞膜弹性较好也可使红细胞变形能力增强，使红细胞不易被挤破，但相对红细胞双凹圆碟形的形状来说，不是主要原因（C错）。红细胞内的黏度较高使红细胞变形能力下降，流经狭小毛细血管和血窦时变得容易破裂（A错）。血流速度的快慢与红细胞的变形能力无关（B错）。","","N"],["2014-N5",2,"第3节 生理性止血","凝血因子",2014,5,"A","","下列凝血因子中，需要维生素K参与其合成的是",[["A","因子Ⅱ、因子Ⅶ、因子Ⅸ、因子Ⅹ"],["B","因子Ⅲ、因子Ⅶ、因子Ⅹ、因子Ⅺ"],["C","因子Ⅴ、因子Ⅷ、因子Ⅸ、因子Ⅺ"],["D","因子Ⅰ、因子Ⅲ、因子Ⅷ、因子Ⅻ"]],"A","维生素K是γ-谷氨酰羧化酶的辅酶，可以促进FⅡ、FⅦ、FⅨ和FⅩ的谷氨酸残基被羧化为γ-羧基谷氨酸，从而具备与Ca²⁺结合的能力，FⅡ、FⅦ、FⅨ和FⅩ与Ca²⁺结合之后发生变构效应，暴露出与磷脂结合的部位而参与凝血。故FⅡ、FⅦ、FⅨ、FⅩ的合成需要维生素K的参与，它们又被称为依赖维生素K的凝血因子（A对）。","","N"],["2014-N6",3,"第1节 心脏的泵血功能","心率",2014,6,"A","","心率过快时，心输出量减少的主要原因是",[["A","等容收缩期缩短"],["B","心室充盈期缩短"],["C","心房收缩期缩短"],["D","等容舒张期缩短"]],"B","在一定范围内，心率加快可使心输出量增加。当心率增快但尚未超过一定限度时，尽管此时心室充盈时间有所缩短，但由于静脉回心血量的大部分在快速充盈期内进入心室，因此心室充盈量和搏出量不会明显减少，而心率的增加可使每分输出量明显增加。但是，如果心率过快，当超过每分钟160～180次时，将使心室舒张期（主要是充盈期，而对等容舒张期影响较小）明显缩短（B对），心舒期充盈量明显减少，因此搏出量明显减少，从而导致心输出量下降。","","N"],["2014-N7",3,"第3节 血管生理","血压",2014,7,"A","","在体循环中，血压下降幅度最为显著的血管部位是",[["A","毛细血管"],["B","中动脉"],["C","静脉"],["D","小动脉"]],"D","根据十版生理学P109图 4-22正常人平卧位时不同血管血压的示意图，可知血压下降幅度最为显著的是微动脉，其次为毛细血管，再次为小动脉或静脉，由于本题无微动脉选项，故毛细血管（A）应为最佳答案。本题的参考答案为D，存在争议。","","N"],["2014-N8",4,"第1节 肺通气","肺容量",2014,8,"A","","哮喘发作时，1秒用力呼气量（FEV₁）/用力肺活量（FVC）的检查结果是",[["A","FEV₁减小，FVC基本不变，FEV₁/FVC减小"],["B","FEV₁基本不变，FVC减小，FEV₁/FVC增大"],["C","FEV₁和FVC均减小，FEV₁/FVC基本不变"],["D","FEV₁和FVC均增大，FEV₁/FVC基本不变"]],"A","解释用力肺活量（FVC）和1秒用力呼气量（FEV₁）需要从肺活量讲起。尽力吸气后，从肺内所能呼出的最大气体量称为肺活量，肺活量测定方法简单，重复性好，可反映一次通气的最大能力，是肺功能测定的常用指标。但是由于测定肺活量时不限制呼气的时间，在某些肺组织弹性降低或呼吸道狭窄的患者，通气功能已经受到损害，如果延长呼气时间，所测得的肺活量仍可正常。因此，肺活量难以充分反映肺组织的弹性状态和气道通畅程度等变化，即不能充分反映肺通气功能的状况。用力肺活量和用力呼气量能更好地反映肺通气功能。用力肺活量是指一次最大吸气后，尽力尽快呼气所能呼出的最大气体量 。正常时，用力肺活量略小于在没有时间限制条件下测得的肺活量；但在气道阻力增高时，用力肺活量却低于肺活量。第1秒钟内的用力肺活量称为1秒用力呼气量 ，曾称为时间肺活量。为排除肺容积差异的影响，通常以FEV₁所占用力肺活量的百分数表示，正常时，FEV₁/FVC约为80％。FEV₁在临床鉴别限制性肺疾病和阻塞性肺疾病中具有重要意义。在肺纤维化等限制性肺疾病患者，FEV₁和FVC均下降，但FEV₁/FVC可正常甚至超过80％；而在哮喘等阻塞性肺疾病患者，FEV₁的降低比FVC更明显，因而FEV₁/FVC也减小（A对）。","","N"],["2014-N9",4,"第2节 肺换气和组织换气","气体的分压差",2014,9,"A","","肺泡内O₂向肺毛细血管扩散，肺毛细血管内CO₂向肺泡扩散的决定因素是",[["A","气体的溶解度"],["B","气体的扩散系数"],["C","气体的分压差"],["D","气体的分子量"]],"C","气体分子不停地进行无定向的运动，当不同区域存在气压差时，气体分子将从气压高处向气压低处发生净转移，直至取得动态平衡，因此气体的分压差是气体扩散的动力，决定了气体扩散的方向（C对）。","","N"],["2014-N10",4,"","",2014,10,"A","","在给肺心病患者应用氧疗时，宜予吸入气体的氧浓度是",[["A","15%～20%"],["B","95%～100%"],["C","80%～85%"],["D","25%～30%"]],"D","肺心病常导致Ⅱ型呼吸衰竭，出现CO₂潴留和缺O₂，虽然CO₂潴留和缺O₂分别可通过中枢化学感受器（为主）和外周化学感受器介导的化学感受性反射使呼吸运动加深加快，肺通气量增加，但是长时间CO₂潴留对中枢化学感受器的刺激存在明显的适应现象，长时间低O₂对外周化学感受器刺激的适应现象则不明显，因此肺心病患者主要依靠低O₂对外周化学感受器刺激进行代偿性呼吸调节。如果在给肺心病患者应用氧疗时吸入高浓度氧，可能由于解除了低氧的刺激作用而引起呼吸抑制，因此宜采用持续低浓度给氧，低浓度给氧的浓度区间在实际临床工作中及教科书有不同版本，包括24%～28%、25%～30%、28%～30%、24%～35%、25%～35%等，24%～35%之间的取值均可认为是正确的（D对）。","","N"],["2014-N11",5,"第3节 胃内消化","促进胃液分泌的主要因素",2014,11,"A","","迷走神经节后纤维兴奋引起胃幽门部胃泌素分泌的神经递质是",[["A","三磷酸腺苷"],["B","蛙皮素"],["C","乙酰胆碱"],["D","一氧化氮"]],"B","迷走神经节后纤维刺激胃液分泌的机制有两种，即：①释放乙酰胆碱直接促进壁细胞分泌胃酸；②释放蛙皮素（十版生理学称铃蟾素）（B对）促进胃幽门部G细胞分泌胃泌素，再通过胃泌素促进壁细胞分泌胃酸；释放乙酰胆碱促进肠嗜铬样（ECL）分泌组胺，再通过组胺刺激壁细胞分泌盐酸。","","N"],["2014-N12",5,"第4节 小肠内消化","胆汁的作用",2014,12,"A","","胆汁在小肠内促进脂肪的消化与吸收的主要作用机制是",[["A","碳酸氢盐对胃酸的中和作用"],["B","所含脂肪酶的脂肪分解作用"],["C","直接刺激肠上皮细胞吸收作用"],["D","胆盐对脂肪的乳化作用"]],"D","胆汁中不含脂肪酶（B错），脂肪酶主要存在于胰液中，胰脂肪酶发挥作用的最适合pH为7.5～8.5（十版生理学P180），故胆汁中的碳酸氢盐对胃酸的中和作用能为胰脂肪酶发挥作用提供适合的pH环境，从而促进脂肪的消化，但由于胆汁中碳酸氢盐含量较少，只能中和一部分胃酸（大部分胃酸是由胰液中碳酸氢盐中和的），对胃酸的中和作用并不是胆汁促进脂肪的消化的主要作用机制（A错）。胆汁促进脂肪吸收的作用机制是：胆汁中胆盐（D对）与脂肪酸、一酰甘油等脂肪分解产物聚合形成水溶性的混合微胶粒，运载脂肪分解产物穿过小肠绒毛表面的静水层而到达肠黏膜表面，从而促进脂肪分解产物的吸收，胆汁并不具备直接刺激肠上皮细胞吸收脂肪的作用（C错）。","","N"],["2014-N13",5,"第7节 吸收","脂肪的吸收",2014,13,"A","","下列食物消化产物中，经小肠黏膜绒毛中毛细淋巴管吸收的是",[["A","各种氨基酸及寡肽"],["B","葡萄糖及其他单糖"],["C","长链脂肪酸和甘油一酯"],["D","短链脂肪酸和甘油一酯"]],"C","各种氨基酸、寡肽、葡萄糖及其他单糖均经过继发性的主动转运进入小肠黏膜上皮细胞内而后经载体易化扩散的方式进入组织间液，最终入血，不进入淋巴（AB错）。在脂肪的分解产物中，长链脂肪酸和甘油一酯是脂溶性的，通常在肠上皮细胞的内质网中重新合成脂肪，并与细胞中生成的载脂蛋白合成乳糜微粒，通过毛细淋巴管吸收（C对）；短链脂肪酸和甘油一酯是水溶性的，可直接进入血液被吸收（D错）。注意甘油一酯是脂溶性还是水溶性取决于其支链是长链脂肪酸还是短链脂肪酸。","","N"],["2014-N14",6,"第1节 能量代谢","间接测热法",2014,14,"A","","下列情况下，呼吸商测定值接近于0.7的是",[["A","糖尿病"],["B","酸中毒"],["C","长期饥饿而明显消瘦"],["D","多食而肥胖"]],"A","呼吸商是指一定时间内机体呼出的CO₂量和吸入的O₂量的比值，糖、脂肪、蛋白质的呼吸商分别为1.00、0.71和0.80。糖尿病患者因为机体内缺乏胰岛素或者是对胰岛素有抵抗，导致利用葡萄糖发生障碍，从而转向依靠脂肪代谢供能，因此呼吸商偏低，接近于0.71（A对）。酸中毒时，为了维持酸碱平衡，呼出的CO₂增加，使呼吸商变大，甚至可超过1.0（B错）。长期饥饿而明显消瘦时，人体的能量主要来自自身蛋白质的分解，故呼吸商接近于0.80（C错）。多食而肥胖者，体内的糖转化为脂肪，由于脂肪的分子组成中氧的含量较少，原来糖分子中的氧就有剩余，这些剩余的氧可参加机体代谢过程中的氧化反应，相应减少了从外界摄取的O₂量，从而使呼吸商变大，甚至可超过1.0（D错）。","","N"],["2014-N15",7,"第2节 肾小球的滤过功能","肾血浆流量",2014,15,"A","","下列情况下，可使肾小球滤过平衡点向出球小动脉端移动的是",[["A","发生中毒性休克"],["B","静脉注射肾上腺素"],["C","快速静脉注射大量生理盐水"],["D","发生肾盂或输尿管结石"]],"C","首先解释滤过平衡：当肾小球毛细血管内血液从入球小动脉端流向出球小动脉端时，由于不断生成超滤液，而蛋白质不能滤过，因而血浆中的蛋白质浓度逐渐升高，使血浆胶体渗透压逐渐升高，故滤过阻力逐渐增大，有效滤过压逐渐减小。当滤过阻力升高到等于滤过动力时，有效滤过压降低到0，滤过停止，此时称为滤过平衡。快速静脉注射大量生理盐水导致肾血浆流量增大，肾小球毛细血管中血浆胶体渗透压上升速度减缓，进而使得滤过平衡点向出球小动脉端移动（C对）。发生中毒性休克、静脉注射肾上腺素时，肾交感神经强烈兴奋，引起入球小动脉收缩，导致血流阻力增加，肾血浆流量减少，肾小球毛细血管中血浆胶体渗透压上升速度增快，滤过平衡点向入球小动脉端移动（AB错）。肾盂或输尿管结石引起尿路阻塞可致肾小球囊内压升高，使得有效滤过压降低，有效滤过压降低到0的时间提前，滤过平衡点向入球小动脉端移动（D错）。","","N"],["2014-N16",7,"第3节 肾小管和集合管的物质转运功能","近端小管",2014,16,"A","","下列关于肾近端小管重吸收HCO₃⁻的描述，正确的是",[["A","重吸收量约占超滤液总量的1/3"],["B","与管腔膜上Na⁺-H⁺交换密切相关"],["C","与小管上皮细胞分泌NH₃无关"],["D","通过Cl⁻-HCO₃⁻交换进入上皮细胞"]],"B","HCO₃⁻带负电荷不易通过细胞膜，重吸收时首先与通过Na⁺-H⁺交换分泌到小管腔中的H⁺结合生成H₂CO₃（B对），H₂CO₃在碳酸酐酶作用下分解为CO₂和水，CO₂具有高度脂溶性，以单纯扩散方式进入管腔上皮细胞内，在上皮细胞内，CO₂和水再在碳酸酐酶的催化下形成H₂CO₃，并解离为H⁺和HCO₃⁻，因此HCO₃⁻是以CO₂的形式（D错），通过单纯扩散的方式进入上皮细胞的。值得注意的是，近端小管后半段存在Cl⁻-HCO₃⁻交换机制，但是其转运结果是HCO₃⁻分泌入组织间隙（D错），Cl⁻重吸收进上皮细胞。NH₃的分泌与HCO₃⁻的重吸收密切相关：小管上皮细胞内的谷氨酰胺在谷氨酰胺酶、谷氨酸脱氢酶等酶的作用下生成NH₃和NH₄⁺，同时生成HCO₃⁻，NH₃和NH₄⁺分泌入小管腔，HCO₃⁻则进入血液循环（C错）。","","N"],["2014-N17",7,"第5节 尿生成的调节","血浆晶体渗透压",2014,17,"A","","大量出汗时尿量减少的主要原因是",[["A","血管升压素分泌增多"],["B","醛固酮分泌增多"],["C","肾交感神经兴奋"],["D","肾小管液溶质浓度下降"]],"A","大量出汗造成高渗性脱水，血浆晶体渗透压升高，刺激抗利尿激素（血管升压素）分泌增多，进而造成集合管对水的重吸收增加，尿量减少（A对）。","","N"],["2014-N18",8,"第3节 视觉","双眼视觉和立体视觉",2014,18,"A","","因眼外肌瘫痪或眼球内肿瘤压迫而产生复视的原因是",[["A","入眼光线分别聚焦于不同焦平面"],["B","眼球变形而导致眼内压过高"],["C","物像落在双眼视网膜的非对称点上"],["D","物像发生球面像差和色像差"]],"C","双眼视物时，两眼的视网膜上各形成一个完整物像，通过眼外肌的精细调节，可使来自物体同一部分的光线成像于两眼视网膜的对称点上，并在主观上产生单一物体的视觉，称为单视。而眼外肌瘫痪或眼球内肿瘤压迫等可使眼外肌的精细调节发生障碍，物像便不能落在视网膜的对称点上（C对），因而在主观产生有一定程度互相重叠的两个物体的感觉，称为复视。入眼光线分别聚焦于不同焦平面是散光（十版生理学P256）发生的原因（A错）。眼球变形而导致眼内压过高是青光眼（十版生理学P257）发生的原因（B错）。物像发生球面像差和色像差是瞳孔近反射障碍的结果（D错）。","","N"],["2014-N19",9,"第1节 神经系统功能活动的基本原理","突触后神经元动作电位的产生",2014,19,"A","","若干EPSP总和后足以达到阈电位水平，神经元上首先爆发动作电位的部位是",[["A","轴突末梢"],["B","轴突始段"],["C","胞体"],["D","树突"]],"B","由于一个突触后神经元常与多个突触前神经末梢构成突触，突触后膜上电位改变的总趋势决定于同时产生的EPSP和IPSP的代数和。当突触后膜去极化并达到阈电位水平时，即可爆发动作电位。动作电位首先发生在运动神经元和中间神经元的轴突始段（B对），或是感觉神经元的轴突始段或第一个郎飞结处，这是因为电压门控钠通道在轴突始段密度较大，而在胞体和树突膜中则很少分布。","","N"],["2014-N20",9,"第3节 神经系统对躯体运动的调控","帕金森病",2014,20,"A","","用左旋多巴治疗不能缓解的帕金森病临床表现是",[["A","动作缓慢"],["B","肌紧张增高"],["C","静止性震颤"],["D","面部表情呆板"]],"C","帕金森症是由于双侧黑质病变，多巴胺能神经元变性受损，使其对纹状体内胆碱能神经元的抑制作用减弱，导致乙酰胆碱能系统亢进而出现的症状，表现为全身肌张力增高，肌肉强直，随意运动减少，运动缓慢，面部表情呆板，常伴有静止性震颤。应用左旋多巴（进入脑组织后变为多巴胺）补充多巴胺增强其对胆碱能系统的抑制作用，或用M受体拮抗剂直接抑制胆碱能作用，可以缓解除静止性震颤之外的大部分症状，因为静止性震颤可能与丘脑外侧腹核等结构的结构异常有关，而与黑质-纹状体多巴胺能系统受损无关（C对）。","","N"],["2014-N21",10,"第2节 下丘脑-垂体及松果体内分泌","促进生长",2014,21,"A","","生长激素可通过靶细胞生成某种物质间接促进生长发育，这种物质是",[["A","转化生长因子"],["B","胰岛素样生长因子"],["C","成纤维细胞生长因子"],["D","表皮生长因子"]],"B","生长激素可通过直接激活靶细胞产生生理学效应，也可通过诱导靶细胞产生胰岛素样生长因子（IGF）（B对）间接激活靶细胞产生生理学效应。胰岛素样生长因子是具有促进生长作用的肽类物质，因其化学结构及作用与胰岛素相似而得名。成纤维生长因子、表皮生长因子和转化生长因子为细胞受到损伤因素刺激后释放的可以促进细胞增生和修复的生长因子（十版病理学P32）。","","N"],["2014-N22",10,"第5节 肾上腺内分泌","应激性调节",2014,22,"A","","机体在发生应激反应时，血中浓度明显升高并起关键作用的激素是",[["A","GHRH、GH"],["B","ACTH、GC"],["C","FSH、LH"],["D","TSH、T₃、T₄"]],"B","当机体发生应激反应时，下丘脑-腺垂体-肾上腺皮质系统被激活：下丘脑CRH（促肾上腺皮质激素释放激素）神经元分泌增强，刺激腺垂体ACTH（促肾上腺皮质激素）分泌，最后引起GC（糖皮质激素）的大量分泌（B对），以提高机体对伤害性刺激的耐受能力。应激反应机制十分复杂，除ACTH、GC分泌迅速增多外，儿茶酚胺、催乳素（PRL）、生长激素（GH）、血管升压素（VP）、β-内啡肽、胰高血糖素和醛固酮等激素的分泌也明显增加。","","N"],["2014-N23",10,"第6节 胰岛内分泌","胰高血糖素的生理作用",2014,23,"A","","胰高血糖素调节糖代谢的主要靶器官或靶组织是",[["A","肾脏"],["B","脑组织"],["C","骨骼肌"],["D","肝脏"]],"D","胰高血糖素的主要靶器官是肝（D对），胰高血糖素与肝细胞膜中的受体结合后，经Gs蛋白-cAMP-PKA或Gq蛋白-PLC-IP₃/DG-PKC通路激活肝细胞内的糖原磷酸化酶、脂肪酶和与糖异生有关的酶，引起后续系列反应：①促进肝糖原分解、减少肝糖原合成及增强糖异生作用，从而提高血糖水平；②减少肝内脂肪酸合成三酰甘油，促进脂肪酸分解，使酮体生成增加；③抑制肝内蛋白质合成，促进其分解，同时增加氨基酸进入肝细胞的量，加速氨基酸转化为葡萄糖，即促进糖异生。","","N"],["2014-N24",11,"第2节 女性生殖功能及其调节","月经周期各期的内分泌调控",2014,24,"A","","女性月经周期中出现两次分泌高峰的激素是",[["A","黄体生成素"],["B","雌激素"],["C","卵泡刺激素"],["D","孕激素"]],"B","正常月经周期中将出现两次雌激素高峰：在卵泡期，卵泡刺激素（FSH）和黄体生成素（LH）共同作用于卵泡，促使卵泡发育成熟，卵泡颗粒细胞分泌的雌激素水平在卵泡发育成熟过程中持续升高，在排卵前一天血中雌激素浓度到达最高值，形成月经周期中雌激素的第一次分泌高峰，在这一雌激素峰的作用下，下丘脑促性腺激素释放激素（GnRH）分泌增强，刺激LH与FSH分泌，形成黄体生成素（LH）峰和卵泡刺激素峰（FSH），其中LH峰是引发排卵的关键因素。排卵后，卵巢周期进入黄体期，卵泡颗粒细胞转换为黄体细胞，黄体细胞在LH的作用下分泌孕激素和雌激素，形成月经周期中孕激素的分泌高峰和雌激素的第二次分泌高峰。故女性月经周期中，黄体生成素、卵泡刺激素和孕激素各出现了一次分泌高峰（ACD错），雌激素则出现两次分泌高峰（B对）。","","N"],["2014-N121",1,"第4节 肌细胞的收缩","兴奋-收缩耦联的基本步骤",2014,121,"B","","心肌兴奋-收缩耦联中，由肌质网释放的Ca²⁺占胞质Ca²⁺增量的百分比是",[["A","30%～40%"],["B","50%～60%"],["C","80%～90%"],["D","100%"]],"C","在兴奋-收缩耦联过程中，骨骼肌胞质内增加的Ca²⁺几乎全部来自连接肌质网（JSR）的释放，而在心肌，连接肌质网释放的Ca²⁺仅占80%～90%（C对），另有10%～20%的Ca²⁺则由细胞外经L型钙通道内流而来。","","N"],["2014-N122",1,"第4节 肌细胞的收缩","兴奋-收缩耦联的基本步骤",2014,122,"B","","在骨骼肌兴奋-收缩耦联中，由肌质网释放的Ca²⁺占胞质Ca²⁺增量的百分比是",[["A","30%～40%"],["B","50%～60%"],["C","80%～90%"],["D","100%"]],"D","在兴奋-收缩耦联过程中，骨骼肌胞质内增加的Ca²⁺几乎全部来自连接肌质网（JSR）的释放（D对），而在心肌，连接肌质网释放的Ca²⁺仅占80%～90%，另有10%～20%的Ca²⁺则由细胞外经L型钙通道内流而来。","","N"],["2014-N123",3,"第4节 心血管活动的调节","颈动脉窦和主动脉弓压力感受性反射",2014,123,"B","","对快速波动的血压进行经常性调节的心血管反射是",[["A","容量感受器反射"],["B","压力感受性反射"],["C","化学感受性反射"],["D","轴突反射"]],"B","容量感受性反射（十版生理学P123）又称心肺感受性反射，指血容量增多时，心房壁内的心肺感受器受牵张刺激，不仅引起交感神经抑制和迷走神经兴奋，使心率减慢，心输出量减少，外周阻力降低和血压下降，还降低血浆血管升压素和醛固酮水平，减少肾远曲小管和集合管对钠和水的重吸收，降低循环血量和细胞外液量，因此容量感受性反射在循环血量和细胞外液量的调节中具有重要的生理意义。压力感受性（十版生理学P123）反射指动脉血压升高时，颈动脉窦和主动脉弓的压力感受器传入冲动增多，通过有关的心血管中枢整合作用，使心迷走紧张加强，心交感紧张和交感缩血管紧张降低，其效应为心率减慢，心输出量减少，外周血管阻力降低，动脉血压回降，压力感受性反射在心输出量、外周血管阻力、血量等发生突然改变的情况下，对动脉血压进行快速调节的过程中起重要的作用（B对）。化学感受性反射（十版生理学P123）指缺氧、窒息、失血、血压过低和酸中毒等情况下，颈动脉体和主动脉体化学感受性器接受刺激，反射性引起心率增快，心输出量增多，冠状动脉舒张，骨骼肌和内脏血管收缩等效应，由于心脏和脑的血管无明显收缩或发生轻微舒张，使循环血量得以重新分配，因此化学感受性反射在重新分配循环血量以保证心、脑等重要器官血液供应的调节中发挥重要的作用。轴突反射（十版生理学P121）是一种由躯体感受器引起的心血管反射，当皮肤受到伤害性刺激时，感觉冲动一方面沿传入纤维向中枢传导，另一方面可在末梢分支处沿其他分支到达受刺激部位邻近的微动脉，使微动脉舒张，局部皮肤出现红晕。这种仅通过轴突外周部位完成的反应，称为轴突反射。","","N"],["2014-N124",3,"第4节 心血管活动的调节","颈动脉体和主动脉体化学感受性反射",2014,124,"B","","在血压过低时，为保证心、脑供血而重新分配血量的心血管反射是",[["A","容量感受器反射"],["B","压力感受性反射"],["C","化学感受性反射"],["D","轴突反射"]],"C","容量感受性反射（十版生理学P123）又称心肺感受性反射，指血容量增多时，心房壁内的心肺感受器受牵张刺激，不仅引起交感神经抑制和迷走神经兴奋，使心率减慢，心输出量减少，外周阻力降低和血压下降，还降低血浆血管升压素和醛固酮水平，减少肾远曲小管和集合管对钠和水的重吸收，降低循环血量和细胞外液量，因此容量感受性反射在循环血量和细胞外液量的调节中具有重要的生理意义。压力感受性（十版生理学P123）反射指动脉血压升高时，颈动脉窦和主动脉弓的压力感受器传入冲动增多，通过有关的心血管中枢整合作用，使心迷走紧张加强，心交感紧张和交感缩血管紧张降低，其效应为心率减慢，心输出量减少，外周血管阻力降低，动脉血压回降，压力感受性反射在心输出量、外周血管阻力、血量等发生突然改变的情况下，对动脉血压进行快速调节的过程中起重要的作用。化学感受性反射（十版生理学P123）指缺氧、窒息、失血、血压过低和酸中毒等情况下，颈动脉体和主动脉体化学性感受器接受刺激，反射性引起心率加快，心输出量增加，冠状动脉舒张，骨骼肌和内脏血管收缩等效应，由于心脏和脑的血管无明显收缩或发生轻微舒张，使循环血量得以重新分配，因此化学感受性反射在重新分配循环血量以保证心、脑等重要器官血液供应的调节中发挥重要的作用（C对）。轴突反射（十版生理学P121）是一种由躯体感受器引起的心血管反射，当皮肤受到伤害性刺激时，感觉冲动一方面沿传入纤维向中枢传导，另一方面可在末梢分支处沿其他分支到达受刺激部位邻近的微动脉，使微动脉舒张，局部皮肤出现红晕。这种仅通过轴突外周部位完成的反应，称为轴突反射。","","N"],["2014-N125",9,"第5节 脑电活动及睡眠与觉醒","脑电图的波形",2014,125,"B","","正常成人深度睡眠时多见的脑电波是",[["A","α波"],["B","β波"],["C","θ波"],["D","δ波"]],"D","脑电波的基本波形有α、β、θ和δ波四种。在成人，α波在清醒、安静并闭眼时出现；β波在活动时出现；θ波在困倦时出现；δ波在入睡后（D对）、极度疲劳或麻醉时出现。","","N"],["2014-N126",9,"第5节 脑电活动及睡眠与觉醒","脑电图的波形",2014,126,"B","","正常人幼年期脑电波的主要成分是",[["A","α波"],["B","β波"],["C","θ波"],["D","δ波"]],"C","人在安静状态下，脑电图的主要波形可随年龄而发生改变。在婴儿期，可见到β波，在幼年期可见θ样波形（C对），到青春期开始时才出现成人型α波。九版生理学P342 表10-5显示婴幼儿正常时的波形为δ波（D），本题答案略有争议。","","N"],["2014-N151",1,"第2节 细胞的信号转导","离子通道型受体介导的信号转导",2014,151,"X","","既可作用于G蛋白耦联受体又可作用于通道型受体的配体有",[["A","乙酰胆碱"],["B","γ-氨基丁酸"],["C","心房钠尿肽"],["D","肾上腺素"]],"AB","乙酰胆碱及γ-氨基丁酸既可作用于G蛋白耦联受体，又可作用于通道型受体（AB对）。肾上腺素属于儿茶酚胺类递质，作用于G蛋白耦联受体（D错）；心房钠尿肽作用于鸟苷酸环化酶受体，鸟苷酸环化酶受体属于酶联型受体的一种（C错）。十版生物化学与分子生物学第二十章整章都在讲细胞信号转导，可以结合起来看。","","N"],["2014-N152",2,"第2节 血细胞生理","红细胞生成的调节",2014,152,"X","","下列生物活性物质中，能促进红细胞生成的有",[["A","雌激素"],["B","雄激素"],["C","甲状腺激素"],["D","促红细胞生成素"]],"BCD","促红细胞生成素（EPO）是促进红细胞生成最重要的调节物（D对），除EPO之外，雄激素（B对）可以通过提高血浆中EPO的浓度，间接促进红细胞的生成，而雌激素（A错）则可降低红系祖细胞对EPO的反应，抑制红细胞的生成，雄激素和雌激素对红细胞生成的不同效应，可能是成年男性红细胞数高于女性的原因之一。甲状腺激素（C对）可以提高组织对氧的需求，使血液和组织内的氧分压降低，刺激肾脏产生和释放EPO，促进红细胞的生成。","","N"],["2014-N153",3,"第3节 血管生理","影响组织液生成的因素",2014,153,"X","","下列情况下，能使全身或局部组织液生成增多的有",[["A","局部炎症"],["B","代谢性酸中毒"],["C","Ⅰ型过敏反应"],["D","右心衰竭"]],"ACD","组织液的生成量与有效滤过压有关，有效滤过压越大，组织液生成越多。有效滤过压=促进组织液生成的力量（毛细血管血压+组织液胶体渗透压）与阻碍组织液生成的力量（组织液静水压+血浆胶体渗透压）之差，右心衰竭时，静脉回流受阻，进而毛细血管流入静脉受阻，使毛细血管血压增大，有效滤过压增大，组织液生成增多（D对）。正常情况下，毛细血管对蛋白质几乎不通透，但在发生局部炎症（A对）、Ⅰ型过敏反应（C对）等情况下，多种炎性介质的释放使毛细血管通透性增加，血浆蛋白可由毛细血管渗入组织液，使血浆胶体渗透压下降，组织液胶体渗透压增高，有效滤过压增大，导致组织液生成增多。代谢性酸中毒是一种酸碱平衡紊乱，对组织液的生成无影响（B错）。","","N"],["2014-N154",6,"第1节 能量代谢","基础代谢",2014,154,"X","","下列疾病中，基础代谢率呈升高趋势的有",[["A","急性白血病"],["B","甲状腺功能亢进症"],["C","真性红细胞增多症"],["D","糖尿病"]],"ABCD","基础代谢率是指在基础状态下单位时间内的能量代谢。临床上很多疾病都伴有基础代谢率的改变，基础代谢率升高的疾病包括甲亢（B对）、糖尿病（D对）、红细胞增多症（C对）、白血病（A对）、肺心病等；基础代谢率降低的疾病包括甲减、肾上腺皮质功能减退、垂体性肥胖、肾病综合征、病理性饥饿等。","","N"],["2014-N155",8,"第4节 听觉","耳蜗的功能结构要点",2014,155,"X","","下列结构中，受损后可产生感音性耳聋的有",[["A","咽鼓管"],["B","螺旋器"],["C","血管纹"],["D","听骨链"]],"BC","耳聋可分为传音性耳聋和感音性耳聋两大类。传音性耳聋又称传导性耳聋，是由于外耳（外耳道）和中耳（鼓膜、听骨链、鼓室和咽鼓管）（AD错）受损后而导致外界声波传导入内耳受阻而造成的耳聋。感音性耳聋又称神经性耳聋，是由于内耳耳蜗、听神经和听觉中枢的病变，导致传入内耳的声波不能被感受而造成的耳聋。螺旋器和血管纹均位于内耳耳蜗（螺旋器是耳蜗基底膜上的听觉感受器；血管纹是耳蜗蜗管外侧壁的一种特殊的含血管而无基膜的复层上皮，可以产生内淋巴中正电位），与感音换能有关，受损后将产生感音性耳聋（BC对）。","","N"],["2014-N156",9,"第4节 神经系统对内脏活动、本能行为和情绪的调节","自主神经系统功能活动的基本特征",2014,156,"X","","交感神经系统活动的一般功能特点和意义有",[["A","其功能活动较为广泛"],["B","对消化系统活动具有增强作用"],["C","对骨骼肌舒血管活动有紧张性作用"],["D","动员机体潜力以应对环境急剧变化"]],"AD","交感神经的活动比较广泛（A对），它可以在环境急剧变化的条件下，动员机体许多器官的潜在力量，促使机体适应环境的变化（D对）。在安静状态下，自主神经持续发放一定频率的冲动，使所支配的器官处于一定程度的活动状态，称为自主神经的紧张性作用，骨骼肌舒血管活动没有紧张性作用，只有在情绪激动和发生防御反应时才会发生（C错）。交感神经兴奋时，作用于胃平滑肌β₂受体或小肠平滑肌的α₂、β₂受体使胃肠道平滑肌舒张，抑制胃肠运动，故交感神经系统活动对消化系统活动具有抑制作用（B错）。","","N"],["2015-N1",0,"第5节 机体生理功能的调节","体液调节",2015,1,"A","","下列生理功能活动中，主要通过体液途径完成的调节是",[["A","沙尘飞入眼球引起的闭眼动作"],["B","大量出汗引起尿量减少"],["C","食物入口引起唾液分泌"],["D","肢体发动随意运动"]],"B","机体生理功能的调节方式（十版生理学P8）主要包括神经调节、体液调节和自身调节。沙尘飞入眼球引起的闭眼动作属于非条件反射（角膜反射），为神经调节（A错）：刺激经角膜→三叉神经的眼神经→三叉神经脑桥核和脊束核→两侧的面神经核→面神经→两侧的眼轮匝肌引起闭眼动作。大量出汗引起尿量减少为体液调节（B对）：大量出汗时，由于汗液属于低渗溶液，导致机体失水多于溶质丧失，体液晶体渗透压升高，神经垂体释放抗利尿激素（血管升压素），使肾小管和集合管对水的通透性增加，水的重吸收增加，使尿量减少，尿液浓缩。食物入口引起唾液分泌属于非条件反射，为神经调节（C错）：食物入口，口腔内的机械、化学、温度感受器受到刺激，兴奋沿第Ⅴ、Ⅶ、Ⅸ、Ⅹ对脑神经中的传入纤维传至唾液分泌中枢（初级中枢在延髓，高级中枢在下丘脑和大脑皮层等处），然后兴奋沿传出神经到达各唾液腺，引起唾液分泌。肢体发出随意运动属于条件反射，是由大脑皮层直接控制的躯体运动，属于神经调节（D错）。","","N"],["2015-N2",1,"第1节 细胞膜的物质转运功能","经通道的易化扩散",2015,2,"A","","当细胞膜去极化和复极化时，相关离子的跨膜转运方式是",[["A","经通道易化扩散"],["B","原发性主动转运"],["C","继发性主动转运"],["D","经载体易化扩散"]],"A","经通道易化扩散（P17）是带电离子在通道蛋白的介导下，顺浓度梯度和（或）电位梯度进行的被动跨膜转运，细胞去极化时的Na⁺内流（钠通道介导）和细胞膜复极化时K⁺外流（钾通道介导）均属于经通道易化扩散（A对）。原发性主动转运（P20）是细胞直接利用代谢产生的能量将物质逆浓度梯度和（或）电位梯度转运的过程，例如钠钾泵、钙泵、质子泵等（B错）。根据九版生理学P101，钠钾泵活动贯穿动作电位全过程，在去极化和复极化时钠钾泵也在活动，但并不是主要的离子流，故不选B选项。继发性主动转运（P22）是利用原发性主动转运所形成的某些离子的浓度梯度，间接利用ATP能量的主动转运过程，例如葡萄糖在小肠黏膜上皮的吸收和在近端小管上皮的重吸收、Na⁺-Ca²⁺交换、Na⁺-H⁺交换等（C错）。经载体易化扩散（P19）是在载体蛋白的介导下，顺浓度梯度和（或）电位梯度的被动跨膜转运，如葡萄糖在一般细胞（除小肠黏膜上皮和肾近端小管上皮外）的跨膜转运（D错）。","","N"],["2015-N3",1,"第3节 细胞的电活动","动作电位期间膜离子通透性的变化",2015,3,"A","","下列情况下，明显延长神经细胞动作电位时程的是",[["A","部分阻断钾通道"],["B","升高细胞膜阈电位"],["C","减小刺激的强度"],["D","部分阻断钠通道"]],"A","从去极化开始到复极化完毕的这段时间，称为动作电位时程（APD）。在神经细胞动作电位过程中，复极化的时间长于去极化的时间，因此影响神经细胞动作电位时程的主要因素是复极化时间，而神经细胞复极化时K⁺外流是主要的离子流，故部分阻断K⁺通道，可明显延长神经细胞复极化时间，从而延长动作电位时程（A对）。神经细胞去极化主要由Na⁺内流引起，钠通道的主要作用是影响动作电位产生的幅度，部分阻断钠通道后，可明显使神经细胞动作电位的幅度减小，但是动作电位时程受到的影响不大（D错）。阈电位指刚好能触发膜去极化与Na⁺电导之间形成正反馈的膜电位水平，升高细胞膜阈电位与细胞的兴奋性下降有关，与细胞动作电位时程无关（B错）。细胞动作电位具有“全或无”的特点，减小刺激强度时，要么动作电位不发生（无），要么动作电位发生以后幅度和时程与减小刺激强度前保持一致（全）（C错）。","","N"],["2015-N4",2,"第2节 血细胞生理","红细胞的生理特征",2015,4,"A","","下列情况下，能使红细胞渗透脆性增高的是",[["A","血浆胶体渗透压降低"],["B","红细胞表面积/体积比降低"],["C","红细胞膜内磷脂/胆固醇比升高"],["D","血浆晶体渗透压升高"]],"B","红细胞的渗透脆性是指红细胞在低渗盐溶液中发生膨胀破裂的特性。正常的红细胞双凹圆碟形使红细胞具有较大的表面积/体积比，减小了红细胞的渗透脆性。遗传性红细胞增多症患者红细胞为球形，表面积/体积比减小（B对），红细胞渗透脆性增大，易发生溶血性贫血。红细胞在等渗盐溶液中可保持正常形态的大小，当血浆晶体渗透压降低时，血浆内的水分渗透入红细胞中，导致红细胞的正常双凹圆碟形逐渐胀大，成为球形，表面积/体积比减小，红细胞渗透脆性增高；而当血浆晶体渗透压升高时，红细胞内的水分渗透入血浆，导致红细胞逐渐缩小，表面积/体积比增大，红细胞渗透脆性降低（D错）。血浆胶体渗透压与血管内外水平衡有关，与红细胞渗透脆性无关（A错）。红细胞膜由双层磷脂与胆固醇排列组成，其中嵌入可移动蛋白质，此膜本身具有很大流动性和韧性，被称为液态膜，当膜内磷脂/胆固醇比升高时，其流动性和韧性增加，红细胞变形能力增强，渗透脆性降低（C错）。","","N"],["2015-N5",2,"第3节 生理性止血","凝血酶原的激活",2015,5,"A","","凝血酶原酶复合物的组成是",[["A","FⅢ-FⅦa-Ca²⁺-PL"],["B","FⅩa-FⅤa-Ca²⁺-PL"],["C","FⅡa-FⅩa-Ca²⁺-PL"],["D","FⅨa-FⅧa-Ca²⁺-PL"]],"B","根据启动方式和参与的凝血因子不同，可将凝血过程分为内源性凝血途径和外源性凝血途径两种：在内源性凝血途径中，当血液与带负电荷的异物表面接触时，首先是FⅫ结合到异物表面，并被激活为FⅫa，FⅫa再激活FⅪ成为FⅪa，FⅪa在Ca²⁺存在的情况下可激活FⅨ生成FⅨa，FⅨa在Ca²⁺的作用下与FⅧa在活化的血小板提供的磷脂（phospholipid，PL）表面结合成复合物（FⅨa-FⅧa-Ca²⁺-PL，因子Ⅹ酶复合物）（D错），可进一步激活FⅩ为FⅩa；在外源性凝血途径中，当血管损伤时，暴露出组织因子（FⅢ），后者与FⅦa和Ca²⁺相结合而形成FⅦa-组织因子复合物（FⅢ-FⅦa-Ca²⁺）（A错），进而激活FⅩ为FⅩa。可见两种凝血途径虽然启动方式和参与的凝血因子不同，但最终殊途同归，均可激活FⅩ生成FⅩa。FⅩa在Ca²⁺存在的情况下可与FⅤa在活化的血小板提供的磷脂（phospholipid，PL）表面形成FⅩa-FⅤa-Ca²⁺-PL（B对），即凝血酶原酶复合物，进而激活凝血酶原。","","N"],["2015-N6",3,"第1节 心脏的泵血功能","每搏输出量和射血分数",2015,6,"A","","心室功能减退病人代偿期射血分数下降的原因是",[["A","每分输出量减少"],["B","心室腔异常扩大"],["C","心肌细胞增生肥大"],["D","每搏输出量减少"]],"B","射血分数是搏出量占心室舒张末期容积的百分比。心室功能减退患者代偿期，心肌细胞代偿性肥大（心肌细胞是永久细胞，代偿期只出现细胞体积增大的肥大，而不出现细胞数量增多的增生），心肌收缩力增强，使每搏输出量（D错）和每分输出量（A错）与正常人无明显差异，因此心肌细胞代偿性肥大本身有利于提升心室功能减退患者的射血分数（C错）。由于心室功能减退的病人早期心室射血能力下降，收缩末期剩余血量增加，导致心室腔异常扩大（B对），而心室腔扩大将导致心室舒张末期容积增大，引起射血分数明显降低。","","N"],["2015-N7",3,"第3节 血管生理","血流阻力",2015,7,"A","","影响血流阻力最重要的因素是",[["A","血液黏度"],["B","血流形式"],["C","血流速度"],["D","血管口径"]],"D","血流阻力（R）指血液流经血管时所遇到的阻力，血流阻力一般不能直接测量，需要通过血流阻力公式计算：R=8ηL/πr⁴，其中η为血液黏度，L为血管长度，r为血管口径。由于在同一血管床内，血管长度L与血液黏度η（A错）在一段时间内变化不大，影响血流阻力的最主要因素为血管口径r（D对）。血流形式包括层流和湍流两种方式，血流阻力公式根据泊肃叶定律推算而来，只适用于血液为层流的情况，在湍流的情况下，血液中各个质点不断变换流动的方向，故消耗的能量较层流时更多，血流阻力较根据血流阻力公式计算出来的数值更大一些，即血流形式可以影响血流阻力，但在同一血管床内血流形式相对是固定的（在生理情况下，心室腔和主动脉内的血流方式是湍流，其余血管系统中的血流方式为层流），对血流阻力影响不大（B错）。血流阻力可消耗血液流动时的能量而影响血流速度（使降低），而不是血流速度影响血流阻力（C错）。","","N"],["2015-N8",4,"第1节 肺通气","肺容量",2015,8,"A","","肺纤维化病人，1秒用力呼气量（FEV₁）/用力肺活量（FVC）的检查结果是",[["A","FEV₁减少，FVC基本不变，FEV₁/FVC减小"],["B","FEV₁基本不变，FVC减小，FEV₁/FVC增大"],["C","FEV₁和FVC均减小，FEV₁/FVC基本不变"],["D","FEV₁和FVC均增大，FEV₁/FVC基本不变"]],"C","1秒用力呼气量（FEV₁）指一次最大吸气后，尽力尽快呼气，在第1秒末所能呼出的气体量；用力肺活量（FVC）指一次最大吸气后，尽力尽快呼气所能呼出的最大气体量。FEV₁/FVC在临床上鉴别阻塞性肺疾病和限制性肺疾病中有重要意义：在哮喘等阻塞性肺疾病患者，呼气阻力增加，FEV₁降低明显，当FVC降低相对不明显或正常（可用时间弥补），因此FEV₁/FVC变小（A错）；在肺纤维化等限制性肺疾病患者，肺弹性回缩力增大，顺应性下降，吸气阻力增加，肺总量下降，使FEV₁和FVC均下降，但是FEV₁/FVC仍可基本正常（C对）。","","N"],["2015-N9",4,"第3节 气体在血液中的运输","氧解离曲线",2015,9,"A","","在高原地区，当吸入气的氧分压大于60mmHg时，血红蛋白氧饱和度为",[["A","60%～69%"],["B","70%～79%"],["C","80%～89%"],["D","90%～99%"]],"D","血红蛋白（Hb）氧饱和度（P163）指Hb氧含量与Hb氧容量的百分比。血红蛋白氧饱和度随氧分压的变化而变化，二者之间的变化关系呈S形曲线，称氧解离曲线。通过氧解离曲线可知，氧分压在60～100mmHg（氧解离曲线的上段）时的血红蛋白氧饱和度变化不大，维持在90%以上（D对）。","","N"],["2015-N10",4,"第4节 呼吸运动的调节","肺牵张反射",2015,10,"A","","实验切断家兔双侧颈迷走神经后，呼吸运动的改变是",[["A","呼吸幅度减小，频率减慢"],["B","呼吸幅度增大，频率加快"],["C","呼吸幅度减小，频率加快"],["D","呼吸幅度增大，频率减慢"]],"D","肺牵张反射包括肺扩张反射和肺萎陷反射两个部分。肺扩张反射是肺扩张时抑制吸气活动的反射，可以使呼吸变浅变快；肺萎陷反射是肺萎陷时增强吸气活动的反射，可以使呼吸变深变慢。肺扩张反射和肺萎陷反射的传入神经均为迷走神经，切断迷走神经后，肺扩张反射被抑制的效应是呼吸变深变慢，肺萎陷反射被抑制的效应是呼吸变浅变快，动物实验表明，切断迷走神经的综合效应是呼吸变深变慢，即呼吸频率减慢，幅度增大（D对）。","","N"],["2015-N11",5,"第3节 胃内消化","胃的运动形式",2015,11,"A","","进食引起胃容受性舒张的支配神经是",[["A","交感神经肾上腺素能纤维"],["B","迷走神经胆碱能纤维"],["C","迷走神经肽能纤维"],["D","交感神经胆碱能纤维"]],"C","进食时食物刺激口腔、咽、食管等处的感受器，可反射性引起胃底和胃体舒张，称为容受性舒张。容受性舒张与食管下括约肌舒张（十版生理学P171、P177）都是通过迷走神经肽能纤维释放某种肽类物质（VIP和NO等）实现的（C对）。","","N"],["2015-N12",5,"第4节 小肠内消化","胰液的性质、成分和作用",2015,12,"A","","在胰脂肪酶消化脂肪的过程中，辅脂酶起的作用是",[["A","提高胰脂肪酶对脂肪的酶解速度"],["B","防止胰脂肪酶从脂滴表面被清除"],["C","促进胰腺细胞分泌大量胰脂肪酶"],["D","将胰脂肪酶原转变为胰脂肪酶"]],"B","由于胆盐具有去垢剂的特性，可将附着于胆盐微胶粒（即乳化的脂滴）表面的蛋白质（胰脂肪酶）从脂滴表面清除下去。辅脂酶对胆盐微胶粒有较高亲和力，当它与胰脂肪酶和胆盐形成三元络合物时，可防止胰脂肪酶从脂滴表面被清除（B对），有助于胰脂肪酶发挥其分解脂肪的作用。辅脂酶不影响胰脂肪酶本身的活性，因此不能提高胰脂肪酶对脂肪的酶解速率（A错）。促进胰腺细胞分泌大量胰脂肪酶的是缩胆囊素（又称促胰酶素）（十版生理学P181），而不是辅脂酶（C错）。胰液中胰脂肪酶不存在酶原的形式，D选项的说法本身就是错误的（D错）。","","N"],["2015-N13",5,"第7节 吸收","维生素的吸收",2015,13,"A","","下列物质中，主要在回肠被吸收的是",[["A","Ca²⁺"],["B","胆固醇"],["C","维生素B₁₂"],["D","Fe²⁺"]],"C","维生素B₁₂在胃内与内因子结合，形成内因子-维生素B₁₂复合物，可保护维生素B₁₂免遭肠内水解酶的破坏。当内因子-维生素B₁₂复合物运行至远端回肠（C对）后，维生素B₁₂被吸收。小肠各段均可吸收Ca²⁺（A错），小肠黏膜对Ca²⁺的吸收通过跨上皮细胞和细胞旁途径两种形式进行。十二指肠是跨上皮细胞主动吸收Ca²⁺的主要部位，空肠和回肠则是细胞旁途径被动吸收Ca²⁺的主要部位。胆固醇和Fe²⁺主要在小肠上部（十二指肠和空肠上段）被吸收（BD错）。","","N"],["2015-N14",6,"第2节 体温及其调节","体温的生理性波动",2015,14,"A","","下列关于体温正常变动的叙述，正确的是",[["A","通常成年人体温高于儿童"],["B","成年女性的体温平均高于男性0.3℃"],["C","育龄期女性基础体温以排卵日为最高"],["D","体温的昼夜变化可超过1℃"]],"B","儿童因为代谢旺盛，所以体温较成年人偏高（A错）。成年女性的体温平均高于男性0.3℃（B对），一方面因为孕激素有升高女性基础体温的功能（十版生理学P389），另一方面因为女性体脂含量高于男性而不利于体热的散失。育龄期女性基础体温以排卵日为最低（C错），排卵后卵巢所分泌的孕激素可刺激体温中枢使体温升高。正常情况下，人体体温在一日之内也会发生波动，表现为体温在清晨2～6时最低，午后1～6时最高，但波动幅度一般不会超过1℃（D错）。","","N"],["2015-N15",7,"第1节 肾的功能解剖和肾血流量","滤过膜的构成",2015,15,"A","","在肾小球滤过膜中起机械屏障作用的主要结构是",[["A","毛细血管内皮下基膜"],["B","肾小囊脏层上皮细胞"],["C","肾小囊脏层足细胞足突裂隙膜"],["D","毛细血管内皮细胞"]],"A","肾小球滤过膜由毛细血管内皮细胞、毛细血管下基膜和肾小囊脏层足细胞的足突构成，三层结构的孔径分别为70～90nm、2～8nm和4～11nm，蛋白质分子的直径一般较大，因此不能自由滤过，此为滤过膜的机械屏障。由于毛细血管内皮下基膜（A对）的滤过孔径最小，因此是肾小球滤过膜中起机械屏障作用的主要结构。","","N"],["2015-N16",7,"第3节 肾小管和集合管的物质转运功能","HCO₃⁻的重吸收与H⁺的分泌",2015,16,"A","","下列关于肾近端小管分泌H⁺的描述，正确的是",[["A","与上皮细胞分泌NH₃相互抑制"],["B","与上皮细胞重吸收Na⁺无关"],["C","碳酸酐酶在泌H⁺中起重要作用"],["D","主要依靠管腔膜上的质子泵转运"]],"C","H⁺与NH₄⁺均通过肾小管上皮细胞顶端膜的Na⁺-H⁺交换体进入小管液，肾近端小管分泌H⁺，与上皮细胞分泌NH₄⁺（而不是NH₃）相互抑制（A错）。肾近端小管分泌H⁺由上皮细胞顶端膜Na⁺-H⁺交换体介导（BD错），小管液中的Na⁺顺浓度梯度被重吸收进上皮细胞的同时，上皮细胞的H⁺被分泌到小管液中。在肾近端小管，碳酸酐酶（C对）可以催化CO₂和水形成H₂CO₃，后者又很快解离成H⁺和HCO₃⁻，H⁺通过顶端膜中的Na⁺-H⁺交换体分泌入小管液。","","N"],["2015-N17",7,"第3节 肾小管和集合管的物质转运功能","小管液中溶质的浓度",2015,17,"A","","静脉推注少量高浓度葡萄糖时出现尿量增多的原因是",[["A","肾小管液溶质浓度升高"],["B","血浆胶体渗透压下降"],["C","肾血流量增多"],["D","肾小球滤过率升高"]],"A","静脉推注少量高浓度葡萄糖时出现尿量增多的原因是渗透性利尿，即由于血糖浓度升高而使超滤液中的葡萄糖超过近端小管对糖的最大转运率，造成小管液葡萄糖浓度升高（A对），渗透压升高，使小管内外渗透压梯度减小，从而使水和NaCl的重吸收减少，尿量增加。由于只推注少量高浓度葡萄糖，故血容量增加有限，血浆胶体渗透压下降（B错），肾血流量增多（C错）和肾小球滤过率升高（D错）对尿量增多的影响几乎可以忽略不计。","","N"],["2015-N18",8,"第3节 视觉","眼的折光系统",2015,18,"A","","在设计视力表时，考虑判断人眼视力高低的标准是",[["A","人眼所能看清楚的物体大小"],["B","视网膜中央凹处最小的清晰像大小"],["C","视网膜中央凹以外最小的清晰像大小"],["D","人眼所能看清楚物体的距离"]],"B","视力又称为视敏度，是指人眼对物体细小结构的分辨能力。正常人眼的视力是有限度的，这个限度是视网膜像不小于中央凹处一个视锥细胞的平均直径（4.5μm），如果物体在视网膜上的成像小于4.5μm，一般不能产生清晰的视觉。在设计视力表时，就是根据视网膜中央凹处最小清晰像的大小（B对）来判断人眼视力高低的。","","N"],["2015-N19",9,"第1节 神经系统功能活动的基本原理","电突触传递",2015,19,"A","","电突触传递的一般特点是",[["A","双向，高电阻，慢速"],["B","单向，高电阻，慢速"],["C","双向，低电阻，快速"],["D","单向，低电阻，快速"]],"C","根据信息传媒的不同，可将突触传递分为电突触传递和化学性突触传递两大类。电突触通过缝隙连接（十版生理学P38），以离子流（局部电流）为媒介直接传递电信号，电突触缝隙连接处的细胞膜薄，突触间隙仅为2～3nm，具有电阻低，传递速度快的特点，同时电突触传递的是离子流，具有双向传递的特点（C对）。化学性突触传递是神经系统信息传递的主要形式，一般由突触前膜、突触间隙和突触后膜三部分组成，化学性突触只能由突触前膜经突触间隙传导至突触后膜，传递速度较慢，并且是单向传递的。","","N"],["2015-N20",9,"第3节 神经系统对躯体运动的调控","运动传出通路",2015,20,"A","","查体巴宾斯基征阳性提示皮层脊髓侧束损伤的条件是",[["A","成人在清醒状态下"],["B","成人在熟睡状态下"],["C","成人在麻醉状态下"],["D","婴儿在清醒状态下"]],"A","巴宾斯基征是神经科常用检查之一，因最早由法国神经学家巴宾斯基发现而得名。用一钝物划足跖外侧，出现𧿹趾背屈和其他四趾外展呈扇形散开的体征称为巴宾斯基征阳性，是一种异常的跖伸肌反射，常提示皮层脊髓束受损。婴儿（D错）因皮层脊髓束发育尚不完全，成年人在深睡（B错）或麻醉（C错）状态下，均可出现巴宾斯基阳性体征，但不表明皮层脊髓束受损，只有成人在清醒状态下（A对）查体巴宾斯基征阳性方可提示皮层脊髓侧束受损。","","N"],["2015-N21",10,"第3节 甲状腺内分泌","甲状腺激素的合成与分泌",2015,21,"A","","在甲状腺激素合成中，不需要甲状腺过氧化物酶催化的过程是",[["A","滤泡聚碘"],["B","碘的活化"],["C","酪氨酸碘化"],["D","碘化酪氨酸缩合"]],"A","甲状腺激素的合成过程包括：①聚碘：碘经钠-碘同向转运体，以继发性主动转运的形式进入滤泡上皮细胞，然后经细胞顶端膜转入滤泡腔中，从而完成聚碘过程，此过程不需要甲状腺过氧化物酶（TPO）的催化（A对）。②碘的活化：在H₂O₂的存在的条件下，甲状腺过氧化物酶（B错）催化I⁻迅速被氧化为“活化碘”。③碘化：碘化是活化碘取代甲状腺球蛋白中酪氨酸残基苯环上氢的过程。在甲状腺过氧化物酶（C错）的催化下，活化碘瞬间即取代酪氨酸残基苯环3位或3和5位上的氢，生成一碘酪氨酸残基和二碘酪氨酸残基，从而完成碘化过程。④缩合：在甲状腺过氧化物酶（D错）的催化下，同一甲状腺球蛋白分子内的一碘酪氨酸（MIT）和二碘酪氨酸（DIT）分别双双耦联成四碘酪氨酸（T₄）和三碘酪氨酸（T₃），完成甲状腺激素的合成过程。","","N"],["2015-N22",10,"","",2015,22,"A","","机体在遇到环境因素紧急变化时，即刻被调动的系统是",[["A","迷走-胰岛系统"],["B","交感-肾上腺髓质系统"],["C","下丘脑-神经垂体系统"],["D","肾素-血管紧张素-醛固酮系统"]],"B","机体在遇到环境因素紧急变化时，有关信息被传入延髓、下丘脑及大脑皮层，进而使支配肾上腺髓质嗜铬细胞的交感神经兴奋，肾上腺髓质激素分泌水平急剧升高，引起中枢神经系统兴奋性增强，此时机体反应极为机敏，处于警觉状态；心率加快，心输出量增加，血压升高，全身血量重新分布，以确保心、脑与肌肉等器官的血流量增加；呼吸加深加快；血糖升高，脂肪分解，葡萄糖、脂肪氧化增强，以满足机体在紧急情况下急增的能量需求。总之，尽最大可能动员机体许多器官的潜能，提高应对能力。这种在紧急情况下发生的交感-肾上腺髓质（B对）系统活动增强的适应性反应，称为应急反应（十版生理学P372）（应急反应非应激反应，应激反应（十版生理学P371）时被调动的系统是下丘脑-腺垂体-肾上腺皮质系统）。由于迷走神经活动加强时常伴有胰岛素分泌增多，故迷走神经又称迷走-胰岛系统，迷走-胰岛系统与应急反应时被调动的交感-肾上腺髓质系统的调节作用正好相反（A错）。下丘脑-神经垂体系统（十版生理学P353）（C错）可分泌血管升压素和缩宫素，前者可升高血压和促进肾重吸收水，后者可刺激子宫收缩和在哺乳期促进乳汁排出，均与应急反应无关。肾素-血管紧张素-醛固酮系统（D错）对电解质和体液平衡的维持（十版生理学P232），以及血压的调节（十版生理学P124）均有重要作用，但与应急反应无关。","","N"],["2015-N23",10,"第6节 胰岛内分泌","激素的调节作用",2015,23,"A","","通过旁分泌的方式抑制胰岛素分泌的激素是",[["A","抑胃肽"],["B","肾上腺素"],["C","生长抑素"],["D","胰高血糖素"]],"C","抑胃肽和胰高血糖素均可促进胰岛素分泌，故首先排除答案A和D（AD错）。生长抑素可通过旁分泌的方式抑制β细胞分泌胰岛素（C对）。肾上腺素由肾上腺髓质分泌入血，经血流运输至胰岛，作用于胰岛β细胞的α₂受体抑制胰岛素分泌，其作用方式为典型的远距分泌（血分泌）（B错）。","","N"],["2015-N24",11,"第2节 女性生殖功能及其调节","雌激素、孕激素的作用",2015,24,"A","","孕激素对子宫的生理作用是",[["A","促进子宫内膜增厚和分泌"],["B","提高子宫平滑肌的兴奋性"],["C","提高子宫肌对缩宫素的敏感性"],["D","促进子宫颈分泌黏液"]],"A","孕激素主要作用于子宫内膜和子宫平滑肌，为受精卵着床作好准备，并维持妊娠：孕激素能降低子宫肌细胞膜的兴奋性（B错），降低妊娠子宫肌对缩宫素的敏感性（C错），也能抑制母体对胎儿的免疫排斥反应，因而有利于胚胎在子宫腔内的生长发育。此外，孕激素还能抑制输卵管的节律性收缩，减少宫颈黏液分泌（D错），增大其稠度，使精子难以通过。孕激素虽然会抑制子宫内膜细胞增殖，促进子宫内膜由增生期转为分泌期，但子宫内膜中的腺体和血管在分泌期增多，整体上而言，孕激素促进子宫内膜增厚和分泌（A对）。","","N"],["2015-N121",1,"第4节 肌细胞的收缩","肌丝的分子结构",2015,121,"B","","具有ATP酶活性，属于分子马达的肌丝成分是",[["A","肌球蛋白"],["B","肌动蛋白"],["C","肌钙蛋白"],["D","原肌球蛋白"]],"A","横纹肌的收缩机制一般用肌丝滑行理论来解释，即肌肉的缩短和伸长系粗肌丝与细肌丝在肌节内相互滑行所致，而粗细肌丝本身长度不改变。粗肌丝主要由肌球蛋白（肌凝蛋白）组成，肌球蛋白头部向外伸出的部位称为横桥，横桥具有ATP酶活性，并能与肌动蛋白结合。横桥分解ATP时产生能量，能拉动肌动蛋白运动，因此粗肌丝的肌球蛋白为分子马达（分子马达是指细胞内利用ATP供能，产生推动力，进行细胞物质运输或细胞运动的蛋白质分子）（A对）。","","N"],["2015-N122",1,"第4节 肌细胞的收缩","肌丝的分子结构",2015,122,"B","","具有结合位点，能与横桥结合而引发肌丝滑行的肌丝成分是",[["A","肌球蛋白"],["B","肌动蛋白"],["C","肌钙蛋白"],["D","原肌球蛋白"]],"B","细肌丝由肌动蛋白（肌纤蛋白）、原肌球蛋白（原肌凝蛋白）和肌钙蛋白三种蛋白质组成。肌动蛋白分子上有能与粗肌丝横桥结合的位点（B对），但是在肌肉舒张状态时，肌动蛋白上的横桥结合位点被原肌球蛋白所掩盖，当胞质中Ca²⁺浓度升高时，Ca²⁺与肌钙蛋白结合，使肌钙蛋白构象改变，促使与肌钙蛋白结合的原肌球蛋白发生移动，暴露肌动蛋白上的横桥结合位点，引发横桥与肌动蛋白结合，导致肌肉收缩。","","N"],["2015-N123",9,"第1节 神经系统功能活动的基本原理","NE和肾上腺素及其受体",2015,123,"B","","可作为交感神经递质或内分泌激素，可以强烈提升动脉血压作用的活性物质是",[["A","血管紧张素"],["B","血管升压素"],["C","内皮素"],["D","去甲肾上腺素"]],"D","去甲肾上腺素既作为交感神经兴奋时释放的神经递质存在，也作为肾上腺髓质分泌的内分泌激素存在，能够与血管平滑肌的α受体结合，引起血管平滑肌收缩，强烈提升动脉血压（D对）。血管紧张素（十版生理学P125）、血管升压素（十版生理学P126）和内皮素（十版生理学P126）均为可以引起血管收缩、提升动脉血压的内分泌激素，但三者均不属于交感神经递质（ABC错）。此题题干不严谨，将或改为和更佳。","","N"],["2015-N124",10,"第2节 下丘脑-垂体及松果体内分泌","血管升压素",2015,124,"B","","一般不经常调节血压，仅在细胞外液明显减少时释放增多，起升压作用的体液因子是",[["A","血管紧张素"],["B","血管升压素"],["C","内皮素"],["D","去甲肾上腺素"]],"B","血管升压素又称抗利尿激素，主要由下丘脑视上核和室旁核的大细胞神经元合成（十版生理学P353），合成之后被运输至神经垂体储存。血管升压素的作用主要包括两个方面：抗利尿和升血压：血管升压素生理水平的升高主要促进肾重吸收水，发挥抗利尿作用；在机体脱水和失血等情况下，细胞外液明显减少时，血管升压素的释放量明显增多，可使血管广泛收缩，发挥升血压作用（B对）。","","N"],["2015-N125",9,"第5节 脑电活动及睡眠与觉醒","睡眠的两种状态及生理意义",2015,125,"B","","慢波睡眠的生理意义",[["A","促进生长和精力恢复"],["B","促进生长和体力恢复"],["C","促进学习记忆和精力恢复"],["D","促进学习与体力"]],"B","人在睡眠时会出现周期性的快速眼球运动，根据睡眠过程中眼电图、肌电图和脑电图的变化观察，可将睡眠分为非快动眼睡眠（NREM睡眠）和快眼动睡眠（REM睡眠）。非快动眼睡眠的脑电图呈现高幅慢波，因而也称慢波睡眠，而快速眼球运动期间的脑电波和觉醒期的脑电波类似，表现为低幅快波，故又称快波睡眠或异相睡眠。在非快动眼睡眠（慢波睡眠）阶段，视、听、嗅和触等感觉以及骨骼肌反射、循环、呼吸和交感神经活动等均随睡眠的加深而降低，且相当稳定；但此期腺垂体分泌生长激素则明显增多，因而非快动眼睡眠（慢波睡眠）有利于促进生长和体力恢复（B对）。","","N"],["2015-N126",9,"第5节 脑电活动及睡眠与觉醒","睡眠的两种状态及生理意义",2015,126,"B","","异相睡眠的生理意义",[["A","促进生长和精力恢复"],["B","促进生长和体力恢复"],["C","促进学习记忆和精力恢复"],["D","促进学习与体力"]],"C","人在睡眠时会出现周期性的快速眼球运动，根据睡眠过程中眼电图、肌电图和脑电图的变化观察，可将睡眠分为非快动眼睡眠（NREM睡眠）和快眼动睡眠（REM睡眠）。非快动眼睡眠的脑电图呈现高幅慢波，因而也称慢波睡眠，而快速眼球运动期间的脑电波和觉醒期的脑电波类似，表现为低幅快波，故又称快波睡眠或异相睡眠。在快动眼睡眠（异相睡眠）阶段，脑内蛋白质合成加快，脑的耗氧量和血流量增多，而生长激素分泌则减少，快动眼睡眠（异相睡眠）与幼儿神经系统的成熟和建立新的突触联系密切有关，因而能促进学习记忆和精力恢复（C对）。","","N"],["2015-N151",1,"第2节 细胞的信号转导","酶联型受体介导的信号转导",2015,151,"X","","下列物质中，可作用于酶联型受体而实现信号转导的配体有",[["A","胰岛素"],["B","心房钠尿肽"],["C","甲状腺激素"],["D","肾上腺素"]],"AB","细胞的信号转导是指生物学信息（兴奋或抑制）在细胞间或细胞内转换和传递，并产生生物效应的过程：①离子通道型受体介导的信号转导：离子通道型受体是一类兼有通道和受体功能的膜蛋白，以离子通道型受体而实现信号转导的配体包括乙酰胆碱、甘氨酸、γ-氨基丁酸等；②G蛋白耦联受体介导的信号转导：G蛋白耦联受体是指激活后作用于与之耦联的G蛋白，然后引发一系列以信号蛋白为主的级联反应而完成跨膜信号转导的一类受体。激活这类受体的配体包括儿茶酚胺（去甲肾上腺素、肾上腺素和多巴胺）（D错）、5-羟色胺、乙酰胆碱、氨基酸类递质以及几乎所有的多肽和蛋白质类递质和（或）激素（钠尿肽家族除外），还有光子、嗅质和味质等；③酶联型受体介导的信号转导：酶联型受体是指其自身就具有酶的活性或能与酶结合的膜受体，这类受体的主要类型有酪氨酸激酶受体、酪氨酸激酶结合型受体、鸟苷酸环化酶受体和丝氨酸/苏氨酸激酶受体。激活酪氨酸激酶受体的配体主要包括各种生长因子，包括表皮生长因子、血小板源性生长因子、成纤维细胞生长因子、肝细胞生长因子和胰岛素（A对）等。激活鸟苷酸环化酶受体的主要是心房钠尿肽（B对）、脑钠尿肽和一氧化氮；④招募型受体介导的信号转导：招募型受体分子的胞内域没有任何酶的活性，故不能进行生物信号的放大，但招募型受体的胞外域一旦与配体结合，其胞内域即可在胞质侧招募激酶或转接蛋白，激活下游不涉及经典第二信使的信号转导通路。招募型受体的主要配体是细胞因子等，受体涉及细胞因子受体、整联蛋白受体、Toll及Toll-like受体、肿瘤坏死因子受体、T细胞受体等众多种类；⑤核受体介导的信号转导：核受体为胞内受体（包括核受体本身和胞质受体两种类型），其实质上是激素调控特定蛋白质转录的一大类转录调节因子。核受体的主要配体包括类固醇激素（糖皮质激素、盐皮质激素、性激素）、维生素D₃、甲状腺激素（C错）和维甲酸等。","","N"],["2015-N152",2,"第2节 血细胞生理","红细胞生成所需物质",2015,152,"X","","下列物质中，若缺乏可导致巨幼红细胞贫血的有",[["A","泛酸"],["B","叶酸"],["C","维生素B₁₂"],["D","生物素"]],"BC","叶酸以四氢叶酸的形式起作用，四氢叶酸作为一碳单位的载体，在体内参与嘌呤核苷酸和胸腺嘧啶核苷酸的合成，叶酸缺乏时，嘌呤核苷酸和胸腺嘧啶核苷酸合成减少，红细胞中DNA合成受阻，细胞分裂增殖速度下降，细胞体积增大，核内染色质疏松，影响红细胞成熟，导致巨幼细胞性贫血（B对）。体内叶酸多以N⁵-甲基四氢叶酸形式存在，发挥作用时，N⁵-甲基四氢叶酸与同型半胱氨酸反应生成四氢叶酸与甲硫氨酸（十版生物化学与分子生物学P189），此反应需N⁵-甲基四氢叶酸转甲基酶催化，而维生素B₁₂是该酶的辅酶成分，故当维生素B₁₂缺乏时，转甲基反应受阻，影响四氢叶酸的周转利用，间接影响胸腺嘧啶脱氧核苷酸的生成，同样影响红细胞成熟，导致巨幼细胞性贫血（C对）。泛酸（十版生物化学与分子生物学P99）又称遍多酸、维生素B₅，其活性形式为辅酶A（CoA）和酰基载体蛋白（ACP），CoA和ACP构成酰基转移酶的辅酶，广泛参与糖、脂类、蛋白质代谢及肝的生物转化作用。泛酸缺乏症很少见，泛酸缺乏的早期易疲劳，引发胃肠功能障碍等疾病，如食欲不振、恶心、腹痛、溃疡、便秘等症状。严重时最显著特征是出现肢神经痛综合征，主要表现为脚趾麻木，步行时摇晃，周身酸痛等。若病情继续恶化，则会产生易怒、脾气暴躁、失眠等症状。总之，泛酸缺乏时不会导致巨幼细胞性贫血（A错）。生物素（十版生物化学与分子生物学P99）又称维生素H、维生素B₇，为体内丙酮酸羧化酶、乙酰CoA羧化酶等多种羧化酶的辅基，参与CO₂固定过程，为脂肪与碳水化合物代谢所必需。生物素的来源极为广泛，人体肠道细胞也能合成，很少出现缺乏症。长期使用抗生素可抑制肠道细菌生长，也可能造成生物素的缺乏，可导致疲乏、恶心、呕吐、食欲不振、皮炎及脱屑性红皮病等，但是不会导致巨幼细胞性贫血（D错）。","","N"],["2015-N153",3,"第3节 血管生理","微循环的血流动力学",2015,153,"X","","下列微循环结构中，主要受局部代谢产物调节的有",[["A","后微动脉"],["B","微动脉"],["C","毛细血管前括约肌"],["D","微静脉"]],"AC","微循环由微动脉、后微动脉、毛细血管前括约肌、真毛细血管、通血毛细血管（或称直捷通路）、微静脉和动-静脉吻合支等部分组成。其中后微动脉（A对）和毛细血管前括约肌（C对）主要受局部代谢产物（如CO₂、H⁺、腺苷、ATP、K⁺等）的调节（代谢性自身调节）而发生交替性血管舒缩活动。微动脉也接受局部代谢产物的调节，但微动脉主要受神经调节（微动脉是交感缩血管神经纤维分布密度最高的血管类型）和体液调节（B错）。较小的微静脉无血管平滑肌分布，不参与微循环血流量的调节（D错）；较大的微静脉有血管平滑肌，主要受神经调节和体液调节（D错）。","","N"],["2015-N154",6,"第2节 体温及其调节","产热活动的调节",2015,154,"X","","能促使机体产热活动明显增强的体液因子有",[["A","肾上腺素"],["B","生长激素"],["C","糖皮质激素"],["D","甲状腺激素"]],"ABD","甲状腺激素和肾上腺素可提高机体代谢率（AD对），使机体产热活动明显增强（称非战栗产热或代谢产热）：当受到甲状腺激素、肾上腺素作用时，人体褐色脂肪组织细胞线粒体内的解耦联蛋白（UCP）成为易化质子通道，H⁺顺浓度梯度沿UCP返回到线粒体基质中，使经线粒体呼吸链电子传递建立的质子跨膜电-化学势能以热能的形式释放出来，而不能用于合成ATP。糖皮质激素（十版生理学P369）的作用广泛而复杂，但不包括促进机体产热活动明显增强的作用（C错）。生长激素的主要作用是促进生长，十版生理学P207明确指出生长激素也可刺激产热（B对），本题的正确答案应为ABD，但给出的参考答案仅为AD。","","N"],["2015-N155",8,"第4节 听觉","骨传导",2015,155,"X","","下列结构中，受损后可产生传导性耳聋的有",[["A","听骨链"],["B","螺旋器"],["C","咽鼓管"],["D","血管纹"]],"AC","耳聋可分为传音性耳聋和感音性耳聋两大类。传音性耳聋又称传导性耳聋，是由于外耳（外耳道）和中耳（鼓膜、听骨链、鼓室和咽鼓管）（AC对）受损后而导致外界声波传导入内耳受阻而造成的耳聋。感音性耳聋又称神经性耳聋，是由于内耳耳蜗、听神经和听觉中枢的病变，导致传入内耳的声波不能感受而造成的耳聋。螺旋器和血管纹均位于内耳耳蜗（螺旋器是耳蜗基底膜上的听觉感受器；血管纹是耳蜗蜗管外侧壁的一种特殊的含血管而无基膜的复层上皮，可以产生内淋巴中正电位），与感音换能有关，受损后将产生感音性耳聋（BD错）。","","N"],["2015-N156",9,"第4节 神经系统对内脏活动、本能行为和情绪的调节","自主神经系统功能活动的基本特征",2015,156,"X","","副交感神经系统活动的一般功能特点和意义有",[["A","其功能活动相对局限"],["B","对消化系统活动具有抑制作用"],["C","活动度大小与效应器功能状态有关"],["D","有利于机体的休整恢复和能量蓄积"]],"ACD","交感神经分布广泛，几乎支配所有内脏器官，而副交感神经分布较局限，有些器官没有副交感神经支配，如皮肤和肌肉的血管、一般的汗腺、竖毛肌、肾上腺髓质和肾脏只有交感神经支配。此外，交感神经在节前与节后神经元换元时的辐散程度较高，一个节前神经元往往与多个节后神经元发生突触联系；而副交感神经在节前与节后神经元换元时的辐散程度较低，一个节前神经元只与1～2个节后神经元发生突触联系。因此，与交感神经相比，副交感神经的功能活动相对局限（A对），副交感神经系统活动的主要意义在于保护机体、休整恢复、促进消化（B错）、积蓄能量（D对）以及加强排泄和生殖功能等。副交感神经系统兴奋时，胃肠道平滑肌收缩，消化腺分泌增加，故副交感神经系统对消化系统活动具有促进作用（B错）。副交感神经系统的活动与效应器功能状态有关（C对），如胃幽门处于收缩状态时，刺激副交感神经（迷走神经）能使之舒张，而幽门处于舒张状态时，刺激副交感神经（迷走神经）则使之收缩。","","N"],["2016-N1",0,"第4节 机体的内环境、稳态和生物节律","内环境的稳态",2016,1,"A","","下列关于机体内环境稳态的描述，错误的是",[["A","稳态是指细胞内液理化性质相对恒定"],["B","稳态是一种动态平衡"],["C","稳态的维持是机体自我调节的结果"],["D","稳态调节中都有一个调节点"]],"A","稳态为机体内环境即细胞外液（A错，为本题正确答案）理化性质和各种液体成分的相对恒定。内环境稳态的维持是机体自我调节的结果（C对），稳态并非固定不变，而是可在一定范围内保持动态平衡（B对）。维持稳态最重要的调节方式是负反馈调节，负反馈调节都有一个调定点（D对）。","","N"],["2016-N2",1,"第1节 细胞膜的物质转运功能","钠-钾泵",2016,2,"A","","在引起和维持细胞内外Na⁺、K⁺不对等分布中起作用的膜蛋白是",[["A","通道"],["B","载体"],["C","离子泵"],["D","膜受体"]],"C","维持细胞内外Na⁺、K⁺不对等分布中起作用的膜蛋白为钠泵，钠泵每分解一分子ATP可逆浓度差将3个Na⁺移出胞外，将2个K⁺移入胞内，是哺乳动物细胞膜中普遍存在的离子泵（C对）。","","N"],["2016-N3",1,"第3节 细胞的电活动","电-化学驱动力及其变化",2016,3,"A","","神经细胞的静息电位是-70mv，钠离子的平衡电位是+60mv，钠离子的电-化学驱动力为多少",[["A","-130mv"],["B","-10mv"],["C","+10mv"],["D","+130mv"]],"A","钠离子的电-化学驱动力=静息电位-钠离子的平衡电位=-70mV-（+60mV）=-130mV（A对）。","","N"],["2016-N4",2,"第2节 血细胞生理","红细胞的生理特征",2016,4,"A","","风湿热时，红细胞沉降率加快的原因是",[["A","血浆纤维蛋白原、球蛋白含量增高"],["B","红细胞本身发生病变"],["C","红细胞表面积/体积比增大"],["D","血浆白蛋白、卵磷脂含量增高"]],"A","风湿热时，红细胞能彼此较快地以凹面相贴（红细胞叠连），使沉降率加快。决定红细胞沉降率快慢的因素不在于红细胞本身（B错），而在于血浆成分的变化。通常血浆中纤维蛋白原、球蛋白（A对）和胆固醇的含量增高时，可加速红细胞沉降率；而血浆中白蛋白、卵磷脂（D错）的含量增多时则可减慢红细胞沉降率。红细胞表面积/体积比增大，所产生的摩擦力增大，可减慢红细胞沉降率（C错）。","","N"],["2016-N5",2,"第2节 血细胞生理","血小板的生理特性",2016,5,"A","","阿司匹林通过减少TXA₂合成而抗血小板聚集的作用环节是",[["A","抑制COX"],["B","抑制TXA₂合成酶"],["C","抑制PGI₂合成酶"],["D","抑制PLA₂"]],"A","阿司匹林可抑制COX（环加氧酶）（A对）而减少TXA₂（血栓烷A₂）的生成。","","N"],["2016-N6",3,"第2节 心脏的电生理学及生理特性","心肌细胞兴奋性的周期性变化",2016,6,"A","","心室肌细胞在相对不应期和超常期内产生动作电位的特点是",[["A","0期去极化速度快"],["B","动作电位时程短"],["C","兴奋传导速度快"],["D","0期去极化幅度大"]],"B","在相对不应期和超常期，由于膜电位水平低于静息电位水平，而此时钠通道开放的速率和数量均低于静息电位水平时，故新生的动作电位的0期去极化速度（A错）和幅度（D错）都低于正常，故兴奋传导速度较慢（C错），动作电位的时程较短（B对）。","","N"],["2016-N7",3,"第3节 血管生理","迂回通路",2016,7,"A","","在微循环中，进行物质交换的血液不流经的血管是",[["A","微动脉"],["B","通血毛细血管"],["C","微静脉"],["D","后微动脉"]],"B","在微循环中，进行物质交换的血液依次流经微动脉（A错）、后微动脉（D错）、毛细血管前括约肌、真毛细血管网和微静脉（C错），此为微循环的营养通路。通血毛细血管（B对）为微循环直捷通路的一部分，直捷通路多位于骨骼肌中，其主要功能为使一部分血液经此通路快速进入静脉，以保证静脉回心血量。","","N"],["2016-N8",4,"","",2016,8,"A","","下列呼吸系统疾病中主要表现为呼气性呼吸困难的是",[["A","肺炎"],["B","肺水肿"],["C","肺气肿"],["D","肺纤维化"]],"C","而在肺气肿（C对）时，肺弹性成分大量破坏，肺回缩力减小，顺应性增大，弹性阻力减小，主要表现为呼气性呼吸困难。肺纤维化（D错）、肺水肿（肺表面活性物质减少）（B错）时，肺的顺应性降低，弹性阻力增加，患者表现为吸气性呼吸困难。肺炎（A错）时吸气和呼气均困难，呼吸的频率快而表浅，为混合性呼吸困难。","","N"],["2016-N9",4,"第3节 气体在血液中的运输","影响氧解离曲线的因素",2016,9,"A","","下列关于CO影响血氧运输的叙述，错误的是",[["A","CO中毒时血O₂分压下降"],["B","CO妨碍O₂与Hb的结合"],["C","CO妨碍O₂与Hb的解离"],["D","CO中毒时血O₂含量下降"]],"A","CO中毒时，动脉血氧分压是正常的（动脉血氧分压是指物理溶解于动脉血中的O₂产生的压力，而动脉血物理溶解的O₂来自肺换气过程中的肺泡气的直接供氧，故CO中毒时动脉血氧分压正常），但动脉血氧含量是下降的（动脉血氧含量的O₂仅1.5%是以物理溶解的形式运输的，其余98.5%是以与Hb化学结合的形式运输的，CO中毒时妨碍O₂与Hb的结合，故动脉血氧含量下降）（D对）。在组织耗氧量无明显改变的情况下，静脉血氧含量也是相应下降的（D对），最终导致静脉血O₂分压下降（静脉血分压是指物理溶解于静脉血中的O₂产生的压力，但是静脉血物理溶解的O₂来自化学结合的HbO₂的解离，静脉血氧含量下降，即HbO₂的含量下降，物理溶解的O₂相应减少）。简而言之：动脉血O₂分压和静脉血O₂分压的来源是不同的，动脉血O₂分压来自肺泡气，静脉血O₂分压来自氧合血红蛋白。由于动脉血氧分压来自肺泡气，所以只要外呼吸肺换气过程不出问题，动脉血氧分压总是正常的，跟血红蛋白的数量和功能状态无关。由于静脉血氧分压来自氧合血红蛋白，只要血红蛋白的数量和功能状态出现问题（如CO中毒），静脉血氧分压就会下降。故CO中毒时动脉血O₂分压是正常的，而静脉血O₂分压是下降的，因此严格来说A选项并不完全错误。但历年西医综合真题似乎将血O₂分压默认为动脉血O₂分压，若如此，则此题答案无争议。","","N"],["2016-N10",4,"第4节 呼吸运动的调节","化学感受器",2016,10,"A","","下列关于颈动脉体化学感受器的描述，错误的是",[["A","其流入流出血液中的PaO₂差接近零，通常处于动脉血环境中"],["B","PaO₂降低、PaCO₂和H⁺浓度升高对其刺激有协同作用"],["C","感受器细胞上存在对O₂、CO₂、H⁺敏感的不同受体"],["D","血供非常丰富，单位时间内血流量为全身之冠"]],"C","颈动脉体的血液供应非常丰富，其每分钟血流量约为其重量的20倍，100g该组织的血流量约为2000ml/min，单位时间内血流量为全身之冠（D对）。一般情况下，颈动脉体的动、静脉PO₂差几乎为零，即颈动脉体始终处于动脉血液的环境之中（A对）。颈动脉体在动脉血PO₂降低、PCO₂或H⁺浓度升高时受到刺激，反射性引起呼吸加深加快和血液循环功能的变化，三种因素对颈动脉体的刺激有相互增强的作用，即协同作用（B对）。颈动脉体虽然可受到PCO₂升高的刺激，但颈动脉体感受器细胞并不存在对CO₂敏感的受体，颈动脉体对CO₂的感受是通过H⁺实现的（CO₂在细胞内生成H⁺）（C错，为本题正确答案）。","","N"],["2016-N11",5,"第1节 消化生理概述","电生理特性",2016,11,"A","","胃和小肠蠕动频率的决定性因素",[["A","胃肠肌间神经丛的活动水平"],["B","胃肠平滑肌慢波节律"],["C","胃肠平滑肌动作电位频率"],["D","胃肠平滑肌本身节律活动"]],"B","胃和小肠蠕动频率的决定性因素是胃肠平滑肌慢波节律（B对）。胃肠肌间神经丛的活动水平（A错）通过影响胃肠慢波节律，进而影响胃肠蠕动频率。胃肠平滑肌本身节律活动（D错）源自胃肠平滑肌慢波节律。胃肠平滑肌动作电位频率影响胃肠蠕动的收缩强度（C错）。","","N"],["2016-N12",5,"第3节 胃内消化","盐酸",2016,12,"A","","在胃黏膜壁细胞完全缺乏时，病人不会出现的表现是",[["A","维生素B₁₂吸收障碍"],["B","肠道内细菌加速生长"],["C","胰腺分泌HCO₃⁻减少"],["D","食物蛋白质消化不良"]],"D","胃黏膜壁细胞完全缺乏时，内因子分泌减少，维生素B₁₂失去内因子-维生素B₁₂复合物的保护，被肠内水解酶破坏，导致维生素B₁₂吸收障碍（A对）。在胃黏膜壁细胞完全缺乏时，胃酸分泌减少，食糜进入小肠引起的促胰液素分泌减少，导致胰腺分泌HCO₃⁻减少（C对）。胃黏膜壁细胞完全缺乏时，胃酸缺乏时，大量细菌无法在胃内被杀灭，随食物进入肠道，使肠道内细菌加速生长（B对）。胃酸缺乏时将导致食物蛋白质消化不良，这一点在无论在临床上还是教材上都是确定无疑的，故D也对，但历年的西医综合真题（1992N148X）似乎不这么认为，若认为D错为本题答案的话，可解释为：胃蛋白酶与胰蛋白酶在功能上是重叠的，即可将蛋白质分解成䏡、胨、多肽和游离氨基酸（十版生理学P172、P180），胃蛋白酶缺乏时，其功能可以由胰蛋白酶替代，不会出现蛋白质吸收障碍。","","N"],["2016-N13",5,"第4节 小肠内消化","缩胆囊素",2016,13,"A","","促进胰腺分泌消化酶最主要的胃肠激素是",[["A","胃泌素"],["B","促胰液素"],["C","胰多肽"],["D","缩胆囊素"]],"D","缩胆囊素（D对）又称促胰酶素，是促进胰腺分泌消化酶最主要的胃肠激素。胃泌素又称促胃液素（十版生理学P175-P176），其主要功能是刺激壁细胞分泌胃酸，胃泌素也具有与缩胆囊素相似的功能（促进胰酶分泌）（十版生理学P181），但作用较缩胆囊素弱（A错）。促胰液素（十版生理学P181）主要促进胰腺分泌水和HCO₃⁻（B错）。胰多肽（C错）抑制缩胆囊素和胰酶的分泌。","","N"],["2016-N14",6,"第2节 体温及其调节","体温调节过程——体温调定点学说",2016,14,"A","","人体发热初期，出现畏寒、寒战的原因是",[["A","产热过程增强"],["B","散热过程受阻"],["C","体温调定点上移"],["D","体温调节中枢功能异常"]],"C","机体保持体温相对稳定的机制可以用体温调定点学说解释：体温调节中枢按照体温调定点设定的温度进行调节活动，当体温调定点上移（C对）时，人体出现畏寒、寒战等现象，促使机体产热活动加强，散热活动减弱，直到体温回到调定点水平。产热过程增强（A错）和散热过程受阻（B错）为畏寒、寒战的结果，而非原因。体温调节中枢功能异常（九版生理学P224）可导致中暑，不出现畏寒、寒战（D错）。","","N"],["2016-N15",7,"第6节 清除率","测定肾小球滤过率",2016,15,"A","","利用肾清除率概念测GFR，被清除物除能被肾小球滤过外，尚需满足的条件是",[["A","可被肾小管重吸收和分泌"],["B","可被肾小管重吸收但不可被分泌"],["C","不被肾小管重吸收但可被分泌"],["D","不被肾小管重吸收和分泌"]],"D","肾清除率与GFR（肾小球滤过率）完全相等时，才能利用肾清除率测GFR。当“被清除物”被肾小管重吸收但不被分泌时（B错），肾清除率小于GFR，不能用于测定GFR。当“被清除物”不被肾小管重吸收但被分泌时（C错），肾清除率大于GFR，不能用于测定GFR。当“被清除物”既可被肾小管重吸收又可被分泌时（A错），肾清除率可能大于GFR，也可能小于GFR，亦不能用于测定GFR。只有“被清除物”既不被肾小管重吸收也不被肾小管分泌时（D对），肾清除率与GFR才完全相等，才能利用肾清除率测GFR。","","N"],["2016-N16",7,"第3节 肾小管和集合管的物质转运功能","球-管平衡",2016,16,"A","","肾小管重吸收Na⁺和水的量与肾小球滤过率成定比关系的部位是",[["A","近端小管"],["B","髓袢细段"],["C","髓袢升支粗段"],["D","远曲小管"]],"A","实验证明，近端小管中Na⁺和水的重吸收率总是占肾小球滤过率的65%～70%，这称为近端小管（A对）的定比重吸收。这种定比重吸收的现象称为球-管平衡。","","N"],["2016-N17",10,"","",2016,17,"A","","机体安静情况下，对醛固酮分泌调节不起作用的因素是",[["A","促肾上腺皮质激素"],["B","高血K⁺"],["C","高血Na⁺"],["D","血管紧张素Ⅱ"]],"A","高血K⁺能够刺激醛固酮分泌，高血Na⁺能够抑制醛固酮分泌，血管紧张素Ⅱ能够刺激醛固酮分泌，故三者均能调节醛固酮的分泌（BCD错）。机体安静情况下（生理情况下），促肾上腺皮质激素（ACTH）对醛固酮的分泌无明显影响，即不起调节作用（A对）（但在应激情况下，促肾上腺皮质激素可促进醛固酮分泌）。","","N"],["2016-N18",9,"第1节 神经系统功能活动的基本原理","单线式联系",2016,18,"A","","视网膜中央凹处视敏度极高的原因是",[["A","感光细胞直径大，感光系统聚合联系"],["B","感光细胞直径小，感光系统单线联系"],["C","感光细胞直径小，感光系统聚合联系"],["D","感光细胞直径大，感光系统单线联系"]],"B","视网膜中央凹处大量分布且仅分布有视锥细胞，视锥细胞直径小，与双极细胞、神经节细胞形成单线联系（B对），这种联系方式具有极高的分辨能力，是视网膜中央凹处视敏度极高的原因。","","N"],["2016-N19",9,"第1节 神经系统功能活动的基本原理","影响递质释放的因素",2016,19,"A","","在突触传递中，与神经末梢释放递质的数量呈正相关的因素是",[["A","活化区面积的大小"],["B","进入末梢的Ca²⁺量"],["C","末梢内囊泡的大小"],["D","囊泡内递质的含量"]],"B","在突触传递中，神经末梢释放递质由Ca²⁺触发，递质的释放量与进入神经末梢的Ca²⁺量呈正相关（B对）。末梢内囊泡的大小与递质种类有关（P302）而与递质的释放量无关（C错）。","","N"],["2016-N20",9,"第1节 神经系统功能活动的基本原理","乙酰胆碱及其受体",2016,20,"A","","在周围神经系统中，属于胆碱能神经纤维的是",[["A","所有支配汗腺的交感节后纤维"],["B","所有自主神经节前纤维"],["C","所有副交感节后纤维"],["D","所有支配血管的交感节后纤维"]],"B","胆碱能神经纤维指以释放乙酰胆碱作为递质的神经纤维。所有自主神经节前纤维均属于胆碱能神经纤维（B对）。精神性发汗时，支配汗腺的交感节后纤维属于肾上腺素能纤维（A错）。少数副交感神经节后纤维释放某些肽类物质（十版生理学P166），如血管活性肠肽（VIP）、P物质、脑啡肽和生长抑素等，属于肽能神经纤维（C错）。只有支配骨骼肌舒血管纤维的交感节后纤维属于胆碱能神经纤维，其余绝大部分支配血管的交感节后纤维属于肾上腺素能纤维（D错）。","","N"],["2016-N21",10,"第2节 下丘脑-垂体及松果体内分泌","调节新陈代谢",2016,21,"A","","下列激素中，能使机体的能量来源由糖代谢向脂肪代谢转移的是",[["A","胰岛素"],["B","皮质醇"],["C","生长激素"],["D","甲状腺激素"]],"C","能使机体的能量来源由糖代谢向脂肪代谢转移的是生长激素（C对），糖皮质激素也能使得机体在饥饿或者其他应激条件下，能量来源由糖代谢向脂肪代谢转移，因此B选项也正确，该题答案存在争议，但原答案为C。注：各种激素对糖代谢、脂类代谢等物质代谢的生理作用十分复杂，具体可参考七版生理学P365页表11-9。","","N"],["2016-N22",10,"第6节 胰岛内分泌","激素的调节作用",2016,22,"A","","口服葡萄糖比静脉注射等量葡萄糖引起更多的胰岛素分泌，其原因是",[["A","小肠吸收葡萄糖非常完全"],["B","小肠分泌抑胃肽刺激胰岛素分泌"],["C","流经胰岛的血流量很少"],["D","血流经胰岛时葡萄糖浓度已很低"]],"B","口服葡萄糖后，由于肠黏膜分泌抑胃肽，可在血糖水平升高前刺激胰岛B细胞释放胰岛素，导致胰岛素迅速而明显的分泌，超过由静脉注射葡萄糖所引起的胰岛素分泌量（B对）。","","N"],["2016-N23",10,"第4节 甲状旁腺、维生素D与甲状腺C细胞内分泌","维生素D的概述",2016,23,"A","","活性最高的1，25-二羟维生素D₃的最终生成部位是",[["A","皮肤"],["B","肠道"],["C","肝脏"],["D","肾脏"]],"D","皮肤（A错）中含7-脱氢胆固醇，在紫外线照射下可转化成维生素D₃，维生素D₃在肝脏（C错）25-羟化酶催化下生成25-羟维生素D₃，最后在肾脏（D对）内，经1α-羟化酶的催化，生成活性最高的1，25-二羟维生素D₃。肠道（B错）是1，25-二羟维生素D₃作用的靶组织。","","N"],["2016-N24",11,"第2节 女性生殖功能及其调节","卵巢的生卵作用",2016,24,"A","","在月经周期的卵泡期，唯有一个卵泡能最终发育成熟的主要原因是",[["A","该卵泡分泌较多E₂，使之摄取更多的FSH"],["B","该卵泡分泌较多P，使之摄取更多的LH"],["C","该卵泡分泌较少抑制素，抑制FSH分泌的作用较弱"],["D","该卵泡分泌较少抑制素，抑制LH分泌的作用较弱"]],"A","按照七版及更早版本教材的观点，在月经周期的卵泡期，唯有一个优势卵泡能最终发育成熟的主要原因是该卵泡分泌较多 E 2 （雌二醇），使之摄取更多的 FSH（卵泡刺激素）（A 对）。九版及十版教材则认为唯有一个优势卵泡能最终发育成熟与不同卵泡对FSH的敏感性不同有关，涉及一个概念，叫FSH阈值，FSH阈值指卵泡生长发育所需的FSH的最小血中浓度，反映卵泡对FSH的敏感性。卵泡期开始的时候，血中FSH水平升高，达到部分卵泡生长发育所需的FSH阈值。随着卵泡的生长，雌激素合成分泌增加，加上卵泡颗粒细胞产生的抑制素对腺垂体的负反馈调节作用，使其FSH分泌有所减少。这时的FSH血中浓度一般仅能满足一个发育最快，其FSH阈值最低的卵泡（即优势卵泡）最终发育成熟的需要，其他卵泡因得不到足够的FSH的支持而发生闭锁。按最新版教材观点，本题无答案。但七版及更早版本教材认为该卵泡分泌较多E₂，使之摄取更多的FSH（A对，为本题正确答案），故本题给出的参考答案为A。","","N"],["2016-N121",1,"第4节 肌细胞的收缩","前负荷",2016,121,"B","","在一定范围内增加骨骼肌收缩的前负荷，则骨骼肌的收缩力的力学改变",[["A","收缩速度加快"],["B","缩短长度增加"],["C","主动张力增加"],["D","缩短起始时间提前"]],"C","在一定范围内增加骨骼肌收缩的前负荷即增加骨骼肌收缩前的初长度，骨骼肌收缩前的初长度增加，粗、细肌丝的重叠程度增加，骨骼肌收缩的主动张力增加（C对）。","","N"],["2016-N122",1,"第4节 肌细胞的收缩","后负荷",2016,122,"B","","在一定范围内增加骨骼肌收缩的后负荷，则骨骼肌的收缩力的力学改变",[["A","收缩速度加快"],["B","缩短长度增加"],["C","主动张力增加"],["D","缩短起始时间提前"]],"C","后负荷是指肌肉在收缩后所承受的负荷。骨骼肌后负荷增加时，骨骼肌收缩过程中遇到的阻力增加，为了克服阻力，骨骼肌收缩的主动张力增加（C对）。后负荷增加，肌肉缩短起始时间推迟（D错），肌肉缩短长度减小（B错），肌肉收缩速度减慢（A错）。","","N"],["2016-N123",3,"第4节 心血管活动的调节","血管紧张素家族主要成员的生理作用",2016,123,"B","","在RAS中，促使全身微动脉收缩，升高血压作用最强的是",[["A","血管紧张素Ⅰ"],["B","血管紧张素Ⅱ"],["C","血管紧张素Ⅲ"],["D","血管紧张素Ⅳ"]],"B","在RAS（肾素-血管紧张素系统）中，血管紧张Ⅰ一般无升压作用（A错）。血管紧张素Ⅱ可使全身微动脉收缩，升高血压（B对）。血管紧张素Ⅲ和血管紧张素Ⅳ均有升压作用，但其作用远小于血管紧张素Ⅱ（CD错）。","","N"],["2016-N124",3,"第4节 心血管活动的调节","血管紧张素家族主要成员的生理作用",2016,124,"B","","在RAS中，促进肾上腺皮质合成与释放醛固酮作用最强的是",[["A","血管紧张素Ⅰ"],["B","血管紧张素Ⅱ"],["C","血管紧张素Ⅲ"],["D","血管紧张素Ⅳ"]],"C","在RAS（肾素-血管紧张素系统）中，血管紧张素Ⅱ和血管紧张素Ⅲ均能促进肾上腺皮质合成与释放醛固酮，但血管紧张素Ⅲ的促进作用更强（C对）。","","N"],["2016-N125",9,"第2节 神经系统的感觉分析功能","体表感觉代表区及感觉信息处理",2016,125,"B","","刺激动物右侧坐骨神经，在大脑皮层可见最大幅度诱发电位的部位是",[["A","左侧中央后回顶部"],["B","右侧中央后回底部"],["C","两侧中央后回顶部"],["D","两侧中央后回底部"]],"A","由于躯干四肢部分的感觉为交叉性投射，且下肢的投射区域位于中央后回顶部，故刺激动物右侧坐骨神经（下肢神经）时，在大脑皮层可见最大幅度诱发电位的部位是左侧中央后回顶部（A对）。","","N"],["2016-N126",9,"第2节 神经系统的感觉分析功能","体表感觉代表区及感觉信息处理",2016,126,"B","","刺激右侧三叉神经，使大脑皮层出现最大幅度诱发电位的部位是",[["A","左侧中央后回顶部"],["B","右侧中央后回底部"],["C","两侧中央后回顶部"],["D","两侧中央后回底部"]],"D","由于头面部感觉的投射为双侧性投射，投射区域为中央后回的底部。故刺激右侧三叉神经（头面部神经）时，在大脑皮层可见最大幅度诱发电位的部位是两侧中央后回底部（D对）。","","N"],["2016-N151",1,"第1节 细胞膜的物质转运功能","出胞",2016,151,"X","","下面的物质转运中属于出胞的是",[["A","肥大细胞脱颗粒"],["B","内分泌细胞分泌激素"],["C","肾小管上皮细胞分泌氢离子"],["D","神经末梢释放递质"]],"ABD","出胞是指胞质内的大分子物质以分泌囊泡的形式排出细胞的过程。肥大细胞脱颗粒（A对）、内分泌细胞分泌激素（B对）、神经末梢释放递质（D对）均属于出胞过程。肾小管（包括近端小管、髓袢和远曲小管）上皮细胞分泌氢离子（P237）主要由Na⁺-H⁺交换介导，属于继发性主动转运（C错）。","","N"],["2016-N152",2,"第3节 生理性止血","纤维酶原的激活",2016,152,"X","","下列物质中能使纤溶酶原激活为纤溶酶的有",[["A","蛋白质C"],["B","尿激酶"],["C","凝血酶因子Ⅻa"],["D","激肽释放酶"]],"BCD","尿激酶（B对）、凝血酶因子Ⅻa（C对）、激肽释放酶（D对）均能使纤溶酶原激活为纤溶酶。蛋白质C为生理性抗凝物质，也可促进纤维蛋白溶解，但并不是纤溶酶原激活物。","","N"],["2016-N153",3,"第3节 血管生理","动脉血压的形成",2016,153,"X","","动脉血压形成的基本条件有",[["A","心脏射血"],["B","血流速度"],["C","大动脉弹性"],["D","外周血管阻力"]],"ACD","心脏射血（A对）、大动脉弹性（C对）、外周血管阻力（D对）均为动脉血压形成的基本条件。动脉血压是血流速度（B错）形成的条件，而非相反。","","N"],["2016-N154",6,"第1节 能量代谢","环境温度",2016,154,"X","","下列哪种情况能使机体能量代谢显著提高",[["A","天气寒冷"],["B","天气炎热"],["C","焦虑烦恼"],["D","病理性饥饿"]],"ABC","天气寒冷（A对）、天气炎热（B对）、焦虑烦恼（C对）时机体能量代谢显著提高。病理性饥饿（D错）时机体能量代谢降低。","","N"],["2016-N155",8,"第4节 听觉","气传导(1)",2016,155,"X","","下列声波传到内耳的途径中，属于气传导的是",[["A","声波→鼓膜→听骨链→卵圆窗膜→内耳"],["B","声波→颅骨→耳蜗外淋巴→耳窝内淋巴"],["C","声波→鼓膜→鼓室空气→圆窗膜→内耳"],["D","声波→颅骨→耳蜗内淋巴"]],"AC","气传导是指声波经外耳道引起鼓膜振动，再经听骨链和卵圆窗膜进入耳蜗的传导途径，即声波-鼓膜-听骨链-卵圆窗膜-内耳（耳蜗内淋巴）的传导途径属于气传导（A对）。此外，鼓膜的振动也可引起鼓室内空气的振动，再经圆窗膜传入耳蜗，这一途径也属于气传导，即声波-鼓膜-鼓室空气-圆窗膜-内耳（耳蜗内淋巴）的传导途径也属于气传导（C对）。骨传导是指声波直接作用于颅骨，经颅骨和耳蜗骨壁传入耳蜗的途径。声波-颅骨-耳窝外淋巴-耳蜗内淋巴和声波-颅骨-耳蜗内淋巴均属于骨传导（BD错）。","","N"],["2016-N156",9,"第3节 神经系统对躯体运动的调控","帕金森病",2016,156,"X","","能明显改善帕金森病症状的药物有",[["A","利血平"],["B","普萘洛尔"],["C","东莨菪碱"],["D","左旋多巴"]],"CD","帕金森病的病因是双侧黑质病变，多巴胺能神经元变性受损，多巴胺能递质减少。多巴胺的前体左旋多巴（D对）及M受体拮抗剂东莨菪碱（C对）均能明显改善帕金森病症状。利血平（A错）可以耗竭多巴胺，会加重帕金森病症状。普萘洛尔属于β受体阻滞剂，在临床上用于高血压和心脏病的治疗，在左旋多巴的使用过程中，有些患者会出现心律不齐，主要是由于新生的多巴胺作用于心脏β受体的原因，可用β受体阻滞剂加以治疗，但同时也有文献表明，β受体阻滞剂可能增加帕金森致病相关基因的活性，曾经服用普萘洛尔的患者患上帕金森的风险增加，普萘洛尔（B错）并不作为帕金森病的常规治疗，不能明显改善帕金森病的症状。","","N"],["2017-N1",1,"第1节 细胞膜的物质转运功能","继发性主动转运",2017,1,"A","","葡萄糖跨肠上皮纹状缘进入细胞的方式是",[["A","单纯扩散"],["B","易化扩散"],["C","原发性主动转运"],["D","继发性主动转运"]],"D","葡萄糖从小肠上皮纹状缘进入上皮细胞采用的方式是继发性主动转运（D对）。单纯扩散（A错）主要介导脂溶性物质或少数不带电荷的极性小分子的物质转运，如O₂、CO₂、N₂、NH₃、类固醇激素、乙醇、尿素、甘油、水等。易化扩散（B错）包括经通道的易化扩散和经载体的易化扩散两种形式：经通道易化扩散主要以离子通道的形式（如Na⁺通道、K⁺通道等）进行物质转运，Na⁺通过离子通道的跨膜转运过程属于此种方式；经载体的易化扩散主要介导葡萄糖、氨基酸等水溶性小分子物质进行顺浓度梯度的跨膜转运。原发性主动转运（C错）通常以离子泵的形式（如Na⁺泵、Ca²⁺泵、H⁺泵等）转运各种带电离子，但其通过膜蛋白转运且为消耗能量的逆浓度运输。","","N"],["2017-N2",1,"第4节 肌细胞的收缩","兴奋-收缩耦联的基本步骤",2017,2,"A","","下列关于骨骼肌兴奋-收缩耦联的叙述，正确的是",[["A","纵管的作用是将电兴奋传入肌细胞深部"],["B","肌膜和横管膜L型钙通道激活"],["C","终池内Ca²⁺逆浓度差进入肌质"],["D","Ca²⁺与肌动蛋白的钙结合亚单位结合"]],"B","骨骼肌收缩耦联的过程（P51）为：①横管（T管）（A错）将电兴奋传入肌细胞深部，激活肌膜（横管膜）中的L型钙通道（B对）；②T管膜中的L型钙通道被激活后，L型钙通道的电压敏感肽段发生构象改变，产生“拔塞”样作用，使与T管膜对应的终池（即连接肌质网，JSR）中的钙释放通道开放（P52图2-32 横纹肌肌质网Ca²⁺释放机制），终池内的高浓度Ca²⁺顺浓度差释放到胞质中（C错）；③胞质中Ca²⁺浓度升高促使Ca²⁺与肌钙蛋白的钙结合亚基（肌钙蛋白C）结合（D错），触发肌肉收缩。","","N"],["2017-N3",2,"第3节 生理性止血","生理性止血的基本过程",2017,3,"A","","生理止血过程中促进血小板发生不可逆聚集的主要原因是",[["A","血管内皮受损，PGI₂生成减少"],["B","血小板释放ADP和TXA₂"],["C","血管内皮受损，内皮下胶原暴露"],["D","血小板收缩蛋白收缩"]],"B","生理性止血过程主要包括血管收缩、血小板聚集（血小板血栓形成）和血液凝固三个过程。ABC均可促进血小板聚集，其中ADP、TXA₂生成（B对）可促进血小板不可逆聚集。血小板收缩蛋白收缩（P73）（D错）则促进血液凝固（引起血凝块回缩，使血凝块更加坚实）。","","N"],["2017-N4",3,"第2节 心脏的电生理学及生理特性","窦房结细胞动作电位",2017,4,"A","","与心室肌相比，窦房结细胞生物电活动的特征是",[["A","0期去极化速度较快"],["B","静息电位绝对值较小"],["C","0期去极化可被河豚毒素阻断"],["D","4期自动去极化速度慢"]],"B","窦房结细胞膜中的Iₖ₁通道较为缺乏，其最大复极化电位仅约-70mV。因此，与心室肌相比，窦房结细胞的静息电位绝对值小（B对）（在自律细胞中，通常用最大复极电位来代表静息电位值）。窦房结细胞膜也缺乏INa通道（快钠通道），其动作电位0期的产生主要依赖ICa-L通道（慢钙通道），因而其0期去极化速度较慢（A错），去极时间较长。河豚毒主要用于阻断钠通道（十版生理学P33），因此能阻断由快钠通道介导的心室肌细胞的0期，但不能阻断由慢钙通道介导的窦房结细胞的0期（C错）。窦房结细胞的4期自动去极化速度快（D错），自律性高，是心脏的起搏细胞，而心室肌细胞不能发生4期自动去极化。","","N"],["2017-N5",3,"第1节 心脏的泵血功能","心室舒张期",2017,5,"A","","一个心动周期中，主动脉瓣开始关闭的瞬间是",[["A","等容收缩期初"],["B","等容舒张期初"],["C","快速射血期初"],["D","快速充盈期初"]],"B","一个心动周期中，主动脉瓣开始关闭的瞬间是等容舒张期初（B对）。等容收缩期初（A错）为房室瓣开始关闭的瞬间。快速射血期初（C错）为主动脉瓣开始开放的瞬间。快速充盈期初（D错）为房室瓣开始开放的瞬间。","","N"],["2017-N6",4,"第2节 肺换气和组织换气","肺换气",2017,6,"A","","肺换气的过程是指",[["A","外界环境中的O₂入肺泡的过程"],["B","肺泡与外界环境进行气体交换"],["C","肺泡与血液进行气体交换"],["D","肺泡内气体不断更新的过程"]],"C","呼吸的全过程由外呼吸、气体在血液中的运输、内呼吸共三个环节组成。外呼吸包括肺通气和肺换气，肺通气是指肺与外界环境之间的气体交换过程，肺换气指肺泡气体和血液（C对）之间的气体交换过程。内呼吸是指血液与组织、细胞之间的气体交换。","","N"],["2017-N7",9,"第1节 神经系统功能活动的基本原理","NE和肾上腺素及其受体",2017,7,"A","","能引起气道平滑肌舒张的化学因素是",[["A","组胺"],["B","PGF2α"],["C","乙酰胆碱"],["D","去甲肾上腺素"]],"D","一般而言，去甲肾上腺素（NE）与α受体（主要是α₁受体）结合后产生的平滑肌效应主要是兴奋性的，包括血管、子宫、虹膜辐射状肌等的收缩，但也有抑制性的，如小肠舒张（为α₂受体）。去甲肾上腺素与β受体（主要是β₂受体）结合后产生的平滑肌效应则为抑制性的，包括血管、子宫、小肠、支气管（D对）等的舒张，但与心肌β₁受体结合所产生的效应却是兴奋性的。组胺（A错）、PGF₂α（前列腺素F₂α）（B错）、乙酰胆碱（C错）均引起气道平滑肌收缩。","","N"],["2017-N8",5,"第7节 吸收","脂肪的吸收",2017,8,"A","","关于肠吸收脂肪叙述，正确的是",[["A","吸收后与胆盐结合成混合微胶粒"],["B","长链脂肪酸在上皮细胞重新合成甘油三酯"],["C","胆盐随胆固醇进入上皮细胞"],["D","中、短脂肪酸通过淋巴管吸收"]],"B","脂肪在肠内需要经过先消化，后吸收的过程。在小肠内，脂类的消化产物脂肪酸、一酰甘油、胆固醇等与胆汁中的胆盐形成混合微胶粒，由于胆盐的双嗜特性，它能携带脂肪消化产物通过覆盖于小肠黏膜上皮细胞表面的不流动水层到达上皮细胞表面。在这里，一酰甘油、脂肪酸和胆固醇等从混合胶粒释出，透过上皮细胞脂质膜而进入细胞。即在肠吸收脂肪过程中，其消化产物是在吸收前（消化过程中）（A错）与胆盐结合成了混合微胶粒。而在吸收过程中，胆固醇等脂类消化产物将从混合胶粒释出，与胆盐分离后再进入上皮细胞（C错）。长链脂肪酸在上皮细胞重新合成甘油三酯（B对），并与细胞中生成的载脂蛋白合成乳糜微粒，出胞释放后经淋巴管吸收。而中、短链脂肪酸在小肠上皮细胞中不再变化，它们是水溶性的，可直接进入血液而不入淋巴（D错）。","","N"],["2017-N9",6,"第1节 能量代谢","间接测热法",2017,9,"A","","关于食物氧热价的叙述正确的是",[["A","食物氧热价分为生物热价和物理热价"],["B","蛋白质的氧热价随耗氧量改变而改变"],["C","指食物氧化时消耗1升氧所产生的热量"],["D","指1克食物氧化时所释放的能量"]],"C","食物的氧热价是指某种食物氧化时消耗1升氧所产生的热量（C对），因此，氧热价的耗氧量为1升氧，是固定值，氧热价随耗氧量改变而改变的说法有误（B错）。1克食物氧化时所释放的能量（D错）为食物的热价。食物的热价分为生物热价和物理热价（A错），分别是指食物在体内氧化和体外燃烧时释放的能量。","","N"],["2017-N10",7,"第3节 肾小管和集合管的物质转运功能","K⁺的重吸收和分泌",2017,10,"A","","正常人摄入K⁺增多，肾排K⁺也增多的原因是",[["A","远曲小管和集合管分泌K⁺增多"],["B","近球小管重吸收K⁺减少"],["C","醛固酮分泌减少"],["D","肾小球滤过率增强"]],"A","正常人摄入K⁺增多时，血K⁺浓度升高，可刺激醛固酮分泌增多（十版生理学P371）（C错），醛固酮可促进肾远曲小管和集合管上皮细胞重吸收Na⁺和分泌K⁺（A对），使肾排K⁺也增多。在近球小管，有65%～70%的K⁺被重吸收，这一重吸收比例是比较固定的（十版生理学P224），因此，当摄入K⁺增多，血K⁺浓度升高时，近端小管重吸收K⁺也是增多的（B错）。肾小球滤过率是指单位时间内两肾生成的超滤液的量，肾小球滤过率的大小取决于有效滤过压和滤过系数（十版生理学P219-P220），与血K⁺浓度无关，因此摄入K⁺增多时，肾小球滤过率不发生变化（D错）。","","N"],["2017-N11",7,"第5节 尿生成的调节","概述",2017,11,"A","","在尿液的浓缩和稀释调控中起关键作用的体液因子是",[["A","血管紧张素Ⅱ"],["B","醛固酮"],["C","血管升压素"],["D","心房钠尿肽"]],"C","尿液的浓缩与稀释实际上取决于集合管对小管液中水和溶质重吸收的比率，而水的重吸收较易改变，因而是其主要方面。水的重吸收取决于两个基本条件，一是肾小管内外的渗透浓度梯度，是水重吸收的动力；二是集合管对水的通透性。因此，尿的浓缩与稀释一方面取决于肾髓质渗透梯度，另一方面取决于集合管对水的通透性，后者主要受血液中血管升压素（C对）浓度的影响。","","N"],["2017-N12",8,"第3节 视觉","瞳孔对光反射",2017,12,"A","","瞳孔对光反射的中枢部位",[["A","枕叶皮层"],["B","外侧膝状体"],["C","中脑"],["D","延髓"]],"C","瞳孔对光反射的中枢部位在中脑（C对）。枕叶皮层（十版生理学P264）（A错）也称视皮层，是视觉中枢所在。外侧膝状体（十版生理学P264）（B错）为视觉传导通路中的神经传导结构。延髓（十版生理学P160）（D错）是调节呼吸循环的基本生命中枢。","","N"],["2017-N13",9,"第1节 神经系统功能活动的基本原理","突触后神经元动作电位的产生",2017,13,"A","","下列关于兴奋性突触后电位的叙述，正确的是",[["A","由突触前神经元释放抑制性递质而引起"],["B","性质上属于动作电位，但幅度较小"],["C","重复刺激可发生时间总和"],["D","通过突触后膜K⁺通道开放而产生"]],"C","兴奋性突触后电位（EPSP）的产生过程：突触前神经元释放兴奋性递质（A错），作用于突触后膜的相应受体，使Na⁺通道、K⁺通道等离子通道开放，使后膜对Na⁺和K⁺的通透性增大，且Na⁺内流大于K⁺外流，故发生净内向电流，导致后膜出现局部去极化，因此，兴奋性突触后电位主要由突触后膜Na⁺通道开放而产生（D错）。兴奋性突触后电位属于局部电位（B错），具有局部兴奋的性质，因此重复刺激可以引起时间和空间的总和（C对）。","","N"],["2017-N14",9,"第3节 神经系统对躯体运动的调控","牵张反射的感受器",2017,14,"A","","下列关于肌牵张反射的叙述，错误的是",[["A","肌梭是肌牵张反射的感受器"],["B","反射的基本中枢位于脊髓"],["C","脊髓横断后，肌牵张反射永久消失"],["D","是维持姿势的基本反射"]],"C","牵张反射是指有完整神经支配的骨骼肌在受外力牵拉伸长时引起的被牵拉的同一肌肉发生收缩的反射。它的感受器是肌梭（A对），有Ⅰa和Ⅱ类两种传入纤维，基本中枢位于脊髓（B对），传出纤维是α和γ纤维，效应器是被牵拉的同一肌肉。脊髓横断后将发生脊髓休克，横断面以下的脊髓所支配的牵张反射暂时消失而进入无反应状态，但随着时间的推移以脊髓为基本中枢的牵张反射可逐渐在不同程度上恢复（C错，为本题正确答案）。牵张反射包括腱反射和肌紧张两种类型，其中肌紧张是维持身体姿势最基本的反射活动（D对）。","","N"],["2017-N15",10,"第2节 下丘脑-垂体及松果体内分泌","调节新陈代谢",2017,15,"A","","生长激素对物质代谢的调节作用是",[["A","促进肝外组织蛋白质合成"],["B","促进肝糖原生成"],["C","促进外周组织利用葡萄糖"],["D","促进脂肪合成"]],"A","生长激素（GH）能调节糖、脂肪、蛋白质等物质代谢。①生长激素可促进肝糖原分解（B错），同时可抑制外周组织摄取和利用葡萄糖（C错），减少葡萄糖消耗，升高血糖水平。②生长激素可以抑制脂肪细胞分化，减少三酰甘油的积蓄；激活激素敏感的脂肪酶，促进脂肪分解，增强脂肪酸氧化，提供能量，并使组织特别是肢体的脂肪量减少，促进脂肪分解（D错）。③生长激素促进蛋白质代谢，总效应是合成大于分解，特别是促进肝外组织合成蛋白质（A对），如促进氨基酸进入肌肉细胞利用，减少尿氮，呈正氮平衡。","","N"],["2017-N16",11,"第1节 男性生殖功能及其调节","睾丸的生精功能",2017,16,"A","","分泌雄激素结合蛋白的细胞是",[["A","睾丸精细胞"],["B","睾丸间质细胞"],["C","睾丸支持细胞"],["D","睾丸生精细胞"]],"C","分泌雄激素结合蛋白的细胞是睾丸支持细胞（C对），其具有分泌功能，还可分泌抑制素等其他生物活性物质。睾丸间质细胞（P404）（B错）可分泌雄激素。睾丸生精细胞（十版生理学P384）（D错）可生成精子。睾丸精细胞（十版生理学P384）（A错）即精子细胞，是睾丸所产生的一种单倍体细胞，它是精子发生、成熟、形成功能性精子过程中第二次成熟分裂的结果，精子细胞经过一系列形态的变化，形成成熟的精子。","","N"],["2017-N116",3,"第3节 血管生理","影响组织液生成的因素",2017,116,"B","","右心衰竭发生组织水肿的主要机制是",[["A","毛细血管血压增高"],["B","血浆胶体渗透压降低"],["C","组织液胶体渗透压增高"],["D","毛细血管通透性增高"]],"A","右心衰竭时，体循环静脉压增高，静脉回流受阻，全身毛细血管后阻力增大，导致毛细血管血压增高（A对），引发组织水肿。血浆胶体渗透压降低（B错）是营养不良性水肿、肝性水肿或肾性水肿的水肿机制。毛细血管通透性增高（D错）时，血浆蛋白可随液体渗出毛细血管，使组织液胶体渗透压增高（C错），导致组织液生成增多而出现水肿，此为炎性水肿（见于感染、烧伤、过敏等情况）的水肿机制。","","N"],["2017-N117",3,"第3节 血管生理","影响组织液生成的因素",2017,117,"B","","肾病综合征发生组织水肿的主要机制是",[["A","毛细血管血压增高"],["B","血浆胶体渗透压降低"],["C","组织液胶体渗透压增高"],["D","毛细血管通透性增高"]],"B","肾病综合征时，大量白蛋白从尿中丢失，使血浆胶体渗透压降低（B对），液体从血管内渗入组织间隙，产生水肿。毛细血管血压增高（A错）是右心衰发生水肿的主要机制。毛细血管通透性增高（D错）时，血浆蛋白可随液体渗出毛细血管，使组织液胶体渗透压增高（C错），导致组织液生成增多而出现水肿，此为炎性水肿（见于感染、烧伤、过敏等情况）的水肿机制。","","N"],["2017-N118",10,"第2节 下丘脑-垂体及松果体内分泌","缩宫素",2017,118,"B","","缩宫素的分泌调节的形式是",[["A","以神经调节形式为主"],["B","以激素调节为主"],["C","以代谢产物反馈调节为主"],["D","受靶腺激素及下丘脑调节肽的双重调节"]],"A","缩宫素（OT）的主要作用是在妇女分娩时刺激子宫强烈收缩和在哺乳期促进乳汁排出。它的调节属于神经-内分泌调节，以神经调节形式为主（A对）。最有力的刺激是分娩时胎儿对子宫颈的机械性扩张，可通过正反馈机制促进OT神经元分泌，结果引起强有力的子宫平滑肌收缩，起到催产的作用。","","N"],["2017-N119",10,"第4节 甲状旁腺、维生素D与甲状腺C细胞内分泌","甲状旁腺激素的分泌调节",2017,119,"B","","甲状旁腺激素分泌的调节形式是",[["A","以神经调节形式为主"],["B","以激素调节为主"],["C","以代谢产物反馈调节为主"],["D","受靶腺激素及下丘脑调节肽的双重调节"]],"C","甲状旁腺激素的分泌主要受血钙浓度的影响，即以代谢产物反馈调节为主（C对）。","","N"],["2017-N136",2,"第3节 生理性止血","生理性抗凝物质",2017,136,"X","","肝素抗凝血作用的机制有",[["A","抑制因子V的激活"],["B","促进纤溶酶原的激活"],["C","增强抗凝血酶的活性"],["D","促进组织因子途径抑制物的释放"]],"CD","肝素的直接抗凝作用很弱，主要通过与抗凝血酶结合，增强其抗凝活性（C对）来间接发挥抗凝作用。促进组织因子途径抑制产物（TFPI）的释放（D对）为肝素发挥抗凝作用的另一机制。灭活因子V，抑制其作用（A错）为蛋白质C系统的抗凝机制。促进纤溶酶原的激活（十版生理学P72）（B错）为促纤溶机制。","","N"],["2017-N137",5,"第4节 小肠内消化","小肠的运动形式",2017,137,"X","","小肠运动的形式",[["A","紧张性收缩"],["B","分节运动"],["C","集团蠕动"],["D","逆蠕动"]],"ABD","小肠有紧张性收缩（A对）、分节运动（B对）和蠕动三种基本运动类型，其中蠕动又包括蠕动冲、逆蠕动（D对）等特殊类型。集团蠕动（C错）为大肠的运动形式。","","N"],["2017-N138",4,"第3节 气体在血液中的运输","CO₂的运输形式",2017,138,"X","","关于CO₂在血液中运输的叙述，正确的是",[["A","化学结合形式的CO₂主要是碳酸氢盐"],["B","小部分CO₂直接溶解于血浆中"],["C","Hb与CO₂结合生成氨基甲酰血红蛋白需酶催化"],["D","碳酸酐酶在CO₂运输中发挥重要作用"]],"ABD","血液中小部分CO₂直接溶解于血浆中（B对），以物理溶解的形式运输，其余则以化学结合的形式运输。化学结合的形式主要是碳酸氢盐（A对）和氨基甲酰血红蛋白，前者由碳酸酐酶（D对）在红细胞内催化CO₂与H₂O反应而生成，后者则由Hb与CO₂结合生成，无需酶的催化（C错）。","","N"],["2017-N139",7,"第5节 尿生成的调节","肾素分泌的调节",2017,139,"X","","促进肾素分泌的因素有",[["A","循环血量减少"],["B","肾小球滤过Na⁺减少"],["C","动脉血压降低"],["D","肾交感神经活动减弱"]],"ABC","（P247）肾素的分泌受肾内机制、神经机制、体液机制这三个机制调节。其中肾内机制分别为位于入球小动脉的牵张感受器感受肾动脉的灌注压和位于远曲小管起始部的致密斑感受流经该处小管液中的 NaCl量，当肾动脉灌注不足（循环血量减少）（A对）以及流经致密斑的 NaCl量减少时（肾小球滤过Na⁺减少是原因之一）（B对），使肾素分泌增加。神经机制为因急性大失血、血量减少、血压下降（C对）时，可反射性兴奋肾交感神经释放去甲肾上腺素，作用于球旁细胞膜中的β受体，使肾素释放增加（D错）。","","N"],["2017-N140",9,"第1节 神经系统功能活动的基本原理","影响递质释放的因素",2017,140,"X","","影响突触前电位神经末梢释放神经递质的数量的主要因素是",[["A","神经冲动的传导速度"],["B","动作电位的频率"],["C","进入神经末梢的Ca²⁺量"],["D","突触囊泡的大小"]],"BC","影响突触前电位神经末梢释放神经递质的数量的主要因素是进入神经末梢的Ca²⁺量（C对），因此，凡能影响末梢处Ca²⁺内流的因素都能改变递质的释放量，而动作电位频率（B对）的改变正是一种可以影响末梢处Ca²⁺内流的因素。神经冲动的传导速度（A错）不影响末梢处Ca²⁺内流，与递质释放量无关。突触囊泡大小（十版生理学P287）（D错）与递质种类有关而与递质的释放数量无关。","","N"],["2017-N141",6,"第2节 体温及其调节","出汗",2017,141,"X","","对汗液的叙述，正确的是",[["A","汗液中不含蛋白质"],["B","刚刚分泌的汗液渗透压高于血浆"],["C","汗液中的Na⁺浓度受醛固酮调节"],["D","由汗腺细胞被动分泌"]],"AC","汗液是由汗腺细胞主动分泌的（D错），其99%的成分是水分，1%的成分是NaCl、KCl、尿素等固态成分，不含蛋白质（A对）。刚分泌出来的汗液渗透压与血液是等渗的（B错），但在流经汗腺管腔时，在醛固酮的作用（C对）下，汗液中的Na⁺和Cl⁻被重吸收，最后排出的汗液是低渗的。","","N"],["2018-N1",0,"第6节 人体内自动控制系统","负反馈控制系统",2018,1,"A","","在维持机体稳态的调节中，负反馈控制的特点是",[["A","迅速"],["B","有波动"],["C","有预见性"],["D","有可能失误"]],"B","人体内包括反馈（十版生理学P10）和前馈（十版生理学P11）两种不同的控制系统，其中反馈包括负反馈和正反馈两种形式。负反馈具有反馈的滞后性和波动性（B对）特点。预见性（C错）和有可能失误（D错）为前馈的特点。","","N"],["2018-N2",1,"第3节 细胞的电活动","动作电位期间膜离子通透性的变化",2018,2,"A","","神经细胞在静息时，电压门控钠通道对Na⁺通透的门控状态是",[["A","激活门和失活门都开放"],["B","激活门和失活门都关闭"],["C","激活门开放，失活门关闭"],["D","激活门关闭，失活门开放"]],"D","电压门控钠通道存在三种功能状态：①静息态；②激活态；③失活态。静息态时，电压门控钠通道的门控状态为激活门关闭，失活门开放（D对）。激活态时，电压门控钠通道的门控状态为激活门开放，失活门逐渐关闭。失活态时，电压门控钠通道的门控状态为激活门开放，失活门完全关闭（B错）。","","N"],["2018-N3",2,"第3节 生理性止血","生理性止血的基本过程",2018,3,"A","","在生理性止血过程中，与识别损伤部位有关的血小板生理特性是",[["A","血小板黏附"],["B","血小板聚集"],["C","血小板释放"],["D","血小板吸附"]],"A","血管损伤时，与血小板识别损伤部位有关的血小板生理是血小板黏附（A对）。血小板黏附指血小板与非血小板表面的黏着，黏附的过程为：血管损伤部位的内皮下胶原暴露→血浆vWF因子与胶原纤维（内皮下组织成分）结合→血浆vWF变构→血小板膜上GPⅠb与变构的vWF结合→血小板黏附于内皮下胶原纤维上。血小板聚集（十版生理学P64）（B错）指血小板与血小板之间的相互黏着。血小板释放（十版生理学P64）（C错）指血小板受刺激后将储存在致密体，α-颗粒或溶酶体内的物质排出的现象，亦称血小板分泌。血小板吸附（十版生理学P65）（D错）指血小板表面可吸附血浆中多种凝血因子，如Ⅰ、Ⅴ、Ⅺ等。","","N"],["2018-N4",3,"第2节 心脏的电生理学及生理特性","窦房结细胞动作电位",2018,4,"A","","引起窦房结P细胞动作电位0期去极化的主要离子流是",[["A","Iɴₐ"],["B","Iᴋ"],["C","Iᴄₐ-ʟ"],["D","Iᴄₐ-ᴛ"]],"C","窦房结P细胞缺乏Iɴₐ通道（A错），0期去极化起主要作用的是Iᴄₐ-ʟ通道（C对），因此0期去极化速度较慢，持续时间较长。Iɴₐ通道（A错）主要作用于心室肌细胞（十版生理学P91）和蒲肯野细胞（十版生理学P95）0期去极化过程。Iₖ通道（B错）主要作用于窦房结P细胞3期复极化过程（十版生理学P94）。Iᴄₐ-T通道（D错）主要作用于窦房结P细胞4期自动去极化过程（十版生理学P94）。","","N"],["2018-N5",4,"第1节 肺通气","肺容量",2018,5,"A","","能使功能余气量增多的呼吸系统疾病是",[["A","肺炎"],["B","矽肺"],["C","肺水肿"],["D","支气管哮喘"]],"D","功能余气量是指平静呼吸末尚存留于肺内的气体量。支气管哮喘（D对）发作时，小气道痉挛收缩，肺泡内气体因气道变窄而排出减少，使功能余气量增加。肺炎（A错）和肺水肿（C错）时肺泡内大量渗入，使肺泡内空间下降，功能余气量减少。矽肺（B错）时肺泡大量破坏，同时伴肺实质实变，功能余气量减少。","","N"],["2018-N6",4,"第4节 呼吸运动的调节","CO₂、H⁺、O₂对呼吸运动的调节",2018,6,"A","","下列关于CO₂刺激呼吸运动的描述，正确的是",[["A","中枢化学感受器的反应较快"],["B","外周化学感受器较易发生适应"],["C","刺激中枢和外周化学感受器的效应等同"],["D","一定水平的PCO₂对维持正常呼吸是必需的"]],"D","一定水平的PCO₂可以刺激呼吸运动，对维持正常呼吸是必需的（D对）。CO₂刺激呼吸运动通过刺激中枢化学感受器和外周化学感受器两条途径，其中刺激中枢化学感受器的效应更为明显（C错）。但因中枢化学感受器的反应较慢（A错），所以当动脉血PCO₂突然增高时，外周化学感受器在引起快速呼吸反应中具有重要作用。另外，中枢化学感受器较易发生适应（B错），当中枢化学感受器对CO₂发生适应后，外周化学感受器的作用就显得很重要。","","N"],["2018-N7",5,"第3节 胃内消化","胃的运动形式",2018,7,"A","","促胃液素延缓胃排空的原因是",[["A","抑制迷走-迷走反射"],["B","抑制壁内神经丛反射"],["C","增强幽门括约肌收缩"],["D","增强肠-胃反射"]],"C","食物由胃排入十二指肠的过程称为胃排空。胃排空的控制包括胃内因素和十二指肠内因素。①胃内因素促进胃排空：食物对胃的扩张刺激可通过迷走-迷走反射（A错）和壁内神经丛局部反射（B错）引起胃运动的加强，促进胃排空；促胃液素既能促进胃的运动，也能通过增强幽门括约肌的收缩抑制胃排空（C对），总的效应是抑制延缓胃排空。②十二指肠内因素抑制胃排空：食物对十二指肠的扩张刺激则可通过肠-胃反射（D错）抑制胃的运动，抑制胃排空。","","N"],["2018-N8",5,"第6节 大肠的功能","大肠内细菌的消化作用",2018,8,"A","","大肠内细菌利用简单物质合成的维生素是",[["A","维生素A和D"],["B","维生素B族和K"],["C","维生素C和E"],["D","维生素PP和叶酸"]],"B","大肠内细菌利用简单物质合成的维生素有维生素B和维生素K（B对），这些维生素可被人体吸收利用。维生素C、维生素PP、叶酸主要依赖食物提供（CD错）。维生素D主要靠人体自身合成，或通过食用一些富含维生素D的食物来获得（A错）。","","N"],["2018-N9",6,"第1节 能量代谢","基础代谢",2018,9,"A","","测得某人在基础状态下的耗氧量为14L/h，体表面积为1.6m2，其BMR约是",[["A","150 kJ/(m²·h)"],["B","167 kJ/(m²·h)"],["C","177 kJ/(m²·h)"],["D","186 kJ/(m²·h)"]],"C","BMR即基础代谢率（Basal Metabolism Rate），是指在基础状态下单位时间内的能量代谢，测定BMR时通常采用简化的能量代谢测定法，即将非蛋白呼吸商视为0.82，与之相对应的氧热价为20.20kJ/L，因此，只需测定受试者在基础状态下一定时间内的耗氧量和体表面积，即可计算出基础代谢率：20.20kJ/L×14L/h÷1.6m²=176.75kJ/（m²•h），接近177kJ/（m²•h）（C对）。","","N"],["2018-N10",7,"第1节 肾的功能解剖和肾血流量","滤过膜的构成",2018,10,"A","","实验中发现，较难通过肾小球滤过膜的物质是",[["A","带正电荷的右旋糖酐分子"],["B","带负电荷的右旋糖酐分子"],["C","电中性的右旋糖酐分子"],["D","带负电荷的无机离子"]],"B","肾小球滤过膜由毛细血管内皮细胞、毛细血管下基膜和肾小囊脏层足细胞的足突构成，三层结构均含直径不同的小孔供不同大小的溶质分子滤过，且均含负电荷，对带负电荷的溶质分子有一定的阻碍作用。一般无机离子（D错）等小分子溶质可自由通过肾小球滤过膜。右旋糖酐分子（多聚葡萄糖）分量较大，通过难度与其所带电荷有关，电中性（C错）和带正电荷（A错）的右旋糖酐分子较易通过，带负电荷的右旋糖酐分子（B对）则较难通过。","","N"],["2018-N11",7,"第5节 尿生成的调节","醛固酮的功能",2018,11,"A","","在肾远曲小管和集合管上皮细胞内，不属于醛固酮诱导蛋白的物质是",[["A","管腔膜上的钠通道"],["B","管腔膜上的水孔蛋白"],["C","基底侧膜上的钠泵"],["D","线粒体中合成ATP的酶"]],"B","醛固酮可作用于肾远曲小管和集合管上皮细胞，增加K⁺的排泄和增加Na⁺、水的重吸收。醛固酮进入远曲小管和集合管上皮细胞胞质后，与胞质内受体结合，形成激素-受体复合物。激素-受体复合物穿过核膜进入核内，通过基因调节机制，生成多种醛固酮诱导蛋白，主要包括管腔膜上的钠通道（A对）、基底侧膜上的钠泵（C对）和线粒体中合成ATP的酶（D对）。管腔膜上的水孔蛋白（B错，为本题正确答案）接受血管升压素调节，可镶嵌到上皮细胞的顶端膜中，形成水通道（十版生理学P231）。","","N"],["2018-N12",8,"第3节 视觉","晶状体变凸",2018,12,"A","","与眼视近物所作的调节无关的反射活动是",[["A","双眼会聚"],["B","晶状体变凸"],["C","瞳孔对光反射"],["D","瞳孔调节反射"]],"C","眼视近物时，将发生一系列称之为‘眼的近反射’的调节，包括双眼会聚（视轴会聚）（A对）、晶状体变凸（B对）和瞳孔调节反射（视近物时可反射性引起双眼瞳孔缩小）（D对）。瞳孔对光反射是指瞳孔在强光照射时缩小而在光线变弱时散大的反射，这是眼的一种重要的适应功能，而与视近物无关（C错，为本题正确答案），其意义在于调节进入眼内的光量。","","N"],["2018-N13",9,"第1节 神经系统功能活动的基本原理","影响递质释放的因素",2018,13,"A","","能阻碍突触前末梢释放递质而影响突触传递的物质是",[["A","α-银环蛇毒"],["B","有机磷酸酯"],["C","肉毒梭菌毒素"],["D","三环类抗抑郁药"]],"C","影响突触传递的因素包括影响递质释放的因素、影响已释放递质清除的因素和影响受体的因素三大类。本题中，肉毒梭菌毒素（C对）属于影响递质释放的因素，能阻碍突触前末梢释放递质而影响突触传递。有机磷酸酯（B错）和三环类抗抑郁药（D错）属于影响已释放递质清除的因素，α-银环毒素（A错）属于影响受体的因素。","","N"],["2018-N14",10,"第1节 内分泌与激素","激素受体",2018,14,"A","","甲状腺激素作用于靶细胞而产生生物效应的受体属于",[["A","核受体"],["B","G蛋白耦联受体"],["C","酪氨酸激酶受体"],["D","离子通道型受体"]],"A","甲状腺激素作用于靶细胞而产生生物学效应的受体属于核受体（A对）。作用于G蛋白耦联受体（B错）的激素主要包括各种‘促’激素和儿茶酚胺、血管升压素等。作用于酪氨酸激酶受体（C错）的激素主要包括胰岛素、生长激素和各种生长因子等。离子通道型受体（D错）的典型代表是骨骼肌终板膜中的ACh受体阳离子通道（十版生理学P16，P43）。","","N"],["2018-N15",10,"第4节 甲状旁腺、维生素D与甲状腺C细胞内分泌","1,25-二羟维生素D₃的生理作用",2018,15,"A","","1，25-二羟维生素D₃对钙、磷调节的效应是",[["A","升高血钙，升高血磷"],["B","升高血钙，降低血磷"],["C","降低血钙，升高血磷"],["D","降低血钙，降低血磷"]],"A","1，25-二羟维生素D₃可促进小肠吸收钙磷，同时促进破骨细胞对骨基质的溶解和成骨细胞产生碱性磷酸酶和纤溶酶原激活物等，促进骨钙磷入血，另外还可以促进肾小管对钙磷的重吸收，故它对钙磷调节的效应是升高血钙和血磷（A对）。升高血钙，降低血磷（B错）为甲状旁腺激素的生物作用。降低血钙，降低血磷（D错）为降钙素的生物作用。","","N"],["2018-N16",11,"第1节 男性生殖功能及其调节","下丘脑－垂体－睾丸轴的调节",2018,16,"A","","下列关于睾酮对下丘脑-腺垂体反馈调节的描述，错误的是",[["A","抑制GnRH的分泌"],["B","抑制FSH的分泌"],["C","抑制LH的分泌"],["D","降低腺垂体对GnRH的反应性"]],"B","当血中睾酮浓度达到一定水平后，可通过负反馈机制直接抑制腺垂体分泌LH（黄体生成素）（C对），同时也可通过降低腺垂体对 GnRH 的反应性（D对）等机制抑制下丘脑分泌GnRH（促性腺激素释放激素）（A对），进而间接抑制腺垂体FSH （卵泡刺激素）（B对）和LH的分泌。睾酮通过抑制GnRH间接抑制FSH为九版教材最新观点，按照九版教材本题应无正确答案，但八版及更早版本教材认为睾酮对 FSH的分泌无影响（B错，为本题正确答案），故本题给出的参考答案为B。","","N"],["2018-N116",3,"第4节 心血管活动的调节","血管紧张素家族主要成员的生理作用",2018,116,"B","","属于血管紧张素转换酶抑制剂的是",[["A","维拉帕米"],["B","美托洛尔"],["C","卡托普利"],["D","氯沙坦"]],"C","属于血管紧张素转化酶抑制剂的是卡托普利（C对）。维拉帕米（A错）为钙通道阻滞剂。美托洛尔（B错）为β受体拮抗剂。氯沙坦（D错）为血管紧张素Ⅱ受体拮抗剂。","","N"],["2018-N117",3,"第4节 心血管活动的调节","血管紧张素家族主要成员的生理作用",2018,117,"B","","属于血管紧张素Ⅱ受体拮抗剂的是",[["A","维拉帕米"],["B","美托洛尔"],["C","卡托普利"],["D","氯沙坦"]],"D","属于血管紧张素Ⅱ受体拮抗剂的是氯沙坦（D对）。维拉帕米（A错）为钙通道阻滞剂。美托洛尔（B错）为β受体拮抗剂。卡托普利（C错）为血管紧张素转化酶抑制剂。","","N"],["2018-N118",9,"第3节 神经系统对躯体运动的调控","帕金森病",2018,118,"B","","能改善帕金森病运动减少症状的药物是",[["A","利血平"],["B","哌唑嗪"],["C","育亨宾"],["D","左旋多巴"]],"D","能改善帕金森病运动减少症状的药物是左旋多巴（D对）。利血平（A错）用于亨廷顿舞蹈病的治疗（十版生理学P315）。哌唑嗪（B错）和育亨宾（C错）分别为α₁和α₂受体拮抗药（十版生理学P297），前者可用于轻、中度高血压的治疗，后者多用于性功能勃起障碍的治疗。","","N"],["2018-N119",9,"第3节 神经系统对躯体运动的调控","亨廷顿病",2018,119,"B","","能改善舞蹈病运动增多症状的药物是",[["A","利血平"],["B","哌唑嗪"],["C","育亨宾"],["D","左旋多巴"]],"A","能改善舞蹈病运动增多症状的药物是利血平（A对）。哌唑嗪（B错）和育亨宾（C错）分别为α₁和α₂受体拮抗药（十版生理学P297），前者可用于轻、中度高血压的治疗，后者多用于性功能勃起障碍的治疗。左旋多巴（D错）用于帕金森病的治疗（十版生理学P315）。","","N"],["2018-N136",1,"第3节 细胞的电活动","钠泵的生电作用",2018,136,"X","","影响细胞静息电位的主要因素有",[["A","K⁺平衡电位"],["B","膜两侧［K⁺］差"],["C","Na⁺平衡电位"],["D","膜对K⁺和Na⁺的相对通透性"]],"ABD","静息电位主要是由于安静时细胞膜K⁺通透性较大，K⁺顺浓度梯度由细胞内向细胞外扩散而形成的。当细胞外K⁺浓度升高（如高血钾）时，K⁺平衡电位减小，静息电位也相应减小，故K⁺的平衡电位（A对）和膜两侧K⁺的浓度差（B对）均能影响细胞静息电位。如果膜对K⁺的通透性增大，静息电位将增大（更趋向于K⁺的平衡电位）；反之，膜对Na⁺的通透性增大，则静息电位减小（更趋向于Na⁺的平衡电位），故膜对K⁺和Na⁺的相对通透性（D对）也能影响细胞静息电位。Na⁺平衡电位（C错）主要影响细胞的动作电位。","","N"],["2018-N137",2,"第3节 生理性止血","内源性凝血途径",2018,137,"X","","血友病的产生原因有",[["A","缺乏维生素K"],["B","缺乏凝血因子Ⅴ"],["C","缺乏凝血因子Ⅷ"],["D","缺乏凝血因子Ⅸ"]],"CD","血友病的发病因素是缺乏凝血因子Ⅷ（C对）（血友病A）或凝血因子Ⅸ（D对）（血友病B）。维生素K（A错）可作为辅因子参与凝血因子Ⅱ、Ⅶ、Ⅸ、Ⅹ合成（十版生理学P68），凝血因子Ⅴ（B错）可作为辅因子促进凝血酶原的激活（十版生理学P68），二者缺乏可引起凝血障碍，但均与血友病发病无关。","","N"],["2018-N138",3,"第5节 器官循环","冠脉循环的生理特点",2018,138,"X","","在生理状态下，能使冠脉血流量增多的因素有",[["A","加快心率"],["B","增加外周阻力"],["C","降低动脉血压"],["D","增强心肌代谢活动"]],"BD","动脉舒张压的高低和心舒期的长短是影响冠脉血流（CBF）的重要因素。当体循环外周阻力增大时，动脉舒张压升高，冠脉血流将增加（B对）；而当心率加快时，由于心舒期明显缩短，冠脉血流则减少（A错）。降低动脉血压（C错），冠状动脉压随之降低，冠脉血流减少。增加心肌代谢活动（D对），其代谢产物如腺苷、乳酸、H⁺等可以舒张冠脉，冠脉血流增加。","","N"],["2018-N139",6,"第2节 体温及其调节","体温调节过程——体温调定点学说",2018,139,"X","","支持体温调定点学说的现象和依据有",[["A","高热高湿环境下中暑的发生"],["B","发热初期出现寒战等产热反应"],["C","发热恢复期发生出汗等散热反应"],["D","体温改变时下丘脑温度敏感神经元电活动改变"]],"BCD","体温调定点学说将体核体温作为控制变量，其变化信息反馈到体温调节中枢，与中枢的调定点水平进行比较，体核体温与此参考温之间的差值即为误差信号，机体据此调节产热活动和散热活动，使体温向着接近于调定点的方向变化。体温改变时，下丘脑热敏神经元和冷敏神经元随温度的变化放电频率发生改变（D对）。发热初期体温低于新的调定点水平，机体皮肤血管收缩，减少散热，随即出现寒战等产热反应（B对），使产热和散热活动在新的调定点水平达到平衡。发热恢复期体温高于新的调定点，机体皮肤血管舒张，增加散热，通过出汗等散热反应（C对），使产热和散热活动在新的调定点水平达到平衡。高热高湿环境下中暑的发生（A错），是由于机体的散热能力不足或者调节中枢功能障碍所导致，为非调节性体温升高，与体温调定点学说无关。","","N"],["2018-N140",8,"第1节 感觉概述","感受器的换能作用",2018,140,"X","","痛觉感受器所具有的生理特性包括",[["A","适宜刺激"],["B","换能作用"],["C","编码功能"],["D","快适应现象"]],"BC","感受器是指生物体内一些感受体内外环境变化的结构或装置。痛觉感受器有感受器的一般生理特性，包括换能作用（B对）和编码功能（C对），但痛觉感受器不易发生适应，属于慢适应感受器（D错），且不存在适宜刺激（A错），任何形式（机械、温度、化学）的刺激只要达到对机体伤害的程度均可使痛觉感受器兴奋。","","N"],["2018-N141",9,"第3节 神经系统对躯体运动的调控","脑干网状结构抑制区和易化区",2018,141,"X","","易化肌紧张的中枢部位有",[["A","前庭核"],["B","纹状体"],["C","小脑半球中间部"],["D","大脑皮层运动区"]],"AC","电刺激脑干网状结构的不同区域，可观察到网状结构中存在抑制或加强肌紧张（和肌肉运动）的区域，分别称为抑制区和易化区。脑干网状结构之外的一些区域可间接通过脑干网状结构的抑制区和易化区对肌紧张进行调节。如刺激大脑皮层运动区（D错）、纹状体（B错）、小脑前叶蚓部等部位，可抑制肌紧张；刺激前庭核（A对）、小脑前叶两侧部和后叶中间部（C对）等部位，可易化肌紧张。","","N"],["2019-N1",0,"第4节 机体的内环境、稳态和生物节律","内环境的稳态",2019,1,"A","","下列对生理学中稳态概念的描述，错误的是",[["A","限于内环境理化性质的稳定状态"],["B","内环境理化性质可在一定范围内波动"],["C","稳态的维持是机体自我调节的结果"],["D","稳态是机体维持生命活动的必要条件"]],"A","在生理学中目前关于稳态的概念已被大大扩展，不再局限于内环境的理化性质，而是扩大到泛指体内从细胞和分子水平、器官和系统水平到整体水平的各种生理功能活动在神经和体液等因素调节下保持相对稳定的状态（A错，为本题正确答案）。内环境的稳态揭示了生命活动的正常进行有赖于内环境相对稳定的内在规律，是维持机体生命活动的必要条件（D对）。内环境的稳态不是静止不变的固定状态，而是可在一定范围内波动（B对），是各种理化因素在各种生理活动的调节下达到动态平衡的一种相对恒定的状态。稳态的维持是机体自我调节的结果（C对）。","","N"],["2019-N2",1,"第4节 肌细胞的收缩","兴奋-收缩耦联的基本步骤",2019,2,"A","","动作电位引起骨骼肌收缩的关键因素是",[["A","肌球蛋白轻链的磷酸化"],["B","横管膜上T型钙通道激活"],["C","胞质内Ca²⁺浓度的瞬时增高"],["D","肌质网膜上ryanodine受体激活"]],"C","动作电位引起骨骼肌收缩的机制（十版生理学P47）：动作电位→横管膜上的L型钙通道激活（B错）→肌质网上ryanodine受体激活（D）→胞质内Ca²⁺浓度的瞬时增高（C对）→骨骼肌收缩。肌球蛋白轻链的磷酸化与平滑肌收缩有关（十版生理学P52）（A错）。本题官方给出的参考答案为C，但判定D选项错存在争议：肌质网上ryanodine受体（钙释放通道）激活（D）是肌质网终池内的Ca²⁺被大量释放，引起胞质内Ca²⁺浓度瞬时增高（C）的原因，是动作电位引起骨骼肌收缩过程中的关键步骤。题干若将“关键因素”改成“直接因素”则无争议。","","N"],["2019-N3",2,"第3节 生理性止血","生理性抗凝物质",2019,3,"A","","临床上在体内和体外均可用于抗凝血的物质是",[["A","肝素"],["B","草酸钾"],["C","华法林"],["D","前列环素"]],"A","肝素（A对）在体内和体外均可发挥抗凝作用，肝素主要通过增强抗凝血酶的活性而发挥间接抗凝作用。此外，肝素还可促进结合于血管内皮细胞表面的TFPI（组织因子途径抑制物） 释放，使血浆TFPI 水平升高，故肝素在体内的抗凝作用强于体外。草酸钾（B错）、枸橼酸钠、草酸铵为体外抗凝剂，可与Ca²⁺结合而除去血浆中的Ca²⁺从而起到抗凝作用。华法林（C错）为维生素K 的结构类似物，可作为维生素K的受体拮抗剂，抑制FⅡ、FⅦ、FⅨ、FⅩ等维生素K依赖性凝血因子的合成，因此在体内具有抗凝作用，但在体外不具有抗凝作用，因为体外血液不存在凝血因子的合成过程。前列环素（D错）由血管内皮细胞合成释放，可通过抑制血小板的聚集而参与体内抗凝血过程。","","N"],["2019-N4",3,"第4节 心血管活动的调节","血管紧张素家族主要成员的生理作用",2019,4,"A","","关于血管紧张素Ⅱ升高血压的机制，下列描述中错误的是",[["A","直接使全身微动脉收缩"],["B","刺激肾上腺髓质激素分泌"],["C","加强交感缩血管中枢的紧张性"],["D","促进交感神经末梢释放去甲肾上腺素"]],"B","血管紧张素Ⅱ（AngⅡ）是一种强力的缩血管物质，可以通过外周和中枢的不同机制使血管阻力增大，血压升高：①缩血管作用。血管紧张素Ⅱ可直接使全身微动脉收缩（A对），血压升高；也能使静脉收缩，回心血量增加。②促进交感神经末梢释放递质。血管紧张素Ⅱ可作用于交感缩血管纤维末梢的突触前血管紧张素受体（AT受体），通过突触前调制作用促进其释放去甲肾上腺素（D对）。③血管紧张素Ⅱ可作用于中枢神经系统的一些神经元，使中枢对压力感受性反射的敏感性降低，交感缩血管中枢紧张加强（C对）；另血管紧张素Ⅱ还促进神经垂体释放血管升压素和缩宫素，及增强促肾上腺皮质激素释放激素的作用（B错，为本题正确答案）等。","","N"],["2019-N5",4,"第3节 气体在血液中的运输","CO₂的运输形式",2019,5,"A","","CO₂在肺部排出比率最高的血液运输形式是",[["A","氨基碳酰血浆蛋白"],["B","物理溶解的CO₂"],["C","氨基甲酰血红蛋白"],["D","氨基甲酰血浆蛋白"]],"C","CO₂以物理溶解（5%）和化学形式（95%）两种形式在血液内运输，化学结合的形式主要是碳酸氢盐（88%）和氨基甲酰血红蛋白（HHbNHCOOH或HbCO₂）（7%）。由八版生理学P175 表5-4可知氨基甲酰血红蛋白虽然仅占CO₂总运输量的7%左右，却占肺部CO₂排出量的17.5%，其排出比率（17.5%/7%）（C对）高于物理溶解的CO₂（7.5%/5%）（B错）及另外一种化学结合的形式碳酸氢盐（75%/88%）。","","N"],["2019-N6",5,"第2节 口腔内消化和吞咽","食管期",2019,6,"A","","下列关于食管下括约肌的叙述，错误的是",[["A","存在明显的解剖学结构"],["B","使静息时食管下段腔内压高于胃内压"],["C","食管蠕动波到达时张力下降"],["D","食物通过后张力增高"]],"A","食管下括约肌（LES）并不是解剖学上的括约肌（A错， 为本题正确答案），而是食管下端近胃贲门处一段长3～5cm的高压区，在静息状态下，此处的压力比胃内压高5～10mmHg（B对），起类似生理性括约肌的作用。当食物进入食管后，刺激食管壁上的机械感受器，反射性引起食管下括约肌舒张（张力下降）（C对），允许食物进入胃内，食物进入胃后，食管下括约肌收缩，恢复其静息时的张力（D对），防止胃内容物反流入食管。","","N"],["2019-N7",5,"第4节 小肠内消化","胆汁的作用",2019,7,"A","","胆汁促进脂肪消化和吸收的主要原因是",[["A","含有丰富的脂肪酶"],["B","含有大量的HCO₃⁻"],["C","胆盐的肠-肝循环"],["D","胆盐对脂肪的乳化作用"]],"D","胆汁主要是由肝细胞分泌的，胆汁中最重要的成分是胆盐，胆盐是胆汁酸与甘氨酸或牛磺酸结合形成的钠盐或钾盐，是胆汁参与消化和吸收的主要成分：胆汁促进脂肪消化和吸收的主要原因是胆盐对脂肪的乳化作用（D对），胆盐可以降低脂肪的表面张力，使脂肪乳化成微滴分散在水性的肠液中，从而增加胰脂肪酶的作用面积，促进脂肪的分解消化，同时胆盐可与脂肪酸、甘油一酯、胆固醇等结合形成水溶性复合物，运载脂肪分解产物到肠黏膜表面，促进脂肪消化产物的吸收。","","N"],["2019-N8",6,"第1节 能量代谢","能量的利用",2019,8,"A","","机体各种功能活动所消耗的能量中，最终不能转化为体热的是",[["A","兴奋在神经纤维上传导"],["B","肌肉收缩对外界物体做功"],["C","细胞合成各种功能蛋白质"],["D","内、外分泌腺体的分泌活动"]],"B","机体各种功能活动所消耗的能量中，除肌肉收缩对外界物体做功会转化成一部分机械能外（B对），绝大部分最终都将转化为体热，用于体温的维持。","","N"],["2019-N9",7,"第2节 肾小球的滤过功能","囊内压",2019,9,"A","","下列能使肾小球滤过率增高的因素是",[["A","血浆胶体渗透压升高"],["B","血浆晶体渗透压升高"],["C","肾小囊内静水压降低"],["D","滤过平衡移向入球端"]],"C","肾小球滤过率（GFR）是单位时间内（每分钟）两肾生成的超滤液量，其影响因素包括肾小球毛细血管滤过系数、有效滤过压和肾血浆流量，与三者均成正比关系。其中有效滤过压＝（肾小球毛细血管静水压＋肾小囊内液胶体渗透压）－（血浆胶体渗透压＋肾小囊内静水压），故肾小囊内静水压降低时（C对），有效滤过压升高，使肾小球滤过率也增高。血浆胶体渗透压升高时（A错），有效滤过压和肾小球滤过率均降低。血浆内的晶体物质能够自由通过肾小球的滤过膜，对肾小球的有效滤过压无影响，故血浆晶体渗透压不影响肾小球滤过率（B错）。当滤过阻力等于滤过动力时，有效滤过压降为零，称为滤过平衡，出现滤过平衡处距入球小动脉端越近，肾小球滤过率越低，反之，滤过平衡处距入球小动脉端越远，肾小球滤过率越高，故滤过平衡移向入球端（D错）将会降低肾小球滤过率（十版生理学P218）。","","N"],["2019-N10",7,"第3节 肾小管和集合管的物质转运功能","髓袢",2019,10,"A","","对NaCl不易通透而对水易通透的肾小管段是",[["A","髓袢降支细段"],["B","髓袢升支细段"],["C","髓袢升支粗段"],["D","远曲小管"]],"A","髓袢降支细段的上皮细胞较薄，线粒体数目少，ATP生成少，对溶质的通透性很低（三版八年制生理学P352），但肾小管上皮细胞的顶端膜和基底外侧膜存在大量AQP1，对水是通透的，促进水的重吸收，使水能迅速地进入组织液，小管液渗透浓度压不断地增加，故对NaCl不易通透而对水易通透的肾小管是髓袢降支细段（记忆为“降水”，降支通透水）（A对）。髓袢升支细段（B错）、髓袢升支粗段（C错）和远曲小管（D错）均对NaCl易通透（通过不同的机制）而对水不易通透，故小管液依次经过髓袢升支细段、髓袢升支粗段和远曲小管时，小管液渗透浓度逐渐降低。","","N"],["2019-N11",8,"第5节 平衡感觉","半规管",2019,11,"A","","人体进行加速度运动时出现眼震颤，感受刺激的器官是",[["A","耳蜗"],["B","球囊"],["C","椭圆囊"],["D","半规管"]],"D","眼震颤是指身体在旋转变速运动时出现的眼球不自主的节律性运动，是前庭反应中最特殊的一种。在生理情况下，绕身体纵轴旋转等运动刺激两侧水平半规管可引起水平方向的眼震颤，侧身翻转等运动刺激上半规管可引起垂直方向的眼震颤，前、后翻滚等运动刺激后半规管可引起旋转性眼震颤，故人体进行加速度运动时出现眼震颤，感受刺激的器官是半规管（D对）。椭圆囊（C错）和球囊（B错）也可感受加速度运动（半规管感受的是正、负角加速度，椭圆囊和球囊感受的是直线加速度运动），接受刺激后，通过不同毛细胞的综合活动，使机体在各种姿势和运动情况下保持身体的平衡。","","N"],["2019-N12",9,"第1节 神经系统功能活动的基本原理","突触后神经元动作电位的产生",2019,12,"A","","神经元兴奋时，首先产生动作电位的部位是",[["A","树突"],["B","胞体"],["C","轴突始段"],["D","轴突末梢"]],"C","通过突触传递，在一个神经元的树突和胞体膜上可同时或几乎同时产生多个局部电位，这些局部电位以电紧张的方式传播或整合，在传到轴突始段膜时（电压门控钠通道在该段轴突膜上密度较大，而在胞体和树突膜上则很少分布）（C对），若达到或超过阈电位，即可爆发动作电位。胞体（B错）和树突（A错）主要负责接受和整合信息。轴突末梢（D错）则负责向效应细胞或其他神经元传递信息。","","N"],["2019-N13",9,"第4节 神经系统对内脏活动、本能行为和情绪的调节","副交感神经系统的功能",2019,13,"A","","副交感神经兴奋时，可引起的生理反应是",[["A","瞳孔散大"],["B","汗腺分泌"],["C","糖原分解"],["D","胰岛素分泌"]],"D","副交感神经兴奋时释放乙酰胆碱，可直接作用于β细胞膜中的M受体，刺激胰岛素分泌，也可通过引起胃肠激素分泌增多而间接促进胰岛素分泌（D对）。使瞳孔散大的（瞳孔开大肌/虹膜辐射状肌收缩扩瞳）是交感神经，而不是副交感神经（A错）。汗腺虽然存在M型胆碱能受体，也接受乙酰胆碱（ACh）支配，但此处释放ACh的是交感神经，而不是副交感神经（B错）。糖原的分解主要受胰高血糖素（肝糖原）、肾上腺素（肌糖原）（十版生物化学与分子生物学 P127）和交感神经的调节，而不受副交感神经的调节，副交感神经主要调节糖原的合成（C错）。","","N"],["2019-N14",10,"第2节 下丘脑-垂体及松果体内分泌","调节新陈代谢",2019,14,"A","","生长激素分泌过多可产生的代谢异常是",[["A","负氮平衡"],["B","低钙血症"],["C","垂体性糖尿"],["D","高胆固醇血症"]],"C","生长激素能调节糖、脂肪、蛋白质等物质代谢。GH 可促进蛋白质代谢，总效应是合成大于分解，特别是促进肝外组织合成蛋白质，如促进氨基酸进入肌肉细胞利用，减少尿氮，呈正氮平衡（P367）（A错）。生长激素对脂肪的代谢调节表现为促进脂肪降解，为脂解激素（D错）。生长激素对糖代谢的影响多继发于对脂肪的动员，血中游离脂肪酸增加可抑制骨骼肌与脂肪组织摄取葡萄糖，减少葡萄糖消耗，升高血糖（“抗胰岛素”效应），生长激素也通过降低外周组织对胰岛素的敏感性升高血糖，也可增加和维持骨骼肌和心肌的糖原储备，但分泌过多时，会导致垂体性糖尿（C对）。生长激素可调节钙磷代谢，促进血钙升高（B错），但其作用较弱。","","N"],["2019-N15",10,"第3节 甲状腺内分泌","促进生长发育",2019,15,"A","","在胚胎期对脑发育最为重要的激素是",[["A","性激素"],["B","胰岛素"],["C","生长激素"],["D","甲状腺激素"]],"D","在胚胎期对脑发育最为重要的激素是甲状腺激素（TH）（D对），在胚胎期，TH能促进神经元的增殖和分化以及突触的形成；促进胶质细胞的生长和髓鞘的形成，诱导神经生长因子和某些酶的合成，促进神经元骨架的发育等。胚胎期及幼儿期缺乏甲状腺激素，除出现甲状腺功能低下的一般症状外，可导致不可逆的神经系统发育障碍和骨骼的生长发育延迟或停滞，出现明显的智力发育迟缓、身材短小、牙齿发育不全等症状，称为克汀病（或称呆小症）。生长激素（十版生理学P349）（C错）几乎对所有组织和器官的生长都有促进作用，尤其是对骨骼、肌肉和内脏器官的作用最为显著。性激素（十版生理学P385、P389）（A错）可促进青春期骨骼生长及骨骺愈合。胰岛素（B错）可以与生长激素协同作用（十版生理学P375），促进生长发育的过程。","","N"],["2019-N16",10,"第5节 肾上腺内分泌","应激性调节",2019,16,"A","","机体在受到有害刺激时，参与应激反应最主要的系统是",[["A","交感-肾上腺髓质系统"],["B","下丘脑-神经垂体系统"],["C","肾素-血管紧张素-醛固酮系统"],["D","下丘脑-腺垂体-肾上腺皮质系统"]],"D","应激反应是指机体遭遇内、外环境和社会、心理等刺激达到一定强度时，下丘脑-腺垂体-肾上腺皮质系统被激活（D对），促肾上腺皮质激素释放激素（CRH）、促肾上腺皮质激素（ACTH）和糖皮质激素（GC）分泌增加，出现的非特异性的适应反应，以提高机体对有害刺激的耐受能力。交感-肾上腺髓质系统（A错）参与的是机体的应急反应（十版生理学P372），当机体遇到紧急情况时，该系统活动增加。下丘脑-神经垂体系统（B错） 主要调节神经垂体分泌血管升压素（抗利尿激素）和缩宫素（十版生理学P354），前者是调节机体水平衡的重要激素之一，对保持体液和维持动脉血压有重要意义，后者的主要作用是在女性分娩时刺激子宫平滑肌收缩和在哺乳期促进乳腺排乳。肾素-血管紧张素-醛固酮系统（十版生理学P232）（C错）是人体重要的体液调节系统，对血压的调节及心血管系统的正常发育、心血管功能稳态、电解质和体液平衡的维持均有重要作用。","","N"],["2019-N116",1,"第3节 细胞的电活动","钠泵的生电作用",2019,116,"B","","增加神经细胞外K⁺浓度，神经细胞跨膜电位的改变",[["A","静息电位减小，动作电位幅度减小"],["B","静息电位增大，动作电位幅度增大"],["C","静息电位减小，动作电位幅度增大"],["D","静息电位增大，动作电位幅度减小"]],"A","增加神经细胞外K⁺浓度，细胞内K⁺与细胞外K⁺浓度差减小，静息状态时细胞内K⁺外流减少，静息电位（绝对值）减小，静息电位减小则发生动作电位去极化时Na⁺内流减少（Na⁺内流驱动力减小），进而动作电位的超射值减小。动作电位幅度等于静息电位绝对值与超射值之和，在静息电位绝对值与超射值均减小的情况下，动作电位的幅度自然也减小（A对）。","","N"],["2019-N117",1,"第3节 细胞的电活动","动作电位期间膜离子通透性的变化",2019,117,"B","","增加细胞外液中Na⁺浓度后，神经细胞跨膜电位的改变是",[["A","静息电位减小，动作电位幅度减小"],["B","静息电位增大，动作电位幅度增大"],["C","静息电位减小，动作电位幅度增大"],["D","静息电位增大，动作电位幅度减小"]],"C","增加细胞外液中Na⁺浓度后，细胞外Na⁺与细胞内Na⁺浓度差增大，发生动作电位去极化时Na⁺内流增加，动作电位的超射值增加，在静息电位变化很小的情况下（实际为轻微减小，分析见后），动作电位幅度将增大（动作电位幅度=静息电位绝对值+动作电位超射值）（C对）。增加细胞外液中Na⁺浓度后，钠泵活动将受到抑制（以维持细胞内外的 Na⁺、K⁺浓度梯度），钠泵活动受抑制时，其生电效应减弱，静息电位减小。但钠泵的生电作用对静息电位形成的贡献十分有限（P34），因此静息电位只会轻微减小。此外，增加细胞外液中Na⁺浓度后，静息状态下进入细胞内的Na⁺可能轻微增加（静息状态下Na⁺通透性小，只可能轻微增加），内流的Na⁺可部分抵消K⁺外流所形成的膜内负电位，使静息电位轻微减小。","","N"],["2019-N118",3,"第3节 血管生理","血压",2019,118,"B","","在体循环中，血压降落最为显著的血管是",[["A","大、中动脉"],["B","小、微动脉"],["C","毛细血管"],["D","静脉系统"]],"B","在体循环中，在血液从主动脉流向心房的过程中，需要不断消耗能量以克服阻力，故血压逐渐降低。在各段血管中，血压降落的幅度与该段血管对血流阻力的大小成正比，而影响血流阻力的最主要因素为血管半径r（血流阻力与r的4次方成反比）（十版生理学P108）。在大、中动脉动脉段（A错），由于血管半径r较大，血压降落较小，到小、微动脉（B对）时，血管r半径明显减小，血流阻力增大，血压降落显著（尤其以微动脉段最为显著）。当血液经毛细血管到达微静脉时，血压也有较大降落，但降幅小于流经微动脉时（参见十版生理学P109 图4-22）（C错）。血液经静脉系统回流至腔静脉汇入右心房时，血压下降至接近0mmHg，但下降幅度较小（D错）。","","N"],["2019-N119",3,"第3节 血管生理","血管的功能性分类",2019,119,"B","","在体循环中，容纳血量最多的血管是",[["A","大、中动脉"],["B","小、微动脉"],["C","毛细血管"],["D","静脉系统"]],"D","人体内的血管按生理功能的不同可分为以下几类（P113-P114）：弹性贮器血管、分配血管、毛细血管前阻力血管、毛细血管前括约肌、交换血管、毛细血管后阻力血管、容量血管及短路血管。其中容量血管即为静脉系统，与同级动脉相比，静脉数量多、管壁薄、口径大、可扩张性大，故其容量大。在安静状态下，静脉系统可容纳60%～70%的循环血量（D对）。大动脉属于弹性贮器血管，作用是使心室的间断射血转化为血液在血管中的连续流动，同时使心动周期中血压的波动幅度减小；中动脉属于分配血管，作用是将心脏输出的血液输送到各器官组织（Ａ错）。小、微动脉属于毛细血管前阻力血管，其作用是控制器官、组织的血流阻力和血流量（Ｂ错），对动脉血压的维持有重要意义。毛细血管属于交换血管，是血液和组织液之间进行物质交换的主要场所（Ｃ错）。","","N"],["2019-N136",1,"第2节 细胞的信号转导","第二信使",2019,136,"X","","需要胞质内第二信使介导信号转导的受体有",[["A","离子通道型受体"],["B","G蛋白耦联受体"],["C","核受体"],["D","鸟苷酸环化酶受体"]],"BD","第二信使是指激素、神经递质、细胞因子等细胞外信使分子（第一信使）作用于膜受体后产生的细胞内信使分子（P27）。目前已知的第二信使包括cAMP、三磷酸肌醇（IP₃）、二酰甘油（DG）、环-磷酸鸟苷（cGMP）、Ca²⁺、花生四烯酸（AA）及其代谢产物等。G蛋白耦联受体（B对）是最经典的第二信使介导信号转导的受体，由G蛋白耦联受体所介导的细胞信号通路主要包括“G蛋白耦联受体-G蛋白-AC-cAMP-PKA”通路及“G蛋白耦联受体-G蛋白-PLC-IP₃-Ca²⁺和DG-PKC通路”。“G蛋白耦联受体-G蛋白-AC-cAMP-PKA”通路的第二信使分子为cAMP，因此该通路也称为cAMP 第二信使系统。“G蛋白耦联受体-G蛋白-PLC-IP₃-Ca²⁺和DG-PKC通路”的第二信使分子为IP₃和DG，因而该通路也称为IP₃和DG第二信使系统。鸟苷酸环化酶受体（D对）介导的信号转导中，也有第二信使分子的参与：鸟苷酸环化酶（GC）受体是一种胞外N末端为配体结合域而胞内C末端为GC活性结构域的单跨膜α螺旋分子。激活该受体的配体主要是心房钠尿肽（ANP）和脑钠尿肽（BNP）。当受体被配体激活后，即可通过其GC活性催化胞质中GTP生成cGMP，后者作为第二信使可进一步激活cGMP依赖性蛋白激酶G（PKG），而PKG则作为丝氨酸／苏氨酸蛋白激酶，再将底物蛋白磷酸化而实现信号转导。狭义上，离子通道型受体即经通道的易化扩散中的化学门控通道（P18，P25），是一类兼具通道和受体功能的膜蛋白，离子通道型受体与配体结合之后，离子通道开放，细胞膜对特定离子的通透性增加，从而引起细胞膜电位的改变，实现跨膜信号转导功能，这一信号转导过程无需第二信使参与（A错）。广义上，离子通道型受体还应包括电压门控通道和机械门控通道（P26），二者可接受电信号和机械信号，通过通道的开、闭和离子跨膜流动的变化把信号传递到细胞内部，心肌细胞T管膜上的L型Ca²⁺通道是一种电压门控通道，当心肌细胞发生动作电位时，T管膜的去极化可激活这种Ca²⁺通道，引起Ca²⁺内流，使肌浆Ca²⁺浓度升高；内流的Ca²⁺还作为第二信使（A），进一步激活肌浆网的Ca²⁺释放通道，引起肌浆Ca²⁺浓度的进一步升高，从而引发心肌细胞的收缩，这样就实现了由电信号（动作电位）引发的跨膜信号转导（三版八年制生理学P38）。核受体实质上是激素调控特定蛋白质转录的一大类转录调节因子（P30），能够直接与核内DNA结合调控转录过程，不需要第二信使参与（C错）。","","N"],["2019-N137",3,"第4节 心血管活动的调节","肾上腺素和去甲肾上腺素",2019,137,"X","","一般情况下，小剂量静脉注射肾上腺素时可出现的心血管效应有",[["A","肾血管舒张"],["B","心率加快"],["C","心肌收缩力增强"],["D","骨骼肌血管舒张"]],"BCD","肾上腺素可与α和β（包括β₁和β₂）两类受体结合。在心脏，肾上腺素与β₁受体结合后，可使心肌收缩力增强（C对）、心率加快（B对），产生正性变力和正性变时作用。在血管，肾上腺素的作用取决于血管平滑肌上α和β₂受体的分布情况：在皮肤、肾（A错）和胃肠道血管平滑肌上α受体在数量上占优势，肾上腺素能使这些器官的血管收缩。在骨骼肌（D对）和肝的血管上β₂受体占优势（但也分布有α受体），小剂量的肾上腺素常以兴奋β₂受体的效应为主，引起血管舒张，而大剂量时则因α受体也兴奋，故引起血管收缩。","","N"],["2019-N138",4,"第1节 肺通气","弹性阻力和顺应性",2019,138,"X","","在肺泡液-气界面存在适量的肺表面活性物质，其生理意义有",[["A","防止肺水肿的发生"],["B","防止肺气肿的发生"],["C","使吸气变得较省力"],["D","稳定肺泡内压力和容积"]],"ACD","正常情况下，肺泡表面存在一层活性物质（肺泡Ⅱ型上皮细胞合成和分泌的含脂质与蛋白质的混合物），其作用是降低肺泡-气界面的表面张力而使肺泡的回缩力减小，其重要的生理意义为：①提高肺的顺应性，可使肺泡表面张力降低达80%～90%，大大降低了吸气阻力，使吸气变得较省力（C对）。②维持肺泡内压力和容积，根据Laplace定律（十版生理学P141），肺泡的回缩力与肺泡半径成反比，即小肺泡的回缩力大，而大肺泡的回缩力小，但肺表面活性物质的存在，降低了小肺泡的回缩力（小肺泡分布的肺表面活性物质密度较大，降低了表面张力），从而避免了小肺泡萎陷关闭而大肺泡过度膨胀的情况，保持了大小肺泡容积和压力的稳定性（D对）。③防止肺水肿。由于肺表面活性物质可降低肺泡表面张力，减小肺泡回缩力，减弱表面张力对肺毛细血管血浆和肺组织间液的“抽吸”作用，阻止液体渗入肺泡，从而防止肺水肿的发生（A对）。肺气肿是指终末细支气管远端的气道弹性减退，过度膨胀、充气和肺容积增大或同时伴有气道壁破坏的病理状态，与肺表面活性物质无关（B错）。","","N"],["2019-N139",5,"第1节 消化生理概述","APUD细胞和胃肠激素",2019,139,"X","","下列有关胃肠激素的叙述，正确的有",[["A","可调节消化功能活动"],["B","可促进消化道黏膜生长"],["C","分泌细胞分布于胃、肠、胰"],["D","有内分泌和旁分泌等多种分泌方式"]],"ABCD","由胃肠道黏膜的内分泌细胞合成和释放的具有生物活性的化学物质统称为胃肠激素，其分泌细胞分布于胃、肠、胰（C对），有内分泌、旁分泌、神经内分泌、管腔分泌、自分泌等多种分泌方式（D对），胃肠激素的生理作用极为广泛，但主要在于调节消化器官的功能，总体上讲有以下三个方面：①调节消化腺分泌和消化道运动（A对）：这是胃肠激素的主要作用，例如，促胃液素能促进胃液分泌和胃运动；而促胰液素和抑胃肽则可抑制胃液分泌及胃运动。②调节其他激素的释放：例如，在血糖浓度升高时，抑胃肽可刺激胰岛素的释放，这对防止餐后血糖升高具有重要的意义；此外，生长抑素、胰多肽、促胃液素释放肽、血管活性肠肽等对生长激素、胰岛素、促胃液素的释放也有调节作用。③营养作用：有些胃肠激素可促进消化系统组织的生长，例如，促胃液素和缩胆囊素分别能促进胃黏膜上皮和胰腺外分泌部组织的生长（B对）。","","N"],["2019-N140",7,"第4节 尿液的浓缩和稀释","尿液的浓缩机制",2019,140,"X","","肾脏对尿液进行浓缩所需要的条件有",[["A","肾交感神经兴奋"],["B","肾髓质间质高渗"],["C","血管升压素的释放"],["D","小管液中高溶质浓度"]],"BC","尿液的浓缩要求小管液中的水被重吸收（溶质仍留在小管内），故肾脏对尿液进行浓缩所必须需要的条件有：①肾小管特别是集合管对水的通透性，抗利尿激素（血管升压素）是决定集合管上皮细胞对水通透性的关键激素，其分泌量增加，集合管上皮细胞对水通透性增加，水的重吸收量增加，小管液被浓缩（C对）。②肾脏髓质组织间液形成高渗透浓度梯度（B对），进一步促进水的重吸收。小管液中高溶质浓度（D错）是尿液浓缩的结果。肾交感神经（十版生理学P230）参与肾血流量和尿量的调节，与尿液的浓缩无关（A错）。","","N"],["2019-N141",9,"第3节 神经系统对躯体运动的调控","脑干网状结构抑制区和易化区",2019,141,"X","","具有易化肌紧张的中枢部位有",[["A","前庭核"],["B","小脑前叶蚓部"],["C","小脑后叶中间部"],["D","大脑皮层运动区"]],"AC","电刺激脑干网状结构的不同区域，可观察到网状结构中存在抑制或易化（加强）肌紧张和肌肉运动的区域，分别称为抑制区和易化区。此外，脑干网状结构之外的一些区域也可间接通过脑干网状结构的抑制区和易化区对肌紧张进行调节。如刺激大脑皮层运动区（D错）、纹状体、小脑前叶蚓部（B错）等部位，可抑制肌紧张；而刺激前庭核（A对）、小脑前叶两侧部和后叶中间部（C对）等部位，可易化肌紧张。","","N"],["2020-N1",0,"第6节 人体内自动控制系统","反馈控制系统",2020,1,"A","","有关人体内控制系统中的调定点，错误的描述是",[["A","自动控制系统中设定的工作点"],["B","可视为生理指标正常值的均数"],["C","正反馈调控的终极目标"],["D","负反馈调控比较器的参照点"]],"C","负反馈控制都有一个调定点，调定点是指自动控制系统所设定的一个工作点或参照点（D对），使受控部分的活动只能在这个设定的工作点或参照点附近的一个狭小范围内变动，以维持人体控制系统的平衡状态（A对），实际上，调定点可被视为各生理指标正常范围的均数（B对）。正反馈控制的结果是使受控部分的活动向与其原先活动的相同方向改变，是机体用于打破原先的平衡状态的机制，如胎儿分娩以及膀胱排尿，因此体内正反馈的结果多背离调定点（C错，为本题正确答案）。","","N"],["2020-N2",1,"第3节 细胞的电活动","电-化学驱动力及其变化",2020,2,"A","","在细胞发生动作电位的过程中，一般不会发生变化的电生理参数是",[["A","Na⁺电导"],["B","Na⁺平衡电位"],["C","K⁺电-化学驱动力"],["D","Na⁺电-化学驱动力"]],"B","动作电位的产生是在静息电位下，依靠离子的电-化学驱动力和细胞膜对离子的通透性的改变而产生的结果。电导反映的是膜对离子的通透性，当钠离子电导（A对）发生快速激活时，可使钠离子快速内流，引发动作电位去极化的产生，而钾离子电导的激活可与钠离子电导的失活共同作用加快膜的复极化。细胞在发生动作电位的过程中，膜电位随去极化和复极化发生改变，导致膜电位与离子平衡电位的差值改变，进而导致钾离子电化学驱动力（C对）和钠离子电化学驱动力（D对）在整个动作电位期间随膜电位的改变而改变。钠离子平衡电位（B错，为本题正确答案）是指钠离子受到的电-化学驱动力等于零时的膜电位，钠离子平衡电位接近动作电位的超射值水平，为一个衡定值（如神经细胞约为+60mV），不会随着细胞发生动作电位而产生变化。","","N"],["2020-N3",1,"第4节 肌细胞的收缩","兴奋-收缩耦联的基本步骤",2020,3,"A","","骨骼肌细胞横管膜上L型钙通道激活后的生理效应是",[["A","大量Ca²⁺内流，直接触发肌肉收缩"],["B","少量Ca²⁺内流，触发终池释放Ca²+"],["C","无Ca²⁺跨细胞膜流动，通道变构使终池释放Ca²⁺"],["D","大量Ca²⁺外流，导致肌肉舒张"]],"C","横纹肌细胞（骨骼肌细胞和心肌细胞）中有横管和纵管两种肌管系统。横管（或称T管）膜上有L型钙通道。纵管（或称L管）即肌质网（SR），分为纵行肌质网（LSR）和连接肌质网（或称终池）（JSR），纵行肌质网膜上有钙泵，连接肌质网膜上有钙释放通道（连接肌质网膜即终池内含有高浓度Ca²⁺），钙释放通道的分布与横管膜或肌膜上的L型钙通道相对应。以上为横纹肌细胞兴奋-收缩耦联的结构基础。下面为横纹肌细胞兴奋-收缩耦联的基本步骤：①横管膜的动作电位传导：肌膜上的动作电位沿横管膜传至肌细胞内部，并激活横管膜和肌膜中的L型钙通道；②终池内Ca²⁺释放：终池内的Ca²⁺在骨骼肌和心肌通过两种不同的机制释放入胞质（可参见十版生理学P47图2-30），在骨骼肌通过构象变化触发钙释放机制，这种触发机制无Ca²⁺跨细胞膜流动（C对），在心肌则通过钙触发钙释放机制，这种触发机制借助少量Ca²⁺内流（B错），通过Ca²⁺与肌质网膜中的钙结合位点结合，引起钙释放通道开放。③Ca²⁺触发肌丝滑行：胞质内Ca²⁺浓度的升高促使Ca²⁺与TnC结合而触发肌肉收缩；④肌质网回摄Ca²⁺：胞质内增加的Ca²⁺由纵行肌质网（LSR）中的钙泵而被回摄进肌质网中。","","N"],["2020-N4",2,"第2节 血细胞生理","红细胞生成所需物质",2020,4,"A","","病人在行远端回肠切除术后可发生的贫血是",[["A","恶性贫血"],["B","溶血性贫血"],["C","再生障碍性贫血"],["D","巨幼细胞贫血"]],"D","叶酸和维生素B₁₂是合成DNA所需要的重要辅酶，叶酸的活化需要维生素B₁₂的参与，而维生素B₁₂在回肠进行吸收，当实行回肠切除术后，维生素B₁₂吸收障碍引起细胞核发育异常，幼红细胞分裂缓慢，核浆发育不平衡导致红细胞体积增大，导致巨幼细胞性贫血（D对）。恶性贫血（A错）是巨幼细胞性贫血的一种，其发生是因患者血液中存在针对内因子的自身抗体，内因子抗体使内因子减少，进而导致维生素B₁₂吸收不良而引起。脾功能亢进或血管受机械冲击而破坏过多，导致红细胞破坏过多可引起溶血性贫血（十版内科学P559）（B错）。骨髓是成人生成红细胞的唯一场所，各种病因（如病毒感染、化学因素、X射线等）引起骨髓造血功能障碍时，导致再生障碍性贫血（十版内科学P555）（C错）。","","N"],["2020-N5",2,"第3节 生理性止血","凝血因子",2020,5,"A","","肝硬化病人易发生凝血障碍的主要原因是",[["A","血小板功能减退"],["B","维生素K相对不足"],["C","凝血因子合成减少"],["D","Ca²⁺缺乏"]],"C","血浆中的凝血因子大部分在肝中合成，当肝硬化后，凝血因子生成减少（C对）可出现凝血功能障碍。肝硬化病人可有维生素 K 相对不足（肝硬化会影响胆汁的排泄，继而影响脂溶性维生素K的吸收）和钙离子缺乏（肝硬化时可因维生素D吸收不良或代谢障碍影响钙的吸收）的情况，二者均可导致凝血功能障碍，但均非主要原因（BD错）。肝硬化可引起脾功能亢进，后者可破坏血小板使血小板数量减少（而非血小板功能减退 ）（A错），且血小板数量减少主要影响血栓形成，而非引起凝血功能障碍。","","N"],["2020-N6",3,"第3节 血管生理","影响组织液生成的因素",2020,6,"A","","发生右心衰竭时，引起水肿的主要原因是",[["A","毛细血管血压升高"],["B","组织液静水压降低"],["C","血浆胶体渗透压降低"],["D","毛细血管壁通透性增大"]],"A","右心衰竭可引起体循环静脉压增高，静脉回流受阻，使全身毛细血管后阻力增大，导致毛细血管血压升高（A对），引起全身性水肿。营养不良或某些肝肾疾病可使血浆蛋白减少，导致血浆胶体渗透压降低（C错），随之有效胶体渗透压下降，有效滤过压增大而发生水肿。在感染、烧伤、过敏等情况下，毛细血管壁的通透性异常增高（D错），血浆蛋白可随液体渗出毛细血管，使血浆胶体渗透压下降，组织胶体渗透压升高，有效滤过压增大，导致组织液生成增多而出现水肿。","","N"],["2020-N7",4,"第3节 气体在血液中的运输","氧解离曲线",2020,7,"A","","在高原或高空，若血液PaO₂＞60mmHg，此时的Hb氧饱和度至少是",[["A","0.6"],["B","0.7"],["C","0.8"],["D","0.9"]],"D","Hb氧饱和度是指Hb氧含量与Hb氧容量的百分比，即Hb实际结合的O₂量与Hb所能结合的最大O₂量的百分比。Hb氧饱和度与血液中PO₂的大小有关，二者之间关系的曲线称为氧解离曲线。氧解离曲线反映不同PO₂时O₂与Hb的结合情况，其上段（60～100mmHg）较平坦，此范围内PO₂对Hb饱和度影响不大，PO₂为100mmHg时，Hb饱和度97.4%，当PO₂下降到60mmHg时，Hb氧饱和度也可达90%（D对）。","","N"],["2020-N8",5,"第3节 胃内消化","盐酸",2020,8,"A","","决定胃酸最大分泌量的主要因素是",[["A","壁细胞的数量"],["B","质子泵的活性"],["C","碳酸酐酶的活性"],["D","迷走神经的活动度"]],"A","最大胃酸分泌量（MAO）是指经五肽胃泌素刺激后，1小时内壁细胞充分发挥其分泌功能，所能分泌的胃酸量。最大胃酸分泌量反映了理想状态下壁细胞所能分泌的最大胃酸量，其大小主要与壁细胞的数量（A对）有关，胃癌和慢性萎缩性胃炎患者，因壁细胞大量减少，最大胃酸分泌量显著降低。","","N"],["2020-N9",5,"第4节 小肠内消化","胆汁的作用",2020,9,"A","","能运载脂肪分解产物通过肠上皮表面静水层以利其吸收的物质是",[["A","混合微胶粒"],["B","载脂蛋白"],["C","乳糜微粒"],["D","脂溶性维生素"]],"A","肠上皮表面静水层是小肠绒毛表面覆盖有一层不流动水层，脂肪分解产物不易穿过。但脂肪分解产物可与胆盐聚合成水溶性的混合微胶粒，混合微胶粒（A对）则很容易穿过静水层而到达肠黏膜表面，从而促进脂肪分解产物的吸收。","","N"],["2020-N10",6,"第2节 体温及其调节","产热的形式",2020,10,"A","","非寒战产热作用最强的组织是",[["A","脑组织"],["B","肝组织"],["C","白色脂肪组织"],["D","褐色脂肪组织"]],"D","非战栗产热又称代谢性产热，是一种通过提高组织代谢率来增加产热的形式。机体的所有组织器官都有非战栗产热的作用，作用最强的是褐色脂肪组织（D对），其可以在甲状腺素、肾上腺素等的作用下，通过解耦联蛋白使经线粒体呼吸链电子传递建立的质子跨膜电-化学势能以热能的形式释放出来。","","N"],["2020-N11",7,"第2节 肾小球的滤过功能","肾小球毛细血管滤过系数",2020,11,"A","","能调节滤过膜有效滤过面积和有效通透系数的肾小球功能活动是",[["A","血管内皮细胞间隙的收放"],["B","基膜的更新和网孔改建"],["C","球内系膜细胞的舒缩"],["D","足细胞足突的伸缩"]],"C","滤过面积和通透系数决定肾小球毛细血管滤过系数（Kf），影响单位时间内通过滤过膜的滤液量。肾小球内肾小球毛细血管间的系膜细胞具有收缩能力，其舒缩活动（C对）可以同时调节滤过膜的滤过面积和通透系数。而血管内皮细胞舒缩（A错）、基膜的更新和网孔的改建（B错）、足细胞足突舒缩（D错）主要影响滤过膜的通透系数，而不影响滤过面积。","","N"],["2020-N12",7,"第5节 尿生成的调节","体液机制",2020,12,"A","","能刺激近球细胞分泌肾素的体液调控分子是",[["A","内皮素"],["B","肾上腺素"],["C","血管升压素"],["D","血管紧张素Ⅱ"]],"B","肾素的分泌受多方面因素的调节，包括肾内机制、神经和体液机制。其中体液机制为：循环血液中的儿茶酚胺（肾上腺素和去甲肾上腺素）（B对），肾内生成的PGE2和PGI2， 均可刺激球旁细胞释放肾素，低盐饮食也可显著增加肾素表达水平。血管紧张素Ⅱ（D错）、抗利尿激素（C错）、心房钠尿肽、内皮素（A错）和NO 则可抑制肾素的释放。","","N"],["2020-N13",8,"第4节 听觉","中耳的功能(1)",2020,13,"A","","在平衡鼓膜内外两侧压力中具有重要作用的结构是",[["A","外耳道"],["B","听骨链"],["C","咽鼓管"],["D","鼓膜张肌"]],"C","咽鼓管（C对）为连接鼓室和鼻咽部的管道，其鼻咽部开口常处于闭合状态，当其开放时与外界是相通的，可平衡鼓膜内外两侧的压力。外耳道（A错）和听骨链（B错）的作用主要为传声及增压。鼓膜张肌（D错）的作用是当声压过大时使鼓膜紧张，保护内耳的感音装置。","","N"],["2020-N14",10,"第3节 甲状腺内分泌","调节新陈代谢",2020,14,"A","","分泌正常时以促进合成代谢为主，分泌过多时则以促进分解代谢为主的激素是",[["A","胰岛素"],["B","生长激素"],["C","甲状腺激素"],["D","糖皮质激素"]],"C","甲状腺激素（C对）几乎刺激所有的代谢途径，包括合成代谢和分解代谢过程，而且对代谢的影响也十分复杂，常表现为双向作用。生理水平的甲状腺激素对蛋白质、糖、脂肪的合成和分解代谢均有不同程度的促进作用（虽然生理状态下甲状腺激素对脂肪促分解作用＞促合成作用，但对整体代谢而言，其以合成代谢为主），而过量的甲状腺激素促进分解代谢的作用更明显。","","N"],["2020-N15",10,"第5节 肾上腺内分泌","对组织器官活动的影响",2020,15,"A","","对去甲肾上腺素缩血管效应起允许作用的激素是",[["A","血管升压素"],["B","甲状腺激素"],["C","胰高血糖素"],["D","糖皮质激素"]],"D","允许作用指一个激素提高受体对另一个激素的敏感性，糖皮质激素（D对）可通过提高心肌、血管平滑肌对儿茶酚胺类激素的敏感性（允许作用），上调心肌、血管平滑肌细胞肾上腺素能受体的表达，并使这些受体与儿茶酚胺的亲和力增加，加强心肌收缩力，增加血管紧张度，以维持正常血压。","","N"],["2020-N16",11,"第1节 男性生殖功能及其调节","雄激素的合成、代谢和利用",2020,16,"A","","人体内生物活性最强的雄激素是",[["A","睾酮"],["B","雄酮"],["C","雄烯二酮"],["D","双氢睾酮"]],"D","睾丸间质细胞分泌的雄激素有雄酮（B错）、雄烯二酮（C错）、和睾酮（A错），睾酮是睾丸间质细胞分泌的雄激素中分泌量最多、活性最强的。双氢睾酮（D对）是由游离的睾酮经靶细胞内5α-还原酶的作用转化而成的，是人体内生物活性最强的雄激素。","","N"],["2020-N116",3,"第4节 心血管活动的调节","血管的神经支配",2020,116,"B","","交感缩血管神经纤维支配密度最高的血管是",[["A","脑血管"],["B","皮肤血管"],["C","内脏血管"],["D","骨骼肌血管"]],"B","交感缩血管神经纤维在不同组织器官血管中的分布密度不同，分布密度最大的是皮肤血管（B对），其次为骨骼肌血管（D错）和内脏血管（C错），最小的是冠状血管和脑血管（A错）。","","N"],["2020-N117",3,"第4节 心血管活动的调节","血管的神经支配",2020,117,"B","","交感缩血管神经纤维支配密度最低的血管是",[["A","脑血管"],["B","皮肤血管"],["C","内脏血管"],["D","骨骼肌血管"]],"A","交感缩血管神经纤维在不同组织器官血管中的分布密度不同，分布密度最大的是皮肤血管（B错），其次为骨骼肌血管（D错）和内脏血管（C错），最小的是冠状血管和脑血管（A对）。","","N"],["2020-N118",9,"第6节 脑的高级功能","大脑皮层的语言中枢",2020,118,"B","","患者除听不懂别人说话外，其他语言认知功能均正常，听力无障碍，其皮层损伤部位是",[["A","Broca区"],["B","颞上回后部"],["C","Wernicke区"],["D","顶下小叶角回"]],"B","病人除了听不懂别人话外，其他语言认知功能正常，听力无障碍，为感觉性失语症的表现，皮层损伤部位为颞上回后部（B对）。Broca区（A错）的损伤可致运动失语症，患者能看懂文字，也能听懂别人的说话，但自己却不会讲话，失去词语的组织搭配能力，不能用词语进行口头表达，但与发音有关的肌肉并不麻痹。Wernicke区（C错）的损伤可引起流畅失语症，患者说话正常，有时说话过度，但言不达意，言语中充满杂乱语和自创词，对别人的说话和文字的理解能力也有明显缺陷。角回（D错）损伤可产生失读症患者看不懂文字，但其视觉并无损害，其他语言功能活动均仍健全。","","N"],["2020-N119",9,"第6节 脑的高级功能","大脑皮层的语言中枢",2020,119,"B","","患者除自己不会说话外，其他语言认知功能均正常，发声无障碍，其皮层损伤部位是",[["A","Broca区"],["B","颞上回后部"],["C","Wernicke区"],["D","顶下小叶角回"]],"A","病人除了不能说话外，其他语言认知功能正常，发音无障碍，为运动性失语症的表现，皮层损伤部位为Broca区（A对）。颞上回后部（B错）的损伤可引起感觉失语症，患者能讲话及书写，也能看懂文字，但听不懂别人的谈话，因此不能回答别人的问题。Wernicke区（C错）的损伤可引起流畅失语症，患者说话正常，有时说话过度，但言不达意，言语中充满杂乱语和自创词，对别人的说话和文字的理解能力也有明显缺陷。角回（D错）损伤可产生失读症患者看不懂文字，但其视觉并无损害，其他语言功能活动均仍健全。","","N"],["2020-N136",1,"第2节 细胞的信号转导","酶联型受体介导的信号转导",2020,136,"X","","可通过激活酪氨酸激酶受体而完成细胞信号转导的配体有",[["A","胰岛素"],["B","肾上腺素"],["C","乙酰胆碱"],["D","神经生长因子"]],"AD","酪氨酸激酶受体的胞内结构域具有酪氨酸激酶活性，胞外结构域则含有可结合配体的部位，该类受体主要介导与生长、发育有关的细胞因子和一部分肽类激素的生理作用，包括表皮生长因子、神经生长因子（D对）、血小板源生长因子、肝细胞生长因子、成纤维细胞生长因子、白细胞介素和胰岛素（A对）等。肾上腺素（B错）为G蛋白耦联受体介导的信号转导的配体。乙酰胆碱（C错）为离子通道型受体介导的信号转导和G蛋白耦联受体介导的信号转导的配体。","","N"],["2020-N137",3,"第4节 心血管活动的调节","血管内皮生成的血管活性物质",2020,137,"X","","下列关于一氧化氮对循环系统作用的描述，正确的有",[["A","抑制血管平滑肌细胞增殖"],["B","使血管平滑肌细胞膜发生超极化"],["C","抑制血小板黏附，防止血栓形成"],["D","降低血管平滑肌胞质内游离Ca²⁺浓度"]],"ACD","NO由血管内皮细胞生成和释放，通过扩散至血管平滑肌细胞并激活胞内可溶性鸟苷酸环化酶，使胞内cGMP水平增高，降低胞质内游离Ca²⁺浓度（D对）。NO还可通过抑制平滑肌细胞的增殖来维持血管的正常结构与功能（A对），另外，NO可抑制血小板黏附，有助于防止血栓形成（C对）。使血管平滑肌细胞膜电位超极化的是内皮超极化因子（EDHF）（B错）。","","N"],["2020-N138",4,"第1节 肺通气","胸膜腔内压",2020,138,"X","","当发生气胸时，对机体功能活动的危害有",[["A","引起肺气肿"],["B","吸气阻力增大"],["C","呼气阻力增大"],["D","阻碍静脉和淋巴回流"]],"BD","当胸膜腔负压时，负压会维持肺扩张、吸引血管扩张、吸引气管扩张，这些都是有利于吸气过程的，气胸为空气进入胸膜腔造成积气状态，胸膜腔负压减小或消失，失去对肺的牵引作用，甚至因正压对肺产生压迫，使肺失去膨胀能力，肺泡萎缩，气道塌陷，故吸气阻力增加（B对），但呼气过程本身是肺回缩、气道口径变小、气道阻力增大的过程，气胸时负压减小相当于加快了呼气的过程（C错）。气胸时由于胸膜腔负压减小或消失甚至胸膜腔正压的压迫，胸腔静脉和淋巴管可回流受阻（D对）。肺气肿（A错）是指终末细支气管远端的气道弹性减退，过度膨胀、充气和肺容积增大的病理状态，与气胸无关。","","N"],["2020-N139",5,"第3节 胃内消化","胃排空及其控制",2020,139,"X","","人在进食后可增强胃排空的因素有",[["A","促胃液素"],["B","肠-胃反射"],["C","迷走-迷走反射"],["D","壁内神经丛反射"]],"CD","食物由胃排入十二指肠的过程称为胃排空。食物对胃的扩张刺激可通过迷走-迷走反射（C对）和胃壁内神经丛反射（D对）引起胃运动的加强，促进胃排空。此外，食物对胃的扩张刺激和食物中某些化学成分可引起胃幽门部G细胞释放促胃液素，促胃液素（A错）能促进胃的运动，也能增强幽门括约肌的收缩，其总效应是延缓胃排空。而当食糜进入十二指肠后，食糜中的酸、脂肪和高渗性以及对肠壁的机械扩张均可刺激十二指肠内感受器，通过肠-胃反射（B错）抑制胃的运动，使胃排空减慢。","","N"],["2020-N140",7,"第3节 肾小管和集合管的物质转运功能","NH₃和NH₄⁺的分泌与H⁺和HCO₃⁻的转运的关系",2020,140,"X","","下列关于肾脏分泌NH₃和NH₄⁺的描述，正确的有",[["A","近端小管主要泌NH₄⁺"],["B","集合管主要泌NH₃"],["C","与泌H⁺密切相关"],["D","与重吸收HCO₃⁻密切相关"]],"ABCD","在近端小管（A对），上皮细胞顶端膜的Na⁺-H⁺交换体（由NH₄⁺代替H⁺）可以介导NH₄⁺的分泌。在集合管（B对），由于缺乏运载NH₄⁺相应的载体而对NH₄⁺的通透性较低，但集合管上皮细胞膜对NH₃高度通透，细胞内生成的NH₃可以单纯扩散的方式分泌进入小管液。肾脏分泌NH₃和NH₄⁺的来源为肾小管或集合管上皮细胞内的谷氨酰胺，谷氨酰胺代谢生成NH₄⁺的同时生成了HCO₃⁻，NH₄⁺分泌至小管液，HCO₃⁻则重吸收进入组织间液（血液）（D对）。NH₃的分泌与H⁺的分泌密切相关（C对），在生理情况下，肾脏分泌的H⁺约有50%由NH₃缓冲，H⁺可与NH₃结合形成NH₄⁺随尿排出体外。","","N"],["2020-N141",9,"第3节 神经系统对躯体运动的调控","牵张反射的感受器",2020,141,"X","","在下列情况下，可使骨骼肌肌梭Ⅰa类纤维传入冲动增多的有",[["A","骨骼肌收缩缩短时"],["B","骨骼肌被动拉长时"],["C","支配该肌梭的α运动神经元兴奋时"],["D","支配该肌梭的γ运动神经元兴奋时"]],"BD","肌梭的传入纤维有Ⅰa和Ⅱ类纤维两类，Ⅰa类纤维的末梢呈螺旋形缠绕于肌梭的感受装置部位，当肌肉受外力牵拉而使肌梭感受装置被拉长时（B对A错），螺旋形末梢发生变形而使Ⅰa类纤维传入冲动增加。肌梭受γ神经元的传出纤维支配，γ运动神经元兴奋时（D对），肌梭两端的收缩成分收缩，可牵拉肌梭感受装置，使Ⅰa类传入纤维传入冲动增加。α运动神经元支配的是与肌梭平行排列的梭外肌纤维，α运动神经元兴奋时（C错），梭外肌收缩，使与梭外肌纤维平行的肌梭（梭内肌纤维）缩短，进而肌梭感受装置所受到的牵拉刺激减少，Ⅰa类纤维传入冲动减少或消失。","","N"],["2021-N1",0,"第4节 机体的内环境、稳态和生物节律","机体的内环境",2021,1,"A","","下列关于人体内环境的概念，叙述错误的是",[["A","机体内全部液体"],["B","细胞赖以生存的环境"],["C","其理化性质变动很小"],["D","生物进化的结果"]],"A","机体内全部液体（A错，为本题正确答案）称为体液，约占体重的60%。体液可分为两部分：约2/3的体液分布在细胞内，称为细胞内液，其余的1/3分布在细胞外，称为细胞外液，包括血浆、组织液、淋巴液和脑脊液。由于机体内细胞直接接触并赖以生存的环境（B对）就是细胞外液，故而又称之为人体内环境。正常情况下，机体的内环境保持稳态，即内环境的基本理化性质，如温度、酸碱度、渗透压和各种液体成分变动很小（C对），保持相对恒定状态。人体内环境及其稳态是长期生物进化的结果（D对）。","","N"],["2021-N2",1,"第3节 细胞的电活动","静息时细胞膜对离子的相对通透性",2021,2,"A","","实际测量神经细胞静息电位略小于钾离子平衡电位的主要原因是",[["A","在钾离子外流的背景下存在少量的钠离子内流"],["B","在钾离子外流的背景下存在少量的钙离子内流"],["C","在钾离子外流的背景下存在一定的氯离子内流"],["D","在钾离子外流的背景下存在钠泵的生电作用"]],"A","实际测量神经细胞静息电位略小于钾离子平衡电位的主要原因是在钾离子外流的背景下存在少量的钠离子内流（A对），少量进入细胞的钠离子可部分抵消由钾离子外流所形成的膜内负电位。膜两侧溶液中的离子还有氯离子和钙离子和有机负离子等，但它们对静息电位的形成均无明显作用（BC错）。钠泵的生电作用是静息电位产生的基础，不是静息电位略小于钾离子平衡电位的原因（D错）。","","N"],["2021-N3",1,"第4节 肌细胞的收缩","骨骼肌神经肌肉接头处的兴奋传递",2021,3,"A","","骨骼肌终板电位以钠离子内流为主，主要是因为",[["A","阳离子中钠离子的活动度最大"],["B","阳离子中钠离子的直径最小"],["C","Ach受体阳离子通道对钠离子通透性最大"],["D","静息时钠离子的内向驱动力大于钾离子的外向驱动力"]],"D","骨骼肌终板电位以钠离子内流为主，主要是因为静息时钠离子的内向驱动力大于钾离子的外向驱动力（D对），与钠离子的活动度高低（A错）和直径大小（B错）无关。骨骼肌终板膜中的N₂型ACh受体通道对钠离子、钾离子、钙离子等阳离子均具有较大通透性（C错）。","","N"],["2021-N4",2,"第3节 生理性止血","内源性凝血途径",2021,4,"A","","血管性血友病的发病机制是",[["A","FⅧ缺陷"],["B","PF₄缺乏"],["C","vWF缺陷"],["D","Vit.K缺乏"]],"C","血管性血友病的发病机制是vWF（血管性血友病因子）缺陷（C对），其具体机制如下：FⅧ缺陷（A错）可引起血友病A，表现出严重的凝血障碍，在正常情况下，血浆中FⅧ与vWF以非共价形式结合成复合物，该复合物可避免FⅧ被活化的蛋白C降解，提高其稳定性，vWF缺乏时血浆FⅧ水平降低，间接引起凝血功能障碍。PF₄（血小板因子4）为血小板受刺激后释放或分泌的物质之一，可一定程度上说明体内血小板的活化情况，故PF₄缺乏（B错）提示血小板的活化不佳。凝血因子FⅡ、FⅦ、FⅨ、FⅩ的生成需要Vitk的参与，Vitk缺乏（D错）可引起凝血功能障碍，但不是血管性血友病的发病机制。","","N"],["2021-N5",3,"第1节 心脏的泵血功能","应用心室压力-容积环评价心功能",2021,5,"A","","心室压力–容积环向左侧扩大，收缩末期压力–容积关系曲线斜率增大所反映的心室功能变化是",[["A","前负荷增加"],["B","后负荷增加"],["C","心室顺应性下降"],["D","心肌收缩能力增强"]],"D","心室压力-容积曲线由每个相对应时间点的心室压力和容积值绘制而成，连接各个点可产生一个心室压力－容积环，表示的是整个心动周期中的心室压力-容积关系，该环变化可用于反映前负荷、后负荷、心室顺应性和心肌收缩能力。心室压力－容积环向左侧扩大反映心肌收缩能力增强；心室压力－容积环向右侧扩大反映前负荷增加（A错）；心室压力－容积环向上扩大反映后负荷增大（B错）；心室压力－容积环缩小反映心肌顺应性减小（C错）。收缩末期压力-容积关系曲线可反映心室收缩能力，曲线斜率增大反映心室收缩能力增强，曲线斜率减小反映心室收缩能力减弱。综上，心室压力–容积环向左侧扩大，收缩末期压力–容积关系曲线斜率增大所反应的心室功能变化是心肌收缩能力增强（D对）。","","N"],["2021-N6",3,"第3节 血管生理","影响静脉回心血量的因素",2021,6,"A","","长期卧床者突然站起时感觉头晕，眼前发黑的主要原因是",[["A","循环血量减少"],["B","静脉回流减少"],["C","心泵功能减弱"],["D","降压反射敏感性下降"]],"B","长期卧床者突然站起时感觉头晕，眼前发黑的主要原因是体位改变引起的静脉回流减少（B对），其作用机制为：长期卧床者突然站起时，由于静脉管壁的紧张性较低、可扩张性较大，同时腹壁和下肢肌肉的收缩力减弱，对静脉的挤压作减小，因而大量的血液淤滞于下肢，静脉回流减少，出现头晕，眼前发黑的症状。循环血量减少（A错）和心泵功能减弱（C错）亦可引起静脉回流减少而出现上诉症状，但循环血量减少常见于大出血患者，心泵功能减弱常见于左、右心衰患者。降压反射敏感性下降（D错）引起上诉症状的作用机制为：通过减弱降压反射导致动脉血压无法回升，从而引起头晕，眼前发黑的症状，但长期卧床者一般不会出现降压反射敏感性的下降。","","N"],["2021-N7",4,"第2节 肺换气和组织换气","通气_血流比值",2021,7,"A","","通气/血流比值异常表现为缺氧，与其发生原因无关的是",[["A","CO₂的扩散系数远大于O₂的扩散系数"],["B","动脉血与静脉血之间PO₂之差远高于PCO₂之差"],["C","氧解离曲线上段平坦，增加通气量无助于摄O₂"],["D","外周化学感受器对缺氧敏感，对CO₂潴留容易适应"]],"D","通气/血流比值异常表现为缺氧，原因在于：①动脉与静脉之间PO₂之差远高于PCO₂之差（B对），所以当发生动－静脉短路时，动脉血PO₂下降的程度大于PCO₂升高的程度；②CO₂的扩散系数约为O₂的20倍（A对），所以正常情况下CO₂的扩散速率比O₂快得多，不易潴留；③动脉血PO₂下降和PCO₂升高时，可刺激呼吸，增加肺泡通气量，有助于CO₂的排除，却几乎无助于O₂的摄取，这是由O₂解离曲线（氧解离曲线上段平坦，此段PO₂对Hb氧饱和度或血氧含量影响不大，增加通气无助于摄氧）和CO₂解离曲线的特点所决定的（C对）。通气/血流比值异常表现为缺氧，与化学感受性呼吸反射无关，且对二氧化碳潴留容易适应的是中枢化学感受器，而非外周化学感受器（D错，为本题正确答案）。","","N"],["2021-N8",5,"第4节 小肠内消化","胆汁的作用",2021,8,"A","","胆石症患者切除胆囊后最可能发生的情况是",[["A","不再发生胆道结石"],["B","胆汁排出量明显减少"],["C","增加消化性溃疡风险"],["D","影响脂肪性食物消化"]],"D","胆道结石是胆道系统中最常见的疾病，包括胆囊结石和胆管结石，切除胆囊后，依然可能发生胆管结石（A错）。肝细胞分泌胆汁，胆囊储存和浓缩胆汁，切除胆囊后，肝细胞依然能持续分泌胆汁，经胆总管直接排入十二指肠，由于未经胆囊浓缩，胆汁排出量反而会增加（B错）。胆囊的作用是储存和浓缩胆汁，当有大量脂肪性食物进入消化道时，排出胆汁到肠道进行消化，当胆囊切除后，没有了一次性释放较多胆汁的功能，对短时间内进食的大量脂肪性食物消化能力下降（D对）。本题答案官方答案为D，但略有争议，十版生理教材P183指出：因为肝胆汁可直接流入小肠的缘故，胆囊被摘除后，小肠内消化和吸收并无明显影响（D？）。此外，切除胆囊后，肝胆汁源源不断排入十二指肠，由于胆汁排出口邻近临近胃的幽门部，如因肠动力不足等原因造成胆汁排向肠道过程受阻，则可能逆向反流到胃里，导致胃黏膜损伤，最终形成胆汁返流性胃炎和消化性溃疡（C？）。","","N"],["2021-N9",6,"第1节 能量代谢","间接测热法",2021,9,"A","","物理热价与生物热价不同的营养物质是",[["A","糖类"],["B","蛋白质"],["C","植物性脂肪"],["D","动物性脂肪"]],"B","食物的热价指1g该食物氧化时所释放的能量，分为生物热价和物理热价，分别指食物在体内氧化和体外燃烧时释放的能量，通常体外燃烧时，食物可被完全氧化，体内氧化则不然。三大营养物质中，糖类（A对））和脂肪（包括植物性脂肪和动物性脂肪）（CD对）在体内可被完全氧化，因此生物热价和物理热价相同；蛋白质（B错，为本题正确答案）则不同，其部分代谢产物以尿素、尿酸和肌酐等形式从尿中排出，还有少量含氮产物从粪便中排出，这些代谢产物在体外燃烧后仍可产生一定能量，故蛋白质的生物热价小于物理热价。","","N"],["2021-N10",7,"第5节 尿生成的调节","血浆晶体渗透压",2021,10,"A","","正常人在下列情况下尿量无明显改变的是",[["A","一次性饮用1000ml清水"],["B","一次性饮用1000ml糖水"],["C","一次性饮用1000ml生理盐水"],["D","一次性静脉注射1000ml生理盐水"]],"C","当大量饮清水后，血液被稀释，血浆晶体渗透压降低，引起抗利尿激素释放减少，集合管对水的重吸收减少，尿液稀释，尿量增加。一次性饮1000ml清水（A错）后，约过30分钟尿量就开始增加，1小时末尿量可达最高峰，2～3小时后尿量恢复到原水平。若一次性饮1000ml生理盐水（C对），由于生理盐水与血浆晶体渗透压相近，不易吸收入血，则排尿量不会有显著变化（不会有显著增加）。一次性饮用1000ml糖水（B错）时，可使血浆葡萄糖浓度超过肾糖阈，肾小管中的葡萄糖无法被完全重吸收，小管液中葡萄糖浓度升高，由于渗透作用，使水和NaCl的重吸收减少，尿量显著增加，这种现象称为渗透性利尿。一次性静脉注射1000ml生理盐水（D错），可使循环血量增多，静脉回心血量增加，进而刺激心肺感受器，抑制抗利尿激素释放，导致尿量增加。此外，大量注射生理盐水，血容量增加，肾血浆流量增加，滤过平衡靠近出球小动脉端，肾小球滤过率增加，也使尿量增多。","","N"],["2021-N11",1,"第4节 肌细胞的收缩","骨骼肌神经肌肉接头处的兴奋传递",2021,11,"A","","临床上使用新斯的明治疗重症肌无力的机制是",[["A","模拟乙酰胆碱"],["B","抑制胆碱酯酶"],["C","激活ACh受体通道"],["D","增大终板电位幅度"]],"B","正常情况下，骨骼肌神经-肌肉接头的接头前膜释放乙酰胆碱，通过接头间隙作用于接头后膜（即终板膜）N₂型ACh受体阳离子通道，产生终板电位，该电位以电紧张方式向周围扩布，刺激邻近的普通肌膜爆发动作电位。随后乙酰胆碱被终板膜外侧的乙酰胆碱酯酶水解为乙酸和胆碱，失去活性，终板膜恢复静息状态。机体产生自身抗体破坏N₂型ACh受体阳离子通道可导致重症肌无力，新斯的明作为一种胆碱酯酶抑制剂，可抑制胆碱酯酶（B对），减少乙酰胆碱的水解，导致胆碱能神经末梢释放的 ACh堆积，产生拟胆碱作用，使骨骼肌收缩力增强，从而减轻肌无力症状。","","N"],["2021-N12",8,"第4节 听觉","耳蜗内电位",2021,12,"A","","临床上使用呋塞米造成感音性耳聋的机制是",[["A","损伤外毛细胞"],["B","损伤内毛细胞"],["C","阻碍内淋巴中高钾形成"],["D","阻碍神经冲动传导"]],"C","听觉器官由外耳、中耳和内耳的耳蜗组成，当外耳和中耳受损后导致传音性耳聋，内耳的耳蜗以及听神经、听觉中枢病变时导致感音性耳聋。耳蜗管以骨蜗轴为中心，上为前庭膜，下为基底膜，外侧为血管纹，内含内淋巴液。其中基底膜上含听觉感受器，称为螺旋器，由内、外毛细胞及支持细胞等组成，毛细胞顶部与蜗管内淋巴接触，底部与鼓阶外淋巴接触。内、外毛细胞的作用不同。蜗管外侧壁的血管纹通过钠泵和Na⁺-K⁺-2Cl⁻将K⁺转入蜗管内淋巴中，随后内毛细胞顶部的机械门控钾通道开放，K⁺内流进入内毛细胞，去极化后引发一系列反应，触发递质释放，进而引起听觉神经产生冲动并传导。而外毛细胞则起到耳蜗放大器作用，可感知并迅速加强基底膜的振动，从而有助于盖膜下内淋巴的流动，使内毛细胞更易受到刺激，提高了对相应振动频率的敏感性。临床上使用呋塞米通过抑制Na⁺-K⁺-2Cl⁻同向转运体，使内淋巴液高钾环境不能形成（C对），K⁺内流无法形成，内毛细胞无法去极化触发递质释放，听觉神经冲动无法产生导致听力障碍。","","N"],["2021-N13",9,"第3节 神经系统对躯体运动的调控","帕金森病",2021,13,"A","","使用左旋多巴治疗帕金森病时，不能改善的症状是",[["A","动作迟缓"],["B","静止性震颤"],["C","肌张力增高"],["D","随意运动减少"]],"B","帕金森病的发病与黑质多巴胺能神经元变性和丘脑外侧腹核等结构的功能异常相关，前者（黑质多巴胺能神经元变性）可引发全身肌张力增高（C错），肌肉强直、随意运动减少（D错）、动作缓慢（A错）、面部表情呆板等，临床上给予多巴胺的前体左旋多巴可能明显改善上述症状；后者（丘脑外侧腹核等结构功能异常）可引发静止性震颤（B对），使用左旋多巴治疗无效。","","N"],["2021-N14",10,"第2节 下丘脑-垂体及松果体内分泌","促进生长",2021,14,"A","","血液中胰岛素样生长因子-1水平明显升高，常提示的疾病是",[["A","侏儒症"],["B","呆小症"],["C","糖尿病"],["D","肢端肥大症"]],"D","肢端肥大症是一种由于生长激素 (GH) 持久过度分泌所引起的内分泌代谢性疾病， 生长激素可通过激活靶细胞上生长激素受体（GHR）和诱导靶细胞产生胰岛素样生长因子（IGF）实现其生物学效应，其中IGF可分为IGF-1和IGF-2两型，患有肢端肥大症（D对）时，血液中IGF-1水平明显升高，测定IGF-1水平是定性诊断肢端肥大症的重要手段之一。","","N"],["2021-N15",10,"第5节 肾上腺内分泌","概述",2021,15,"A","","实验中，切除双侧肾上腺后，动物很快死亡的主要原因是",[["A","缺乏肾上腺髓质素"],["B","缺乏肾上腺髓质激素"],["C","缺乏肾上腺皮质激素"],["D","缺乏血管紧张素Ⅱ"]],"C","实验中，切除双侧肾上腺后，动物很快死亡的主要原因是缺乏肾上腺皮质激素（C对），肾上腺皮质激素是维持生命活动的必需激素，缺乏糖皮质激素时，体内糖、蛋白质和脂肪代谢紊乱，机体对伤害性刺激的耐受力严重降低，缺乏盐皮质激素时，水盐代谢紊乱，循环血量严重不足，动脉血压降低，从而引起机体功能衰竭而死亡。","","N"],["2021-N16",11,"第3节 妊娠","胎盘的功能",2021,16,"A","","妊娠期妇女由胎盘合成和分泌的雌激素主要是",[["A","雌酮"],["B","雌二醇"],["C","雌三醇"],["D","己烯雌酚"]],"C","妊娠期妇女由胎盘合成和分泌的雌激素主要是雌三醇（C对），雌二醇（B错）和雌酮（A错）较少，己烯雌酚（D错）为人工合成的非甾体雌激素。","","N"],["2021-N116",4,"第3节 气体在血液中的运输","影响氧解离曲线的因素",2021,116,"B","","不阻碍Hb与O₂结合，但是阻碍HbO₂释放O₂的因素是",[["A","CO中毒"],["B","PO₂下降"],["C","PCO₂升高"],["D","2，3-DPG降低"]],"D","2，3-DPG浓度降低（D对）时，Hb对O₂的亲和力升高，从而促进Hb与O₂结合，阻碍HbO₂释放O₂。CO中毒时，一方面，由于CO对Hb的亲和力远大于O₂，CO可从HbO₂取代O₂，从而阻碍Hb与O₂结合，另一方面，当CO与Hb分子中一个血红素结合后，可增加其余3个血红素对O₂的亲和力，进而阻碍Hb对O₂的解离，因此CO中毒（A错）既妨碍Hb与O₂的结合，又妨碍HbO₂释放O₂。PO₂下降（B错）时，Hb分子逐渐由R型（疏松型）变为T型（紧密型），对O₂的亲和力逐渐降低，从而阻碍Hb与O₂结合，促进HbO₂释放O₂。PCO₂升高（C错）时，Hb对O₂的亲和力降低，从而阻碍Hb与O₂结合，促进HbO₂释放O₂。","","N"],["2021-N117",4,"第3节 气体在血液中的运输","影响氧解离曲线的因素",2021,117,"B","","既阻碍Hb与O₂结合，又阻碍HbO₂释放O₂的因素是",[["A","CO中毒"],["B","PO₂下降"],["C","PCO₂升高"],["D","2，3-DPG下降"]],"A","CO中毒时，一方面，由于Hb对CO的亲和力远大于O₂，CO可从HbO₂取代O₂，从而阻碍Hb与O₂结合，另一方面，当CO与Hb分子中一个血红素结合后，可增加其余3个血红素对O₂的亲和力，进而阻碍Hb对O₂的解离，因此CO中毒（A对）既妨碍Hb与O₂的结合，又妨碍Hb与O₂的解离。PO₂下降（B错）时，Hb分子逐渐由R型（疏松型）变为T型（紧密型），对O₂的亲和力逐渐降低，从而阻碍Hb与O₂结合，促进Hb与O₂解离。PCO₂升高（C错）时，Hb对O₂的亲和力降低，从而阻碍Hb与O₂结合，促进Hb与O₂解离。","","N"],["2021-N118",5,"第4节 小肠内消化","缩胆囊素",2021,118,"B","","主要促进胰酶分泌，而水和HCO₃⁻分泌量较少的是胃肠激素是",[["A","胰多肽"],["B","促胰液素"],["C","缩胆囊素"],["D","胰高血糖素"]],"C","胰腺是兼有外分泌和内分泌功能的腺体。胰腺的外分泌物为胰液，是由胰腺的腺泡细胞和小导管管壁细胞所分泌的，具有很强的消化能力，调节胰液分泌的体液因素主要有促胰液素和缩胆囊素，其中促胰液素（B错）主要促进水和HCO₃⁻分泌，而胰酶分泌量较少，缩胆囊素（C对）主要促进胰酶分泌，而水和HCO₃⁻分泌量较少。胰腺的内分泌物为激素，是由胰腺的胰岛细胞（呈小岛状散在分布于外分泌腺泡之间的内分泌细胞团）分泌的，主要与糖代谢调节有关，包括胰高血糖素、胰岛素、胰多肽等，其中胰多肽（A错）的作用为抑制缩胆囊素和胰酶的排放，从而抑制餐后胰液和胆汁分泌，胰高血糖素（D错）的作用为升高血糖，促进肝糖原分解，抑制肝内蛋白和甘油三酯的合成，通过促进能源物质分解代谢达到为机体供能的目的。","","N"],["2021-N119",5,"第4节 小肠内消化","促胰液素",2021,119,"B","","主要促进水和HCO₃⁻分泌，而胰酶分泌量较少的胃肠激素是",[["A","胰多肽"],["B","促胰液素"],["C","缩胆囊素"],["D","胰高血糖素"]],"B","胰腺是兼有外分泌和内分泌功能的腺体。胰腺的外分泌物为胰液，是由胰腺的腺泡细胞和小导管管壁细胞所分泌的，具有很强的消化能力，调节胰液分泌的体液因素主要有促胰液素和缩胆囊素（二者均属于胃肠激素），其中促胰液素（B对）主要促进水和HCO₃⁻分泌，而胰酶分泌量较少，缩胆囊素（C错）主要促进胰酶分泌，而水和HCO₃⁻分泌量较少。胰腺的内分泌物为激素，是由胰腺的胰岛细胞（呈小岛状散在分布于外分泌腺泡之间的内分泌细胞团）分泌的，主要与糖代谢调节有关，包括胰高血糖素、胰岛素、胰多肽等，其中胰多肽（A错）的作用为抑制缩胆囊素和胰酶的排放，从而抑制餐后胰液和胆汁分泌，胰高血糖素（D错）的作用为升高血糖，分解四肢脂肪，抑制肝内蛋白合成，促进肝外蛋白分解，通过促进能源物质分解代谢达到为机体供能的目的。","","N"],["2021-N136",5,"第3节 胃内消化","内因子",2021,136,"X","","因体内缺乏维生素B₁₂而导致巨幼红细胞性贫血的原因是",[["A","胃酸分泌不足"],["B","胃大部切除术后"],["C","末端回肠切除术后"],["D","体内产生抗内因子抗体"]],"ABCD","存在于食物中的大多数维生素B₁₂是与蛋白质结合的，胃蛋白酶消化蛋白质的作用和胃内的低pH环境，能够使维生素B₁₂能从结合的形式释放出来，胃酸分泌不足时（A对），使维生素B₁₂不能由食物中的蛋白结合形式释放出来而发生维生素B₁₂缺乏，导致巨幼细胞性贫血。食物中的维生素B₁₂经人体摄入后，与胃黏膜壁细胞合成的内因子结合形成复合物，内因子可保护维生素B₁₂不受胃肠道分泌液的破坏，达到回肠末端经肠上皮细胞吸收。胃大部切除术后（B对）和体内产生内因子抗体（D对）时，内因子缺乏，维生素B₁₂易被胃肠道分泌液破坏，导致巨幼细胞性贫血。回肠末端切除后（C对），维生素B₁₂吸收减少，导致巨幼细胞性贫血。","","N"],["2021-N137",3,"第4节 心血管活动的调节","颈动脉窦和主动脉弓压力感受性反射",2021,137,"X","","颈动脉窦和主动脉弓压力感受性反射调节的生理特点是",[["A","具有双向调节血压能力"],["B","对心率快慢无调节作用"],["C","对血压主要起短期调节作用"],["D","血压持续升高时可发生重调定"]],"ACD","颈动脉窦和主动脉弓压力感受性反射具有双向调节血压的能力（A对）：当动脉血压突然升高时，可反射性引起心率减慢（B错）、心输出量减少、血管舒张、外周阻力减小，血压下降，这一反射称为压力感受性反射；当动脉血压降低时，反射减弱，引起心率加快，心输出增多，外周阻力增大，血压回升。压力感受性反射属于典型的负反馈调节，其生理意义主要是在短时间内（C对）快速调节动脉血压，以维持动脉血压相对稳定，使动脉血压不致发生过分的波动。血压持续升高时，压力感受性反射的调定点将上调，从而在较正常高的血压水平上保持血压相对稳定，这一现象称为压力感受性反射的重调定（D对）。","","N"],["2021-N138",6,"第2节 体温及其调节","产热活动的调节",2021,138,"X","","参与人体产热活动调节的内分泌激素有",[["A","胰岛素"],["B","生长激素"],["C","甲状腺激素"],["D","糖皮质激素"]],"BC","甲状腺激素（C对）是调节非战栗产热活动最重要的体液因素，生长激素（B对）可调节代谢性产热活动。胰岛素主要促进物质代谢、调节血糖浓度，对产热活动无明显调节作用（A错）。糖皮质激素在治疗严重感染或炎症时具有退热作用（十版药理学P323），但对机体正常产热活动的无明显调节作用（D错）。","","N"],["2021-N139",7,"第5节 尿生成的调节","维持机体酸碱平衡",2021,139,"X","","肾小管和集合管上皮细胞参与调节和维持机体酸碱平衡的功能活动有",[["A","Na⁺-H⁺交换"],["B","质子泵活动"],["C","NH₃/NH₄⁺的分泌"],["D","Na⁺-K⁺-2Cl⁻同向转运"]],"ABC","肾小管和集合管通过Na⁺-H⁺交换（A对）和质子泵活动（B对）将H⁺主动分泌到小管液中，且泌H⁺与HC0₃⁻的重吸收相耦联，此外，肾还能泌NH₃和NH₄⁺（C对），这一过程不仅能使小管液中的H⁺浓度降低，使泌H⁺持续不断地进行，而且也能促进HC0₃⁻的重吸收，以上机制共同参与调节和维持了机体的酸碱平衡。Na⁺-K⁺-2Cl⁻同向转运（D错）发生于髓袢升支粗段， 该转运过程主动重吸收NaCl， 使外髓部组织间液NaCl堆积，形成了肾脏外髓部高渗透压浓度。","","N"],["2021-N140",8,"第3节 视觉","晶状体变凸",2021,140,"X","","眼科检查中，使用后马托品滴眼可出现的症状有",[["A","扩瞳"],["B","复视"],["C","视物模糊"],["D","缓解青光眼症状"]],"AC","后马托品是胆碱M受体阻断药，虹膜环行肌和睫状肌均受副交感神经支配，使用后马托品滴眼，一方面可抑制虹膜环行肌收缩，发挥扩瞳作用（A对），另一方面可抑制睫状肌收缩，影响晶状体变凸而使视网膜成像变模糊（C对）。复视（B错）指两眼看一物体时感觉为两个物像的异常现象，眼外肌瘫痪、眼球内肿瘤压迫、脑神经病变等情况均可导致复视，复视的产生与植物神经（交感神经和副交感神经）的控制无关，不会因为使用后马托品滴眼而出现复视现象。后马托品扩瞳后，前房角间隙变窄，阻碍房水回流进入巩静脉窦，造成眼压升高，会加重青光眼症状（D错）。","","N"],["2021-N141",9,"第5节 脑电活动及睡眠与觉醒","睡眠的两种状态及生理意义",2021,141,"X","","下列有关非快眼动睡眠的生理意义叙述正确的是",[["A","促进儿童生长发育"],["B","促进脑合成蛋白质"],["C","有助于体力恢复"],["D","有助于突触建立联系"]],"AC","非快眼动睡眠（NREM）时期腺垂体分泌生长激素明显增多，有助于体力恢复（C对）和促进生长发育（A对）。促进脑蛋白质合成（B错）和有助于突触建立联系（D错）为快眼动睡眠（REM）的生理意义。","","N"],["2022-N1",1,"第1节 细胞膜的物质转运功能","继发性主动转运",2022,1,"A","","由反向转运体介导的物质跨膜运输是",[["A","甲状腺滤泡上皮细胞吸收I⁻"],["B","肾近端小管分泌H⁺"],["C","肾小管上皮细胞对HCO₃⁻的重吸收"],["D","葡萄糖跨肠上皮细胞刷状缘进入细胞"]],"B","反向转运属于继发性主动转运的一种形式，载体称为反向转运体或交换体，被转运的分子或离子在跨膜转运过程中向相反方向运动；另一种形式为同向转运，载体称为同向转运体，被转运的分子或离子在跨膜转运过程中向同一方向运动。由反向转运体介导的物质跨膜运输是肾小管近端小管分泌氢离子（H⁺）（B对），是由肾小管近端小管上皮细胞顶端膜上分布的Na⁺-H⁺交换体来实现的，完成一次转运可将1个Na⁺顺电化学梯度重吸收进入细胞内，同时将胞内的1个H⁺逆浓度梯度分泌到管腔中。甲状腺滤泡上皮吸收碘离子（I⁻）（A错）是由Na⁺- I⁻同向转运体介导的同向转运；肾小管上皮细胞重吸收碳酸氢根（HCO₃⁻）（C错）包括以CO₂形式单纯扩散入上皮细胞和以由Na⁺-HCO₃⁻同向转运体介导的同向转运入细胞间液两个过程；葡萄糖跨肠上皮细胞刷状缘进入细胞（D错）是由Na⁺-葡萄糖同向转运体介导的同向转运。","","N"],["2022-N2",1,"第4节 肌细胞的收缩","后负荷",2022,2,"A","","后负荷增加时，骨骼肌收缩的改变是",[["A","等长收缩时间缩短"],["B","等张收缩时间延长"],["C","肌肉收缩的长度减小"],["D","肌肉收缩的速度增加"]],"C","后负荷是指肌肉在收缩后所承受的负荷。由于肌肉在等张收缩时产生的收缩张力与后负荷大小相等，方向相反，故在数值上可用后负荷反映收缩张力的大小。后负荷增加时，肌肉收缩的长度减小（C对），当后负荷增加到使肌肉不能缩短时，肌肉产生的张力达到最大，称为最大收缩张力，表现为等长收缩。后负荷（肌肉收缩张力）和速度呈反变关系，后负荷增加时，肌肉收缩的速度减慢（D错）。后负荷为零时肌肉缩短速度最大，称为最大缩短速度， 表现为等张收缩；随着后负荷的增大，表现为先等长收缩后等张收缩，后负荷越大，等长收缩时间越长（A错），等张收缩时间越短（B错）。","","N"],["2022-N3",2,"第2节 血细胞生理","红细胞的生理特征",2022,3,"A","","红细胞沉降率增快的原因是",[["A","红细胞数量增加"],["B","血浆球蛋白减少"],["C","血浆白蛋白增多"],["D","血浆纤维蛋白原增多"]],"D","红细胞沉降率是指红细胞在一定条件下沉降的速率，简称“血沉”，是静止情况下，红细胞受地球引力、血浆浮力及血液组成相互作用的结果。红细胞沉降率主要受血液组成的影响：①血浆中组分变化，血浆中纤维蛋白原（D对）、球蛋白（B错）和胆固醇的含量增高时，可加快红细胞叠连和沉降率，而血浆中白蛋白（C错）、卵磷脂的含量增多则可减慢沉降率；②红细胞数量和形状，红细胞减少时（A错）血沉加快，球形红细胞增多血沉减慢。","","N"],["2022-N4",2,"第4节 血型和输血原则","ABO血型系统",2022,4,"A","","ABO血型中O型血红细胞表面具有的抗原是",[["A","A抗原"],["B","B抗原"],["C","D抗原"],["D","H抗原"]],"D","根据红细胞膜上是否存在A抗原和B抗原可将血液分为四种ABO血型：红细胞膜上只含A抗原者为A型；只含B抗原者为B型；含有A与B两种抗原者为AB型；A和B两种抗原均无者为O型（AB错）。 O型红细胞虽然不含A、B抗原，但有H抗原（D对），A、B抗原都是在H抗原的基础上形成的。 D抗原（C错）为Rh阳性血型的红细胞膜抗原。","","N"],["2022-N5",3,"第1节 心脏的泵血功能","心室舒张期",2022,5,"A","","心动周期中，主动脉瓣关闭的时间是",[["A","心房收缩期末"],["B","快速射血期初"],["C","减慢射血期初"],["D","等容舒张期初"]],"D","射血后，心室开始舒张，室内压下降，主动脉内的血液向心室方向反流，推动主动脉瓣（半月瓣）使之关闭（D对），但此时室内压仍高于房内压，故房室瓣仍处于关闭状态，心室暂时为一封闭腔。从主动脉瓣关闭至房室瓣开启前的这一段时间内，心室舒张而心室容积并不改变，称为等容舒张期，故主动脉瓣关闭的时间是等容舒张期初（D对）。心房收缩期末，房室瓣关闭（A错）；快速射血期初（B错），主动脉瓣开放；减慢射血期初（C错），室内压已低于主动脉压，但此时心室内的血液因具有较高的动能，仍可逆压力梯度继续进入主动脉，故主动脉瓣仍处于开放状态。","","N"],["2022-N6",3,"第3节 血管生理","影响静脉回心血量的因素",2022,6,"A","","可以增加静脉回心血量的是",[["A","大失血"],["B","用力呼气"],["C","每搏输出量增加"],["D","由平卧位突然站立"]],"C","每搏输出量增加（C对），心室内剩余血量减少，心舒期室内压就较低，从而对心房和静脉内血液的抽吸力量增强，故回心血量增多。大失血（A错）时，血量减少，体循环平均充盈压降低，静脉回心血量也降低。用力呼气（B错）时，胸膜腔负压减小，静脉回心血量相应减少。由平卧位突然转为直立位（D错）时，身体低垂部分的静脉因跨壁压增大而扩张，可容纳更多的血液，因而回心血量减少。","","N"],["2022-N7",4,"第1节 肺通气","肺内压",2022,7,"A","","在呼吸过程中，肺内压最低值出现的时期是",[["A","吸气相起始期"],["B","吸气相中期"],["C","呼气相起始期"],["D","呼气相中期"]],"B","肺内压在呼吸过程中呈周期性变化，在吸气相起始期（A错），肺内压约等于大气压，随着吸气的进行，肺容积逐渐增大，肺内压也随之降低，至吸气相中期（B对），肺内压至最低，外界气体进入肺，随着肺内气体量的逐渐增加，肺内压也逐渐升高，至吸气末，肺内压升高到与大气压相等，气流便暂停。在呼气相起始期（C错），肺内压约等于大气压，随着呼气的进行，肺容积减小，肺内压随之升高，当高于大气压时，气体流出肺，至呼气相中期（D错），肺内压达最高。随着肺内气体量的减少，肺内压也逐渐降低，至呼气末，肺内压又降到与大气压相等，气流再次暂停。","","N"],["2022-N8",5,"第4节 小肠内消化","胰液的性质、成分和作用",2022,8,"A","","辅脂酶在甘油三酯消化中的作用是",[["A","分解甘油三酯"],["B","乳化甘油三酯"],["C","激活胰脂肪酶"],["D","防止胰脂肪酶从脂滴表面清除"]],"D","辅脂酶主要是通过疏水键与甘油三酯结合，通过氢键与胰脂酶结合，将胰脂酶锚定在乳化微团的脂-水界面，防止胰脂肪酶从脂滴表面清除（D对）。辅脂酶可防止胰脂酶在脂-水界面上变性、失活，而非激活胰脂肪酶（C错）。能够分解甘油三酯（A错）的是胰脂肪酶。起乳化甘油三酯（B错）作用的是胆汁酸盐。","","N"],["2022-N9",7,"第2节 肾小球的滤过功能","肾血浆流量",2022,9,"A","","可导致肾小球滤过增加的因素是",[["A","交感神经兴奋"],["B","肾盂结石"],["C","收缩压升高到150mmHg"],["D","肾血浆流量增加"]],"D","单位时间内（每分钟）两肾生成的超滤液量称为肾小球滤过率。影响肾小球滤过的因素包括肾小球毛细血管滤过系数、有效滤过压（肾小球毛细血管静水压+囊内液胶体渗透压-血浆胶体渗透压-肾小囊内压）和肾血浆流量。肾血浆流量增加（D对）时，肾小球毛细血管中血浆胶体渗透压上升的速度减缓，滤过平衡点向出球小动脉端移动，甚至不出现滤过平衡的情况，即有效滤过面积增大，导致肾小球滤过率增加。肾交感神经兴奋（A错）时，入球动脉阻力增加，肾血浆流量减少，肾小球滤过率降低。肾盂结石（B错）时，小管液或终尿不能排出，可引起逆行性压力升高，最终导致囊内压升高，从而使有效滤过压和肾小球滤过率降低。全身动脉血压在70～180mmHg范围内波动时（C错），由于肾血流量存在自身调节机制，肾血流量和肾小球毛细血管静水压保持相对稳定，肾小球滤过率不会受大的影响。","","N"],["2022-N10",7,"第4节 尿液的浓缩和稀释","直小血管的逆流交换机制",2022,10,"A","","肾脏直小血管的功能是",[["A","带走肾髓质中的溶质"],["B","维持肾皮质低渗状态"],["C","维持肾髓质间质的高渗状态"],["D","维持肾组织的血液供应"]],"C","直小血管主要的作用是逆流交换，使积聚在肾小管外的NaCl和尿素能持续滞留在该部位而不被循环液带走，维持肾髓质间液的高渗环境（C对）。","","N"],["2022-N11",9,"第1节 神经系统功能活动的基本原理","突触前抑制",2022,11,"A","","突触前抑制的特点",[["A","感觉传入通路中少见"],["B","减少突触前神经元递质释放"],["C","增加被抑制神经元Cl⁻内流"],["D","被抑制神经元产生IPSP"]],"B","突触前抑制是通过改变突触前神经元的活动，最终使突触后神经元（被抑制神经元）兴奋性降低，从而引起抑制效应的现象。例如在脊髓灰质后角，源自脊神经后根感觉神经纤维的轴突末梢A（突触前神经元）与脊髓内第一级感觉上行投射神经元C（突触后神经元/被抑制神经元）构成轴突-胞体式突触；后角内中间神经元的轴突末梢B与末梢A（突触前神经元）构成轴突-轴突式突触（改变突触前神经元的活动），但与神经元C（突触后神经元/被抑制神经元）不直接形成突触。末梢B兴奋时，释放 GABA（γ-氨基丁酸）作用于末梢A（突触前神经元）上的 GABAA受体，引起末梢A（突触前神经元）的Cl⁻电导增加，膜发生去极化，使传到末梢A（突触前神经元）的动作电位幅度变小，时程缩短，结果使进入末梢A（突触前神经元）的Ca²⁺减少，由此而引起末梢A（突触前神经元）递质释放量减少（B对），最终导致突触后神经元C（突触后神经元/被抑制神经元）的EPSP减小（D错）。突触前抑制广泛存在于中枢，尤其在感觉传入通路中多见（A错），对调节感觉传入活动具有重要意义。增加被抑制神经元Cl⁻内流（C错）是突触后抑制产生抑制性突触后电位（IPSP）的特点。","","N"],["2022-N12",9,"第1节 神经系统功能活动的基本原理","反射的中枢整合",2022,12,"A","","在人类，属于单突触反射的是",[["A","腱反射"],["B","逃避反射"],["C","吸吮反射"],["D","翻正反射"]],"A","单突触反射指的是传入神经及传出神经之间仅有一次突触传递的反射活动，在人体内目前仅发现腱反射（A对）是单突触反射。","","N"],["2022-N13",10,"第1节 内分泌与激素","激素受体",2022,13,"A","","类固醇激素结合的受体是",[["A","酪氨酸激酶受体"],["B","核受体"],["C","G蛋白耦联受体"],["D","鸟苷酸环化酶受体"]],"B","类固醇激素因其共同前体是胆固醇而得名，其典型代表是孕酮、醛固酮、皮质醇、睾酮、雌二醇和胆钙化醇。类固醇激素的分子量小，且因属于亲脂激素，可以直接穿透细胞膜的磷脂双分子层，与胞质或核受体（B对）结合发挥调节效应。酪氨酸激酶受体（A错）的配体主要是各种生长因子和胰岛素等。G蛋白耦连受体（C错）的配体种类繁多，包括各种下丘脑调节肽和垂体激素、儿茶酚胺、血管升压素等；鸟苷酸环化酶受体（D错）的配体主要是脑钠尿肽（BNP）、心房钠尿肽（ANP）和一氧化氮（NO）。","","N"],["2022-N14",10,"第5节 肾上腺内分泌","对物质代谢的影响",2022,14,"A","","肾上腺糖皮质激素分泌过多可引起的效应是",[["A","肝外组织蛋白质合成增加"],["B","骨质疏松"],["C","血管舒张"],["D","血糖降低"]],"B","糖皮质激素（GC）在体内的作用广泛而复杂。（1）对物质代谢的影响：①糖代谢：GC是调节糖代谢的重要激素之一，因能显著升高血糖而得名。因此GC缺乏将导致低血糖，而GC过多则可升高血糖（D错）。②脂肪代谢：GC对脂肪组织的主要作用是提高四肢部分的脂肪酶活性，促进脂肪分解，使血浆中的脂肪酸浓度增加，并向肝脏转移，增强脂肪酸在肝内的氧化，以利于肝糖原异生。③蛋白质代谢：GC对肝内和肝外组织细胞的蛋白质代谢影响不同。GC能抑制肝外组织细胞内的蛋白质合成（A错），加速其分解，减少氨基酸转运入肌肉等肝外组织，为糖异生提供原料；相反，却能促进肝外组织产生的氨基酸转运入肝，提高肝内蛋白质合成酶的活性，使肝内蛋白质合成增加，血浆蛋白也相应增加。因此，当糖皮质激素分泌过多时，可出现肌肉消瘦、骨质疏松、皮肤变薄等体征（B对）。（2）参与应激反应。（3）对组织器官活动的影响：1）对血细胞的影响：GC可增强骨髓造血功能，使血液中红细胞、血小板数量增加；2）对循环系统的作用：①提高心肌、血管平滑肌对儿茶酚胺的敏感性（允许作用），加强心肌收缩力，增加血管紧张度（C错），以维持正常血压。②抑制前列腺素的合成，降低毛细血管的通透性，减少血浆滤过，有利于维持循环血量。3）对胃肠道的影响：GC可促进胃腺分泌盐酸和胃蛋白酶原，也可增高胃腺细胞对迷走神经与促胃液素的反应性，故长期大量应用GC易诱发或加重消化性溃疡。4）调节水盐代谢。","","N"],["2022-N15",10,"第6节 胰岛内分泌","神经调节",2022,15,"A","","可以抑制胰岛素分泌的因素是",[["A","血液中游离脂肪酸增多"],["B","抑胃肽分泌增加"],["C","交感神经兴奋"],["D","生长激素分泌增加"]],"C","胰岛素分泌活动受到营养物质、神经体液等诸多因素的调节：（1）营养成分的调节作用：①血中葡萄糖浓度升高时，胰岛素分泌明显增加。②血中氨基酸和脂肪酸增多时（A错）也能促进胰岛素分泌。（2）激素的调节作用：①胰岛激素：胰岛分泌的多种激素可以通过细胞间的旁分泌方式对胰岛β细胞的功能进行调节。②胃肠激素：促胃液素、促胰液素、缩胆囊素、抑胃肽（GIP）（B错）等胃肠激素可促进胰岛素分泌。③其他激素：生长激素（D错）、糖皮质激素、甲状腺激素等可通过升高血糖浓度间接刺激胰岛素的分泌。（3）神经调节：胰岛β细胞受迷走神经和交感神经的双重支配。交感神经兴奋时（C对）释放去甲肾上腺素，可通过作用于β细胞膜上的α受体抑制胰岛素分泌，也可通过β受体刺激胰岛素分泌（在α受体阻断的情况下），但以前者作用为主。","","N"],["2022-N16",11,"第2节 女性生殖功能及其调节","月经周期的分期",2022,16,"A","","育龄期女性子宫内膜周期性变化的序列是",[["A","月经期-增生期-分泌期"],["B","月经期-分泌期-增生期"],["C","增生期-排卵期-分泌期"],["D","增生期-分泌期-排卵期"]],"A","受激素水平影响，育龄期女性子宫内膜依次呈现月经期-增生期-分泌期（A对）的周期性变化。月经期是月经周期开始的几天，月经期血中雌、孕激素水平降低，给子宫内膜供血的螺旋小动脉出现痉挛性收缩，使子宫内膜组织发生缺血、变性、坏死，最后剥脱，血管破裂，出血。月经期结束后，进入卵泡期（增生期），该期卵泡快速发育，分泌的雌激素逐渐增加，因月经损伤的子宫内膜开始修复，生长增厚。卵泡期末，发育成熟的卵泡在雌激素和LH分泌高峰的刺激下破裂，完成排卵。排卵后形成黄体，进入黄体期（分泌期），黄体分泌大量孕激素和雌激素，子宫内膜进一步增厚，同时分泌功能增强。如果排卵后没有发生受精、着床，则黄体萎缩退化，血中雌、孕激素水平再次降低，进入下一个月经周期。","","N"],["2022-N116",3,"第3节 血管生理","影响动脉血压的因素",2022,116,"B","","每搏输出量增加，血压的变化是",[["A","收缩压升高，舒张压升高，脉压增大"],["B","收缩压下降，舒张压下降，脉压减小"],["C","收缩压下降，舒张压升高，脉压减小"],["D","收缩压升高，舒张压下降，脉压增大"]],"A","每搏输出量的改变主要影响收缩压。每搏出量增加时，心缩期射入主动脉的血量增多，动脉管壁所承受的压强也增大，故收缩压明显升高。由于动脉血压升高，血流速度随之加快，在心舒期末存留在大动脉中的血量增加不多，舒张压的升高相对较小，故脉压增大（A对）。收缩压下降，舒张压下降，脉压减小（B错）见于每搏输出量减少时。收缩压升高，舒张压下降，脉压增大（D错）见于动脉管壁硬化时。","","N"],["2022-N117",3,"第3节 血管生理","影响动脉血压的因素",2022,117,"B","","大动脉硬化时，血压的变化是",[["A","收缩压升高，舒张压升高，脉压增大"],["B","收缩压下降，舒张压下降，脉压减小"],["C","收缩压下降，舒张压升高，脉压减小"],["D","收缩压升高，舒张压下降，脉压增大"]],"D","大动脉硬化时，管壁弹性纤维减少而胶原纤维增多，导致血管可扩张性降低，大动脉的弹性贮器作用减弱，对血压的缓冲作用减弱，因而收缩压增高而舒张压降低，结果使脉压明显增大（D对）。收缩压升高，舒张压升高，脉压增大（A错）见于每搏输出量增加时。收缩压下降，舒张压下降，脉压减小（B错）见于每搏输出量减少时。","","N"],["2022-N118",7,"第3节 肾小管和集合管的物质转运功能","葡萄糖和氨基酸的重吸收",2022,118,"B","","肾脏重吸收葡萄糖的主要部位是",[["A","近端小管"],["B","髓袢"],["C","远曲小管"],["D","集合管内髓段"]],"A","微穿刺实验证明，滤过的葡萄糖均在近端小管，特别是近端小管（A对）的前半段被重吸收。小管液中的葡萄糖是通过近端小管上皮细胞顶端膜中的Na⁺葡萄糖同向转运体，以继发性主动转运的方式被转入细胞的。","","N"],["2022-N119",7,"第3节 肾小管和集合管的物质转运功能","尿素的重吸收与排泄",2022,119,"B","","尿素最容易通透的部位是",[["A","近端小管"],["B","髓袢"],["C","远曲小管"],["D","集合管内髓段"]],"D","尿素最容易通透的部位是集合管内髓部（D对），内髓部集合管末端依赖抗利尿激素调控的尿素通道蛋白UT-A1和UT-A3对尿素高度通透，使浓缩的尿素扩散到内髓部组织。","","N"],["2022-N136",0,"第6节 人体内自动控制系统","负反馈控制系统",2022,136,"X","","负反馈的特征包括",[["A","其控制系统是一个闭合的环路"],["B","都有一个调定点"],["C","没有纠正偏差的功效"],["D","数量比正反馈少"]],"AB","来自受控部分的输出信息反馈调整控制部分的活动，最终使受控部分的活动向与其原先活动的相反方向改变，称为负反馈。负反馈控制系统是个闭环的控制系统（A对）。负反馈系统都有一个相应的调定点（B对），负反馈机制对受控部分活动的调节就是以这个调定点为参照，将受控部分的活动控制在调定点附近的狭小范围内。负反馈调节具有纠正偏差的作用（C错），从而使机体的内环境处于相对恒定的状态。在正常生理情况下，体内的控制系统绝大多数都属于负反馈控制系统，负反馈系统的数量要远多于正反馈系统（D错）。","","N"],["2022-N137",1,"第3节 细胞的电活动","局部电位的特征和意义",2022,137,"X","","局部电位的特征包括",[["A","非“全或无”"],["B","电紧张性扩布"],["C","无不应期"],["D","可以总和"]],"ABCD","局部电位的特征包括：①非“全或无”（A对），为等级性电位，即其幅度与刺激强度相关。②衰减性传导，以电紧张的方式向外扩布（B对）。③无不应期（C对），反应可以叠加总和（D对），其中相距较近的多个局部反应同时产生的叠加称为空间总和，多个局部反应先后产生的叠加称为时间总和。","","N"],["2022-N138",5,"第3节 胃内消化","胃的运动形式",2022,138,"X","","胃的运动形式包括",[["A","紧张性收缩"],["B","蠕动"],["C","分节运动"],["D","容受性舒张"]],"ABD","胃的运动形式包括紧张性收缩（A对）、蠕动（B对）和容受性舒张（D对）。分节运动（C错）可见于小肠（十版生理学P183），分节推进见于大肠（十版生理学P187）。","","N"],["2022-N139",6,"第2节 体温及其调节","产热的形式",2022,139,"X","","寒战产热的特点包括",[["A","屈肌和伸肌同时收缩"],["B","肌肉收缩转化为外功"],["C","常见于新生儿"],["D","寒战产热前出现肌紧张"]],"AD","寒战产热又称战栗产热，其特点包括：屈肌和伸肌同时发生不随意的节律性收缩（A对），此时肌肉收缩活动不做外功（B错），能量全部转化为热量。在寒冷环境下，寒战产热前出现肌紧张（D对），在此基础上出现战栗，可使产热量明显增多。新生儿体温调节功能尚不完善，不能发生战栗（C错），故寒冷条件下主要依赖代谢性产热维持体温。","","N"],["2022-N140",8,"第4节 听觉","骨传导",2022,140,"X","","听觉骨传导的结构包括",[["A","颅骨"],["B","圆窗膜"],["C","听骨链"],["D","耳蜗骨壁"]],"AD","听觉骨传导的结构包括颅骨（A对）和耳蜗骨壁（D对）。声波直接作用于颅骨，经颅骨和耳蜗骨壁传入耳蜗，此途径称为骨传导。卵圆窗膜（B错）和听骨链（C错）是气传导的结构。","","N"],["2022-N141",9,"第6节 脑的高级功能","学习的形式",2022,141,"X","","非联合型学习包括",[["A","习惯化"],["B","敏感化"],["C","条件反射"],["D","长时程增强"]],"ABD","学习有两种形式，非联合型学习和联合型学习。非联合型学习不需要在刺激的反应之间形成某种明确的联系，突触可塑性改变引起习惯化（A对）和敏感化（B对）符合非联合型学习模式。 突触可塑性是指突触的形态和功能可发生较为持久的改变的特性或现象，目前被认为是学习和记忆产生机制的生理学基础， 其中长时程增强（LTP）（D对）已被公认为是脊椎动物学习和记忆机制在细胞水平的基础，故广义上也属于非联合型学习的范畴。联合型学习为一种复杂的学习形式，如经典的条件反射和更为复杂的操作式的条件反射（C错），人类的学习方式多数为联合型学习。","","N"],["2023-N1",0,"第6节 人体内自动控制系统","前馈",2023,1,"A","","下列生理活动中，存在前馈控制的是",[["A","动脉血压在压力感受性反射作用下维持稳定"],["B","脚踩铁钉引起受刺激肢体的回撤反射"],["C","长期大剂量使用可的松引起肾上腺皮质萎缩"],["D","百米赛跑起跑枪声未响前运动员心率加快"]],"D","机体的控制系统主要包括反馈控制系统和前馈控制系统。前馈系统是指当控制部分发出信号，指令受控部分进行某一活动时，受控部分不发出反馈信号，而是由某一监测装置在受到刺激后发出前馈信号，作用于控制部分，使其及早作出适应性反应，及时地调控受控部分的活动，百米比赛枪响开始之前心跳加快（D对）属于前馈控制系统的典型例子，有助于提前适应赛跑时机体血供和耗氧量增加的需要，更富有预见性和适应性。反馈控制系统包括负反馈和正反馈，正常生理情况下，体内的控制系统绝大多数都属于负反馈控制系统，例如动脉血压在压力感受性反射作用下维持稳定（A错），当机体的动脉血压突然升高时，分布在主动脉弓和颈动脉窦的压力感受器就能感受到这一变化，并将这一信息通过迷走神经和舌咽神经反馈到心血管中枢，经中枢的整合、比较、分析后，通过传出神经支配心脏和血管的活动，使动脉血压回降至调定点的相应水平。脚踩铁钉后立即出现的退缩反应（B错）为神经反射中的非条件反射，不属于前馈控制系统。长期大剂量使用可的松（C错）会负反馈抑制下丘脑CRH神经元及腺垂体ACTH细胞，使CRH与ACTH的合成和分泌减少，导致患者肾上腺皮质束状带和网状带的萎缩，分泌功能减退或停止。","","N"],["2023-N2",1,"第1节 细胞膜的物质转运功能","单纯扩散",2023,2,"A","","以单纯扩散进出细胞的物质是",[["A","葡萄糖"],["B","氨基酸"],["C","肽类激素"],["D","甘油"]],"D","单纯扩散是指物质从质膜的高浓度一侧通过脂质分子间隙向低浓度一侧进行的跨膜扩散，经单纯扩散转运的物质都是脂溶性（非极性）物质或少数不带电荷的极性小分子，甘油（D对）属于脂溶性物质，经单纯扩散进出细胞。葡萄糖（A错）和氨基酸（B错）进入肠黏膜上皮细胞和肾小管上皮细胞属于继发性主动转运，除以上细胞属于经载体介导的易化扩散；出入红细胞和脑细胞等其他细胞属于经载体介导的易化扩散。肽类激素（C错）分子质量比较大，不能直接穿过细胞膜，需要以囊泡的形式进行跨膜转运（膜泡运输）。","","N"],["2023-N3",1,"第4节 肌细胞的收缩","肌丝的分子结构",2023,3,"A","","横纹肌收缩过程中，与横桥结合的蛋白质是",[["A","肌钙蛋白"],["B","原肌球蛋白"],["C","肌动蛋白"],["D","钙调蛋白"]],"C","肌原纤维由粗肌丝和细肌丝组成，粗肌丝由肌球蛋白（肌凝蛋白）组成，上有横桥结构，具有ATP酶活性。细肌丝由肌动蛋白（肌纤蛋白）、原肌球蛋白（原肌凝蛋白）和肌钙蛋白三种蛋白质组成。在肌肉舒张状态时，肌动蛋白上的横桥结合位点被原肌球蛋白（B错）所掩盖，当胞质中Ca²⁺浓度升高时，Ca²⁺与肌钙蛋白（A错）结合，使肌钙蛋白构象改变，促使与肌钙蛋白结合的原肌球蛋白发生移动，暴露肌动蛋白上的横桥结合位点，引发横桥与肌动蛋白结合（C对），导致肌肉收缩。钙调蛋白（CaM）（D错）在平滑肌收缩过程中发挥作用（十版生理学P51）。","","N"],["2023-N4",2,"第4节 血型和输血原则","Rh血型系统",2023,4,"A","","Rh阳性血型红细胞膜表面的Rh抗原是",[["A","A抗原"],["B","B抗原"],["C","H抗原"],["D","D抗原"]],"D","人类血型系统中与临床关系最密切的是ABO血型系统和Rh血型系统。ABO血型系统的抗原包括A（A错）、B（B错）、H抗原（C错）。Rh血型的抗原包括D、E、C、c、e，其中D抗原的抗原性最强，临床意义最为重要，通常将红细胞上含有D抗原（D对）者称为Rh阳性，而红细胞上缺乏D抗原者称为Rh阴性。","","N"],["2023-N5",3,"第1节 心脏的泵血功能","心室收缩期",2023,5,"A","","在一个心动周期中，第一心音出现的时期是",[["A","等容收缩期"],["B","等容舒张期"],["C","快速射血期"],["D","减慢射血期"]],"A","在心动周期中，心房和心室按照一定的次序和时程先后进行活动，进而依次产生四个心音。心室开始收缩后，心室内的压力升高，当室内压升高到超过房内压时，房室瓣关闭引起心室内血液和室壁的振动，第一心音产生，此时半月瓣仍处于关闭状态，从房室瓣关闭到主动脉瓣开启前的这段时期，心室的收缩不能改变心室的容积，称为等容收缩期（A对）；当心室内压升高至超过主动脉压时半月瓣开放，心动周期进入射血期，在射血的早期，心室射入主动脉的血液量较多，血液流速也很快，称为快速射血期（C错）；在射血的后期，心室收缩强度减弱，射血的速度逐渐减慢，故称为减慢射血期（D错）；心室射血完成后，心室开始舒张，半月瓣关闭，形成第二心音，此时房室瓣处于关闭状态，从半月瓣关闭至房室瓣开启前的这一段时间内，心室舒张而心室的容积并不改变，为等容舒张期（B错）。心动周期中，四个心音依次出现的时期为等容收缩期、等容舒张期、快速充盈期和心房收缩期。","","N"],["2023-N6",3,"第2节 心脏的电生理学及生理特性","心室肌细胞动作电位",2023,6,"A","","在心室肌细胞静息电位和动作电位平台期均发挥作用的离子流是",[["A","IK"],["B","IK1"],["C","ICa-L"],["D","ICa-T"]],"B","心室肌细胞静息电位的离子流有内向整流钾电流、钠背景电流、泵电流，其中内向整流钾电流（Iₖ₁）引起的K⁺平衡电位构成了心室肌细胞静息电位的主要成分；而在动作电位平台期（2期）的离子流包括内向电流的L型钙电流（ICa-L）和慢失活的INa、Na⁺-Ca²⁺交换电流(INa-Ca)，外向电流的内向整流钾电流（Iₖ₁）、延迟整流钾电流Iₖ和钠泵活动引起的泵电流，其中内向整流钾电流（Iₖ₁）的内向整流特性是造成平台期持续时间较长的重要原因。故在心室肌细胞静息电位和动作电位平台期均发挥作用的离子流是Iₖ₁（B对）。Iₖ（延迟整流钾电流）（A错）是平台期晚期导致膜复极化的主要离子电流（十版生理学P92），在静息电位的维持中不发挥作用。ICa-L（L型钙电流）（C错）是平台期的主要去极化离子流（十版生理学P92），不参与静息电位的维持。ICa-T（T型钙电流）（D错）是在窦房结P细胞4期自动去极化后期发挥作用的离子流（十版生理学P94）。","","N"],["2023-N7",4,"第1节 肺通气","弹性阻力和顺应性",2023,7,"A","","合成和分泌肺表面活性物质的细胞是",[["A","肺泡Ⅰ型上皮细胞"],["B","肺泡Ⅱ型上皮细胞"],["C","肺间质细胞"],["D","肥大细胞"]],"B","肺泡上皮由肺泡Ⅰ型上皮细胞和肺泡Ⅱ型上皮细胞组成，其中Ⅰ型细胞（A错）是普通的肺泡上皮细胞，覆盖了肺泡95%的表面积，是进行气体交换的部位；Ⅱ型细胞具有分泌功能，能够合成和分泌肺表面活性物质（B对），降低肺泡表面张力，稳定肺泡大小。肺间质细胞（C错）包括成纤维细胞、平滑肌细胞，及各类炎症细胞、免疫细胞等。肥大细胞（D错）是一种免疫细胞，主要存在于组织中，如皮肤、呼吸道和肠道等。肥大细胞起源于骨髓干细胞，其功能包括调节炎症反应、抗感染、参与细胞介导的免疫反应等。","","N"],["2023-N8",5,"第3节 胃内消化","胃和十二指肠黏膜的细胞保护作用",2023,8,"A","","胃和十二指肠黏膜中含有抑制胃酸和胃蛋白酶原分泌的物质是",[["A","HCO₃⁻"],["B","前列腺素"],["C","缩胆囊素"],["D","组胺"]],"B","胃和十二指肠易受到各种理化因素的刺激，也接受黏膜细胞的保护作用，以减轻有害刺激对细胞的损伤。其中一个重要机制为胃和十二指肠黏膜和肌层中含有高浓度的前列腺素（B对）和表皮生长因子，它们能抑制胃酸和胃蛋白酶原的分泌，刺激黏液和碳酸氢盐的分泌，使胃黏膜的微血管扩张，增加黏膜的血流量，有助于胃黏膜的修复和维持其完整性。胃黏膜内的非泌酸细胞能分泌HCO₃⁻（A错），与胃黏膜表面的黏液联合形成黏液－碳酸氢盐屏障，保护胃黏膜免受胃内盐酸和胃蛋白酶的损伤，但并不能抑制胃酸和胃蛋白酶原分泌。缩胆囊素（C错）对胃酸的分泌主要表现为抑制效应（十版生理学P177），但会促进胃蛋白酶原的分泌（十版生理学P177）。组胺（D错）具有极强的促胃酸分泌作用，不属于胃和十二指肠黏膜的保护因素。","","N"],["2023-N9",6,"第2节 体温及其调节","不感蒸发",2023,9,"A","","一般情况下，人体24小时的不感蒸发量约是",[["A","200ml"],["B","600ml"],["C","1000ml"],["D","1500ml"]],"C","不感蒸发是指体内的水分从皮肤和黏膜（主要是呼吸道黏膜）表面不被人们所察觉地渗出而被汽化的过程，一般情况下人体24小时的不感蒸发量约为1000ml（C对），在临床上给患者补液时，应注意补充不感蒸发丢失的体液量。","","N"],["2023-N10",7,"第5节 尿生成的调节","概述",2023,10,"A","","肾脏在对尿液浓缩和稀释、实现机体水平衡的调节中，起关键作用的活性物质是",[["A","肾素"],["B","醛固酮"],["C","血管升压素"],["D","血管紧张素"]],"C","尿液的浓缩与稀释一方面取决于肾髓质渗透梯度，另一方面取决于集合管对水的通透性，血管升压素（抗利尿激素）（C对）可通过调节水通道蛋白的表达，进而调节集合管对水的通透性。肾素（A错）－血管紧张素（D错）－醛固酮（B错）系统主要是在体内细胞外液量和（或）循环血量不足时，通过调节减少尿量使细胞外液量和（或）循环血量以及动脉血压恢复正常。","","N"],["2023-N11",7,"第3节 肾小管和集合管的物质转运功能","HCO₃⁻的重吸收与H⁺的分泌",2023,11,"A","","肾小管在通过泌酸而维持机体酸碱平衡中具有重要作用的酶是",[["A","环加氧酶"],["B","碳酸酐酶"],["C","磷酸二酯酶"],["D","钠-钾ATP酶"]],"B","肾小管泌H⁺由上皮细胞顶端膜Na⁺-H⁺交换体介导，小管液中的Na⁺顺浓度梯度被重吸收进上皮细胞的同时，上皮细胞的H⁺被分泌到小管液中，进入小管液的H⁺，经上皮细胞顶端膜上的碳酸酐酶（B对）催化，与HCO₃⁻结合为H₂CO₃，又很快解离成CO₂和水， CO₂以单纯扩散的方式进入上皮细胞，在细胞内，CO₂和细胞内的水又在碳酸酐酶的催化下形成H₂CO₃，后者又很快解离成H⁺与HCO₃⁻，H⁺再次通过上皮细胞顶端膜Na⁺-H⁺逆向转运进入小管液，如此反复循环，实现肾小管泌H⁺过程。环加氧酶（COX）（A错）是动物体内前列腺素生成的限速酶，可催化花生四烯酸转化为前列腺素（十版生理学P65）。磷酸二酯酶（PDEs）（C错）能够水解细胞内cAMP或cGMP，终止第二信使传导的信号。钠-钾ATP酶即钠泵，存在于肾小管细胞基底侧膜上，可维持上皮细胞内的低Na⁺环境，为肾小管Na⁺-H⁺交换提供动力，间接促进肾小管的泌H⁺过程，故钠-钾ATP酶在肾小管通过泌H⁺维持机体酸碱平衡的过程中也间接发挥了重要作用，D选项存在争议。","","N"],["2023-N12",9,"第1节 神经系统功能活动的基本原理","影响突触后膜反应的因素",2023,12,"A","","应用筒箭毒碱松弛骨骼肌的作用机制是",[["A","抑制突触前膜ACh囊泡的动员"],["B","抑制突触前膜ACh囊泡的着位"],["C","增强乙酰胆碱酯酶的活性"],["D","阻断神经-肌接头终板膜受体"]],"D","骨骼肌收缩依赖于神经-肌接头（一种特化的化学突触）处的兴奋传递，影响兴奋传递的因素包括影响递质释放的因素、影响已释放递质清除的因素和影响受体的因素三大类。本题中筒箭毒碱属于影响受体的因素，通过阻断神经-肌接头终板膜上的N₂-ACh受体，可以阻断神经-肌接头的兴奋传递过程，达到肌肉松弛的作用（D对）。","","N"],["2023-N13",9,"第1节 神经系统功能活动的基本原理","NE和肾上腺素及其受体",2023,13,"A","","下列自主神经节后纤维中，属于交感肾上腺素能纤维的是",[["A","支配全身小汗腺的神经纤维"],["B","引起骨骼肌血管舒张的神经纤维"],["C","引起大量稀薄唾液分泌的神经纤维"],["D","寒冷时使皮肤血管收缩的神经纤维"]],"D","以肾上腺素（以肾上腺素为递质的肾上腺素能纤维目前仅见于中枢神经系统内）或去甲肾上腺素为递质的神经纤维均称为肾上腺素能纤维，大部分交感神经节后纤维均为肾上腺素能纤维，当机体处于寒冷时，交感神经兴奋，受交感-肾上腺素能纤维支配的皮肤血管收缩（D对），血流量减少，以减少通过皮肤产生的散热。以乙酰胆碱为递质的神经纤维称为胆碱能纤维，在外周，支配骨骼肌的运动神经纤维、大多数副交感节后纤维、少数交感节后纤维（如支配全身小汗腺的神经纤维和引起骨骼肌血管舒张的神经纤维）（AB错）都属于胆碱能纤维。交感和副交感神经支配有时对某一器官的作用可以是一致的，例如交感和副交感神经都有促进唾液腺分泌的作用，但交感神经促使少量黏稠唾液分泌，而副交感神经则引起大量稀薄唾液的分泌（C错）。","","N"],["2023-N14",8,"第3节 视觉","晶状体变凸",2023,14,"A","","当被视物体由远移近时，不会出现的眼调节活动是",[["A","双眼球会聚"],["B","晶状体变凸"],["C","瞳孔调节反射"],["D","瞳孔对光反射"]],"D","当被视物体由远移近时，眼将发生一系列调节，这一系列调节称为眼的近反射。主要包括：（1）晶状体变凸（B对），这是由于眼视近物时睫状肌收缩，导致连接于晶状体囊的悬韧带松弛，晶状体因其自身的弹性而向前和向后凸出，有利于物像落于视网膜上；（2）瞳孔缩小，视近物时，可反射性地引起双眼瞳孔缩小，称为瞳孔近反射（瞳孔调节反射）（C对），其意义在于减少折光系统的球面像差和色像差呈色彩模糊的现象，使成像更清晰；（3）视轴会聚（A对），是指眼视近物时，两眼视轴向鼻侧会聚的现象，其意义在于两眼同时看一近物时，物像仍可落在两眼视网膜的对称点上，以避免形成复视。瞳孔对光反射（D错，为本题正确答案）是指瞳孔在强光照射时缩小而在光线变弱时散大的反射，它是眼的一种适应功能，与视近物无关，其意义在于调节进入眼内的光量，使视网膜不至于因光量过强而受到损害，也不会因光线过弱而影响视觉。","","N"],["2023-N15",10,"第3节 甲状腺内分泌","调节新陈代谢",2023,15,"A","","甲状腺功能亢进症患者不会出现的表现是",[["A","心力衰竭"],["B","精神亢进"],["C","骨质疏松"],["D","低血糖"]],"D","甲状腺激素（TH）几乎作用于机体的所有组织，从多方面调节新陈代谢和生长发育，并影响器官系统功能。在调节糖代谢方面，甲状腺激素可加速肠黏膜吸收葡萄糖、促进肝糖异生，同时又能增强肾上腺素、胰高血糖素、皮质醇和生长激素的生糖效应，升高血糖水平，但甲状腺激素同时能加强外周组织对糖的利用，也能降低血糖，但总体而言，甲状腺激素升血糖的作用强于降血糖作用，甲亢患者往往表现为糖耐量减低或轻型糖尿病（D错，为本题正确答案）；在调节蛋白质代谢方面，甲状腺激素过量分泌时（甲状腺功能亢进患者），可使骨骼肌为主的外周组织蛋白分解加速，骨基质蛋白质分解，Ca²⁺析出，导致血钙升高，骨质疏松（C对）；在影响器官系统功能方面，对神经系统而言，TH对已分化成熟的成年人神经系统的活动主要起兴奋作用，因此甲状腺功能亢进患者常有易激动、烦躁不安、喜怒无常、失眠多梦、注意力分散等精神亢进表现（B对）；对心血管系统而言，TH可使心率增快、心肌收缩力增强、心输出量和心肌耗氧量增加，因此甲状腺功能亢进患者可出现心动过速、心律失常甚至心力衰竭（A对）。","","N"],["2023-N16",11,"第1节 男性生殖功能及其调节","下丘脑－垂体－睾丸轴的调节",2023,16,"A","","由睾丸合成和分泌的抑制素的生理作用是",[["A","抑制GnRH分泌"],["B","抑制FSH分泌"],["C","抑制LH分泌"],["D","抑制睾酮分泌"]],"B","睾丸功能受下丘脑－垂体－睾丸轴的调节，使其生精和内分泌功能能够维持在适当的水平。青春期开始后，下丘脑合成和分泌GnRH（促性腺激素释放激素），GnRH作用于腺垂体，促进其分泌FSH（卵泡刺激素）和LH（黄体生成素），FSH可作用于支持细胞，启动生精，LH则作用于间质细胞，促进睾酮分泌。当血中睾酮浓度达到一定水平后，可通过负反馈机制直接抑制腺垂体分泌LH，同时也可通过降低腺垂体对 GnRH 的反应性等机制抑制下丘脑分泌GnRH（A错），进而间接抑制腺垂体FSH和LH 的分泌。而睾丸支持细胞在FSH的作用下分泌抑制素，可选择性地抑制腺垂体FSH的合成和分泌（B对），但对LH的分泌没有明显影响（C错），也不会影响睾酮分泌（D错）。","","N"],["2023-N116",3,"第3节 血管生理","影响动脉血压的因素",2023,116,"B","","主要导致舒张压上升的因素是",[["A","外周阻力增加"],["B","心输出量增加"],["C","主动脉和大动脉硬化"],["D","循环血量增加"]],"A","舒张压的高低主要反映外周阻力的大小，当外周阻力增加时，心脏舒张期内血液外流的速度减慢，舒张压明显升高（A对），而心脏收缩期内，动脉血压升高使得血流速度加快，使得收缩压升高不如舒张压升高明显。心输出量为每搏输出量和心率的乘积，当心输出量增加时，可能是每搏输出量增加，也可能是心率在一定范围内的增加。每搏输出量的改变主要影响收缩压，每搏出量增加时，心缩期射入主动脉的血量增多，动脉管壁所承受的压强也增大，故收缩压明显升高。由于动脉血压升高，血流速度随之加快，在心舒期末存留在大动脉中的血量增加不多，舒张压的升高相对较小。而心率增加时，心室舒张期明显缩短，心舒期从大动脉流向外周的血量减少，存留在主动脉内的血量增多，致使舒张压明显升高，由于舒张期末主动脉内存留的血量增多，使心缩期主动脉内血量增多，收缩压也相应升高，但由于血压升高使血流速度加快，在心缩期有较多的血液流向外周，使收缩压升高程度较小。故心率增加引起的心输出量增加，主要影响舒张压升高，B选项存在争议。主动脉和大动脉硬化时，管壁弹性纤维减少而胶原纤维增多，大动脉的弹性贮器作用减弱，对血压的缓冲作用减弱，因而收缩压增高而舒张压降低（C错）。循环血量主要影响循环系统平均充盈压（D错），平均充盈压是血压形成的重要前提。","","N"],["2023-N117",3,"第3节 血管生理","影响动脉血压的因素",2023,117,"B","","导致脉压增加的因素是",[["A","外周阻力增加"],["B","心输出量增加"],["C","主动脉和大动脉硬化"],["D","循环血量增加"]],"C","脉压是指收缩压和舒张压的差值。主动脉和大动脉硬化时，管壁弹性纤维减少而胶原纤维增多，大动脉的弹性贮器作用减弱，对血压的缓冲作用减弱，因而收缩压增高而舒张压降低，结果使脉压明显增大（C对）。外周阻力的改变主要影响舒张压，外周阻力增大时，心舒期内血液外流速度减慢，因而舒张压明显升高；在心缩期，动脉血压升高使得血流速度加快，因而收缩压升高不如舒张压升高明显，故脉压减小（A错）。心输出量为每搏输出量和心率的乘积，当心输出量增加时，可能是每搏输出量增加，也可能是心率在一定范围内的加快。每搏输出量的改变主要影响收缩压，搏出量增加时，心缩期射入主动脉的血量增多，动脉管壁所承受的压强也增大，故收缩压明显升高；由于动脉血压升高，血流速度加快，在心舒期末存留在大动脉中的血量增加不多，舒张压的升高相对较小，故脉压增大；心率加快时，心室舒张期明显缩短，因此在心舒期从大动脉流向外周的血量减少，存留在主动脉内的血量增多，致使舒张压明显升高；由于舒张期末主动脉内存留的血量增多，致使心缩期主动脉内血量增多，收缩压也相应升高，但由于血压升高使血流速度加快，在心缩期有较多的血液流向外周，使收缩压升高程度较小，则脉压减小（B错）。生理情况下，循环血量与血管系统容量是相匹配的，即循环血量略多于血管系统容量，使之产生一定的循环系统平均充盈压，这是血压形成的重要前提，平均充盈压由循环血量和血管系统容量的比例决定，单纯循环血量增加，无法判断其对脉压的影响（D错）。","","N"],["2023-N118",10,"第4节 甲状旁腺、维生素D与甲状腺C细胞内分泌","甲状旁腺激素的生理作用",2023,118,"B","","能使血钙升高、血磷降低的活性物质是",[["A","甲状旁腺激素"],["B","1，25-（OH）₂D₃"],["C","甲状腺激素"],["D","生长激素"]],"A","甲状旁腺激素（PTH）、1，25-（OH）₂D₃（钙三醇）和降钙素是体内共同调节钙、磷代谢稳态的三种基础激素。甲状旁腺激素主要由甲状旁腺主细胞合成和分泌，通过调节肾小管对钙、磷的重吸收以及促进骨钙入血调节血钙和血磷，其总效应是升高血钙和降低血磷（A对）。1，25-（OH）₂D₃是维生素D₃经过肝脏和肾脏羟化生成的活性形式，通过促进小肠黏膜上皮细胞对钙的吸收、促进骨吸收效应（大于骨形成效应），及协同PTH促进肾小管对钙和磷的重吸收，进而升高血钙和血磷（B错）。甲状腺激素（C错）和生长激素（D错）不是调节血钙和血磷的主要激素，研究表明二者均有升血钙和升血磷的作用。","","N"],["2023-N119",10,"第4节 甲状旁腺、维生素D与甲状腺C细胞内分泌","1,25-二羟维生素D₃的生理作用",2023,119,"B","","能使血钙和血磷都升高的活性物质是",[["A","甲状旁腺激素"],["B","1，25-（OH）₂D₃"],["C","甲状腺激素"],["D","生长激素"]],"B","甲状旁腺激素、1，25-（OH）₂D₃和降钙素是体内共同调节钙、磷代谢稳态的三种基础激素。1，25-（OH）₂D₃（钙三醇）是维生素D₃经过肝脏和肾脏羟化生成的活性形式，通过促进小肠黏膜上皮细胞对钙的吸收，促进骨吸收效应大于骨形成效应，协同PTH促进肾小管对钙和磷的重吸收，进而升高血钙和血磷（B对）。甲状旁腺激素、1，25-（OH）₂D₃和降钙素是体内共同调节钙、磷代谢稳态的三种基础激素。PTH主要由甲状旁腺主细胞合成和分泌，通过调节肾小管对钙、磷的重吸收以及促进骨钙入血调节血钙和血磷，其总效应是升高血钙和降低血磷（A错）。甲状腺激素（C）和生长激素（D）不是调节血钙和血磷的主要激素，但研究表明二者均有升血钙和升血磷的作用，CD选项存在争议。","","N"],["2023-N136",1,"第3节 细胞的电活动","钠泵的生电作用",2023,136,"X","","影响静息电位的因素有",[["A","细胞外液的K⁺浓度"],["B","细胞外液的Ca²⁺浓度"],["C","膜对K⁺和Na⁺的相对通透性"],["D","钠泵活动水平"]],"ACD","静息电位主要是由于安静时细胞膜K⁺通透性较大，K⁺顺浓度梯度由细胞内向细胞外扩散而形成的。当细胞外K⁺浓度升高（如高血钾）时，K⁺平衡电位减小，静息电位也相应减小，故细胞外液的K⁺浓度（A对）能影响细胞静息电位。如果膜对K⁺的通透性增大，静息电位将增大（更趋向于K⁺的平衡电位）；反之，膜对Na⁺的通透性增大，则静息电位减小（更趋向于Na⁺的平衡电位），故膜对K⁺和Na⁺的相对通透性（C对）也能影响细胞静息电位。钠泵每次活动都会使3个Na⁺移出胞外、2个K⁺移入胞内，产生一个正电荷的净外移，故钠泵具有生电效应，钠泵活动水平（D对），其生电效应改变，膜发生一定程度的超极化或去极化，静息电位可在一定程度增大或减小。细胞外液的Ca²⁺浓度（B错）可影响钠通道的激活（十版生理学P36），主要影响动作电位的阈电位水平。","","N"],["2023-N137",2,"第3节 生理性止血","生理性抗凝物质",2023,137,"X","","属于生理性抗凝物质的有",[["A","蛋白质C"],["B","组织因子途径抑制物"],["C","纤溶酶原激活物抑制物-1"],["D","肝素"]],"ABD","体内的生理性抗凝物质主要包括丝氨酸蛋白酶抑制物、蛋白质C系统、组织因子途径抑制物和肝素。蛋白C系统包括蛋白质C（A对）（PC）、凝血酶调节蛋白、蛋白质S和蛋白质C的抑制物，可灭活FⅧa和FⅤa，有助于避免凝血过程向周围正常血管部位扩展。组织因子途径抑制物质（TFPI）（B对）是主要的生理性抗凝物质，由血管内皮细胞产生，可与FⅩa和FⅦa-组织因子复合物结合抑制其活性，是外源性凝血途径的特异性抑制物。肝素（D对）首先从肝脏发现而得名，主要由肥大细胞和嗜碱性粒细胞产生，既可增强抗凝血酶的活性而发挥间接抗凝作用，也可促进结合于血管内皮细胞表面的TFPI（组织因子途径抑制物） 释放，使血浆TFPI水平升高，故肝素在体内的抗凝作用强于体外。纤溶酶原激活物抑制物-1（PAl-1）（C错）属于纤溶抑制物，主要由血管内皮细胞产生，通过与t-PA和u-PA结合而灭活t-PA和u-PA。","","N"],["2023-N138",4,"第3节 气体在血液中的运输","Hb与O₂结合的特征",2023,138,"X","","关于血红蛋白的叙述，正确的是",[["A","R型Hb分子对O₂的亲和力高于T型Hb"],["B","H⁺浓度升高时不利于Hb与O₂的结合"],["C","Hb与O₂结合后呈樱桃红色"],["D","Hb中的Fe主要为三价铁离子"]],"AB","血红蛋白（Hb）分子由1个珠蛋白和4个血红素组成，每个血红素基团中心为一个二价铁离子（D错），该铁离子可与O₂结合，使Hb成为HbO₂（氧合血红蛋白）。HbO₂呈鲜红色（C错），呈樱桃红色的是HbCO（一氧化碳血红蛋白）。Hb有两种构象：T型Hb（紧密型）和R型HbO₂（疏松型），两者与血红蛋白的亲和力不同，R型Hb对O₂的亲和力要高于T型Hb（A对）。根据波尔效应，血液酸度和PCO₂影响Hb与O₂的亲和力，当血液中H⁺的浓度升高时，PH降低，Hb与O₂的亲和力降低，即H⁺的浓度不利于O₂与Hb结合（B对）。","","N"],["2023-N139",5,"第6节 大肠的功能","大肠内细菌的消化作用",2023,139,"X","","大肠内细菌可以合成的维生素有",[["A","维生素C"],["B","维生素B复合物"],["C","维生素E"],["D","维生素K"]],"BD","大肠内细菌利用简单物质合成的维生素有维生素B复合物（B对）和维生素K（D对），这些维生素可被人体吸收利用。维生素C（A错）、维生素E（C错）主要依赖食物提供。","","N"],["2023-N140",7,"第6节 清除率","推测肾小管的功能",2023,140,"X","","利用肾清除率的原理，可测定的肾功能指标有",[["A","肾小球滤过率"],["B","肾血流量"],["C","肾小管重吸收钠量"],["D","肾小管泌氢能力"]],"AB","两肾在单位时间（一般为每分钟）内能将一定毫升血浆中所含的某种物质完全清除，这个能完全清除某物质的血浆毫升数称为该物质的清除率。测定清除率的意义主要包括：①测定肾小球滤过率（A对），由于菊粉可被肾小球自由滤过，且在肾小管和集合管不被重吸收和分泌，因此利用菊粉的清除率可以测定肾小球清除率；②测定肾血浆流量、滤过分数和肾血流量（B对），静脉滴注碘锐特或对氨基马尿酸，维持其血浆浓度在1～3mg/100ml，当血液流经肾脏一个周期后，碘锐特或对氨基马尿酸经过肾脏大约有90%可从血浆中清除，因此碘锐特或对氨基马尿酸的清除率可用来代表有效肾血浆流量，根据肾血浆流量和血细胞比容，可进一步计算出肾血流量（B对）；③推测肾小管的功能，通过对各种物质清除率的测定，可推测哪些物质能被肾小管净重吸收，哪些物质能被肾小管净分泌。假如某一物质的清除率小于肾小球滤过率，表明该物质必定在肾小管被重吸收，但不能排除它能被肾小管分泌的可能性；如果某种物质的清除率大于肾小球滤过率，则表明肾小管必定能分泌该物质，但不能排除该物质也可被肾小管重吸收的可能性。通过测定钠离子和氢离子的清除率可以分别推测其是否被肾小管净重吸收或净分泌，但具体重吸收钠量（C错）和泌氢能力（D错）无法测定；④自由水清除率。","","N"],["2023-N141",10,"第5节 肾上腺内分泌","对组织器官活动的影响",2023,141,"X","","Cushing综合征患者循环血中血细胞计数的改变有",[["A","红细胞增多"],["B","淋巴细胞减少"],["C","中性粒细胞减少"],["D","嗜酸性粒细胞减少"]],"ABD","Cushing综合征为各种病因造成肾上腺分泌过多糖皮质激素所致病症的总称。糖皮质激素（GC）对血液系统血细胞的影响主要表现为：①增强骨髓的造血功能，使血液中红细胞、血小板数量增加（A对）。②使附着在血管壁及骨髓中的中性粒细胞进入血液循环，增加外周血液中性粒细胞的数量（C错）。③抑制淋巴细胞有丝分裂、促进淋巴细胞凋亡、使淋巴结和胸腺萎缩，并增加淋巴细胞与嗜酸性粒细胞在脾和肺的破坏，使淋巴细胞和嗜酸性粒细胞数量减少（BD对）。","","N"],["2024-N1",0,"第6节 人体内自动控制系统","反馈控制系统",2024,1,"A","","在人体的自动控制系统中，由受控部分发出到达控制部分的信息是",[["A","偏差信息"],["B","前馈信息"],["C","反馈信息"],["D","指令信息"]],"C","在反馈控制系统中，控制部分发出指令信息（D错）使受控部分发生活动，反过来，受控部分也可以发出信息对控制部分产生影响，这种信息被称之为反馈信息（C对），包括正反馈和负反馈两种信息形式，反馈信息传递到比较器（调定点）与参考信息比较产生偏差信息（A错），由控制部分接收。与反馈对应的一个概念是前馈（十版生理学P11），在前馈系统中，受控部分不发出反馈信息，前馈信息（B错）由某一监测装置在受到刺激后发出，作用于控制部分，能够调控受控部分的活动。","","N"],["2024-N2",1,"第3节 细胞的电活动","细胞兴奋后兴奋性的变化",2024,2,"A","","神经纤维上两个先后发生的锋电位之间的最短间隔时间是",[["A","≥绝对不应期"],["B","≥相对不应期"],["C","≥超常期"],["D","≥低常期"]],"A","在神经细胞上，由于绝对不应期的长短正好对应于锋电位发生的时期。在锋电位升支期间，大部分Na⁺（或Ca²⁺）通道已处于激活状态，不存在再激活的问题，在锋电位降支期间，大部分Na⁺（或Ca²⁺）通道处于失活状态，不可能再次接受刺激而被激活，因而在整个锋电位期间，细胞的兴奋性才为零，无论给予多强的刺激，也不能使细胞再次兴奋，这一段时间称为绝对不应期。而在绝对不应期之后，兴奋性逐渐恢复，受不同程度的阈上或阈下刺激后可发生兴奋。故相邻两次兴奋，即相邻两个锋电位之间的最短间隔时间是绝对不应期（A对）。","","N"],["2024-N3",1,"第4节 肌细胞的收缩","后负荷",2024,3,"A","","关于后负荷增加时骨骼肌收缩改变的叙述，错误的是",[["A","开始缩短的时间推迟"],["B","收缩产生的张力减小"],["C","缩短的速度减小"],["D","缩短的距离减小"]],"B","后负荷是指肌肉在收缩后所承受的负荷。骨骼肌后负荷增加时，骨骼肌收缩过程中遇到的阻力增加，为了克服阻力，骨骼肌收缩所产生的张力增加（B错，为本题正确答案）。后负荷增加，肌肉开始缩短的时间推迟（A对），肌肉缩短的速度减小（C对），肌肉缩短的距离也减小（D对）。","","N"],["2024-N4",2,"第3节 生理性止血","生理性抗凝物质",2024,4,"A","","蛋白质C系统的抗凝血机制是",[["A","灭活FⅧa和FⅤa"],["B","抑制FⅦa-FⅢ复合物"],["C","增强抗凝血酶活性"],["D","拮抗维生素K的作用"]],"A","体内的生理性抗凝物质可分为丝氨酸蛋白酶抑制物、蛋白质C系统和组织因子途径抑制物三类。蛋白质C系统主要通过灭活FⅧa和FⅤa发挥抗凝血作用（A对）。组织因子途径抑制物（TFPI）在结合FⅩa后结合FⅦa-FⅢ（组织因子）复合物抑制其活性（B错）。肝素主要通过增强抗凝血酶的活性而发挥间接抗凝作用（C错）。维生素K拮抗剂（如华法林）可抑制FⅡ、FⅦ、FⅨ、FⅩ等维生素K依赖性凝血因子的合成，发挥体内抗凝作用（D错）。","","N"],["2024-N5",3,"第3节 血管生理","微循环的血流动力学",2024,5,"A","","调节毛细血管前括约肌舒缩活动的主要因素是",[["A","交感神经"],["B","副交感神经"],["C","血管紧张素"],["D","局部代谢产物"]],"D","毛细血管前括约肌组成微循环的一部分，其和后微动脉主要受局部代谢产物（如CO₂、H⁺、腺苷、ATP、K⁺等）的调节（代谢性自身调节）而发生交替性血管舒缩活动（D对）。交感缩血管神经主要分布在动脉，以微动脉中的密度为最高，主要调节血管舒缩活动（A错）。副交感神经舒血管神经纤维分布在少数器官如脑膜、唾液腺、胃肠外分泌腺和外生殖器的血管平滑肌，起血管舒张和局部血流量增加的作用，平时无紧张性活动（B错）。血管紧张素中最重要的为AngII，可直接使全身微动脉收缩，血压升高，一般不调节毛细血管前括约肌的舒缩活动（C错）。","","N"],["2024-N6",3,"第4节 心血管活动的调节","心脏的神经支配",2024,6,"A","","心迷走神经兴奋时，心脏活动不会发生的明显改变是",[["A","心室肌收缩力减弱"],["B","心房肌收缩力减弱"],["C","心率减慢"],["D","心内兴奋传导减慢"]],"A","迷走神经的节后神经纤维主要支配窦房结、心房肌、房室交界、房室束及其分支，而对心室肌的支配则很少。迷走神经兴奋时，神经末梢释放ACh，作用于心肌细胞膜的M型胆碱能受体，可引起心房肌收缩力减弱（B对）、心率减慢（C对）和房室传导速度减慢（D对），即具有负性变力、负性变时和负性变传导作用。而迷走神经对心室肌的支配密度较低，兴奋时，心室肌收缩力不会发生明显改变（A错，为本题正确答案）。","","N"],["2024-N7",4,"第3节 气体在血液中的运输","影响氧解离曲线的因素",2024,7,"A","","下列各种情况下，可引起氧解离曲线右移的是",[["A","CO中毒"],["B","血pH升高"],["C","PaCO₂降低"],["D","红细胞糖酵解加强"]],"D","氧解离曲线的位置发生偏移意味着Hb对O₂的亲和力发生了变化。通常用P₅₀来表示Hb对O₂的亲和力。P₅₀是使Hb饱和度达50%时的PO₂，P₅₀增大时氧解离曲线右移，表示Hb对O₂的亲和力降低，需要更高的PO₂才能使Hb氧饱和度达到50%。使氧解离曲线右移的常见因素包括血pH降低（B错）、PCO₂↑（C错）、温度↑、2，3-DPG↑等。在慢性缺氧贫血等情况下，红细胞糖酵解加强，2，3-DPG增加，氧解离曲线右移（D对）。CO与O₂亲和力极强，当CO与Hb分子中一个血红素结合后，可增加其余3个血红素对O₂的亲和力，使氧解离曲线左移（A错）。","","N"],["2024-N8",5,"第4节 小肠内消化","促胰液素",2024,8,"A","","酸性食糜入肠后通过小肠黏膜释放某种胃肠激素而使胰液大量分泌，这种胃肠激素是",[["A","促胰液素"],["B","促胃液素"],["C","抑胃肽"],["D","缩胆囊素"]],"A","胰腺兼有外分泌（分泌胰液）和内分泌（分泌胰岛素）的双重功能，其中分泌胰液的外分泌部分由腺泡及导管两个部分组成，腺泡主要分泌胰酶，导管则主要分泌水和碳酸氢盐，当酸性食糜进入小肠后，可刺激小肠黏膜释放促胰液素，进而促使胰液大量分泌（A对）。迷走神经兴奋时，可以通过促胃液素释放肽的作用促进促胃液素的分泌，最终刺激壁细胞分泌盐酸（B错），其与缩胆囊素具有相似的作用，可促进胰酶分泌，但作用较弱。抑胃肽（C错）可通过生长抑素的介导抑制组胺和胰岛素性低血糖所引起的胃酸分泌。食物中的蛋白质分解产物、脂酸钠等可以促进小肠黏膜分泌缩胆囊素（D错），进而促进胰液中各种酶的分泌，同时也可促进胆囊强烈收缩，排出胆汁。","","N"],["2024-N9",6,"第1节 能量代谢","基础代谢",2024,9,"A","","测得某受试者的体表面积为1.67㎡，在基础状态下的耗氧量为16.7L/h，非蛋白氧热价为20.2KJ/L，该受试者的基础代谢率约为",[["A","140KJ/（㎡·h）"],["B","170KJ/（㎡·h）"],["C","200KJ/（㎡·h）"],["D","250KJ/（㎡·h）"]],"C","基础代谢率是指在基础状态下单位时间内的能量代谢，其测定通常采用简化的能量代谢测定法，题目中给出非蛋白质的氧热价为20.2KJ/L，因此，只需知道受试者在基础状态下一定时间内的耗氧量和体表面积，即可计算出基础代谢率：20.20kJ/L×16.7L/h÷1.67m²=202kJ/（m²•h），接近200kJ/（m²•h）（C对）。","","N"],["2024-N10",7,"第3节 肾小管和集合管的物质转运功能","髓袢",2024,10,"A","","对水不通透的肾小管和集合管部位是",[["A","髓袢升支粗段"],["B","髓袢降支细段"],["C","近端小管"],["D","集合管"]],"A","肾小管液流经肾单位的顺序为：近曲小管→髓袢降支粗段→髓袢降支细段→髓袢升支细段→髓袢升支粗段→远曲小管→集合管。其中，对水不通透的主要有髓袢升支粗段（A对）、髓袢升支细段和远曲小管。髓袢降支细段（B错）对水易通透，对NaCl不易通透。近端小管（C错）对水通透（重吸收），主要通过水通道蛋白1在渗透压作用下完成。集合管（D错）对水也通透，主要通过水通道蛋白2在抗利尿激素的调节下完成。","","N"],["2024-N11",8,"第1节 感觉概述","感觉通路中的侧向抑制",2024,11,"A","","在感觉通路中，能增强感觉系统分辨能力的信息处理方式是",[["A","侧向抑制"],["B","交互抑制"],["C","反馈抑制"],["D","突触前抑制"]],"A","在感觉通路中，由于存在辐散式联系，一个局部刺激常可激活多个神经元，处于中心区的投射纤维直接兴奋下一个神经元；而处于周边区的投射纤维感觉则通过抑制性中间神经元而抑制其后续神经元。这样，与来自刺激中心区感觉神经元的信息相比来自刺激周边区的信息则是抑制的，因此，侧向抑制能加大刺激中心区和周边区之间神经元兴奋程度的差别、增强感觉系统的分辨能力（A对）。交互抑制（B错），也称传入侧支性抑制，其神经联系方式是感觉传入纤维进入中枢后，一方面与反射通路上的某一中枢神经元形成兴奋性突触，另一另方面通过侧支与一个抑制性中间神经元也形成兴奋性突触，这个抑制性中间神经元再与另一个中枢神经元形成抑制性突触，伸肌肌梭的传入冲动对与该肌相拮抗的屈肌运动神经元的抑制就是典型的传入侧支性抑制，这种抑制的意义在于保证伸肌和屈肌活动的协调控制。反馈是指由受控部分发出的信息反过来影响控制部分的活动，在感觉通路中，通过反馈抑制可使感觉活动及时终止（C错）。突触前抑制（D错）是指一个神经元的轴突末梢与第二个兴奋性神经元的轴突末梢形成轴突-轴突式突触，前者兴奋时释放的递质就可影响后者兴奋时在其突触后的第三个神经元的胞体产生的兴奋性突触后电位，即第一个神经元兴奋时释放的递质相对地降低了第二个神经元兴奋时在第三个神经元的胞体产生的兴奋性突触后电位，突触前抑制广泛存在于中枢，尤其在感觉传入通路中，对调节感觉传入活动具有重要意义。","","N"],["2024-N12",9,"第3节 神经系统对躯体运动的调控","牵张反射的感受器",2024,12,"A","","下列关于骨骼肌牵张反射的叙述，错误的是",[["A","肌肉静息时，肌梭有一定的传入冲动"],["B","α传出冲动增加时，肌梭传入冲动增加"],["C","γ传出冲动增加时，肌梭传入冲动增加"],["D","肌肉受牵拉而伸长时，肌梭传入冲动增加"]],"B","牵张反射是指有完整神经支配的骨骼肌在受外力牵拉伸长时引起的被牵拉的同一肌肉发生收缩的反射。牵张反射的感受器是肌梭（梭内肌纤维），有Ⅰa和Ⅱ类两种传入纤维，基本中枢位于脊髓，传出纤维是α和γ纤维。当肌肉受外力牵拉而使肌梭被拉长时，作为传入神经的Ⅰa类和Ⅱ类纤维的传入冲动增加，肌梭的传入冲动增加（D对），引起支配同一肌肉的α运动神经元兴奋，使梭外肌收缩，形成一次牵张反射，梭外肌收缩可以引起与其并联的梭内肌缩短，肌梭感受器所受的牵拉刺激减少，肌梭传入冲动减少（B错，为本题正确答案）。γ运动神经元兴奋性很高，可以在高位脑中枢的影响下以较高频率持续放电，在整体情况下，即使肌肉不活动，α运动神经元无放电时，有些γ运动神经元仍持续放电（A对），肌梭感受的传入冲动也增加（C对）。","","N"],["2024-N13",9,"第4节 神经系统对内脏活动、本能行为和情绪的调节","本能行为",2024,13,"A","","在动物下丘脑埋藏电极，通电刺激后能引起动物多食的部位是",[["A","前核"],["B","弓状核"],["C","外侧区"],["D","腹内侧核"]],"C","摄食行为是人和动物的本能行为，摄食中枢和饱中枢共同参与摄食行为的调节。摄食中枢位于下丘脑外侧区，刺激该区将引起动物多食（C对）。饱中枢位于下丘脑的腹内侧核，刺激此核将引起动物拒食（D错）。丘脑前核（A错）属于联络核，接受来自下丘脑乳头体的传入纤维，传出纤维投射到大脑皮层扣带回，参与内脏活动的调节。下丘脑弓状核（B错）可通过抑制神经肽Y神经元活动，减少摄食量，与参与摄食平衡调节的兴奋性因素相抵抗。","","N"],["2024-N14",10,"第4节 甲状旁腺、维生素D与甲状腺C细胞内分泌","对肾脏的作用",2024,14,"A","","能促进肾脏合成活性维生素D₃的激素是",[["A","E₂"],["B","GH"],["C","TH"],["D","PTH"]],"D","维生素D₃无活性，需要经过两次羟化才能转变为活性维生素D₃，即1，25－二羟维生素D₃。PTH（甲状旁腺激素）除了可以促进肾远曲小管和集合管对钙的重吸收，抑制近端和远端小管对磷的重吸收，升高血钙，降低血磷外，还可以激活肾脏1α-羟化酶，催化25-（OH）-D₃转变为活性维生素D₃（D对），间接调节钙、磷代谢。对于钙磷调节而言，E₂（雌二醇）（A错）有抑制骨吸收、减少骨量丢失的作用；GH（生长激素）（B错）和TH（甲状腺激素）（C错）不是调节血钙和血磷的主要激素，三者均不通过促进肾脏合成活性维生素D₃调节钙、磷代谢。","","N"],["2024-N15",10,"第5节 肾上腺内分泌","反馈调节",2024,15,"A","","长期大剂量服用皮质醇类激素的患者不能突然停药，其原因是",[["A","突然停药可导致血糖突然降低"],["B","相当于应激后机体极度虚弱难以恢复"],["C","突然停药后立即反弹，皮质醇大量分泌"],["D","反馈抑制ACTH释放而致肾上腺皮质萎缩"]],"D","临床上长期大剂量应用糖皮质激素，可通过长反馈抑制下丘脑CRH（促肾上腺皮质激素释放激素）神经元及腺垂体ACTH（促肾上腺皮质激素）细胞，使CRH与ACTH的合成和分泌减少，导致患者肾上腺皮质束状带和网状带的萎缩，分泌功能减退或停止，患者突然停药时，由于肾上腺皮质萎缩无法分泌足量糖皮质激素（皮质醇激素）以满足机体所需，可能会出现急性肾上腺皮质功能减退的严重后果，甚至危及生命（D对C错）。长期大剂量服用皮质醇激素可以引起血糖调节障碍，甚至有诱发糖尿病的风险，即使停药后血糖也很难降至正常（A错）。应激是指当机体受到伤害性刺激时，发生的一系列非特异性的适应反应，应激反应机制十分复杂（P393），应激时皮质醇激素分泌会增多（但远不止如此，其他应激激素也分泌增多，同时交感神经系统活动增强），不代表服用皮质醇激素机体会处于应激状态（B错）。","","N"],["2024-N16",11,"第2节 女性生殖功能及其调节","月经周期各期的内分泌调控",2024,16,"A","","育龄期妇女在结扎输卵管后的生殖系统周期性变化是",[["A","无排卵，有月经"],["B","无排卵，无月经"],["C","有排卵，有月经"],["D","有排卵，无月经"]],"C","女性内生殖系统包括阴道、子宫、输卵管、卵巢。在女性的生殖系统周期性变化中，随着血中雌、孕激素的变化，月经周期中的LH峰触发排卵，排出的卵细胞与放射冠一起被输卵管伞摄入到输卵管中，在此存活10多个小时，如果在输卵管壶腹部发生受精，黄体发育为妊娠黄体，子宫发生内膜蜕膜化，为胚泡着床做准备；如果未发生受精，黄体萎缩退化，血中雌、孕激素水平突然降低，子宫内膜功能层出现缺血、变性、坏死，最后剥脱，血管破裂，出血，形成月经。对于输卵管结扎后的育龄期妇女，其体内的雌、孕激素仍然发生周期性的改变，仍存在LH峰触发排卵，但是由于输卵管结扎阻断了受精过程，在排卵后将出现雌、孕激素降低，子宫内膜剥脱，形成月经。因此，其生殖系统的周期性改变为有排卵，有月经（C对）。","","N"],["2024-N116",4,"第1节 肺通气","肺容量",2024,116,"B","","在阻塞性肺疾病患者，其肺通气功能检测结果是",[["A","FEV₁/FVC基本不变，余气量增多"],["B","FEV₁/FVC基本不变，余气量减少"],["C","FEV₁/FVC比值减小，余气量增多"],["D","FEV₁/FVC比值减小，余气量减少"]],"C","FVC即用力肺活量，是一次最大吸气后，尽力尽快呼气所能呼出的最大气体量。FEV₁即1秒用力呼气量，指一次最大吸气后，尽力尽快呼气，在第1秒末所能呼出的气体量。FEV₁/FVC即一秒率，是第1秒呼出气量占FVC的百分率，正常值约83%（正常参考值＞80%）。FEV₁/FVC临床应用非常广泛，对于判断气道阻力有重要意义，是临床上鉴别阻塞性肺疾病和限制性肺疾病最常用的指标。阻塞性通气障碍病人，如慢性阻塞性肺疾病、支气管哮喘急性发作的病人，其气道阻塞、呼气延长，FEV₁和FEV₁/FVC均会降低，同时因呼气困难而使残留在肺内的气体增多，故余气量增加（C对D错）。但限制性通气障碍时，如弥漫性肺间质疾病、胸廓畸形等，FEV₁/FVC可正常（AB错），因为气道呼出气流不受限制，但肺弹性及胸廓顺应性降低，呼气运动迅速减弱停止，使肺活量的绝大部分在极短时间迅速呼出，甚至可达到100%。","","N"],["2024-N117",4,"第1节 肺通气","肺容量",2024,117,"B","","在限制性肺疾病患者，其肺通气功能检测结果是",[["A","FEV₁/FVC基本不变，余气量增多"],["B","FEV₁/FVC基本不变，余气量减少"],["C","FEV₁/FVC比值减小，余气量增多"],["D","FEV₁/FVC比值减小，余气量减少"]],"B","FVC即用力肺活量，是一次最大吸气后，尽力尽快呼气所能呼出的最大气体量。FEV₁即1秒用力呼气量，指一次最大吸气后，尽力尽快呼气，在第1秒末所能呼出的气体量。FEV₁/FVC即一秒率，是第1秒呼出气量占FVC的百分率，正常值约83%（正常参考值＞80%）。FEV₁/FVC临床应用非常广泛，对于判断气道阻力有重要意义，是临床上鉴别阻塞性肺疾病和限制性肺疾病最常用的指标。阻塞性通气障碍病人，如慢性阻塞性肺疾病、支气管哮喘急性发作的病人，其气道阻塞、呼气延长，FEV₁和FEV₁/FVC均会降低，同时因呼气困难而使残留在肺内的气体增多，故余气量增加（CD错）。但限制性通气障碍时，如弥漫性肺间质疾病、胸廓畸形等，FEV₁/FVC可正常，因为气道呼出气流不受限制，但肺弹性及胸廓顺应性降低，呼气运动迅速减弱停止，使肺活量的绝大部分在极短时间迅速呼出，甚至可达到100%，同时，限制性肺疾病时，因肺总量降低，余气量也相应的下降（B对A错）。","","N"],["2024-N118",7,"第2节 肾小球的滤过功能","囊内压",2024,118,"B","","输尿管结石时尿量减少的原因是",[["A","肾小囊内压升高"],["B","滤过膜通透性减小"],["C","血浆胶体渗透压升高"],["D","肾小球滤过总面积减少"]],"A","肾小球有效滤过压＝（肾小球毛细血管静水压＋囊内液胶体渗透压）－（血浆胶体渗透压＋肾小囊内压）。输尿管结石时引起尿路阻塞时，囊内压升高，超滤的阻力增加，使有效滤过压减低，肾小球滤过率降低，导致超滤液生成减少，尿量减少（A对）。","","N"],["2024-N119",7,"第2节 肾小球的滤过功能","肾小球毛细血管滤过系数",2024,119,"B","","大量失血时尿量减少的主要原因是",[["A","肾小囊内压升高"],["B","滤过膜通透性减小"],["C","血浆胶体渗透压升高"],["D","肾小球滤过总面积减少"]],"D","大量失血，一方面导致血容量减少，另一方面引起交感神经兴奋，二者均可使肾血流量和肾血浆流量减少，滤过平衡点移向入球小动脉端，即有效滤过面积减小（D对），使肾小球滤过率降低，导致超滤液生成减少，尿量减少。值得注意的是，大量失血时可激活肾素-血管紧张素系统，使血管紧张素Ⅱ（AngⅡ）分泌增加→肾小球毛细血管间的系膜细胞收缩→滤过膜通透性减小（B错）→肾小球滤过率降低，最终也可导致尿量减少。本题问的是主要原因，D选项为最佳答案。","","N"],["2024-N136",2,"第3节 生理性止血","纤维蛋白的生成",2024,136,"X","","凝血酶（FⅡa）对血液凝固过程的正反馈作用有",[["A","使FⅤ活化为FⅤa"],["B","使FⅧ活化为FⅧa"],["C","使FⅪ活化为FⅪa"],["D","使FXⅢ活化为FXⅢa"]],"ABC","凝血酶（FⅡa）在血液凝固过程中起着核心作用，它不仅直接将可溶性纤维蛋白原转化为不可溶的纤维蛋白，而且还通过正反馈机制激活几个重要的凝血因子，加速血液凝固过程：①使FⅤ活化为FⅤa（A对），FⅤa在钙离子和磷脂的存在下，与FⅩa结合形成凝血酶原酶复合物，进一步促进凝血酶原转化为凝血酶，从而加速凝血过程，这是一个典型的正反馈机制；②使FⅧ活化为FⅧa（B对），FⅧa是内源性凝血途径中的关键组分，与凝血因子Ⅸa共同促进凝血因子Ⅹ的活化，从而增加了凝血酶的生成，这同样是一个正反馈作用；③使FⅪ活化为FⅪa（C对），FⅪa进一步活化凝血因子Ⅸ，增强内源性凝血途径，促进更多凝血酶的生成，故对血液凝固过程也有正反馈作用。凝血酶也可使FⅩⅢ活化为FⅩⅢa（D错），FⅩⅢa在凝血过程的最后阶段发挥作用，通过交联纤维蛋白形成更稳定的血栓，这一过程并不直接促进凝血酶的生成或增加其活性，因此对血液凝固过程不存在正反馈作用。","","N"],["2024-N137",3,"第2节 心脏的电生理学及生理特性","窦房结细胞动作电位",2024,137,"X","","动作电位0期去极化是由Ca²⁺内流引起的心肌细胞有",[["A","窦房结P细胞"],["B","心房肌细胞"],["C","房室结细胞"],["D","浦肯野细胞"]],"AC","根据心肌细胞动作电位去极化的快慢及其产生机制，又可将心肌细胞分成快反应细胞和慢反应细胞。快反应细胞包括心房（B错）、心室肌和浦肯野细胞（D错），其动作电位的特点是去极化速度和幅度大，兴奋传导速度快；慢反应细胞包括窦房结（A对）和房室结细胞（C对），其动作电位特点是去极化速度和幅度小。对于慢反应细胞而言，其动作电位0期的产生则主要依赖ICa-L（慢钙通道），而快反应细胞0期去极化主要是由钠内向电流INa（快钠通道）引起。","","N"],["2024-N138",5,"第3节 胃内消化","胃和十二指肠黏膜的细胞保护作用",2024,138,"X","","在胃和十二指肠黏膜合成和释放的物质中，参与黏膜细胞保护作用的有",[["A","前列环素"],["B","生长抑素"],["C","表皮生长因子"],["D","降钙素基因相关肽"]],"ABCD","胃和十二指肠黏膜具有很强的细胞保护作用，能够合成和释放某些具有防止或减轻各种有害刺激对细胞损伤和致坏死的物质。胃和十二指肠黏膜和肌层中含有高浓度的前列环素（A对）和表皮生长因子（C对），它们能抑制胃酸和胃蛋白酶原的分泌，刺激黏液和碳酸氢盐的分泌，使胃黏膜的微血管扩张，增加黏膜的血流量，有助于胃黏膜的修复和维持其完整性。生长抑素（B对）可以抑制胃酸分泌，从而保护胃黏膜细胞免受过多酸性物质的侵蚀。降钙素基因相关肽（D对）可以促进血管扩张，增加胃黏膜的血流量，有助于胃黏膜细胞的保护和修复。","","N"],["2024-N139",6,"第2节 体温及其调节","产热活动的调节",2024,139,"X","","能刺激人体产热、起效较快而持续时间较短的激素有",[["A","生长激素"],["B","甲状腺激素"],["C","肾上腺素"],["D","去甲肾上腺素"]],"ACD","甲状腺激素、肾上腺素、去甲肾上腺素和生长激素可以促进机体产热，主要通过神经调节和体液调节。寒冷刺激可使交感神经系统兴奋，促进肾上腺髓质释放肾上腺素（C对）和去甲肾上腺素（D对），通过神经－体液调节使代谢性产热增加，相当于紧急情况下的应急反应。寒冷作为有害刺激，使机体产生应激激素生长激素（A对），其生效时间较快且发挥作用的时长也较短。同时寒冷也可通过下丘脑－腺垂体－甲状腺轴，促进甲状腺产生和分泌甲状腺激素（B错），调节线粒体功能、Na⁺，K⁺-ATP酶活性等来提高代谢率，特别是在寒冷环境中数周这种效应更为明显。由于调节该效应的方式为体液调节，其作用缓慢而持久。","","N"],["2024-N140",9,"第4节 神经系统对内脏活动、本能行为和情绪的调节","副交感神经系统的功能",2024,140,"X","","患者使用阿托品后可出现的生理变化有",[["A","闭汗"],["B","瞳孔扩大"],["C","心率加快"],["D","骨骼肌松弛"]],"ABC","大多数副交感神经的节后纤维释放的递质是乙酰胆碱（少数节后纤维释放肽类和嘌呤类递质），激活M型或N型胆碱能受体发挥作用。M受体激活时的效应包括心率减慢，内脏平滑肌收缩，消化腺、汗腺分泌增加，瞳孔缩小和骨骼肌血管舒张等，阿托品为M受体拮抗剂，使用后出现的生理变化与激活效应相反，即闭汗（A对）、瞳孔扩大（B对）和心率加快（C对）。N₂受体激活时可使骨骼肌收缩，但阿托品不能阻断N受体，因此无法使骨骼肌松弛（D错）。","","N"],["2024-N141",10,"第4节 甲状旁腺、维生素D与甲状腺C细胞内分泌","对骨的作用",2024,141,"X","","可引起骨质疏松的内分泌激素分泌紊乱有",[["A","雌激素分泌过多"],["B","皮质醇分泌过多"],["C","甲状腺激素分泌过多"],["D","甲状旁腺激素分泌过多"]],"BCD","机体钙、磷代谢主要受甲状旁腺激素、降钙素、1，25-二羟维生素D₃调节，除此之外，雌激素、甲状腺激素、糖皮质激素也对血清钙、磷水平变化有所影响。糖皮质激素（皮质醇）可抑制肝外组织细胞内的蛋白质合成，加速其分解，皮质醇分泌过多（B对）时，可引起肌肉消瘦、骨质疏松等。甲状腺激素分泌过多（C对）时，外周组织蛋白质分解加速，骨基质蛋白质分解，Ca²⁺析出，导致血钙升高，骨质疏松。甲状旁腺激素是调节钙、磷代谢的基础激素之一，主要起升高血钙和降低血磷的作用，分泌过多（D对）将造成骨质过度溶解、骨量减少、骨质疏松症等。雌激素有抑制骨吸收、减少骨量丢失的作用，更年期妇女由于雌激素水平降低（A错），容易发生骨质疏松。","","N"],["2025-N1",0,"第4节 机体的内环境、稳态和生物节律","机体的内环境",2025,1,"A","","下列不属于内环境范畴的体液是",[["A","血浆"],["B","脑脊液"],["C","胃肠消化液"],["D","淋巴液"]],"C","人体内的液体总称为体液，体液可分为细胞内液和细胞外液，细胞内液约占2/3，细胞外液约占1/3。细胞外液也称为内环境，是体内细胞直接接触和生存的环境，包括血浆（A对）、组织液、淋巴液（D对）和脑脊液（B对）。胃肠道消化液（C错，为本题正确答案）、汗腺管内的液体、尿道内的液体、膀胱内的液体等由于都是与外环境连通的，所以不属于内环境的范畴。","","N"],["2025-N2",1,"第1节 细胞膜的物质转运功能","钙泵",2025,2,"A","","关于钙泵的叙述，正确的是",[["A","细胞膜与内质网膜上的钙泵相同"],["B","不具有特异性的Ca²⁺结合位点"],["C","细胞内Ca²⁺通过与钙调蛋白结合可刺激其活动"],["D","维持细胞内游离的Ca²⁺浓度在一个较高的水平"]],"C","钙泵是哺乳动物细胞中广泛分布的一种离子泵，也称Ca²⁺-ATP酶。钙泵分布于质膜（细胞膜）、肌细胞的肌质网和其他细胞的内质网膜上。细胞膜与内质网膜上的钙泵并不相同（A错），细胞膜上的钙泵称为质膜钙ATP酶（PMCA），质膜的钙泵每分解1分子ATP可将1个Ca²⁺由胞质内转运至胞外，而肌质网和内质网膜上的钙泵称为肌质网和内质网钙ATP酶（SERCA），肌质网和内质网的钙泵每分解1分子ATP可将2个Ca²⁺从胞质内转运至肌质网或内质网内。钙泵的活动原理类似于钠泵，不同的是钙泵具有特异性的Ca²⁺结合位点（B错），当胞质内Ca²⁺浓度升高时，Ca²⁺通过与钙调素蛋白的结合而刺激钙泵活动（C对）。PMCA和SERCA的共同作用可使胞质内游离Ca²⁺浓度保持在0.1～0.2μmol/L的低水平（D错）。","","N"],["2025-N3",1,"第3节 细胞的电活动","电紧张电位",2025,3,"A","","将正、负两个刺激电极都置于细胞膜外侧，接通直流电刺激时产生的膜电位变化是",[["A","两个电极下方同时产生极性相同的电紧张电位"],["B","负极下方产生超极化电紧张电位"],["C","正极下方产生去极化电紧张电位"],["D","负极下方膜电位改变相当于给细胞内注入了正电流"]],"D","如果将正、负两个刺激电极分别连接到细胞外膜上，当接通直流电刺激时，由于细胞膜的电容性质会导致正负两极的电流不同（A错）。由于负电极吸引正离子，排斥负离子，胞质内的正电荷会流向负电极的下方，负极下方的细胞膜可以产生去极化电流（B错），相当于给其胞内注入了正电流（D对）。由于正电极吸引负离子，排斥正离子，胞内的负电荷会流向正电极下方，正电极下方的细胞膜则产生超极化电流（C错），相当于在其胞内注入了负电流。","","N"],["2025-N4",2,"第3节 生理性止血","纤维酶原的激活",2025,4,"A","","能明显增加组织型纤溶酶原激活物对纤溶酶原亲和力的物质是",[["A","纤维蛋白"],["B","凝血酶"],["C","尿激酶型纤溶酶原激活物"],["D","激肽释放酶"]],"A","纤溶酶原激活物主要有组织型纤溶酶原激活物（t-PA）和尿激酶型纤溶酶原激活物（u-PA）。t-PA是血液中主要的内源性纤溶酶原激活物，主要由血管内皮细胞合成，正常情况下新分泌出来的t-PA为单链t-PA，已具有较低的纤溶酶原激活作用，在纤维蛋白（A对）的存在下，t-PA可与吸附于纤维蛋白上的纤溶酶原形成三联体，其促进纤溶酶原激活的活性增加1000倍。凝血酶（B错）可以激活FⅤ、FⅧ、FⅪ，形成凝血过程中的正反馈机制，使血小板活化，凝血酶还能通过与凝血酶调节蛋白的结合激活凝血酶激活的纤溶抑制物，抑制纤维蛋白的溶解。尿激酶纤溶酶原激活物（u-PA）（C错）是血液中仅次于t-PA的生理性活化物，主要由肾小管、集合管上皮细胞产生，u-PA通过与细胞膜上的尿激酶型纤溶酶原激活物受体结合，促进结合于细胞表面的纤溶酶原的激活，u-PA不增加t-PA与纤溶酶原的亲和力。激肽释放酶（D错）分解血浆和组织中的蛋白质底物激肽原产生激肽，也可激活纤溶酶原，但正常情况下其激活活性不足总激活能力的15%。","","N"],["2025-N5",3,"第1节 心脏的泵血功能","影响前负荷的因素",2025,5,"A","","在心动周期中，可导致舒张期心室充盈增加的因素是",[["A","心肌纤维化"],["B","直立体位"],["C","舒张期心肌细胞外Na⁺浓度增高"],["D","舒张期心肌细胞胞质Ca²⁺浓度回降加快"]],"D","在心动周期中，心室舒张是一个耗能的过程，舒张期心肌细胞胞质钙离子回流增快（D对），钙离子与肌钙蛋白C结合位点解离并触发舒张过程就越快，心肌舒张速率也越快，快速充盈期产生的心室负压就越大，抽吸作用也越强，静脉回心血量越多，心室就能充盈更多的血量。当发生心肌纤维化（A错）或心肌肥厚时，心室顺应性降低，使舒张期特别减慢充盈期和心房收缩期的心室充盈量降低。直立体位（B错）受重力影响会使静脉回流至心脏的血液量减少，因此会减少舒张期心室的充盈量。心肌细胞的动作电位变化，如舒张期心肌细胞外Na⁺浓度增高（C错），主要影响心肌细胞的电生理特性，不会导致舒张期心室充盈量的增加。","","N"],["2025-N6",3,"第3节 血管生理","动脉血压的测量与正常值",2025,6,"A","","动脉收缩压出现在心动周期中的时间是",[["A","等容收缩期末"],["B","快速射血期末"],["C","减慢射血期末"],["D","心房收缩期末"]],"B","动脉收缩压是指一个心动周期中因心室射血而使动脉压达到的最高值，出现在心动周期中的时间是快速射血期末（B对），此时，心室强力收缩，将血液迅速射入主动脉，导致动脉血压达到峰值，快速射血期持续约0.1秒，心室射出的血液量约占总射血量的2/3。等容收缩期末（A错），室内压升高到超过房内压，推动房室瓣使之关闭，但室内压尚低于主动脉压，半月瓣处于关闭状态，心室暂时成为一个封闭的腔，还没有血液摄入主动脉。减慢射血期末（C错）由于心室收缩强度减弱，射血的速度逐渐减慢，室内压和主动脉压都由峰值逐渐下降。心房收缩期（D错）使心室舒张末期容积进一步增大，心房收缩期间，进入心室的血量约占每个心动周期的心室总回流量的25%。","","N"],["2025-N7",3,"第4节 心血管活动的调节","动脉血压的长期调节",2025,7,"A","","实现动脉血压长期调节的主要机制是",[["A","调节心脏收缩力"],["B","调节心率"],["C","调节外周阻力"],["D","调节细胞外液量"]],"D","根据神经和多种体液因素参与的对动脉血压的调节过程，可将动脉血压调节分为短期调节和长期调节。动脉血压长期调节是对血压在较长时间内（数小时，数天，数月或更长）发生的变化进行调节，主要通过肾-体液控制系统调节细胞外液量实现（D对），当体内细胞外液量增多时，循环血量增多，动脉血压升高，循环血量增多和动脉血压的升高能直接导致肾排钠和排水增加，将过多的体液排出体外，从而使血压恢复至正常水平。短期调节是指对短时间内发生的血压变化进行调节，主要是通过神经调节方式，包括通过各种心血管反射调节心肌收缩力（A错）和血管外周阻力（C错），同时也能通过调节心率（B错），影响舒张压，进而实现血压的调节。","","N"],["2025-N8",4,"第1节 肺通气","呼吸运动",2025,8,"A","","用力呼气时，收缩并起重要作用的呼气肌是",[["A","肋间外肌和膈肌"],["B","肋间内肌和腹肌"],["C","斜角肌和胸锁乳突肌"],["D","腹肌和胸大肌"]],"B","呼吸肌的收缩和舒张所引起的胸廓节律性扩大和缩小称为呼吸运动，包括吸气运动和呼气运动。根据机体的呼吸状态又可以分为平静呼吸和用力呼吸。用力呼吸是当机体劳动或运动、呼吸道不通畅或肺通气阻力增大时，或者当吸入气中CO₂含量增加或O₂含量减少时，加深加快的呼吸型式，包括用力吸气和用力呼气。当用力呼气时，吸气肌舒张，腹肌收缩增加腹内压，膈肌被向上推挤，使胸腔的上下径减小，肋间内肌收缩使肋骨和胸骨下移，肋骨向内侧旋转，使胸腔的前后径和左右径进一步缩小，肺内压升高，呼出更多的气体（B对）。肋间外肌和膈肌（A错）在用力吸气时收缩，此时控制第一对肋骨和胸骨运动的斜角肌和胸锁乳突肌（C错）也参加收缩，使胸骨柄及第一对肋骨向上向外提起，扩展胸廓上部，胸廓和肺的容积进一步扩大，更多的气体被吸入肺内。胸大肌（D错）为辅助吸气肌，不参与用力呼气。","","N"],["2025-N9",5,"第3节 胃内消化","促进胃液分泌的主要因素",2025,9,"A","","支配胃窦黏膜G细胞的迷走神经末梢释放的递质是",[["A","铃蟾素"],["B","组胺"],["C","缩胆囊素"],["D","促胃液素"]],"A","G细胞主要分布于胃窦，分泌促胃液素和促肾上腺皮质激素，G细胞的分泌活动受到迷走神经的支配，迷走神经发出的纤维通过释放促胃液素释放肽，也称为铃蟾素（A对），使G细胞释放促胃液素，间接引起壁细胞分泌胃酸。组胺（B错）由胃泌酸区黏膜内的肠嗜铬样（ECL）细胞分泌，该细胞的分泌活动也受到迷走神经发出的纤维支配，纤维末梢通过释放ACh作用于ECL细胞。缩胆囊素（C错）由小肠黏膜的I细胞分泌，其主要功能是刺激胰液分泌和胆囊收缩，增强小肠和大肠运动，抑制胃排空增强幽门括约肌收缩等，与G细胞无关。促胃液素（D错）由G细胞分泌，主要作用为促进胃酸和胃蛋白酶原分泌、使胃窦和幽门括约肌收缩、延缓胃排空等，蛋白质消化产物、迷走神经递质和扩张胃可刺激促胃液素的释放。","","N"],["2025-N10",5,"第6节 大肠的功能","大肠内细菌的消化作用",2025,10,"A","","大肠内细菌分解食物残渣时，不会产生的物质是",[["A","脂肪酸"],["B","维生素C"],["C","甘油"],["D","吲哚"]],"B","大肠内有大量细菌，主要为大肠杆菌、葡萄球菌，这些细菌含有能分解食物残渣的酶，分解糖及脂肪后的产物有乳酸、乙酸、CO₂、甲烷、脂肪酸（A对）、甘油（C对）、胆碱等，分解蛋白质后的产物有胨、氨基酸、NH₃、H₂S、组胺、吲哚（D对）等。维生素C（B错，为本题正确答案）广泛存在于新鲜蔬菜和水果中，不能在人体内合成，也不能由大肠内的细菌分解食物残渣产生，必须由食物供给。","","N"],["2025-N11",6,"第1节 能量代谢","食物的特殊动力效应",2025,11,"A","","食物特殊动力效应最显著的食物成分是",[["A","蛋白质"],["B","糖类"],["C","脂肪"],["D","纤维素"]],"A","食物特殊动力学效应指进食能刺激机体额外消耗能量的作用，食物的成分不同，所产生的特殊动力学效应也不同。在三种主要营养物质中，进食蛋白质（A对）产生的特殊动力学效应最为显著，约为30%，糖类（B错）和脂肪（C错）分别为6%和4%左右，混合性食物约为10%。纤维素（D错）虽然也是食物的一部分，但由于人体无法直接消化和吸收，其食物特殊动力学效应几乎可以忽略不计。","","N"],["2025-N12",7,"第3节 肾小管和集合管的物质转运功能","髓袢",2025,12,"A","","在肾小管髓袢升支粗段，使小管液呈正电位的物质是",[["A","Na⁺"],["B","K⁺"],["C","Ca²⁺"],["D","NH₄⁺"]],"B","髓袢升支粗段的上皮细胞有很高的代谢活性，对Na⁺、K⁺和Cl⁻具有主动重吸收作用。在髓袢升支粗段上皮细胞的顶端膜上具有Ⅱ型Na⁺-K⁺-2Cl⁻同向转运体（NKCC2），可以同向转运1个Na⁺、1个K⁺和2个Cl⁻，进入细胞内的Na⁺通过基底侧膜中的钠钾泵转运至组织间液，Cl⁻顺浓度梯度经基底侧膜中的氯通道进入组织间液，而K⁺（B对）则顺浓度梯度经顶端膜返回小管液中，并使小管液呈正电位。Na⁺（A错）通过顶端膜上的NKCC2进入细胞内，然后通过上皮细胞基底侧膜上的钠钾泵至组织间液，不参与构成小管液正电位。Ca²⁺（C错）在K⁺造成小管液呈正电位之后，经细胞旁途径被动重吸收，并不参与小管液正电位的构成。NH₄⁺（D错）在近端小管、髓袢升支粗段和远端小管上皮细胞内产生，主要在近端小管的上皮细胞顶端膜通过Na⁺-H⁺交换体进入小管液，与髓袢升支粗段小管液正电位无关。","","N"],["2025-N13",7,"第5节 尿生成的调节","血浆晶体渗透压",2025,13,"A","","大量出汗引起ADH分泌增加，尿液浓缩，该反射感受器的部位是",[["A","颈动脉体和主动脉弓"],["B","远曲小管和集合管"],["C","球旁器的致密斑"],["D","下丘脑前部室周器"]],"D","大量出汗后导致机体大量水分丢失，血浆晶体渗透压升高和血容量减少，该变化可以刺激位于下丘脑室周器（D对）的渗透压感受性神经元，进而使ADH（抗利尿激素）分泌量明显增加，促进肾重吸收水，浓缩尿并减少尿量，发挥抗利尿作用。颈动脉体和主动脉弓（A错）存在可感受动脉血中的O₂分压、CO₂分压和H⁺浓度的化学感受性反射，受到刺激后可调节呼吸，反射性地引起呼吸加深加快，通过呼吸运动的改变，再反射性影响心血管活动。远曲小管和集合管（B错）的主要作用是参与Na⁺、Cl⁻和水的重吸收，并受到醛固酮的作用，增加K⁺的排泄和增加Na⁺、水的重吸收。球旁器的致密斑（C错）位于穿过入球小动脉和出球小动脉之间的远曲小管起始部，能够感受小管液中NaCl含量的变化，将信息传递至邻近的球旁细胞，然后调节肾素分泌，从而调节尿量的生成。","","N"],["2025-N14",8,"第1节 感觉概述","感受器的适应现象",2025,14,"A","","属于快适应感受器的是",[["A","皮肤环层小体"],["B","皮肤梅克尔盘"],["C","关节囊感受器"],["D","肌梭"]],"A","当某一恒定强度的刺激持续作用于一个感受器时，其传入神经纤维上动作电位的频率会逐渐降低，这一现象称为感受器的适应。然后根据感受器出现适应的快慢，可分为快适应感受器和慢适应感受器两类。快适应感受器包括皮肤触觉感受器如环层小体（A对）、麦斯纳小体。慢适应感受器包括梅克尔盘（B错）、鲁菲尼小体、关节囊感受器（C错）、肌梭（D错）、颈动脉窦压力感受器和颈动脉体化学感受器等。","","N"],["2025-N15",9,"第1节 神经系统功能活动的基本原理","突触后抑制",2025,15,"A","","伸肌肌梭的传入冲动对屈肌运动神经元的抑制机制是",[["A","突触前抑制"],["B","传入侧支抑制"],["C","回返抑制"],["D","侧向抑制"]],"B","伸肌肌梭的传入冲动对屈肌运动神经元的抑制是传入侧支抑制（B对），其神经联系方式是感觉传入纤维进入中枢后，一方面与反射通路上的某一中枢神经元形成兴奋性突触，另一方面通过侧支与一个抑制性中间神经元也形成兴奋性突触，这个抑制性中间神经元再与另一个中枢神经元形成抑制性突触。突触前抑制（A错）发生于一种特殊的轴突-轴突-胞体式突触联系模式中，第一个神经元兴奋时释放的递质相对地降低了第二个神经元兴奋时在第三个神经元的胞体产生的兴奋性突触后电位，可见于脊神经感觉传入纤维在脊髓中央灰质后角的联系方式。回返抑制（C错）指神经元通过轴突侧支和抑制性中间神经元对自身的抑制，其神经联系方式是神经元兴奋时，传出冲动沿主轴突向末梢传导，同时又经轴突侧支兴奋一个抑制性中间神经元，后者释放抑制性递质，反过来抑制原先发生兴奋的神经元及同一中枢的其他神经元，可见于脊髓前角运动神经元的轴突支配骨骼肌。侧向抑制（D错）指在感觉通路中，一个局部刺激通常可启动多个神经元，处于中心区的投射纤维直接兴奋下一个神经元，而处于周边区的投射纤维则通过抑制性中间神经元而抑制其后续神经元，侧向抑制是空间辨别的基础。","","N"],["2025-N16",10,"第3节 甲状腺内分泌","下丘脑－腺垂体－甲状腺轴的调节",2025,16,"A","","导致甲状腺激素分泌减少的刺激是",[["A","交感神经兴奋"],["B","寒冷"],["C","瘦素水平升高"],["D","饥饿"]],"D","甲状腺激素由甲状腺合成和分泌，广泛调节机体的生长发育、新陈代谢等多种功能活动，甲状腺激素的分泌受下丘脑-腺垂体-甲状腺轴、神经、免疫以及甲状腺自身调节机制等的调节。交感神经兴奋（A错）会促进甲状腺激素的分泌。寒冷（B错）条件下，寒冷刺激的信号传入到中枢神经系统，同时到达下丘脑体温调节中枢以及与其相邻近的促甲状腺激素释放激素（TRH）神经元，可促进TRH释放，进而使腺垂体分泌促甲状腺激素（TSH）增加，血中甲状腺激素水平升高。饥饿（D对）状态下，瘦素水平的降低（C错），对TRH分泌的刺激减少，抑制甲状腺激素分泌，最终通过减少能量消耗，以维持机体的能量平衡。","","N"],["2025-N116",4,"第4节 呼吸运动的调节","动脉血气分析",2025,116,"B","","突然加快呼吸频率，潮气量不变，动脉血气分析结果是",[["A","血液pH升高，PaCO₂升高"],["B","血液pH升高，PaCO₂降低"],["C","血液pH降低，PaCO₂降低"],["D","血液pH降低，PaCO₂升高"]],"B","突然加快呼吸频率，潮气量（指每次呼吸时吸入或呼出的气体量）不变时，会导致每分钟通气量（指每分钟吸入或呼出的气体总量，是潮气量与呼吸频率的乘积）增加，进而促进更多的CO₂从肺部排出，PaCO₂降低，使血浆中H₂CO₃浓度降低，pH升高（B对）。血液pH升高，PaCO₂升高（A错）见于代谢性碱中毒，例如当幽门梗阻伴持续呕吐时，大量H⁺和Cl⁻丢失，HCO₃⁻相对增多，血液pH升高，肺通过升高PaCO₂来进行代偿。血液pH降低，PaCO₂降低（C错）见于代谢性酸中毒，例如当糖尿病酮症酸中毒时，体内酸性物质积聚过多致H⁺浓度增高，血液pH降低，引起呼吸中枢兴奋，增加呼吸的深度和频率，PaCO₂降低。血液pH降低，PaCO₂升高（D错）见于呼吸性酸中毒，因肺泡通气功能障碍， CO₂潴留以致血液的PaCO₂增高引起高碳酸血症，pH降低，可见于慢性阻塞性肺部疾病等。","","N"],["2025-N117",4,"第4节 呼吸运动的调节","动脉血气分析",2025,117,"B","","糖尿病酮症酸中毒时，动脉血气分析结果是",[["A","血液pH升高，PaCO₂升高"],["B","血液pH升高，PaCO₂降低"],["C","血液pH降低，PaCO₂降低"],["D","血液pH降低，PaCO₂升高"]],"C","当糖尿病酮症酸中毒时，动脉血气分析结果是血液pH降低，PaCO₂降低（C对），因为体内酸性物质积聚过多致H⁺浓度增高，血液pH降低，引起呼吸中枢兴奋，增加呼吸的深度和频率，PaCO₂降低。血液pH升高，PaCO₂升高（A错）见于代谢性碱中毒，例如当幽门梗阻伴持续呕吐时，大量H⁺和Cl⁻丢失，HCO₃⁻相对增多，血液pH升高，肺通过升高PaCO₂来进行代偿。血液pH升高，PaCO₂降低（B错）见于呼吸性碱中毒，例如当癔症发作时引起精神性通气过度，引起PaCO₂降低，血液pH升高。血液pH降低，PaCO₂升高（D错）见于呼吸性酸中毒，因肺泡通气功能障碍， CO₂潴留以致血液的PaCO₂增高引起高碳酸血症，pH降低，可见于慢性阻塞性肺部疾病等。","","N"],["2025-N118",9,"第3节 神经系统对躯体运动的调控","帕金森病",2025,118,"B","","帕金森病的中枢病变部位是",[["A","脊髓前角"],["B","纹状体"],["C","黑质"],["D","脊髓小脑"]],"C","帕金森病是一种常见于中老年人的神经系统变性疾病，其中枢病变部位是黑质（C对），当该递质系统受损时，可引起直接通路活动减弱而间接通路活动增强，使皮层对运动的发动受到抑制，从而出现运动减少和动作缓慢的症状。脊髓前角（A错）内的前角细胞属下运动神经元，病变可见于脊髓前角灰质炎等。纹状体（B错）参与构成基底神经节，与大脑皮质及小脑协同调节随意运动、肌张力和姿势反射等，病变可引起亨廷顿病。脊髓小脑（D错）由小脑前叶和后叶的中间带区（包括蚓部和半球中间部）组成，主要功能是调节进行过程中的运动，协助大脑皮层对随意运动进行适时的控制，病变可引起意向性震颤。","","N"],["2025-N119",9,"第3节 神经系统对躯体运动的调控","脊髓小脑",2025,119,"B","","意向性震颤的中枢病变部位是",[["A","脊髓前角"],["B","纹状体"],["C","黑质"],["D","脊髓小脑"]],"D","意向性震颤的中枢病变部位是脊髓小脑（D对），其由小脑前叶和后叶的中间带区（包括蚓部和半球中间部）组成，主要功能是调节进行过程中的运动，协助大脑皮层对随意运动进行适时的控制。脊髓前角（A错）内的前角细胞属下运动神经元，病变可见于脊髓前角灰质炎等。纹状体（B错）参与构成基底神经节，与大脑皮质及小脑协同调节随意运动、肌张力和姿势反射等，病变可引起亨廷顿病。黑质（C错）参与构成基底神经节，当黑质多巴胺能神经元变性时，可引起直接通路活动减弱而间接通路活动增强，使皮层对运动的发动受到抑制，从而出现运动减少和动作缓慢的症状，病变可引起帕金森病。","","N"],["2025-N136",1,"第4节 肌细胞的收缩","前负荷",2025,136,"X","","骨骼肌收缩前负荷越大，其可能的结果有",[["A","主动张力越大"],["B","被动张力越大"],["C","总张力越大"],["D","初长度越大"]],"BD","前负荷指肌肉在收缩前所承受的负荷，前负荷是牵拉肌肉的力量，决定肌肉在收缩前的长度，即初长度，所以前负荷增加时，初长度增加（D对），此时因肌肉受到牵拉而弹性回位的张力属于被动张力，所以被动张力增加（B对）。肌肉主动收缩产生的张力，即主动张力，根据肌肉的长度-张力关系曲线可以看出，肌肉收缩存在一个最适初长度，当超过最适初长度时，主动张力（A错）和总张力反而降低（C错），所以前负荷需要在一定范围内增加，主动张力和总张力才会相应增加。","","N"],["2025-N137",3,"第2节 心脏的电生理学及生理特性","影响心肌收缩的因素",2025,137,"X","","可影响心肌收缩力的因素有",[["A","前负荷"],["B","后负荷"],["C","胞外Ca²⁺浓度"],["D","自主神经活动"]],"ABCD","前负荷（A对）指心肌收缩之前遇到的阻力或负荷，相当于心室舒张末期充盈的血液量，在一定范围内增加前负荷，心肌收缩力加强，也称为心肌异长自身调节。后负荷（B对）指心肌收缩之后所遇到的阻力或负荷，大动脉血压是心室收缩时所遇到的后负荷，当大动脉压突然升高而使搏出量暂时减少时，心室收缩期末容积增大，通过异长自身调节加强心肌的收缩力量。胞外Ca²⁺浓度（C对）可影响活化的横桥在全部横桥中所占的比例，影响心肌细胞兴奋-收缩耦联，Ca²⁺浓度升高可以增强心肌收缩力。自主神经活动（D对）通过释放神经递质来调节心肌收缩力，当心交感神经兴奋时，释放的儿茶酚胺激动心肌细胞的β肾上腺素受体，使心肌收缩能力增强。","","N"],["2025-N138",5,"第4节 小肠内消化","缩胆囊素",2025,138,"X","","缩胆囊素的生理功能有",[["A","促进胰液中各种酶的分泌"],["B","促进胆管上皮分泌大量的水和HCO₃⁻"],["C","引起胆囊收缩，促使胆汁排出"],["D","对胰腺组织具有营养作用"]],"ACD","缩胆囊素由小肠上部的I细胞分泌，其生理功能包括：促进胰液中各种酶的分泌（A对），如胰蛋白酶、胰脂肪酶、胰淀粉酶等，从而增强胰液的消化功能；促进胆囊收缩，促使胆汁排出（C对），进入胆总管，最终参与食物的消化过程；对胰腺组织具有营养作用（D对），可促进胰组织蛋白质和核糖核酸的合成。促进胆管上皮分泌大量的水和HCO₃⁻（B错）是促胰液素的生理功能。","","N"],["2025-N139",7,"第2节 肾小球的滤过功能","影响肾小球滤过的因素",2025,139,"X","","可以减少肾小球滤过率的疾病有",[["A","肾盂积水"],["B","高血压肾小动脉硬化"],["C","早期糖尿病"],["D","尿崩症"]],"AB","肾小球滤过率指单位时间内（每分钟）两肾生成的超滤液量。肾盂积水（A对）是由于尿液在肾盂内积聚导致肾盂内压力增高，进而压迫肾小球，使得肾小球的有效滤过面积减少，从而肾小球滤过率降低。高血压肾小动脉硬化（B对）会引起肾小球毛细血管管腔狭窄，阻力增加，使得肾小球内的有效滤过压下降，导致肾小球滤过率降低。早期糖尿病（C错）时，近端小管中钠、葡萄糖协同转运过强，钠盐过度重吸收，肾小囊压力降低，肾小球滤过被迫增多，高滤过导致肾小球高灌注、高跨膜压和蛋白尿生成，而晚期糖尿病时，由于大量肾小球硬化，滤过功能逐渐下降。尿崩症（D错）是抗利尿激素完全/部分缺乏或肾脏对其不敏感，致肾远曲小管、集合管对水重吸收功能障碍，不会直接导致肾小球滤过率减少。","","N"],["2025-N140",10,"第2节 下丘脑-垂体及松果体内分泌","腺垂体激素的概述",2025,140,"X","","腺垂体分泌的激素有",[["A","催乳素"],["B","缩宫素"],["C","促甲状腺激素"],["D","促肾上腺皮质激素"]],"ACD","腺垂体又称为垂体前叶，其分泌的激素包括促甲状腺激素（C对）、卵泡刺激素、黄体生成素/间质细胞刺激素、促肾上腺皮质激素（D对）、生长激素、催乳素（A对）。而缩宫素（B错）是由下丘脑的视上核和室旁核合成并储存于神经垂体，在需要时释放入血。","","N"],["2025-N141",11,"第1节 男性生殖功能及其调节","睾酮的生理作用",2025,141,"X","","睾酮的生理功能有",[["A","可促进血低密度脂蛋白增加"],["B","刺激骨骺闭合"],["C","引起负氮平衡"],["D","参与机体的水和电解质平衡"]],"ABD","睾酮由睾丸间质细胞分泌，睾酮的生理作用包括：促使胚胎男性第一性征形成；促进血中低密度脂蛋白合成（A对），并降低高密度脂蛋白含量；刺激骨生长和骨骺的闭合（B对）；促进蛋白质合成并抑制其分解，引起正氮平衡（C错）；参与调节人体水和电解质的平衡（D对），有类似于肾上腺皮质激素的作用，导致体内钠、水潴留；促进肾脏合成促红细胞生成素，刺激红细胞生成等。","","N"],["2026-N1",0,"第5节 机体生理功能的调节","体液调节",2026,1,"A","","下列属于神经-体液调节的是",[["A","血糖升高引起胰岛素的分泌"],["B","血压升高导致副交感神经兴奋"],["C","肾血流量升高导致肾毛细血管平滑肌收缩"],["D","婴儿吮吸乳头导致的乳汁分泌"]],"D","人体内有很多内分泌腺的活动接受神经的调节，如婴儿吮吸乳头所引起的射乳反射（D对），婴儿通过吮吸乳头反射性地引起神经垂体分泌缩宫素，进而导致乳腺腺泡周围的肌上皮细胞收缩，乳汁从乳头射出，此时缩宫素的分泌和产生的效应就相当于神经调节反射弧的传出部分，这种调节称为神经-体液调节。血糖升高引起胰岛素的分泌（A错）属于体液调节，因血糖水平可直接作用于胰岛β细胞促进胰岛素释放，无需神经系统参与。血压升高引起副交感神经兴奋（B错）属于神经调节，血压升高刺激颈动脉窦、主动脉弓压力感受器，经传入神经激活延髓心血管中枢，进而兴奋副交感神经。肾血流量升高导致肾毛细血管平滑肌收缩（C错）属于自身调节，在一定范围内（70～180mmHg），当肾灌注压升高时，入球小动脉血管平滑肌受到牵张，紧张性升高，更多的Ca²⁺从胞外进入胞内，使平滑肌收缩，血管口径相应地缩小，血流阻力增大。","","N"],["2026-N2",1,"第1节 细胞膜的物质转运功能","继发性主动转运",2026,2,"A","","细胞内外Na⁺、Ca²⁺通过细胞膜上的Na⁺-Ca²⁺交换体进行的跨膜运输是",[["A","原发性主动转运"],["B","继发性主动转运"],["C","经载体的易化扩散"],["D","经通道的易化扩散"]],"B","Na⁺-Ca²⁺交换体是一种反向转运蛋白，细胞膜上的Na⁺-Ca²⁺交换体通常是在Na⁺顺电化学梯度进入细胞内的同时，将细胞内的Ca²⁺逆浓度梯度转运到细胞外，实现Ca²⁺逆浓度梯度的转运，属于继发性主动转运（B对）。原发性主动转运（A错）主要是细胞直接利用代谢产生的能量将物质逆浓度梯度和/或电位梯度转运的过程，其底物通常为带电离子，如同时转运Na⁺和K⁺的钠-钾泵、转运Ca²⁺的钙泵、转运H⁺的质子泵等。经载体的易化扩散（C错）是指水溶性小分子物质在载体蛋白介导下顺浓度梯度进行的跨膜转运，属于载体介导的被动转运，如葡萄糖转运体可将胞外的葡萄糖顺浓度梯度转运到细胞内。经通道的易化扩散（D错）是各种带电离子在通道蛋白的介导下，顺浓度梯度和/或电位梯度的跨膜转运，如电压门控钠通道、钾通道等。","","N"],["2026-N3",1,"第3节 细胞的电活动","静息时细胞膜对离子的相对通透性",2026,3,"A","","在静息电位状态下，神经细胞膜内的k⁺外流所依赖的通道是",[["A","钠-钾泵"],["B","非门控钾通道"],["C","电压门控钾通道"],["D","化学门控通道"]],"B","在静息电位状态下，神经细胞膜对K⁺的通透性最高，K⁺通过神经细胞膜中的钾通道外流，属于非门控钾通道（B对），其特点为持续开放，不受电压、化学信号等调控。钠-钾泵（A错）是哺乳动物细胞膜中普遍存在的离子泵，其主要作用是维持细胞内外钠钾离子浓度梯度，不直接介导静息状态的离子流动。电压门控钾通道（C错）参与动作电位的形成，通道开放引起K⁺外流和复极化发生。化学门控通道（D错）是一类兼有通道和受体功能的蛋白分子，如骨骼肌终板膜上的N₂型乙酰胆碱能受体，化学门控通道不参与神经细胞膜静息电位状态下的K⁺外流。","","N"],["2026-N4",1,"第4节 肌细胞的收缩","肌丝的分子结构",2026,4,"A","","组成骨骼肌粗肌丝的蛋白是",[["A","肌动蛋白"],["B","肌钙蛋白"],["C","肌球蛋白"],["D","原肌球蛋白"]],"C","横纹肌的肌原纤维由粗肌丝和细肌丝构成。粗肌丝长约1.6μm，主要由数百个肌球蛋白（C对）分子聚合而成，单个肌球蛋白分子呈豆芽状，有一个杆部和两个球形的头部，由6条肽链构成。肌动蛋白（A错）、肌钙蛋白（B错）和原肌球蛋白（D错）则是细肌丝的组成部分。","","N"],["2026-N5",2,"第2节 血细胞生理","红细胞生成的调节",2026,5,"A","","促红细胞生成素的功能是",[["A","促进晚期红细胞凋亡"],["B","促进晚期红系祖细胞增殖"],["C","促进网织红细胞增殖"],["D","促进肺循环红细胞进入体循环"]],"B","红系造血祖细胞向红系前体细胞的增殖分化是红细胞生成的关键环节，晚期红系造血祖细胞因存在较密集的促红细胞生成素受体，所以主要接受促红细胞生成素的调节，因此促红细胞生成素的功能主要是促进晚期红系祖细胞增殖（B对）。促红细胞生成素作为存活因子可以抑制晚期红细胞的凋亡（A错），激活血红蛋白等红系特异基因的表达，促进红系造血祖细胞向原红细胞分化及幼红细胞血红蛋白的合成以及促进网织红细胞的成熟与释放（C错）。红细胞在肺循环与体循环的转运（D错）主要依赖血流动力学调控，与促红细胞生成素无关。","","N"],["2026-N6",3,"第2节 心脏的电生理学及生理特性","兴奋在心脏内的传导",2026,6,"A","","兴奋在心脏传导速度最快的部位是",[["A","心房优势传导通路"],["B","房室交界区"],["C","心室肌"],["D","浦肯野纤维"]],"D","兴奋在心内的传播是通过特殊传导系统有序进行的，传导速度受心肌细胞电生理特性、细胞间缝隙连接的分布密度和类型的影响。由于浦肯野纤维（D对）十分粗大，细胞间缝隙连接数量很多，因此是兴奋在心脏传导速度最快的部位，可达4m/s左右。心房优势传导通路（A错）纤维较粗，方向较直，其传导速度较快，约为1.0～1.2m/s，可将兴奋直接传到房室结。房室交界区（B错）的传导非常缓慢，传导速度仅0.02m/s。兴奋在心室肌（C错）的传导速度约为1m/s，由于心室肌纤维呈双螺旋状环绕心室腔排列，故兴奋呈一定角度沿螺旋方向传导。","","N"],["2026-N7",3,"第2节 心脏的电生理学及生理特性","心房肌细胞动作电位",2026,7,"A","","乙酰胆碱可以激活心房肌细胞上的离子通道是",[["A","钾通道"],["B","钠通道"],["C","钙通道"],["D","氯通道"]],"A","心脏迷走神经节后纤维释放乙酰胆碱（ACh），它作用于心房肌细胞膜上的M型胆碱能受体，通过G蛋白偶联信号通路，最终激活心肌细胞的乙酰胆碱敏感性钾通道（A对）。心肌细胞的钠通道（B错）主要被去极化刺激激活，参与动作电位0期去极化，乙酰胆碱不直接激活该通道。乙酰胆碱会抑制心肌细胞的L型钙通道（C错），减少钙内流，减弱心肌收缩力，而非激活。乙酰胆碱对心肌细胞的氯通道无直接激活作用（D错）。","","N"],["2026-N8",3,"第3节 血管生理","影响组织液生成的因素",2026,8,"A","","丝虫病患者出现组织水肿的原因是",[["A","血浆胶体渗透压降低"],["B","毛细血管通透性增加"],["C","毛细血管血压升高"],["D","淋巴管阻塞"]],"D","丝虫的成虫主要寄生在人体的淋巴管内，其代谢产物、死亡虫体等会刺激淋巴管内皮细胞，引发淋巴管的慢性炎症、增生和纤维化，最终导致淋巴管管腔狭窄或完全阻塞，当淋巴管阻塞时，淋巴液回流受阻，组织液无法正常经淋巴管返回血液循环，大量液体积聚在组织间隙中，就会形成水肿（D对）。血浆胶体渗透压降低（A错）见于营养不良或某些肝肾疾病，因血浆胶体渗透压降低，导致有效胶体渗透压下降，有效滤过压增大而发生水肿。毛细血管通透性增加（B错）常见于感染、烧伤、过敏反应，会导致血浆蛋白渗出到组织间隙而出现水肿。毛细血管血压升高（C错）多见于右心衰竭等循环淤血状态，丝虫病不会直接引起毛细血管血压升高。","","N"],["2026-N9",4,"第1节 肺通气","弹性阻力和顺应性",2026,9,"A","","可导致肺顺应性增大的疾病是",[["A","肺气肿"],["B","肺纤维化"],["C","新生儿呼吸窘迫综合征"],["D","肺水肿"]],"A","肺顺应性反映的是肺组织在外力作用下的可扩张程度，顺应性增大意味着肺组织弹性减退、容易被扩张。肺气肿（A对）时，肺泡壁破坏、肺泡融合成大疱，肺的弹性纤维大量降解，导致肺的弹性回缩力显著下降，故肺顺应性增大。肺纤维化（B错）时，肺质地变硬，弹性阻力增加，肺顺应性降低。新生儿呼吸窘迫综合征（C错）因缺乏肺表面活性物质，肺泡表面张力显著增高，肺泡不易扩张，肺扩张阻力增加，肺顺应性降低。肺水肿（D错）时肺泡和肺间质内液体积聚，使肺组织质地变实，肺扩张的阻力增大，同时会影响肺表面活性物质的功能，最终导致肺顺应性降低。","","N"],["2026-N10",5,"第4节 小肠内消化","胰液的性质、成分和作用",2026,10,"A","","可以保证胰脂肪酶发挥作用的是",[["A","磷脂酶A₂"],["B","辅脂酶"],["C","胆固醇酯酶"],["D","肠激酶"]],"B","辅脂酶（B对）由胰腺分泌，其锚定在脂肪滴的油-水界面上，对胆盐微胶粒有较高的亲和力，与胰脂肪酶和胆盐形成三元络合物，以防止胆盐将胰脂肪酶从脂滴表面清除。磷脂酶A₂（A错）作用底物是卵磷脂，可将其水解为溶血磷脂和脂肪酸。胆固醇酯酶（C错）主要负责分解胆固醇酯，生成游离胆固醇和脂肪酸。肠激酶（D错）是激活胰蛋白酶原的特异性酶，可使胰蛋白酶原变为有活性的胰蛋白酶。","","N"],["2026-N11",7,"第3节 肾小管和集合管的物质转运功能","髓袢",2026,11,"A","","肾小管髓袢升支细段通透性较高的物质是",[["A","水"],["B","尿素"],["C","Na⁺"],["D","菊粉"]],"C","肾小管髓袢升支细段对Na⁺（C对）的通透性较高，NaCl不断通过被动的易化扩散进入组织间液，小管液渗透浓度逐渐降低。髓袢升支细段对水（A错）不通透，因为此段没有水通道蛋白表达。尿素（B错）主要在髓袢降支细段和集合管内髓部被重吸收，髓袢升支细段对尿素的通透性较低。菊粉（D错）作为滤过标志物不被肾小管重吸收或分泌。","","N"],["2026-N12",7,"第5节 尿生成的调节","血浆晶体渗透压",2026,12,"A","","可使抗利尿激素分泌减少的因素是",[["A","静脉滴注甘露醇"],["B","静脉滴注生理盐水"],["C","动脉血压较正常水平低"],["D","饮用大量清水"]],"D","饮用大量清水（D对）可稀释血液，降低血浆晶体渗透压，直接引起抗利尿激素分泌减少，进而集合管对水的重吸收减少，尿液稀释，尿量增加。静脉滴注甘露醇（A错）时，因为渗透性利尿会增加血浆渗透压，从而促进抗利尿激素分泌。静脉滴注生理盐水（B错）虽然可以使循环血量增多，静脉回心血量增加，进而刺激心肺感受器，抑制抗利尿激素释放，但是生理盐水是等渗溶液，静脉注射生理盐水不会直接改变血浆晶体渗透压，其不直接影响抗利尿激素。动脉血压降低会激活压力感受器，反射性增加抗利尿激素分泌以维持血压（C错）。","","N"],["2026-N13",8,"第3节 视觉","视紫红质的光化学反应",2026,13,"A","","人在暗处视物时，视网膜含量较多的物质是",[["A","视紫红质"],["B","全反型视黄醛"],["C","11-顺视黄醛"],["D","全反型视黄醇"]],"A","在暗处时，人眼适应暗视觉，视紫红质既分解又合成，但合成大于分解，因此视网膜中视紫红质（A对）数量较多，使视网膜对弱光较敏感。视紫红质是视杆细胞中的光敏感色素，视紫红质是一种蛋白质，由1分子视蛋白和1分子视黄醛的生色基团组成，在暗处为11-顺视黄醛（C错）。全反型视黄醛（B错）是视紫红质在光照下分解的产物，暗处时浓度较低。全反型视黄醇（D错）是维生素A的代谢形式，参与视黄醛再生，在暗处时不占主导。","","N"],["2026-N14",9,"第5节 脑电活动及睡眠与觉醒","脑电图的波形",2026,14,"A","","成人大脑皮层处于紧张活动时，脑电波常见的波形是",[["A","α"],["B","β"],["C","θ"],["D","δ"]],"B","脑电波主要有α、β、θ和δ波四种基本波形。α波（A错）的频率为8～13Hz，幅度为20～100μV，在成年人清醒、安静并闭眼时出现，睁眼或接受其他刺激时立即消失。β波（B对）频率为14～30Hz，幅度为5～20μV，是新皮层处于紧张活动状态的标志。θ波（C错）的频率为4～7Hz，幅度为100～150μV，常见于儿童或成年人困倦时。δ波（D错）的频率为0.5～3Hz，幅度为20～200μV，常见于婴儿时期，以及成人深度睡眠、极度疲劳或麻醉时。","","N"],["2026-N15",10,"第6节 胰岛内分泌","激素的调节作用",2026,15,"A","","不通过升高血糖直接导致胰岛素分泌增加的激素是",[["A","促胃液素"],["B","促胰液素"],["C","缩胆囊素"],["D","抑胃肽"]],"D","抑胃肽（GIP）（D对）是一种肠促胰岛素激素，能直接作用于胰腺β细胞上的受体，刺激胰岛素分泌增加，而不依赖血糖升高的机制。相反，促胃液素（A错）、促胰液素（B错）和缩胆囊素（C错）是通过刺激消化液分泌或营养吸收，间接导致血糖升高，从而影响胰岛素释放。","","N"],["2026-N16",11,"第2节 女性生殖功能及其调节","雌激素、孕激素的作用",2026,16,"A","","卵巢排卵前分泌最多的激素是",[["A","雌酮"],["B","雌二醇"],["C","雌三醇"],["D","孕激素"]],"B","在卵巢排卵前，卵巢处于卵泡期，卵泡分泌雌激素为主，其中雌二醇（B对）是雌激素的主要活性形式，分泌量最高。雌酮（A错）是雌激素的另一种形式，但分泌量较少，活性较低。雌三醇（C错）通常在妊娠期显著增加，排卵前分泌极少。孕激素（D错）主要由黄体分泌，在排卵后黄体形成时才大量产生。","","N"],["2026-N116",1,"第2节 细胞的信号转导","核受体介导的信号转导",2026,116,"B","","与核受体结合发挥生理作用的激素是",[["A","甲状腺激素"],["B","生长激素"],["C","甲状旁腺激素"],["D","肾上腺素"]],"A","甲状腺激素（A对）通过与细胞内核受体结合，直接调控基因转录而发挥其调节代谢、发育等生理作用。生长激素（B错）作用于细胞膜上的酪氨酸激酶相关受体，不进入核内，不与核受体结合。甲状旁腺激素（C错）和肾上腺素（D错）作用于细胞膜G蛋白偶联受体，通过cAMP-PKA等途径产生效应，不通过核受体。","","N"],["2026-N117",10,"第2节 下丘脑-垂体及松果体内分泌","生长激素",2026,117,"B","","和催乳素有一定交叉重叠作用的激素是",[["A","甲状腺激素"],["B","生长激素"],["C","甲状旁腺激素"],["D","肾上腺素"]],"B","生长激素（B对）与催乳素均为腺垂体分泌的肽类激素，分子结构相似，且存在部分共同的受体结合位点，两者作用有一定的交叉重叠。甲状腺激素（A错）主要调节新陈代谢和生长发育，与催乳素的乳腺泌乳、生殖调控功能无交叉重叠。甲状旁腺激素（C错）主要负责钙磷代谢调节，与催乳素的生理作用无关。肾上腺素（D错）主要作用于心血管和代谢系统，与催乳素无交叉重叠。","","N"],["2026-N118",9,"第1节 神经系统功能活动的基本原理","乙酰胆碱及其受体",2026,118,"B","","兴奋可引起骨骼肌收缩的受体是",[["A","M型受体"],["B","N型受体"],["C","α受体"],["D","β受体"]],"B","兴奋可引起骨骼肌收缩的受体主要是神经肌肉接头处的烟碱受体（N型受体），乙酰胆碱激活骨骼肌的N₂型受体（B对）时，激活离子通道，导致钠离子内流和肌肉动作电位，最终引起骨骼肌收缩。M型受体（A错）分布于大多数副交感节后纤维支配的效应细胞、汗腺细胞和骨骼肌内的血管平滑肌细胞，兴奋时可导致心脏活动抑制、平滑肌收缩等。α受体（C错）主要分布于血管平滑肌，兴奋时引起血管收缩，不参与骨骼肌收缩。β受体（D错）中的β₂受体可引起骨骼肌血管舒张，但不直接导致骨骼肌收缩。","","N"],["2026-N119",9,"第1节 神经系统功能活动的基本原理","NE和肾上腺素及其受体",2026,119,"B","","兴奋可引起有孕子宫平滑肌收缩的受体是",[["A","M型受体"],["B","N型受体"],["C","α受体"],["D","β受体"]],"C","子宫平滑肌上存在α₁受体，当α₁受体（C对）与NE和肾上腺素结合后产生平滑肌兴奋效应，可直接引起子宫平滑肌收缩，尤其在妊娠状态下，子宫对α₁受体激动剂的敏感性显著提高，收缩效应更强。M受体（A错）兴奋主要引起胃肠道、支气管平滑肌收缩，虽然子宫平滑肌上有M₃受体分布，但对子宫平滑肌作用较弱且非妊娠特异性。N型受体（B错）的N₂受体仅分布于骨骼肌，与子宫平滑肌收缩无关。β受体（D错）中的β₂受体激动时，可松弛子宫平滑肌，可以用于抑制早产，与收缩作用相反。","","N"],["2026-N136",3,"第1节 心脏的泵血功能","心肌收缩能力",2026,136,"X","","可导致心肌收缩能力增强的增强的因素有",[["A","前负荷增加"],["B","甲状腺激素分泌增加"],["C","儿茶酚胺分泌增加"],["D","血钙浓度降低"]],"BC","可影响心肌收缩能力的因素有：①在同一初长度下，活化的横桥数目和肌球蛋白头部ATP酶的活性是影响心肌收缩能力的主要环节，血钙浓度降低（D错）会使活化的横桥数目减少，心肌收缩能力减弱。②儿茶酚胺分泌增加（C对），可激动心肌细胞的β肾上腺素受体，促进胞质内Ca²⁺浓度升高，从而使心肌收缩能力增强。③钙增敏剂（如茶碱）可增加肌钙蛋白对Ca²⁺的亲和力，使心肌收缩能力增强。④当心肌受到牵张时，血管紧张素Ⅱ增多，可使胞内Ca²⁺增多，引起心肌收缩力增强。⑤甲状腺激素（B对）可上调心肌细胞Na⁺-K⁺-ATP酶、α-肌球蛋白重链，以及β₁-肾上腺素受体的表达，增强心肌收缩能力。心肌收缩能力是不依赖于前负荷（A错）和后负荷而改变心肌的收缩速度和强度。","","N"],["2026-N137",4,"第3节 气体在血液中的运输","影响氧解离曲线的因素",2026,137,"X","","导致血红蛋白氧饱和度降低的因素有",[["A","人处于高海拔地区"],["B","动脉血PCO₂升高"],["C","缺铁性贫血"],["D","动脉血pH升高"]],"ABC","血红蛋白氧饱和度可受多种因素影响，如pH、PCO₂、温度、2，3-DPG、CO、Hb的自身性质和含量等。血液pH和PCO₂对Hb与O₂亲和力的影响称为波尔效应，当动脉血pH降低（D错）或动脉血PCO₂升高（B对）时，Hb对O₂的亲和力降低，P₅₀增大，曲线右移，导致血红蛋白氧饱和度降低。人处于高海拔地区（A对）、慢性缺氧、缺铁性贫血（C对）时，糖酵解加强，红细胞内2，3-DPG增加，氧解离曲线右移，促进O₂的释放，导致血红蛋白氧饱和度降低。","","N"],["2026-N138",5,"第4节 小肠内消化","胰液分泌的调节",2026,138,"X","","促进胰液分泌的因素有",[["A","迷走神经兴奋"],["B","缩胆囊素分泌增加"],["C","促胃液素分泌增加"],["D","小肠内盐酸浓度增加"]],"ABCD","迷走神经兴奋（A对）通过反射途径促进胰液分泌，可通过其末梢释放ACh直接作用于胰腺，也可通过引起促胃液素的释放，间接引起胰腺分泌。缩胆囊素是一种由肠道细胞合成并释放的胃肠激素，其作用于受体后可引起胆囊收缩和促进胰液、小肠液分泌，所以缩胆囊素分泌增加（B对）会促进胰液分泌。促胃液素（又称胃泌素）由胃肠黏膜细胞分泌，促胃液素分泌增加（C对）可直接与胰腺细胞表面的受体结合，激活细胞内的信号通路，促进胰液中消化酶的合成与分泌，此外食物刺激胃肠道黏膜时，会引起迷走神经兴奋，进而促进促胃液素的大量分泌，刺激胰腺分泌胰液。小肠内盐酸浓度增加（D对）时，会刺激促胰液素和缩胆囊素的分泌，两者都有促进胰液分泌的作用。","","N"],["2026-N139",8,"第5节 平衡感觉","前庭器官的感受装置和适宜刺激",2026,139,"X","","与人内耳平衡感觉相关的生理现象有",[["A","毛细胞电位"],["B","前庭姿势反射"],["C","半规管内淋巴流动"],["D","耳蜗微音器点位"]],"ABC","人内耳的前庭器官由半规管、椭圆囊和球囊组成，其主要功能是感受机体的平衡感觉。毛细胞是前庭器官的感受细胞，当机体的运动状态和头部在空间的位置发生改变时，毛细胞的电位（A对）会发生改变，不同毛细胞综合活动的结果使机体在各种姿势和运动情况下保持身体平衡。前庭器官的传入冲动可引起各种姿势调节反射，姿势反射（B对）都与引起反射的刺激相对抗，其意义在于使机体尽可能保持在原有空间位置上，以维持一定的姿势和身体平衡。半规管感受头部旋转变速运动，人体三对半规管所在的平面互相垂直，能感受空间任何方向的角加速度运动。内淋巴因惯性流动（C对），刺激壶腹嵴毛细胞，是平衡信号产生的起始环节。耳蜗微音器电位（D错）是多个毛细胞在接受声音刺激时所产生的感受器电位的复合表现，属于听觉系统的生理现象，由耳蜗毛细胞受声波刺激产生，与平衡感觉无关。","","N"],["2026-N140",7,"第4节 尿液的浓缩和稀释","影响尿液浓缩和稀释的因素",2026,140,"X","","可导致尿量增多的因素",[["A","剧烈疼痛"],["B","肾髓质渗透压下降"],["C","激活RAAS系统"],["D","抗利尿激素分泌减少"]],"BD","肾髓质高渗环境是肾小管重吸收水的动力，若肾髓质渗透压下降（B对），如髓袢功能障碍导致NaCl重吸收减少，水的重吸收驱动力减弱，终尿量增加。抗利尿激素（ADH）通过提高肾小管对水的通透性促进重吸收，当ADH分泌减少时（D对），集合管对水的重吸收显著降低，原尿中水分大量排出，尿量增多。剧烈疼痛（A错）时，机体应激反应激活交感神经系统和抗利尿激素分泌，反而促进水重吸收，导致尿量减少。激活RAAS系统（肾素-血管紧张素-醛固酮系统）（C错）增加醛固酮分泌，促进肾小管钠和水重吸收，从而减少尿量。","","N"],["2026-N141",10,"第5节 肾上腺内分泌","对组织器官活动的影响",2026,141,"X","","糖皮质激素对血细胞的影响是",[["A","红细胞数量增多"],["B","血小板数量增多"],["C","嗜酸性粒细胞数量增多"],["D","淋巴细胞数量增多"]],"AB","糖皮质激素能增强骨髓造血功能，促进红细胞和血小板的生成，所以糖皮质激素对血细胞的影响是使红细胞数量增多（A对）、血小板数量增多（B对）。糖皮质激素能抑制淋巴细胞的有丝分裂，促进淋巴细胞凋亡，增加淋巴细胞与嗜酸性粒细胞在脾和肺的破坏，使淋巴细胞（D错）和嗜酸性粒细胞（C错）数量减少。","","N"]];
